COLLDATA("sh132971","ar",[[9752,"المدنى. روى عن أبيه (١). روى عنه غسان بن عبد الحميد (٢)."],[9753,"١٣٧٧ - أبو بكر النصرى. عن أبى قرة (٣). روى عنه غسان بن عبد الحميد."],[9754,"١٣٧٨ - أبو بكر بن القاسم الكليبى. روى عنه عبد الواحد بن واصل (٤)."],[9755,"١٣٧٩ - أبو بكر بن الضحاك (٥) الزبيدى كوفى روى عن عاصم بن بهدله (٦). روى عنه الثورى."],[9756,"١٣٨٠ - أبو بكر بن القاسم. عن عبيد اللَّه بن العيزار. روى عنه النضر بن شميل."],[9757,"١٣٨١ - أبو بكر القتبى عن أبى الزناد. روى عنه معاوية بن يحيى (٧). هو رجل مجهول لا يدرى من هو."],[9758,"(١) عثمان بن عبد الرحمن بن سعيد بن يربوع القرشى، المخزومى، ترجمته في الجرح (٣/ ١/ ١٥٧)."],[9759,"(٢) قال ابن حجر: مجهول. انظر اللسان (٤/ ٤١٨)."],[9760,"١٣٧٧ - كنى الحاكم (١/ ٣٦/ أ)."],[9761,"(٣) ستأتى ترجمته في (٢٣١٧) وفيها هناك أنه روى عنه \"أبو بكر النصرى\"."],[9762,"١٣٧٨ - كنى الحاكم (١/ ٣٦/ أ). كنى ابن منده (٤٥/ أ)."],[9763,"(٤) عبد الواحد بن واصل السدوسى، أبو عبيدة الحداد، البصرى نزيل بغداد، ثقة، تكلم فيه الازدى بغير حجة، من التاسعة. التقريب (١/ ٥٢٦)."],[9764,"١٣٧٩ - كنى البخارى (ص ١٣). الجرح (٤/ ٢/ ٣٤٢). كنى الحاكم (١/ ٣٦/ أ) كنى ابن منده (٤٥/ أ)."],[9765,"(٥) في الجرح \"رجاء\" بدل \"الضحاك\"."],[9766,"(٦) في كنى الحاكم والجرح \"عاصم بن شريب\" فاللَّه أعلم."],[9767,"١٣٨٠ - كنى ابن منده (٤٦/ ب). كنى الحاكم (١/ ٣٦/ أ)."],[9768,"١٣٨١ - كنى الحاكم (١/ ٣٦/ أ) وقال: رجل مجهول، لا يدرى من هو؟"],[9769,"(٧) معاوية بن يحيى. هناك اثنان يسمى كل منهما معاوية بن يحيى وكلاهما من الطبقة السابعة أما أحدهما فهو الصدفى، أبو روح الدمشقى سكن الرى. ="],[9770,"١٣٨٢ - أبو بكر بن إسماعيل. روى عن محمد بن سعد بن أبى وقاص (١) روى عنه محمد بن عمر الواقدى."],[9771,"١٣٨٣ - أبو بكر بن عبد الرحمن بن أبى سفيان بن حويطب قاضى المدينة. قيل اسمه كنيته. وقيل: اسمه رباح وقد ذكرناه فيمن غلبت كنيته على اسمه."],[9772,"١٣٨٤ - أبو بكر بن أبى النضر البغدادى. واسم أبى النضر الهاشم بن القاسم. وأما ابنه أبو بكر فاسمه كنيته. ويلقب قيصر سمع أباه وأبا نوح قراد والاسود بن عامر، وخلف بن تميم (٢) روى عنه أبو قدامه عبيد اللَّه بن سعيد ومسلم بن الحجاج وأبو حاتم الرازى. هو صدوق عندهم."],[9773,"١٣٨٥ - أبو بكر بن أبى بشر واسم أبى بشر بكر بن خلف (٣). سمع أباه"],[9774,"= وأما الآخر فهو الطرابلسى، أبو مطيع أصله دمشق أو حمص، صدوق له أوهام. وقال ابن حجر: غلط من خلطهما ببعض. انظر التقريب (٢/ ٢٦١). تهذيب الكمال (٣/ ١٣٤٨) ولم يتبين لى أيهما الراوى عن أبى بكر صاحب هذه الترجمة."],[9775,"١٣٨٢ - كنى ابن منده (٤٥/ أ)."],[9776,"(١) محمد بن سعد بن أبى وقاص، مدنى، نزل الكوفة، كان يلقب ظل الشيطان لقصره، ثقة، من الثالثة، قتله الحجاج بعد الثمانين. التقريب (٢/ ١٦٤)."],[9777,"١٣٨٣ - تقدم في الكتاب الثانى انظر الترجمة (٤٣٨)."],[9778,"١٣٨٤ - الجرح (٤/ ٢/ ٣٤٥) وقال: سألت أبى عنه فقال: صدوق، تاريخ بغداد (١٤/ ٣٨٦). التهذيب (١٢/ ٤٢). التقريب (٢/ ٤٠٠) وقال: أبو بكر بن النضر بن أبى النضر البغدادى وقد ينسب لجده، اسمه كنيته واحد وقيل: اسمه محمد. وقيل: أحمد. ثقة، من الحادية عشرة (ت: ٢٤٥)./ م. د. ت. س."],[9779,"(٢) خلف بن تميم. كوفى نزل المصيصة، صدوق عابد، من التاسعة. التقريب (١/ ٢٢٥)."],[9780,"١٣٨٥ - المقتنى في سرد الكنى (٢٣/ ب)."],[9781,"(٣) بكر بن خلف أبو بشر، صدوق، من العاشرة. التقريب (١/ ١٠٥)."],[9782,"وخاله (١). روى عنه عبد اللَّه بن محمد بن مسلم (٢)."],[9783,"١٣٨٦ - أبو بكر بن مروان بن الحكم بن يزيد الاسيدى. روى عن عبد الوارث كتب عنه أبو حاتم الرازى وقال: ليس به بأس."],[9784,"١٣٨٧ - أبو بكر الكليبى وليس بعباد بن صهيب (٣). روى عن شيخ (٤) (حدثه) (٥) عن أبى سعيد الخدرى، روى عنه أبو داود الطيالسى، وحجاج بن منهال، قال أبو حاتم: هو شيخ ليس بالمعروف."],[9785,"١٣٨٨ - أبو بكر بن أبى قيس، روى عن أبيه عن عثمان بن عفان. روى عنه أبو هانئ حميد بن هانئ. لا يعرف اسمه ولا اسم أبيه."],[9786,"(١) لم أقف على من سماه."],[9787,"(٢) عبد اللَّه بن محمد بن مسلم. ويقال: عبد اللَّه بن مسلم، مقبول، من السادسة. التقريب (١/ ٤٥٠)."],[9788,"١٣٨٦ - الجرح (٤/ ٢/ ٣٤٥) وقال: سألت أبى عنه فقال: كتبت عنه وليس به بأس."],[9789,"١٣٨٧ - الجرح (٤/ ٢/ ٣٤٥) وذكره كما هنا وقال: سألت أبى عنه فقال: شيخ ليس بمعروف."],[9790,"(٣) له ترجمة مطولة في اللسان (٣/ ٢٣٠)."],[9791,"(٤) لم أقف على اسمه."],[9792,"(٥) هكذا في الأصل \"حدثه\" والذى في الجرح \"يرجف\"."],[9793,"١٣٨٨ - الجرح (٤/ ٢/ ٣٤٦) وقال: سئل أبو زرعة عنه فقال: لا أعرف اسم أبى بكر ولا اسم أبيه. كنى ابن منده (٤٣/ ب) وقال: عداده في أهل مصر، ثم ساق اسناد حديثه وفيه \"عن أبى بكر بن أبى قيس الحسلى\"."],[9794,"باب أبى بشر"],[9795,"١٣٨٩ - أبو بشر مولى بنى غلاب. روى عن ابن عمر وابن عباس وابن الزبير انه سألهم \"هل ينفع عمل مع الشرك؟ \" الحديث. روى عنه عوف بن أبى جميلة الاعرابى."],[9796,"١٣٩٠ - أبو بشر. روى عن أبى هريرة. روى عنه راشد بن سعد، يعد في الشاميين."],[9797,"١٣٩١ - أبو بشر مؤذن مسجد دمشق عن عامر بن لُدَين (١) روى عنه معاوية بن صالح، حديثه في أهل الشام. وقيل: انه الذى روى عنه راشد بن سعد. وقيل: انه الذى روى عن مكحول وعمر بن عبد العزيز. وانه من أهل قنَّسْرين (٢)."],[9798,"١٣٨٩ - الجرح (٤/ ٢/ ٣٤٧) وذكره كما هنا تماما وقال: سئل أبو زرعة عنه فقال: لا يسمى."],[9799,"١٣٩٠ - كنى الحاكم (١/ ٣٨/ ب)."],[9800,"١٣٩١ - كنى البخارى (ص ١٥). كنى الحاكم (١/ ٣٨/ ب). الجرح (٤/ ٢/ ٣٤٧). تهذيب الكمال (٣/ ١٥٨٠). كنى ابن منده (٥٠/ أ) التهذيب (١٢/ ٢١). التقريب (٢/ ٣٩٥) وقال: مقبول، من السادسة، وأما أبو بشر صاحب أبى الزاهرية فضعيف، من طبقته./ مد. ت."],[9801,"(١) عامر بن لدين الاشعرى ويقال: عمرو بن لدين قاضى عبد الملك سمع أبا هريرة: روى معاوية بن صالح عن أبى بشر وعنه. قاله أبو حاتم. انظر الجرح (٣/ ١/ ٣٢٧)."],[9802,"قلت: ولُدَين: هو بضم اللام وفتح الدال المهملة وبالياء المثناة من تحتها وفى آخره النون. انظر الاكمال (٧/ ١٩٣)."],[9803,"(٢) قِنَّسْرين: بكسر أوله، وفتح ثانيه وتشديده، وقد كسره قوم ثم سين مهمله ="],[9804,"١٣٩٢ - أبو بشر، عن عثّامة (١) بن قيس البجلى روى عنه حبيب ابن عبيد (٢)."],[9805,"١٣٩٣ - أبو بشر، من أهل قنسرين قال: صلى عمر بن عبد العزيز العشاء فسجد في ﴿إِذَا السَّمَاءُ انْشَقَّتْ﴾ (٣) (٤)."],[9806,"= مدينة بينها وبين حلب مرحلة كانت عامرة آهلة فلما غلب الروم على حلب في سنة احدى وخمسين وثلاثمائة خاف أهل قِنَّسْرين وجلوا عنها وتفرقوا في البلاد، ولم يبق بها إلا خان تنزله انقوافل. اهـ. انظر مراصد الاطلاع (٣/ ١١٢٦)."],[9807,"١٣٩٢ - كنى البخارى (ص ١٥)، كنى ابن منده (٥٠/ أ)، كنى الحاكم (١/ ٣٩/ أ)، الجرح (٤/ ٢/ ٣٤٧) وذكره كما هنا وقال: سمعت أبى يقول ذلك. وسألته عنه فقال: لا يدرى من هو."],[9808,"(١) عثّامة: العين غير معجمة والثاء منقوطة بثلاث ومشددة وفى آخره الهاء، ابن قيس البجلى ذكره ابن أبى حاتم في الجرح (٣/ ٢/ ٣٩)، وقال: عن أبيه: له صحبة. وقال الذهبى في التجريد (١/ ٣٧٣): عثّامة بن قيس. وقيل: عسّامة. له حديث في الصوم: وقال العسكرى في التصحيفات أيضا (٢/ ٧٢٩): له صحبة."],[9809,"(٢) حبيب بن عبيد الرَّحَبى، بالمهملة المفتوحة ثم الموحدة أبو حفص الحمصى، ثقة، من الثالثة. التقرير (١/ ١٥٠)"],[9810,"١٣٩٣ - كنى البخارى (ص ١٥)، الجرح (٤/ ٢/ ٣٤٧)."],[9811,"(٣) الانشقاق: (١)"],[9812,"(٤) الأثر أخرجه البخارى في الكنى وابن أبى حاتم في الجرح. وزاد البخارى \"ولم يسجد مرة. قاله عبد اللَّه بن صالح عن معاوية بن صالح\" وأخرجه أيضا ابن أبى شيبة (٢/ ٨) من طريق سليمان بن حبيب قال: سجدت مع عمر بن عبد العزيز في ﴿إِذَا السَّمَاءُ انْشَقَّتْ﴾. وأخرج ابن الجوزى في سيرة عمر بن عبد العزيز (ص ١٥) من طريق أبى معشر عن محمد بن قيس قال: حدثنا عمر بن عبد العزيز انسجد في ﴿إِذَا السَّمَاءُ انْشَقَّتْ﴾؟ فقلت: لا. فقال عمر ="],[9813,"١٣٩٤ - أبو بشر الثّقفى (١)، حكي أنه رأى رؤيا في إبراهيم بن أدهم (٢)"],[9814,"= ابن عبد العزيز: أخبرنى أبو سلمة بن عبد الرحمن عن أبى هريرة أن رسول اللَّه -صلى الله عليه وآله وسلم- كان يسجد في ﴿إِذَا السَّمَاءُ انْشَقَّتْ﴾. وروى عن أبى هريرة رضي الله عنه أيضا مرفوعا قال \"سجد رسول اللَّه -صلى الله عليه وآله وسلم- في ﴿إِذَا السَّمَاءُ انْشَقَّتْ﴾ وأنه صلى بهم أبو هريرة مرة صلاة العتمة أو صلاة العشاء فقرأ ﴿إِذَا السَّمَاءُ انْشَقَّتْ﴾ فسجد فيها. فقال لمن سأله عن ذلك \"سجدت فيها خلف أبى القاسم -صلى الله عليه وآله وسلم- فلا أزال أسجدها حتى ألقاه\". أخرجه البخارى \"الاذان\" باب الجهر في العشاء. وفى باب القراءة في العشاء (٢/ ٢٥٠ - ٢٥١). وفى \"سجود القرآن\" باب سجدة ﴿إِذَا السَّمَاءُ انْشَقَّتْ﴾ (٢/ ٥٥٦). وفى باب من قرأ السجدة في الصلاة فسجد بها (٢/ ٥٥٩) ومسلم \"المساجد\" باب سجود التلاوة (١/ ٤٠٦ - ٤٠٧)، وأبو داود \"الصلاة\" باب السجود في ﴿إِذَا السَّمَاءُ انْشَقَّتْ﴾ و\"اقرأ\" (٢/ ٩)، والنسائى \"الافتتاح\" باب السجود في ﴿إِذَا السَّمَاءُ انْشَقَّتْ﴾ (٢/ ١٦١)، والترمذى \"السفر\" باب في السجدة في ﴿إِذَا السَّمَاءُ انْشَقَّتْ﴾ (٣/ ١٦٥) وقال: حسن صحيح، وابن ماجة \"اقامة الصلاة والسنة فيها\" باب عدد سجود القرآن (١/ ٣٣٦)، وأحمد (٢/ ٢٢٩)، وابن أبى شيبة (٢/ ٦ - ٧)، وعبد الرزاق (٣/ ٣٤٠)، والحديث أخرجه أيضا السيوطى في الدر المنثور (٦/ ٣٣٨) وزاد نسبته إلى ابن مردويه. وانظر تفسير ابن كثير (٤/ ٤٨٧)."],[9815,"١٣٩٤ - كنى ابن منده (٥٢/ أ) وقال: مجهول. كنى الحاكم (١/ ٣٨/ ب)."],[9816,"(١) هكذا في الأصل \"الثقفى\". والذى في كنى ابن منده، كنى الحاكم \"الفقيمى\"."],[9817,"(٢) إبراهيم بن ادهم، صدوق، من الثامنة (ت: ١٦٢). انظر التقريب (١/ ٣١) وله ترجمة مطولة أيضا في الحلية (٧/ ٣٦٧ - ٣٩٥ و٨/ ٣/ ٥٨) وفى سير أعلام النبلاء (٧/ ٣٨٧ - ٣٩٦)."],[9818,"وسَلم الخوّاص (١)، روى عنه مؤمل بن (شهاب) (٢)."],[9819,"(١) سلم: بفتح السين المهملة وسكون اللام، الخوّاص، بفتح الخاء وتشديد الواو وبعد الالف صاد مهملة يقال: لمن ينسخ الخوص. وسلم هذا رازى سكن الرملة من العباد. وقيل: انه دفن كتبه، وكان يحدث من حفظه فيغلط، ادركهُ أبو حاتم فلم يكتب عنه. اهـ. انظر الجرح (٢/ ١/ ٢٦٧)، اللباب (١/ ٤٦٧)."],[9820,"(٢) هكذا في الأصل \"شهاب\" والذى في كنى ابن منده، كنى الحاكم \"أهاب\" والذى في التقريب (٢/ ٢٩٠) مؤمّل، بوزن محمد، واهاب، بكسر أوله وبموحدة، الربعى العجلى، كوفى نزل الرملة، أصله من كرمان، صدوق له أوهام، من الحادية عشرة (ت: ٢٥٤). وانظر أيضا الجرح (٤/ ١/ ٣٧٥)."],[9821,"باب أبى البخترى"],[9822,"١٣٩٥ - أبو البَخْتَرى (١) الأزدى سمع عمر بن الخطاب وابنه عبد اللَّه بن عمر، مصرى روى عنه عبد اللَّه بن يزيد الحبلى أبو عبد الرحمن."],[9823,"١٣٩٦ - أبو البخترى العبدى كوفى سمع ابن عمر روى عنه الأعمش ويونس بن أبى اسحاق."],[9824,"١٣٩٧ - أبو البخترى الهجيمى عن محمد بن سيرين وزرارة بن أوفى بصرى روى عنه حماد بن زيد، ذكر اسحاق بن منصور عن يحيى بن معين قال: \"أبو البخترى الهجيمى ثقة\" (٢)."],[9825,"١٣٩٨ - أبو البخترى عن رجل عن سعيد بن جبير روى عنه إبراهيم بن عدى (٣)."],[9826,"١٣٩٥ - كنى البخارى (ص ١٥)، كنى الحاكم (١/ ٣٩/ ب)، الجرح (٤/ ٢/ ٣٤٦)، كنى ابن منده (٥٣/ أ)."],[9827,"(١) البخترى: بفتح موحدة وسكون معجمة وفتح مثناة فوق كسر راء وشدة ياء. الاكمال (١/ ٤٥٩)، المغنى (ص ٨)."],[9828,"١٣٩٦ - كنى ابن منده (٥٣/ أ)."],[9829,"١٣٩٧ - كنى مسلم (ص ١٧٩)، كنى الحاكم (١/ ٣٩/ ب)، الجرح (٤/ ٢/ ٣٤٧)، كنى ابن ابن منده (٥٣/ أ)، الاكمال (١/ ٤٦٠)."],[9830,"(٢) انظر الجرح (٤/ ٢/ ٣٤٧)."],[9831,"١٣٩٨ - كنى البخارى (ص ١٥)، كنى ابن منده (٥٣/ أ)، كنى الحاكم (١/ ٣٩/ ب)، الجرح (٤/ ٢/ ٣٤٦)."],[9832,"(٣) هكذا في الأصل إبراهيم بن عدى. وفى مصادر الترجمة \"إبراهيم بن عربى\". وانظر ترجمة إبراهيم بن عربى في التاريخ الكبير (١/ ١/ ٣٠٨) الاكمال (٦/ ١٧٧) وعربى: بفتح العين والراء كسر الباء المعجمة بواحدة. انظر الاكمال (٦/ ١٧٦)."],[9833,"باب أبى بشير"],[9834,"١٣٩٩ - أبو بشير صاحب على رضي الله عنه. روى عنه سفيان بن دينار (١) وفطر بن خليفة."],[9835,"١٤٠٠ - أبو بشير سمع ابن عمر قال: لا حول ولا قوة إلا باللَّه كنز من كنوز الجنة (٢)."],[9836,"١٣٩٩ - كنى البخارى (ص ١٥)، كنى الحاكم (١/ ٤١/ أ)، الجرح (٤/ ٢/ ٣٤٨)، كنى ابن منده (٥٤/ أ)."],[9837,"(١) سفيان بن دينار التمار، الكوفى، ثقة، من السادسة. التقريب (١/ ٣١٠) (١٤٠٠) كنى البخارى (ص ١٥)، الجرح (٤/ ٢/ ٣٤٨)، كنى ابن منده (٥٤/ أ)، كنى الحاكم (١/ ٤١/ أ)."],[9838,"(٢) الحديث أخرجه البخارى في الكنى، وابن منده في الكنى، والحاكم في الكنى وابن أبى حاتم في الجرح. انظر مصادر الترجمة. وذكر الهيثمى في مجمع الزوائد (١٠/ ٩٨) قال: عن ابن عمر قال: قال رسول اللَّه -صلى الله عليه وآله وسلم-: \"اكثروا من غرس الجنة، فانه عذب ماؤها، طيب ترابها، فأكثروا من غراسها، لا حول ولا قوة إلا باللَّه\" رواه الطبرانى. وفيه عقبة بن على وهو ضعيف."],[9839,"وأخرج الحاكم في ترجمة أبى بيان الآتية بعد هذه الترجمة من طريق الأعمش عن أبى بيان قال: كنت أطوف مع ابن عمر، فسمع رجلا يقول لا حول ولا قوة إلا باللَّه. فقال ابن عمر: أما انها كنز من كنوز الجنة. اهـ. انظر الكنى (١/ ٤٢/ ب)."],[9840,"والحديث أخرجه أيضا الطيالسى (١/ ٢٥٠) من حديث أبى هريرة رضي الله عنه يرفعه به، والطبرانى في الكبير (١/ ٤٢٠) من حديث بهز بن حكيم عن أبيه عن جده يرفعه به. والنسائى في عمل اليوم والليلة (١٤) و(٤٣)."],[9841,"باب أبى بيان"],[9842,"١٤٠١ - أبو بَيَان (١)، كوفى، سمع عبد اللَّه بن عمر. روى عنه الأعمش سليمان بن مهران."],[9843,"١٤٠٢ - أبو بيان قال: كتب عدى بن أرطأة (٢) إلى عمر بن عبد العزيز وذكر الخبر."],[9844,"١٤٠١ - كنى الحاكم (١/ ٤٢/ ب)، المقتنى في سرد الكنى (٢٤/ ب)."],[9845,"(١) بيان: بفتح الباء الموحدة وتخفيف الياء المثناة من تحتها. انظر الاكمال (١/ ٣٦٧)."],[9846,"١٤٠٢ - كنى البخارى (ص ١٦)، كنى الحاكم (١/ ٤٢/ ب)، المقتنى في سرد الكنى (٢٤/ ب)."],[9847,"(٢) عدى بن أرطأة الفزارى، عامل عمر بن عبد العزيز، مقبول من الرابعة قتل سنة (١٠٢). انظر التقريب (٢/ ١٦)، تهذيب الكمال (٢/ ٩٢٣)، سير أعلام النبلاء (٥/ ٥٣)."],[9848,"باب الافراد في كنى الباء"],[9849,"١٤٠٣ - أبو بَركَة (١) (٢) روى عن سعد بن أبى وقاص أنه قال لما قتل على ذا الثُّدَيَّة (٣): ابن أبى طالب جان الردهة (٤). روى عنه أبو اسحاق."],[9850,"١٤٠٤ - أبو بُسرة (٥) الغفارى مدنى روى عن البراء بن عازب روى عنه"],[9851,"١٤٠٣ - كنى الحاكم (١/ ٤٢/ ب)، الاكمال (١/ ٢٣٣)."],[9852,"(١) في الاكمال (١/ ٢٣٣) بركة: متوالى الفتحات."],[9853,"(٢) في الاكمال زيادة الصائدى."],[9854,"(٣) ذو الثدية: ذكره عبد القاهر البغدادى في الفرق بين الفرق (ص ٧٦) فقال: حرقوص بن زهير البجلى المعروف بذى الثديه. اهـ. وقال ابن الاثير في النهاية (١/ ٢٠٨) الثُّدية: تصغير الثدى وإنما ادخل فيه الهاء وان كان الثدى مذكرا كأنه اراد قطعة من ثدى، وهو تصغير الثندوة بحذف النون، لانها من تركيب الثدى وانقلاب الياء فيها واوا لضمه ما قبلها، ولم يضر ارتكاب الوزن لظهور الاشتقاق. ويروى. ذو اليدية. بالياء بدل الثاء. تصغير اليد وهى مؤنثة. اهـ."],[9855,"(٤) هكذا العبارة هنا. والذى في كنى الحاكم، والاكمال: \"لما قتل على رضي الله عنه ذا الثدية قال سعد: \"لقد قتل على جان الردهة\". وأخرجه البسوى في المعرفة والتاريخ (١/ ٢٣٢) من طريق شعبة عن أبى اسحاق عن حامد قال: سمعت سعدا يقول: قتل على شيطان الردهة. وقال: سئل أبو يوسف عن حامد هذا؟ فقال: لا أعرفه. وأخرجه أيضا ابن كثير في البداية والنهاية (٦/ ٢١٧) و(٧/ ٢٩٧)."],[9856,"١٤٠٤ - كنى البخارى (ص ١٦)، كنى الحاكم (١/ ٤٢/ أ)، الجرح (٤/ ٢/ ٣٤٨) الميزان (٤/ ٤٩٥)، التهذيب (١٢/ ٢٠)، التقريب (٢/ ٣٩٥) وقال: مقبول، من الرابعة./ د. ت."],[9857,"(٥) بمضمومة وسكون مهملة. المغنى (ص ١٠)."],[9858,"صفوان بن سليم."],[9859,"١٤٠٥ - أبو بَصِير (١) العبدى الأعمى من عبد القيس كوفى سمع أبى بن كعب روى عنه أبو اسحاق السبيعى وابنه عبد اللَّه بن أبى بصير (٢)."],[9860,"١٤٠٦ - أبو بردة العنبرى، عن ابن أبى مليكة. روى عنه وكيع بن الجراح."],[9861,"١٤٠٧ - أبو بحر، عن البراء بن عازب. روى عنه أبو الحكم زيد بن أبى الشعثاء البصرى (٣)."],[9862,"١٤٠٨ - أبو بحر البكراوى قال على بن المدينى: كان يحيى حسن الرأى فيه. قال على وأنا لا أحدث عنه بشئ فكان يحيى ربما كلمنى فيه وقال: انكم تكتبون عمن دونه."],[9863,"١٤٠٩ - أبو بسطام مولى أسامة بن زيد مولى النبى عليه السلام روى عنه"],[9864,"١٤٠٥ - كنى ابن منده (٥٥/ ب)، كنى البخارى (ص ١٦)، كنى الحاكم (١/ ٤٢/ أ)، الجرح (٤/ ٢/ ٣٤٨)، التهذيب (١٢/ ٢٢)، التقريب (٢/ ٣٩٥)، وقال: يقال: اسمه حفص، مقبول، من الثالثة./ قد. س. ق."],[9865,"(١) بصير: اوله باء مفتوحه، معجمة بواحدة وصاد مبهمة مكسورة الاكمال (١/ ٣١٩)."],[9866,"(٢) عبد اللَّه بن أبى بصير العبدى، وثقه العجلى، من الثالثة انظر التقريب (١/ ٤٠٤)."],[9867,"١٤٠٦ - كنى البخارى (ص ٦)، كنى الحاكم (١/ ٤٠/ أ)، كنى ابن منده (٥٣/ ب)"],[9868,"١٤٠٧ - كنى ابن منده (٥٢/ ب)، كنى البخارى (ص ١٦)، كنى الحاكم (١/ ٣٩/ ب)، الجرح (٤/ ٢/ ٣٤٨)، الميزان (٤/ ٤٩٤)، وقال: مجهول اللسان (٧/ ١٣)، تعجيل المنفعة (ص ١٩٣ و٣٠٧)."],[9869,"(٣) مقبول، من الرابعة. التقريب (١/ ٢٧٥)."],[9870,"١٤٠٨ - تقدمت هذه الترجمة في الكتاب الثانى وتم التعليق عليها هناك. انظر الترجمة (٤٦٩)."],[9871,"١٤٠٩ - كنى البخارى (ص ١٦)، كنى الحاكم (١/ ٤١/ ب). كنى ابن منده (٥٤/ ب)، الجرح (٤/ ٢/ ٣٤٨)."],[9872,"مرزوق بن ماهان (١)."],[9873,"١٤١٠ - أبو بدر (٢) الحلبى عن عبد اللَّه بن عبيد بن عمير (٣) عن أبيه عن جده (٤) روى عنه بكر بن خنيس."],[9874,"١٤١١ - أبو البدّاح بن عاصم بن عدى الأنصارى عن أبيه (٥). روى عنه أبو بكر بن محمد بن عمرو بن حزم وابنه عاصم بن أبى البداح (٦) وقيل: ان أبا البداح لقب كنيته أبو عمرو."],[9875,"١٤١٢ - أبو بُرَيْدة (٧)، سمع ابن عباس. روى عنه عبد العزيز بن حكيم (٨)."],[9876,"(١) هو أبو جندب تقدم في (٥٥٠)"],[9877,"١٤١٠ - كنى البخارى (ص ١٦)، كنى الحاكم (١/ ٤١/ ب)، الجرح (٤/ ٢/ ٣٤٨)"],[9878,"(٢) بدر: بسكون الدال وآخره راء. الاكمال (١/ ٢١٨)."],[9879,"(٣) ثقة، من الثالثة، استشهد غازيا سنة (١١٣). التقريب (١/ ٤٣١)."],[9880,"(٤) هو عمير بن قتادة بن سعد بن عامر الليثى. صحابى، من مسلمة الفتح التقريب (٢/ ٨٦)."],[9881,"١٤١١ - تقدمت هذه الترجمة في الكتاب الأول في الصحابة حيث رجح ابن عبد البر هناك أنه صحابى، انظر الترجمة (٤٢)."],[9882,"(٥) عاصم بن عدى بن الحارث بن العجلان الأنصارى، صحابى. شهد أحدا. مات في خلافة معاوية./ عـ. التقريب (١/ ٣٨٤)."],[9883,"(٦) انظر ترجمته في الجرح (٣/ ١/ ٣٤١)."],[9884,"١٤١٢ - كنى البخارى (ص ١٦)، كنى الحاكم (١/ ٤٢/ ب)، الميزان (٤/ ٤٩٥) اللسان (٧/ ١٤)"],[9885,"قال الذهبى وتبعه ابن حجر: لا يعرف."],[9886,"(٧) بريدة: بتصغير واهمال دال. المغنى (ص ٩)."],[9887,"(٨) عبد العزيز بن حكيم، وثقه ابن معين، وقال أبو حاتم: ليس بقوى يكتب حديثه انظر الجرح (٢/ ٢/ ٣٧٩ - ٣٨٠)."],[9888,"١٤١٣ - أبو البَيّاع (١)، سمع أبا هريرة. روى عنه عكرمة بن عمار."],[9889,"١٤١٤ - أبو البراء قال: كان ابن عمر يطوف بالبيت. روى عنه أبو الأزهر."],[9890,"١٤١٥ - أبو بلال الاشعرى من ولد عبد اللَّه بن أبى بردة بن أبى موسى الاشعرى كوفى. روى عن شريك وقيس بن الربيع وعبد السلام بن حرب (٢) وحفص بن غياث وعيسى بن غياث وعيسى بن يونس روى عنه أبو حاتم الرازى. وقال (٣): سألته عن اسمه فقال: ليس لى اسم غير كنيتى."],[9891,"١٤١٦ - أبو بديل التميمى. سأل يحيى بن معين يعد في البغداديين روى عنه محمد بن عثمان بن أبى شيبة (٤)."],[9892,"١٤١٣ - كنى البخارى (ص ١٦)، كنى الحاكم (١/ ٤٢/ ب)، الجرح (٤/ ٢/ ٣٤٨)، الميزان (٤/ ٥٠٧)، اللسان (٧/ ٢٢)."],[9893,"(١) البَيّاع: بفتح الباء الموحدة وفى آخره عين مهملة. الاكمال (١/ ٣٨٣) قال الذهبى وتبعه ابن حجر: لا يكاد يعرف."],[9894,"١٤١٤ - كنى الحاكم (١/ ٤٢/ ب)."],[9895,"١٤١٥ - كنى الحاكم (١/ ٤١/ ب)، الجرح (٤/ ٢/ ٣٥٠)، الميزان (٤/ ٥٠٧) اللسان (٧/ ٢٢) وقال: يقال: اسمه مرداس بن محمد بن الحارث بن عبد اللَّه بن أبى بردة بن أبى موسى عبد اللَّه بن قيس الاشعرى، وقيل: اسمه محمد، وقيل: عبد اللَّه، ضعفه الدارقطنى."],[9896,"(٢) عبد السلام بن حرب، ثقة حافظ، له مناكير، من صغار الثامنة (ت: ١٨٧). انظر التقريب (١/ ٥٠٥)"],[9897,"(٣) انظر الجرح (٤/ ٢/ ٣٥٠)."],[9898,"١٤١٦ - كنى ابن منده (٥٥/ ب)، كنى الحاكم (١/ ٤٢/ ب)."],[9899,"(٤) محمد بن عثمان بن أبى شيبة: كوفى سكن بغداد، كان كثير الحديث واسع الرواية ذا معرفة وفهم وله تاريخ كبير، ومات ببغداد سنة سبع وتسعين ومائتين. انظر تاريخ بغداد (٣/ ٤٢ - ٤٧)."],[9900,"حرف التاء"],[9901,"باب أبى تميم"],[9902,"١٤١٧ - أبو تميم عن المنذر بن المبارك (ملك) (١) شامى، روى عنه عبد الرحمن بن ثابت بن ثوبان (٢)."],[9903,"١٤١٨ - أبو تميم الزهرى مصرى، روى عن أبى هريرة. روى عنه عياش بن عباس. وليس بأبى تميم الجيشانى (٣)."],[9904,"١٤١٧ - المقتنى في سرد الكنى (٢٥/ أ)."],[9905,"(١) هكذا رسمه في الأصل. والمنذر هذا هو المنذر بن مالك بن قطعة أبو نضرة. تقدم. انظر الترجمة (٨٨٠)."],[9906,"(٢) عبد الرحمن بن ثابت بن ثوبان. صدوق يخطئ ورمى بالقادر، وتغيّر بآخره من السابعة. (ت: ١٦٥). التقريب (١/ ٤٧٤)."],[9907,"١٤١٨ - كنى الحاكم (١/ ٤٣/ ب)، كنى ابن منده (٥٦/ أ)، تعجيل المنفعة (ص ٣٠٩)، المقتنى في سرد الكنى (٢٥/ أ)."],[9908,"(٣) تقدم في الكتاب الثانى. انظر الترجمة (٤٩٨)."],[9909,"باب الافراد في التاء"],[9910,"١٤١٩ - أبو توبة (١) المرّى، شامى. روى عنه معاوية بن صالح، وصفوان ابن عمرو. قوله."],[9911,"١٤٢٠ - أبو تميمة الأموى، الشامى مولى لبنى مروان. روى عن عمر بن روى عنه عبيد اللَّه بن الوليد (٢)."],[9912,"١٤٢١ - أبو التُّجِيب (٣) مولى عبد اللَّه بن عمرو بن العاص مصرى سمع أبا سعَيد الخدرى. روى عنه بكر بن سوادة."],[9913,"١٤١٩ - كنى البخارى (ص ١٦)، كنى الحاكم (١/ ٤٢/ ب)، الجرح (٤/ ٢/ ٣٥٠)"],[9914,"(١) توبة: بتاء معجمة باثنتين من فوقها وبعدها واو ساكنة وباء مفتوحة معجمة بواحدة. الاكمال (١/ ٣٧٣)."],[9915,"١٤٢٠ - كنى الحاكم (١/ ٤٣/ أ)."],[9916,"(٢) عبيد اللَّه بن الوليد الوصّافى الكوفى. ضعيف، من السادسة (١/ ٥٤٠)."],[9917,"١٤٢١ - كنى الحاكم (١/ ٤٣/ ب)، كنى ابن منده (٥٦/ أ)، الميزان (٤/ ٥٠٨) وقال: لا يعرف. ويقال: أبو النجيب، بالنون. اهـ."],[9918,"(٣) التُّجيب: أوله تاء مضمومة معجمة باثنتين من فوقها وبعدها جيم مكسورة وآخرها باء معجمة بواحدة. الاكمال (١/ ٢١٤). وقد جاء في الاكمال أيضا (١/ ٢١٢). أبو النجيب. أوله نون مفتوحة وبعدها جيم مكسورة وآخره باء معجمة بواحدة. أبو نجيب شيخ لأهل مصر اسمه ظليم. هو مولى عبد اللَّه ابن سعد بن أبى سرح. يروى عن أبى سعيد الخدرى. روى عنه بكر بن سوادة. اهـ."],[9919,"وقال ابن حجر في التهذيب (١٢/ ٢٥٤) أبو النجيب بالنون، العامرى السرخسى المصرى، مولى ابن أبى السرح، ويقال: أبو التجيب، بالتاء المثناة يروى عن أبى سعيد وابن عمر وعنه بكر بن سوادة. . . وضبطه أبو أحمد الحاكم وابن عبد البر وغير واحد بالتاء المثناة المضمومة قبل الجيم. أهـ."],[9920,"١٤٢٢ - أبو تَهْلِل (١)، روى عن بلال (٢) مؤذن النبى عليه السلام. روى عنه جعفر بن برقان."],[9921,"١٤٢٢ - الجرح (٤/ ٢/ ٣٥٠)."],[9922,"(١) تَهْلِل: التاء مفتوحة فوقها نقطتان، واللام الاولى مكسورة. انظر تصحيفات المحدثين (٣/ ١١١٢ - ١١١٣)."],[9923,"(٢) بلال: هو ابن رباح مؤذن النبى -صلى الله عليه وآله وسلم- مولى أبى بكر، من السابقين الأولين، شهد بدرا والمشاهد، مات بالشام سنة سبع عشرة أو ثمان عشرة. وقيل: سنة عشرين، وله بضع وستون سنة، انظر التقريب (١/ ١١٠)."],[9924,"حرف الثاء"],[9925,"باب أبى ثابت"],[9926,"١٤٢٣ - أبو ثابت عن أبى الدرداء. روى حديثه الأعمش واظنه الذى روى عنه أبو راشد الحبرانى (١). ذكره الحاكم (٢). وفيه نظر."],[9927,"١٤٢٤ - أبو ثابت الدمشقى، روى عن مكحول. روى عنه سعيد بن أبى أيوب. يقال له: جبار الرحبى."],[9928,"١٤٢٥ - أبو ثابت من ولد ثابت بن قيس بن شمّاس الأنصارى (٣) روى عن إسماعيل بن محمد بن سعد بن أبى وقاص. روى عنه زيد بن الحباب."],[9929,"١٤٢٣ - كنى البخارى (ص ١٧)، الجرح (٢/ ٤/ ٣٥٢)، كنى ابن منده (٥٧/ أ)"],[9930,"(١) أبو ثابت الذى روى عنه أبو راشد الحبرانى هو من قريش يدعى جار الوحى بيته عند بيت النبى -صلى الله عليه وآله وسلم-. انظر الجرح (٤/ ٢/ ٣٥١)."],[9931,"(٢) كنى الحاكم (١/ ٤٤/ ب)."],[9932,"١٤٢٤ - كنى البخارى (ص ١٧)، كنى الحاكم (١/ ٤٤/ ب)، الجرح (٤/ ٢/ ٣٥١)، كنى ابن منده (٥٧/ أ)."],[9933,"١٤٢٥ - كنى البخارى (ص ١٧)، كنى الحاكم (١/ ٤٤/ ب)، الجرح (٤/ ٢/ ٣٥١)، كنى ابن منده (٥٧/ أ)."],[9934,"(٣) ثابت بن قيس بن شمّاس، بمعجمة وميم مشددة وآخره مهملة انصارى خزرجى، خطيب الأنصار، من كبار الصحابة، بشره النبى -صلى الله عليه وآله وسلم- بالجنة واستشهد باليمامة. التقريب (١/ ١١٧)."],[9935,"باب أبى ثور"],[9936,"١٤٢٦ - أبو ثور الأزدى عن أبى هريرة. روى عنه الشعبى."],[9937,"١٤٢٧ - أبو ثور الحدّانى (١). كوفى. سمع حذيفة بن اليمان وأبا موسى الأشعرى وأبا مسعود الأنصارى. روى عنه أبو البخترى الطائى."],[9938,"١٤٢٨ - أبو ثور الأعمى، سمع بلالا، روى عنه الشعبى وقيل: هو الأزدى (٢) الراوى عن أبى هريرة."],[9939,"١٤٢٦ - كنى مسلم (ص ١٩٦)، كنى الحاكم (١/ ٤٥/ ب)، الجرح (٤/ ٢/ ٣٥١)، كنى ابن منده (٥٧/ ب)."],[9940,"١٤٢٧ - كنى البخارى (ص ١٧)، كنى ابن منده (٥٧/ ب)، كنى الحاكم (١/ ٤٥/ ب)، تاريخ ابن معين (٢/ ٦٩٩)، الجرح (٤/ ٢/ ٣٥١) الثقات (٥/ ٥٧٢)، التهذيب (١٢/ ٥١)، التقريب (٢/ ٤٠٤)، وقال: مقبول، من الثانية./ ت."],[9941,"(١) في الجرح \"الحرّانى\" بالراء، كوفى ويقال: \"الحدّانى\" بالدال."],[9942,"والحدّانى أصح. اهـ. وفى تاريخ ابن معين \"الحدى\" وفى التهذيب \"أبو ثور الازدى الحدانى الكوفى. روى عن ابن مسعود وحذيفة وأبى هريرة، وعنه الشعبى وعمرو بن مرة وقيل: عن عمرو بن مرة عن أبى البخترى عنه. . قال قوم هو حبيب بن أبى مليكة. اهـ. قلت: وقد فرق الحاكم بين أبى ثور هذا وبين حبيب بن أبى مليكة. انظر مصادر الترجمة في كل ما ذكر."],[9943,"١٤٢٨ - كنى البخارى (ص ١٧)، كنى ان منده (٥٧/ ب) وقال: أراه الأول. قلت ويريد بالأول هنا الازدى الذى روى عن أبى هريرة المتقدم في (١٤٢٦)، كنى الحاكم (١/ ٤٥/ ب) وقال: لا ادرى هو الراوى عن أبى هريرة أم هما اثنان؟"],[9944,"(٢) انظر الترجمة (١٤٢٦)."],[9945,"باب أبى ثمامة"],[9946,"١٤٢٩ - أبو ثُمَامة (١) الصّائدى (٢). كوفى سمع عليا رضي الله عنه. وقد روى عن حسين بن على. روى عنه أبو اسحاق الهمدانى وعبد العزيز بن رفيع (٣)."],[9947,"١٤٣٠ - أبو ثمامة الحنّاط. ويقال: القمّاح (٤) حجازى (٥). روى عن كعب ابن عجرة. روى عنه سعيد بن أبى سعيد."],[9948,"١٤٣١ - أبو ثمامة، الثقفى (٦) بصرى. روى عن عبد اللَّه بن عمرو بن العاص، روى عنه قتادة."],[9949,"١٤٢٩ - كنى البخارى (ص ١٧)، كنى مسلم (ص ١٩٧)، كنى ابن منده (ص ٥٧/ ب)، كنى الحاكم (١/ ٤٥/ ب)، الجرح (٤/ ٢/ ٣٥١)."],[9950,"(١) ثمامة: بمضمومة، وخفة ميمين. المغنى (ص ١٤)."],[9951,"(٢) الصّائدى، بفتح الصّاد المهملة وبعد الالف ياء مثناة من تحتها وفى آخرها دال مهملة. هذه النسبة إلى صائد وهو بطن من همدان. اللباب (٢/ ٢٣٢)."],[9952,"(٣) عبد العزيز بن رفيع، بفاء مصغرا، الاسدى، أبو عبد الملك المكى، نزيل الكوفة، ثقة، من الرابعة. التقريب (١/ ٥٠٩)."],[9953,"١٤٣٠ - كنى البخارى (ص ١٧)، كنى ابن منده (٥٧/ ب)، كنى مسلم (ص ١٩٧) كنى الحاكم (١/ ٤٥/ ب)، الجرح (٤/ ٢/ ٣٥١) وقال عن أبيه: لا أعرف اسمه، الثقات (٥/ ٥٦٦)، الميزان (٤/ ٥٠٩)، التهذيب (١٢/ ٥١)، التقريب (٢/ ٤٠٤) وقال: مجهول الحال، من الثالثة./ د"],[9954,"(٤) القمّاح: نسبة إلى بيع القمح. كما أن الحناط نسبة إلى بيع الحنطة. وهما بمعنى واحد. انظر اللباب (٣/ ٥٣)."],[9955,"(٥) في كنى البخارى والثقات زيادة \"كان حريفا لكعب بن عجرة\"."],[9956,"١٤٣١ - كنى الحاكم (١/ ٤٥/ ب)، الثقات (٥/ ٥٦٧)، كنى ابن منده (٥٧/ ب)."],[9957,"(٦) هكذا في الأصل \"الثقفى\" والذى في الثقات \"الحنفى\"."],[9958,"باب الافراد في الثاء"],[9959,"١٤٣٢ - أبو ثعلبة القرظى. سمع عمر بن الخطاب. روى عنه الزهرى."],[9960,"١٤٣٣ - أبو ثوابة (١) شامى. روى عن عبد الرحمن بن هند روى عنه بقية ابن الوليد."],[9961,"١٤٣٤ - أبو ثامر (٢) العابد. روى عنه ثابت البنانى."],[9962,"١٤٣٢ - كنى الحاكم (١/ ٤٦/ ب)."],[9963,"١٤٣٣ - كنى الحاكم (١/ ٤٦/ أ)، كنى ابن منده (٥٧/ ب)."],[9964,"(١) في كنى ابن منده زيادة \"الزبيدى\"."],[9965,"١٤٣٤ - كنى البخارى (ص ١٨)، كنى الحاكم (١/ ٤٦/ ب)، الجرح (٤/ ٢/ ٣٥٢)، كنى ابن منده (٥٨/ أ)."],[9966,"(٢) في كنى ابن منده \"أبو ثابر\" بالباء الموحدة."],[9967,"باب الجيم"],[9968,"من يكنى منهم أبا جعفر"],[9969,"١٤٣٥ - أبو جعفر (١) رجل من أهل المدينة. سمع أبا هريرة. روى عنه أبى كثير."],[9970,"١٤٣٦ - أبو جعفر الأنصارى. شهد الدار يوم قتل عثمان. روى عنه ثابت ابن عبيد (٢)."],[9971,"١٤٣٥ - كنى مسلم (ص ٢١٥)، كنى الحاكم (١/ ٥٣/ أ)، تهذيب الكمال (٣/ ١٥٩٣)، الميزان (٤/ ٥١١)، التهذيب (١٢/ ٥٥)، التقريب (٢/ ٤٠٦) وقال: مقبول، من الثالثة، ومن زعم أنه محمد بن على بن الحسين فقد وهم. / بخ. د. ت. س. ق."],[9972,"(١) قال المزى في تهذيب الكمال: أبو جعفر الأنصارى المدنى المؤذن. . قال الترمذى: لا يعرف اسمه. وقال غيره هو محمد بن على بن الحسين رواه أبو مسلم الكجى وأبو بكر الباغندى الكبير في أبى عاصم النبيل عن حجاج بن عثمان الصواف عن يحيى بن أبى كثير عن محمد بن على عن أبى هريرة."],[9973,"وقال الباغندى في حديثه: عن أبى جعفر محمد بن على. فاللَّه أعلم. اهـ."],[9974,"١٤٣٦ - كنى مسلم (ص ٢١٤)، كنى ابن منده (٥٩/ أ) وذكر حديثه من طريق الأعمش عن ثابت بن عبيد عن أبى جعفر شيخ من الأنصار قال: شهدت الدار يوم قتل عثمان، التقريب (٢/ ٤٠٦) وقال: أدرك أبا بكر الصديق، روى عنه ثابت بن عبيد، من الثالثة./ تمييز."],[9975,"(٢) ثابت بن عبيد الأنصارى، مولى زيد بن ثابت، كوفى، ثقة، من الثالثة. التقريب (١/ ١١٦)."],[9976,"١٤٣٧ - أبو جعفر الأشجعى مولى لهم. سمع أبا هريرة وعائشة روى عنه مطرف بن طريف وأبو سعد البقّال والعوام بن حوشب."],[9977,"١٤٣٨ - أبو جعفر الحنفى عن أبى هريرة. روى عنه عثمان بن أبى العاتكة."],[9978,"١٤٣٩ - أبو جعفر العمى (١). سمع عمر بن الخطاب، وعبد اللَّه بن مسعود. روى عنه عمران بن سليمان (٢)."],[9979,"١٤٤٠ - أبو جعفر الذى روى عن أبى المثنى مؤذن مسجد الكوفة عن ابن عمر قال: \"كان الأذان على عهد رسول اللَّه -صلى الله عليه وآله وسلم- مثنى والإقامة مرة (٣) \". روى عنه شعبة."],[9980,"١٤٣٧ - كنى البخارى (ص ١٨)، كنى مسلم (ص ٢١٥)، كنى الحاكم (١/ ٥٤/ أ)، الثقات (٥/ ٥٦٨)، الجرح (٤/ ٢/ ٣٥٢) وقال: سألت أبى عنه فقال: لا أدرى من هو؟"],[9981,"١٤٣٨ - كنى الحاكم (١/ ٥٤/ أ)، الميزان (٤/ ٥١١) وقال: مجهول. اللسان (٧/ ٢٥)."],[9982,"١٤٣٩ - كنى البخارى (ص ١٨)، كنى الحاكم (١/ ٥٤/ أ)، الجرح (٤/ ٢/ ٣٥٢)، كنى ابن منده (٥٩/ أ)."],[9983,"(١) الذى في الجرح، وفى كنى ابن منده \"القبى\" بالباء الموحدة."],[9984,"(٢) عمران بن سليمان المرادى. ترجمته في الجرح (٣/ ١/ ٢٩٩)."],[9985,"١٤٤٠ - كنى مسلم (ص ٢١٥)، الجرح (٤/ ٢/ ٣٥٣)، كنى ابن منده (٥٩/ أ)، تهذيب الكمال (٣/ ١١٥٩، ١٥٩٤) وقال: أبو جعفر مؤذن مسجد العريان اسمه محمد بن إبراهيم بن مسلم بن مهران. روى عنه شعبة فكناه أبا جعفر ولم يسمه. . ."],[9986,"(٣) الحديث أخرجه أحمد في المسند (٢/ ٨٧)، وأبو داود \"الصلاة\" باب في الإقامة (١/ ١٤١)، والنسائى \"الاذان\" باب تثنية الاذان (٢/ ٣)، وباب كيف الإقامة (٢/ ٢١)، وأبو داود الطيالسى في المسند (١/ ٧٩)، وابن خزيمة في"],[9987,"الصحيح (١/ ١٩٣)، والبغوى في شرح السنة (٢/ ٢٥٥)، الدارمى (١/ ٢٧٠)، والمزى في تهذيب الكمال (٣/ ١١٥٩) كلهم أخرجوه من = سئل أبو زرعة عن أبى جعفر الذى روى عن أبى المثنى قال: هو كوفى لا أعرفه إلا في هذا الحديث (١)."],[9988,"وقال ابن أبى حاتم (٢): قلت لأبى: روى عيسى بن يونس هذا الحديث عن شعبة فقال: عن أبى جعفر القارئ. فقال: غلط (٣) عيسى. أبو جعفر القارئ مدنى وهذا كوفى."],[9989,"١٤٤١ - أبو جعفر بن محمد بن رُكَانة (٤) بن عبد يزيد. روى عن أبيه (٥)."],[9990,"= طريق شعبة عن أبى جعفر قال: سمعت أبا المثنى عن ابن عمر قال: \"كان الاذان على عهد رسول اللَّه -صلى الله عليه وآله وسلم- مثنى مثنى والإقامة مرة مرة غير انه يقول: قد قامت الصلاة قد قامت الصلاة\". وفيه أيضا عندهم. قال شعبة: لم أسمع من أبى جعفر غير هذا الحديث هذا اللفظ لأبى داود."],[9991,"والباقون بنحوه وفيه عند بعضهم ثنا شعبة عن أبى جعفر مؤذن مسجد العريان قال: سمعت أبا المثنى مؤذن مسجد الأكبر. وأخرجه ابن أبى شيبة في المصنف (١/ ٢٠٥) من طريق سليمان التيمى قال: حدثنى رجل في مسجد الكوفة عن ابن عمر فذكره موقوفا. والحديث المرفوع حسّنه الألبانى في تعليقه على صحيح ابن خزيمة. لكن قال الحافظ في فتح البارى (٢/ ٨٢) عند ذكر حديث ابن عمر هذا: صححه ابن خزيمة. اهـ. ويشهد لهذا الحديث حديث أنس أخرجه البخارى \"الاذان\" باب الاذان مثنى مثنى (٢/ ٨٢) وفى باب الإقامة واحدة إلا قوله \"قد قامت الصلاة\" (٢/ ٨٣) بلفظ \"أمر بلال أن يشفع الاذان وان يوتر الإقامة\"."],[9992,"(١) انظر الجرح (٤/ ٢/ ٣٥٣)."],[9993,"(٢) الجرح (٤/ ٢/ ٣٥٣)."],[9994,"(٣) هكذا في الأصل \"غلط\" والذى في مطبوعة الجرح \"خطأ\"."],[9995,"١٤٤١ - كنى البخارى (ص ١٨)، الجرح (٤/ ٢/ ٣٥٣)، كنى ابن منده (٥٩/ ب)، الميزان (٤/ ٥١٠) وقال: مجهول، التهذيب (١٢/ ٥٥)، التقريب (٢/ ٤٠٦) وقال: مجهول، من السادسة./ د. ت."],[9996,"(٤) ركانه: بمضمومة وخفة كاف وبنون. المغنى (ص ٣٤)."],[9997,"(٥) محمد بن ركانه بن عبد يزيد المطلبى، مجهول، من الثالثة ووهم من ذكره ="],[9998,"١٤٤٢ - أبو جعفر. روى عن شريح. روى عنه سليمان التيمى."],[9999,"١٤٤٣ - أبو جعفر. روى عن ابن سيرين. روى عنه مسعدة بن اليسع (١)."],[10000,"١٤٤٤ - أبو جعفر الازهرى. من ولد عبد الرحمن بن الأزهر (٢). روى عنه محمد بن إسماعيل البخارى."],[10001,"١٤٤٥ - أبو جعفر الفسوى (٣). سمع اسحاق بن بشر الكاهلى (٤)."],[10002,"١٤٤٦ - أبو جعفر السُّويدى (٥). روى عن عبد الرزاق. روى عنه يحيى بن معين قال عباس الدورى عن يحيى بن معين قال: قال لى أبو جعفر السويدى:"],[10003,"= من الصحابة. التقريب (٢/ ١٦١)."],[10004,"١٤٤٢ - كنى البخارى (ص ١٨)، كنى الحاكم (١/ ٥٤/ أ)، الجرح (٤/ ٢/ ٣٥٣)"],[10005,"١٤٤٣ - كنى البخارى (ص ١٨)، كنى الحاكم (١/ ٥٤/ أ)، الجرح (٤/ ٢/ ٣٥٣) كنى ابن منده (٦٠/ أ)."],[10006,"(١) مسعدة بن اليسع بن قيس اليشكرى. قال أبو حاتم: ذاهب منكر الحديث لا يشتغل به يكذب على جعفر بن محمد. الجرح (٤/ ١/ ٣٧٠)"],[10007,"١٤٤٤ - كنى الحاكم (١/ ٥٤/ أ)."],[10008,"(٢) هو أبو جبير المدنى، صحابى صغير. مات قبل الحرة. التقريب (١/ ٤٧٢)"],[10009,"١٤٤٥ - كنى الحاكم (١/ ٥٤/ أ)."],[10010,"(٣) الفسوى: بفتح الفاء والسين وفى آخرها واو - هذه النسبة إلى فسا، وهى مدينة من بلاد فارس. انظر اللباب (٢/ ٤٣٢) وقال ياقوت في معجم البلدان (٤/ ٢٦٠ - ٢٦١) فسا: بالفتح والقصر كلمة عجمية وعندهم بسا، بالباء. . وأصلها في كلامهم الشمال من الرياح، مدينة بفارس، انزه مدينة بها فيما قيل. اهـ."],[10011,"(٤) اسحاق بن بشر بن مقاتل الكاهلى. له ترجمة مطولة في اللسان (١/ ٣٥٥)."],[10012,"١٤٤٦ - كنى الحاكم (١/ ٥٤/ أ)، كنى ابن منده (٦٠/ أ). وقال: اسمه محمد"],[10013,"(٥) السّويدى: بضم السين وفتح الواو وسكون الياء المثناة من تحتها وفى آخرها دال مهملة - نسبة إلى سويد. اللباب (٢/ ١٥٦) وقال ابن منده في الكنى \"إنما سمى سويد لأنه رحل إلى سويد بن عبد العزيز البعلبكى."],[10014,"جاء إلى عبد الرزاق بأحاديث كثيرة ليس هى من حديثه فقالوا له: اقرأها علينا ولا تقل فيها حدثنا. فقرأها عليهم (١)."],[10015,"(١) انظر التاريخ ٢/ ٣٦٣ وذكره الحاكم عن الدورى عن ابن معين. انظر مصادر الترجمة."],[10016,"باب أبى الجراح"],[10017,"١٤٤٧ - أبو الجراح مولى أم حبيبة بنت أبى سفيان بن حرب زوج النبى عليه السلام، روى عن أم حبيبة مولاته. روى عنه سالم بن عبد اللَّه بن عمر."],[10018,"١٤٤٨ - أبو الجراح (١) عن جابر بن صبح (٢). روى عنه أبو عاصم الضحاك بن مخلد."],[10019,"١٤٤٧ - تقدمت له ترجمة مطولة في الكتاب الثانى انظر الترجمة (٥٣٨) وقال ابن عبد البر هناك: لا يعرف له أسم على صحة. وقد قيل: اسمه يسار. اهـ."],[10020,"١٤٤٨ - كنى البخارى (ص ٢٠)، كنى مسلم (ص ٢٢٠)، تهذيب الكمال (٣/ ١٥٩٢)، كنى الحاكم (١/ ٦١/ ب)، الجرح (٤/ ٢/ ٣٥٢)، الميزان (٤/ ٥١٠) وقال: لا يعرف، التهذيب (١٢/ ٥٣)، التقريب (٢/ ٤٠٥) وقال: مجهول، من السابعة./ ت."],[10021,"(١) في كنى البخارى، والجرح، وتهذيب الكمال، والميزان، والتهذيب زيادة لفظ \"المهرى\"."],[10022,"(٢) جابر بن صبح. هو أبو بشر الراسبى."],[10023,"باب أبى الجهم"],[10024,"١٤٤٩ - أبو الجهم القوّاس (١) الفارسى من أصحاب أبى هريرة. روى عن أبى هريرة. روى عنه عبد الحميد بن جعفر (٢)."],[10025,"١٤٥٠ - أبو الجهم الايادى. روى عن الزهرى عن أبى سلمة عن أبى هريرة قال: قال رسول اللَّه صلى اللَّه عليه (وسلم) \"أمرؤ القيس (٣) صاحب لواء الشعر إلى النار (٤) \"."],[10026,"١٤٤٩ - كنى مسلم (ص ٢١٨)، كنى الحاكم (١/ ٥٥/ أ)."],[10027,"(١) القواس: بفتح القاف والواو المشددة وبعد الالف سين مهملة. هذه النسبة لمن يعمل القسى. اللباب (٣/ ٦٢)."],[10028,"(٢) هو أبو حفص الأنصارى."],[10029,"١٤٥٠ - كنى البخارى (ص ٢٠)، كنى الحاكم (١/ ٥٥/ أ)، كنى ابن منده (٦٦/ أ)، الجرح (٤/ ٢/ ٣٥٤)، الميزان (٤/ ٥١٢)، اللسان (٧/ ٢٩)، المجروحين (٣/ ١٥٠)، الكامل لابن عدى (٣/ ٢٦٠/ ب) وقال: منكر الحديث."],[10030,"(٣) امرؤ القيس: هو أمرؤ القيس بن حجر بن عمرو الكندى وهو من أهل نجد، من الطبقة الأولى. قال لبيد بن ربيعة أشعر الناس ذو القروح يعنى أمرأ القيس. له ترجمة مطولة في الشعر والشعراء لابن قتيبة (ص ٣٦ - ٥٠)، وانظر معجم الشعراء للمرزبانى (ص ٩)."],[10031,"(٤) الحديث أخرجه البخارى في الكنى، والحاكم في الكنى وابن عدى في الكامل من هذه الطريق به، وزاد البخارى وابن عدى قوله لأنه أول من أحكم الشعر وأخرجه أيضا أحمد (٢/ ٢٢٨) والبزاز كما في كشف الاستار (٢/ ٤٥٢) كلاهما من طريق هشيم عن أبى الجهم، عن الزهرى عن أبى سلمة عن أبى هريرة يرفعه به."],[10032,"وقال البزار: لا نعلمه عن رسول اللَّه -صلى الله عليه وآله وسلم- إلا بهذا الاسناد. وذكر الهيثمى في مجمع الزوائد (٨/ ١١٩) هذا الحديث وعزاه لأحمد والبزار وقال: في اسناده أبو الجهم شيخ هشيم بن بشير ولم اعرفه، وبقية رجاله رجال = روى عنه هشيم. قال أحمد بن حنبل: أبو الجهم الذى روى عنه هشيم مجهول ما تصنع به (١). وقال أبو زرعة: حديثه واه (٢)."],[10033,"١٤٥١ - أبو جهم عن بعض علمائهم. روى عنه الليث بن سعد (٣)."],[10034,"١٤٥٢ - أبو جهم بن صخير عن سالم بن عبد اللَّه بن عمر. روى عنه الوليد بن أبى الوليد. قال أبو زرعة: كان ثقة (٤)."],[10035,"= الصحيح اهـ قلت: وفيه عند أحمد والهيثمى \"أبو الجهيم\" بالتصغير وهو خطأ. وأخرجه الطرانى في الكبير (١٨/ ١٠٠) من حديث فروة بن سعيد بن عفيف بن معدى كرب، عن أبيه، عن جده. وذكره أيضا ابن قتيبة في الشعر والشعراء (ص ٤٦) بهذا اللفظ."],[10036,"(١، ٢) انظر الجرح (٤/ ٢/ ٣٥٤ - ٣٥٥)."],[10037,"١٤٥١ - كنى البخارى (ص ٢٠)، كنى الحاكم (١/ ٥٥/ ب)، كنى ابن منده (٦٦/ أ) وقال: روى الليث عن أبى الجهم مجهول."],[10038,"(٣) زاد البخارى في الكنى \"مرسل\"."],[10039,"١٤٥٢ - كنى الحاكم (١/ ٥٥/ ب)، كنى ابن منده (٦٦/ أ)، الجرح (٤/ ٢/ ٣٥٤)"],[10040,"(٤) الجرح (٤/ ٢/ ٣٥٤)."],[10041,"باب أبى الجعد"],[10042,"١٤٥٣ - أبو الجعد بصرى. روى عنه يزيد بن حميد."],[10043,"١٤٥٤ - أبو الجعد. مولى النعمان بن مقرّن (١) قال: كان نقش (خاتم) (٢) النعمان بن مقرن. روت عنه انيسة أم نافع (٣)."],[10044,"١٤٥٣ - كنى مسلم (ص ٢١٩)، كنى الحاكم (١/ ٥٧/ أ)، كنى ابن منده (٦٦/ ب) وقال: أبو الجعد بصرى حدث عن أبى امامة. روى عنه يزيد بن حميد أبو التياح لا يعرف له اسم. اهـ."],[10045,"١٤٥٤ - كنى الحاكم (١/ ٥٧/ ب)، كنى ابن منده (٦٦/ ب)."],[10046,"(١) صحابى مشهور استشهد بنهاوند سنة أحدى وعشرين. التقريب (٢/ ٣٠٤)."],[10047,"(٢) لم تكن في الأصل. وقد اثبتت عن كنى الحاكم. والسياق يقتضيها."],[10048,"(٣) هكذا في الأصل \"أنيسة أم نافع\" وفى كنى ابن منده \"ابنته أم رافع\"."],[10049,"باب أبى جهضم"],[10050,"١٤٥٥ - أبو جَهضم (١) الهجيمى، سمع أبا نعامة، عن ابن عباس روى عنه يحيى بن بشر، يعد في البصريين."],[10051,"١٤٥٦ - أبو جهضم. روى عنه الوضاح بن عبد المجيد (٢)، يعد في البصريين."],[10052,"١٤٥٧ - أبو جهضم. عن ابن عباس. روى عنه ليث بن أبى سليم."],[10053,"١٤٥٥ - كنى البخارى (ص ٢٠)، كنى الحاكم (١/ ٥٩/ ب)، الجرح (٤/ ٢/ ٣٥٤)، كنى ابن منده (٦٧/ ب)."],[10054,"(١) جهضم: بفتح جيم وضمها وسكون هاء. المغنى (ص ١٨)."],[10055,"١٤٥٦ - كنى البخارى (ص ٢٠)، كنى الحاكم (١/ ٥٩/ ب)، الجرح (٤/ ٢/ ٣٥٤)"],[10056,"(٢) الوضاح بن عبد المجيد: هو أبو الجراح المهرى. تقدم في (٥٣٧)."],[10057,"١٤٥٧ - كنى البخارى (ص ٢٠)، كنى الحاكم (١/ ٥٩/ ب)، كنى ابن منده (٦٧/ ب) وقال: أبو جهضم عن ابن عباس قال: توفى النبى -صلى الله عليه وآله وسلم- وأنا ابن عشر سنين. رواه شريك عن ليث عنه. أراه موسى بن سالم. اهـ."],[10058,"باب أبى الجنيد"],[10059,"١٤٥٨ - أبو الجُنَيْد (١)، كوفى، سكن الرّى، عن جعفر بن أبى المغيرة، روى اسحاق بن سليمان، وجرير بن عبد الحميد. هو عندهم ثقة."],[10060,"١٤٥٩ - أبو الجُنَيد الضرير. روى عن العباس بن الفضل. روى عنه الحسن ابن مُكْرَم (٢)."],[10061,"١٤٥٨ - كنى البخارى (ص ٢١)، كنى الحاكم (١/ ٦٠/ ب)، كنى ابن منده (٦٨/ أ)، الجرح (٤/ ٢/ ٣٥٤) وقال: قال ابن معين: ليس به بأس. وسألت أبى عنه فقال: لا بأس به، محله الصدق."],[10062,"(١) الجنيد: بضم الجيم وفتح النون وآخره دال مهملة. الاكمال (٢/ ١٦١)."],[10063,"١٤٥٩ - كنى الحاكم (١/ ٦٠/ ب)، الجرح (٤/ ٢/ ٣٥٤)، كنى ابن منده (٦٨/ أ)."],[10064,"(٢) الحسن بن مُكْرَم، بضم الميم وسكون الكاف وفتح الراء وتخفيفها، ابن حسان، ذكره ابن ماكولا في الاكمال (٧/ ٢٨٦)، وذكره الخطيب في تاريخ بغداد (٧/ ٤٣٢ - ٤٣٣) وقال: كان ثقة، مات سنة أربع وسبعين ومائتين. اهـ."],[10065,"باب الافراد في الجيم"],[10066,"(وهى الكنى الشتى)"],[10067,"١٤٦٠ - أبو جُبَيرْ (١) الجرموزى. قال: \"رأيت كعب بن سور (٢) يوم الجمل. آخذا بخطام (جمل) (٣) عائشة فقتل يومئذ\" (٤)."],[10068,"١٤٦١ - أبو الجارود. عن جابر بن زيد والحسن بن أبى الحسن. روى عنه"],[10069,"١٤٦٠ - كنى البخارى (ص ١٨)، كنى الحاكم (١/ ٦١/ ب)، الجرح (٤/ ٢/ ٣٥٣)، كنى ابن منده (٦٦/ ب) وقال: أبو جبيرة وقيل: أبو جبير الجرموزى. فذكره."],[10070,"(١) جبير: بضم أوله. مصغرا. المغنى (ص ١٥)."],[10071,"(٢) كعب بن سور، بمهملة مضمومة بن بكر الازدى، قاضى البصرة، قيل أدرك النبى -صلى الله عليه وآله وسلم-. وقتل يوم الجمل. التجريد (٢/ ٣١) تبصير المنتبه (٢/ ٧٩٢)، أخبار القضاة (١/ ٢٧٤ - ٢٨٣)."],[10072,"(٣) ليست في الأصل وهى مثبتة عن مصادر الترجمة. والسياق يقتضيها."],[10073,"(٤) ذكر البسوى في المعرفة والتاريخ (٣/ ٣١٢) قال: لما التقوا امام كعب بن سور ومعه المصحف ينشدهم اللَّه والاسلام، فلم ينشب أن قتل. اهـ. وأخرج وكيع في أخبار القضاة (١/ ٢٨٢) من طريق الزبير بن الحارث عن أبى حبيش الجرموزى قال: رأيت كعب بن سور يومئذ اخذا بخطام الجمل فقال لى: يا أبا حبيش: انا واللَّه كما قالت القائلة: فإنا بنى لا نفر ولا نقاتل. فقتل يومئذ. هكذا جاء في أخبار القضاة \"أبو حبيش\". والظاهر أنه حصل فيه تحريف، والصواب \"أبو جبير\" وقال ابن الاثير في الكامل في التاريخ (٣/ ٢٤٥): وقالت عائشة لما انجلت الوقعة وانهزم الناس لكعب بن سور: خلّ عن الجمل وتقدم بالمصحف فادعهم إليه وناولته مصحفا فاستقبل القوم. . فرموه رشقا واحدا فقتلوه. اهـ."],[10074,"١٤٦١ - كنى البخارى (ص ٢٠)، كنى الحاكم (١/ ٦٠/ أ)، الجرح (٤/ ٢/ ٣٥٥)."],[10075,"عبد الملك بن عمرو العقدى وسلم بن قتيبة."],[10076,"١٤٦٢ - (أبو جندل. عن شريح في الدعاء. روى عنه عبد اللَّه بن شقيق) (١)."],[10077,"١٤٦٣ - أبو الجُلَاس (٢). سمع عليا رضي الله عنه. روى عنه الحارث بن (عبد الرحمن) (٣)."],[10078,"١٤٦٤ - أبو الجماهر. عم معاوية بن صالح. روى عنه معاوية بن صالح قوله."],[10079,"١٤٦٥ - أبو جَرْوا (٤) المازنى. سمع على بن أبى طالب والزبير بن العوام."],[10080,"١٤٦٢ - كنى الحاكم (١/ ٦٤/ أ)، كنى ابن منده (٦٨/ أ)."],[10081,"(١) الحقت هذه الترجمة بكاملها في هامش الأصل. كتب بعدها \"صح أصل\"."],[10082,"١٤٦٣ - كنى البخارى (ص ٢١)، كنى مسلم (ص ٢٢٥)، كنى الحاكم (١/ ١/ ٦٤) تهذيب الكمال (٣/ ١٥٩٥)، كنى ابن منده (٦٨/ أ)، التهذيب (١٢/ ٦٣)، التقريب (٢/ ٤٠٨)."],[10083,"(٢) الجلاس: بضم أوله. الخلاصة (ص ٤٤٧)."],[10084,"(٣) في الأصل \"عثمان\" وفى مصادر الترجمة \"عبد الرحمن\" وفى تهذيب الكمال والتهذيب أبو هند الحارث بن عبد الرحمن الهمدانى وهو الصواب. فقد ذكر ابن حجر في التهذيب (١٢/ ٢٦٨): أبو هند الهمدانى الدالانى الكوفى. اسمه الحارث بن عبد الرحمن روى عن أبى الجنبى وأبى الجلاس. . الخ. . والحارث بن عبد الرحمن هذا مقبول، من السابعة. كما في التقريب (٢/ ٤٨٤)."],[10085,"١٤٦٤ - كنى البخارى (ص ٢١)، كنى الحاكم (١/ ٦٤/ ب)، الجرح (٤/ ٢/ ٣٥٥)، كنى ابن منده (٧٠/ ب)."],[10086,"١٤٦٥ - كنى البخارى (ص ٢١)، كنى الحاكم (١/ ٦٦/ ب)، كنى ابن منده (٦٩/ أ)، الجرح (٤/ ٢/ ٣٥٦)، الميزان (٤/ ٥١٠)، التهذيب (١٢/ ٥٤)، التقريب (٢/ ٤٠٥) وقال: مقبول، من الثالثة./ عس."],[10087,"(٤) جَرْو بفتح الجيم وسكون الراء. كما في التقريب."],[10088,"روى عنه عبد الملك بن مسلم (١)."],[10089,"١٤٦٦ - أبو الجارية العبدى، روى عن أبى ذر الغفارى. روى عنه عبد الرحمن بن مسعود (٢). كوفى."],[10090,"١٤٦٧ - أبو الجارية عن شعبة بن الحجاج. روى عنه امية بن خالد (٣) بصرى."],[10091,"١٤٦٨ - أبو الجلوا عن ابن عمر. ويقال: أبو الجلو. حديثه عند وكيع، عن سفيان عن يحيى بن عروة المرادى (٤) عنه، وقد حدثنا خلف بن قاسم، نا خلف ابن قاسم نا ابن المفسّر (٥) نا أحمد بن على بن سعيد (٦) نا يحيى بن معين نا وكيع عن سفيان عن يحيى بن هانئ عن أبى الجلوا. قال: سألت ابن عمر عن الديوان فقال: \"خذ فإذا رأيت ما يكره فاختنس\" (٧)."],[10092,"(١) عبد الملك بن مسلم الرقاشى: لين الحديث، من السابعة. التقريب (١/ ٥٢٣)."],[10093,"١٤٦٦ - كنى الحاكم (١/ ٦٦/ ب)."],[10094,"(٢) عبد الرحمن بن مسعود بن نِيَار، بكسر النون وبالتحتانية الأنصارى، المدنى، مقبول، من الرابعة. التقريب (١/ ٤٩٧)."],[10095,"١٤٦٧ - كنى الحاكم (١/ ٦٦/ ب)، كنى ابن منده (٧٠/ أ)."],[10096,"(٣) أمية بن خالد بن الاسود القيسى، صدوق، من التاسعة. التقريب (١/ ٨٣)."],[10097,"١٤٦٨ - كنى البخارى (ص ٢١)، كنى الحاكم (١/ ٦٦/ ب)، الجرح (٤/ ٢/ ٣٥٥)، كنى ابن منده (٦٩/ ب)."],[10098,"(٤) يحيى بن عروة المرادى: هو يحيى بن هانئ بن عروة المرادى، أبو داود كوفى ثقة، من الخامسة، وروايته عن ابن مسعود مرسلة. انظر التقريب (٢/ ٣٥٩)."],[10099,"(٥) ابن المفسر: هو أبو أحمد عبد اللَّه بن محمد بن ناصح بن شجاع. انظر بغية الملتمس (ص ٢٨٦) ترجمة خلف بن قاسم بن سهل."],[10100,"(٦) أحمد بن على بن سعيد بن إبراهيم المروزى، أبو بكر القاضى، ثقة حافظ، من الثانية عشرة. التقريب (١/ ٢٢)."],[10101,"(٧) الأثر أخرجه أبو أحمد الحاكم في الكنى (١/ ٦٦/ ب)."],[10102,"١٤٦٩ - أبو جَبَلة (١). عن محمد بن شهاب الزهرى. روى عنه معاوية بن صالح."],[10103,"١٤٧٠ - أبو جَعونه (٢) عن (هشام) (٣) الأوقص عن ابن عمر. شامى. روى عنه يزيد بن عبد اللَّه الجهنى (٤)."],[10104,"١٤٧١ - أبو الجُوْدى (٥)، عن أبى ذر، روى عنه عبيد اللَّه بن العيزار، بصرى، وقد قيل: انه الحارث بن عمير (٦)."],[10105,"١٤٧٢ - أبو الجَنُوب (٧) الاسدى. سمع مؤذن مسجد بنى كاهل. روى"],[10106,"١٤٦٩ - كنى البخارى (ص ٢١)، كنى الحاكم (١/ ٦٦/ ب)، الجرح (٤/ ٢/ ٣٥٥)، كنى ابن منده (٦٩/ ب)."],[10107,"(١) جبله: بجيم وموحدة مفتوحتين. المغنى (ص ١٥)."],[10108,"١٤٧٠ - كنى الحاكم (١/ ٦٦/ ب)، كنى ابن منده (٧٠/ أ) وقال: مجهول."],[10109,"(٢) جعونة: بمفتوحة وسكون عين مهملة وبنون، المغنى (ص ١٦)."],[10110,"(٣) هكذا في الأصل \"هشام\" وكذا في كنى ابن منده. وفى كنى الحاكم \"هاشم\" وترجم له ابن حجر في اللسان (٦/ ١٨٣) فقال: هاشم بن الأوقص قال البخارى: غير ثقة. . الخ. وقال ابن حجر أيضا في ترجمة يزيد بن عبد اللَّه الجهنى في اللسان (٦/ ٢٩٠) \"يزيد بن عبد اللَّه الجهنى\" عن هاشم الاوقص. فالظاهر أنه \"هاشم\". واللَّه أعلم."],[10111,"(٤) يزيد بن عبد اللَّه الجهنى: قال ابن حجر: لا يصح خبره. اللسان (٦/ ٢٩٠)."],[10112,"١٤٧١ - كنى الحاكم (١/ ٦٦/ ب)، التاريخ الصغير (ص ١٤٧)، التقريب (٢/ ٤٠٨)، كنى ابن منده (٦٩/ ب)."],[10113,"(٥) الجودى: بضم الجيم وسكون الواو. كما في التقريب (٢/ ٤٠٨)."],[10114,"(٦) الحارث بن عمير: هو أبو الجودى، الاسدى الشامى، نزيل واسط، مشهور بكنيته، ثقة، من السادسة. وروايته عن أبى ذر مرسلة./ د. التقريب (٢/ ٤٠٨) وانظر ترجمته أيضا في تهذيب الكمال (٣/ ١٥٩٥)."],[10115,"١٤٧٢ - كنى البخارى (ص ٢٠)، كنى ابن منده (٦٩/ ب) وقال: اسمه عقبة بن علقمة. كنى الحاكم (١/ ٦٧/ أ)."],[10116,"(٧) الجنوب: بمفتوحة وضم نون، وبموحدة. المغنى (ص ١٧)."],[10117,"عنه حسين بن ميمون (١) وعيسى بن قرطاس (٢)."],[10118,"١٤٧٣ - أبو الجبر بن تميم بن حذلم. روى عن أبيه تميم بن حذلم. روى عنه أبو اسحاق الهمدانى ومغيرة."],[10119,"١٤٧٤ - أبو جابر المؤذن. شيخ ليس به بأس."],[10120,"(١) حسين بن ميمون، كوفى، لين الحديث، من السابعة. التقريب (١/ ١٨٠)."],[10121,"(٢) عيسى بن قرطاس، الكوفى، متروك، وقد كذبه السّاجى، من السادسة. التقريب (٢/ ١٠١)."],[10122,"١٤٧٣ - كنى البخارى (ص ٤٥)، الجرح (٤/ ٢/ ٣٥٥)، الاكمال (٢/ ١٦)، وقال: يقال: اسمه محمد. ويقال: عبد الرحمن، وهو كوفى ضبى."],[10123,"١٤٧٤ - الجرح (٤/ ٢/ ٣٥٦)."],[10124,"حرف الحاء"],[10125,"باب أبى الحسن"],[10126,"١٤٧٥ - أبو الحسن الهاشمى. مولى عبد اللَّه (١) بن نوفل بن الحارث بن عبد المطلب بن هاشم. روى عنه ابن شهاب الزهرى. ذكره بعلم وصلاح."],[10127,"روى عبد الرزاق عن معمر عن الزهرى. قال: حدثنى أبو الحسن مولى عبد اللَّه بن نوفل، وكان من أهل العلم والصلاح (٢). اتفقوا على أنه ثقة (٣)."],[10128,"١٤٧٦ - أبو الحسن مولى أم قيس بنت محصن، عن أم قيس بنت محصن روى عنه يزيد بن أبى حبيب."],[10129,"١٤٧٧ - أبو الحسن، مولى أبى أسيد، عن مكحول. روى عنه محمد بن حمير."],[10130,"١٤٧٨ - أبو الحسن الجزرى."],[10131,"١٤٧٥ - كنى مسلم (ص ٢٧٩)، الجرح (٤/ ٢/ ٣٥٦)، كنى الحاكم (١/ ٨٩/ ب) الميزان (٤/ ٥١٤)، تهذيب الكمال (٣/ ١٥٩٨)، التهذيب (١٢/ ٧٣)، التقريب (٢/ ٤١٢) وقال: مقبول، من الرابعة./ م. . د. ق"],[10132,"(١) أدرك النبى -صلى الله عليه وآله وسلم- وقتل زمن معاوية. التجريد (١/ ٣٣٨)."],[10133,"(٢) ذكر هذا الخبر أبو أحمد الحاكم في الكنى والمزى في تهذيب الكمال، وابن حجر في التهذيب. انظر مصادر الترجمة."],[10134,"(٣) يذكر ابن حجر: التهذيب (١٢/ ٧٤) \"قال ابن عبد البر: اتفقوا على انه ثقة."],[10135,"١٤٧٦ - كنى مسلم (ص ٢٧٨)، كنى الحاكم (١/ ٨٩/ ب)، الميزان (٤/ ٥١٥)، التهذيب (١٢/ ٧٤)، كنى ابن منده (٧٦/ أ)."],[10136,"١٤٧٧ - كنى الحاكم (١/ ٨٩/ ب)، كنى ابن منده (٧٦/ أ)."],[10137,"١٤٧٨ - كنى مسلم (ص ٢٧٨)، كنى الحاكم (١/ ٨٩/ ب)، الميزان (٤/ ٥١٥) = عن عمرو (١) بن مرة صاحب النبى عليه السلام. روى عنه على بن الحكم."],[10138,"١٤٧٩ - أبو الحسن عن عبد اللَّه بن عبد الرحمن عن أبيه عن (أنيس) (٢) الأنصارى. قال: \"صليت خلف النبى عليه السلام وعلىَّ ثوب خلق فلما صلى رسول اللَّه (صلى الله عليه وآله وسلم) كسانى ثوبا جديدا (٣). روى عنه سليمان بن كثير (٤)."],[10139,"١٤٨٠ - أبو الحسن الكندى. سمع عثمان بن سعيد. روى عنه عبد الوهاب بن نَجْدة (٥)."],[10140,"١٤٨١ - أبو الحسن التغلبى بصرى عن محمد بن واسع (٦)، روى عنه أبو داود الطيالسى."],[10141,"= التهذيب (١٢/ ٧٣)، التقريب (٢/ ٤١١) وقال: مجهول، من السادسة، وأخطأ من سماه عبد الحميد./ د. ت."],[10142,"(١) عمرو بن مرة بن عبس الجهنى، صاحبى مات بالشام في خلافة معاوية. التقريب (٢/ ٧٩)، التجريد (١/ ٤١٦)."],[10143,"١٤٧٩ - كنى الحاكم (١/ ٨٩/ ب)، كنى ابن منده (٧٦/ أ)."],[10144,"(٢) هكذا في الأصل \"أنيس\" وفى كنى الحاكم \"عبد اللَّه بن أنيس الأنصارى وذكر حديثه\" الخ. وعبد اللَّه بن أنيس صحابى. انظر ترجمته في الإصابة (٢/ ٢٧٨)، التجريد (١/ ٣٩٨)، التهذيب (٥/ ١٤٩)، التقريب (١/ ٤٠٢)."],[10145,"(٣) الحديث أخرجه الحاكم أبو أحمد في الكنى (١/ ٨٩/ ب) من طريق أبى الحسن عن عبد اللَّه بن عبد الرحمن عن أبيه عن عبد اللَّه بن أنيس الأنصارى به."],[10146,"(٤) سليمان بن كثير، لا بأس به في غير الزهرى، من السابعة. التقريب (١/ ٣٢٩)."],[10147,"١٤٨٠ - كنى الحاكم (١/ ٨٩/ ب)."],[10148,"(٥) عبد الوهاب بن نجدة، بفتح النون وسكون الجيم، الحوطى بفتح المهملة بعدها واو ساكنة، ثقة، من العاشر. التقريب (١/ ٥٢٩)."],[10149,"١٤٨١ - كنى الحاكم (١/ ٨٩/ ب)، كنى ابن منده (٧٦/ ب)."],[10150,"(٦) محمد بن واسع بن جابر بن الاخنس، الازدى، ثقة عابد، كثير المناقب من الخامسة. التقريب (٢/ ٣١٥)."],[10151,"١٤٨٢ - أبو الحسن. ويقال: أبو الحسين عن الحكم بن عبد اللَّه الايلى (١). روى عنه سليمان بن بلال (٢)."],[10152,"١٤٨٣ - أبو الحسن. روى عن أبى أسماء، قال: \"قال لى أبو هريرة: ممن أنت؟ قلت من أهل الشام. ذكره البخارى (٣). قال: قال حدثنى ابن إسماعيل (٤) عن (حماد) (٥) عن على بن الحكم عن أبى الحسن واظنه أبو الحسن الجزرى (٦) الذى قدمنا ذكره لرواية على بن الحكم عنه."],[10153,"١٤٨٤ - أبو الحسن العسقلانى. عن أبى جعفر محمد بن يزيد بن"],[10154,"١٤٨٢ - كنى الحاكم (١/ ٨٩/ ب)."],[10155,"(١) الحكم بن عبد اللَّه الايلى. ضعيف، وله ترجمة مطولة في اللسان (٢/ ٣٣٢)."],[10156,"(٢) سليمان بن بلال التيمى، ثقة، من الثامنة. التقريب (١/ ٣٢٢)."],[10157,"١٤٨٣ - الجرح (٤/ ٢/ ٣٥٦)، كنى الحاكم (١/ ٩٠/ أ)."],[10158,"(٣) انظر كنى البخارى (ص ٢١)."],[10159,"(٤) هو موسى بن إسماعيل التبوذكى."],[10160,"(٥) هكذا جاء هنا \"حماد\" مطلقا. وموسى بن إسماعيل روى عن الحمادين حماد بن زيد وحماد بن سلمة والحمادان أيضا رويا عن على بن الحكم. انظر تهذيب الكمال (٣/ ١٣٨٢) في ترجمة موسى بن إسماعيل التبوذكى شيخ البخارى، والتهذيب (٧/ ٣١١) في ترجمة على بن الحكم. لكن جاء في تهذيب الكمال في ترجمة موسى بن إسماعيل قيل: انه روى عن حماد ابن زيد حديثا واحدا. قلت: ومن هنا يمكن أن يكون حماد هذا المذكور هو حماد بن سلمة. واللَّه أعلم."],[10161,"(٦) انظر ترجمة أبى الحسن الجزرى في (١٤٧٨). قلت: وقال الحاكم أيضا بعد ان ذكر أبا الحسن الجزرى وأبا الحسن هذا: لا أدرى هما اثنان أم واحد. اهـ."],[10162,"١٤٨٤ - كنى البخارى (ص ٢٢)، الجرح (٤/ ٢/ ٣٥٦)، كنى ابن منده (٧٦/ ب)، كنى الحاكم (١/ ٩٠/ أ)، الميزان (٤/ ٥١٥)، تهذيب الكمال (٣/ ١٥٩٨)، التهذيب (١٢/ ٧٣)، التقريب (٢/ ٤١٢)، وقال: مجهول، من السابعة./ د. ت."],[10163,"ركانه (١) روى عنه محمد بن ربيعة الكلابى."],[10164,"١٤٨٥ - أبو الحسن. عن حنظلة (بن) (٢) أبى سفيان الجمحى (٣) روى عنه الحسن بن عياش (٤)."],[10165,"١٤٨٦ - أبو الحسن التميمى، عن عبيد اللَّه بن عمر، عن نافع. روى عنه يزيد بن هارون. قيل له (٥): على بن عاصم. قال: لا هذا ثقة. قاله البخارى (٦)."],[10166,"١٤٨٧ - أبو الحسن. شيخ من أهل البصرة عن ابن عون. روى عنه يحيى ابن أيوب."],[10167,"١٤٨٨ - أبو الحسن البراد مولى تميم الدارى مدنى، روى عن على رضي الله عنه قال: لا يصلح الحيوان بالحيوان نسيئة (٧) روى عنه يزيد بن قسيط."],[10168,"(١) محمد بن يزيد بن ركانة، عن أبيه عن جده قال البخارى: اسناده مجهول من السادسة. التقريب (٢/ ٢١٩)."],[10169,"١٤٨٥ - كنى البخارى (ص ٢٢)، الجرح (٤/ ٢/ ٣٥٧)، كنى الحاكم (١/ ٩٠/ أ)."],[10170,"(٢) لم تكن في الأصل. وهى مثبته في كنى البخارى والجرح، كنى الحاكم. وكذا في التقريب كما سيأتى في ترجمة حنظلة بن أبى سفيان."],[10171,"(٣) حنظلة بن أبى سفيان بن عبد الرحمن بن صفوان بن أمية الجمحى المكى، ثقة حجة، من السادسة. التقريب (١/ ٢٠٦)."],[10172,"(٤) الحسن بن عياش، بتحتانية ثم معجمة، ابن سالم الاسدى صدوق، من الثامنة. التقريب (١/ ١٦٩)."],[10173,"١٤٨٦ - كنى الحاكم (١/ ٩٠/ أ)، كنى ابن منده (٧٦/ ب)."],[10174,"(٥) في كنى الحاكم \"قيل ليزيد بن هارون: هو على بن عاصم؟ قال: لا. ثقة. سمع عبيد اللَّه عن نافع. قاله محمد بن إسماعيل."],[10175,"(٦) لم أقف عليه في مطبوعة الكنى، والتاريخ الكبير، والتاريخ الصغير والضعفاء الصغير للبخارى."],[10176,"١٤٨٧ - كنى الحاكم (١/ ٩٠/ أ)."],[10177,"١٤٨٨ - الثقات (٥/ ٥٧٣)، الجرح (٤/ ٢/ ٣٥٦)، كنى البخارى (ص ٢٢)، كنى الحاكم (١/ ٩٠/ أ)."],[10178,"(٧) الحديث أخرجه ابن حبان في الثقات (٥/ ٥٧٣) والبخارى في الكنى (ص ="],[10179,". . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . ."],[10180,"= ٢٢)، والحاكم في الكنى (١/ ٩٠/ أ)، وابن أبى شيبة (٦/ ١١٦) من طريق يزيد بن عبد اللَّه بن قسيط عن أبى الحسن البراد، عن على بن أبى طالب رضي الله عنه قال \"لا يصلح الحيوان بالحيوان نسيئة، وعند ابن أبى شيبة لفظ \"لا يصلح الحيوان بالحيوانين ولا الشاة بالشاتين إلا يدا بيد\". وأخرجه أيضا ابن التركمانى في الجوهر النقى (٦/ ٢٢) من طريق يزيد بن عبد اللَّه بن قسيط عن أبى الحسن البراد عن على بن أبى طالب به كما عند ابن أبى شيبة. وعزاه له."],[10181,"وأخرجه عبد الرزاق من طريق ابن قسيط عن ابن المسيب عن على أنه كره بعيرا ببعيرين نسيئة، وعند ابن أبى شيبة (٦/ ١١٣) عن يزيد بن عبد اللَّه ابن قسيط قال: باع على بعيرا ببعيرين فقال له الذى اشتراه منه سلم لى بعيرى حتى آتيك ببعيريك. فقال على: لا تفارق يدى خطامه حتى تأتى ببعيرىّ."],[10182,"ويشهد لهذا الحديث حديث سمرة بن جندب برواية الحسن عنه \"أن رسول اللَّه -صلى الله عليه وآله وسلم- نهى عن بيع الحيوات بالحيوان نسيئة\" أخرجه أبو دادود \"البيوع\" باب الحيوان بالحيوان نسيئة (٣/ ٢٥٠)، والترمذى، وقال: حسن صحيح \"البيوع\" باب كراهية بيع الحيوان بالحيوان نسيئة (٤/ ٤٣٦)، والنسائى \"البيوع\" باب الحيوان بالحيوان نسيئة (٧/ ٢٩٢) وابن ماجة \"التجارات\" باب الحيوان بالحيوان نسيئة (٢/ ٧٦٣)، والدارمى (٢/ ٢٥٤) وقال: ان الحسن نسى هذا الحديث ولم يقل: جعفر. ثم ان الحسن نسى هذا الحديث. اهـ. قلت وجعفر هذا هو ابن عون أحد رجال الاسناد عنده وعند الطحاوى في شرح معانى الآثار (٤/ ٦٠)، وأخرجه أيضا البيهقى (٥/ ٢٨٨) وقال أن أكثر الحفاظ لا يثبتون سماع الحسن البصرى من سمرة في غير حديث العقيقة. اهـ. وقال الحافظ ابن حجر في فتح البارى (٤/ ٤١٩): رجال حديث سمرة ثقات إلا انه اختلف في سماع الحسن من سمرة."],[10183,"ويشهد له أيضا حديث ابن عباس رضي الله عنهما يرفعه \"أن النبى -صلى الله عليه وآله وسلم- = ١٤٨٩ - أبو الحسن اللحام. روى عن أبى قلابة. روى عنه شعبة."],[10184,"١٤٩٠ - أبو الحسن الاسدى. روى عن مسعود بن سليمان (١)، عن حبيب ابن (أبى) (٢) ثابت. روى عنه أبو كريب."],[10185,"= نهى عن بيع الحيوان بالحيوان نسيئة\" أخرجه ابن حبان كما في موارد الظمآن (ص ٢٧٢)، والطحاوى في شرح معانى الآثار (٤/ ٦٠) والطبرانى في الكبير والاوسط كما في مجمع الزوائد (٤/ ١٠٥) والبيهقى (٥/ ٢٢٨) وقال الهيثمى: رجال الطبرانى رجال الصحيح."],[10186,"وحديث جابر بن عبد اللَّه رضي الله عنهما قال: قال رسول اللَّه -صلى الله عليه وآله وسلم- \"الحيوان اثنان بواحد لا يصلح نسيئا ولا بأس به يدا بيد\" أخرجه الترمذى (٤/ ٤٣٧ - ٤٣٨) والطحاوى (٤/ ٦٠) وقال الترمذى: هذا حديث حسن صحيح. اهـ. قلت: قال الحافظ في الفتح (٤/ ٤١٩): اسناده لين."],[10187,"وحديث ابن عمر رضي الله عنهما \"ان النبى -صلى الله عليه وآله وسلم- نهى عن بيع الحيوان بالحيوان نسيئة\" أخرجه الطحاوى (٤/ ٦٠)، والطبرانى في الكبير كما في مجمع الزوائد (٤/ ١٠٥). وقال الهيثمى: فيه محمد بن دينار وثقه ابن حبان وغيره وضعفه ابن معين. اهـ."],[10188,"قلت: ومذهب الجمهور على خلاف هذا، وهو جواز بيع الحيوان بالحيوان نسيئة، وقد ورد من فعل جماعة من الصحابة رضوان اللَّه عليهم كابن عمر وابن عباس ورافع وغيرهم في الصحيح. انظر صحيح البخارى (٤/ ٤١٩) وقد ذكر الحافظ ابن حجر في الفتح أدلة الجمهور وذكر في هذه المسألة تفصيلات شافيه. واللَّه أعلم."],[10189,"١٤٨٩ - الجرح (٤/ ٢/ ٣٥٦) وقال: سألت أبى عنه فقال: لا يسمى، هو شيخ لشعبة."],[10190,"١٤٩٠ - الجرح (٤/ ٢/ ٣٥٧)، الميزان (٤/ ٥١٤) وقال: مجهول، اللسان (٧/ ٣٣)."],[10191,"(١) قال ابن حجر في اللسان (٦/ ٢٦): \"مسعود بن سليمان عن حبيب بن أبى ثابت مجهول\"."],[10192,"(٢) الحق في الهامش. كتب عنده \"صح\"."],[10193,"١٤٩١ - أبو الحسن (روى عنه شعبة) (١) روى عن طاوس. قال أبو زرعة: اللحام وأبو الحسن هذا شيخان لشعبة لا يسميان (٢)."],[10194,"١٤٩٢ - أبو الحسن، سمع أنس بن مالك عن النبى عليه السلام قال: \"من شرب الخمر حرمت عليه الصلاة أربعين ليلة\" (٣) وذكر الحديث. روى عنه أبو معشر"],[10195,"١٤٩١ - الجرح (٤/ ٢/ ٣٥٧)، الميزان (٤/ ٥١٤)، تهذيب الكمال (٣/ ١٥٩٨)، التهذيب (١٢/ ٧٤)، التقريب (٢/ ٤١٢) وقال: أبو الحسن شيخ لشعبة قال أبو حاتم مجهول، من السادسة. . ./ س."],[10196,"(١) هكذا في الأصل، وقد ضبب عليه. وقد جرت عادة المؤلف في هذا الكتاب أن يذكر شيوخ صاحب الترجمة أولا ثم يتبعهم بذكر تلاميذه الراوين عنه."],[10197,"(٢) هكذا هنا قال: \"قال أبو زرعة. . \" الخ. والذى في الجرح قال ابن أبى حاتم: \"سألت أبى عنه فقال: لا يسمى، وهو مجهول. وكذا ذكره الذهبى، والمزى وابن حجر في التهذيب والتقريب عن أبى حاتم. واللَّه أعلم. وقد تقدم في ترجمة اللحام قول لأبى حاتم مثل هذا. وانظر الترجمة (١٤٨٩)."],[10198,"١٤٩٢ - الجرح (٤/ ٢/ ٣٥٧)، كنى ابن منده (٧٦/ أ)"],[10199,"(٣) الحديث ذكره ابن أبى حاتم في الجرح (٤/ ٢/ ٣٥٧) كما هنا ولم أقف عليه في الكتب المعتمدة في التخريج من حديث أنس ولكن للحديث شواهد منها ما أخرجه الترمذى \"الأشربة\" باب ما جاء في شارب الخمر (٥/ ٦٠٠) وقال: حديث حسن. من حديث عبد اللَّه بن عمر رضي الله عنهما برواية عبد اللَّه بن عبيد بن عمير عن أبيه عنه. وأخرجه أيضا عبد الرزاق (٩/ ٢٣٥) من طريق معمر عن عطاء بن السائب عن عبد اللَّه بن عبيد بن عمير عن عبد اللَّه بن عمر. ومن طريق عبد اللَّه أخرجه أحمد في المسند (٢/ ٣٥). وفيه عندهم: قال رسول اللَّه -صلى الله عليه وآله وسلم- \"من شرب الخمر لم تقبل صلاته أربعين ليلة\" الحديث. وأخرجه عبد الرزاق أيضا موقوفا من طريق ابن جريح قال: سمعت عبد العزيز بن عبد اللَّه يحدث عن عبد اللَّه بن عمر انه قال: \"من شرب الخمر لم يقبل اللَّه منه صلاة أربعين صباحا فان مات في الاربعين دخل النار ولم ينظر اللَّه إليه\". وأخرجه النسائى أيضا \"الأشربة\" باب ذكر الآثام المتولدة عن شرب الخمر. . \" (٨/ ٣١٦) من طريق مجاهد عن ابن عمر بنحو لفظه من حديث ابن جريح عند عبد الرزاق. ="],[10200,"البراء يوسف بن يزيد."],[10201,"= وما أخرجه النسائى \"الأشربة\" باب ذكر الرواية المبينة عن صلوات شارب الخمر (٨/ ٣١٤) وابن ماجه \"الأشربة\" باب من شرب الخمر لم تقبل له صلاة (٢/ ١١٢٠) والدارقطنى (٤/ ٢٤٧)، والحاكم (٤/ ١٤٥ - ١٤٦)، والدارمى (٢/ ١١١)، وابن حبان كما في موارد الظمآن (ص ٣٣٤) كلهم أخرجوه من حديث عبد اللَّه بن عمرو بن العاص رضي الله عنهما يرفعه وفيه لفظ \"لا يشرب الخمر رجل من أمتى فيقبل اللَّه منه صلاة أربعين يوما\" هذا اللفظ للنسائى والباقون بنحوه وقال الحاكم: هذا حديث صحيح الاسناد ولم يخرجاه، ووافقه الذهبى وأخرجه ابن أبى شيبة (٨/ ٢٠٠) عن ابن عمرو موقوفا وذلك انه سئل عن شارب الخمر وقال: \"لا تقبل له صلاة أربعين يوما وأربعين ليلة\" وعزاه الهيثمى في مجمع الزوائد (٥/ ٧٠) إلى البزار من حديث ابن عمرو وقال الهيثمى: فيه يونس بن خباب وهو ضعيف. وما أخرجه أبو داود \"الأشربة\" باب النهى عن المسكر من حديث ابن عباس رضي الله عنهما يرفعه بنحوه وفيه \"من شرب مسكرا نجست صلاته أربعين صباحا\"."],[10202,"باب أبى الحكم"],[10203,"١٤٩٣ - أبو الحكم. مولى عبد اللَّه بن عمرو. سمع عبد اللَّه بن عمرو قال: \"لا تعجلوا بالعصر فتكون من النهار ولا تمسوا بها فتكون من الليل\" (١). رواه عمرو ابن الحارث عن بكر بن سوادة عنه."],[10204,"١٤٩٤ - أبو الحكم الليثى. مولى الليثيين عن أبى هريرة. روى عنه محمد ابن عمرو البجلى."],[10205,"١٤٩٥ - أبو الحكم البجلى عن أبى هريرة. روى عنه محمد بن قيس (٢)."],[10206,"١٤٩٦ - أبو الحكم. عن البراء بن عازب عن النبى عليه السلام"],[10207,"١٤٩٣ - كنى البخارى (ص ٢٢)، الثقات (٥/ ٥٦٢)، الجرح (٤/ ٢/ ٣٥٧) كنى ابن منده (٩٠/ أ) وقال: عداده في أهل مصر."],[10208,"(١) الخبر أخرجه البخارى في الكنى (ص ٢٢) وابن أبى حاتم في الجرح (٤/ ٢/ ٥٧) من طريق عمرو بن الحارث عن بكر بن سوادة عن أبى الحكم عن عبد اللَّه بن عمرو به."],[10209,"١٤٩٤ - كنى البخارى (ص ٢٣)، كنى ابن منده (٩٠/ أ)، كنى الحاكم (١/ ١٠١/ أ)، الجرح (٤/ ٢/ ٣٥٧)، الميزان (٤/ ٥١٦)، التهذيب (١٢/ ٧٧)، التقريب (٢/ ٤١٣) وقال: مقبول. من الثالثة./ س. ق."],[10210,"١٤٩٥ - كنى الحاكم (١/ ١٠١/ أ)، التهذيب (١٢/ ٧٧)، التقريب (٢/ ٤١٣) وقال ابن حجر: مستور، من الثالثة./ ت."],[10211,"(٢) محمد بن قيس النخعى: له ترجمة في اللسان (٥/ ٣٤٩)."],[10212,"١٤٩٦ - كنى البخارى (ص ٢٢)، كنى ابن منده (٩٠/ ب)، الجرح (٤/ ٢/ ٣٥٧) تهذيب الكمال (٣/ ١٥٩٩) وقال: أبو الحكم العنزى زيد بن أبى الشعثاء عن البراء بن عازب. . في المصافحة روى عنه أبو بلج الفزارى. وذكره أيضا في الأسماء في زيد (١٠/ ٤٥٤) وذكره المزى أيضا في تحفة الاشراف (٢/ ٤٦٨) وذكر حديثه. التهذيب (٣/ ٤١٦) وذكر أيضا حديثه في فضل المصافحة عن البراء."],[10213,"في المصافحة (١)."],[10214,"١٤٩٧ - أبو الحكم التنوخى. روى عن أنس بن مالك قال: خدمت النبى عليه السلام سبع سنين (٢). روى عنه معاوية بن صالح."],[10215,"(١) الحديث أخرجه أبو داود \"الأدب\" باب في المصافحة (٤/ ٣٥٤) والبخارى في الكنى (ص ٢٢) من طريق أبى بلج عن زيد بن أبى الحكم العنزى عن البراء بن عازب قال: قال رسول اللَّه -صلى الله عليه وآله وسلم- \"إذا التقى المسلمان، فتصافحا وحمدا اللَّه عز وجل واستغفراه غفر لهما\" اللفظ لأبى داود. وقال المزى في تحفة الاشراف (١/ ٤٥٤) في ترجمة زيد بن أبى الشعثاء العنزى أبى الحكم: وقع لنا حديثه عاليا. . ثم ساق الحديث من طريق أبى بلج عن زيد أبى الحكم عن البراء بن عازب فذكره مرفوعا به."],[10216,"وأخرجه أبو داود (٤/ ٣٥٤) والترمذى \"الاستئذان\" باب ما جاء في المصافحة (٧/ ٥١٧ - ٥١٨)، وابن ماجه \"الأدب\" باب المصافحة (٢/ ١٢٢٠) وأحمد (٤/ ٢٨٩) من طريق أبى خالد الاحمر وعبد اللَّه بن نمير عند أبى داود وابن ماجه، وعند الترمذى، وأحمد عن ابن نمير فقط، عن الأجلح عن أبى اسحاق، عن البراء بن عازب قال: قال رسول اللَّه -صلى الله عليه وآله وسلم-: فذكره بنحوه: وقال الترمذى: هذا حديث حسن غريب من حديث أبى اسحاق، عن البراء، ويروى هذا الحديث من غير وجه عن البراء. اهـ."],[10217,"وأخرج أحمد (٤/ ٢٨٩) الحديث من طريق ابن نمير، انا مالك عن أبى داود قال: لقيت البراء بن عازب فسلم على وأخذ بيدى وضحك في وجهى قال: تدرى لم فعلت هذا بك؟ قال: قلت: لا أدرى ولكن لا أراك فعلته إلا لخير. قال: انه لقينى رسول اللَّه -صلى الله عليه وآله وسلم- ففعل بى مثل الذى فعلت بك، فسألنى فقلت: مثل الذى قلت لى فقال: \"ما من مسلمين. . \" فذكره."],[10218,"والحديث ذكره السيوطى في الجامع الصغير (٢/ ١٥٣) وفى الجامع الكبير (١/ ٧٢٩) ورمز لحسنه وعزاه لأبى داود والترمذى وابن ماجه وأحمد، وإلى الضياء المقدسى في الجنان."],[10219,"١٤٩٧ - كنى البخارى (ص ٢٣)، الجرح (٤/ ٢/ ٣٥٨)، كنى ابن منده (٩٠/ أ)"],[10220,"(٢) الحديث أخرجه البخارى في الكنى (ص ٢٣)، وابن أبى حاتم في الجرح ="],[10221,"١٤٩٨ - أبو الحكم. مولى عثمان بن أبى العاص (١). روى (عن) (٢) عثمان ابن أبى العاص عن النبى عليه السلام: \"لا يدخل الجنة ولد زنا\" (٣) روى عنه"],[10222,"= (٤/ ٢/ ٣٥٨) من طريق معاوية بن صالح عن أبى الحكم التنوخى عن أنس به."],[10223,"وأخرجه أيضا البخارى \"الوصايا\" باب استخدام اليتيم في السفر والحضر إذا كان صالحا له (٥/ ٣٩٥). وفى \"الأدب\" باب حسن الخلق والسخاء (١٠/ ٤٥٦) وفى \"الديات\" باب من استعان عبدا أو صبيا (١٢/ ٢٥٣)، ومسلم \"الفضائل\" باب كان رسول اللَّه -صلى الله عليه وآله وسلم- أحسن الناس خلقا (٤/ ١٨٠٤ - ١٨٠٥) وأبو داود \"الأدب\" باب في الحلم وأخلاق النبى -صلى الله عليه وآله وسلم- (٤/ ٢٤٦)، وأحمد (٣/ ٢٢٢) كلهم أخرجوه من حديث أنس رضي الله عنه وفيه ذكر حُسْن خُلُقِ النبى -صلى الله عليه وآله وسلم-. وفيه عند البخارى، وعند أحمد، وعند مسلم في رواية \"أنه خدمه عشر سنين\". وعند أبى داود \"سبع سنين أو تسع سنين\" على الشك. وعند مسلم في رواية \"تسع سنين\"."],[10224,"وذكر الحافظ ابن حجر في الفتح (١٠/ ٤٥٩ - ٤٦٠) الرواية التى فيها لفظ \"عشر سنين\" ورواية مسلم التى فيها لفظ \"تسع سنين\" وذكر أنه لا مغايرة بين الروايتين، وجمع بينهما فقال: مدة خدمة أنس تسع سنين واشهرا فألغى الكسر مرة، وجبره أخرى. واللَّه أعلم."],[10225,"١٤٩٨ - الجرح (٤/ ٢/ ٣٥٨)، الميزان (٤/ ٥١٦)، اللسان (٧/ ٣٦) قال الذهبى، وتبعه ابن حجر: لا يعرف."],[10226,"(١) عثمان بن أبى العاص: الثقفى الطائفى، أبو عبد اللَّه، صحابى، شهير، استعمله رسول اللَّه -صلى الله عليه وآله وسلم- على الطائف، ومات في خلافة معاوية بالبصرة. التقريب (٢/ ١٠)"],[10227,"(٢) الحق في هامش الأصل."],[10228,"(٣) الحديث أخرجه أبو يعلى من طريق عبد اللَّه بن عيسى -رجل من أهل البصرة- عن أبى الحكم مولى أبى العاص عن عثمان بن أبى العاص قال: قال رسول اللَّه -صلى الله عليه وآله وسلم-: \"لا يدخل الجنة ولد الزنا، ولا عاق الوالدين، ولا مدمن خمر\" انظر اللالئ المصنوعة (٢/ ١٩٢ - ١٩٣)، والحديث أخرجه ابن أبى حاتم في الجرح (٤/ ٢/ ٣٥٨) من طريق عيسى بن عبد اللَّه عن أبى ="],[10229,". . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . ."],[10230,"= الحكم عن عثمان بن أبى العاص به مرفوعا. وأخرجه أيضا أحمد (٢/ ٢٠١ و٢٠٣)، والدارمى (٢/ ١١٢)، والخطيب البغدادى في التاريخ (١١/ ١٩١ و١٢/ ٢٩٣)، وابن خزيمة في التوحيد (ص ٣٦٥ - ٣٦٦) وأبو نعيم في الحلية (٣/ ٣٠٩) وابن جرير الطبرى في تهذيب الآثار (١/ ١٥٢ - ١٥٣) وابن فيل، وعبد الرزاق، كما في اللآلئ المصنوعة (٢/ ١٩٢)، والخرائطى في مساوئ الاخلاق، والطبرانى في الكبير كما في الجامع الكبير للسيوطى (١/ ٩٢٧)."],[10231,"وقال الهيثمى في مجمع الزوائد (٦/ ٢٥٧): حديث عبد اللَّه بن عمرو ابن العاص رواه أحمد والطبرانى، وفيه جابان، وثقه ابن حبان وبقية رجاله رجال الصحيح. وأخرجه أبو نعيم في الحلية (٣/ ٣٠٧ و٨/ ٢٤٩ و٣٠٨)، والطبرانى في الأوسط كما في مجمع الزوائد (٦/ ٢٥٧)، والدارقطنى في الافراد. كما في اللآلئ المصنوعة (٢/ ١٩٣) من حديث أبى هريرة رضي الله عنه. وقال الهيثمى: فيه الحسين بن ادريس وهو ضعيف. وأيضا أخرجه أبو نعيم في الحلية (٣/ ٣٠٩)، من حديث أبى سعيد الخدرى."],[10232,"فائدة: قال السيوطى في اللآلئ المصنوعة (٢/ ١٩٤) قال الرافعى في تاريخ قزوين: رأيت بخط الامام أبى الخير أحمد بن إسماعيل الطالقانى سألنى بعض الفقهاء في المدرسة النظامية ببغداد في جمادى الأولى سنة ست وسبعين وخمسمائة عما ورد في الخبر أنَّ ولد الزنا لا يدخل الجنة وهناك جمع من الفقهاء فقال: بعضهم هذا لا يصح ﴿وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى﴾ وذكر أن بعضهم قال في معناه أنه إذا عمل عمل أصليه وارتكب الفاحشة لا يدخل الجنة وزيف ذلك بأن هذا لا يختص بولد الزنا بل حال الرشدة مثله. ثم فتح اللَّه على جوابا شافيا لا أدرى هل سبقت إليه؟ فقلت: معناه انه لا يدخل الجنة بعمل أصليه بخلاف ولد الرشدة فانه إذا مات طفلا وأبواه مؤمنان الحق بهما وبلغ درجتهما بصلاحهما على ما قال تعالى ﴿وَالَّذِينَ آمَنُوا وَاتَّبَعَتْهُمْ ذُرِّيَّتُهُمْ بِإِيمَانٍ أَلْحَقْنَا بِهِمْ ذُرِّيَّتَهُمْ﴾ الطور: ٢١. وولد الزنا لا يدخل الجنة بعمل أصليه أما الزانى فنسبه منقطع، وأما الزانية فشؤم زناها وإن صلحت يمنع من وصول بركة صلاحها إليه. اهـ."],[10233,"عبد اللَّه بن عيسى (١). قال على بن المدينى (٢) أبو الحكم مولى عثمان بن أبى العاص لا أعرفه، وعبد اللَّه بن (عيسى) (٣) مجهول."],[10234,"(١) عبد اللَّه بن عيسى. ذكره ابن أبى حاتم في الجرح (٢/ ٢/ ١٢٧ - ١٢٨) وذكر روايته عن أبى الحكم مولى عثمان بن أبى العاص ورواية إبراهيم بن الحسن الكندى عنه وقال: قال على بن المدينى: عبد اللَّه بن عيسى وإبراهيم ابن الحسن مجهولان."],[10235,"(٢) انظر الجرح (٤/ ٢/ ٣٥٨) في ترجمة أبى الحكم، و(٢/ ٢/ ١٢٨)، في ترجمة عبد اللَّه بن عيسى."],[10236,"(٣) الحق بهامش الأصل. كتب عنده كلمة \"صح\"."],[10237,"باب أبى الحارث"],[10238,"١٤٩٩ - أبو الحارث الغفارى، عن أبى هريرة، روى عنه يحيى بن أبى كثير من رواية على بن المبارك."],[10239,"١٥٠٠ - أبو الحارث الكرمانى، سمع أبا رجاء العطارى، روى عنه أبو سلمة المنقرى، (وبدل بن المحبر) (١)."],[10240,"١٥٠١ - أبو الحارث (٢). وقيل: أبو الحويرث، روى عن أبيه، روى عنه ثابت ابن سهل القرشى (٣)، حديثه عند أبى معشر البراء (٤)."],[10241,"١٤٩٩ - كنى البخارى (ص ٢٣)، كنى الحاكم (١/ ٩٧/ أ)، كنى ابن منده (٨٧/ ب)، الجرح (٤/ ٢/ ٣٥٨)، اللسان (٧/ ٢٩)."],[10242,"١٥٠٠ - كنى البخارى (ص ٢٣)، كنى ابن منده (٨٧/ ب)، كنى الحاكم (١/ ٩٧/ أ)، الجرح (٤/ ٢/ ٣٥٨)، التهذيب (١٢/ ٦٤)، التقريب (٢/ ٤٠٩) وقال: مقبول. من السادسة./ بخ."],[10243,"(١) الحق بهامش الأصل."],[10244,"١٥٠١ - كنى البخارى (ص ٢٣)، كنى الحاكم (١/ ٩٧/ أ)، الجرح (٤/ ٢/ ٣٥٨)، كنى ابن منده (٨٧/ ب)."],[10245,"(٢) في الأصل هذه الترجمة متأخرة عن التى بعدها، ولكن كتب أعلى هذه الترجمة \"تقدم\" كتب أعلى الترجمة الآتية والتى هى في الأصل مقدمة على هذه الترجمة - \"تؤخر\" لذا فاننى قدمت ترجمة أبى الحارث أو أبو الحويرث. والتى كتب عندها \"تقدم\" واخرت ترجمة أبى الحارث التيمى والتى كتب عندها تؤخر."],[10246,"(٣) ثابت بن سهل القرشى. له ترجمة في الجرح (١/ ١/ ٤٥٣)."],[10247,"(٤) أخرج البخارى في الكنى والحاكم في الكنى، وابن أبى حاتم في الجرح حديثه من طريق أبى معشر عن ثابت بن سهل القرشى، سمع شيخا من أهل المدينة أبو الحارث أو أبو الحويرث، ويخيل إلى أنه أبو الحارث أن أباه حدثه أن النبى -صلى الله عليه وآله وسلم- قال: \"والتمر والعنب فأيهما بطشت فهما أخوان، هو الخمر\"."],[10248,"١٥٠٢ - أبو الحارث التيمى، عن أم معبد."],[10249,"١٥٠٢ - كنى الحاكم (١/ ٩٧/ أ)، كنى ابن منده (٨٧/ ب) وقال: حدث عنه أبو الاحوص سلام بن سليم."],[10250,"باب أبى حرب"],[10251,"١٥٠٣ - أبو حرب بن أبى الأسود الدّيلى، بصرى، ثقة (١) روى عن عبد اللَّه ابن عمرو. وروى عن أبيه، روى عنه قتادة، وداود بن أبى هند، وأبو اليقظان عثمان بن عمير."],[10252,"١٥٠٤ - أبو حرب بن زيد بن خالد الجهنى، روى عن أبيه (٢) روى عنه بكير بن عبد اللَّه بن الاشج."],[10253,"١٥٠٥ - أبو حرب. ويقال: حرب. روى عن سعيد بن جبير. روى عنه ليث ابن أبى سليم."],[10254,"١٥٠٣ - كنى البخارى (ص ٢٣)، كنى مسلم (ص ٣٢١)، الطبقات الكبرى (٧/ ٢٢٦)، الثقات (٥/ ٥٧٦)، الجرح (٤/ ٢/ ٣٥٨)، كنى الحاكم (١/ ١٢١/ ب)، التهذيب (١٢/ ٦٩)، التقريب (٢/ ٤١٠) وقال: ثقة، قيل: اسمه محجن. وقيل: عطاء، من الثالثة (ت: ١٠٨) / ت. ص. ق."],[10255,"(١) يذكر ابن حجر: التهذيب (١٢/ ٧٠) \"قال ابن عبد البر في الكنى هو بصرى ثقة\"."],[10256,"١٥٠٤ - كنى البخارى (ص ٢٣)، الثقات (٥/ ٥٧٦)، الجرح (٤/ ٢/ ٣٥٨) كنى الحاكم (١/ ١٢٢/ أ)، الميزان (٤/ ٥١٣) وقال: مجهول التهذيب (١٢/ ٧٠)، التقريب (٢/ ٤١٠) وقال: مقبول، من الرابعة./ س."],[10257,"(٢) أبوه هو زيد بن خالد الجهنى، المدنى، صاحبى مشهور. مات بالكوفة سنة ثمان وستين أو سبعين. التقريب (١/ ٢٧٤)."],[10258,"١٥٠٥ - كنى البخارى (ص ٢٤)، الجرح (٤/ ٢/ ٣٥٩)."],[10259,"باب أبى حمزة"],[10260,"١٥٠٦ - أبو حمزة الخولانى، سمع جابر بن عبد اللَّه، روى عنه بكر بن سوادة. قال أبو زرعة: هو مصرى لا يعرف اسمه (١)."],[10261,"١٥٠٧ - أبو حمزة بن سليم العنسى روى عنه معاوية بن صالح و(محمد) (٢) بن الحارث، وعيسى بن يونس. قال ابن أبى حاتم: سمعت أبى يقول: لا يسمى وهو حمصى ثقة."],[10262,"١٥٠٨ - أبو حمزة مولى أبى مريم، شامى. روى عن أنس بن مالك. روى عنه صفوان بن عمرو."],[10263,"١٥٠٦ - كنى البخارى (ص ٢٦)، الثقات (٥/ ٥٧٨)، كنى الحاكم (١/ ١٠٥/ أ) الجرح (٤/ ٢/ ٣٦٢)."],[10264,"(١) انظر الجرح (٤/ ٢/ ٣٦٢)."],[10265,"١٥٠٧ - الجرح (٤/ ٢/ ٣٦٢) وقال: أبو حمزة بن سليم العنسى روى عن. . روى عنه معاوية بن صالح وعمرو بن الحارث، وعيسى بن يونس، سمعت أبى يقول: لا يسمى، وهو حمصى ثقة. اهـ."],[10266,"قلت: هكذا قال أبو حاتم: لا يسمى. وقد ذكره المزى في تهذيب الكمال وقال: اسمه عيسى بن سليم العنسى الحمصى، وذكر رواية عمرو بن الحارث المصرى، وعيسى بن يونس، ومعاوية بن صالح الحضرمى، وآخرين عنه. وذكر أيضا قول أبى حاتم المتقدم فيه. وتبعه ابن حجر أيضا فذكره بهذا. انظر تهذيب الكمال (٢/ ١٠٧٩) و(٣/ ١٦٠٠)، والتهذيب (٨/ ٢١٠)."],[10267,"(٢) هكذا في الأصل \"محمد\" وفى الجرح، وتهذيب الكمال والتهذيب \"عمرو ابن الحارث المصرى\". وذكر المزى أيضا في ترجمة عمرو بن الحارث بن يعقوب المصرى أنه روى عن أبى حمزة بن سليم."],[10268,"١٥٠٨ - كنى الحاكم (١/ ١٠٤/ ب)، كنى ابن منده (٩٢/ ب) وقال: أبو حمزة مولى أنس. فذكره كما هنا."],[10269,"١٥٠٩ - أبو حمزة التّمار بصرى. له حديث واحد سأل عنه الحسن. روى (عنه) (١) حماد بن سلمة قال أبو حاتم: هو شيخ بصرى لا يسمى."],[10270,"١٥١٠ - أبو حمزة، رجل شامى، روى عن ابن شهاب روى عنه ضمرة بن ربيعة."],[10271,"١٥٠٩ - الجرح (٤/ ٢/ ٣٦٢) وقال: أبو حمزة التمار، بصرى، سأل الحسن حديثا واحدا، روى عنه حماد بن سلمة، سمعت أبى يقول ذلك. ويقول: لا يسمى. قلت له: فما قولك فيه؟ قال: هو شيخ. كنى ابن منده (٩٢/ أ)، وقال: أبو حمزة يزيد التمار، بصرى، سمع الحسن بن أبى الحسن البصرى، روى عنه حماد بن سلمة."],[10272,"قلت: وقد تقدم في الكتاب الثانى (٦١٤) أبو حمزة التمار يزيد. وأغلب الظن أن الترجمتين لرجل واحد واللَّه أعلم."],[10273,"(١) الحق في الهامش أسفل الترجمة. كتب عنده كلمة \"صح\"."],[10274,"١٥١٠ - كنى الحاكم (١/ ١٠٥/ أ)."],[10275,"باب أبى حبيب"],[10276,"١٥١١ - أبو حبيب بن يعلى بن أمية التميمى. وربما نسب إلى أمه فقيل: يعلى بن منية (١) -قد ذكرناه في الصحابة بما ينبغى- من ذكره (٢)، وابنه أبو حبيب هذا روى عن عبد اللَّه بن عباس. روى عنه مصعب بن شيبة (٣)."],[10277,"١٥١٢ - أبو حبيب. عن أبيه عن على. روى عنه المختار بن نافع (٤)."],[10278,"١٥١١ - كنى البخارى (ص ٢٤)، كنى الحاكم (١/ ١٠٨/ أ)، الجرح (٤/ ٢/ ٣٥٩)، كنى مسلم (ص ٣١١)، الميزان (٤/ ٥١٣) العقد الثمين (٨/ ٣٦)، التهذيب (١٢/ ٦٨)، الثقات (٥/ ٥٧٥)، التقريب (٢/ ٤١٠) قال ابن حجر: مجهول، من الرابعة./ ق."],[10279,"(١) قال ابن عبد البر: اختلف في نسب منية بنت جابر. فقيل منية بنت جابر. وقيل: منية بنت الحارث بن جابر. وقد قيل: منية بنت غزوان أخت عتبة بن غزوان. وأهل الحديث أصحاب التواريخ يقولون: منية بنت غزوان أخت عتبة ابن غزوان. وأم يعلى بن أمية. وقال الطبرى: هى منية بنت جابر عمة عتبة بن غزوان وأم يعلى بن أمية. واللَّه أعلم. انظر الاستيعاب (٣/ ٦٦١ - ٦٦٢) وذكر ابن ماكولا منية هذه في الاكمال (٧/ ٢٩٦) فقال: منية بعد الميم نون ساكنة وياء مفتوحة معجمة باثنتين من تحتها. . \" فذكرها."],[10280,"(٢) انظر الاستيعاب (٣/ ٦٦١)."],[10281,"(٣) مصعب بن شيبة بن جبير، ليّن الحديث، من الخامسة. التقريب (٢/ ٢٥١)."],[10282,"١٥١٢ - كنى البخارى (ص ٢٤)، كنى مسلم (ص ٣١١)، كنى الحاكم (١/ ١٠٨/ أ) وذكره الحاكم كما هنا ثم قال: قاله لى على بن محمد سمع الحسين بن محمد وتابعه على ذلك مسلم بن الحجاج، وهو وهم، إنما هو أبو حيان، وهو التيمى يحيى ين سعيد بن حيان، روى عنه أبيه عن على بن أبى طالب غير حديث روى عنه المختار بن نافع وغيره. اهـ. قلت: وقد تقدم أبو حيان التيمى في الكتاب الثانى. انظر الترجمة (٦٣٦)."],[10283,"(٤) المختار بن نافع. هو أبو اسحاق التمار المتقدم في (٣٧٧)."],[10284,"١٥١٣ - أبو حبيب السلمى. روى عن جعفر بن سليمان."],[10285,"١٥١٤ - أبو حبيب عن رجل (١). روى عنه سليمان بن قرم."],[10286,"١٥١٥ - أبو حبيب البصرى. عن جابر (٢) بن زيد. روى عنه حميد الطويل."],[10287,"١٥١٣ - كنى البخارى (ص ٢٤)، كنى الحاكم (١/ ١٠٨/ أ)، الجرح (٤/ ٢/ ٣٥٩)."],[10288,"١٥١٤ - كنى البخارى (ص ٢٤)، كنى الحاكم (١/ ١٠٨/ أ)، الجرح (٤/ ٢/ ٣٥٩)."],[10289,"(١) لم أقف على من سماه."],[10290,"١٥١٥ - كنى البخارى (ص ٢٤)، كنى الحاكم (١/ ١٠٨/ أ)"],[10291,"(٢) هكذا في الأصل \"جابر\" والذى في مصادر الترجمة \"خالد\"."],[10292,"باب أبى حبيبة"],[10293,"١٥١٦ - أبو حبيبة الطّائى، سمع أبا الدراء، روى عنه أبو اسحاق السبيعى."],[10294,"١٥١٧ - أبو حبيبة مولى الزبير، روى عن الزبير. وسمع أبا هريرة \"وعثمان محصور\" (١)."],[10295,"١٥١٦ - كنى مسلم (ص ٣٢٥)، كنى الحاكم (١/ ٢٢/ أ). الثقات (٥/ ٥٧٧) الجرح (٤/ ٢/ ٣٥٩)، الميزان (٤/ ٥١٣) وقال: لا يدرى من هو. تهذيب الكمال (٣/ ١٥٩٦) وقال: أبو حبيبة الطائى، حديثه في الكوفيين، روى عن أبى الدرداء، روى عنه أبو اسحاق السبيعى، ولا نعرف له راو غيره. اهـ. التهذيب (١٢/ ٦٨)، التقريب (٢/ ٤١٠) وقال: مقبول، من الثالثة، د. ت. س."],[10296,"١٥١٧ - كنى البخارى (ص ٢٤)، كنى مسلم (ص ٣٢٥)، كنى الحاكم (١/ ١٢٢/ أ) الثقات (٥/ ٥٩١)، الجرح (٤/ ٢/ ٣٥٩)، تعجيل المنفعة (ص ٣١١)."],[10297,"(١) الحديث أخرجه أحمد في المسند (٢/ ٣٤٥) من طريق موسى بن عقبة قال: حدثنى جدى أبو أمى أبو حبيبة أنه دخل الدار وعثمان محصور فيها أنه سمع أبا هريرة يستأذن عثمان في الكلام فأذن له فقام فحمد اللَّه وأثنى عليه، ثم قال: سمعت رسول اللَّه -صلى الله عليه وآله وسلم- يقول: \"إنكم تلقون بعدى فتنة واختلافا\" أو قال: اختلافا وفتنة فقال له قائل من الناس فمن لنا يا رسول اللَّه قال: \"عليكم بالأمين وأصحابه\" وهو يشير إلى عثمان بذلك."],[10298,"والحديث عزاه أيضا الحافظ ابن حجر في تعجيل المنفعة (ص ٣١١) إلى أحمد في المسند."],[10299,"روى عنه موسى وإبراهيم (١) ومحمد (٢) بنو عقبة وهو جدهم (٣)."],[10300,"١٥١٨ - أبو حبيبة مولى طلحة بن عبيد اللَّه سمع على بن أبى طالب. روى عنه سعد بن طارق أبو مالك الاشجعى وطلحة بن يحيى (٤)."],[10301,"(١) إبراهيم بن عقبة بن أبى عياش الاسدى، ثقة، من السادسة. التقريب (١/ ٣٩)."],[10302,"(٢) محمد بن عقبة بن أبى عياش الاسدى، ثقة، من السادسة، التقريب (٢/ ١٩١)."],[10303,"(٣) هو جدهم لأمهم. كما ذكر أنجو أحمد الحاكم في الكنى وقد تقدم في الحديث عند أحمد قال: موسى بن عقبة \"حدثنى جدى أبو أمى. . \" الخ."],[10304,"١٥١٨ - كنى البخارى (ص ٢٤)، كنى الحاكم (١/ ٢٢/ ب)."],[10305,"(٤) طلحة بن يحيى بن طلحة التيمى، صدوق يخطئ، من السادسة. التقريب (١/ ٣٨٠)."],[10306,"باب أبى الحجاج"],[10307,"١٥١٩ - أبو الحجاج الازدى عن سلمان الفارسى. روى عنه أبو اسحاق السبيعى."],[10308,"١٥٢٠ - أبو الحجاج (١) الثقفى. له حديث عن النبى -صلى الله عليه وآله وسلم- مرسل. انه قال: مرّ رجل من قومى على رسول اللَّه (٢) فذكر الحديث. روى عنه حصين بن عبد الرحمن."],[10309,"١٥١٩ - كنى مسلم (ص ٣١٦)، كنى الحاكم (١/ ١٠٩/ ب)."],[10310,"١٥٢٠ - كنى الحاكم (١/ ١٠٩/ ب)، الجرح (٤/ ٢/ ٣٦٣)."],[10311,"(١) في مصادر الترجمة زيادة لفظ \"بن سعيد\"."],[10312,"(٢) ذكر الحديث أيضا ابن أبى حاتم: قال: \"مر رجل من قومى سمع رسول اللَّه -صلى الله عليه وآله وسلم- وهو يجر ازاره\"."],[10313,"باب أبى حذيفة"],[10314,"١٥٢١ - أبو حذيفة بن حذيفة، سمع عمه زياد بن صيفى بن صهيب بن سنان (١)، مدنى، روى عنه محمد بن اسحاق، ويحيى بن محمد الجارى (٢)."],[10315,"١٥٢٢ - أبو حذيفة البصرى. عن داود بن أبى هند. روى عنه مروان بن معاوية."],[10316,"١٥٢١ - كنى البخارى (ص ٢٤)، كنى الحاكم (١/ ١٢/ ب)، الجرح (٤/ ٢/ ٣٥٩)."],[10317,"(١) زياد بن صيفى، بفتح المهملة وسكون التحتانية، ابن صهيب الرومى، صدوق، من الرابعة. التقريب (١/ ٢٦٨)."],[10318,"(٢) الجارى: بفتح الجيم وبالراء - هذه النسبة إلى الجار، وهى بليدة على الساحل بقرب مدينة النبى -صلى الله عليه وآله وسلم-. اللباب (١/ ٢٥١) ويحيى بن محمد الجارى هذا ذكره ابن أبى حاتم في الجرح (٤/ ٢/ ١٨٤) ولم يذكر فيه شيئا."],[10319,"١٥٢٢ - كنى البخارى (ص ٢٤)، كنى الحاكم (١/ ١١٢/ ب)، الجرح (٤/ ٢/ ٣٦٠)، الميزان (٤/ ٢/ ٥١٣)، اللسان (٧/ ٣٢) قال الذهبى، وتبعه ابن حجر: لا يعرف."],[10320,"باب أبى حية"],[10321,"١٥٢٣ - أبو حيّة (١) بن قيس الوادعى. روى عن على بن أبى طالب. روى عنه أبو اسحاق السبيعى. ذكر عبد اللَّه بن أحمد بن حنبل قال: قال أبى (٢): أبو حية الوادعى صاحب على شيخ من شيوخ أبى اسحاق (ما علمت) (٣) إلا خيرا وقال أبو زرعة: الوادعى لا يسمى بغير كنيته (٤) (٥)."],[10322,"١٥٢٣ - كنى البخارى (ص ٢٤)، كنى الحاكم (١/ ١٢٨/ أ)، الثقات (٥/ ١٨٠) الجرح (٤/ ٢/ ٣٦٠)، الميزان (٤/ ٥١٩)، الاكمال (٢/ ٣٢٥)، تهذيب الكمال (٣/ ١٦٠٠)، كنى ابن منده (٩٩/ أ)، التهذيب (١٢/ ٨١)، التقريب (٢/ ٤١٥) وقال: مقبول، من الثالثة./ عـ."],[10323,"(١) حيّه: أوله حاء مهملة وبعدها ياء مشددة معجمة باثنتين من تحتها. الاكمال (٢/ ٣٢٣)."],[10324,"(٢) و(٤) الجرح (٤/ ٢/ ٣٦٠)."],[10325,"(٣) غير واضح في الأصل. ولعل الصواب ما أثبته، وهو الذى يناسب السياق. والله أعلم."],[10326,"(٥) هكذا ذكر ابن عبد البر هذه الترجمة فيمن لا يعرف لهم أسماء وذكر قول أبى زرعة حيث قال \"لا يسمى بغير كنيته\". وقال الحاكم أيضا في الكنى: لا يعرف اسمه. لكن ذكره ابن حبان في الثقات في الأسماء فقال \"عمرو ابن عبد اللَّه. . \" الخ."],[10327,"وقال ابن ماكولا: يختلف في اسمه، فيقال: عمرو بن نصر، ويقال: عامر ابن الحارث. واللَّه أعلم."],[10328,"قلت: وستأتى أيضا ترجمة لأبى حية بن قيس الوادعى الهمدانى عند المؤلف. انظر الترجمة (١٥٦٠)."],[10329,"١٥٢٤ - أبو حيّة الكلبى. روى عن سعد بن أبى وقاص، وعبد اللَّه بن عمر روى عنه (. . . . .) (١)."],[10330,"١٥٢٤ - كنى البخارى (ص ٢٤)، الثقات (٥/ ٥٩١)، الجرح (٤/ ٢/ ٣٦٠) الميزان (٤/ ٥١٩)، الاكمال (٢/ ٣٢٥)، تهذيب الكمال (٣/ ١٦٠١)، التهذيب (١٢/ ٨٢)، التقريب (٢/ ٤١٥) وقال: مجهول، من الرابعة./ ق."],[10331,"(١) هكذا في الأصل فراغ. حيث لم يذكر ابن عبد البر من روى عنه. وكذا في الجرح. والذى في مصادر الترجمة الاخرى. روى عنه ابنه أبو جناب يحيى ابن أبى حية."],[10332,"قلت: وقد تقدم في ترجمة أبى جناب الكلبى يحيى بن أبى حية قول ابن عبد البر: \"لا يوقف لأبيه أبى حية على اسم على صحة. وقد قيل: اسمه حى. روى أبو جناب هذا عن أبيه\". اهـ."],[10333,"باب أبى حميد"],[10334,"١٥٢٥ - أبو حميد مولى مسافع، سمع أبا هريرة. روى عنه الزهرى، قال عباس عن ابن معين (١): هذه الأحاديث التى يروونها عن الزهرى عن أبى حميد رأيتها في كتاب ابن المبارك عن يونس عن أبى حميد، (جمعها) (٢) يونس عن أبى حميد قال عباس: فقلت ليحيى: فلعل الزهرى أيضا سمعها من أبى حميد؟ قال: لا."],[10335,"١٥٢٦ - أبو حميد الرعينى، شامى، روى عن عتبة بن عبد، روى عنه ثور ابن يزيد."],[10336,"١٥٢٧ - أبو حميد، عن عمر بن عبد العزيز، شامى، روى عنه عمرو بن عبد اللَّه (٣)."],[10337,"١٥٢٥ - كنى البخارى (ص ٢٥)، كنى مسلم (ص ٣١٧)، كنى الحاكم (١/ ١١٣/ ب)، تهذيب الكمال (٣/ ١٦٠٠)، التهذيب (١٢/ ٨٠) كنى ابن منده (٩٦/ أ)، الجرح (٤/ ٢/ ٣٦٠)، التقريب (٢/ ٤١٤) وقال: أبو حميد مولى مسافع. قيل: هو عبد الرحمن بن سعد المقعد وإلا فمجهول، من الثالثة./ ق."],[10338,"(١) انظر التاريخ ٣/ ١١٣، وقد ذكره ابن أبى حاتم في الجرح (٤/ ٢/ ٣٦٠)."],[10339,"(٢) كذا في الأصل \"جمعها\" بالجيم. والذى في الجرح \"سمعها\" بالسين."],[10340,"١٥٢٦ - كنى البخارى (ص ٢٥)، كنى الحاكم (١/ ١١٣/ أ)، الميزان (٤/ ٥١٧) وقال: مجهول، الجرح (٤/ ٢/ ٣٦٠)، التهذيب (١٢/ ٧٩)، التقريب (٢/ ٤١٤) وقال: مجهول، من السادسة./ د."],[10341,"١٥٢٧ - كنى ابن منده (٩٦/ أ)، كنى الحاكم (١/ ١١٣/ أ)."],[10342,"(٣) عمرو بن عبد اللَّه بن صفوان القرشى، له ترجمة في الجرح (٣/ ١/ ٢٤٢)."],[10343,"باب أبى حرة"],[10344,"١٥٢٨ - أبو حُرّة (١)، روى عن عمر بن الخطاب، روى عنه ابنه عبد الملك (٢)."],[10345,"١٥٢٩ - أبو حُرَّة مولى المسيب (٣)، مدنى، روى عن معاوية بن الحكم (٤) روى عنه موسى بن عبيدة."],[10346,"١٥٢٨ - كنى البخارى (ص ٢٤)، كنى الحاكم (١/ ١١٦/ ب)، كنى ابن منده (٩٦/ ب)."],[10347,"(١) حرّة، بضم الحاء المهملة وتشديد الراء. الاكمال (٢/ ٤٣٤)."],[10348,"(٢) عبد الملك بن أبى حرة. ترجمته في الجرح (٢/ ٢/ ٣٤٨)."],[10349,"١٥٢٩ - كنى الحاكم (١/ ١١٦/ ب)، كنى ابن منده (٩٦/ ب)."],[10350,"(٣) المسيّب: هو ابن حزن، بفتح المهملة وسكون الزاى، ابن وهب المخزومى، أبو سعيد، له ولأبيه صحبة، عاش إلى خلافة عمر. التقريب (٢/ ٢٥٠)."],[10351,"(٤) معاوية بن الحكم، سلمى، صحابى، نزل المدينة. التقريب (٢/ ٢٥٨)."],[10352,"باب أبى حنيفة"],[10353,"١٥٣٠ - أبو حنيفة. رجل من رهط زياد بن كليب كوفى شهد جنازة جبير ابن مطعم (١) ورافع بن خديج. روى عنه المغيرة بن مقسم صاحب إبراهيم."],[10354,"١٥٣١ - أبو حنيفة اليمامى. روى عنه ابن المبارك قوله. اسمه ناشرة (٢)."],[10355,"والأكثر يقولون: اسمه كنيته. وقد روى عنه عبد الحكم بن أعين (٣) المصرى، والد عبد اللَّه بن عبد الحكم."],[10356,"١٥٣٠ - كنى البخارى (ص ٢٥)، كنى الحاكم (١/ ١٢١/ أ)، الميزان (٤/ ٥١٨) وقال: لا يعرف، اللسان (٤/ ٣٧)."],[10357,"(١) جبير بن مطعم بن عدى بن نوفل بن عبد مناف القرشى النوفلى، صحابى عارف بالانساب. التقريب (١/ ١٢٦)."],[10358,"١٥٣١ - كنى البخارى (ص ٢٥)، كنى الحاكم (١/ ١٢١/ أ)، الثقات (٧/ ٦٥٧) الجرح (٤/ ١/ ٤٩٩)، اللسان (٦/ ١٤٤)."],[10359,"(٢) ذكره البخارى وابن حبان وأبو أحمد الحاكم فيمن لم يوقف له على اسم وذكره ابن أبى حاتم وابن حجر فيمن يسمى ناشرة فقال ابن أبى حاتم: ناشرة اليمامى. كنيته أبو حنيفة. روى عنه ابن المبارك \"وقال ابن حجر: ناشرة بن عبد اللَّه أبو حنيفة. يروى عن طاووس. روى عنه ابن المبارك\" اهـ. قلت: وقد تقدم أبو حنيفة اليمامى هذا في الكتاب الثانى وقد قال ابن عبد البر هناك: \"والصواب أبو حنيفة اليمامى ناشر. وقد قيل ان اسمه كنيته\" انظر الترجمة (٦٢٥)."],[10360,"(٣) عبد الحكم بن أعين المصرى، ترجم له ابن أبى حاتم في الجرح (٣/ ١/ ٣٦) فقال: روى عن أبى حنيفة اليمامى\". اهـ."],[10361,"باب أبى حفص"],[10362,"١٥٣٢ - أبو حفص. بصرى روى عن عمر بن الخطاب. روى عنه سليمان التيمى."],[10363,"١٥٣٣ - أبو حفص المدنى. سمع ابن عباس. قال اسحاق بن منصور عن يحيى بن معين: ليس به بأس (١)."],[10364,"١٥٣٤ - أبو حفص الحمصى. قال: لقيت سلمان يطوف بالبيت (٢): روى عنه السَّرِي بن إسماعيل (٣)."],[10365,"١٥٣٥ - أبو حفص الطائفى، عن أبى حازم، سلمة بن دينار المزنى، روى عنه معاوية بن هشام."],[10366,"١٥٣٦ - أبو حفص الأعشى الكوفى عن ياسين الزيات (٤) روى عنه محمد"],[10367,"١٥٣٢ - كنى الحاكم (١/ ٧٤/ ب)، كنى ابن منده (٧٣/ ب)."],[10368,"١٥٣٣ - كنى البخارى (ص ٢٥)، الجرح (٤/ ٢/ ٣٦٠)."],[10369,"(١) انظر الجرح (٤/ ٢/ ٣٦٠ - ٣٦١)."],[10370,"١٥٣٤ - كنى الحاكم (١/ ٧٤/ أ)، كنى ابن منده (٧٣/ ب) وقال: عن سلمان مرسل."],[10371,"(٢) زاد الحاكم \"فقلت يا أبا عبد اللَّه\"."],[10372,"(٣) السّرى -بفتح مهملة وكسر راء خفيفة وشدة مثناة تحت- ابن إسماعيل الهمدانى، الكوفى، ابن عم الشعبى ولى القضاء، وهو متروك الحديث من السادسة. التقريب (١/ ٢٨٥)، المغنى (ص ٣٨)."],[10373,"١٥٣٥ - كنى الحاكم (١/ ٧٤/ أ)، كنى ابن منده (٧٣/ ب)."],[10374,"١٥٣٦ - كنى الحاكم (١/ ٧٤/ أ) وقال: قد أخرجت فيما تقدم أبا حفص عمر بن أبى سليمان، فلا ادرى هما اثنان أم واحد. اهـ. قلت: وانظر ترجمة أبى حفص عمر بن أبى سليمان في كنى الحاكم (١/ ٧١/ ب)."],[10375,"(٤) ياسين بن معاذ الزيات، كان من كبار فقهاء الكوفة ومفتيها وأصله يمامى يكنى أبا خلف. اللسان (٦/ ١٣٨)."],[10376,"ابن عبيد (١) وقد قيل: ان أبا حفص الأعشى هذا هو عمر بن سليمان."],[10377,"١٥٣٧ - أبو حفص العمرى. روى عنه خالد بن كثير (٢)."],[10378,"١٥٣٨ - أبو حفص العبدى. روى عن هشام بن حسان، وثابت البنانى، روى عنه ابن أبى سريج (٣). قال عباس عن يحيى بن معين: أبو حفص العبدى ليس بشئ (٤)."],[10379,"وقال أبو حاتم: أبو حفص العبدى بصرى سكن بغداد ضعيف الحديث لا يشتغل به (٥)."],[10380,"١٥٣٩ - أبو حفص الأسيدى قال: خطب عبد الملك بن مروان (٦)، روى عنه محمد بن زهير."],[10381,"(١) محمد بن عبيد بن محمد واقد المحاربى النحاس، الكوفى، صدوق، من العاشرة. التقريب (٢/ ٢٨٩)."],[10382,"١٥٣٧ - كنى البخارى (ص ٢٥)، الجرح (٤/ ٢/ ٣٦١)، كنى الحاكم (١/ ٧٤/ أ)."],[10383,"(٢) خالد بن كثير الهمدانى، الكوفى، ليس به بأس، من السادسة. التقريب (١/ ٢١٧)."],[10384,"١٥٣٨ - الجرح (٤/ ٢/ ٣٦١)، الميزان (٤/ ٥١٦)، كنى الدولابى (١/ ١٥٢)، تاريخ بغداد (١١/ ١٩٢ - ١٩٤). قلت: وقد تقدم أبو حفص العبدى عمر بن حفص في الكتاب الثانى. انظر الترجمة (٥٩٠)."],[10385,"(٣) ابن أبى سريج: هو أحمد بن صبّاح النهشلى ثقة حافظ، له غرائب من العاشرة. التقريب (١/ ١٧)."],[10386,"(٤) انظر تاريخ ابن معين (٢/ ٤٢٦) وسماه عمر بن حفص أبو حفص العبدى وذكره عنه أيضا الخطيب البغدادى في التاريخ (١١/ ١٩٣)."],[10387,"(٥) الجرح (٤/ ٢/ ٣٦١)، وزاد لفظ \"يروى عن ثابت مناكير\"."],[10388,"١٥٣٩ - كنى الحاكم (١/ ٧٤/ أ)، كنى ابن منده (٧٣/ ب) وقال: ذكره محمد بن اسحاق السراج."],[10389,"(٦) زاد الحكم \"مرسل\"."],[10390,"١٥٤٠ - أبو حفص الدمشقى عن مكحول. روى عنه اسحاق بن أسيد (١) حديثا منكرًا، وقد قيل: انه عثمان بن أبى العاتكة وليس ممن تقوم به حجة (٢)."],[10391,"١٥٤١ - أبو حفص الأرطبانى، بصرى. سمع عاصم الجحدرى (٣). روى عنه نصر بن على الجهضمى."],[10392,"١٥٤٢ - أبو حفص. روى عن أنس بن مالك عن النبى عليه السلام أنه قال: \"مثل العلماء في الارض مثل النجوم في السماء يهتدى بها في ظلمات البر والبحر فإذا طمست النجوم أوشك أن تضل الهداة\" (٤). روى حديثه هذا رِشْدِين"],[10393,"١٥٤٠ - الميزان (٤/ ٥١٦) وقال: لا يعرف، كنى الحاكم (١/ ٧٤/ أ)، اللسان (٧/ ٣٥)، التهذيب (١٢/ ٧٦١)، التقريب (٢/ ٤١٣) وقال ابن حجر: مجهول، من الخامسة، وقيل: هو عمر الدمشقى، وقيل هو عثمان بن أبى العاتكة./ د. ق."],[10394,"(١) اسحاق بن أسِيد، بالفتح، فيه ضعف، من الثامنة. التقريب (١/ ٥٦) وقال أبو حاتم: شيخ خراسانى ليس بالمشهور ولا يشتغل به. الجرح (١/ ١/ ٢١٣)."],[10395,"(٢) يذكر ابن حجر التهذيب (١٢/ ٧٦) \"قال ابن عبد البر: حديثه منكر، وقد قيل: انه عثمان بن أبى العاتكه وليس ممن تقوم به حجة\"."],[10396,"١٥٤١ - كنى الحاكم (١/ ٧٤/ ب)، كنى ابن منده (٧٣/ ب)."],[10397,"(٣) عاصم الجحدرى، هو ابن العجاج البصرى، كان من عبَّاد أهل البصرة وقرائهم (ت: ١٢٩)، اللسان (٣/ ٢٢٠)."],[10398,"١٥٤٢ - الجرح (٤/ ٢/ ٣٦١)، تعجيل المنفعة (ص ٣١٣)."],[10399,"(٤) الحديث أخرجه أحمد في المسند (٣/ ١٧٥)، والخطيب البغدادى في كتاب الفقيه والمتفقه (٢/ ٧٠) كلاهما من طريق رشدين بن سعد عن عبد اللَّه بن الوليد التجيبى عن أبى حفص حدثه أنه سمع أنس بن مالك يقول: قال النبى -صلى الله عليه وآله وسلم-: فذكره."],[10400,"والحديث ذكره الهيثمى في مجمع الزوائد (١/ ١٢١ و٢٠٢) وعزاه لأحمد وقال: فيه رشدين بن سعد واختلف في الاحتجاج به، وأبو حفص صاحب أنس مجهول. واللَّه أعلم. ="],[10401,"ابن سعد (١) عن عبد اللَّه بن الوليد التجيبى (٢) عنه."],[10402,"= وذكره السيوطى في الجامع الصغير (١/ ٩٧) من حديث أنس وعزاه لأحمد، ورمز لحسنه."],[10403,"وذكره الحافظ ابن حجر في تعجيل المنفعة (ص ٣١٣) وقال: في سنده رشدين بن سعد أحد الضعفاء. اهـ."],[10404,"(١) رِشدين، بكسر الراء وسكون المعجمة، ابن سعد بن مفلح المَهْرى، بفتح الميم وسكون الهاء أبو الحجاج المصرى، ضعيف، رجح أبو حاتم عليه ابن لهيعة، وقال ابن يونس: كان صالحا في دينه. فأدركته غفلة الصالحين، فخلط في الحديث، من السابعة. التقريب (١/ ٢٥١)."],[10405,"(٢) عبد اللَّه بن الوليد التجيبى: بصرى، لين الحديث، من السادسة. التقريب (١/ ٤٥٩)."],[10406,"باب أبى الحصين"],[10407,"١٥٤٣ - أبو الحُصَين (١) سمع ابن عمر. روى عنه عثمان بن واقد (٢)."],[10408,"١٥٤٤ - أبو الحصين الذى سمع يحيى بن سليم. روى عنه محمد بن إبراهيم بن زياد الطيالسى (٣)."],[10409,"١٥٤٥ - أبو الحصين، المكى. روى عن شهر بن حوشب، عن معاذ، وهو منقطع عن النبى -صلى الله عليه وآله وسلم- أنه قال: \"ذكر اللَّه خير من الجهاد في سبيل اللَّه\" (٤)."],[10410,"١٥٤٣ - كنى البخارى (ص ٢٥)، الثقات (٥/ ٥٧٤)، كنى الحاكم (١/ ١١٠/ ب) الاكمال (٢/ ٤٧٩)، الجرح (٤/ ٢/ ٣٦١)، الميزان (٤/ ٥١٦). اللسان (٧/ ٣٥)."],[10411,"(١) الحصين: بضم الحاء المهملة، مصغرا، الاكمال (٢/ ٤٧٨)."],[10412,"(٢) عثمان بن واقد بن محمد بن زيد بن عبد اللَّه بن عمر العمرى المدنى، نزيل البصرة، صدوق ربما وهم، من السابعة. التقريب (٢/ ١٥)"],[10413,"١٥٤٤ - لم أقف عليه عند غير المؤلف."],[10414,"(٣) محمد بن إبراهيم بن زياد الطيالسى الرازى المحدث الجوال، ضعفه أبو أحمد الحاكم وقال الدارقطنى: متروك. انظر اللسان (٥/ ٢٢)."],[10415,"١٥٤٥ - كنى البخارى (ص ٢٥)، الجرح (٤/ ٢/ ٣٦١)، الاكمال (٢/ ٤٧٩)."],[10416,"(٤) الحديث أخرجه أحمد في المسند (٥/ ٢٣٩) من طريق حجين بن المثنى، ثنا عبد العزيز -يعنى ابن أبى سلمة عن زياد بن أبى زياد مولى عبد اللَّه بن عياش بن أبى ربيعة أنه بلغه عن معاذ بن جبل أنه قال: قال رسول اللَّه -صلى الله عليه وآله وسلم-: \"ما عمل آدمى عملا قط انجى له من عذاب اللَّه من ذكر اللَّه\" وقال معاذ قال رسول اللَّه -صلى الله عليه وآله وسلم-: \"ألا أخبركم بخير أعمالكم وازكاها عند مليككم وارفعها في درجاتكم وخير لكم من تعاطى الذهب والفضة ومن أن تلقوا عدوكم غدا فتضربوا أعناقهم ويضربوا أعناقكم؟ قالوا: بلى يا رسول اللَّه قال: \"ذكر اللَّه عز وجل\"."],[10417,"وأخرجه الطبرانى في الكبير من حديث معاذ بن جبل بنحو هذا اللفظ = . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . ."],[10418,"= انظر مجمع الزوائد (١٠/ ٧٣) وقال الهيثمى: رجاله رجال الصحيح وأخرجه أيضا اسحاق بن راهويه في المسند. انظر المطالب العالية (٣/ ٢٤٣) وقال المحقق حبيب الرحمن الأعظمى قال البوصيرى: رواه اسحاق موقوفا وابن أبى شبية مرفوعا. وعنه عبد بن حميد بسند صحيح. ورواه أحمد بسند فيه انقطاع. اهـ."],[10419,"باب أبى حاضر"],[10420,"١٥٤٦ - أبو حاضر. روى عن النبى عليه السلام مرسلًا. انه كان إذا صلى وسلم يقول: \"اللهم أنت خلقتنا ونحن عبادك أنت ربنا وإليك معادنا\" (١). من حديث شعبة عن خالد الحذاء عن أبى هنيدة عن أبى حاضر."],[10421,"١٥٤٧ - أبو حاضر سمع ابن عباس روى عنه أبو السوار (٢)،"],[10422,"١٥٤٦ - الجرح (٤/ ٢/ ٣٦٢)، الإصابة (٤/ ٤٠)، وقال: أبو حاضر غير منسوب ذكره البغوى وابن الجارود والباوردى وابن حبان في الصحابة وقال الذهلى لا أدرى له صحبة أم لا؟ وقال البغوى: لم ينسب. وقال ابن منده له ذكر في الصحابة. اهـ. وانظر الثقات لابن حبان (٣/ ٤٥٣) التجريد (٢/ ١٥٧)، المراسيل لابن أبى حاتم (ص ٢٥٢)، وقال: قيل لأبى زرعة: له صحبة؟ قال: اللَّه أعلم. وسمعت أبى يقول: أبو حاضر هو تابعى، جامع التحصيل (ص ٣٨٠ - ٣٨١) وذكر قول أبى حاتم وقال: قلت: في التابعين أبو حاضر عثمان بن حاضر يروى عن ابن عباس وابن عمرو وأبى هريرة رضي الله عنهم، وغيرهم وكأنه هذا. واللَّه أعلم. اهـ."],[10423,"(١) الحديث أخرجه ابن أبى حاتم في الجرح (٤/ ٢/ ٣٦٢) وابن منده والبغوى كلهم من طريق شعبة عن خالد الحذاء عن أبى هنيدة عن أبى حاضر قال: إلا أعلمك كيف كان رسول اللَّه -صلى الله عليه وآله وسلم- يصلى على الجنازة؟: اللهم نحن عبادك وأنت خلقتنا وأنت ربنا وإليك معادنا، وفى رواية البغوى انه -صلى الله عليه وآله وسلم- صلى على جنازة ثم قال: \"ألا أخبركم فذكره\" وقال فيه: \"أنت خلقتنا ونحن عبادك والباقى مثله\". انظر الإصابة (٤/ ٤٠)."],[10424,"١٥٤٧ - كنى البخارى (ص ٢٦)، الثقات (٥/ ١٥٦ و٥٧٩)، الجرح (٤/ ٢/ ٣٦٢)، كنى ابن منده (٩٨/ أ)، وقال: أبو حاضر حدث عن عبد اللَّه ابن عباس اسمه عثمان بن حاضر روى عنه عمرو بن ميمون وأبو السّوار."],[10425,"(٢) أبو السّوار. هو السلمى يأتى في (١٤٢٣)."],[10426,"وأبو الجنيد قال أبو حاتم: لا أدرى أهو عثمان بن حاضر أم لا؟ (١)."],[10427,"١٥٤٨ - أبو حاضر. روى عن الوضين بن عطاء. روى عنه ابن فضيل (٢)، هو عندهم مجهول."],[10428,"(١) الجرح (٤/ ٢/ ٣٦٢ - ٣٦٣)."],[10429,"١٥٤٨ - الجرح (٤/ ٢/ ٣٦٢)، وقال: سألت أبى عنه فقالت هو مجهول، اللسان (٧/ ٣٠)."],[10430,"(٢) ابن فضيل: هو قتادة بن فضيل كما صرح بذلك ابن أبى حاتم في الجرح، وهو مقبول، من التاسعة (ت: ٢٠٠)، التقريب (٢/ ١٢٣)."],[10431,"باب أبى حصين"],[10432,"١٥٤٩ - أبو حصين (١) بن أحمد بن يونس. روى عن عبثر بن القاسم (٢) روى عنه أبو حاتم الرازى وغيره."],[10433,"١٥٥٠ - أبو حصين بن يحيى بن سليمان الرازى. روى عن سفيان بن عيينة وحفص بن غياث ومحمد بن فضيل وأبى معاوية الضرير وكيع ويونس بن بكير وعبد الرزاق وجعفر بن عون. روى عنه جماعة منهم أبو حاتم وأبو زرعة. قال ابن أبى حاتم: \"سمعت أبى يقول: قلت لأبى حصين هل لك اسم؟ قال: لا. اسمى وكنيتى واحد. فقلت له: فأنا اسميك عبد اللَّه فتبسم. وسئل عنه أبى فقال: صدوق ثقة (٣)."],[10434,"١٥٤٩ - الجرح (٤/ ٢/ ٣٦٤)، وقال: سمعت أبى يقول: هو صدوق، كنى ابن منده (٩٥/ أ) وذكر أن اسمه أحمد بن يونس، تهذيب الكمال (٣/ ١٥٩٩)."],[10435,"(١) حصين: بفتح الحاء كسر الصاد. الاكمال (٢/ ٤٨٠)."],[10436,"(٢) عبثر: بفتح أوله وسكون الموحدة وفتح المثلثة، ابن القاسم، ثقة، من الثامنة. التقريب (١/ ٤٠٠)."],[10437,"١٥٥٠ - الجرح (٤/ ٢/ ٣٦٤)، تهذيب الكمال (٣/ ١٥١٩)، التهذيب (١٢/ ٧٥)، التقريب (٢/ ٤١٢) وقال: ثقة، من العاشرة. قيل: اسمه عبد اللَّه./ د."],[10438,"(٣) الجرح (٤/ ٢/ ٣٦٤)."],[10439,"باب افراد في الحاء"],[10440,"١٥٥١ - أبو حاتم. روى أن عمر بن عبد العزيز مرض فأتى بطبيب ينظر فيه فقال له: داء ليس له دواء وأغلب الخوف على قلبه (١). روى عنه حكام بن سلم."],[10441,"١٥٥٢ - أبو حَرِيز (٢) المَوْقِفِى (٣) المصرى، والموقف محلة بفسطاط مصر سكنها فنسب إليها. روى عن محمد بن كعب القرظى. روى عنه ابن وهب وسعيد بن كثير بن عفير (٤) وأبو هارون البكاء نزيل قزوين. قال أبو حاتم: لا يوقف له على اسم وهو منكر الحديث (٥)."],[10442,"١٥٥٣ - أبو حفصه مولى عائشة. روى عنه يحيى بن أبى كثير."],[10443,"١٥٥١ - كنى الحاكم (١/ ١٠٦/ ب)."],[10444,"الخبر أخرجه أبو أحمد الحاكم (١/ ١٠٦/ ب) من طريق أبى عبد الرحمن حكام بن سلم الكنانى عن أبى حاتم. فذكره. وبنحو هذا أخرجه ابن الجوزى في سيرة عمر بن عبد العزيز (ص ٢٣٩)."],[10445,"١٥٥٢ - الجرح (٤/ ٢/ ٣٦٢)، الميزان (٤/ ٥١٤)."],[10446,"(٢) حريز: أوله جاء مهملة وراء مكسورة وآخره زاى. الاكمال (٢/ ٨٥)."],[10447,"(٣) الموقفى: بفتح الميم وسكون الواو كسر القاف وفى آخرها فاء نسبة إلى الموقف وهو محلة بفسطاط مصر. اللباب (٣/ ٢٧١). وقال الذهبى: منسوب إلى موقف الدواب. انظر مصادر الترجمة. وانظر أيضا مراصد الاطلاع (٣/ ١٣٣٥)."],[10448,"(٤) سعيد بن كثير بن عفير، بالمهملة والفاء، مصغرا، وقد ينسب لجده، صدوق عالم بالانساب وغيرها، من العاشرة (ت: ٢٢٦) التقريب (١/ ٣٠٤)."],[10449,"(٥) الجرح (٤/ ٢/ ٣٦٢)."],[10450,"١٥٥٣ - كنى البخارى (ص ٢٦)، الجرح (٤/ ٢/ ٣٦٣)، الميزان (٤/ ٥١٦) التهذيب (١٢/ ٧٦)، تعجيل المنفعة (ص ٣١٣)، التقريب (٢/ ٤١٣)، وقال: مقبول، من الثالثة. س."],[10451,"١٥٥٤ - أبو حنظلة الحذاء. روى عن ابن عمر. وقيل: أنه روى عن عمر. روى عنه إسماعيل بن أبى خالد، ومالك بن مغول قال أبو زرعة: هو كوفى لا اعرف اسمه (١)."],[10452,"١٥٥٥ - أبو حكيم البارقى (٢). روى عن ابن عباس. روى عنه السّدى."],[10453,"١٥٥٦ - أبو الحَوارى (٣) مولى عبد اللَّه بن شقيق. سمع أنسا."],[10454,"١٥٥٧ - أبو حيّان (٤). سمع عبد اللَّه بن ذكوان. روى عنه إسماعيل بن عليه."],[10455,"١٥٥٨ - أبو الحُبَاب (٥). قال: لما دفن قتادة جابر بن زيد قال: اليوم دفن اعلم أهل الأرض (٦). روى عنه محمد بن سوا."],[10456,"١٥٥٤ - كنى البخارى (ص ٢٦)، كنى مسلم (ص ٣٣٢)، غنى الحاكم (١/ ١٢٨/ أ)، الجرح (٤/ ٢/ ٣٦٣)، كنى ابن منده (١٠٠/ أ)، وقال: أبو حنظلة حكيم الحذاء حدث عن ابن عمر، روى عنه إسماعيل بن أبى خالد، تعجيل المنفعة (ص ٣١٥)."],[10457,"(١) انظر الجرح (٤/ ٢/ ٣٦٣)."],[10458,"١٥٥٥ - كنى مسلم (ص ١٥١٤)، كنى الحاكم (١/ ١١٥/ ب)، الميزان (٤/ ٥١٦)، اللسان (٧/ ٣٦)."],[10459,"قال الذهبى، وتبعه ابن حجر: مجهول."],[10460,"(٢) البارقى: بفتح الباء المعجمة بواحدة، كسر الراء وفى آخرها قاف نسبة إلى بارق، وهو جبل نزله الازد فيما اظن ببلاد اليمن. انظر اللباب (١/ ١٠٧)."],[10461,"١٥٥٦ - كنى البخارى (ص ٢٦)، كنى الحاكم (١/ ١١٧/ أ)."],[10462,"(٣) الحوارى: بحاء مهملة مفتوحة، وفتح الواو بلا تشديد كسر الراء، وتشديد التحتية. الاكمال (٣/ ٢١٦)."],[10463,"١٥٥٧ - كنى الحاكم (١/ ٢٠١/ أ)."],[10464,"(٤) حيّان: بالياء المثناة من تحتها."],[10465,"١٥٥٨ - كنى الحاكم (١/ ١٢٠/ ب)، كنى ابن منده (٩٧/ ب) وقال: غير مسمى."],[10466,"(٥) الحباب: بالضم وبالموحدتين الأولى خفيفة. تبصير المنتبه (١/ ٣٩٢)."],[10467,"(٦) أخرج هذا الخبر أبو أحمد الحاكم في الكنى (١/ ١٢٠/ ب)، وأبو نعيم في ="],[10468,"١٥٥٩ - أبو حَثْمة (١). عن أمه (٢) عن النبى عليه السلام."],[10469,"١٥٦٠ - أبو حيّة بن قيس الوادعى الهمدانى، عن على رضي الله عنه. روى عنه أبو إسحاق السبيعى والمنهال بن عمرو."],[10470,"١٥٦١ - أبو حميرة. روى عنه طلحة بن يحيى التيمى."],[10471,"١٥٦٢ - أبو حُكَيْمة (٣) الجمّال. سمع سعيد بن المسيب. روى عنه قرة ابن خالد. ذكر إسحاق بن منصور عن يحيى بن معين انه قال: أبو حكيمة ثقة (٤)."],[10472,"١٥٦٣ - أبو حرملة. عن معاذ بن جبل. روى عنه يزيد بن خصيفة."],[10473,"١٥٦٤ - أبو حنُيَنْ (٥) بن عبد اللَّه بن حنين أخو إبراهيم بن عبد اللَّه بن"],[10474,"= الحلية (٣/ ٨٦)، وعزاه ابن حجر في التهذيب (٢/ ٣٨) لأحمد في الزهد. وفيه عنده \"اليوم مات أعلم أهل العراق\". وأخرجه أيضًا الذهبى في سير أعلام النبلاء (٤/ ٤٨٢) وفيه أيضا لفظ \"اعلم أهل العراق\" أو عالم أهل العراق\"."],[10475,"١٥٥٩ - كنى الحاكم (١/ ١٢٣/ أ)."],[10476,"(١) حثمة: بمفتوحة وسكون مثلثة المغنى (ص ٢٠)."],[10477,"(٢) قال الحاكم: أبو حثمة عن أمه قال النبى -صلى الله عليه وآله وسلم- \"ارقى برقيتك\"."],[10478,"١٥٦٠ - تقدم انظر الترجمة (١٥٢٣) والتعليق عليها."],[10479,"١٥٦١ - كنى الحاكم (١/ ١٢٨/ ب)."],[10480,"١٥٦٢ - كنى البخارى (ص ٢٦)، الجرح (٤/ ٢/ ٣٦٣)."],[10481,"(٣) حُكَيْمة: بضم الحاء وفتح الكاف. الاكمال (٢/ ٤٩٥)."],[10482,"(٤) الجرح (٤/ ٢/ ٣٦٣)."],[10483,"١٥٦٣ - كنى الحاكم (١/ ١٢٩/ أ)."],[10484,"١٥٦٤ - كنى البخارى (ص ٢٦)، كنى الحاكم (١/ ١٢٨/ ب)، الجرح (٤/ ٢/ ٣٦٣)، الاكمال (٢/ ٢٦)، كنى ابن منده (١٠١/ أ)."],[10485,"(٥) حنين: بحاء مهملة مضمومة وبعدها نون مفتوحة بعدها ياء ساكنة معجمة باثنتين من تحتها وآخره نون. الاكمال (٢/ ٢٥)."],[10486,"حنين. (روى عن بنت أخيه (١). قلابة الشاعرة عن خالها) (٢). روى عنه عبد اللَّه ابن يوسف التنيسى (٣)."],[10487,"١٥٦٥ - أبو حَرْمل (٤) عن عبادة بن الوليد. روى عنه إسرائيل."],[10488,"١٥٦٦ - أبو حىّ (٥) المؤذن. سمع ثوبان. روى عنه راشد بن سعد، ويزيد ابن شريح (٦)."],[10489,"(١) لم أقف عليها."],[10490,"(٢) هكذا في الأصل \"روى عن بنت أخيه قلابة الشاعرة عن خالها\" وفى كنى البخارى \"روى عن بنت أخيه عن خالد الشاعر\". وفى الجرح \"عن بنت أخيه عن خاله ابن الشاعر\" وفى الاكمال \"عن بنت أخيه عن خالها ابن الشاعر\" وفى كنى الحاكم \"عن أبنة أخيه عن خالها ويقال له: ابن الشاعر\" وقد ترجم ابن أبى حاتم لابن الشاعر هذا وقال: \"سمعت أبى يقول: هو مجهول\". انظر الجرح (٤/ ٢/ ٣٢٢)."],[10491,"(٣) ثقة متقن، من أثبت الناس في الموطأ، من كبار العاشرة. التقريب (١/ ٤٦٣)."],[10492,"١٥٦٥ - كنى الحاكم (١/ ١٢٩/ أ)، كنى ابن منده (٩٩/ ب)."],[10493,"(٤) حرمل: بفتح الحاء المهملة وسكون الراء. الاكمال (٢/ ٤٤٣)."],[10494,"١٥٦٦ - كنى البخارى (ص ٢٦)، كنى الحاكم (١/ ١٢١/ ب)، الثقات (٥/ ٥٧٩)، الجرح (٤/ ٢/ ٣٦٤)، كنى ابن منده (٩٩/ أ)."],[10495,"هكذا ذكره ابن عبد البر هنا فيمن لا يعرف لهم أسماء، وقد ذكره البخارى، والحاكم، وابن حبان، وابن أبى حاتم أيضا فيمن لم يوقف على اسمائهم. وقد ذكره ابن حجر في التهذيب (٤/ ٣١٥ - ٣١٦) في باب شداد فقال \"شداد بن حى أبو حى الحمصى المؤذن. روى عن ثوبان. . وعنه يزيد بن شريح بن مسلم وراشد بن سعد\". اهـ."],[10496,"(٥) حىّ: ضد ميت. المغنى (ص ٢٥)."],[10497,"(٦) يزيد بن شريح الحضرمى الحمصى، مقبول، من الثالثة، وروايته عن نعيم بن همّام مرسلة. التقريب (٢/ ٣٦٦)."],[10498,"١٥٦٧ - (أبو خمير) (١). عن كعب. قال: \"المطر زوج الأرض\" (٢). روى عنه يحيى بن هانئ."],[10499,"١٥٦٧ - كنى البخارى (ص ٢٦)، كنى الحاكم (١/ ١٢٩/ أ)، الاكمال (٢/ ٥٢٢)، كنى ابن منده (١٠٠/ ب) وذكره في الحاء المهملة."],[10500,"(١) في الأصل \"حمير\" بالحاء المهملة وكذا هو في كنى ابن منده، والتصحيح عن بقية المصادر وخمير: أوله خاء معجمة مضمومة بعدها ميم مفتوحة خفيفة الاكمال (٢/ ٥١٩)."],[10501,"(٢) أخرجه البخارى في الكنى (ص ٢٦) وأبو أحمد الحاكم في الكنى (١/ ١٢٩/ أ)، وابن ماكولا في الاكمال (٢/ ٥١٩)، كلهم أخرجوه من طريق يحيى بن هانئ عن أبى خمير عن كعب به."],[10502,"حرف الخاء"],[10503,"باب أبى خالد"],[10504,"١٥٦٨ - أبو خالد البزار. روى عن أبى هريرة. روى عنه ابنه سليمان بن أبى خالد (١)."],[10505,"١٥٦٩ - أبو خالد. روى عن ابن عباس. روى عنه إسماعيل بن حماد بن أبى سليمان (٢)."],[10506,"١٥٧٠ - أبو خالد وليس بالواسطى. روى عن أنس. روى عنه منْدِل بن على العنزى (٣)."],[10507,"١٥٧١ - أبو خالد الفارسى، مولى عمر بن عبد العزيز، كان رجلًا صالحا اعتقه عمر بن عبد العزيز."],[10508,"١٥٦٨ - كنى البخارى (ص ٢٧)، كنى الحاكم (١/ ١٣٦/ أ)، الجرح (٤/ ٢/ ٣٦٥)."],[10509,"(١) سليمان بن أبى خالد: ذكره ابن حجر في اللسان (٣/ ٨٣) وقال: شيخ للقعنبى لا يعرف."],[10510,"١٥٦٩ - كنى البخارى (ص ٢٧)، كنى الحاكم (١/ ١٣٦/ أ)، كنى ابن منده (١٠١/ ب)، الثقات (٥/ ٥٦٣)، الجرح (٤/ ٢/ ٣٦)، اللسان (٧/ ٤١)."],[10511,"(٢) إسماعيل بن حماد بن أبى سليمان الاشعرى، كوفى، صدوق، من الثامنة. التقريب (١/ ٦٨)."],[10512,"١٥٧٠ - الجرح (٤/ ٢/ ٣٦٦)."],[10513,"(٣) مَندل: مثلث الميم ساكن الثانى، ابن على العنزى، بفتح المهملة والنون ثم زاى -يقال: اسمه عمرو، ومندل لقب، ضعيف من السابعة (١٠٣ - ١٦٧ أو ١٦٨). انظر التقريب (٢/ ٢٧٤)."],[10514,"١٥٧١ - كنى الحاكم (١/ ١٣٧/ أ)."],[10515,"١٥٧٢ - أبو خالد البزاز (١). روى عن كلاب بن عمرو (٢). روى عنه القاسم ابن عبد الكريم (٣)."],[10516,"١٥٧٣ - أبو خالد عن أبى عطاء (٤) مولى عتبة بن أبى سفيان (٥). روى عنه والد العتبى."],[10517,"١٥٧٤ - أبو خالد مولى الأنصار، مصرى، روى عنه بكر بن سوادة."],[10518,"١٥٧٥ - أبو خالد الاسدى، مولى بنى الصباح، مدنى له رواية عن سعد (٦)."],[10519,"١٥٧٢ - كنى البخارى (ص ٢٧)، كنى الحاكم (١/ ١٣٦/ أ)، الجرح (٤/ ٢/ ٣٦٦) كنى ابن منده (١٠٢/ أ)."],[10520,"(١) في كنى البخارى (القزاز أو البزاز)."],[10521,"(٢) كلاب بن عمرو بن خالد بن عرفطة الزهرى، ترجمته في الجرح (٣/ ٢/ ١٧١)."],[10522,"(٣) القاسم بن عبد الكريم العرفطى، ترجم له ابن أبى حاتم في الجرح (٣/ ٢/ ١١٤) وقال هو من ولد خالد بن عرفطه. روى عن كلاب بن عمرو وأبى خالد البزاز. الخ."],[10523,"١٥٧٣ - كنى الحاكم (١/ ١٣٧/ أ)، كنى ابن منده (١٠٣/ أ)."],[10524,"(٤) أبو عطاء مولى عتبة بن أبى سفيان: يأتى في (٢٢٣٢) وذكر ابن عبد البر في ترجمته هناك أنه روى عنه أبو خالد."],[10525,"(٥) عتبة بن أبى سفيان الاموى، ولد على عهد النبى -صلى الله عليه وآله وسلم- وولاه عمر الطائف. . . وولى مصر، سنة. انظر التجريد (١/ ٣٧٨)"],[10526,"١٥٧٤ - كنى الحاكم (١/ ١٣٦/ أ)، كنى ابن منده (١٠١/ ب)."],[10527,"١٥٧٥ - كنى الحاكم (١/ ١٣٦/ ب)، كنى ابن منده (١٠١/ ب)."],[10528,"(٦) هو أبو سعيد سعد بن مالك الخدرى، كما صرح بذلك أبو أحمد الحاكم. انظر مصادر الترجمة."],[10529,"باب أبى الخطاب"],[10530,"١٥٧٦ - أبو الخطاب، مصرى. روى عن أبى سعيد الخدرى، روى عنه مرشد بن عبد اللَّه أبو الخير اليزنى."],[10531,"١٥٧٧ - أبو الخطاب الهجرى. روى عنه ابن (أبى) (١) غنيّة (٢) وعلى بن عابس."],[10532,"١٥٧٨ - أبو الخطاب. عن أبى زرعة (٣). روى عنه ليث بن أبى سليم. هو عندهم مجهول."],[10533,"١٥٧٦ - كنى البخارى (ص ٢٧)، كنى الحاكم (١/ ١٣٩/ أ)، كنى ابن منده (١٠٤/ ب)، الجرح (٤/ ٢/ ٣٦٤)، الميزان (٤/ ٥٢٠)، التهذيب (١٢/ ٨٦)، التقريب (٢/ ٤١٧) وقال: مجهول من الثالثة./ س."],[10534,"١٥٧٧ - كنى البخارى (ص ٢٧)، الجرح (٤/ ٢/ ٣٦٥)، اللسان (٧/ ٨٦) التهذيب (١٢/ ٨٦)، تهذيب الكمال (٣/ ١٠٦٢)، التقريب (٢/ ٤١٧) وقال: اسمه عمرو، وقيل: عمر، مجهول، من السابعة/ ق."],[10535,"(١) لم تكن في الأصل والمثبت عن مصادر الترجمة."],[10536,"(٢) غنيّة: بفتح المعجمة كسر النون وتشديد التحتانية. الاكمال (٦/ ١١٩) واسم ابن أبى غنية هذا عبد الملك بن حميد بن أبى غنية، ثقة، من السابعة، انظر التقريب (١/ ٥١٨)."],[10537,"١٥٧٨ - كنى البخارى (ص ٢٧)، كنى الحاكم (١/ ١٣٩/ أ)، الجرح (٤/ ٢/ ٣٦٥) الميزان (٤/ ٥٢٠)، التهذيب (١٢/ ٨٦)، كنى ابن منده (١٠٤/ ب) التقريب (٢/ ٤١٧) وقال: مجهول، من السادسة./ ت."],[10538,"(٣) هو هرم بن عمر بن جرير. كما صرح بذلك ابن أبى حاتم وأبو أحمد الحاكم. انظر مصادر الترجمة."],[10539,"باب أبى خلف"],[10540,"١٥٧٩ - أبو خلف المكى. دخل مع عبيد بن عمير (على) (١) عائشة."],[10541,"حديثه عند يزيد بن هارون عن صخر بن جويرية (٢) عن إسماعيل بن مسلم المكى عنه في قوله ﴿يُؤْتُونَ مَا آتَوْا﴾ (٣) (٤) الآية."],[10542,"١٥٧٩ - كنى الحاكم (١/ ١٤٠/ ب)، الجرح (٤/ ٢/ ٣٦٦)، تعجيل المنفعة (ص ٣١٦)، اللسان (٧/ ٤٢)، كنى البخارى (ص ٢٨)."],[10543,"(١) في الأصل \"عن\"، والتصحيح عن مصادر الترجمة."],[10544,"(٢) صخر بن جويرية أبو نافع، وثقة أحمد، وقال القطان: ذهب كتابه ثم وجده فتكلم فيه لذلك، من السابعة، التقريب (١/ ٣٦٥)."],[10545,"(٣) سورة المؤمنون: ٦٠. والآية كاملة كالآتى: ﴿وَالَّذِينَ يُؤْتُونَ مَا آتَوْا وَقُلُوبُهُمْ وَجِلَةٌ أَنَّهُمْ إِلَى رَبِّهِمْ رَاجِعُونَ﴾."],[10546,"(٤) الحديث أخرجه أحمد (٦/ ٩٥) من طريق عفان ثنا صخر بن جويرية قال: ثنا إسماعيل المكى قال: حدثنى أبو خلف مولى بنى جمح أنه دخل مع عبيد بن عمير على عائشة أم المؤمنين في سقيفة زمزم، ليس في المسجد ظل غيرها، فقالت: مرحبا واهلا بأبى عاصم -يعنى عبيد بن عمير- ما يمنعك أن تزورنا أو تلم بنا؟ فقال: أخشى أن أملك. فقالت: ما كنت تفعل. قال: جئت أن أسألك عن آية في كتاب اللَّه عز وجل. كيف كان رسول اللَّه -صلى الله عليه وآله وسلم- يقرؤها؟ فقالت: آية آية؟ فقال: ﴿الَّذِينَ يُؤْتُونَ مَا آتَوْا﴾ أو ﴿الذين يأتون ما أتوا﴾؟ فقالت: أيتهما أحب إليك؟ قال: قلت: والذى نفسى بيده لإحداهما أحب إلى من الدنيا جميعًا أو الدنيا وما فيها. قالت: ايتهما؟ قلت: ﴿الذين يأتون ما أتوا﴾. قالت: أشهد أن رسول اللَّه -صلى الله عليه وآله وسلم- كذلك كان يقرؤها، وكذلك أنزلت. أو قالت: أشهد لكذلك أنزلت، وكذلك كان رسول اللَّه -صلى الله عليه وآله وسلم- يقرؤها ولكن الهجاء حرف. ="],[10547,". . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . ."],[10548,"= وأخرجه أيضًا أحمد (٦/ ١٤٤) من طريق يزيد، أنا صخر بن جويرية به. والحديث ذكره الهيثمى في مجمع الزوائد (٧/ ٧٢ - ٧٣) وعزاه لأحمد. وقال: فيه إسماعيل بن مسلم المكى وهو ضعيف."],[10549,"وأخرجه أيضًا البخاى في الكنى (ص ٢٨) من طريق يزيد بن هارون عن ابن جويرية به. لكن قال: في إسناده \"عن إسماعيل بن أمية\"."],[10550,"وأخرجه ابن أبى حاتم في الجرح (٤/ ٢/ ٣٦٦) من طريق يزيد بن هارون به، والحاكم في الكنى (١/ ١٤٠/ ب) من طريق يزيد بن هارون عن صخر ابن جويرية عن إسماعيل بن أمية به وقد تابع عفانَ ويزيدَ بن هارون عبد الوهاب بن عطاء حيث روى هذا الحديث عن صخر بن جويرية عن أبى خلف به أخرجه أبو العباس السراج في تفسيره كما ذكر الحاكم في الكنى (١٤٠/ ب)، وتابع إسماعيل المكى على روايته عن أبى خلف طلحة بن عمرو المكى، أخرجه إسحاق بن راهوية في مسنده عن عبد اللَّه بن نمير عن طلحة كما في كنى الحاكم أيضًا. وانظر أيضًا تعجيل المنفعة (ص ٣١٦) وأخرجه أيضًا الحاكم في الكنى من طريق وكيع عن طلحة بن عمرو المكى عن أبى خلف به. وقال الحافظ ابن حجر في تعجيل المنفعة (ص ٣١٦) فصار أبو خلف بذلك مشهورا بعد أن كان مجهولا، لكن بقى بيان حاله. أهـ."],[10551,"والحديث أخرجه أيضًا الطبرى في التفسير (١٨/ ٣٣. ط - حلبى) عند قوله تعالى ﴿وَالَّذِينَ يُؤْتُونَ. .﴾ من طريق طلحة بن عمر عن أبى خلف قال: دخلت مع عبيد بن عمير على عائشة. . الخ وفيه أنها قالت: \"يأتون ما أتوا\" قال الطبرى. وكأنها تأولت في ذلك والذين يفعلون ما يفعلون من الخيرات وهم وجلون من اللَّه."],[10552,"وأخرجه كذلك السيوطى في الدر المنثور (٥/ ١٢) من حديث عبيد بن عمير أنه سأل عائشة رضي الله عنها. . الخ ونسبه السيوطى إلى سعيد بن منصور وأحمد والبخارى في التاريخ وعبد بن حميد وابن المنذر وابن اشته وابن الانبارى معا في المصاحف، الدارقطنى في الأفراد والحاكم وصححه، وابن مردويه. اهـ. = ١٥٨٠ - أبو خلف. قال: كنت في جيش ابن الزبير أو حرس ابن الزبير (١). روى عنه ابن جريج."],[10553,"١٥٨١ - أبو خلف عن الحارث بن عميرة الحارثى (٢). سمع معاذا باليمن."],[10554,"= قلت: ولم أقف عليه في مطبوعة المستدرك من طريق عبيد بن عمير بهذا اللفظ. وإنما رواه الحاكم من وجه آخر من حديث عائشة رضي الله عنها بنحو لفظه. انظر المستدرك (٢/ ٣٩٣ - ٣٩٤) وقال: صحيح الإسناد ولم يخرجاه ووافقه الذهبى."],[10555,"وأخرجه أيضًا ابن كثير في التفسير (٣/ ٢٤٨) من طريق أحمد به وقال: فيه إسماعيل بن مسلم المكى وهو ضعيف. اهـ."],[10556,"قلت: وبالنظر إلى سند هذا الحديث نلاحظ أن فيه عند ابن عبد البر \"إسماعيل بن مسلم المكى\" وكذا جاء في سنده في الجرح، وفى مجمع الزوائد حيث قال الهيثمى عند الكلام على سند حديث أحمد: فيه إسماعيل ابن مسلم المكى الخ وجاء فيه عند أحمد \"إسماعيل المكى\" وفى كنى البخارى كنى الحاكم \"إسماعيل بن أمية\" وقال ابن حجر في تعجيل المنفعة (ص ٣١٦) بعد أن ذكر رواية أحمد واعقبها بذكر رواية الحاكم لهذا الحديث: واستفدنا من هذه الرواية -يعنى رواية الحاكم- أن إسماعيل المكى وابن أمية أحد الثقات المشهورين من رجال الصحيح. وظن شيخنا الهيثمى في مجمع الزوائد له أنه إسماعيل بن مسلم المكى وليس كما ظن. أهـ."],[10557,"قلت: وليس الهيثمى هو أول من قال بهذا، وإنما سبقه ابن عبد البر وابن أبى حاتم. كما سبق وإن عرفت. واللَّه أعلم."],[10558,"١٥٨٠ - كنى البخارى (ص ٢٧)، كنى الحاكم (١/ ١٤٠/ ب)، الجرح (٤/ ٢/ ٣٦٧)، كنى ابن منده (١٠٥/ ب)."],[10559,"(١) الخبر: أخرجه البخارى في الكنى، والحاكم في الكنى، وابن أبى حاتم في الجرح، وابن منده في الكنى كلهم أخرجوه من طريق ابن جريج عن أبى خلف به."],[10560,"١٥٨١ - كنى البخارى (ص ٢٨)، كنى ابن منده (١٠٥/ ب)، كنى الحاكم (١/ ١٤١/ أ)، الجرح (٤/ ٢/ ٣٦٦)."],[10561,"(٢) له ترجمة في الجرح (١/ ٢/ ٨٣)."],[10562,"١٥٨٢ - أبو خلف، الكوفى. عن يعقوب بن عبد اللَّه. روى عنه عيسى بن يونس."],[10563,"١٥٨٣ - أبو خلف مولى عمرو بن العاص. عن عمرو بن العاص. روى عنه خالد (١). رجل مجهول."],[10564,"١٥٨٤ - أبو خلف. سمع جابر بن عبد اللَّه. روى عنه شبل بن عبّاد (٢)."],[10565,"١٥٨٥ - أبو خلف عن أنس."],[10566,"= والترهيب (٤/ ١٢٣): رواه أحمد بإسناد جيد ورواته ثقات مشهورون، والبزار بنحوه. اهـ. وحديث أنس أخرجه أيضًا الماوردى في أعلام النبوة (ص ١٢٠)."],[10567,"١٥٨٢ - كنى الحاكم (١/ ١٤١/ أ)، كنى ابن منده (١٠٦/ أ)."],[10568,"١٥٨٣ - كنى الحاكم (١/ ١٤١/ أ)، كنى ابن منده (١٠٥/ ب)."],[10569,"(١) قال أبو أحمد الحاكم في الكنى (١/ ٤١/ أ) في ترجمة أبى خلف، روى عنه خالد غير منسوب وهو عبدى. اهـ."],[10570,"١٥٨٤ - كنى الحاكم (١/ ١٤١/ أ)."],[10571,"(٢) شبل بن عباد المكى القارئ، ثقة، رمى بالقدر، من الخامسة، التقريب (١/ ٣٤٦)."],[10572,"١٥٨٥ - كنى ابن منده (١٠٥/ ب)، كنى الحاكم (١/ ١٤٠/ ب) وقال أبو خلف عن أنس قال النبى -صلى الله عليه وآله وسلم-: \"أن اللَّه يغضب إذا مدح الفاسق\" والحديث أخرجه أيضًا أبو نعيم في ذكر أخبار أصبهان (٢/ ٢٧٧) من طريق أبى خلف الأعمى، عن أنس مرفوعًا به. والبيهقى في شعب الإيمان من حديث أنس كما في الفتح الكبير (١/ ٣٥٩)."],[10573,"سمع النبى عليه السلام قال: \"لو كنت آمرا أحدًا أن يسجد لأحد أمرت المرأة أن تسجد لزوجها\" (١)."],[10574,"(١) الحديث أخرجه البخارى في الكنى، وأبو أحمد الحاكم في الكنى، من طريق أبى خلف، عن الحارث بن عميرة عن معاذ يرفعه به. وفيه عندهما لفظ \"لو يصلح لاحد أن يسجد لاحد. . \" الخ. انظر مصادر الترجمة. وأخرجه أيضًا أحمد (٥/ ٢٢٧)، وابن أبى شيبة (٤/ ٣٠٥) من طريق وكيع عن الأعمش، عن أبى ظبيان عن معاذ بن جبل أنه لما رجع من اليمن قال: يا رسول اللَّه رأيت رجالا باليمن يسجد بعضهم لبعض، أفلا نسجد لك؟ قال: لو كنت آمرا بشرا يسجد لبشر لأمرت المرأة أن تسجد لزوجها."],[10575,"قال الشيخ الألبانى في إرواء الغليل (٧/ ٥٧): هذا إسناد رجاله كلهم ثقات رجال الشيخين، لكن أبو ظبيان لم يسمعه من معاذ واسمه حصين بن جندب الجنبى الكوفى."],[10576,"وقد روى الحديث أيضًا أحمد (٥/ ٢٢٨) وابن أبى شيبة (٤/ ٣٠٥) من طريق ابن نمير، ثنا الأعمش قال: سمعت أبا ظبيان يحدث عن رجل من الأنصار عن معاذ بن جبل قال: أقبل معاذ من اليمن فقال: يا رسول اللَّه إنى رأيت رجالا فذكر معناه."],[10577,"قلت: وهذا يؤيد ما ذكره الشيخ الألبانى في أن الحديث منقطع، وبين أبى ظبيان ومعاذ رجل مجهول غير مسمى. واللَّه أعلم."],[10578,"وحديث معاذ هذا أخرجه أيضًا ابن أبى حاتم في العلل (١/ ٤٢٦) من طريق عبد الرحمن بن أبى ليلى عن معاذ بن جبل يرفعه بمثله. وزاد لفظ \"من عظم حقه عليها\"."],[10579,"ويشهد لحديث معاذ بن جبل حديث عبد اللَّه بن أبى أوفى قال: لما قدم معاذ من الشام سجد للنبى قال: \"ما هذا يا معاذ؟ ! . . وفيه فلا تفعل فإنى لو كنت أمرا أحدا أن يسجد لغير اللَّه لأمرت. . . \" الخ."],[10580,"أخرجه ابن أبى حاتم في العلل (١/ ٤٢٦)، ابن ماجه \"النكاح\" باب حق الزوج على المرأة (١/ ٥٩٥) وابن حبان كما في موارد الظمآن (ص ٣١٤)، والحاكم (٤/ ١٧٢) وقال: صحيح على شرط الشيخين ولم يخرجاه ووافقه الذهبى، والبيهقى (٧/ ٢٩٢)، وأحمد (٤/ ٣٨١) والبزار. كما في = . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . ."],[10581,"= كشف الأستار (٢/ ١٧٦) وقال الهيثمى في مجمع الزوائد (٤/ ٣٠٩) رواه بتمامه البزار، وأحمد باختصار، ورجاله رجال الصحيح، وكذلك طريق من طرق أحمد، وروى الطبرانى بعضه أيضًا. اهـ."],[10582,"وحديث زيد بن ارقم، أخرجه البزار كما في كشف الأستار (٢/ ١٧٩) من طريق صدقة بن عبد اللَّه، عن سعيد بن أبى عروبة، عن قتادة، عن القاسم الشيبانى وهو ابن عوف، عن زيد بن ارقم قال: بعث رسول اللَّه -صلى الله عليه وآله وسلم- معاذ بن جبل إلى الشام فلما قدم معاذ قال: يا رسول اللَّه رأيت أهل الكتاب يسجدون لأساقفتهم وبطارقهم أفلا نسجد لك؟ \"قال لو كنت آمرا. . . \" الخ."],[10583,"وذكر الهيثمى هذا الحديث في مجمع الزوائد (٤/ ٣١٠) وقال: رواه البزار والطبرانى في الكبير والأوسط، وأحد اسنادى الطبرانى رجاله رجال الصحيح، خلا صدقة بن عبد اللَّه السمين، وثقه أبو حاتم وجماعة وضعفه البخارى وجماعة."],[10584,"وحديث أبى هريرة رضي الله عنه أخرجه الترمذى (٤/ ٣٢٣) بمثل حديث معاذ وقال الترمذى: وفى الباب عن معاذ بن جبل، وسراقة بن مالك بن جشعهم، وعائشة، وابن عباس، وعبد اللَّه بن أبى أوفى وطلق بن على، وأم سلمة، وأنس، وابن عمر. وقال أيضًا: حديث أبى هريرة حديث حسن غريب. اهـ. وأخرج حديث أبى هريرة أيضًا ابن حبان كما في موارد الظمآن (ص ٣١٤)، والبيهقى (٧/ ٢٩١)، والبزار كما في كشف الأستار (٢/ ١٧٨)، والحاكم (٤/ ١٧١ - ١٧٢) وهو عند البزار والحاكم من طريق سليمان بن داود اليمامى، عن يحيى بن أبى كثير، وأبى سلمة عن أبى هريرة وللحديث عندهما قصة. وقال البزار: سليمان بن داود لين ولم يتابع على هذا. وقال الحاكم: صحيح الإسناد ولم يخرجاه. وتعقبه الذهبى فقال: سليمان هو اليمامى ضعفوه."],[10585,"ويشهد لهذا الحديث أيضًا حديث أنس رضي الله عنه أخرجه أحمد (٣/ ١٨٥) والبزار كما في مجمع الزوائد (٤١٩) وقال الهيثمى: رجاله رجال الصحيح غير حفص بن أخى أنس وهو ثقة أهـ. وقال المنذرى في الترغيب ="],[10586,"باب أبى الخليل"],[10587,"١٥٨٦ - أبو الخليل، عن سلمان الفارسى كوفى، روى عنه برذعه (١) بن عبد الرحمن، وقد قيل: أن أبا الخليل هذا هو عبد اللَّه بن الخليل (٢) الذى روى عن على. روى عنه أبو إسحاق وأكثرهم عن أبى إسحاق. لا يسمون أبا الخليل عن على رضي الله عنه."],[10588,"١٥٨٧ - أبو الخليل. عن ابن عباس. روى عنه الأعمش، وإسماعيل بن رجاء."],[10589,"١٥٨٨ - أبو الخليل، روى عن الشعبى. روى عنه يحيى بن زكريا بن أبى زائدة. لم يعرفه أبو زرعة."],[10590,"١٥٨٦ - كنى الحاكم (١/ ١٤٢/ أ)، كنى ابن منده (١٠٦/ ب)، وقال: حديثه عن سلمان مرسل."],[10591,"(١) برذعة بن عبد الرحمن، ترجم له ابن حبان في المجروحين (١/ ١٩٨) فقال \"يروى برذعة أحاديث مناكير لا أصول لها يهم فيها لأن الحديث لم يكن من صناعته، كان يأتى بالشئ بعد الشئ على الوهم، فلا يجوز الاحتجاج بخبره\". وانظر ترجمته أيضًا في اللسان (٢/ ٧)."],[10592,"(٢) عبد اللَّه بن الخليل: أو ابن أبى الخليل الحضرمى، أبو الخليل الكوفى، مقبول، من الثانية، وفرق البخارى وابن حبان الراوى عن على فقال فيه ابن أبى الخليل، وبين الراوى عن زيد بن ارقم فقال فيه ابن الخليل. التقريب (١/ ٤١٢)."],[10593,"١٥٨٧ - كنى البخارى (ص ٢٧)، كنى الحاكم (١/ ١٤١/ ب)، الجرح (٤/ ٢/ ٣٦٦)."],[10594,"١٥٨٨ - الجرح (٤/ ٢/ ٣٦٦). وقال: سئل أبو زرعة عنه فقال: لا أعرفه."],[10595,"باب افراد في الخاء"],[10596,"١٥٨٩ - أبو خُشَيْنة (١). روى عن ابن عمر \"أنه راه يبول قائما\" (٢) قيل: هو مولى الأحنف بن قيس. روى عنه أبو عوانة."],[10597,"١٥٨٩ - كنى ابن منده (١٠٨/ أ)، اللسان (٧/ ٤١)."],[10598,"(١) خشينة: بخاء معجمة مضمومة وبعدها شين مفتوحة وبعدها ياء معجمة باثنتين من تحتها ساكنة وبعدها نون معجمة بواحدة من فوقها مفتوحة. الاكمال (٢/ ١٠٥)."],[10599,"(٢) أخرجه ابن أبى شيبة (١/ ١٢٣) من طريق عبد اللَّه الرومى قال: رأيت ابن عمر يبول قائما. وروى ابن أبى شيبة أيضًا أن عمر وعليا وزيد بن ثابت، وأبا هريرة رضي الله عنهم أنهم كانوا يفعلون مثل هذا."],[10600,"وقد جاء في حديث حذيفة رضي الله عنه أن النبى -صلى الله عليه وآله وسلم- \"انتهى إلى سباطة قوم فبال قائما\"."],[10601,"أخرجه البخارى \"الوضوء\" باب البول قائما وقاعدا (١/ ٣٢٨) وفى باب البول عند صاحبه والتستر بالحائط (١/ ٣٢٩). وفى باب البول عند سباطة القوم (١/ ٣٢٩). وفى \"كتاب المظالم\" باب الوقوف والبول عند سباطة القوم (٥/ ١١٧)، ومسلم \"كتاب الطهارة\" باب المسح على الخفين (١/ ٢٢٨) وأبو داود \"الطهارة\" باب البول قائما (١/ ٦) والترمذى \"الطهارة\" باب الرخصة في البول قائما (١/ ٦٩)، وابن ماجه \"الطهارة\" باب ما جاء في البول قائما (١/ ١١١) وابن أبى شيبة (١/ ١٢٣)."],[10602,"والدارمى (١/ ١٧١) والبيهقى (١/ ١٠٠، ٢٧٠، ٢٧٤). وأحمد في المسند (٥/ ٣٨٢ و٤٠٢ و٣٩٤)."],[10603,"السباطة: بضم السيم المهملة، بعدها موحدة هى المزبلة والكناسة تكون بفناء الدور مرفقا لأهلها وتكون في الغالب سهلة لا يرتد فيها البول على البائل واضافتها إلى القوم اضافة اختصاص لا ملك؛ لأنها لا تخلو عن النجاسة. اهـ. انظر الفتح (١/ ٣٢٨)، النهاية (٢/ ٣٣٥)"],[10604,"١٥٩٠ - أبو خَيْرة (١)، مصرى. روى عن موسى بن وردان. روى عنه سعيد ابن أبى أيوب."],[10605,"١٥٩١ - أبو الخنْساء، مصرى. سمع أبا هريرة من حديث عمرو بن الحارث عن عبد العزيز بن صالح (٢). ليس لأبى الخنساء غيره (٣)."],[10606,"١٥٩٠ - كنى البخارى (ص ٢٨)، كنى الحاكم (١/ ١٤٦/ ب)، الجرح (٤/ ٢/ ٣٦٧) اللسان (٧/ ٤٣)، تعجيل المنفعة (ص ٢٥٨) و(ص ٣١٦)، الميزان (٤/ ٥٢١)، الاكمال (٢/ ٣١)، كنى ابن مندة (١٠٨/ أ)."],[10607,"(١) خيرة: أوله خاء معجمة مفتوحة وبعدها ياء ساكنة معجمة باثنتين من تحتها وراء مفتوحة. الاكمال (٢/ ٣٠)."],[10608,"١٥٩١ - كنى الحاكم (١/ ١٤٩/ أ)، الجرح (٤/ ٢/ ٣٦٧)، اللسان (٧/ ٤٣) الميزان (٢/ ٥٢١)."],[10609,"(٢) ترجمته في الجرح (٢/ ٢/ ٣٨٥)، اللسان (٤/ ٣١)."],[10610,"(٣) الحديث أخرجه أبو أحمد الحاكم، وابن أبى حاتم، من طريق عمرو بن الحارث عن عبد العزيز بن صالح، عن أبى خنساء، أنه سمع أبا هريرة يقول \"مر رسول اللَّه -صلى الله عليه وآله وسلم- بقبرين فأخذ سعفة أو جريدة فشقها فجعل نصفها على أحدهما ونصفها على الآخر فسئل عن ذلك فقال: \"انهما يعذبان رجلًا لا يتطهّر من البول وأمراة كانت تمشى بالنميمة. . \" الحديث."],[10611,"والحديث أخرجه ابن حبان كما في موارد الظمآن (ص ١٩٩) من طريق عبد اللَّه بن الحارث عن أبى هريرة قال: كنا نمشى مع رسول اللَّه -صلى الله عليه وآله وسلم- فمررنا على قبرين. . فذكره."],[10612,"وأخرج أحمد في المسند (٢/ ٤٤١) حديثا عن أبى هريرة قال: مر رسول اللَّه -صلى الله عليه وآله وسلم- على قبر فقال: أئتونى بجريدتين فجعل أحداهما عند رأسه والأخرى عند رجليه فقيل: يا نبى اللَّه أينفعه ذلك؟ قال: لن يزال أن يخفف عنه بعض عذاب القبر ما كان فيهما ندوّ. وقال الهيثمى في مجمع الزوائد (٣/ ٥٧): رجاله رجال الصحيح. اهـ ويشهد لحديث أبى هريرة هذا: حديث ابن عباس بنحوه."],[10613,"أخرجه البخارى \"الوضوء\" باب من الكبائر أن لا يستتر من بوله (١/ ٣١٧) وفى باب ما جاء في غسل البول (١/ ٣٢٢). وفى \"كتاب = ١٥٩٢ - أبو خُشَيْنة (١)، مولى الأحنف بن قيس. روى عن الأحنف. روى عنه عوف بن أبى جميلة."],[10614,"١٥٩٣ - أبو الخير. عن عبد اللَّه بن مسعود. روى عنه أبو اسحاق الهمدانى كوفى."],[10615,"١٥٩٤ - أبو خليفة، عن على رضي الله عنه، روى عنه وهب بن منبه، حديثه في أهل اليمن."],[10616,"١٥٩٥ - أبو خِرَاش (٢). الهذلى، سمع فَضَالة بن عبيد، روى عنه عمران بن عبد الرحمن."],[10617,"١٥٩٦ - أبو خَلَّاد (٣) عن عمر بن الخطاب. روى عنه معاوية بن صالح."],[10618,"= الجنائز\" باب الجريدة على القبر (٣/ ٢٢٢ - ٢٢٣). وفى \"كتاب الأدب\" باب النميمة من الكبائر (١٠/ ٤٧٢) وأخرجه مسلم \"كتاب الطهارة\" باب الدليل على نجاسة البول ووجوب الاستبراء (١/ ٢٤٠). والنسائى \"الجنائز\" باب وضع الجريدة على القبر (٤/ ١٠٦) وأخرجه أيضًا ابن أبى شيبة (١/ ١٢٢)."],[10619,"١٥٩٢ - الحاكم (١/ ١٤٥/ ب)، كنى ابن منده (١٠٨/ أ)، الاكمال (٢/ ٤٧٢)."],[10620,"(١) انظر الضبط في الترجمة (١٥٨٩)."],[10621,"١٥٩٣ - كنى الحاكم (١/ ١٤٤/ أ)."],[10622,"١٥٩٤ - كنى الحاكم (١/ ١٤٦/ أ)، كنى ابن منده (١٠٨/ أ)."],[10623,"١٥٩٥ - كنى البخارى (ص ٢٧)، كنى ابن منده (١٠٧/ ب)، كنى الحاكم (١/ ١٤٦/ ب)، الجرح (٤/ ٢/ ٣٦٧)."],[10624,"(٢) خِرَاش: بخاء معجمة مكسورة وراء مهملة مخففة وشين معجمة. الاكمال (٢/ ٤٢٦)."],[10625,"١٥٩٦ - كنى البخارى (ص ٢٨)، كنى الحاكم (١/ ١٤٨/ ب)، كنى ابن منده (١٠٧/ ب)."],[10626,"(٣) خلّاد: بخاء مفتوحة وشدة لام واهمال دال. المغنى (ص ٢٨)."],[10627,"حرف الدال"],[10628,"باب أبى داود"],[10629,"١٥٩٧ - أبو داود، روى عن رجل (١) من أصحاب النبى عليه السلام. روى عنه عكرمه بن عمار."],[10630,"١٥٩٨ - أبو داود المدنى، سمع ابن عمر. روى عن عبد الرحمن بن القاسم (٢)."],[10631,"١٥٩٩ - أبو داود الواسطى. روى عنه شعبة. قال ابن أبى حاتم: سألت عنه أبى فقال: شيخ لشعبة مجهول (٣)."],[10632,"١٥٩٧ - كنى البخارى (ص ٢٩)، الجرح (٤/ ٢/ ٣٦٨)، الميزان (٤/ ٥٢١)، اللسان (٧/ ٤٣)، كنى الحاكم (١/ ١٥٢/ ب)، كنى ابن منده (١٠٩/ ب)."],[10633,"(١) هكذا هو هنا وفى مصادر الترجمة مبهم ولم أقف على من سماه."],[10634,"١٥٩٨ - كنى البخارى (ص ٢٩)، كنى ابن منده (١٠٩/ ب)، الثقات (٥/ ٥٧٤) الجرح (٤/ ٢/ ٣٦٨)، اللسان (٧/ ٤٣)، كنى الحاكم (١/ ١٥٢/ ب)."],[10635,"(٢) عبد الرحمن بن القاسم: هم ثلاثة ولم يتبين لى هذا أى واحد منهم."],[10636,"١٥٩٩ - الجرح (٤/ ٢/ ٣٦٨)، الميزان (٤/ ٥٢١)، اللسان (٧/ ٤٣)."],[10637,"(٣) الجرح (٤/ ٢/ ٣٦٨) في الجرح: شيخ لشعبة واسطى مجهول بزيادة لفظ \"واسطى\"."],[10638,"باب أبى الدرداء"],[10639,"١٦٠٠ - أبو الدرداء الرهاوى. عن رجل (١) من أصحاب النبى عليه السلام. ليس بالمعروف."],[10640,"١٦٠١ - أبو الدراء. سمع عائشة في إتيان القصاص (٢)."],[10641,"١٦٠٠ - كنى البخارى (ص ٢٩)، الجرح (٤/ ٢/ ٣٦٨)، الميزان (٤/ ٥٢٢) اللسان (٧/ ٤٤)، كنى الحاكم (١/ ١٤٩/ ب)، كنى ابن منده (١٠٩/ أ)."],[10642,"(١) هكذا هو مبهم هنا وكذا في مصادر الترجمة ولم أقف على من سماه."],[10643,"١٦٠١ - كنى الحاكم (١/ ١٥٠/ أ)، كنى ابن منده (١٠٩/ أ)."],[10644,"(٢) في كنى الحاكم: أبو الدرداء جار سلمة، قلت لعائشة أى القاص يدعوا رواه ابن مهدى، عن سفيان عن سلمة بن كهيل. اهـ."],[10645,"باب أبى الدهماء"],[10646,"١٦٠٢ - أبو الدّهماء. عن رسول من أهل البادية عن النبى -صلى الله عليه وآله وسلم- أنه قال \"لا تدع شيئا اتقاء اللَّه إلا أعطاك اللَّه خيرا منه\" (١)."],[10647,"١٦٠٣ - أبو الدهماء بصرى، روى عن ثابت البنانى. روى عنه عبد اللَّه بن محمد (٢)."],[10648,"١٦٠٢ - كنى الحاكم (١/ ١٥٣/ ب)، كنى ابن منده (١١٠/ ب)"],[10649,"(١) الحديث أخرجه أبو أحمد الحاكم في الكنى كما هنا. وأخرجه أحمد في المسند (٥/ ٣٦٣) عن أبى قتادة وأبى الدهماء قالا: اتينا على رجل من أهل البادية فقلنا: هل سمعت من رسول اللَّه -صلى الله عليه وآله وسلم- شيئًا؟ قال: نعم سمعته يقول: إنك لن تدع شيئًا للَّه عز وجل إلا بذلك اللَّه به ما هو خير لك منه. وعزاه الهيثمى في مجمع الزوائد (١٠/ ٢٩٦) إلى أحمد. وقال: رجاله رجال الصحيح."],[10650,"والحديث عزاه السيوطى في الجامع الكبير (١/ ٢٨) أيضًا لأحمد والبغوى والبيهقى أهـ. ولم أجده في مطبوعة السنن الكبرى للبيهقى. واللَّه أعلم."],[10651,"١٦٠٣ - كنى الحاكم (١/ ١٥٣/ ب)، كنى ابن منده (١١٠/ ب)."],[10652,"(٢) هو أبو جعفر النفيلى كما صرح بذلك الحاكم أبو أحمد."],[10653,"باب افراد في الدال"],[10654,"١٦٠٤ - أبو دهقانة. روى عن ابن عمر في الصرف (١). روى عنه فضيل بن غزوان. في الكوفيين."],[10655,"١٦٠٤ - كنى البخارى (ص ٢٩)، الثقات (٥/ ٥٨٠)، الجرح (٤/ ٢/ ٣٦٨) وقال: سئل أبو زرعة عن أبى دهقانة فقال: كوفى لا أعرف اسمه، كنى الحاكم (١/ ١٥٣/ ب)، كنى ابن منده (١١٠/ أ) وقال: أبو الدهشان وقيل أبو الدهقان. . \" فذكره."],[10656,"(١) الحديث أخرجه الحاكم أبو أحمد في الكنى (١/ ١٥٣/ ب) من طريق عبد اللَّه بن داود عن فضيل بن غزوان عن أبى دهقانه عن ابن عمر أن بلالًا ابدل صاعا من تمر بصاعين فقال له رسول اللَّه -صلى الله عليه وآله وسلم-: اردده اردده اردده."],[10657,"والحديث أخرجه أحمد في المسند (٢/ ٢١) من طريق ابن نمير ثنا فضيل -يعنى ابن غزوان- حدثنى أبو دهقانة قال: كنت جالسا عند عبد اللَّه بن عمر فقال: أتى رسول اللَّه -صلى الله عليه وآله وسلم- ضيف فقال لبلال: أئتنا بطعام فذهب بلال فأبدل صاعين من تمر بصاع من تمر جيد، وكان تمرهم دونا فأعجب النبى -صلى الله عليه وآله وسلم- التمر فقال النبى -صلى الله عليه وآله وسلم-: من اين هذا التمر؟ فأخبره أنه أبدل صاعا بصاعين فقال رسول اللَّه -صلى الله عليه وآله وسلم-: رد علينا تمرنا. اهـ."],[10658,"والحديث ذكره الهيثمى في مجمع الزوائد (٤/ ١١٢) عن ابن عمر به وعزاه إلى أحمد وأبى يعلى، والطبرانى في الكبير وقال: رجال أحمد ثقات. أهـ. وأخرج البزار من طريق منصور عن أبى حمزة، عن سعيد بن المسيب عن بلال قال: وكان عندى تمر فبعته في السوق بتمر أجود منه بنصف كيله فقدمته إلى رسول اللَّه -صلى الله عليه وآله وسلم- فقال: ما رأيت اليوم تمرا أجود منه! من أين هذا يا بلال!؟ فحدثته بما صنعت فقال: انطلق فرده على صاحبه وخذ تمرك فبعه بحنطة أو شعير ثم اشتر به من هذا التمر، ففعلت فقال رسول اللَّه -صلى الله عليه وآله وسلم-: \"التمر بالتمر مثلا بمثل والذهب بالذهب مثلا بمثل والفضة بالفضة وزنا بوزن فما كان من فضل فهو ربا\" قال البزار: رواه قيس عن أبى حمزة، عن = ١٦٠٥ - أبو دجيلة. سمع ابن عمر. روى عنه ابنه."],[10659,"١٦٠٦ - أبو درّاس (١). صاحب الحور (٢). روى عن أبى بكر وأبى بردة ابنى (أبى) (٣) موسى الاشعرى. روى عنه عبد الصمد بن عبد الوارث وغيره. قال عثمان بن سعيد الدارمى: سألت يحيى بن معين عن أبى دراس ما حاله؟"],[10660,"= سعيد بن المسيب عن عمر عن النبى -صلى الله عليه وآله وسلم-. انظر كشف الأستار (٢/ ١٠٧ - ١٠٨) وعزاء الهيثمى في مجمع الزوائد (٤/ ١١٣) إلى البزار والطبرانى في الكبير بنحوه وزاد فإذا اختلف النوعان فلا بأس واحد بعشرة ورجال البزار رجال الصحيح إلا أنه من رواية سعيد بن المسيب عن بلال ولم يسمع سعيد من بلال، وله في الطبرانى أسانيد بعضها من حديث ابن عمر عن بلال باختصار عن هذا ورجالها ثقات وبعضها من رواية عمر بن الخطاب عن بلال بنحو الأول وإسنادها ضعيف. اهـ."],[10661,"١٦٠٥ - كنى البخارى (ص ٢٩)، الجرح (٤/ ٢/ ٣٦٨)، كنى الحاكم (١/ ١٥٣/ ب) كنى ابن منده (١١١/ أ) وقال: حدث عن ابن عمر وروى عنه ابنه عبد اللَّه. اهـ. فأفاد في التصريح باسم ابنه هذا."],[10662,"١٦٠٦ - التاريخ الكبير (١/ ١/ ٣٥٢)، كنى مسلم (ص ٣٦٥)، كنى الحاكم (١/ ١٥٣/ ب)، الجرح (١/ ١/ ١٦٨)، و(٤/ ٢/ ٣٦٨)، كنى الدولابى (١/ ١٧٠)، الميزان (٤/ ٥٢٢)، اللسان (٧/ ٤٤)، تعجيل المنفعة (ص ٣١٦)، تاريخ ابن معين رواية الدارمى (ص ٢٤٦)."],[10663,"(١) هكذا في الأصل \"دَرَّاس\" بتقديم الراء على الالف وكذا في تاريخ ابن معين، والجرح، كنى الدولابى، كنى مسلم أيضا \"دراس\" وفى الميزان واللسان \"أبو دراس أو أبو دارس\". والذى في التاريخ الكبير، كنى الحاكم وتعجيل المنفعة \"أبو دارس إسماعيل بن دارس\" بتقديم الالف على الراء وسيأتى عند أحمد في المسند أيضًا \"أبو دارس\"."],[10664,"(٢) هكذا في الأصل وفى بعض المصادر \"صاحب الحور\" والذى في تعجيل المنفعة \"صاحب الجريرى\"."],[10665,"(٣) لم تكن في الأصل والمثبت عن بعض مصادر الترجمة. والسياق يقتضيها."],[10666,"فقال (١): ليس به بأس إنما روى حديثا واحدا (٢)."],[10667,"١٦٠٧ - أبو دلماثه القيسى. سمع منه عوف الاعرابى خبرا في غسل الرجل امرأته (٣)."],[10668,"١٦٠٨ - أبو الدهقان. عن الأحنف بن قيس. روى عنه صدقة بن صالح أبو الزنباع."],[10669,"(١) انظر تاريخ ابن معين رواية الدارمى (ص ٢٤٦)."],[10670,"(٢) الحديث أخرجه أحمد في المسند (٤/ ٤١٦) من طريق عبد الصمد قال ثنا أبو دارس صاحب الحور قال: ثنا أبو بردة بن أبى موسى. والبخارى في التاريخ الكبير (١/ ١/ ٣٥٢) من طريق مكى عن أبى دارس عن أبى بكر بن أبى موسى كلاهما -أبو برده وأبو بكر- عن أبيهما أبى موسى الاشعرى أنه رأى النبى -صلى الله عليه وآله وسلم- يصلى ركعتين بعد العصر."],[10671,"١٦٠٧ - كنى الحاكم (١/ ١٥٣/ ب) وقال: أبو دلهامة القيسى. سمع منه عوف الاعرابى. اهـ ولم يزد على هذا."],[10672,"(٣) أخرجه ابن أبى شيبة (٣/ ٣٥١) من طريق أبى أسامة عن عوف قال: كنت في مجلس فيه قسامة بن زهير وأشياخ وقد أدركوا عمر بن الخطاب فقال رجل: كانت تحتى امرأة من بنى عامر بن صعصعه وكان يثنى عليها خيرا فلما كان زمن طاعون الجارف طعنت فلما ثقلت قالت: انى امرأة غريبة فلا يلينى غيرك فماتت فغسلتها ووليتها. قال عوف: فما رأيت أحدا من أولئك الاشياخ عتب ولا عاب ذلك على الرجل."],[10673,"وقد روى عن ابن عباس انه قال: الرجل أحق بغسل امرأته. اهـ. وقد غسل ابن مسعود امرأته حين ماتت وكذا فعل عبد الرحمن بن الأسود. أخرج هذه الآثار ابن أبى شيبة (٣/ ٢٥٠)، والبيهقى (٣/ ٣٩٧) وقال البيهقى أيضًا وروينا في غسل الزوج امرأته عن علقمة وجابر بن زيد وأبى قلابة وغيرهم من التابعين\" أهـ."],[10674,"١٦٠٨ - كنى البخارى (ص ٢٩)، الثقات (٥/ ٥٨١)، الجرح (٤/ ٢/ ٣٦٨) كنى الحاكم (١/ ١٥٣/ ب)."],[10675,"حرف الذال"],[10676,"باب أبى ذر"],[10677,"١٦٠٩ - أبو ذر مولى حبيب بن مسلمة الفهرى (١). روى عن سويد بن جبلة (٢) قوله. سمع منه حريز بن عثمان."],[10678,"١٦١٠ - أبو ذر، كوفى. روى عن أبى إسحاق عن أبى ميسرة روى عنه يحيى بن زكريا بن أبى زائدة."],[10679,"١٦١١ - أبو ذر بن مسلم الازدى. روى عن أبيه عن الحسن وعن الرحال الراسبى. روى عنه مسلم بن إبراهيم."],[10680,"١٦٠٩ - كنى الحاكم (١/ ١٥٤/ ب)، كنى ابن منده (١١١/ ب) وقال أبو ذر الشامى. . فذكره."],[10681,"(١) مكى نزل الشام، وكان يسمى حبيب الروم، لكثرة دخوله عليهم مجاهدا، مختلف في صحبته والراجح ثبوتها، لكنه كان صغيرا مات بأرمينية، كان أميرا عليها لمعاوية سنة (٤٢). التقريب (١/ ١٥٠)."],[10682,"(٢) سويد بن جبلة الفزارى. روى عن النبى -صلى الله عليه وآله وسلم-. مرسل. قال أبو حاتم: ليست له صحبة. اهـ. الجرح (٢/ ١/ ٢٣٦)."],[10683,"١٦١٠ - كنى البخارى (ص ٢١)، الثقات (٧/ ٦٥٧)، كنى ابن منده (١١١/ ب)."],[10684,"١٦١١ - كنى الحاكم (١/ ١٥٤/ ب)، الجرح (٤/ ٢/ ٣٦٩)."],[10685,"باب افراد في الذال"],[10686,"١٦١٢ - أبو ذِرَاع (١). روى عن عثمان بن عفان. روى عنه عاصم بن كليب."],[10687,"١٦١٣ - أبو الذَّيَّال (٢). قال: كان ابن عباس \"يغمز قدمى عمر بن الخطاب\" (٣) روى عنه رجل من أهل الكوفة."],[10688,"١٦١٢ - كنى البخارى (ص ٢٩)، كنى مسلم (ص ٣٦٨)، الاكمال (٣/ ٣٨٤) ذكره في الهامش عن الاستدراك، كنى الحاكم (١/ ١٥٥/ أ)، الجرح (٤/ ٢/ ٣٦٩)، كنى الدولابى (١/ ١٧١)، التاريخ الكبير (٢/ ٢/ ١٠٧) هكذا ذكره ابن عبد البر هنا فيمن لا يعرف لهم أسماء، والذى في كنى الدولابى وكنى الحاكم \"أبو ذراع سهيل بن ذراع. . \" الخ. وفى التاريخ الكبير أيضًا. سهيل بن ذراع. . \"."],[10689,"(١) ذراع: بكسر الذال، وبالراء. الاكمال (٣/ ٣٨٤)."],[10690,"١٦١٣ - كنى الحاكم (١/ ١٥٤/ ب)، كنى ابن منده (١١١/ ب)."],[10691,"(٢) الذيال: بفتح ذال معجمة وشدة تحتية. المغنى (ص ٣٢)."],[10692,"(٣) الخبر: أخرجه الحاكم في الكنى (١/ ١٥٤/ ب) من طريق ابن عون قال: حدثنى رجل من أهل الكوفة عن جده أبى الذيال: قال: كان ابن عباس يغمز قدمى عمر بن الخطاب فقرأ ابن عباس لو أن لابن آدم واديين مالًا لابتغى واديًا ثالثا ولا يملأ جوف ابن آدم إلا التراب فقال عمر: ما هذا؟ قال: أقرأنيه أبى بن كعب فقال عمر: أبو المنذر؟ قال: نعم -فدخل عمر ومعه ابن عباس وكان ساكتا. فقال عمر: كيف أنت يا أبا المنذر؟ كيف أنت يصلحك اللَّه؟ قال عمر: ما شئ أقرأنيه ابن أخيك عنك؟، فقال: أى ما هذا لأن كذبوا على؟ قال: فقرأ ابن عباس لو أن لابن آدم واديين مالًا لابتغى واديًا ثالثا ولا يملأ بطن ابن آدم إلا التراب فقال: أى كنا نقرأها فقال عمر: فما تأمر؟ قال: لا آمرك ولا أنهاك\" أهـ."],[10693,"حرف الراء"],[10694,"باب أبى رجاء"],[10695,"١٦١٤ - أبو رجاء. رأى على بن أبى طالب. كوفى. روى عنه مجمع التيمى (١)."],[10696,"١٦١٥ - أبو رجاء عن أبى جحيفة. قال: تجشيت (٢). عند النبى عليه السلام فذكر الحديث (٣)."],[10697,"١٦١٤ - كنى ابن منده (١١٣/ أ) وذكره كما هنا ثم ساق إسناده إليه فقال: أخبرنا عمرو بن عبد اللَّه أبو عثمان ثنا محمد بن عبد الوهاب بن حبيب نا يعلى بن عبيد عن أبى حيان التيمى عن مجمع التيمى عن أبى رجاء. اهـ. المقتنى في سرد الكنى (٥١/ أ)."],[10698,"(١) مجمع التيمى: هو مجمع بن سمعان الحائك النساج أبو حمزة. المتقدم في (٦١٠)."],[10699,"١٦١٥ - كنى البخارى (ص ٣١)، كنى ابن منده (١١٣/ أ)."],[10700,"(٢) تجشيت: قال الجوهرى في الصحاح مادة \"جشأ\" (١/ ٤١): قال الاصمعى: يقال: الجُشَاء على فُعَال، كأنه من باب العطاس والبُوال، والدُّوار. اهـ. وقال ابن منظور في لسان العرب مادة \"جشأ\" (١/ ٤٨ - ٤٩): التجشؤ: تنفس المعدة عند الامتلاء، وجشأت المعدة عند الامتلاء. وجشأت المعدة وتجشأت: تنفست، والأسم الجشاء، ممدود على وزن فُعَال كأنه من باب العطاس. والدوار والبوال وجشأ فلان عن الطعام إذا اتخم فكره الطعام. وقد جشأت نفسه فما تشتهى طعاما. اهـ."],[10701,"(٣) الحديث ذكره السيوطى في الجامع الكبير (٢/ ٦٣٤) عن أبى جحيفة قال: أكلت ثريدا أو لحما سمينا ثم أتيت النبى -صلى الله عليه وآله وسلم- اتجشأ فقال: \"احبس جشأك يا أبا جحيفة، فإن أكثركم شبعا اليوم أطولكم جوعا يوم القيامة\"."],[10702,"وعزاه السيوطى لابن جرير في تهذيب السنن. = ١٦١٦ - أبو رجاء الحنفى (١). روى عن أبى موسى الاشعرى في المكاتب (٢). روى عنه عبد اللَّه الداناج. قال على بن المدينى: أبو رجاء الحنفى مجهول (٣)."],[10703,"١٦١٧ - أبو رجاء الكلبى. نا عبد الوارث نا قاسم، نا ابن أبى خيثمة قال: سمعت يحيى بن معين يقول: أبو رجاء الكلبى ثقة."],[10704,"= والحديث أخرجه أيضا ابن عبد البر في الاستيعاب (٤/ ٣٧) وابن الأثير في أسد الغابة (٦/ ٤٨ و٤٩) كلاهما عن عون بن أبى جحيفة عن أبيه فذكره مرفوعًا. وأخرجه أيضًا البزار باسنادين أحدهما رجاله ثقات مرفوعًا بلفظ \"أكثرهم شبعا في الدنيا أكثرهم جوعا يوم القيامة\" قاله -صلى الله عليه وآله وسلم- لأبى جحيفة لما تجشأ. اهـ. كما في سبل السلام (٤/ ١٧٩)."],[10705,"وأخرجه أيضًا الطبرانى في الكبير والأوسط بأسانيد كما في مجمع الزوائد (٥/ ٣١) من حديث أبى جحيفة قال: أكلت ثريدة بلحم سمين، فأتيت رسول اللَّه -صلى الله عليه وآله وسلم- وأنا اتجشأ فقال: \"اكفف عنا جشأك أبا جحيفة، فإن أكثر الناس شبعا في الدنيا أطولهم جوعا يوم القيامة\" فما أكل أبو جحيفة ملء بطنه حتى فارق الدنيا كان إذا تغدى لا يتعشى، وإذا تعشى لا يتغدى."],[10706,"وقال الهيثمى: في أحد اسانيد الكبير محمد بن خالد الكوفى ولم أعرفه. وبقية رجاله ثقات. اهـ."],[10707,"١٦١٦ - كنى البخارى (ص ٣١)، الجرح (٤/ ٢/ ٣٧٠)، الميزان (٤/ ٥٢٤)، اللسان (٧/ ٤٧)، ديوان الضعفاء (ص ٣٥٦)."],[10708,"(١) الذى في كنى البخارى \"الجعفى\" وقال ابن حجر في اللسان بعد أن ذكره كما هنا: \"ورأيت في نسخة الأصل عن ابن الجعفى بدل الحنفى\"."],[10709,"(٢) ومثله في كنى البخارى، والجرح، والميزان، اللسان. ولم أقف على هذا الحديث."],[10710,"(٣) انظر الجرح (٤/ ٢/ ٣٧٠)."],[10711,"١٦١٧ - الجرح (٤/ ٢/ ٣٧٠) وقال: نا أبو بكر بن أبى خيثمة فيما كتب قال: سمعت يحيى بن معين يقول: أبو رجاء الكلبى ثقة. اهـ. كنى الدولابى (١/ ١٧٤) وذكر قول ابن معين فيه."],[10712,"١٦١٨ - أبو رجاء الكندى. روى عنه سليمان بن حرب نا عبد اللَّه بن محمد نا محمد بن عثمان نا إسماعيل بن إسحاق نا على بن المدينى نا سليمان بن حرب نا أبو رجاء الكندى قال: قال فضل الرقاشى: إذا اقدرت له بالعلم فقد امكنته من رجلك يجرها."],[10713,"١٦١٨ - لم أقف عليه عند غير المؤلف."],[10714,"باب أبى روح"],[10715,"١٦١٩ - أبو روح الكلبى، شامى عن جبير بن نفير عن أبى الدرداء. روى عنه معاوية بن صالح."],[10716,"١٦٢٠ - أبو روح. عن عكرمة. روى عنه يزيد بن سنان."],[10717,"١٦٢١ - أبو روح، عن أبى الجلد. روى عنه موسى بن جميل (١)."],[10718,"١٦٢٢ - أبو روح. روى عنه معاوية بن صالح قوله، فيه وفى الذى قبله نظر."],[10719,"١٦١٩ - الثقات (٧/ ٦٥٧)، كنى ابن منده (١١٣/ ب) وقال: ذكره البخارى."],[10720,"١٦٢٠ - كنى ابن منده (١١٤/ ب) وقال: أبو روح عكرمة روى عنه يزيد بن سنان. أهـ. قلت: وقوله \"أبو روح عن عكرمة\" خطأ، وإنما هو \"أبو روح عن عكرمة\". واللَّه أعلم."],[10721,"١٦٢١ - كنى ابن منده (١١٤/ ب)."],[10722,"(١) موسى بن جميل، له ترجمة في الجرح (٤/ ١/ ١٣٩)."],[10723,"١٦٢٢ - كنى ابن منده (١١٣/ ب)، وقال: أراه الأول. والأول عنده هو أبو روح الكلبى الشامى. انظر (١٦١٩)."],[10724,"باب أبى الربيع"],[10725,"١٦٢٣ - أبو الربيع المدنى. قيل: هو رجل من الأنصار. روى عن أبى هريرة روى عنه سماك بن حرب، ويزيد بن أبى زياد (١)، وعلقة بن مرثد. حديثه في الكوفيين."],[10726,"١٦٢٤ - أبو الربيع الاسدى، سمع سعيد بن جبير. روى عنه طلحة الحارثى."],[10727,"١٦٢٥ - أبو الربيع الكوفى. روى عن عبد الرحمن بن أبى ليلى. روى عنه أبو العميس."],[10728,"١٦٢٣ - كنى البخارى (ص ٣٠)، الثقات (٥/ ٥٨٢)، الجرح (٤/ ٢/ ٣٧٠) كنى ابن منده (١١٥/ أ)، التهذيب (١٢/ ٩٤)، التقريب (٢/ ٤٢١) وقال: مقبول، من الثالثة./ بخ ت."],[10729,"(١) يزيد بن أبى زياد الهاشمى مولاهم كوفى، ضعيف، كبر فتغير. صار يتلقن وكان شيعيا، من الخامسة (ت: ١٣٦). التقريب (٢/ ٣٦٥)."],[10730,"١٦٢٤ - كنى البخارى (ص ٣١)، الثقات (٧/ ٦٥٨)، كنى ابن منده (١١٥/ ب)."],[10731,"١٦٢٥ - الجرح (٤/ ٢/ ٣٧٠) وذكره كما هنا وقال: سألت أبى عنه فقال: هو شيخ كوفى، لا يعرف."],[10732,"باب أبى رزين"],[10733,"١٦٢٦ - أبو رَزِين (١). روى عن على رضي الله عنه. روى عنه ابنه عبد اللَّه ابن أبى رزين. ذكر إسحاق بن منصور عن يحيى بن معين، أنه سئل عن حديث رواه موسى بن أبى عائشة (٢) عن عبد اللَّه بن أبى رزين عن أبى رزين عن على. وقيل ليحيى: من أبو رزين هذا؟ فلم يعرفه (٣)."],[10734,"١٦٢٧ - أبو رَزِين الباهلى. سمع مالك بن أخيمر، ويقال: ابن أخامر وابن أبى اخيمر (٤). روى عنه موسى بن يعقوب الزَّمعى (٥)، ومسلم بن إبراهيم."],[10735,"١٦٢٨ - أبو رَزِين، المدنى، القرشى، الأموى. عن أبى عبيد مولى ابن أزهر، روى عنه يزيد بن سنان."],[10736,"١٦٢٦ - الجرح (٤/ ٢/ ٣٧١)."],[10737,"(١) رزين: بفتح راء كسر زاى وسكون ياء وبنون. الاكمال (٤/ ٦٤)، المغنى (ص ٣٣)."],[10738,"(٢) موسى بن أبى عائشة الهمْدانى، بسكون الميم، مولاهم أبو الحسن الكوفى ثقة عابد، من الخامسة، وكان يرسل./ ع. التقريب (٢/ ٢٨٥)."],[10739,"(٣) الجرح (٤/ ٢/ ٣٧١)."],[10740,"١٦٢٧ - كنى البخارى (ص ٣٢)، الجرح (٤/ ٢/ ٣٧١)، كنى ابن منده (١١٢/ أ) وقال: أبو رزين الباهلى، حدث عن مالك بن يخامر."],[10741,"(٤) في الجرح (٤/ ١/ ٢٠٣) \"مالك بن أخيمر اليمامى، ويقال: ابن أخامر. روى عن النبى -صلى الله عليه وآله وسلم- ولم يثبت له صحبة، روى عنه أبو رزين الباهلى توفى زمن عبد الملك بن مروان، سمعت أبى يقول ذلك\" أهـ."],[10742,"(٥) الزّمعى: بفتح الزاى وسكون الميم وفى آخرها عين مهملة - هذه النسبة إلى الجد والمشهور بها أبو محمد موسى بن يعقوب بن عبد اللَّه بن وهب بن زمعة القرشى. اهـ. اللباب (٢/ ٧٤). وجاء في التقريب (٢/ ٢٨٩) بأن الزمعى هذا صدوق سئ الحفظ، من السابعة، مات بعد سنة (١٤٠) أهـ."],[10743,"١٦٢٨ - المقتنى في سرد الكنى (٢١/ ب)."],[10744,"باب أبى رفاعة"],[10745,"١٦٢٩ - أبو رفاعة مدنى. روى عن أبى سعيد الخدرى. روى عنه محمد ابن عبد الرحمن بن ثوبان."],[10746,"١٦٣٠ - أبو رفاعة عن معاذ بن جبل. روى عنه محمد بن سُوقة (١)، حديثه في البصريين."],[10747,"١٦٣١ - أبو رفاعة الفهمى، يُرْوى عنه، عن أبى بكر الصديق وعن رجل عن أبى بكر. وليس إسناده مما يعتمد عليه."],[10748,"١٦٢٩ - كنى البخارى (ص ٣١)، كنى مسلم (ص ٣٨١)، كنى ابن منده (١١٦/ ب) الجرح (٤/ ٢/ ٣٧١) وقال: أبو رفاعة، وقال بعضهم، عن رفاعة، وقال بعضهم: عن أبى مطيع بن رفاعة. روى عن أبى سعيد الخدرى، روى يحيى بن أبى كثير عن عبد الرحمن بن ثوبان عنه. اهـ."],[10749,"١٦٣٠ - المقتنى في سرد الكنى (٢٢/ أ)."],[10750,"(١) محمد بن سُوقة، يضم المهملة، الغَنَوى، بفتح المعجمة والنون الخفيفة، أبو بكر الكوفى، العابد، ثقة، مرضى عابد، من الخامسة. انظر التقريب (٢/ ١٦٨)."],[10751,"١٦٣١ - المقتنى في سرد الكنى (٢١/ أ)."],[10752,"باب أبى ربيعة"],[10753,"١٦٣٢ - أبو ربيعة البصرى، عن الحسن بن أبى الحسن. روى عنه الحسن ابن صالح. لا يعلم له رواية غيره."],[10754,"١٦٣٣ - أبو ربيعة الكوفى. روى عن ابن بريدة. روى عنه شريك بن عبد اللَّه القاضى."],[10755,"١٦٣٢ - كنى البخارى (ص ٣١)."],[10756,"١٦٣٣ - كنى ابن منده (١١٧/ أ) وقال: أبو ربيعة عمرو بن ربيعة. تهذيب الكمال (٣/ ١٦٠٤) وقال: أبو ربيعة الايادى ذكر أبو عبد اللَّه بن منده أن اسمه عمر ابن ربيعة. روى على الحسن البصرى وعبد اللَّه بن بريدة، روى عنه الحسن به. صالح بن حى وشريك بن عبد اللَّه وعلى بن صالح بن حى ومالك بن مغول. أهـ. التهذيب (١٢/ ٩٤)، التقريب (٢/ ٤٢١) وقال: مقبول، من السادسة. قيل: اسمه عمر بن ربيعة./ د. ت. ق."],[10757,"باب أبى رباح"],[10758,"١٦٣٤ - أبو رَباحَ (١) اليمامى. ويقال: الفدكى. ويقال: القرظى عن ابن عمر. روى عنه عكرمة بن عمار."],[10759,"١٦٣٥ - أبو رباح بن أبى الحكم بن حبيب الثقفى. روى عنه عمر بن ذر (٢) قوله."],[10760,"١٦٣٤ - كنى البخارى (ص ٣٠)، الثقات (٥/ ٥٧٩)، الجرح (٤/ ٢/ ٣٧١)، كنى ابن منده (١١٨/ أ)."],[10761,"(١) رَبَاح: بفتح الراء والباء المعجمة بواحدة. الاكمال (٤/ ٧)."],[10762,"١٦٣٥ - كنى البخارى (ص ٣٠)، الثقات (٥/ ٥٧٣)، الجرح (٤/ ٢/ ٣٧١) كنى ابن منده (١١٨/ أ)."],[10763,"(٢) عمر بن ذر بن عبد اللَّه زرارة الهمدانى، الكوفى، ثقة، رمى بالارجاء من السادسة (ت: ١٥٣) وقيل غير ذلك./ خ. د. ت. س. فق. التقريب (٢/ ٥٥)."],[10764,"باب أبى راشد"],[10765,"١٦٣٦ - أبو راشد الكوفى. سمع عليا رضي الله عنه. روى عنه عبد العزيز ابن سِيَاه (١)."],[10766,"١٦٣٧ - أبو راشد الحبرانى، عن عبادة بن الصامت، وأبى أمامة الباهلى. روى عنه محمد بن زياد (٢) ولقمان بن عامر (٣)."],[10767,"١٦٣٨ - أبو راشد. سمع عمارا رحمه الله. روى عنه على بن ثابت."],[10768,"١٦٣٩ - أبو راشد الشامى. قال: قلت ليزيد بن ميسرة: يا يوسف. روى عنه أبو بكر بن أبى مريم."],[10769,"١٦٤٠ - أبو راشد مولى عبيد بن عمير. سمع عبيد بن عمير. روى عنه الأعمش."],[10770,"١٦٣٦ - كنى البخارى (ص ٣٠)، الجرح (٤/ ٢/ ٣٧٠)، كنى ابن منده (١١٧/ ب)."],[10771,"(١) عبد العزيز بن سياه، بكسر المهملة بعدها تحتانية خفيفة، الاسدى، الكوفى، صدوق يتشيع، من السابعة. التقريب (١/ ٥٠٩)."],[10772,"١٦٣٧ - الثقات (٥٨٣/ ٥)، كنى ابن منده (١١٧/ ب)، تاريخ دمشق (ل/ ٦٦٤) وذكره بنحو ماهنا وقال: اسمه أخضر. ويقال: النعمان بن بشير، من أهل حمص، ويقال: من أهل دمشق."],[10773,"(٢) محمد بن زياد الأَلْهَانى، بفتح الهمزة وسكون اللام، أبو سفيان الحمصى، من الرابعة. التقريب (٢/ ١٦٢)."],[10774,"(٣) لقمان بن عامر الوَصَابى، بتخفيف الصاد المهملة، أبو عامر الحمصى، صدوق، من الثالثة. التقريب (٢/ ١٣٨)."],[10775,"١٦٣٨ - كنى البخارى (ص ٣٠)، الثقات (٥/ ٥٧٨)، الجرح (٤/ ٢/ ٣٧٠)، الميزان (٤/ ٥٢٣)، التهذيب (١٢/ ٩٢)، التقريب (٢/ ٤٢١) وقال: مقبول، من الثالث./ د."],[10776,"١٦٣٩ - كنى ابن منده (١١٧/ ب)."],[10777,"١٦٤٠ - تقدم في (٧٠٣) وقال ابن عبد البر هناك: \"اسمه سعيد، وقال: ليس به = ١٦٤١ - أبو راشد الضبى البصرى. سمع مهدى بن هلال (١). روى عنه أبو حفص عمرو بن على."],[10778,"= بأس\". ولم يشر ابن عبد البر إلى أنه ذكره في موضعين من هذا الكتاب."],[10779,"١٦٤١ - كنى ابن منده (١١٧/ ب)."],[10780,"(١) مهدى بن هلال: أبو عبد اللَّه البصرى كذبه يحيى بن سعيد. وقال الدارقطنى وغيره. متروك. وقال ابن معين أيضًا: صاحب بدعة، يضع الحديث."],[10781,"وقال ابن المدينى: كان يتهم بالكذب. اهـ. الميزان (٤/ ١٩٦) وقال ابن حبان في المجروحين (٣/ ٣٠): كان ممن يروى الموضوعات عن الاثبات والمعضلات عن الثقات حتى خرج عن حد الاحتجاج به بحال. اهـ."],[10782,"باب أبى الرقاد"],[10783,"١٦٤٢ - أبو الرُّقَاد (١). سمع حذيفة. روى عنه رزين (٢) بن حبيب الرمانى (٣)."],[10784,"١٦٤٣ - أبو الرُّقَاد. شيخ من اشجع (٤). سمع علقمة (٥) عن على. روى عنه حُنَيْف بن رستم (٦) من حديث (جرير) (٧)."],[10785,"١٦٤٢ - كنى البخارى (ص ٣٠)، كنى الحاكم (١/ ١٥٨/ ب)، الجرح (٤/ ٢/ ٣٧٠)."],[10786,"(١) رقاد: براء مضمومة بعدها قاف. الاكمال (٤/ ١٠٧)."],[10787,"(٢) في كنى البخارى \"زر بن حبيش\" وهو تحريف."],[10788,"(٣) رَزِين: بفتح أوله كسر الزاى، ابن حبيب الجهنى أو البكرى، الكوفى الرُّمانى، بضم الراء التمار، بياع الانماط ويقال: رزين الجهنى الرمانى غير رزين بياع الانماط والجهنى، هو الذى أخرج له الترمذى ووثقه أحمد وابن معين، والآخر مجهول، وكلاهما من السابعة. التقريب (١/ ٢٥٠)."],[10789,"١٦٤٣ - كنى البخارى (ص ٣٠)، كنى ابن منده (١١٩/ أ) وقال: أبو رقاد شيخ من النخع حدث عن علقمة، كنى الحاكم (١/ ١٥٨/ ب)، الجرح (٤/ ٢/ ٣٧٠)، الميزان (٤/ ٥٢٤)، تهذيب الكمال (٣/ ١٦٠٥)، التهذيب (١٢/ ٩٦)، التقريب (٢/ ٤٢٣) وقال: مقبول، من السادسة./ عس."],[10790,"(٤) في كنى البخارى، والجرح، وتهذيب الكمال \"النخعى\"."],[10791,"(٥) علقمة هو ابن قيس النخعى كما في تهذيب الكمال (٢/ ٩٥٣)."],[10792,"(٦) حُنَيف، بالنون، مصغرا، ابن رستم المؤذن، الكوفى، مجهول، من السابعة./ عس، التقريب (١/ ٢٦٠)."],[10793,"(٧) هكذا رسمه في الأصل. وفى تهذيب الكمال (٣/ ١٦٠٥) والتهذيب (١٢/ ٩٦) في ترجمة أبى الرُّقاد \"روى عن علقمة عن على\" \"لعن اللَّه قوما اتخذوا قبور انبيائهم مساجد\". . روى له النسائى في مسند على هذا الحديث. اهـ."],[10794,"باب أبى رافع"],[10795,"(١)"],[10796,"١٦٤٤ - أبو رافع عن ابن مسعود. روى عنه على بن زيد بن جدعان."],[10797,"١٦٤٥ - أبو رافع. روى عن أبى هريرة عن النبى عليه السلام أنه قال: \"إذا كان أحدكم في الصلاة فلا يبزق عن يمينه وليبزق عن يساره\" (٢). رواه شعبة عن"],[10798,"(١) الحق هذا الباب بكامله بهامش الأصل. كتب في آخره \"صح أصل\"."],[10799,"١٦٤٤ - كنى ابن منده (١١٦/ أ)."],[10800,"١٦٤٥ - الجرح (٤/ ٢/ ٣٧١)، الثقات (٥/ ٥٨٣)."],[10801,"(٢) الحديث أخرجه مسلم \"المساجد\" باب النهى عن البصاق في المسجد في الصلاة وغيرها (١/ ٣٨٩)، وابن ماجه \"الإقامة\" باب المصلى يتنخم (١/ ٣٢٦)، وأحمد (٢/ ٤١٥) كلهم أخرجوه من طريق القاسم بن مهران عن أبى رافع عن أبى هريرة يرفعه بلفظ أن رسول اللَّه -صلى الله عليه وآله وسلم- رأى نخامة في قبلة المسجد، فأقبل على الناس فقال: ما بال أحدكم يقوم مستقبل ربه فيتنخع أمامه؟ أيحب أحدكم أن يستقبل فيتنخع في وجهه؟ فإذا تنخع أحدكم فلينخع عن يساره تحت قدمه فإن لم يجد فليقل هكذا ووصف القاسم فتفل في ثوبه ثم مسح بعضه على بعض. هذا لفظ مسلم."],[10802,"وأخرجه البخارى \"الصلاة\" باب حك المخاط بالحصى من المسجد (١/ ٥٠٩) وفى باب لا يبصق عن يمينه في الصلاة (١/ ٥١٠)، ومسلم \"المساجد\" باب النهى عن البصاق في المساجد (١/ ٣٨٩)، والدارمى (١/ ٣٢٥) من حديث أبى هريرة وأبى سعيد رضي الله عنهما مرفوعًا بنحوه وفيه لفظ \"إذا تنخم أحدكم فلا يتنخمن قبل وجهه ولا عن يمينه وليبصق عن يساره أو تحت قدمه اليسرى\"."],[10803,"وأخرج الترمذى \"الجمعة\" باب كراهية البزاق في المسجد (٣/ ١٦٢) حديث عبد اللَّه بن طارق المحاربى يرفعه \"إذا كنت في الصلاة فلا تبزق عن يمينك ولكن خلفك أو تلقاء شمالك أو تحت قدمك اليسرى\". وقال ="],[10804,"القاسم بن مهران (١) عنه."],[10805,"= الترمذى: حديث حسن صحيح. . وفى الباب عن أبى سعيد وابن عمر وأنس وأبى هريرة."],[10806,"(١) القاسم بن مهران القيسى، مولى بنى قيس بن ثعلبة، خال هشيم، صدوق، من السادسة./ م. س. ق. التقريب (٢/ ١٢١)، التهذيب (٨/ ٣٣٩)."],[10807,"باب أفراد في الراء"],[10808,"١٦٤٦ - أبو رِشْدِين (١) بن عبيد بن أبى شمر. مصرى. رأى عمرو بن العاص. روى عنه بكر بن سوادة."],[10809,"١٦٤٧ - أبو رَوَّاد (٢) والد عبد العزيز بن أبى رواد (٣). روى عن ابن عمر روى عنه ابنه عبد العزيز."],[10810,"١٦٤٨ - أبو الرُّواع (٤) عن ابن عمر. روى عنه عثمان بن الحارث (٥)."],[10811,"١٦٤٩ - أبو الرَّحَّال (٦). سمع الحسن مرسلًا. روى عنه أبو نعيم."],[10812,"١٦٤٦ - كنى الحاكم (١/ ١٥٦/ أ). كنى ابن منده (١١٨/ أ)."],[10813,"(١) رشدين: بكسر راء وسكون معجمة كسر قال مهملة وبياء ونون. المغنى (ص ٣٣)."],[10814,"١٦٤٧ - كنى البخارى (ص ٣١)، الجرح (٤/ ٢/ ٣٧٢)، كنى ابن منده (١١٩/ ب) وقال أبو رواد أيمن بن بدر العتكى والد عبد العزيز وجبلة."],[10815,"(٢) رواد: بفتح الراء وتشديد الواو وبالدال المهملة الاكمال (٤/ ١٠٤)."],[10816,"جاء في الاكمال (٤/ ١٠٥) \"أبو رواد يمن بن بدر مولى المغيرة بن المهلب بن أبى صفرة الازى والد عبد العزيز بن أبى رواد المكى، يروى عن ابن شهاب، روى عنه ابناه الحكم وعبد العزيز. روى عنه ابنه عبد العزيز قال: مرَّ بى ابن عمر\" أهـ. فاللَّه أعلم."],[10817,"(٣) صدوق عابد، ربما وهم ورمى بالارجاء، من السابعة (ت: ١٥٩)، التقريب (١/ ٥٠٩)."],[10818,"١٦٤٨ - كنى مسلم (ص ٣٨٤). كنى ابن منده (١١٨/ أ)."],[10819,"(٤) الرُّوَاع بضم الراء وتخفيف الواو وبالعين المهملة. الاكمال (٤/ ١٠٣)."],[10820,"(٥) عثمان بن الحارث أبو الرُّواع، بفتح المهملة وتشديد الواو وآخره مهمله ثقة، من الرابعة./ بخ. التقريب (٧١٢)."],[10821,"١٦٤٩ - كنى البخارى (ص ٣٠)، كنى ابن منده (١١٨/ ب)."],[10822,"(٦) الرّحال: بفتح الراء وتشديد الحاء المهملة. الاكمال (٤/ ٢٩)."],[10823,"١٦٥٠ - أبو ربعى. روى عن الأعمش قوله. روى عنه يعقوب بن عبد اللَّه بن سعد."],[10824,"١٦٥١ - أبو الرَّبَاب (١). مولى معقيل بن يسار المزنى البصرى. سمع معقل ابن يسار روى عنه أبو معاذ (٢)."],[10825,"١٦٥٢ - أبو رَمْلَة (٣). كوفى عن عبيد اللَّه بن مسلم (٤). روى عنه قيس بن مسلم. هو الجدلى كما صرح بذلك الحاكم."],[10826,"١٦٥٣ - أبو الرضراض. عن أبى عياض. روى عنه سعيد بن أبى عروبة."],[10827,"١٦٥٠ - كنى ابن منده (١٢٠/ أ)."],[10828,"١٦٥١ - كنى البخارى (ص ٣٠)، كنى الحاكم (١/ ١٥٨/ أ). كنى ابن منده (١١٨/ ب)."],[10829,"(١) رَبَاب: بفتح الراء والباء المخففة المعجمة بواحدة وهى مكررة. الاكمال (٤/ ١ - ٢)."],[10830,"(٢) هكذا هنا \"أبو معاذ\" غير منسوب ولا مسمى. والذى في كنى البخارى والحاكم \"الحكم أبو معاذ\" وفى كنى ابن منده \"الحكم بن طهمان\" وفى الجرح (١/ ٢/ ١١٨) الحكم بن طهمان أبو عزة الدباغ روى عن أبى الرباب مولى معقل بن يسار. . سمعت أبى يقول: روى عنه أبو نعيم وكناه بأبى معاذ، ويرون أنه غلط. . ذكره أبى عن إسحاق بن منصور عن يحيى بن معين أنه قال: أبو عزة الدباغ صالح، سألت أبى عن أبى عزة فقال: ثقة لا بأس به صالح الحديث. سئل أبو زرعة عن أبى عزة الدباغ فقال: شيخ ثقة. اهـ."],[10831,"١٦٥٢ - كنى الحاكم (١/ ١٥٨/ ب)، تعجيل المنفعة (ص ٣١٨)، كنى ابن منده (١١٩/ أ)."],[10832,"(٣) رملة: بفتح راء وسكون ميم وبلام. المغنى (٣٤)."],[10833,"(٤) عبيد اللَّه بن مسلم أو ابن أبو، مسلم الحضرمى، صحابى ويقال: تابعى. التقريب (١/ ٥٣٩) وقال الذهبى في التجريد (١/ ٣٦٤): له صحبة."],[10834,"١٦٥٣ - كنى ابن منده (١٢٠/ أ) ذكره كما هنا وقال ذكره البخارى."],[10835,"قلت: ولم أقف عليه في مطبوعة الكنى للبخارى. واللَّه أعلم."],[10836,"١٦٥٤ - أبو رُؤْبة. روى عن أنس بن مالك. من حديث الفرات بن خالد (١) عن عتبة (٢) عنه. وروى عن عمران بن حصين. روى عنه أيوب بن عائذ (٣) عنه."],[10837,"١٦٥٥ - أبو رياح ختن مجاهد. روى عن سعيد بن المسيب. روى عنه سفيان الثورى."],[10838,"١٦٥٤ - الجرح (٤/ ٢/ ٣٧٢)، كنى الحاكم (١/ ١٥٦/ ب)، تعجيل المنفعة (ص ٣١٨)، كنى ابن منده (١١٨/ ب)."],[10839,"(١) الفرات بن خالد الضبى أبو إسحاق الرازى، والد أبى مسعود الحافظ ثقة، من التاسعة. التقريب (٢/ ١٠٧)."],[10840,"(٢) انظر ترجمته في الجرح (٣/ ١/ ٣٧٥)."],[10841,"(٣) أيوب بن عائذ بن مدلج الطائى الكوفى، ثقة، رمى بالارجاء من السادسة./ س. التقريب (١/ ٩٠)."],[10842,"١٦٥٥ - الجرح (٤/ ٢/ ٣٧٢)."],[10843,"حرف الزاى"],[10844,"باب أبى زيد"],[10845,"١٦٥٦ - أبو زيد مولى عمرو بن حريث المخزومى. روى عن عبد اللَّه بن مسعود روى عنه أبو فزارة راشد بن كيسان. هو عند أهل الحديث رجل مجهول. روى عن ابن مسعود عن النبى عليه السلام في الوضوء بالنبيذ حديثا منكرا لم يتابع عليه. ولم يرو عنه غير أبى فزارة، ولا يصح حديث أبى زيد هذا عند أهل الحديث ولا قال به أحد من أهل الحجاز."],[10846,"١٦٥٧ - أبو زيد. مولى بنى ثعلبة (١) عن معقل بن أبى معقل. روى عنه عمرو بن يحيى المازنى."],[10847,"١٦٥٨ - أبو زيد الفزارى. ويقال المرادى. سمع زيد بن ارقم روى عنه شعبة."],[10848,"١٦٥٩ - أبو زيد. روى عن أبى هريرة. روى عنه أبو جهضم (٢). وأبو جهضم لا أعرفه."],[10849,"١٦٥٦ - تقدم هو وحديثه. انظر الترجمة (٧١٧)، ولم ينبه ابن عبد البر على أنه ذكره في موضعين من هذا الكتاب."],[10850,"١٦٥٧ - كنى مسلم (ص ٣٩٤)، كنى ابن منده (١٢١/ ب)، تهذيب الكمال (٣/ ١٦٠٧)، التهذيب (١٢/ ١٠٣)، التقريب (٢/ ٤٢٥) وقال: مجهول، من الرابعة./ ق."],[10851,"(١) في تهذيب الكمال، والتهذيب زياد لفظ \"قيل: اسمه الوليد\"."],[10852,"١٦٥٨ - كنى البخارى (ص ٣٢)، الثقات (٥/ ٥٨٥)، الجرح (٤/ ٢/ ٣٧٢) كنى ابن منده (١٢١/ ب)."],[10853,"١٦٥٩ - كنى البخارى (ص ٣٢)، كنى ابن منده (١٢١/ أ)، الجرح (٤/ ٢/ ٣٧٢) تهذيب الكمال (٣/ ١٦٠٧)، الميزان (٤/ ٥٢٦)، التهذيب (١٢/ ١٠٣) التقريب (٢/ ٤٢) وقال: مجهول، من الثالثة./ س."],[10854,"(٢) هكذا في الأصل \"أبو جهضم، وأبو جهضم لا أعرفه\". والذى في مصادر ="],[10855,"١٦٦٠ - أبو زيد. روى عن رزيق (١). روى عنه عبد اللَّه بن أبى شقيق (٢). هو عندهم أيضًا مجهول."],[10856,"= الترجمة \"أبو جهم\" وزاد المزى في تهذيب الكمال فصرح باسمه فقال: أبو الجهم سليمان بن الجهم. وذكر المزى في تهذيب الكمال (١/ ٥٣٣) وتبعه ابن حجر في التهذيب (٤/ ١٧٧) سليمان بن الجهم بن أبى الجهم الأنصارى أبو الجهم وذكرا روايته عن أبى زيد صاحب أبى هريرة. قلت: وإذا كان الأمر كذلك فقد تقدم أبو الجهم سليمان بن الجهم في الكتاب الثانى، انظر الترجمة (٥٣٠)."],[10857,"١٦٦٠ - كنى البخارى (ص ٣٢)، الميزان (٤/ ٥٢٧)، اللسان (٧/ ٤٩)، الجرح (٤/ ٢/ ٣٧٢) وقال: روى عنه عبد اللَّه بن أبى شقيق. سمعت أبى يقول ذلك، ويقول: هما مجهولان."],[10858,"(١) رزيق، مولى لعمر بن الخطاب، روى عن عمر، روى عنه أبو زيد. انظر الجرح (١/ ٢/ ٥٠٤)."],[10859,"(٢) عبد اللَّه بن أبى شقيق السلولى، روى عن أبى زيد، قال أبو حاتم: هو مجهول، انظر الجرح (٢/ ٢/ ٨٣)."],[10860,"باب أبى زياد"],[10861,"١٦٦١ - أبو زياد الطحان. مولى الحسن بن على بن أبى طالب، عن أبى هريرة. روى عنه شعبة بن الحجاج، ذكره إسحاق بن منصور عن يحيى بن معين: قال: أبو زياد الطحان ثقة (١)."],[10862,"١٦٦٢ - أبو زياد الخلقانى. عن محمد بن المنكدر. يعد في الشاميين."],[10863,"١٦٦٣ - أبو زياد الهاشمى. مولى ابن عباس. عن ابن عباس. روى عنه أبو حذيفة."],[10864,"١٦٦١ - كنى البخارى (ص ٣٢). كنى مسلم (ص ٤٠٥)، الجرح (٤/ ٢/ ٣٧٣) الميزان (٤/ ٥٢٦)، اللسان (٧/ ٤٩)، تعجيل المنفعة ص ٣١٩ كنى ابن منده (١٢٤/ أ). المقتنى في سرد الكنى (٥٥/ ب)."],[10865,"ذكر ابن حجر في تعجيل المنفعة بأن أبا أحمد الحاكم ذكر أبا زياد الطحان في الكنى فيمن لا يعرف اسمه فقال: أبو زياد الطحان الهاشمى مولى الحسن بن على، حديثه في البصريين\" أهـ -ولم أقف عليه في الكنى للحاكم. واللَّه أعلم. انظر مصادر الترجمة."],[10866,"(١) الجرح (٤/ ٢/ ٣٧٣) وقال: ذكره أبى عن إسحاق بن منصور عن يحيى بن معين قال: أبو زياد الطحان ثقة. . سألت أبى عن أبى زياد الطحان فقال: شيخ صالح الحديث."],[10867,"١٦٦٢ - المقتنى في سرد الكنى (٥٥/ ب)."],[10868,"١٦٦٣ - كنى البخارى (ص ٣٢)، الجرح (٤/ ٢/ ٣٧٣). كنى ابن منده (١٢٤/ أ) المقتنى في سرد الكنى (٥٥/ ب) وقال: أبو زياد عن مولاه ابن عباس وعنه أبو حذيفة شيخ لشعبة. اهـ."],[10869,"قلت: وأبو حذيفة شيخ شعبة تقدم انظر الترجمة (٦٢١) وقد قيل: إنما هو أبو اليمان حذيفة صحفه شعبة. انظر الترجمه (١٢٣٦)."],[10870,"١٦٦٤ - أبو زياد التيمى، كوفى، عن النعمان بن بشير، روى عنه أشعث بن سوار."],[10871,"١٦٦٥ - أبو زياد. قال: رأيت قاتل عمار بواسط القصب (١) مع الحجاج رجلًا من جهينة (٢) عليه مقطعات. روى عنه أبو المنهال."],[10872,"١٦٦٦ - أبو زياد الفقيمى. روى عن أبى حريز. روى عنه أحمد بن عبد اللَّه ابن يونس. شيخ ثقة."],[10873,"١٦٦٤ - كنى البخارى (ص ٣٢)، الجرح (٤/ ٢/ ٣٧٣)، الميزان (٤/ ٥٢٦) اللسان (٧/ ٤٩)، كنى ابن منده (١٢٤/ ب). المقتنى في سرد الكنى (٥٥/ ب)."],[10874,"١٦٦٥ - كنى ابن منده (١٢٤/ أ)."],[10875,"(١) واسط القصب: سميت بذلك لأنها متوسطة بين البصرة والكوفة. انظر معجم البلدان (٥/ ٣٤٧)، مراصد الاطلاع (٣/ ١٤١٩)."],[10876,"(٢) قاتل عمار هو أبو الغادية الجهنى واسمه يسار بن عبدة كما تقدم في الصحابة. انظر الترجمة (٢٦٣)."],[10877,"١٦٦٦ - المجرح (٤/ ٢/ ٣٧٣) وقال: سألت أبى عنه فقال: شيخ لا بأس به."],[10878,"باب أبى الزبير"],[10879,"١٦٦٧ - أبو الزبير مؤذن بيت المقدس (١). سمع عمر بن الخطاب. روى عنه عبد العزيز. والد مرحوم العطار."],[10880,"١٦٦٨ - أبو الزبير الدرمكى، كوفى. روى عن جبلة بن سحيم. روى عنه عمر."],[10881,"١٦٦٧ - كنى مسلم (ص ٤١٠)، الجرح (٤/ ٢/ ٣٧٤)، الثقات (٥/ ٥٧٢)، كنى ابن منده (١٢٥/ ب)."],[10882,"(١) بيت المقدس: بالفتح، ثم السكون، وتخفيف الدال، كسرها: أى البيت المطهر الذى يتطهر به من الذنوب، وهو مسجد كبير متسع الاقطار في وسط مدينة كبيرة تسمى المقدس انظر مراصد الاطلاع ٤/ ١٢٩٦ قلت: والمسجد الاقصى -في فلسطين مشهور معروف."],[10883,"١٦٦٨ - كنى ابن منده (١٢٥/ ب) وقال: أبو الزبير الدرمكى كوفى، حدث عن جبلة ابن سحيم، سمعت محمد بن يعقوب قال: سمعت الدورى قال: سمعت يحيى بن معين قال: أبو الزبير: حدث عن جبلة بن سحيم كوفى. اهـ."],[10884,"وقال المزى في تهذيب الكمال (١/ ١٨٤) في ترجمة جبلة بن سحيم: روى عنه جعفر بن أبى الزبير الدرمكى. وفى المغنى (ص ٣١) الدرمكى: بمفتوحة وسكون راء، وفتح ميم - نسبة إلى درمك. اهـ."],[10885,"وقال ابن منظور في لسان العرب (١٠/ ٤٢٣) مادة \"درك\": الدرمك دقيق الحوارى. قال ابن الاعرابى: الدرمك: النقى الحوارى. . قال خالد: الدرمك الذى يدرمك حتى يكون دقاقا من كل شئ، الدقيق، والكحل وغيرهما، وكذلك التراب الدقيق. اهـ."],[10886,"باب أبى زهير"],[10887,"١٦٦٩ - أبو زهير بن معاذ بن رباح (١) الثقفى. سمع أباه عن عمته سارة (٢) عن ميمونة بنت كردم (٣)."],[10888,"١٦٧٠ - أبو زهير الجزرى، روى عنه موسى بن اعين حديثا مرسلا."],[10889,"١٦٦٩ - كنى البخارى (ص ٣٣)، الجرح (٤/ ٢/ ٣٧٤)."],[10890,"(١) معاذ بن رباح الثقفى. صحابى، له حديث./ ق. التقريب (٢/ ٤٢٥) التهذيب (١٢/ ١٠١)."],[10891,"(٢) هى سارة نجت مقسم الثقفية. لا تعرف، من الرابعة. التقريب (٢/ ٦٠١)."],[10892,"(٣) ميمونة بنت كردم، وزن جعفر، الثقفية، من صغار الصحابة، لها حديث. التقريب (٢/ ٦١٥)."],[10893,"١٦٧٠ - كنى البخارى (ص ٣٣)، الجرح (٤/ ٢/ ٣٧٤)، كنى ابن منده (١٢٥/ ب) وقال: حديثه مرسل."],[10894,"افراد"],[10895,"١٦٧١ - أبو زرعة. روى عن أبى ادريس عن ثوبان عن النبى عليه (السلام) (١) أنه \"لعن الراشى والمرتشى\" (٢)."],[10896,"١٦٧١ - كنى البخارى (ص ٣٢)، الجرح (٤/ ٢/ ٣٧٤) وقال: سألت أبى عنه فقال: مجهول، الميزان (٤/ ٥٢٥)، التهذيب (١٢/ ١٠٠) التقريب (٢/ ٤٢٤) وقال: قيل هو ابن عمرو بن جرير، والا فهو مجهول من الخامسة./ ت."],[10897,"(١) ليست في الأصل. والسياق يقتضيها."],[10898,"(٢) الحديث أخرجه أحمد (٥/ ٢٧٩)، والبزار كما في كشف الاستار (٢/ ١٢٤) وابن أبى شيبة (٦/ ٥٨٧)، ووكيع في أخبار القضاة (١/ ٤٩) كلهم أخرجوه من طريق ليث عن أبى الخطاب -وليس في سنده عند البزار أبو الخطاب- عن أبى زرعة، عن أبى ادريس عن ثوبان قال: لعن رسول اللَّه -صلى الله عليه وآله وسلم- الراشى والمرتشى والرائش -يعنى الذى يمشى بينهما. وقال البزار: قوله الرائش لا نعلمها إلا من هذا الطريق وإنما يرويه ليث بن أبى سليم عن أبى زرعة عن أبى ادريس، وقد أدخل ذؤاد بن عليه بينه وبين أبى زرعة رجلا فذكره عن أبى الخطاب، وأبو الخطاب فليس بالمعروف إلا أنه قد روى عنه ليث غير حديث."],[10899,"وأخرجه أيضا الحاكم (٤/ ١٠٣). والحديث ذكره الهيثمى في مجمع الزوائد (٤/ ١٩٨) من حديث ثوبان به وقال: رواه أحمد، والبزار والطبرانى في الكبير وفيه أبو الخطاب وهو مجهول."],[10900,"ويشهد لهذا الحديث حديث عبد اللَّه بن عمرو رضي الله عنهما أخرجه الترمذى \"الأحكام\" باب ما جاء في الراشى والمرتشى في الحكم (٤/ ٥٦٧) وقال: حديث حسن صحيح. وابن ماجه \"الأحكام\" باب التغليظ في الحيف والرشوة (٢/ ٧٧٥)، وأبو داود \"الاقضية\" باب كراهية الرشوة (٣/ ٣٠٠)، والحاكم (٤/ ١٠٢) وقال: حديث صحيح الاسناد ولم يخرجاه، ووافقه الذهبى، والطبرانى في الصغير (١/ ٢٨). = روى عنه أبو الخطاب (١)."],[10901,"١٦٧٢ - أبو الزعيزعه (٢)، كاتب مروان (٣)، روى عن أبى هريرة وعن مكحول. روى عنه عمرو بن عبيد الأنصارى (٤) مجهول في حمل العلم لا يحتج به."],[10902,"١٦٧٣ - أبو الزرقاء الهمدانى. كوفى سمع مرة بن شراحيل الطيب (٥). روى عنه شعبة بن الحجاج."],[10903,"= وقال الهيثمى في مجمع الزوائد (٤/ ١٩٩): رجال الطبرانى ثقات."],[10904,"ويشهد له أيضا حديث أبى هريرة رضي الله عنه مرفوعا أخرجه الترمذى \"الأحكام\" (٤/ ٥٦٥) وحسنه، وابن حبان كما في موارد الظمآن (ص ٢٩٠) والحاكم (٤/ ١٠٣) بلفظ \"لعن رسول اللَّه -صلى الله عليه وآله وسلم- الراشى والمرتشى في الحكم\"."],[10905,"(١) أبو الخطاب تقدم في (١٥٧٨) وقال ابن عبد البر في ترجمته: روى عن أبى زرعة، هو عندهم مجهول. اهـ."],[10906,"١٦٧٢ - كنى البخارى (ص ٣٣)، الجرح (٤/ ٢/ ٣٧٥)، الميزان (٤/ ٥٢٥) اللسان (٧/ ٤٨)، كنى ابن منده (٢٩/ ب)."],[10907,"(٢) هكذا في الأصل \"الزعيزعة\" وفى كنى البخارى، والجرح، واللسان \"الزعزعة\" وفى الإصابة (٤/ ٢٠٥) في ترجمة أبى هريرة \"أبو الزعيزعة كاتب مروان\"."],[10908,"(٣) هو مروان بن الحكم بن أبى العاص بن أمية أبو عبد الملك الأموى المدنى، ولى الخلافة في آخر سنة أربع وستين، ومات سنة خمس وستين في رمضان، وله ثلاث أو احدى وستون سنة. لا يثبت له صحبة، من الثانية./ خ عـ. التقريب (٢/ ٢٣٨)."],[10909,"(٤) ترجمته في الجرح (٣/ ١/ ٢٤٦)."],[10910,"١٦٧٣ - كنى ابن منده (١٢٦/ أ) ذكره كما هنا وقال: أراه الزبرقان. اهـ."],[10911,"(٥) مرة بن شراحيل الطيب، ثقة عابد، من الثانية (ت: ٧٦) وقيل بعد ذلك./ ع. التقريب (٢/ ٢٣٨)."],[10912,"١٦٧٤ - أبو زينب مولى حازم بن حرملة (١). حجازى، عن حازم بن حرملة. روى عنه (سعيد بن خالد) (٢)."],[10913,"١٦٧٥ - أبو الزبرقان (٣). عن عبد اللَّه بن عمرو بن العاص. روى عنه سماك ابن حرب."],[10914,"١٦٧٤ - كنى ابن منده (١٢٩/ ب)، تهذيب الكمال (٣/ ١٦٠٧)، التهذيب (١٢/ ١٠٤)، التقريب (٢/ ٤٢٥) وقال: مجهول، من الرابعة./ ق."],[10915,"(١) حازم بن حرملة الغفارى صحابى، له حديث واحد في الذكر. ق/ التقريب (١/ ١٤٦)."],[10916,"(٢) هكذا في الأصل \"سعيد بن خالد\" والذى في كنى ابن منده، وتهذيب الكمال، والتهذيب \"أبو زينب مولى حازم بن حرملة الغفارى حجازى لا يعرف اسمه، روى عن مولاه حازم بن حرمله، وأبى ذر الغفارى، روى عنه خالد بن سعيد بن أبى مريم."],[10917,"وأخرج ابن ماجه في السنن \"كتاب الأدب\" - باب ما جاء في \"لا حول ولا قوة إلا باللَّه\" (٢/ ١٢٥٧) من طريق خالد بن سعيد، عن أبى زينب مولى حازم بن حرملة، عن حازم بن حرملة، قال: مررت بالنبى -صلى الله عليه وآله وسلم- فقال لى: يا حازم أكثر من قول: لا حول ولا قوة إلا باللَّه فانها من كنوز الجنة\"."],[10918,"وقال السندى: في الزوائد: في اسناده مقال، وأبو زينب لم يسم ولم أر من جرحه ولا من وثقه، وخالد بن سعيد هو ابن أبى مريم التيمى، ذكره ابن حبان في الثقات. . ثم إن المصنف لم يخرج لأبى حازم بن حرملة هذا غير هذا الحديث وليس له شئ في بقية الكتب. اهـ."],[10919,"وذكر المزى في تهذيب الكمال (١/ ٢٢٢) في ترجمة حازم بن حرملة الغفارى قال: روى عنه أبو زينب روى له ابن ماجه وقد وقع لنا حديثه عاليا ثم - ذكر الحديث باسناده المتصل إلى خالد بن سعيد المدنى، عن أبى زينب مولى حازم بن حرملة الغفارى. فذكر الحديث مرفوعا به."],[10920,"من هذا يتبين أن الراوى عن أبى زينب إنما هو خالد بن سعيد. وليس كما هو مذكور \"سعيد بن خالد\". واللَّه أعلم."],[10921,"١٦٧٥ - كنى مسلم (ص ٤١٦)."],[10922,"(٣) الزِّبْرِقان: بكسر زاى وسكون موحدة كسر راء وبقاف. المغنى (ص ٣٥)."],[10923,"١٦٧٦ - أبو زبيد (١) الهمدانى، سمع أبا أيوب الأنصارى، روى عنه يزيد بن خمير (٢)."],[10924,"١٦٧٧ - أبو زبيبة عن أبى بكرة وعبد الرحمن بن سمرة. روى عنه عاصم بن سليمان الاحول."],[10925,"١٦٧٦ - كنى البخارى (ص ٣٣)، الثقات (٥/ ٥٨٥)، الجرح (٤/ ٢/ ٣٧٥) كنى ابن منده (١٢٩/ ب)."],[10926,"(١) زبيد: بضم الزاى وفتح الباء المعجمة بواحدة وسكون الياء. الاكمال (٤/ ١٦٩)."],[10927,"(٢) يزيد بن خمير، بمعجمة، مصغرا الرحبى الهمدانى، أبو عمر الحمصى، صدوق، من الخامسة. التقريب (٢/ ٣٦٤)، التهذيب (١١/ ٣٢٣)."],[10928,"١٦٧٧ - كنى ابن منده (١٢٩/ ب)."],[10929,"باب الطاء"],[10930,"باب أبى طلحة"],[10931,"١٦٧٨ - أبو طلحة الاسدى، عن عبد اللَّه بن عباس، وأنس بن مالك، روى عنه أبو العميس (عتبة) (١) بن عبد اللَّه والرُّكين بن الربيع (٢) وإبراهيم بن محمد ابن حاطب (٣)."],[10932,"١٦٧٩ - أبو طلحة الخولانى، شامى، روى عن الضحاك بن عبد الرحمن ابن عرزب، عن أبى موسى الاشعرى. روى عنه أبو سنان عيسى بن سنان (٤)."],[10933,"١٦٨٠ - أبو طلحة عن شريح. روى عنه ابن المنتشر (٥)."],[10934,"١٦٧٨ - كنى البخارى (ص ٤٥)، الثقات (٥/ ٥٧٤)، كنى ابن منده (١٦٨/ أ) كنى الحاكم (١/ ٢٥١/ ب)، الجرح (٤/ ٢/ ٣٩٦)، التهذيب (١٢/ ١٣٨)، التقريب (٢/ ٤٤٠) وقال: مقبول، من الرابعة./ د."],[10935,"(١) جاء في التهذيب \"عبيد\" وهو خطأ."],[10936,"(٢) الركين بالتغصير ابن الربيع بن عميلة بفتح المهملة الفزارى، أبو الربيع الكوفى، ثقة، من الرابعة (ت: ١٣١)، التقريب (١/ ٢٥٢)."],[10937,"(٣) مدنى صدوق، من الخامسة./ د التقريب (١/ ٤١)."],[10938,"١٦٧٩ - كنى البخارى (ص ٤٥)، كنى الحاكم (١/ ٢٥٢/ ب)، كنى ابن منده (١٦٨/ ب)، الجرح (٤/ ٢/ ٣٩٦)، التهذيب (١٢/ ١٣٨)، التقريب (٢/ ٤٤٠) وقال: مقبول، من الثالثة، وحديثه عن النبى -صلى الله عليه وآله وسلم- مرسل وقد قيل: اسمه سفيان بن عبد اللَّه./ ت."],[10939,"(٤) هو القسملى تقدم في (١١٠٥)."],[10940,"١٦٨٠ - كنى البخارى (ص ٤٥)، كنى الحاكم (١/ ٢٥٢/ أ)، الجرح (٤/ ٢/ ٣٩٧)، كنى ابن منده (٦٨/ ب)."],[10941,"(٥) منتشر: بضم الميم وبسكون النون وتاء معجمة باثنتين. انظر الاكمال ="],[10942,"١٦٨١ - أبو طلحة. سمع ماهان الحنفى (١). روى عنه ابن عيينة."],[10943,"١٦٨٢ - أبو طلحة المدنى، روى عنه معن بن عيسى القزاز."],[10944,"= (٨/ ٢٩٨). وابن المنتشر هو إبراهيم بن محمد بن المنتشر الاجدع الهمدانى الكوفى، ثقة من الخامسة. انظر تهذيب الكمال (١/ ٦٣)، التقريب (١/ ٤٢)."],[10945,"١٦٨١ - كنى البخارى (ص ٤٥)، الجرح (٤/ ٢/ ٣٩٧)."],[10946,"(١) هو أبو صالح ماهان الحنفى تقدم في (٨٩٨)."],[10947,"١٦٨٢ - كنى البخارى (ص ٤٥)، الجرح (٤/ ٢/ ٣٩٧)، كنى ابن منده (١٦٨/ ب)."],[10948,"باب أبى طالب"],[10949,"١٦٨٣ - أبو طالب. روى عن أبى ذر، عن النبى -صلى الله عليه وآله وسلم- من حديث الليث عن عبيد اللَّه بن أبى جعفر (١)."],[10950,"١٦٨٤ - أبو طالب الضبعى الحجام. روى عن ابن عباس روى عنه قتادة قال ابن أبى حاتم (٢): نا يونس بن حبيب (٣) قال: نا أبو داود الطيالسى قال: نا"],[10951,"١٦٨٣ - كنى البخارى (ص ٤٥)، كنى الحاكم (١/ ٢٥٦/ أ)، الجرح (٤/ ٢/ ٣٩٧) تعجيل المنفعة (ص ٣٢٥)."],[10952,"(١) عبيد اللَّه بن أبى جعفر المصرى، أبو بكر الفقيه، مولى بنى كنانة أو أمية. قيل: اسم أبيه يسار. بتحتانية ومهملة، ثقة. وقيل: عن أحمد: انه لينه. وكان فقيها عابدا."],[10953,"قال أبو حاتم: هو مثل يزيد بن أبى حبيب، من الخامسة./ ع. التقريب (١/ ٥٣١)."],[10954,"قلت: والحديث المذكور أخرجه أحمد في المسند (٥/ ١٥٥) والبخارى في الكنى (ص ٤٥) من طريق الليث بن سعد عن عبيد اللَّه بن أبى جعفر عن أبى طالب، عند البخارى. وعند أحمد عن عبيد اللَّه بن أبى جعفر عن الحمصى، عن أبى طالب، عن أبى ذر قال: سمعت رسول اللَّه -صلى الله عليه وآله وسلم- يقول: من زنى امة لم يرها تزنى جلده اللَّه يوم القيامة بسوط من نار."],[10955,"والحديث ذكره السيوطى في الجامع الصغير (٢/ ١٧٢) وعزاه لأحمد. ورمز لحسنه."],[10956,"١٦٨٤ - كنى البخارى (ص ٤٦)، كنى الحاكم (١/ ٢٥٦/ أ)، كنى ابن منده (١٦٩/ ب)، الثقات (٥/ ٥٧٤)، الجرح (٤/ ٢/ ٣٩٧)، اللسان (٧/ ٦٧)."],[10957,"(٢) انظر الجرح (٤/ ٢/ ٣٩٧)."],[10958,"(٣) يونس بن حبيب بن عبد القاهر بن عبد العزيز بن عمرو بن قيس الماصر العجلى، أبو بشر، وثقه ابن أبى حاتم. انظر الجرح (٤/ ٢/ ٢٣٧)."],[10959,"شعبة عن قتادة قال: سمعت أبا طالب الحجام - واثنى عليه خيرا يحدث عن ابن عباس. قال (١): ونا عمرو بن عبد اللَّه الاودى (٢) قال: نا وكيع عن شعبة عن قتادة عن أبى طالب الحجام عن ابن عباس قال وكيع: وكان ثقة. قال (٣): ونا أبى قال: نا ابن أبى مريم (٤) قال: نا مخلد بن يزيد (٥) قال: حدثنى شعبة عن قتادة عن أبى طالب الحجام قال: وكان رجل صدق. سئل أبو زرعة عن اسم أبى طالب الحجام فقال (٦): لا أعرف اسمه. وهو بصرى ثقة."],[10960,"١٦٨٥ - أبو طالب، سمع أبا هريرة، روى عنه يحيى بن أبى كثير."],[10961,"(١، ٢) انظر الجرح (٤/ ٢/ ٣٩٧)."],[10962,"(٣) عمرو بن عبد اللَّه بن حنش بفتح المهملة والنون بعدها معجمة ويقال: ابن محمد بن حنش الاودى، ثقة، من العاشرة. (ت: ٢٥٠)، التقريب (٢/ ٧٣)."],[10963,"(٤) ابن أبى مريم: قال ابن حجر في التقريب (٢/ ٥٢٦): ابن أبى مريم بصرى، وشامى، وحمصى، ومصرى، فالبصرى بريد، بالموحدة والشامى، يزيد بالزاى، والحمصى، أبو بكر بن عبد اللَّه بن أبى مريم والمصرى، سعيد بن الحكم بن أبى مريم. اهـ."],[10964,"قلت: والمراد هنا هو سعيد بن الحكم بن محمد بن سالم المعروف بابن أبى مريم الجمحى أبو محمد المصرى، مولى أبى الضبيع مولى بنى جمح حدث عنه يحيى بن معين وأبو حاتم الرازى، وآخرون، وهو ثقة ثبت فقيه، من كبار العاشر، (ت: ٢٢٤) /ع. التقريب (١/ ٢٩٣) التهذيب (٤/ ١٧)."],[10965,"(٥) صدوق له أوهام، من كبار التاسعة (ت: ١٩٣)، التقريب (٢/ ٢٣٥)."],[10966,"(٦) انظر الجرح (٤/ ٢/ ٣٩٧)."],[10967,"١٦٨٥ - كنى البخارى (ص ٤٦)، كنى الحاكم (١/ ٢٥٦/ أ)، كنى ابن مندة (١٦٩/ ب)."],[10968,"١٦٨٦ - أبو طالب، عن طالوت العُرْفُطى (١). روى عنه النضر بن إسماعيل (٢)."],[10969,"١٦٨٦ - كنى البخارى (ص ٤٦)، كنى الحاكم (١/ ٢٥٦/ أ)، الجرح (٤/ ٢/ ٣٩٧) كنى ابن منده (١٦٩/ ب)."],[10970,"(١) العرفطى: بضم العين وسكون الراء وضم فاء وفى آخرها طاء مهملة - هذه النسبة إلى عرفطة، وهو جد طالوت بن أبى بكر بن خالد بن عرفطة العرفطى حليف بنى زهرة، روى عن عمر رضي الله عنه روى عنه أبو طالب يحيى بن يعقوب بن مدرك. اللباب (٢/ ٣٣٥). وفى الجرح أيضا (٢/ ١/ ٤٩٥) ذكر ابن أبى حاتم في ترجمة طالوت بن أبى بكر بن خالد بن عرفطه ويقال العرفطى حليف بنى زهرة بأنه روى عن عمر رضي الله عنه وروى عنه أبو طالب القاضى يحيى بن يعقوب بن مدرك. فاللَّه أعلم."],[10971,"(٢) النضر بن إسماعيل بن حازم البجلى، أبو المغيرة الكوفى، القاص، ليس بالقوى، من صغار الثامنة (ت: ١٨٢) ت. س. التقريب (٢/ ٣٠١). وانظر التهذيب (١٠/ ٤٣٤)."],[10972,"باب أبى طاهر"],[10973,"١٦٨٧ - أبو طاهر مولى الحسن (١) بن على. رأى أنس بن مالك. روى عنه حفص بن غياث، رآه بواسط، روى محمد بن القاسم الاسدى (٢) قال: سألت أبا طاهر مولى الحسن بن على عن اسمه فقال: ما اسمى إلا أبو الطاهر (٣)."],[10974,"١٦٨٨ - أبو طاهر، عن عبد اللَّه بن عبيد بن عمير (٤). روى عنه سلام بن مسكين. وقيل: انه روى عن أبى وائل (٥)."],[10975,"١٦٨٩ - أبو طاهر، عن أبى يزيد المدنى، روى عنه جعفر بن سليمان."],[10976,"١٦٨٧ - كنى البخارى (ص ٤٦)، الحاكم (١/ ٢٥٦/ ب)، الثقات (٥/ ٥٧٥) الجرح (٤/ ٢/ ٣٩٧)، كنى ابن منده (١٧٠/ أ) وقال: روى عنه محمد بن القاسم الاسدى وسئل عن اسمه فقال: لا يعرف له اسم غيره. اهـ."],[10977,"(١) في كنى البخارى والجرح \"الحسين\"."],[10978,"(٢) محمد بن القاسم الاسدى، أبو القاسم الكوفى، شامى الأصل، لقبه كاو، كذبوه، من التاسعة (ت: ٢٠٧) ت. التقريب (٢/ ٢٠١)."],[10979,"(٣) ومثله في كنى الحاكم، والجرح."],[10980,"١٦٨٨ - كنى البخارى (ص ٤٦)، كنى الحاكم (١/ ٢٥٦/ ب)، الجرح (٤/ ٢/ ٣٩٨) كنى ابن منده (١٧٠/ أ)."],[10981,"(٤) مكى، ثقة، من الثالثة، استشهد غازيا سنة (١١٣)، التقريب (١/ ٤٣١)."],[10982,"(٥) هو شقيق بن سلمة."],[10983,"١٦٨٩ - كنى البخارى (ص ٤٦)، كنى الحاكم (١/ ٢٥٧/ أ)، الجرح (٤/ ٢/ ٣٩٨) كنى ابن منده (١٧٠/ أ)."],[10984,"باب أبى طالوت"],[10985,"١٦٩٠ - أبو طالوت. سمع أنس بن مالك. روى عنه معاوية بن صالح. يعد في الشاميين. حدث معاوية بن صالح عن أبى طالوت عن أنس عن النبى عليه السلام \"أنه كان يحب القرع\" (١)."],[10986,"١٦٩١ - أبو طالوت، سمع أبا أمامة، روى عنه أبو الهندى (٢)."],[10987,"١٦٩٢ - أبو طالوت. سمع أبا السليل (٣)."],[10988,"١٦٩٠ - كنى البخارى (ص ٤٦)، كنى الحاكم (١/ ٢٥٧/ أ)، الجرح (٤/ ٢/ ٣٩٩) الميزان (٤/ ٥٤١)، التهذيب (١٢/ ١٣٦)، التقريب (٢/ ٤٤٠). وقال: مجهول، من الخامسة./ ت."],[10989,"(١) الحديث أخرجه البخارى في الكنى، والحاكم في الكنى، وابن أبى حاتم في الجرح كما في مصادر الترجمة، وأخرجه أيضا البخارى \"الأطعمة\" باب الدباء (٩/ ٥٥٩) وفى باب المرق (٩/ ٥٦٢)، ومسلم \"الأشربة\" باب جواز أكل المرق واستحباب أكل اليقطين (٣/ ١٦١٥) ومالك في الموطأ (٢/ ٥٤٦) وأحمد في المسند (٣/ ١٦٩ و١٧٤ و١٧٧ و٢٧٤) وابن ماجه \"الأطعمة\" باب الدباء (٢/ ١٠٩٨)، وعبد الرزاق (١٠/ ٤٤٨) والترمذى في الشمائل (ص ٨٧) و(ص ١٧١)، والدارمى (٢/ ١٠١) والنسائى في السنن الكبرى. كما في تحفة الاشراف (١/ ٤٢١)، وأبو بكر الشافعى في الفوائد (٩٥٣) و(٩٥٤) و(٩٥٨) و(٩٥٩) كلهم أخرجوه من حديث أنس رضي الله عنه به، وبألفاظ متقاربة."],[10990,"١٦٩١ - كنى البخارى (ص ٤٦)، كنى الحاكم (١/ ٢٥٧/ أ)، كنى ابن منده (١٧٠/ ب)."],[10991,"(٢) سيأتى في آخر هذا الكتاب. انظر الترجمة (٢٥٠٢)."],[10992,"١٦٩٢ - كنى الحاكم (١/ ٢٥٧/ أ)، كنى ابن منده (١٧٠/ ب)."],[10993,"(٣) هو ضريب بن نفير."],[10994,"باب أبى طارق"],[10995,"١٦٩٣ - أبو طارق الاحمسى. كوفى."],[10996,"١٦٩٤ - أبو طارق البصرى (١)، روى عن الحسن بن أبى الحسن، روى عنه جعفر بن سليمان الضبعى."],[10997,"١٦٩٥ - أبو طارق الازدى، عن بلال. روى عنه يزيد بن أبى زياد."],[10998,"١٦٩٦ - أبو طارق السراج، سمع سعيد بن جبير، روى عنه وكيع، وأبو نعيم - كوفى."],[10999,"١٦٩٣ - كنى ابن منده (١٧٠/ ب) وقال: أبو طارق الاحمسى من بجيلة، ذكره الواقدى في الكوفيين. اهـ. كنى الحاكم (١/ ٢٥٧/ ب) وقال: أبو طارق الاحمسى، ذكره أبو عبد اللَّه محمد بن عمر الواقدى في الطبقات في ذكر الكوفيين. اهـ."],[11000,"١٦٩٤ - كنى الحاكم (١/ ٢٥٧/ أ)، الميزان (٤/ ٥٤٠)، كنى ابن منده (١٧٠/ ب)."],[11001,"(١) الذى في كنى ابن منده \"السعدى\"."],[11002,"١٦٩٥ - كنى البخارى (ص ٤٧)، كنى الحاكم (١/ ٢٥٧/ ب)، الثقات (٥/ ٥٧٤) كنى ابن منده (١٧٠/ أ)."],[11003,"١٦٩٦ - كنى البخارى (ص ٤٧)، كنى الحاكم (١/ ٢٥٧/ ب)، كنى ابن منده (١٧٠/ ب)، الثقات (٧/ ٦٦٠)، الجرح (٤/ ٢/ ٣٩٨)."],[11004,"باب أبى طعمة"],[11005,"١٦٩٧ - أبو طُعمة (١)، مولى عمر بن عبد العزيز (٢). سمع عبد اللَّه بن عمر. أصله الشام، وكان قاصا بمصر. روى عنه ابنا (٣) يزيد بن جابر، وعبد اللَّه ابن عيسى (٤) وابن لهيعة - رماه مكحول بالكذب (٥)."],[11006,"١٦٩٧ - كنى البخارى (ص ٤٧)، كنى ابن منده (١٧٠/ ب)، كنى الحاكم (١/ ٢٥٧/ ب)، الجرح (٤/ ٢/ ٣٩٨)، مسائل الإمام أحمد، رواية ابن هانئ النيسابورى (٢/ ٢٤٤)، تهذيب الكمال (٣/ ١٦١٧)، الميزان (٤/ ٥٤١)، التهذيب (١٢/ ١٣٧)، التقريب (٢/ ٤٤٠) وقال: يقال: اسمه هلال، مقبول، من الرابعة، ولم يثبت أن مكحولا، رماه بالكذب./ د. سى. ق."],[11007,"(١) طعمة: بمضمومة وسكون عين مهملة. المغنى (ص ٤٩)."],[11008,"(٢) في تهذيب الكمال، والميزان، والتهذيب، وبعض المصادر \"اسمه هلال\"."],[11009,"(٣) ابنا يزيد بن جابر، هما عبد الرحمن، ويزيد كما صرح بذلك المزى في تهذيب الكمال."],[11010,"قلت: فأما عبد الرحمن بن يزيد بن جابر فقد تقدم، وأما يزيد فقد نزل البصرة ثم تحول إلى دمشق، وهو ثقة فقيه، من السادسة (ت: ١٣٤) انظر التهذيب (١١/ ٣٧٠)، والتقريب (٢/ ٣٧٢). قلت: وهناك رجل يسمى يزيد ابن يزيد بن جابر لكنه رقى، مجهول، ومن الطبقة السابعة وهو غير الأول."],[11011,"(٤) عبد اللَّه بن عيسى، كوفى، ثقة، فيه تشيع، من السادسة (ت: ١٣٠). انظر التقريب (١/ ٤٣٩)، التهذيب (٥/ ٣٥٢)."],[11012,"(٥) قال الحاكم في الكنى (١/ ٢٥٧/ ب) وتبعة المزى في تهذيب الكمال (٣/ ١٦١٧): رماه مكحول بالكذب."],[11013,"لكن قال ابن حجر في التهذيب (١٢/ ١٣٧) بعد أن ذكر قول الحاكم: قلت: لم يكذبه مكحول التكذيب الاصطلاحى وإنما روى الوليد بن مسلم عن ابن جابر أن أبا طعمة حدث مكحولا بشئ وقال: ذروه يكذب. هذا محتمل أن يكون مكحول طعن فيه على من فوق أبى طعمة. واللَّه أعلم. اهـ."],[11014,"١٦٩٨ - أبو طعمة، عن عبد اللَّه بن عمرو بن العاص، روى عنه يحيى بن أبى كثير، قال أبو أحمد الحاكم في كتاب الأسماء والكنى: \"لا أدرى اهو الأول أم لا؟ \" (١)."],[11015,"١٦٩٨ - كنى ابن منده (١٧٠/ ب)، كنى الحاكم (١/ ٢٥٧/ ب)، التهذيب (١٢/ ١٣٨)، التقريب (٢/ ٤٤٠) وقال: أبو طعمة شيخ ليحيى بن أبى كثير. وقيل: هو هلال المذكور أولا والا فمجهول، من الثالثة./ د. س."],[11016,"(١) انظر كنى الحاكم (١/ ٢٥٧/ ب)."],[11017,"باب افراد"],[11018,"١٦٩٩ - أبو طليب مولى أنس بن مالك. روى عن أنس بن مالك. روى عنه محمد بن اسحاق."],[11019,"١٧٠٠ - أبو الطيب، روى عن عكرمة، روى عنه شبابة بن سوار قال عبد اللَّه بن أحمد بن حنبل: سألت أبى عن أبى الطيب الذى روى عن عكرمة، روى عنه شبابه فقال: أراه شيخا ثقة. قد حدث ابن المبارك عن رجل عنه (١)."],[11020,"١٦٩٩ - كنى البخارى (ص ٤٧)، كنى الحاكم (١/ ٢٥٨/ أ)، الثقات (٥/ ٥٧٩)، الجرح (٤/ ٢/ ٣٩٨)، كنى ابن منده (١٧٠/ ب)."],[11021,"١٧٠٠ - الجرح (٤/ ٢/ ٣٩٨)، كنى ابن منده (١٧٠/ ب)."],[11022,"(١) العلل ومعرفة الرجال لأحمد (١/ ٣٦٨)، الجرح (٤/ ٢/ ٣٩٨)."],[11023,"الظاء"],[11024,"باب أبى ظبيان"],[11025,"١٧٠١ - أبو ظِبْيَان (١) القرشى كوفى، وليس بالجنبى (٢). روى عن عمر بن الخطاب. روى عنه سلمة بن كهيل والاعمش. وقد روى عن أبى ظبيان الجنبى سلمة بن كهيل ولم يرو أبو ظبيان الجنبى عن عمر، ولكنه روى عن على وعمار وسلمان وغيرهم."],[11026,"١٧٠١ - كنى البخارى (ص ٤٧)، كنى مسلم (ص ٥٤٧)، الثقات (٥/ ٥٧٤)، كنى ابن منده (١٧/ أ)، كنى الحاكم (١/ ٢٥٨/ ب)، الميزان (٤/ ٢/ ٤٤٢) تاريخ ابن معين (٢/ ٧١٢ و٣/ ٢٩٥)، التهذيب (١٢/ ١٤٠)، التقريب (٢/ ٤٤٢) وقال: مجهول، من الثالثة./ د."],[11027,"(١) ظبيان: قال ابن ماكولا في الاكمال (٥/ ٢٤٧): ظبيان، بكسر الظاء المعجمة وتقديم الباء والمعجمة على الياء. اهـ."],[11028,"وفى المغنى (ص ٥٠) ظبيان، بكسر الظاء عند المحدثين، وفتحها عند أهل اللغة، وسكون موحدة وبتحتية ونون. اهـ."],[11029,"(٢) أبو ظبيان الجنبى هو حصين بن جندب المتقدم في (٧٤١)."],[11030,"قلت: هكذا فرق ابن عبد البر هنا بين أبى ظبيان القرشى وبين أبى ظبيان الجنبى. وقال: لم يرو الثانى عن عمر. وفردتى بينهما أيضا ابن معين في التاريخ وابن منده في الكنى والحاكم في الكنى."],[11031,"ولكن قال ابن حجر في التهذيب (٢/ ٣٧٩) في ترجمة حصين بن جندب أبى ظبيان الجنبى: روى عن عمر وعلى. . روى عنه سلمة بن كهيل. فكأنه جعلهما رجلا واحدا واللَّه أعلم."],[11032,"١٧٠٢ - أبو ظبيان الازدى. سمع عمر. روى عنه موسى بن عبد اللَّه بن يزيد (١)."],[11033,"١٧٠٢ - كنى البخارى (ص ٤٧)، الثقات (٥/ ٥٧٥)، كنى الحاكم (١/ ٢٥٨/ ب) الجرح (٤/ ٢/ ٣٩٩)."],[11034,"(١) موسى بن عبد اللَّه بن يزيد الخطمى: بفتح المعجمة وسكون المهملة، الكوفى، ثقة، من الرابعة. التقريب (٢/ ٢٨٥)."],[11035,"فرد"],[11036,"١٧٠٣ - أبو ظَبْية (١) الكلاعى، شامى، من كبار التابعين. روى عن معاذ ابن جبل والمقداد بن الأسود، وعَمْرو بن عبسة (٢) وعبد اللَّه بن عمر روى عنه شهر بن حوشب ومحمد بن سعد وثابت البنانى."],[11037,"قال شهر بن حوشب: كان أبو ظبية الكلاعى من افضل رجال الشام (٣). وقال عثمان بن سعيد: قلت ليحيى بن معين: أبو ظبية الذى روى عنه محمد بن سعد الأنصارى؟ قال: ثقة (٤)."],[11038,"١٧٠٣ - كنى البخارى (ص ٤٧)، كنى مسلم (ص ٥٤٨)، الثقات (٥/ ٥٧٣) كنى الحاكم (١/ ٢٥٩/ أ)، الجرح (٤/ ٢/ ٣٩٩)، التهذيب (١٢/ ١٤٠) التقريب (٢/ ٤٤٢) وقال: مقبول، من الثانية./ بخ. د. س. ق."],[11039,"قلت: وقد تقدم صاحب هذه الترجمة بنحو ما هنا عند المؤلف في الكتاب الثانى وقال ابن عبد البر هناك: \"لا يوقف من اسمه على صحة\" انظر الترجمة (٧٤٩)."],[11040,"(١) ظَبْية: بظاء معجمة ثم باء معجمة بواحدة ثم ياء معجمة باثنتين من تحتها. الاكمال (٥/ ٢٥٠)."],[11041,"(٢) عمرو بن عَبْسَة: بموحدة ومهملتين مفتوحات، هو أبو نجيح العبسى المتقدم في (١٩٩)."],[11042,"(٣) يذكر ابن حجر: التهذيب (١٢/ ١٤١)."],[11043,"قال شهر بن حوشب: دخلت المسجد فإذا أبو أمامة جالس فجلست فجاء شيخ يقال له: أبو ظبية من أفضل رجل بالشام إلا رجلا من الصحابة."],[11044,"(٤) تاريخ يحيى رواية الدارمى (ص ١٩٧) و(ص ٢٣٦)."],[11045,"الكاف"],[11046,"باب أبى كثير"],[11047,"١٧٠٤ - أبو كثير. مولى بنى هاشم. سمع أبا ذر الغفارى أن التسبيح في دبر الصلاة يمحو الخطايا (١). روى عنه حُيى بن عبد اللَّه (٢)."],[11048,"١٧٠٤ - كنى البخارى (ص ٦٤)، الجرح (٤/ ٢/ ٤٢٩)، تعجيل المنفعة (ص ٣٣٨)."],[11049,"(١) الحديث أخرجه البخارى في الكنى، وابن أبى حاتم في الجرح. بهذا اللفظ وأخرجه أحمد في المسند (٥/ ١٧٣) من طريق ابن لهيعة، ثنا حيى بن عبد اللَّه أن أبا كثير مولى بنى هاشم حدثه أنه سمع أبا ذر الغفارى صاحب رسول اللَّه -صلى الله عليه وآله وسلم- يقول: كلمات من ذكرهن مائة مرة دبر كل صلاة، اللَّه اكبر، سبحان اللَّه والحمد اللَّه ولا اله إلا اللَّه وحده لا شريك له ولا حول ولا قوة إلا باللَّه ثم لو كانت خطاياه مثل زبد البحر لمحتهن - قال أبى: لم يرفعه."],[11050,"قلت: والذى في مطبوعة المسند \"ابن لهيعة ثنا يحيى بن عبد اللَّه\" وهو خطأ."],[11051,"والحديث ذكره الهيثمى في مجمع الزوائد (١٠/ ١٠١) من حديث أبى ذر برواية أبى كثير مولى بنى هاشم عنه. وقال: رواه أحمد موقوفا. وأبو كثير لم أعرفه، وبقية رجاله حديثهم حسن. اهـ."],[11052,"وذكره السيوطى في الجامع الصغير (٢/ ٩٥) وعزاه لا حمد ورمز لحسنه، وأخرجه أيضا النسائى في عمل اليوم والليلة (١٢٧) من حديث أبى ذر بنحوه."],[11053,"(٢) حيى: بضم أوله، ويائين من تحت، الأولى مفتوحة ابن عبد اللَّه بن شريح المعافرى، المصرى، صدوق، يهم، من السادسة (ت: ١٤٨) التقريب (١/ ٢٠٩)."],[11054,"١٧٠٥ - أبو كثير الأنصارى. سمع على بن أبى طالب عن النبى عليه السلام في المارقة (١). روى عنه بدر بن الخليل (٢)."],[11055,"١٧٠٥ - كنى البخارى (ص ٦٤)، الجرح (٤/ ٢/ ٤٢٩)، تاريخ بغداد (١٤/ ٣٦٢)."],[11056,"(١) الحديث أخرجه البخارى في الكنى (ص ٦٤)، وابن أبى حاتم في الجرح (٤/ ٢/ ٤٢٩) والخطيب في التاريخ (١٤/ ٣٦٢ - ٣٦٣)، والطيالسى (٦/ ١٨٦)، وأحمد في المسند (١/ ٨٨) كلهم أخرجوه من طريق أبى كثير الأنصارى سمع على بن أبى طالب، وفى المسند وتاريخ بغداد عن أبى كثير مولى الأنصار قال: كنت مع سيدى مع على بن أبى طالب حين قتل أهل النهروان. . فذكره وفيه قال على رضي الله عنه: يا أيها الناس ان رسول اللَّه -صلى الله عليه وآله وسلم- قد حدثنا بأقوام يمرقون من الدين كما يمرق السهم من الرمية، ثم لا يرجعون فيه ابدا حتى يرجع السهم على فوقه، وان آية ذلك أن فيهم رجلا أسود مخدج اليد، أحد ثديية كثدى المرأة لها حلمة كحلمة ثدى المرأة، له سبع هلبات فالتمسوه، فانى أراه فيهم. . الخ الحديث."],[11057,"هذا لفظ أحمد والخطيب بنحو هذا اللفظ، وهو عند البخارى وابن أبى حاتم مختصر، وذكر الهيثمى في مجمع الزوائد (٦/ ٢٢٥) هذا الحديث وعزاه لأحمد وقال: رجاله ثقات."],[11058,"وحديث على هذا أخرجه من طرق عن على وبألفاظ متقاربه البخارى \"فضائل القرآن\" باب اثم من راءى بالقرآن أو تأكل به أو فجر به (٩/ ٩٩) ومسلم \"الزكاة\" باب التحريض على قتل الخوارج (٢/ ٧٤٦ - ٧٥٠) وأبو داود \"السنة\" باب قتال الخوارج (٤/ ٢٤٢ - ٢٤٤)، وابن ماجه \"المقدمة\" باب في ذكر الخوارج (١/ ٥٩ - ٦١)، وأحمد في المسند (١/ ٩٢ و١٠٨ و١٣١ و١٤٧ و١٥١ و١٥٦ و١٦٠). والترمذى \"الفتن\" باب ما جاء في صفة المارقة (٦/ ٤٢٤). والحاكم في المستدرك (٤/ ٥٣١)، وابن أبى عاصم في السنة (٢/ ٤٣٩ - ٤٥٩)."],[11059,"(٢) بدر بن الخليل: أسدى، ذكره ابن أبى حاتم في الجرح (١/ ١/ ٤١٢) وقال عن أبيه: هو شيخ. اهـ."],[11060,"١٧٠٦ - أبو كثير، مولى محمد بن عبد اللَّه بن جحش (١)، روى عن محمد ابن عبيد اللَّه بن جحش، روى عنه العلاء بن عبد الرحمن."],[11061,"١٧٠٧ - أبو كثير المحاربى. سمع خَرَشَة (٢) بن الحر الفزارى (٣). روى عنه"],[11062,"١٧٠٦ - كنى البخارى (ص ٦٥)، الثقات (٥/ ٥٧٠)، الجرح (٤/ ٢/ ٤٢٩)، تهذيب الكمال (٣/ ١٦٤٠ - ١٦٤١)، التهذيب (١٢/ ٢١٠)، التقريب (٢/ ٤٦٦) وقال: ثقة، من الثانية، ويقال: له صحبة ومنهم من ضبطه بالموحدة، والتأنيث./ س."],[11063,"(١) الذى في كنى البخارى \"مولى عبد اللَّه بن جحش\" وفى تهذيب الكمال \"مولى آل جحش، ويقال: مولى محمد بن عبد اللَّه بن جحش القرشى الاسدى، ويقال: مولى الليثيين\"."],[11064,"١٧٠٧ - كنى البخارى (ص ٦٥)، الجرح (٤/ ٢/ ٤٣٠)، تعجيل المنفعة (ص ٣٣٨)."],[11065,"(٢) خَرَشة: بفتحات. الإصابة (١/ ٤٢٣)، المغنى (ص ٢٧)."],[11066,"(٣) هكذا ذكر ابن عبد البر هنا \"خرشة بن الحر الفزارى\" وجعله شيخا لأبى كثير المحاربى. وقال ابن حجر في تعجيل المنفعة في ترجمة أبى كثير: ذكره البخارى ولم يذكر فيه جرحا، وشيخه خرشة بن الحارث لا ابن الحر. واللَّه أعلم."],[11067,"وقال ابن حجر في الإصابة (١/ ٤٢٣) خَرَشَة بن الحارث أو ابن الحر المحاربى. . روى أحمد والبغوى والطبرانى وآخرون من طريق أبى كثير المحاربى سمعت خرشة يقول: . . فذكر حديثا مرفوعا ووقع في رواية الطبرانى خرشة المحاربى وفى رواية أحمد خرشة بن الحر وفى رواية الآخرين خرشة ابن الحارث وهو الراجح. . وقال أبو حاتم: خرشة شامى له صحبة روى عنه أبو كثير المحاربى وتعقبه ابن عبد البر وزعم أن الصواب أنه هو خرشة بن الحر، ولم يصب في ذلك، والحق أنهما اثنان، وقد فرق بينهما البخارى فذكر خرشة بن الحر في التابعين وذكر هذا في الصحابة، وكذلك صنع ابن حبان، وذكر أبو أحمد الحاكم في ترجمة أبى كثير في الكنى قول من قال عن أبى كثير، عن خرشة بن الحر ووهاه وصوب أنه خرشة بن الحارث. اهـ. ="],[11068,"ثابت بن عجلان (١)."],[11069,"١٧٠٨ - أبو كثير الأنصارى. سمع عليا. روى عنه إسماعيل بن مسلم العبدى قال أبو أحمد الحاكم: خليقا ان يكون الذى روى عنه بدر بن الخليل. وقد قيل: اسم أبى كثير الأنصارى عن على، رفيع."],[11070,"= قلت: وانظر الثقات (٣/ ١١٣) في ترجمة خرشة بن الحارث و(٤/ ٢١٢) في ترجمة خرشة بن الحر الفزارى. والتاريخ الكبير (٢/ ١/ ٢١٣) الجرح (١/ ٢/ ٣٨٩) والاستيعاب (١/ ٤٣٩ - ٤٤١)."],[11071,"وقال ابن حجر أيضا في الإصابة (١/ ٤/ ٤٧١) خرشة شامى، له صحبة ذكره ابن عبد البر وعزاه لأبى حاتم وفرق بينه وبين خرشة بن الحارث المحاربى وخرشة بن الحر الفزارى ثم زعم ابن عبد البر أن الشامى هو الفزارى، فوهم وإنما هو المحاربى. واللَّه أعلم. اهـ"],[11072,"(١) ثابت بن عجلان الأنصارى، حمصى، نزل ارمينية، صدوق، من الخامسة التقريب (١/ ١١٦)."],[11073,"١٧٠٨ - كنى البخارى (ص ٦٤) و(ص ٨٩)، تعجيل المنفعة (ص ٣٣٨)."],[11074,"وقال: ذكره البخارى ولم يذكر فيه جرحا، وتبعه أبو أحمد الحاكم وجوز في موضع آخر أنه أبو كثير الراوى عن الحسن بن على رضي الله عنهما، وعنه بدر بن الخليل، وهو محتمل، وجوز أيضا أنه أبو كثير رفيع، روى عن على، روى عنه عمران بن حدير وغيره، وليس بجيد لأن شيخ عمران يقال له: أبو كثيرة، بزيادة هاء في آخره. . ."],[11075,"قلت: وانظر ترجمة أبى كثير رفيع في (٧٥٣) وانظر أيضا الترجمة (١٧٠٥) في أبى كثير روى عنه بدر بن الخليل."],[11076,"باب أبى كبشة"],[11077,"١٧٠٩ - أبو كبشة (١) السكسكى، كان عريف السكاسك، روى عن أبى الدرداء، روى عنه ابنه يزيد (٢)."],[11078,"١٧١٠ - أبو كبشة السدوى (٣) بصرى، سمع أبا موسى الاشعرى. روى عنه عاصم الاحول."],[11079,"١٧١١ - أبو كبشة السلولى، روى عن عبد اللَّه بن عمرو بن العاص، وثوبان، وسهل بن الحنظلية (٤)، روى عنه أبو سلام الحبشى، وحسان بن عطية. قال أبو حاتم: لا أعلمه يسمى (٥)."],[11080,"١٧٠٩ - كنى البخارى (ص ٦٥)، الجرح (٤/ ٢/ ٤٣٠)."],[11081,"(١) كبشة: بفتح الكاف وسكون الباء المعجمة بواحدة وفتح الشين المعجمة الاكمال (٧/ ١٥٥)."],[11082,"(٢) يزيد بن أبى كبشه السكسكى، الدمشقى، مقبول، من الثالثة. التقريب (٢/ ٣٦٩)."],[11083,"١٧١٠ - كنى البخارى (ص ٦٥) الاكمال (٧/ ١٥٧)، الجرح (٤/ ٢/ ٦٣٠)، الميزان (٤/ ٥٦٤)، تهذيب الكمال (٣/ ١٦٤٠)، التهذيب (١٢/ ٢١٠) التقريب (٢/ ٤٦٥) وقال: مقبول، من الثالثة./ د."],[11084,"(٣) هكذا في الأصل وفى مصادر الترجمة \"السدوسى\" إلا أن المزى قال \"الدوسى\"."],[11085,"١٧١١ - كنى البخارى (ص ٦٥)، كنى مسلم (ص ٨٣٨)، الاكمال (٧/ ١٥٧)، الثقات (٥/ ٥٦٣)، الجرح (٤/ ٢/ ٤٣٠)، الميزان (٤/ ٥٦٤)، كنى ابن منده (٢٠٣/ أ)، تهذيب الكمال (٣/ ١٦٤٠) وقال: ذكره أبو زرعة الدمشقى في الطبقة الثانية من تابعى أهل الشام. التهذيب (١٢/ ٢١٠)، التقريب (٢/ ٤٦٥) وقال: ثقة، من الثانية./ تمييز."],[11086,"(٤) سهل بن الحنظلية، صحابى انصارى أوسى، والحنظلية: أمه أو من أمهاته، واختلف في اسم أبيه. انظر التقريب (١/ ٣٣٦)."],[11087,"(٥) الجرح (٤/ ٢/ ٤٣٠)."],[11088,"باب أبى كنانة"],[11089,"١٧١٢ - أبو كنانة، مولى ربيعة، بصرى، روى عن على، والزبير، روى عنه حبيب أبو محمد."],[11090,"١٧١٣ - أبو كنانة القرشى، سمع أبا موسى الاشعرى، روى عنه معاوية بن قرة، أبو اياس وزياد الجصاص (١)."],[11091,"١٧١٢ - كنى البخارى (ص ٦٥)، الجرح (٤/ ٢/ ٤٣٠)."],[11092,"١٧١٣ - كنى البخارى (ص ٦٥)، الجرح (٤/ ٢/ ٤٣٠)، الميزان (٤/ ٥٦٥)، تهذيب الكمال (٣/ ١٦٤١)، التهذيب (١٢/ ٢١٣)، التقريب (٢/ ٤٦٦) وقال: مجهول، من الثالثة، ويقال: هو معاوية بن قرة ولم يثبت./ بخ. د."],[11093,"(١) زياد الجصاص، هو زياد بن أبى زياد، أبو محمد الواسطى، بصرى الأصل، ضعيف من الخامسة./ ت. التقريب (١/ ٢٦٧)."],[11094,"باب أبى كعب"],[11095,"١٧١٤ - أبو كعب الحارثى. صاحب الإِداوة (١). رأى عثمان بن عفان وسأله عن أمر دينه. روى عنه زياد بن جِيْل (٢)."],[11096,"١٧١٥ - أبو كعب البصرى، روى عن عبد اللَّه بن عمرو. قال: \"يتبع الدجال أربعون الفا من صلب العرب\" (٣) روى عنه أبو التياح."],[11097,"١٧٤ - كنى البخارى (ص ٦٥)، كنى مسلم (ص ٨٣٩)، كنى ابن منده (٢٠٣/ أ) الثقات (٥/ ٥٨٧)، الميزان (٤/ ٥٦٥) وقال: مجهول، المقتنى في سرد الكنى (١١٦/ أ)، الجرح (٤/ ٢/ ٤٣٠) وقال: أبو كعب الحارثى، رأى عثمان بن عفان وسأله عن أمر دينه. . سمعت أبى يقول بعض ذلك وبعضه من قبلى. . سألت أبى عنه فقال: مجهول."],[11098,"(١) الاداوة: بالكسر، اناء صغير من جلد يتخذ للماء كالسطيحة ونحوها، وجمعها أداوى. النهاية (١/ ٣٣)."],[11099,"(٢) زياد بن جيل، بكسر الجيم وبالياء المعجمة باثنتين من تحتها هكذا ذكره ابن ماكولا في الاكمال (٢/ ٤٨). وقال: زياد بن جيل الصنعانى الابناوى، روى عنه هشام بن يوسف وعبد العزيز بن خالد بن رستم وأمية بن شبل."],[11100,"وقال البخارى في التاريخ الكبير (٢/ ١/ ٣٤٧) زياد بن جيل عن مشكان وأبى كعب روى عنه معمر وأمية بن شبل. اهـ."],[11101,"١٧١٥ - كنى البخارى (ص ٦٥)، الجرح (٤/ ٢/ ٤٣٠)، المقتنى في سرد الكنى (١١٦/ أ)."],[11102,"(٣) الحديث أخرجه البخارى في الكنى وابن أبى حاتم في الجرح. انظر مصادر الترجمة."],[11103,"١٧١٦ - أبو كعب، مدنى، مولى على بن عبد اللَّه بن عباس، روى عن على بن عبد اللَّه بن عباس، روى عنه إسماعيل بن قيس بن سعد بن زيد بن ثابت (١)."],[11104,"١٧١٧ - أبو كعب الجرموزى، بصرى. قال: رأيت على أنس بن مالك مطرف خزّ، فيه اعلام. روى عنه بسطام (٢) بن جندب الازدى."],[11105,"١٧١٦ - الجرح (٤/ ٢/ ٤٣٠). المقتنى في سرد الكنى (١١٦/ أ)."],[11106,"(١) هو أبو مصعب الأنصارى."],[11107,"قال البخارى والدارقطنى: منكر الحديث. انظر الميزان (١/ ٢٤٥)."],[11108,"١٧١٧ - المقتنى في سرد الكنى (١١٦/ أ)."],[11109,"(٢) لم أقف له على ترجمة."],[11110,"باب أبى كلثوم"],[11111,"١٧١٨ - أبو كلثوم، كوفى سمع حسين بن على بن أبى طالب. روى عنه عمران بن سليمان."],[11112,"١٧١٩ - أبو كلثوم، روى عن ربعى بن حراش كوفى أيضا، روى عنه الاجلح الكندى."],[11113,"١٧٢٠ - أبو كلثوم الدوسى، سمع أبا هريرة (ذكره كهيل بن حرملة النميرى) (١) (٢)."],[11114,"١٧١٨ - كنى البخارى (ص ٦٥)، الجرح (٤/ ٢/ ٤٣١)، المقتنى في سرد الكنى (١١٦/ ب)."],[11115,"١٧١٩ - كنى البخارى (ص ٦٥)، المقتنى في سرد الكنى (١١٦/ ب)."],[11116,"١٧٢٠ - المقتنى في سرد الكنى (٦٥/ أ)."],[11117,"(١) كهيل بن حرملة. ذكره ابن أبى حاتم في الجرح (٣/ ٢/ ١٧٣) ولم يذكر فيه جرحا ولا تعديلا."],[11118,"(٢) الحق في هامش الأصل كتب عنده كلمة \"صح\"."],[11119,"باب أبى كباش"],[11120,"١٧٢١ - أبو كِبَاش (١) العيشى (٢). روى عن أبى هريرة. روى عنه كدام بن عبد الرحمن السلمى (٣)."],[11121,"١٧٢٢ - أبو كِبَاش الكندى. سمع محمد بن الأشعث (٤). روى عنه القاسم بن الفضل (٥)."],[11122,"١٧٢١ - كنى البخارى (ص ٥٦)، الجرح (٤/ ٢/ ٤٣١) وقال: سمعت أبى يقول: هو مجهول، الاكمال (٧/ ١٥٩)، كنى ابن منده (١١٥/ أ)، الميزان (٤/ ٥٦٤) وقال: لا يعرف. اللسان (٧/ ٤٧٩)، التهذيب (١٢/ ٢٠٩)، التقريب (٢/ ٤٦٥) وقال: مجهول. من الثالثة./ ت."],[11123,"(١) كِبَاش: بكسر الكاف وتخفيف الباء المعجمة بواحدة وآخره شين معجمة كما في الاكمال (٧/ ١٥٩)."],[11124,"(٢) في الاكمال \"التاجر\" وفى تهذيب الكمال، والتهذيب واللسان \"العيشى\". وقيل \"السلمى\" وقيل \"أبو عياش\"."],[11125,"(٣) كِدَام، بالكسر والتخفيف، ابن عبد الرحمن السلمى، مجهول، من السادسة انظر التقريب (٢/ ١٣٤)."],[11126,"١٧٢٢ - المقتنى في سرد الكنى (١١٥/ أ)."],[11127,"(٤) محمد بن الاشعت بن قيس الكندى، أبو القاسم، الكوفى، مقبول، من الثانية ووهم من ذكره في الصحابة (ت: ٦٧). انظر التقريب (٢/ ١٤٦)."],[11128,"(٥) القاسم بن فضل، ثقة، من السابعة، رمى بالارجاء (ت: ١٦٧). انظر التقريب (٢/ ١١٩)."],[11129,"أفراد"],[11130,"١٧٢٣ - أبو كَنِف (١). سمع سعد بن مالك (٢)، وعبد اللَّه بن مسعود، وأبا هريرة، روى عنه الشعبى، وعبد اللَّه بن مرة."],[11131,"١٧٢٤ - أبو كرمة الكندى، روى عن زاذان. روى عنه العلاء بن عبد الكريم (٣)."],[11132,"١٧٢٥ - أبو كرز. عن الزهرى عن سعيد بن المسيب. روى عنه المعافى ابن سليمان الجزرى (٤)."],[11133,"١٧٢٣ - كنى البخارى (ص ٦٥)، الجرح (٤/ ٢/ ٤٣١)، المقتنى في سرد الكنى (١١٦/ ب) وقال: أبو كنف العبدى، سمع ابن مسعود، وعنه الشعبى وعبد اللَّه بن مرة."],[11134,"(١) ضبط في الأصل: بفتح الكاف كسر النون."],[11135,"(٢) سعد بن مالك، هو أحد العشرة المبشرين بالجنة. وآخرهم موتا وأمه حمزة بنت سفيان بن أمية بنت عم أبى سفيان بن حرب، وكان أحد الفرسان، وهو أول من رمى بسهم في سبيل اللَّه، وهو أحد الستة أهل الشورى، وكان رأس من فتح العراق، وولى الكوفة لعمر، مات بعد الخمسين. انظر الإصابة (٢/ ٣٣)"],[11136,"١٧٢٤ - كنى البخارى (ص ٦٥)، الجرح (٤/ ٢/ ٤٣١) وقال: سمعت أبا زرعة يقول: لا أعلم أحدا سماه، المقتنى في سرد الكنى (١١٦/ أ)."],[11137,"(٣) العلاء بن عبد الكريم، أبو عون الكوفى، ثقة، عابد، من السادسة، انظر التقريب (٢/ ٩٣)."],[11138,"١٧٢٥ - كنى مسلم (ص ٨٤٠)، كنى ابن منده (٢٠٣/ أ)، الميزان (٤/ ٥٦٥)، المقتنى في سرد الكنى (١١٦/ أ) وقال أبو كرز."],[11139,"(٤) المعافى بن سليمان الجزرى، صدوق، من العاشرة (ت: ٢٣٤)، التقريب (٢/ ٢٥٨)."],[11140,"١٧٢٦ - أبو كَرِب (١)، روى عن عثمان."],[11141,"١٧٢٧ - أبو كَيْسَبة (٢) عن عمر بن الخطاب، روى عنه قيس بن أبى حازم، روى عن على بن عاصم، عن بيان بن بشر (٣) عن قيس بن أبى حازم، قال: نا أبو كيسبة فذكر الأبيات \"أقسم باللَّه أبو حفص عمر\" (٤)."],[11142,"١٧٢٦ - المقتنى في سرد الكنى (١١٦/ أ)."],[11143,"(١) كرب: بفتح الكاف كسر الراء. الاكمال (٧/ ١٧٠)."],[11144,"١٧٢٧ - الاكمال (٧/ ١٥٨)، المقنى في سرد الكنى (١١٦/ ب) وقال: أبو كيسبة راجز عن عمر، وعنه قيس بن أبى حازم، الإصابة (٣/ ٣/ ٩٣) و(٤/ ٣/ ١٦٧)."],[11145,"(٢) كيسبة: بفتح الكاف وقبل آخره باء معجمة بواحدة. الاكمال (٧/ ١٥٨)."],[11146,"(٣) بيان بن بشر الاحمسى، بمهملتين، أبو بشر الكوفى، ثقة ثبت، من الخامسة. التقريب (١/ ١١١)، التهذيب (١/ ٥٠٦)."],[11147,"(٤) هذا البيت من الرجز ذكره ابن حجر في الإصابة (٣/ ٣/ ٩٣ - ٩٤) في ترجمة عبد اللَّه بن كيسبة النهدى وقال: ذكره المرزبانى في معجم الشعراء وقال: كيسبة أمه ويقال: اسمه عمرو. وهو القائل لعمر بن الخطاب واستحمله فلم يحمله:"],[11148,"أقسم باللَّه أبو حفص عمر ... ما مسها من نقب ولا دبر"],[11149,"فاغفر له اللهم إن كان فجز"],[11150,"وقال ابن حجر في الكنى من الاستيعاب (٤/ ٣/ ١٦٧) في \"أبو كيسبة\" روى قصته مع عمر بيان بن بشر عن قيس بن أبى حازم عن أبى كيسبة."],[11151,"قلت: ولم أقف على هذا الرجز لأبى كيسبة في معجم الشعراء للمرزبانى وذلك لأن المطبوع هو جزء من المخطوط والجزء الباقى مفقود. وذكر هذا البيت أيضا ابن هشام الأنصارى في شذور الذهب (ص ٤٣٥) من شعر عبد اللَّه بن كيسبة، وعبد القادر البغدادى في خزانة الأدب (٢/ ٣٥١) وقال: هو أول رجز قاله أعرابى لعمر بن الخطاب. وابن عقيل في شرحه على الفية ابن مالك (٢/ ٢١٩) باب عطف البيان، شاهد رقم (٢٩٢) وابن منظور في لسان العرب (١/ ٧٦٦). = . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . ."],[11152,"= وذكر ابن حجر: وابن هشام الأنصارى وعبد القادر البغدادى سبب هذا البيت فقالوا أتى عبد اللَّه بن كيسبة عمر بن الخطاب فقال: يا أمير المؤمنين ان أهلى بعيد، وأن ناقتى دبراء نقباء فاحملنى فقال عمر: كذبت واللَّه ما بها من نقب ولا دبر. فقال هذا الرجز فسمعه أمير المؤمنين فحمله وأعطاه."],[11153,"وقوله دبراء نقباء: الدَّبرة بالتحريك قرحة الدابة والبعير والجمع دبر وأدبار والدَّبَر: بالتحريك، الجرح الذى يكون في ظهر الدابة. انظر لسان العرب مادة \"دبر\" (٤/ ٢٧٣ - ٢٧٤)."],[11154,"وقوله نقباء: جاء في لسان العرب مادة \"نقب\" (١/ ٧٦٦) نَقِبَ البعير بالكسر، إذا رقت أخفافه، يقال: نقب خف البعير نقبا إذا حفى حتى يتخرق فرسنه. اهـ."],[11155,"اللام"],[11156,"باب أبى ليلى"],[11157,"١٧٢٨ - أبو ليلى بن عبد اللَّه بن عبد الرحمن بن سهل الأنصارى الحارثى. روى عن سهل بن أبى حثمة. روى عنه مالك (بن) (١) أنس. قال أبو زرعة: هو مدنى أنصارى ثقة."],[11158,"١٧٢٩ - أبو ليلى الكندى كوفى. روى عن سويد بن غفلة الجعفى. روى عنه عثمان بن أبى زرعة الثقفى. قال محمد بن عثمان بن أبى شيبة (٢): سمعت يحيى بن معين وسئل عن أبى ليلى الكندى فقال: كان ضعيفا (٣)."],[11159,"١٧٣٠ - أبو ليلى مولى أبى سعيد. وربما قيل: أبو ليلى بن"],[11160,"١٧٢٨ - الجرح (٤/ ٢/ ٤٣١)، التهذيب (١٢/ ٢١٥)، التقريب (٢/ ٤٦٧) وقال: يقال: اسمه عبد اللَّه، ثقة، من الرابعة/ خ. م. د. س. ق."],[11161,"قلت: وقد تقدم أبو ليلى هذا في الكتاب الثانى فيمن يعرف لهم أسماء انظر الترجمة (٧٦٥)."],[11162,"(١) لم يكن في الأصل والسياق يقتضى إثباته فاثبت."],[11163,"١٧٢٩ - المقنى في سرد الكنى (١١٧/ ب) وقال: أبو ليلى الكندى عن سويد بن غفلة وعنه عثمان بن أبى زرعة واه."],[11164,"قلت: وقد تقدم في الكتاب الثانى، أبو ليلى الكندى سلمة بن معاوية الكوفى. . الخ. انظر الترجمة (٧٦٤)."],[11165,"(٢) محمد بن عثمان بن أبى شيبة: هو المحدث البارع محدث الكوفة أبو جعفر العبسى، انظر اللسان (٥/ ٢٨٠)، تذكرة الحفاظ (٢/ ٦٦١)."],[11166,"(٣) التهذيب (١٢/ ٢١٦)."],[11167,"١٧٣٠ - كنى البخارى (ص ٦٦)، الجرح (٤/ ٢/ ٤٣١). المقتنى في سرد الكنى (١١٧/ ب) وقال: أبو ليلى مولى بن سعيد سمع ابن أبى اوفى."],[11168,"سعيد (١)، كوفى، سمع عبد اللَّه بن أبى اوفى، عن النبى عليه السلام. حديثه عند أبى عاصم النبيل عن عمارة الاحمر (٢) عنه (٣)."],[11169,"١٧٣١ - أبو ليلى الخراسانى. عن أبى عكاشة (٤). روى عنه وكيع. قال أبو أحمد الحاكم (٥): \"وخليقا أن يكون أبو ليلى هذا هو أبو ليلى الذى بينا ضعفه في الباب قبل هذا عبد اللَّه بن ميسرة\" (٦)."],[11170,"١٧٣٢ - أبو ليلى، روى عن بريدة الاسلمى، قال عباس عن يحيى بن معين: أبو ليلى الذى يروى عن بريدة ضعيف (٧)."],[11171,"(١) في كنى البخارى والجرح \"أبو ليلى بن سعيد\" انظر مصادر الترجمة."],[11172,"(٢) عمارة الاحمر: قال الذهبى في الميزان (٣/ ١٧٨): عمارة الاحمر: شيخ لأبى عاصم النبيل مجهول."],[11173,"(٣) الحديث: ذكره البخارى في الكنى وابن أبى حاتم في الجرح من هذا الطريق وفيه قال ابن أبى أوفى: رأيت النبى -صلى الله عليه وآله وسلم- أخذ بعضده حتى رأيت بياض ابطيه. اهـ"],[11174,"١٧٣١ - كنى البخارى (ص ٦٦) المقتنى في سرد الكنى (١١٧/ ب)، الجرح (٤/ ٢/ ٤٣٢)، تهذيب الكمال (٣/ ١٦٤٢) التهذيب (١٢/ ٢١٦) التقريب (٢/ ٤٦٧) وقال: مجهول: من السادسة، ويقال: هو عبد اللَّه بن ميسرة الحارثى./ ق."],[11175,"(٤) أبو عكاشة الهمدانى، الكوفى، مجهول، من السادسة./ ق. التقريب (٢/ ٤٥٢)."],[11176,"(٥) لم أقف على كلام الحاكم عند غير ابن عبد البر هنا."],[11177,"(٦) أبو ليلى عبد اللَّه بن ميسرة هو أبو ليلى الكندى المتقدم في (٧٦٩) وذكر ابن عبد البر في ترجمته هناك بأنه ضعيف الحديث. اهـ."],[11178,"١٧٣٢ - الجرح (٤/ ٢/ ٤٣١)، اللسان (٧/ ٩٩)."],[11179,"(٧) انظر الجرح (٤/ ٢/ ٤٣١)، ولم أقف على هذا النص في التاريخ لابن معين رواية الدورى."],[11180,"١٧٣٣ - أبو ليلى، سمع عبد اللَّه (١) بن أبى بكر، روى عنه أحمد بن عبد اللَّه بن يونس، وسعيد بن سليمان سعدوية (٢). قال ابن معين: ليس بشئ (٣)."],[11181,"١٧٣٤ - أبو ليلى، مولى الأنصار، كوفى، عن أبى هريرة. روى عنه سعيد ابن عمرو بن أشوع (٤)."],[11182,"١٧٣٥ - أبو ليلى، عن نافع مولى ابن عمر، حدث عنه اسرائيل بن يونس ابن (أبى) (٥) اسحاق."],[11183,"١٧٣٣ - كنى البخارى (ص ٦٦)، الجرح (٤/ ٢/ ٤٣٢)، المقتنى في سرد الكنى (١١٧/ ب)."],[11184,"(١) في الجرح \"عبيد اللَّه بن أبى بكر\"."],[11185,"(٢) سعدوية: لقب له."],[11186,"(٣) تاريخ ابن معين رواية الدارمى (ص ٢٤٩)."],[11187,"١٧٣٤ - المقتنى في سرد الكنى (١١٧/ ب)."],[11188,"(٤) أشوع: ذكره في المغنى (ص ٥) في أُشكاب، بضم أوله وبشين معجمة، فقال: سعيد بن عمرو بن أشوع بمفتوحة، فساكنة معجمة فواو مفتوحة فمهملة، ممنوع من الصرف. اهـ. وسعيد هذا همدانى كوفى، قاض، ثقة، رمى بالتشيع، من السادسة، مات في حدود العشرين ومائة. كما في التقريب (١/ ٣٠٢)."],[11189,"١٧٣٥ - المقتنى في سرد الكنى (١١٧/ ب)، اللسان (٧/ ٩٩) وقال: لا يدرى من هو والخبر الذى أتى به موضوع."],[11190,"(٥) لم تكن في الأصل، وهو اسرائيل بن يونس بن أبى اسحاق السبيعى."],[11191,"افراد"],[11192,"١٧٣٦ - أبو لقمان الحضرمى، سمع أبا هريرة فيما رواه معن بن عيسى، عن معاوية بن صالح، عن أبى لقمان، عن أبى هريرة ورواه عبد الرحمن بن مهدى وأبو صالح كاتب الليث، عن معاوية بن صالح عن أبى لقمان عبد اللَّه عن أبى هريرة عن النبى -صلى الله عليه وآله وسلم-: \"انه نهى أن يياع سهم حتى يعلم ما هو\" (١)."],[11193,"١٧٣٧ - أبو لؤلؤ الضبى، روى عن أبى صالح، روى عنه الوليد بن أبى زينب (٢)."],[11194,"١٧٣٦ - كنى البخارى (ص ٦٦)، الجرح (٤/ ٢/ ٤٣٢)، الثقات (٥/ ٥٧٢)، اللسان (٧/ ٩٩)، المقتنى في سرد الكنى (١١٧/ أ)."],[11195,"(١) الحديث أخرجه البخارى في الكنى، وابن أبى حاتم في الجرح وذكرا أن رواية ابن مهدى وأبى صالح أصح من رواية معن بن عيسى."],[11196,"وأخرجه الدارمى (٢/ ٢٢٦) من حديث أبى أمامة يرفعه \"أنه نهى أن تباع السهام حتى تقسم."],[11197,"١٧٣٧ - كنى البخارى (ص ٦٦)، الجرح (٤/ ٢/ ٤٣٢)."],[11198,"(٢) الوليد بن أبى زينب. ذكره أبن أبى حاتم عن أبيه فقال: \"روى عن أبى لؤلؤة روى عنه يزيد بن هارون. هو مجهول\". الجرح (٤/ ٢/ ٥)."],[11199,"باب أبى محمد"],[11200,"١٧٣٨ - أبو محمد، كوفى من أصحاب ابن مسعود، روى عنه إبراهيم بن عبيد بن رفاعة (١)."],[11201,"١٧٣٩ - أبو محمد المهدى. عن ابن مسعود. روى عنه حصين بن منيع السدوسى (٢). جعلهما الحاكم أبو أحمد اثنين. واتفق هو وأبو حاتم الرازى على الأول."],[11202,"١٧٤٠ - أبو محمد الحضرمى. روى عن أبى أيوب الأنصارى حديثين أحدهما في أعلام النبوة (٣) والآخر أن رجلا قال خلف النبى عليه السلام:"],[11203,"١٧٣٨ - كنى البخارى (ص ٦٦)، الثقات (٥/ ٥٨٦)، الجرح (٤/ ٢/ ٤٣٢) تعجيل المنفعة (ص ٣٣٩)."],[11204,"(١) صدوق، من الرابعة. التقريب (١/ ٣٩)."],[11205,"١٧٣٩ - لم أقف عليه عند غير المؤلف."],[11206,"(٢) ذكره ابن أبى حاتم في الجرح (١/ ٢/ ١٩٦) وقال: ذكره أبى عن اسحاق ابن منصور عن يحيى بن معين أنه قال: حصين بن منيع السدوسى صالح. أهـ."],[11207,"١٧٤٠ - كنى البخارى (ص ٦٦)، الجرح (٤/ ٢/ ٤٣٢)، وقال: سمعت أبا زرعة يقول: لا أعلم أحدا سماه. الميزان (٤/ ٥٧٠)، تهذيب الكمال (٣/ ١٦٤٤)، التهذيب (١٢/ ٢٢٤)، التقريب (٢/ ٤٦٩) وقال: أبو محمد الحضرمى، غلام أبى أيوب، قيل: هو أفلح والا فمجهول من الثالثة./ بخ خت."],[11208,"(٣) حديث في أعلام النبوة أخرجه الحافظ أبو نعيم في دلائل النبوة (ص ٣٦٦ - ٣٦٧) والحافظ ابن كثير في الشمائل (ص ٢٠٩ - ٢١٠) وعزاه الأخير إلى البيهقى وقال: هذا حديث غريب جدا اسنادا ومتنا كلهم أخرجوه من طريق سعيد الجريرى عن أبى الورد عن أبى محمد الحضرمى عن أبى أيوب ="],[11209,"\"الحمد للَّه حمدا كثيرا طيبا مباركًا\" (١) روى عنه أبو الورد بن ثمامة (٢)."],[11210,"١٧٤١ - أبو محمد الأنصارى، سمع عثمان بن عفان، وأبا هريرة، والحسن بن على، روى عنه، سعدان الجهنى."],[11211,"= الأنصارى رضي الله عنه قال: صنعت لرسول اللَّه -صلى الله عليه وآله وسلم- ولأبى بكر طعاما قدر ما يكفيهما فأتيتهما به فقال رسول اللَّه -صلى الله عليه وآله وسلم-: اذهب فادع لى ثلاثين من أشراف الأنصار قال: فشق ذلك على وما عندى ما أزيده قال: وكأنى تثاقلت فقال: اذهب فادع لى ثلاثين من أشراف الأنصار! فدعوتهم فجاؤا فقال: اطعموا فأكلوا حتى صدروا ثم شهدوا أنه رسول اللَّه -صلى الله عليه وآله وسلم- ثم بايعوا قبل أن يخرجوا ثم قال: اذهب فادع لى ستين من اشراف الأنصار. . الحديث وفيه انه دعى تسعين حتى أنه أكل من طعامه ذاك مائة وثمانون رجلا والحديث أخرجه أيضا الطبرانى كما في مجمع الزوائد (٨/ ٣٠٣) وقال الهيثمى: في اسناده من لم أعرفه."],[11212,"(١) وأما حديث الذكر فقد أخرجه ابن أبى حاتم في الجرح (٤/ ٢/ ٤٣٢) وأخرجه البخارى \"الدعوات\" باب فضل التهليل (١١/ ٢٠١) بعد أن ذكر حديث أبى أيوب الأنصارى برواية عبد الرحمن بن أبى ليلى عنه فقال: ورواه أبو محمد الخضرمى، عن أبى أيوب عن النبى -صلى الله عليه وآله وسلم- فذكره بنحوه وأخرجه المزى في تهذيب الكمال (٣/ ١٦٤٤) فقال وقد وقع لنا حديثه بعلو ثم ذكره بسنده المتصل إلى أبى الورد، عن أبى محمد الحضرمى. عن أبى أيوب فذكره كما هنا وقال: رواه عن مسدد."],[11213,"والحديث ذكره الحافظ ابن حجر في المطالب العالية (٣/ ٢٤٠) وقال: أخرجه مسدد. وقال المحقق في الهامش: قال البوصيرى: رواه مسدد وابن أبى الدنيا والطبرانى، واسناده حسن."],[11214,"وذكره أيضا الحافظ الهيثمى في مجمع الزوائد (١٠/ ٩٦)، وعزاه للطبرانى. وقال: اسناده حسن."],[11215,"(٢) أبو الورد بن ثمامة بن حزن القشيرى، البصرى، مقبول، من السادسة التقريب (٢/ ٤٨٦)."],[11216,"١٧٤١ - كنى البخارى (ص ٦٦)، الثقات (٥/ ٥٨٩)، الجرح (٤/ ٢/ ٤٣٣)."],[11217,"١٧٤٢ - أبو محمد الحمصى. روى عن عمر بن الخطاب. حديثه عند معاوية بن صالح عن أبى بكر عنه."],[11218,"١٧٤٣ - أبو محمد. شيخ قديم، روى عن حذيفة بن اليمان قال: قال رسول اللَّه -صلى الله عليه وآله وسلم-: \"اقرأوا القرآن بلحون العرب وأصواتها وإياكم ولحون أهل الكتابين وأهل الفسق - فانه سيجئ بعدى قوم يرجعون بالقرآن ترجيع الغناء والرهبانية والهرج (١) لا يجاوز حناجرهم مفتونة قلوبهم وقلوب من يعجبهم شأنهم\" (٢)."],[11219,"١٧٤٤ - أبو محمد، عن عبد اللَّه بن عمر، روى عنه سفيان الثورى."],[11220,"١٧٤٥ - أبو محمد، عن أبى هريرة، روى عنه ابنه محمد (٣)."],[11221,"١٧٤٢ - الجرح (٤/ ٢/ ٤٣٣)."],[11222,"١٧٤٣ - المقتنى في سرد الكنى (١٢٢/ أ)."],[11223,"(١) هكذا في الأصل \"والهرج\" والذى في الجامع الصغير (١/ ٥٢) ومجمع الزوائد (٧/ ١٦٩) \"والنوح\"."],[11224,"(٢) الحديث أخرجه الذهبى في المقتنى في سرد الكنى وقال حديث منكر. وأخرجه الطبرانى في الأوسط، والبيهقى في شعب الايمان. كما في الجامع الصغير (١/ ٥٢). وذكره الهيثمى أيضا في مجمع الزوائد (٧/ ١٦٩) وقال: رواه الطبرانى في الأوسط، وفيه راو لم يسم، وبقية أيضا. وذكره الذهبى في الميزان (١/ ٣٥٣) في ترجمة بقيه بن الوليد وذكره مرة ثانية في ترجمة حصين بن مالك الفزارى، عن رجل عن حذيفة به. وقال: تفرد عنه بقية، ليس بمعتمد، والخبر منكر."],[11225,"وأخرجه أيضا ابن الجوزى في العلل المتناهية (١/ ١١١) من طريق بقيه عن الحصين بن مالك الفزارى، عن أبى محمد، عن حذيفة به وقال: هذا حديث لا يصح، وأبو محمد مجهول، وبقية يروى عن الضعفاء ويدلسهم."],[11226,"١٧٤٤ - المقتنى في سرد الكنى (١٢٢/ ب)."],[11227,"١٧٤٥ - كنى البخارى (ص ٦٦)، الجرح (٤/ ٢/ ٤٣٣)، اللسان (٧/ ١٠٢) وقال: شيخ مجهول."],[11228,"(٣) محمد بن أبى محمد المدنى، عن أبيه عن أبى هريرة، شيخ لعبد الرزاق، مجهول من السابعة./ تمييز. التقريب (٢/ ٢٠٥)، التهذيب (٩/ ٤٣٣) ="],[11229,"١٧٤٦ - أبو محمد البصرى، روى عن الحسن بن على، روى عنه منصور ابن المعتمر."],[11230,"١٧٤٧ - أبو محمد الفرغانى (١)، سمع جابر بن عبد اللَّه، روى عنه أبو الحارث. قال أبو حاتم: مجهول (٢)."],[11231,"١٧٤٨ - أبو محمد الهذلى، عن على بن أبى طالب، حديثه عند حمّاد ابن سلمة، عن الحجّاج بن أرطأة، عن الحكم عنه."],[11232,"١٧٤٩ - أبو محمد الجزرى، عن النبى عليه السلام مرسل حديثه عند معاوية بن صالح عن شعيب، عنه."],[11233,"١٧٥٠ - أبو محمد القرشى، عن اسرائيل بن يونس، روى عنه محمد بن"],[11234,"١٧٤٦ - كنى البخارى (ص ٦٦)، الجرح (٤/ ٢/ ٤٣٣)، المقتنى في سرد الكنى (١٢٢/ أ)."],[11235,"١٧٤٧ - كنى البخارى (ص ٦٧)، الجرح (٤/ ٢/ ٤٣٣)، الميزان (٤/ ٥٧٠) اللسان (٧/ ١٠١) وقال: مجهول."],[11236,"(١) الفَرْغَانى: بفتح الفاء وسكون الراء وفتح الغين المعجمة وبعد الالف نون - هذه النسبة إلى موضعين أحدهما إلى فرغانة وهى ولاية وراء الشاش وراء جيحون وسيحون. . والثانى إلى فرغان، قرية من قرى فارس."],[11237,"اللباب (٢/ ٤٢٢)."],[11238,"(٢) الجرح (٤/ ٢/ ٤٣٣)."],[11239,"١٧٤٨ - الميزان (٤/ ٥٧٠)، وقال: مجهول، اللسان (٧/ ١٠٣)، ديوان الضعفاء (ص ٣٦٥)، التهذيب (١٢/ ٢٢٥)، التقريب (٢/ ٤٧٠) وقال: مجهول، من الثالثة./ عس، تعجيل المنفعة (ص ٣٣٩)، وقال: أبو محمد الهذلى، عن على وعنه الحكم بن عتيبة، قال غندر، عن الحكم عن رجل من أهل البصرة يكنونه أبا المورع، وأهل الكوفة يكنونه أبا محمد. اهـ. قلت: وسيأتى أبو المورع، في (١٩٠٧) بنحو ما هنا ويظهر من الترجمتين انهما لرجل واحد. واللَّه أعلم."],[11240,"١٧٤٩ - كنى البخارى (ص ٦٧)، الجرح (٤/ ٢/ ٤٣٣)."],[11241,"١٧٥٠ - الميزان (٤/ ٥٦١)، اللسان (٧/ ١٠١). ="],[11242,"جهم (١) حديثا منكرا."],[11243,"١٧٥١ - أبو محمد الحضرمى (٢)، عن أبى على الهمدانى، روى عنه يحيى ابن حماد (٣) في الكوفيين."],[11244,"١٧٥٢ - أبو محمد عن زرارة بن أوفى. روى عنه حماد بن سلمة. لم يعرفه يحيى بن معين (٤)."],[11245,"١٧٥٣ - أبو محمد مولى عمر بن الخطاب عن أبى عبيدة بن عبد اللَّه بن مسعود (٥). روى عنه العوّام بن حوشب."],[11246,"١٧٥٤ - أبو محمد السّاعدى، عن يزيد بن زيد (٦)، عن أبى حميد (٧) روى"],[11247,"= قال الذهبى وتبعه ابن حجر: \"لا يدرى من هو\" انظر مصادر الترجمة."],[11248,"(١) محمد بن جهم. انظر ترجمته في الجرح (٣/ ٢/ ٢٢٤)."],[11249,"١٧٥١ - المقتنى في سرد الكنى (١٢٢/ أ)."],[11250,"(٢) الحضرمى: نسبة إلى حضرموت: بالفتح ثم السكون، وفتح الراء والميم اسمان مركبان، وهى ناحية واسعة في شرقى عدن، بقرب البحر، وحولها رمال كثيرة تعرف بالاحقاف. انظر مراصد الاطلاع (١/ ٤٠٩)"],[11251,"(٣) في المقتنى \"يحيى بن حماد القطان\"."],[11252,"١٧٥٢ - المقتنى في سرد الكنى (١٢٢/ أ)، الجرح (٤/ ٢/ ٤٣٤)."],[11253,"(٤) يذكر ابن أبى حاتم: الجرح (٤/ ٢/ ٤٣٤) قال: \"قرئ على العباس بن محمد الدورى عن يحيى بن معين أنه سئل عن أبى محمد الذى روى عن زرارة بن أوفى الذى روى عنه حماد بن سلمة فقيل له: من أبو محمد هذا؟ فقال: لا أعرفه. اهـ."],[11254,"قلت: ولم أقف على هذا النص في تاريخ ابن معين رواية الدورى."],[11255,"١٧٥٣ - كنى البخارى (ص ٦٧)، الجرح (٤/ ٢/ ٤٣٣)، الميزان (٤/ ٥٧٠) التهذيب (١٢/ ٢٢٥)، المقتنى في سرد الكنى (١٢٢/ ب)."],[11256,"(٥) هو عامر بن عبد اللَّه بن مسعود تقدم في (٩٤٥)."],[11257,"١٧٥٤ - المقتنى في سرد الكنى (١٢٢/ أ)."],[11258,"(٦) يزيد بن زيد المدينى. ذكره ابن أى حاتم في الجرح (٤/ ٢/ ٣٦١)، وذكر روايته عن أبى حميد الساعدى. ولم يذكر فيه شيئا."],[11259,"(٧) أبو حميد: هو الساعدى المتقدم في (٧٥)."],[11260,"عنه، عمر بن حفص بن ثابت الأنصارى (١)."],[11261,"١٧٥٥ - أبو محمد العبدى، عن عبد اللَّه بن لهيعة، روى عنه خليفة بن خياط."],[11262,"١٧٥٦ - أبو محمد القرشى، عن النبى -صلى الله عليه وآله وسلم- مرسل. حدث عنه معاوية بن صالح."],[11263,"١٧٥٧ - أبو محمد الكوفى، عن محمد بن المنكدر، روى عنه زيد بن الحباب، وهو رجل مجهول عندهم، وحديثه منكر."],[11264,"١٧٥٨ - أبو محمد بن الاعيس (٢)، وقيل: ابن أبى الاعيس الخولانى الدمشقى، روى عنه معاوية بن صالح."],[11265,"١٧٥٩ - أبو محمد عن أبى كنانة (٣)، روى عنه مالك بن دينار."],[11266,"١٧٦٠ - أبو محمد بن كعب بن مالك (وقيل: أبو محمد بن"],[11267,"(١) عمر بن حفص بن ثابت الأنصارى. انظر ترجمته في الجرح (٣/ ١/ ١٠٢)."],[11268,"١٧٥٥ - المقتنى في سرد الكنى (١٢٢/ أ)."],[11269,"١٧٥٦ - كنى البخارى (ص ٦٧)."],[11270,"١٧٥٧ - الميزان (٤/ ٥٧٠)، اللسان (٧/ ١٠١)، المقتنى في سرد الكنى (١٢٢/ ب) وقال الذهبى وتبعه ابن حجر: خبره باطل."],[11271,"١٧٥٨ - كنى البخارى (ص ٦٧)، الجرح (٤/ ٢/ ٤٣٣)، المقتنى في سرد الكنى (١٢٢/ ب) وقال: أبو محمد بن أبى الاعيس عنه معاوية بن صالح."],[11272,"(٢) الاعيس: في الاكمال (١/ ١٠٠): الأعيس بعين مهملة بعدها ياء معجمة باثنتين من تحتها مفتوحة. اهـ."],[11273,"١٧٥٩ - كنى البخارى (ص ٦٧)، الجرح (٤/ ٢/ ٤٣٤)، الميزان (٤/ ٥٧٠)."],[11274,"(٣) قد تقدم في ترجمة أبى كنانة مولى ربيعة، بصرى رقم (١٧١٢) روى عنه حبيب أبو محمد. فاللَّه أعلم."],[11275,"١٧٦٠ - كنى البخارى (ص ٦٧) وقال: أبو محمد بن كعب بن مالك، روى عنه حماد بن سلمة. وقال ابن أبى حاتم في كتاب بيان خطأ محمد بن إسماعيل البخارى في تاريخه (ص ١٦٤) إنما هو أبو محمد بن معبد بن ="],[11276,"معبد بن كعب بن مالك) (١)، والحديث واحد، روى عنه حماد بن سلمة، واختلف عليه، فروى عفان عن حماد بن سلمة، عن أبى محمد بن معبد بن أبى قتادة (عن ابن كعب بن مالك (٢)، عن أبى قتادة، وروى موسى بن إسماعيل عن حماد بن سلمة، عن أبى محمد بن معبد بن أبى قتادة، عن معبد بن كعب بن مالك، عن أبى قتادة) (٣). وقال أبو حاتم: هذا هو الصحيح."],[11277,"= كعب اهـ. الجرح (٤/ ٢/ ٤٣٣ - ٤٣٤) وذكره كما هنا تقريبا وقال: سمعت أبى يقول: الصحيح عن معبد بن كعب بن مالك، وروى عنه حماد ابن سلمة."],[11278,"(١) الحق في هامش الأصل. كتب عنده \"صح أصل\"."],[11279,"(٢) هو معبد بن كعب بن مالك. كما صرح بذلك الدارقطنى في العلل (٥/ ٦٢/ ب) وهو مقبول، روى له البخارى ومسلم، وأبو داود، والنسائى وابن ماجه. انظر التهذيب (١٠/ ٢٢٤)، التقريب (٢/ ٢٦٢)."],[11280,"(٣) حديث أبى قتادة هذا أخرجه أحمد في المسند (٥/ ٢٩٧) من طريق محمد ابن اسحاق، حدثنى ابن لكعب بن مالك عن أبى قتادة يرفعه وفيه لفظ \"من قال على ما أأقل ليتبوّأ مقعده من النار\". وهو في المسند أيضا (٥/ ٣١٠) من طريق عفان، ثنا حماد بن سلمة، انا أبو محمد بن معبد بن أبى قتادة، عن ابن كعب بن مالك. . الخ وفى المسند (٥/ ٣٠٠) من طريق حسن، ثنا حماد بن سلمة، عن أبى محمد بن معبد بن معبد بن أبى قتادة قال: سمعت عبد اللَّه بن كعب بن مالك يحدث أن أبا قتادة\" فذكره."],[11281,"والحديث أخرجه أيضا ابن ماجة في السنن (١/ ١٤)، والدارمى في السنن (١/ ٧٧) والحاكم وقال على شرط مسلم وأقره الذهبى (١/ ١١١) والطحاوى في مشكل الآثار (١/ ١٧٢) كلهم أخرجوه من طريق محمد بن اسحاق عن ابن لكعب بن مالك به."],[11282,"وأخرجه أيضا الحافظ ابن حجر في المطالب العالية (٣/ ١٣٦) وعزاه لابن منيع من طريق عبد اللَّه بن كعب بن مالك به."],[11283,"قلت: وقد ذكر الحافظ الدارقطنى هذا الحديث في العلل (٥/ ٦٢/ ب) وذكر طرقه والاختلاف فيها، وصوّب طريق محمد بن اسحاق عن معبد بن = ١٧٦١ - أبو محمد الهذلى، عن الحسن. روى عنه عكرمة بن خالد (١)."],[11284,"١٧٦٢ - أبو محمد عن الحسن. روى عنه جرير بن حازم (روى عنه جرير ابن حازم) (٢) ذكرهما الحاكم أبو أحمد هذا والهذلى."],[11285,"وذكر أبو حاتم أبو محمد سمع الحسن. روى عنه حريز بن عثمان وفى ذلك عندى نظر، وممكن أن يكونا واحدا (٣)."],[11286,"١٧٦٣ - أبو محمد مولى قريش، عن عباد (٤) بن الربيع (٥) روى عنه هشيم."],[11287,"= كعب بن مالك وهو يوافق بهذا قول أبى حاتم -كما سبق وأن عرفت- حيث قال: الصحيح عن معبد بن كعب بن مالك. أى انهما يريان بأن أبا محمد هذا إنما هو معبد بن كعب بن مالك. واللَّه أعلم."],[11288,"١٧٦١ - كنى البخارى (ص ٦٧)، الجرح (٤/ ٢/ ٤٣٣)، المقتنى في سرد الكنى (١٢٢/ ب)."],[11289,"(١) عكرمة بن خالد بن العاص بن هشام المخزومى، ثقة، من الثالثة. انظر التقريب (٢/ ٢٩)."],[11290,"١٧٦٢ - كنى البخارى (ص ٦٧)، الجرح (٤/ ٢/ ٤٣٤) وقال: سمعت أبى يقول: هو مجهول، الميزان (٤/ ٥٧٠)، اللسان (٧/ ١٠٢)."],[11291,"(٢) هكذا هو مكرر في الأصل."],[11292,"(٣) هكذا ذكر ابن عبد البر هنا ورجح أن يكونا واحدا. . وقد فرق البخارى بينهما انظر الكنى (ص ٦٧). واللَّه أعلم."],[11293,"١٧٦٣ - كنى البخارى (ص ٦٧)، الجرح (٤/ ٢/ ٤٣٤) وقال: سمعت أبى يقول: هو مجهول، الميزان (٤/ ٥٧٠)، اللسان (٧/ ١٠١) وقال مجهول."],[11294,"(٤) في اللسان \"عبادة\" بزيادة هاء. وهو خطأ."],[11295,"(٥) عباد بن الربيع ذكره ابن أبى حاتم في الجرح (٣/ ١/ ٧٩) وقال عن أبيه: هو كوفى، إمام من أئمة نُخَيلة، روى عن على، روى هشيم عن أبى محمد عن عباد بن الربيع."],[11296,"قلت: ونُخيلة، تصغير نخلة، موضع قرب الكوفة، على سمت الشام معجم البلدان (٥/ ٢٧٨)."],[11297,"١٧٦٤ - أبو محمد البصرى، عن نعيم بن أبى هند. روى عنه عباد بن العوام."],[11298,"١٧٦٥ - أبو محمد الخزاعى، روى عن سعيد بن المسيب، روى عنه حماد ابن سلمة، روى عباس بن محمد الدورى، عنى يحيى بن معين أنه سئل عن أبى محمد الخزاعى الذى روى عن ابن المسيب في قضاء رمضان الذى روى عنه حماد بن سلمة فقال: هو مشهور (١)."],[11299,"١٧٦٦ - أبو محمد الخراسانى، روى عن (. . . .) (٢) روى عنه أبو عبد الرحمن المقرئ، هو عندهم مجهول."],[11300,"١٧٦٤ - كنى البخارى (ص ٦٧)، الجرح (٤/ ٢/ ٤٣٣) وقال: هو مجهول، الميزان (٤/ ٥٧٠)، المقتنى في سرد الكنى (١٢٢/ ب)، اللسان (٧/ ١٠٢)، وقال: مجهول."],[11301,"١٧٦٥ - الجرح (٤/ ٢/ ٤٣٤)."],[11302,"(١) الجرح (٤/ ٢/ ٤٣٤) قلت: لم أقف على قول يحيى بن معين في التاريخ. واللَّه أعلم."],[11303,"١٧٦٦ - الجرح (٤/ ٢/ ٤٣٤) وذكره كما هنا وقال: سألت أبى عنه فقال: مجهول الميزان (٤/ ٥٧٠)، اللسان (٧/ ١٠٢) وقال: مجهول."],[11304,"(٢) هكذا في الأصل بياض بمقدار كلمتين، ومثله في الجرح، ولم يذكر الذهبى، وابن حجر له شيخا وإنما ذكرا تلميذه فقط."],[11305,"باب أبى موسى"],[11306,"١٧٦٧ - أبو موسى الحذاء روى عن عبد اللَّه بن عمرو بن العاص. وحديثه عند الثورى عن حبيب بن أبى ثابت عنه، وروى ذلك الحديث الأعمش عن حبيب بن أبى ثابت عن عبد اللَّه بن باباه (١). عن عبد اللَّه بن عمرو فجعل مكان أبى موسى عبد اللَّه بن باباه (. . . . .) (٢) الثورى لحفظ ذلك وخطؤا الأعمش (٣) وقد روى عن أبى موسى الحذاء مجاهد بن جبر."],[11307,"١٧٦٧ - كنى البخارى (ص ٦٩)، الثقات (٥/ ٥٨٤)، الجرح (٤/ ٢/ ٤٣٨) الميزان (٤/ ٥٧٨)، التهذيب (١٢/ ٢٥١)."],[11308,"(١) عبد اللَّه بن باباه، بموحدتين بينهما الف ساكنة. ويقال بتحتانية بدل الالف، ويقال بحذف الالف. ويقال بحذف الهاء، المكى، ثقة، من الرابعة./ م. عـ. التقريب (١/ ٤٠٣)."],[11309,"(٢) في الأصل كلمة غير واضحة."],[11310,"(٣) الحديث ذكره الذهبى في الميزان (٤/ ٥٧٨) فقال: أبو موسى الحذاء عن عبد اللَّه بن عمرو في صلاة القاعد لا يعرف، تفرد به حبيب بن أبى ثابت، ولعله عبد اللَّه بن باباه، فان الأعمش سماه عن حبيب عنه. اهـ. وحديث عبد اللَّه بن عمرو بن العاص برواية أبى موسى الحذاء وبرواية عبد اللَّه بن باباه. لم يشر إليه ابن عبد البر هنا ولكن أشار إليه الذهبى في الميزان وابن حجر في التهذيب وهو \"في صلاة الرجل قاعدا\"."],[11311,"والحديث أخرجه ابن ماجه \"إقامة الصلاة والسنة فيها\" باب صلاة القاعد على النصف من صلاة القائم (١/ ٣٨٨) من طريق قطبه عن الأعمش عن حبيب أبى ثابت عن عبد اللَّه بن باباه عن عبد اللَّه بن عمرو أن النبى -صلى الله عليه وآله وسلم- مرّ به وهو يصلى جالسا فقال: \"صلاة الجالس على النصف من صلاة القائم\"."],[11312,"وأخرجه أيضا النسائى في السنن الكبرى كما في تحفة الاشراف = ١٧٦٨ - أبو موسى الحكمى. روى عن النبى عليه السلام. مرسلا أنه قال: \"لا تزال هذه الأمة متمسكة بما هى فيه ما لم تكذب بالقدر\" (١). فقال له مروان: هل"],[11313,"= (٦/ ٤٠٠) من طريق سفيان عن حبيب عن أبى موسى الحذاء عن عبد اللَّه ابن عمرو به. وأخرج مسلم \"صلاة المسافرين\" باب جواز النافلة قاعدا أو قائما (١/ ٥٠٧) وأبو داود \"الصلاة\" باب صلاة القاعد (١/ ٢٥٠) والنسائى \"قيام الليل\" باب فضل صلاة القائم على القاعد (٣/ ٢٢٣)، والدارمى (١/ ٣٢١)، وأحمد (٢/ ١٦٢ و١٩٢ و٢٠١ و٢٠٣) حديث عبد اللَّه بن عمرو برواية هلال بن يساف عن أبى يحيى عنه أنه قال: حدّثت أن رسول اللَّه -صلى الله عليه وآله وسلم- قال: \"صلاة الرجل قاعدا نصف الصلاة\" قال: فأتيته فوجدته يصلى جالسا. فوضعت يدى على رأسه فقال: ما لك يا عبد اللَّه بن عمرو؟ قلت: حدثت يا رسول اللَّه إنك قلت \"صلاة الرجل قاعدا على نصف الصلاة\" وأنت تصلى قاعدا."],[11314,"قال: \"أجل. ولكنى لست كأحد منكم\". اللفظ لمسلم."],[11315,"ويشهد لحديث عبد اللَّه بن عمرو حديث عمران بن حصين قال: سألت رسول اللَّه -صلى الله عليه وآله وسلم- عن صلاة الرجل قاعدا فقال \"ان صلى قائما فهو أفضل ومن صلى قاعدا فله نصف أجر القائم ومن صلى نائما فله نصف أجر القاعد\" أخرجه البخارى \"تقصير الصلاة\" باب صلاة القاعد (٢/ ٥٨٤) وأبو داود \"الصلاة\" باب صلاة القاعد (١/ ٢٥٠) والترمذى \"الصلاة\" باب صلاة القاعد على النصف من صلاة القائم (٢/ ٣٦٨) وقال: حديث حسن صحيح. والنسائى \"القيام\" باب فضل صلاة القاعد على صلاة النائم (٣/ ٢٢٣ - ٢٢٤) وابن ماجه \"إقامة الصلاة\" باب صلاة القاعد على النصف من صلاة القائم (١/ ٣٨٨) والبيهقى (٢/ ٤٩١) وأحمد (٤/ ٤٣٣ و٤٣٥ و٤٤٣)."],[11316,"١٧٦٨ - كنى البخارى (ص ٦٩)، الجرح (٤/ ٢/ ٤٣٨)، الاستيعاب (٤/ ١٧٥)، الإصابة (٤/ ١٨٧)، وقال: ذكره البغوى ولم يخرج له شيئا، وأبو نعيم في الصحابة وقال: ذكره البخارى في الكنى ولا ادرى له صحبة؟ ."],[11317,"(١) الحديث أخرجه البخارى في الكنى، وابن أبى حاتم في الجرح وابن منده في الصحابة كما في الإصابة (٤/ ١٨٧)، وأبو أحمد الحاكم في الكنى. كما ="],[11318,"كان ذكر القدر على عهد رسول اللَّه -صلى الله عليه وآله وسلم-. حديثه عند الحجاج بن فُرَافِصة (١) (عن) (٢) (عمر) (٣) بن أبى سفيان عن أبى موسى الحكمى."],[11319,"١٧٦٩ - أبو موسى الهمدانى. روى عن على قصة ذى الثُّدَيَّة (٤) روى عنه"],[11320,"= في الاستيعاب (٤/ ٧٥) كلهم أخرجوه من طريق حجاج بن فرافصة عن عمرو بن أبى سفيان قال: كنا عند مروان فجاء أبو موسى الحكمى فقال له مروان: هل كان ذكر القدر على عهد رسول اللَّه -صلى الله عليه وآله وسلم-؟ فقال: قال رسول اللَّه -صلى الله عليه وآله وسلم-: \"لا تزال هذه الأمة متمسكة بما هى فيه ما لم تكذب بالقدر، فإذا كذبوا بالقدر فعند ذلك هلاكها للمكذبين بالقدر. . \" الحديث."],[11321,"وذكر الهيثمى هذا الحديث في مجمع الزوائد (٧/ ٢٠٣) لكن من حديث أبى موسى الاشعرى. وقال: رواه الطبرانى، وأبو البكرات تابعى لم أعرفه وبقية رجاله ثقات."],[11322,"(١) فُرَافِصة: بضم الفاء الأولى وكسر الثانية بعدها صاد مهملة، جاء في الاكمال (٧/ ٦٤) كل اسم في العرب فرافصة فهو مضموم الفاء إلا الفرافصه رجل وهو ابن الاحوص بن عمرو بن ثعلبة بن الحارث بن حصين الكلبى اهـ."],[11323,"قلت: وحجاج بن فرافصة هذا صدوق عابد، يهم، من السادسة. التقريب (١/ ١٥٤)."],[11324,"(٢) في الأصل \"على\" وهو تحريف، والمثبت عن مصادر الترجمة."],[11325,"(٣) هكذا في الأصل \"عمر\" والذى في مصادر الترجمة \"عمرو\" وفى التقريب (٢/ ٧١) عمرو بن أبى سفيان بن أسِيد، بفتح أوله، ابن جارية بالجيم الثقفى المدنى، حليف بنى زهرة، وقد ينسب لجده، ويقال: عمر، ثقة، من الثالثة. اهـ."],[11326,"١٧٦٩ - الجرح (٤/ ٢/ ٤٣٩) وقال: سمعت أبى يقول: هو مجهول، الميزان (٤/ ٥٧٨)، اللسان (٧/ ١١٣)."],[11327,"قال الذهبى وتبعه ابن حجر: مجهول."],[11328,"(٤) قصة ذى الثُّديَّة. انظر هذه القصة مفصلة في السنة لابن أبى عاصم (٢/ ٤٤١ و٤٤٣ و٤٤٤)، والملل والنحل (٢/ ٢٥) وما بعدها وانظر أيضا الترجمة (١٧٠٥) والترجمة (١٤٠٣) والتعليق عليهما."],[11329,"رمح (١)."],[11330,"١٧٧٠ - أبو موسى الهمدانى. روى عن الوليد بن عقبة بن أبى (معيط) (٢). روى عنه عبد اللَّه الهمدانى (٣). وعبد اللَّه الهمدانى، وأبو موسى الهمدانى ليسا بمعروفين، ومنهم من لا يقول الهمدانى في أبى موسى."],[11331,"١٧٧١ - أبو موسى الهلالى (٤)."],[11332,"عن أبيه (٥) عن عبد اللَّه بن مسعود كعب بن عجرة. ومنهم من يقول: عن أبى موسى الهلالى عن أبيه عن ابن لعبد اللَّه بن مسعود (٦) عن ابن مسعود. روى عنه سليمان بن المغيرة."],[11333,"(١) في اللسان \"رُمَيح\" بالتصغير. والذى في بقية المصادر \"رمح\" كما هنا وفى الجرح (٢/ ١/ ٥٢٢) رمح بن نفيل الكلابى، كوفى روى عن عبد الرحمن ابن الأسود، والشعبى، روى عنه أبو أسامة، وعبد اللَّه بن داود الخريبى ومروان الفزارى. . . سمعت أبى يقول: ذلك. وسألت أبا زرعة عنه فقال: لا أعرفه إلا برواية عبد اللَّه بن داود عنه. اهـ."],[11334,"١٧٧٠ - الجرح (٤/ ٢/ ٤٣٨)، اللسان (٧/ ١١٢)."],[11335,"(٢) الحق في هامش الأصل. كتب عنده كلمة \"صح\"."],[11336,"(٣) في التقريب (١/ ٤٦٣) عبد اللَّه الهمدانى، أبو موسى، محهول وخبره منكر، قاله ابن عبد البر، من الرابعة. اهـ."],[11337,"١٧٧١ - كنى البخارى (ص ٦٩)، الثقات (٧/ ٦٦٣)، الجرح (٤/ ٢/ ٤٣٨) وقال: سألت أبى عنه فقال: هو مجهول، وأبوه مجهول، الميزان (٤/ ٥٧٨)، تهذيب الكمال (٣/ ١٦٥٢)، التهذيب (١٢/ ٢٥١) التقريب (٢/ ٤٧٩) وقال: مقبول، من الثالثة./ د."],[11338,"(٤) الهلالى: بكسر الهاء - نسبة إلى هلال بن عامر بن صعصعه بن معاوية بن بكر بن هوازن، قبيلة كبيرة. اللباب (٣/ ٣٩٦)."],[11339,"(٥) و(٦) أبو أبى موسى الهلالى وابن لعبد اللَّه بن مسعود. هكذا ذكرا هنا من غير تسمية. وكذا ذكرا أيضا في مصادر الترجمة وفى تحفة الاشراف للمزى (٧/ ١٦٩) من غير تسمية."],[11340,"وذكر أيضا أبو داود \"النكاح\" باب في رضاعة الكبير (٢/ ٢٢٢) = ١٧٧٢ - أبو موسى الأسدى كوفى. روى عن الشعبى. روى عنه سفيان الثورى."],[11341,"١٧٧٣ - أبو موسى التّمّار عن وهب بن منبه اليمانى: روى عنه الثورى. قد قيل: انه الاسدى الذى روى عن الشعبى."],[11342,"١٧٧٤ - أبو موسى الصّفَار. روى عن ابن عباس. روى عنه موسى بن المغيرة (١)."],[11343,"= حديث ابن مسعود من طريق عبد السلام بن مطهر أن سليمان بن المغيرة حدثهم عن أبى موسى، عن أبيه عن ابن لعبد اللَّه بن مسعود عن ابن مسعود قال: \"لا رضاع إلا ما شدّ العظم وانبت اللحم فقال أبو موسى: لا تسألونا وهذا الحبر فيكم. ومن طريق محمد بن سليمان الأنبارى، ثنا وكيع عن سليمان بن المغيرة، عن أبى موسى الهلالى، عن أبيه عن ابن مسعود عن النبى -صلى الله عليه وآله وسلم- بمعناه، وقال: \"انشز العظم\" اهـ."],[11344,"قلت: هكذا ذكر أبو داود الطريقين، ولم يسم الرجلين. فاللَّه أعلم."],[11345,"١٧٧٢ - الجرح (٤/ ٢/ ٤٣٨) وذكره كما هنا."],[11346,"١٧٧٣ - كنى البخارى (ص ٧٠)، الثقات (٧/ ٦٦٤)، الجرح (٤/ ٢/ ٤٣٨) الميزان (٤/ ٥٧٨)، التهذيب (١٢/ ٢٥٢)، التقريب (٢/ ٤٧٩)، وقال: مجهول، من السادسة، ووهم من قال: انه اسرائيل بن موسى./ د. ت. س."],[11347,"١٧٧٤ - الجرح (٤/ ٢/ ٤٣٨)، الميزان (٤/ ٥٧٨)، اللسان (٧/ ١١٣) قال الذهبى وتبعه ابن حجر: مجهول، وقال ابن أبى حاتم: سألت أبى عنه فقال: هو مجهول."],[11348,"(١) موسى بن المغيرة، ذكره ابن حجر في اللسان (٦/ ١٣٢) وذكر له حديثا يرويه عن أبى موسى الصفار عن ابن عباس في الصدقة. اهـ."],[11349,"باب أبى مريم"],[11350,"١٧٧٥ - أبو مريم الشامى، روى عن عمر بن الخطاب. حديثه عند ثور بن يزيد عن زياد بن أبى سودة (١) عنه."],[11351,"١٧٧٦ - أبو مريم الحضرمى شامى. روى عنه يحيى بن أبى عمرو الشيبانى."],[11352,"١٧٧٧ - أبو مريم السّكونى. روى عن ثوبان عن النبى عليه السلام. قال \"من حافظ على الأذان سنة وجبت له الجنة\" (٢)."],[11353,"١٧٧٥ - كنى البخارى (ص ٦٨)، الجرح (٤/ ٢/ ٤٣٦)، المقتنى في سرد الكنى (١٢٦/ أ)، تاريخ دمشق (ل/ ٦٨٧)."],[11354,"(١) مقدسى، أخو عثمان، ثقة، من الثالثة./د. ق. التقريب (١/ ٢٦٨)."],[11355,"١٧٧٦ - المقتنى في سرد الكنى (١٢٦/ ب)."],[11356,"١٧٧٧ - كنى البخارى (ص ٦٨)، الثقات (٥/ ٥٨٤)، الجرح (٤/ ٢/ ٤٣٦) المقتنى في سرد الكنى (١٢٦/ ب)."],[11357,"(٢) الحديث أخرجه البخارى في الكنى (ص ٦٨) من حديث محمد بن سعيد عن أبى معاوية عن أبى قيس الدمشقى، عن عبادة بن نسى عن أبى مريم عن ثوبان يرفعه به، وأخرجه أبو الشيخ في كتاب الاذان، والبيهقى في شعب الايمان كما في الجامع الكبير للسيوطى (١/ ٧٧٠) وقال السيوطى: ضعيف، وذكره السيوطى أيضا في الجامع الصغير (٢/ ١٦٩) وعزاه للبيهقى في شعب الايمان ورمز لضعفه."],[11358,"وقال المناوى في فيض القدير (٦/ ١١٥) الذى وقفت عليه في أصول صحيحة من الشعب بدل وجبت. . إلخ \"أوجب الجنة\" فلينظر، والمراد من حافظ على ذلك محتسبا كما قيده به في روايات أخر. اهـ."],[11359,"وأخرج ابن الجوزى في العلل المتناهية (١/ ٣٩٧) حديثا عن أنس رضي الله عنه من طريق عبد اللَّه بن على المقرئ قال: نا جدى أبو منصور = إلا أنه من حديث محمد بن سعيد (١) عن أبى معاوية (٢) عن أبى قيس عن عبادة بن نسى عن أبى مريم عن ثوبان عن النبى عليه السلام."],[11360,"١٧٧٨ - أبو مريم الأنصارى. عن جابر بن عبد اللَّه عن النبى عليه السلام. في العزل: قال: \"ما من نفس قدر اللَّه أن تخريج إلا هى كائنه\" (٣). روى عنه معاوية ابن صالح."],[11361,"= المقرئ قال: نا عبد اللَّه بن عمر بن شاهين قال: نا جعفر بن عبد اللَّه بن مجاشع قال: نا محمد بن مسلمة قال: نا موسى الطويل قال: حدثنى أنس قال: قال رسول اللَّه -صلى الله عليه وآله وسلم- \"من أذن سنة بنية صادقة ما يطلب عليها أجرا دعى يوم القيامة فوقف على باب الجنة وقيل له اشفع لمن شئت\" اهـ."],[11362,"(١) محمد بن سعيد، هو الذى صلب في الزندقة كما ذكر ابن أبى حاتم في ترجمة أبى مريم (٤/ ٢/ ٤٣٦) وقال ابن حجر في التقريب (٢/ ١٦٤) محمد بن سعيد بن حسان بن قيس الاسدى الشامى المصلوب. . وذكر أنه قد ينسب لجده وقيل: انهم قلبوا اسمه على مائة وجه ليخفى كذبه، وقال أحمد بن صالح: وضع أربعة الآف حديث، وقال أحمد: قتله المنصور على الزندقة وصلبه من السادسة. اهـ."],[11363,"(٢) هو الضرير كما في ترجمة أبى قيس الدمشقى. انظر الترجمة (٢٣٢٨)."],[11364,"١٧٧٨ - كنى البخارى (ص ٦٨)، الجرح (٤/ ٢/ ٤٣٦)، المقتنى في سرد الكنى (١٢٦/ ب)."],[11365,"(٣) الحديث أخرجه البخارى في الكنى (ص ٦٨) وابن أبى حاتم في الجرح (٤/ ٢/ ٤٣٦) من طريق معاوية بن صالح عن أبى مريم الأنصارى عن جابر ابن عبد اللَّه به مرفوعا. ومن حديث جابر أخرجه أيضا البخارى \"النكاح\" باب العزل (٩/ ٣٠٥) ومسلم \"النكاح\" حكم العزل (٢/ ١٠٦٤ - ١٠٦٥) وأبو داود \"النكاح\" باب ما جاء في العزل (٢/ ٢٥٢) والترمذى \"النكاح\" باب ما جاء في العزل (٤/ ٢٨٧ - ٢٩٠) وابن ماجة \"المقدمة\" (١/ ٣٤) وفى \"النكاح\" باب العزل (١/ ٦٢٠) والطحاوى في شرح معانى الآثار (٣/ ٣٥) وابن أبى عاصم في السنة (١/ ١٦٠) وأحمد في المسند (٣/ ٣٠٩ و٣١٣ و٣٨٠ و٣٨٦ و٣٨٨) وابن أبى شيبة (٤/ ٢١٩ و٢٢٠) وعبد الرزاق."],[11366,". . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . ."],[11367,"= (٧/ ١٤٠ و١٤١ و١٤٤) وابن حبان في الصحيح كما في الجامع الكبير للسيوطى (١/ ٧٠٨) ولم أقف عليه في صحيح ابن حبان ولا في موارد الظمآن - كلهم أخرجوه من حديث جابر رضي الله عنه ومن غير وجه عنه وللحديث عند بعضهم قصّة وهى أن رجلا من الأنصار جاء إلى النبى -صلى الله عليه وآله وسلم- فقال: يا رسول اللَّه إن لى جارية تسير تستقى على ناضحى وأنا أصيب منها أفأعزل فقال رسول اللَّه -صلى الله عليه وآله وسلم- \"نعم فاعزل\" فلم يلبث الرجل أن جاء فقال: يا رسول اللَّه عزلت عنها فحملت فقال: رسول اللَّه -صلى الله عليه وآله وسلم- \"ما قدر اللَّه عز وجل لنفس أن يخلقها إلا وهى كائنة\". وللحديث عندهم لفظ آخر. وهو أنه قال جابر رضي الله عنه \"كنا نعزل والقرآن ينزل\"."],[11368,"قال الحافظ ابن حجر في الفتح (٩/ ٣٠٦) في التعليق على هذا الحديث والمسألة المشهورة في الأصول وفى علم الحديث وهى أن الصحابى إذا أضافه إلى زمن النبى -صلى الله عليه وآله وسلم- كان له حكم الرفع عند الأكثر لأن الظاهر أن النبى -صلى الله عليه وآله وسلم- اطلع على ذلك وأقره لتوفر دواعيهم على سؤالهم اياه عن الأحكام وإذا لم يضفه فله حكم الرفع عند قوم وهذا من الأول فإن جابرا صرح بوقوعه في عهده وقد وردت عدة طرق تصرح باطلاعه على ذلك. اهـ."],[11369,"ويشهد لهذا الحديث حديث أبى سعيد الخدرى رضي الله عنه بنحو لفظ حديث جابر وهو أنه -صلى الله عليه وآله وسلم- سئل عن العزل فقال: \"لا عليكم إلا تفعلوا فانه ليست نسمة كتب اللَّه أن تخريج إلا هى كائنة\" أخرجه البخارى \"البيوع\" باب الرقيق (٤/ ٤٢٠) و\"العتق\" باب من ملك من العرب رقيقا (٥/ ١٧٠) و\"المغازى\" غزوة بنى المصطلق (٧/ ٤٢٨) و\"النكاح\" باب العزل (٩/ ٣٠٥) و\"القدر\" (١١/ ٤٩٤) و\"التوحيد\" (١٣/ ٣٩٠ - ٣٩١) ومسلم \"النكاح\" باب حكم العزل (٢/ ١٠٦١ - ١٠٦٤) وأبو داود \"النكاح\" باب ما جاء في العزل (٢/ ٢٥٢)، والترمذى \"النكاح\" باب ما جاء في كراهية العزل (٤/ ٢٩٠ - ٢٩١)، والنسائى \"النكاح\" باب العزل (٦/ ١٠٧) وابن ماجة \"النكاح\" باب العزل (١/ ٦٢٠) ومالك \"الطلاق\" باب ما جاء في العزل (٢/ ٥٩٤) والدارمى (٢/ ١٤٨)، والطحاوى في شرح معانى الآثار (٣/ ٣٣)، وعبد الرزاق (٧/ ١٤٦) وابن أبى شيبة (٤/ ٢٢٢)."],[11370,"١٧٧٩ - أبو مريم. مولى أبى هريرة، عن أبى هريرة، عن النبى عليه السلام قال: \"الملك في قريش والقضاء في الأنصار والاذان في الحبشة\" (١). روى عنه معاوية بن صالح الحضرمى."],[11371,"١٧٨٠ - أبو مريم خادم مسجد دمشق. روى عن أبى هريرة. روى عنه،"],[11372,"١٧٧٩ - كنى البخارى (ص ٦٨)، الجرح (٤/ ٢/ ٤٣٧)، المقتنى في سرد الكنى (١٢٦/ ب)."],[11373,"(١) الحديث أخرجه الترمذى \"الفضائل\" باب فضل اليمن (١٠/ ٤٣٧ - ٤٣٨) من طريق زيد بن حباب أخبرنا معاوية بن صالح، أخبرنا أبو مريم الأنصارى عن أبى هريرة قال: قال رسول اللَّه -صلى الله عليه وآله وسلم- \"الملك في قريش والقضاء في الأنصار والاذان في الحبشة والامانة في الازد -يعنى اليمن\"."],[11374,"وأخرجه الترمذى أيضا من طريق عبد الرحمن بن مهدى عن معاوية بن صالح عن أبى مريم الأنصارى عن أبى هريرة بنحوه. وقال الترمذى: لم يرفعه وهذا أصح من حديث زيد بن حباب. اهـ. وقال المبارك فورى في تحفة الاحوذى (١٠/ ٤٣٨) قوله \"وهذا أصح من حديث زيد بن حباب\" لأن عبد الرحمن بن مهدى أوثق وأحفظ من زيد بن حباب. اهـ. وأخرجه أيضا أحمد في المسند (٢/ ٣٦٤) من طريق زيد بن الحباب به. والحديث ذكره أيضا البخارى في الكنى (ص ٦٨) وابن أبى حاتم في الجرح (٤/ ٢/ ٤٣٧) من طريق معاوية بن صالح عن أبى مريم مولى أبى هريرة به مرفوعًا. وأخرجه أيضا ابن جرير في تهذيب الآثار كما في الجامع الكبير للسيوطى (١/ ٤٤٨) وذكر السيوطى في الجامع الصغير (٢/ ١٨٧) هذا الحديث عن أبى هريرة ورمز لصحته."],[11375,"١٧٨٠ - كنى البخارى (ص ٦٩)، تاريخ دمشق (ل ٦٨٤)، الجرح (٤/ ٢/ ٤٣٧) الميزان (٤/ ٥٧٢)، التهذيب (١٢/ ٢٣١)، التقريب (٢/ ٤٧١)، المقتنى في سرد الكنى (١٢٦/ ب)."],[11376,"قال ابن أبى حاتم: جعل البخارى هذا والذى تقدم مولى أبى هريرة اثنين فسمعت أبى يقول: هذا ومولى أبى هريرة واحد. اهـ."],[11377,"وقال الذهبى: أبو مريم الأنصارى ويقال الحضرمى القناديلى قيم جامع ="],[11378,"حريز بن عثمان (١)."],[11379,"١٧٨١ - أبو مريم، مكاتب عائشة، سمع عائشة أم المؤمنين، روى عنه، خصيف بن عبد الرحمن الجزرى."],[11380,"١٧٨٢ - أبو مريم. عن هشام بن أبى رقية (٢). سمع عقبة بن عامر عن النبى عليه السلام. في لبس الحرير (٣)."],[11381,"= دمشق. وقيل حمصى. وقيل مولى أبى هريرة. وقيل: هم ثلاثة قال ابن أبى حاتم: اسمه عبد الرحمن بن ماعز، أدرك عليا وروى عن أبى هريرة وجابر. وعنه يحيى بن أبى عمرو الشيبانى، ومعاوية بن صالح وحريز بن عثمان، وصفوان بن عمرو. اهـ. قلت: وقال المزى في تحفة الاشراف: (١١/ ٩٢) الاشبه انهما رجل واحد. اهـ."],[11382,"(١) حريز بن عثمان: بالمهملة والزاى وهو الرحبى. قال ابن حجر في اللسان (٢/ ١٠٣) في ترجمة جرير بن عثمان. بأنه شديد الالتباس بحريز بن عثمان الرحبى المخرج له في الصحيح. اهـ."],[11383,"١٧٨١ - كنى البخارى (ص ٦٩)، الجرح (٤/ ٢/ ٤٣٧)، التهذيب (١٢/ ٢٣٣) المقتنى في سرد الكنى (١٢٦/ ب)، التقريب (٢/ ٤٧٢) وقال: مجهول، من الثالثة./ ق."],[11384,"١٧٨٢ - المقتنى في سرد الكنى (١٢٦/ ب)."],[11385,"(٢) هشام بن أبى رقية، مصرى، روى عن عبد اللَّه بن عمرو بن العاص وعقبة بن عامر ومسلمة بن مخلد، انظر الجرح (٤/ ٢/ ٥٧)، التاريخ الكبير (٤/ ٢/ ١٩٢)."],[11386,"(٣) الحديث: أخرجه أحمد في المسند (٤/ ١٥٦) وابن عبد الحكم في فتوح مصر (ص ٢٩٣) وأبو يعلى والبزار والطبرانى في الكبير والأوسط كما في مجمع الزوائد (٥/ ٣٢) وقال الهيثمى رجالهم ثقات. اهـ. كلهم أخرجوه من طريق عمرو بن الحارث عن هشام بن أبى رقية قال: سمعت مسلمة بن مخلد وهو قاعد على المنبر يخطب الناس وهو يقول: يا أيها الناس أما لكم في العصب والكتّان ما يكفيكم عن الحرير وهذا رجل فيكم يخبركم عن رسول اللَّه -صلى الله عليه وآله وسلم-. قم يا عقبة. فقام عقبة بن عامر وأنا أسمع فقال: انى سمعت ="],[11387,". . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . ."],[11388,"= رسول اللَّه -صلى الله عليه وآله وسلم- يقول: \"من كذب على متعمدا فليّتبوأ مقعده من النار وأشهد أنى سمعته يقول: \"من لبس الحرير في الدنيا حُرِمه أن يلبسه في الآخرة\". والحديث أخرجه البخارى \"كتاب اللباس\" باب لبس الحرير للرجال (١٠/ ٢٨٤) من حديث أنس بن مالك ومن حديث عمر بن الخطاب رضي الله عنهما ومن حديث عبد اللَّه بن الزبير بنحوه. وأخرجه أيضا مسلم \"اللباس والزينة\" باب تحريم استعمال اناء الذهب والفضة على الرجال والنساء وخاتم الذهب والحرير على الرجال واباحته للنساء (٣/ ١٦٤٥ - ١٦٤٦) من حديث أنس وأبى امامه بلفظ \"من لبس الحرير في الدنيا لم يلبسه في الآخرة\" وبمثل هذا اللفظ أخرجه الترمذى \"الأدب\" باب كراهية الحرير والديباج\" (٨/ ١٠٣) من حديث عمر بن الخطاب رضي الله عنه وقال الترمذى: حسن صحيح. وأخرجه أيضا النسائى \"اللباس\" باب التشديد في لبس الحرير وأن من لبسه في الدنيا لم يلبسه في الآخرة (٨/ ٢٠٠) وأخرجه أيضا ابن ماجة \"اللباس\" باب كراهية لبس الحرير (٢/ ١١٨٧) من حديث أنس به وبنحوه من حديث حذيفة بن اليمان."],[11389,"باب أبى معاذ"],[11390,"١٧٨٣ - أبو معاذ الصيرفى (١)، روى عن أنس، روى عنه صفوان بن عمرو السكسكى."],[11391,"١٧٨٤ - أبو معاذ الواسطى، قال: سمعت أنس بن مالك يقول: \"كان النبى عليه السلام يقنت في الفجر\" (٢). روى عنه يونس بن بكير."],[11392,"١٧٨٣ - كنى البخارى (ص ٦٩)، الجرح (٤/ ٢/ ٤٣٧). كنى الدولابى (٢/ ١٢٣) المقتنى في سرد الكنى (١٣٠/ أ)."],[11393,"(١) هكذا في الأصل \"الصيرفى\"، وفى كنى البخارى \"الصروى\" وفى الجرح \"الصردفى\" وفى كنى الدولابى \"الصردى\" والأشبه أن يكون الصيرفى."],[11394,"١٧٨٤ - الجرح (٤/ ٢/ ٤٣٧)، وقال: سئل أبو ز عة عن اسمه فقال: لا أعرف اسمه."],[11395,"(٢) الحديث أخرجه ابن أبى حاتم في الجرح من طريق يونس بن بكير عن أبى معاذ الواسطى قال سمعت أنس بن مالك. فذكره، وحديث أنس هذا أخرجه أيضا من غير وجه البخارى \"الوتر\" باب القنوت قبل الركوع وبعده (٢/ ٤٨٩ و٤٩٠) وفى \"الجنائز\" باب من جلس عند المصيبة يعرف فيه الحزن (٣/ ١٦٦) وفى \"الجهاد\" باب من ينكب في سبيل اللَّه (٦/ ١٨ - ١٩ و٣١ و١٨٠ و٢٧٢) وفى \"المغازى\" باب غزوة الرجيع (٧/ ٣٨٥ و٣٨٩) ومسلم \"المساجد ومواضع الصلاة\" باب استحباب القنوت في جميع الصلاة إذا نزلت بالمسلمين نازلة (٤٦٨ - ٤٦٩) والدارمى (١/ ٣٧٤ - ٣٧٥) والبيهقى (٢/ ١٩٩ و٢٠٠ و٢٠١ و٢٠٢ و٢٠٦ و٢٠٧ و٢١١) وأبو داود \"الصلاة\" باب القنوت في الصلوات (٢/ ٦٨) وأحمد في المسند (٣/ ١٣٢ و١٩٦ و٢٥٥ و٢٨٨) وأبو عوانه في المسند (٢/ ٢٨١ و٢٨٥ و٢٨٦) والطحاوى في شرح معانى الآثار (١/ ٢٤٣ و٢٤٤ و٢٤٥ و٢٤٧ و٢٤٨) وابن أبى شيبة (٢/ ٣١٢ و٣١٨) والدارقطنى (٢/ ٣٨ و٣٩ و٤٠ و٤١)، وعبد الرزاق (٣/ ١١٠) والهمدانى في الاعتبار في الناسخ والمنسوخ ="],[11396,"١٧٨٥ - أبو معاذ مولى البراء بن عازب، روى عنه الثورى، وروى عنه شعبة فقال: عن أبى عثمان مولى البراء بن عازب. (روى عنه الثورى وروى عنه شعبة. فقال: عن أبى عثمان مولى البراء) (١)."],[11397,"١٧٨٦ - أبو معاذ، عن صالح (٢) قال: رأيت بيد ابن الحنفية (٣) أثر الحناء"],[11398,"= (ص ٨٨ و٩١ و٩٨) وابن جرير الطبرى في تهذيب الاثار (٢/ ٥ و١١ و١٨ و٢٨ و٣٠) والبزار كما في كشف الاستار (١/ ٢٦٩ - ٢٧٠)، وذكره الهيثمى في مجمع الزوائد (٢/ ١٣٩) وعزاه لأحمد والبزار وقال: رجاله موثقون، وذكره الهيثمى أيضا من وجه آخر وعزاه لأبى يعلى والبزار وقال: فيه حنظلة بن عبيد اللَّه السدوسى ضعفه أحمد وابن المدينى وجماعة ووثقه ابن حبان."],[11399,"ومن ألفاظ الحديث عندهم \"ما زال رسول اللَّه -صلى الله عليه وآله وسلم- يقنت في الفجر حتى فارق الدنيا\" ومن ألفاظه كذلك عند البخارى ومسلم البيهقى والطحاوى وابن أبى شيبة وابن جرير في تهذيب الآثار \"كان القنوت في الفجر والمغرب\"."],[11400,"وعلى كل فقد اختلف السلف الصالح رضوان اللَّه عليهم في القنوت في صلاة الصبح فذهب أكثرهم إلى إثبات القنوت وخالف اخرون ولكل من الفريقين أدلتهم. وقد أفاض الحافظ الإمام ابن جرير الطبرى في تهذيب الاثار (٢/ ١) وما بعدها في ذكر الأحاديث والآثار الواردة في هذه المسألة والتوفيق بينها وكذلك فعل الهمذانى في الاعتبار في الناسخ والمنسوخ (ص ٨٨) وما بعدها. وانظر أيضا نصب الراية لأحاديث الهداية مع التعليق بغية الالمعى في تخريج الزيلعى (٢/ ١٢٦) وما بعدها."],[11401,"١٧٨٥ - كنى البخارى (ص ٦٩)، الجرح (٤/ ٢/ ٤٣٧)."],[11402,"ذكر البخارى وابن أبى حاتم هذه الترجمة بنحو ما هنا وقال ابن أبى حاتم: سمعت أبى يقول: الثورى أحفظ."],[11403,"(١) هكذا مكرر في الأصل والظاهر أنه سبق قلم من النّسّاخ."],[11404,"١٧٨٦ - المقتنى في سرد الكنى (١٣٠/ أ)."],[11405,"(٢) هو صالح بن ميسم. انظر الطبقات الكبرى (٥/ ١١٤)."],[11406,"(٣) هو محمد بن على بن أبى طالب."],[11407,"فقلت له: ما هذا؟ فقال: \"كنت أخضب أمى\" (١). روى عنه الفضل بن دكين في الكوفيين."],[11408,"١٧٨٧ - أبو معاذ الأحموسى. الشامى روى عن النبى عليه السلام حديثا مرسلا. روى عنه معاوية بن صالح (٢)."],[11409,"١٧٨٨ - أبو معاذ الدَّامَغَانى (٣) الجدعانى (٤) روى عنه جرير بن عبد الحميد الضّبى."],[11410,"١٧٨٩ - أبو معاذ، شامى. روى عن يزيد بن يزيد بن جابر الازدى، روى عنه عبد العزيز بن محمد الدراورى."],[11411,"(١) أخرج هذا الأثر ابن سعد في الطبقات (٥/ ١١٤ - ١١٥) من طريق الفضل بن دكين قال: حدثنا أبو نعيم الخزاز قال: سمعت صالح بن ميسم قال: رأيت في يد محمد بن على بن الحنفية أثر الحناء فقلت له: ما هذا؟ فقال: كنت أخضب أمى\"."],[11412,"١٧٨٧ - كنى البخارى (ص ٦٩)، الجرح (٤/ ٢/ ٤٣٧)، المقتنى في سرد الكنى (١٣٠/ أ) وقال ارسل عنه معاوية بن صالح."],[11413,"(٢) هو الشامى كما قال البخارى في الكنى كما في ترجمة أبى معاذ هذا وهو معاوية بن صالح بن أبى عبد اللَّه الاشعرى أبو عبد اللَّه الدمشقى، صدوق، من الحادية عشرة (ت: ٢٦٣) التقريب (٢/ ٢٥٩)."],[11414,"١٧٨٨ - كنى البخارى (ص ٦٩)، الجرح (٤/ ٢/ ٤٣٨)."],[11415,"(٣) الدَّامَغانى: بفتح الدال، وسكون الألف وفتح الميم والغين المعجمة وسكون الألف وبعدها نون - هذه النسبة إلى دامغان. وهى مدينة من بلاد قومس ينسب اليها كثير من العلماء. اللباب (١/ ٤٨٦)."],[11416,"(٤) الجُدْعَانى: بضم الجيم وسكون الدال وبالعين المهملة وفى آخره النون بعد الألف - نسبة إلى بنى جدعان التيمى تيم قريش. اللباب (١/ ٢٦٢)."],[11417,"١٧٨٩ - كنى البخارى (ص ٦٩)، الجرح (٤/ ٢/ ٤٣٨)، المقتنى في سرد الكنى (١٣٠/ أ)."],[11418,"١٧٩٠ - أبو معاذ عن أبى كاهل (١) قال: قال لى رسول اللَّه: \"يا أبا كاهل\" (٢) روى عنه أبو منظور وهو حديث ليس مما يعتمد عليه لضعفه."],[11419,"١٧٩٠ - اللسان (٧/ ١٠٨)، المقتنى في سرد الكنى (١٣٠/ أ)."],[11420,"(١) أبو كاهل تقدم في الصحابة (١٤٨)."],[11421,"(٢) الحديث أخرجه الطبرانى (١٨/ ٣٦١ - ٣٦٢) من طريق الفضل بن عطاء عن الفضل بن شعيب عن أبى منظور عن أبى معاذ، عن أبى كاهل به مطولا وذكره السيوطى في الجامع الكبير (١/ ٩٤٥) وقال: أخرجه الطبرانى في الكبير وابن عدى في الكامل، وابن السكن في الصحابة وقال: اسناده مجهول، والحاكم أبو أحمد في الكنى، كما في الإصابة (٤/ ١٦٤) والعقيلى في الضعفاء (٣/ ١٤٧٤) من طريق الفضل بن جعفر قال حدثنا جدى محمد بن عبيد اللَّه قال: حدثنا يونس بن محمد المؤدب قال: حدثنا الفضل بن عطاء، عن الفضل بن شعيب عن أبى منظور، عن أبى معاذ عن أبى كاهل قال: قال رسول اللَّه -صلى الله عليه وآله وسلم-: \"يا أبا كاهل إلا أخبرك بقضاء قضاه اللَّه على نفسه؟ . قلت؟ بلى يا رسول اللَّه قال: من لى أن أبقى حتى أخبرَك به كلَّه، أحيا اللَّه قلبك فلا يمته حتى يميت بدنك. . \" وفيه أيضا \"اعلمن يا أبا كاهل أنه لم يغضب ربُّ العزة على من كان في قلبه مخافة ولا تأكل النار هُدبه. . \" الحديث. وفيه مسائل كثيرة. وقال العقيلى: فيه نظر. وقال ابن السكن: اسناده مجهول. وقال أبو أحمد الحاكم: لا يروى من وجه يعتمد، وذكر الحافظ ابن حجر هذا الحديث في اللسان (٤/ ٤٤٥) في ترجمة الفضل بن عطاء وقال: سنده مظلم، والمتن باطل، وقال ابن عبد البر في ترجمة أبى معاذ صاحب هذه الترجمة بعد أن ذكر هذا الحديث: حديث ليس مما يعتمد عليه لضعفه. وقد تقدم في ترجمة أبى كاهل شيخ أبى معاذ قول ابن عبد البر: روى عنه حديث منكر لا يصح. انظر الترجمة (١٤٨) وسيأتى في ترجمة أبى منظور الراوى لهذا الحديث عن أبى معاذ قول ابن عبد البر حيث قال: اسناد حديثه مجهول. انظر الترجمة (١٨٨٦)."],[11422,"باب أبى مالك"],[11423,"١٧٩١ - أبو مالك الدمشقى عن النبى -صلى الله عليه وآله وسلم- مرسلا. رواه معاوية بن صالح (١) عن عبد اللَّه بن دينار الدمشقى (٢) عن أبى مالك عن النبى عليه السلام."],[11424,"١٧٩٢ - أبو مالك القرظى (٣) والد ثعلبة بن أبى مالك (٤)، المدنى. روى عن عمر بن الخطاب أنه دعاه فيمن دعا من الأجناد الحديث. روى عنه ابنه ثعلبة."],[11425,"١٧٩١ - كنى البخارى (ص ٦٧)، الجرح (٤/ ٢/ ٤٣٤ - ٤٣٥) وقال: عن النبى -صلى الله عليه وآله وسلم-. . سمعت أبى يقول: هو مجهول. الميزان (٤/ ٦٧)، اللسان (٧/ ١٠٠)، المقتنى في سرد الكنى (١٢٣/ ب) قلت: وقد تقدم في الصحابة انظر الترجمة (١٨٠) وذكر له ابن عبد البر هناك حديث المسخط لابوية. . \" وقال: حديثه مرسل، لا تصح له صحبة."],[11426,"(١) هو الحضرمى. كما صرح بذلك ابن حجر في التهذيب (٥/ ٢٠٣) في ترجمة عبد اللَّه بن دينار البهرانى الدمشقى."],[11427,"(٢) ضعيف، من الخامسة./ ق. التقريب (١/ ٤١٣) وانظر التهذيب (٥/ ٢٠٣). وهو غير عبد اللَّه بن دينار العدوى. فذاك مدلس، من الرابعة."],[11428,"١٧٩٢ - الجرح (٤/ ٢/ ٤٣٤)، الإصابة (٤/ ١٧٢)، المقتنى في سرد الكنى (١٢٣/ ب) وقال: من جند عمر وهو والد ثعلبة. اهـ."],[11429,"(٣) القرظى: بضم القاف وفتح الراء وفى آخرها ظاء معجمة - هذه النسبة إلى قريظة، وهو اسم رجل نزل أولاده حصنا بقرب المدينة، وقريظة والنضير أخوان من أولاد هارون النبى عليه السلام. اهـ. اللباب (٣/ ٢٦)."],[11430,"(٤) ثعلبة بن أبى مالك القرظى، حليف الأنصار، أبو مالك، ويقال: أبو يحيى المدنى، مختلف في صحبته، وقال العجلى: تابعى ثقة/ خ. د. ق. التقريب (١/ ١١٩)."],[11431,"وذكر ابن سعد في الطبقات (٥/ ٧٩) في ترجمة ثعلبة بن أبى مالك = ١٧٩٣ - أبو مالك (١) بن ثعلبة بن أبى مالك القرظى المدنى. روى عن أبيه وعن عمر بن الحكم بن ثوبان (٢)."],[11432,"= القرظى قال: \"واسم أبى مالك عبد اللَّه بن سام. . وقدم أبو مالك من اليمن فقال: نحن من كندة على دين يهود، فتزوج من بنى قريظه وحالفهم فقيل القرظى. اهـ. وقد ترجم ابن حجر في الإصابة (٤/ ١٧٢) لأبى مالك القرظى والد ثعلبة فقال: ذكره الواقدى وقال: أنه قدم من اليمن وهو على دين اليهودية فتزوج امرأة من قريظة فانتسب فيهم وهو من كندة. وقيل: اسمه عبد اللَّه. . وذكر الحاكم أبو أحمد عن البخارى قال: قال إبراهيم بن المنذر حدثنى اسحاق بن جعفر عمن سمع عبد اللَّه بن جعفر عن يزيد بن الهاد عن ثعلبة ابن أبى مالك أن عمر دعا الاجناد فدعا أبا مالك، قال: ورواه الواقدى عن عثمان بن الضحاك عن ابن الهاد عن ثعلبة أن عمر سأل أبا مالك وكان من علماء اليهود عن صفة النبى -صلى الله عليه وآله وسلم- في التوراة. . .) إلخ اهـ."],[11433,"١٧٩٣ - كنى البخارى (ص ٦٧)، الجرح (٤/ ٢/ ٤٣٥)، المقتنى في سرد الكنى (١٢٣/ ب)."],[11434,"(١) هكذا ذكره ابن عبد البر هنا وكذا هو في مصادر الترجمة."],[11435,"وقال ابن حجر في التهذيب (١١/ ١٠) \"مالك بن ثعلبة بن أبى مالك القرظى ويقال: أبو مالك. روى عن أبيه وعمر بن الحكم بن ثوبان، وعنه ابن إسحاق والوليد بن كثير\" اهـ. وقال في التقريب أيضا (٢/ ٢٢٣) \"مالك بن ثعلبة بن أبى مالك القرظى، ويقال: أبو مالك، مقبول من الخامسة./ د. م."],[11436,"وجاء في سيرة ابن هشام (١/ ٢٧) \"قال ابن اسحاق حدثنى أبو مالك ابن ثعلبة بن أبى مالك القرظى قال: سمعت إبراهيم بن محمد بن طلحة بن عبيد اللَّه يحدث أن تبعا لما دنا من اليمن ليدخلها حالت حمير بينه وبين ذلك، وقالوا لا تدخلها علينا وقد فارقت ديننا. . \" إلخ. قلت: والذى يظهر أن أبا مالك هذا هو حفيد أبى مالك المتقدم). واللَّه أعلم."],[11437,"(٢) عمر بن الحكم بن ثوبان، المدنى، صدوف، من الثالثة، (ت: ١١٧) وله ثمانون سنة./ خت. م. د. س. ق. التقريب ٢/ ٥٣."],[11438,"١٧٩٤ - أبو مالك الأزدى الخزاعى وكان من صالحى الأزد قدم المدينة زمن عثمان. روى قتادة عن صاحب (١) له عنه وعن عمر بن عبد العزيز. روى عنه محمد ابن إسحاق."],[11439,"١٧٩٥ - أبو مالك، روى عن ابن عباس، روى عنه السدى. سئل عنه أبو زرعة فقال \"كوفى ثقة لا أعرف اسمه\"."],[11440,"١٧٩٦ - أبو مالك الأعور، كوفى، عن الحسن بن محمد بن على بن أبى طالب، روى عنه أبو إسحاق السبيعى."],[11441,"١٧٩٧ - أبو مالك الأشعرى، عن محمد بن مزاحم الهلالى أخى الضحاك ابن مزاحم. روى عنه ابن العوام."],[11442,"١٧٩٨ - أبو مالك الصهبانى (٢) عن الحسن بن سعد (٣) عن على رضى اللَّه"],[11443,"١٧٩٤ - لم أقف عليه عند غير المؤلف."],[11444,"(١) صاحب قتادة هو سعيد بن يزيد البصرى، صرح بذلك المزى في تهذيب الكمال ٢/ ١١٢١ في ترجمة قتادة بن دعامة. وانظر أيضًا ترجمة سعيد بن يزيد البصرى في تهذيب الكمال ١/ ٥٠٩ وفى الجرح ٢/ ١/ ٧٤ وقال ابن أبى حاتم: سألت أبى عنه فقال: هو شيخ."],[11445,"١٧٩٥ - الجرح ٤/ ٢/ ٤٣٥ وقال: سئل أبو زرعة عنه فقال: كوفى ثقة، لا أعرف اسمه."],[11446,"١٧٩٦ - المقتنى في سرد الكنى (١٢٣/ ب)."],[11447,"١٧٩٧ - المقتنى في سرد الكنى (١٢٣/ ب) وقال: روى عنه عباد بن العوام."],[11448,"١٧٩٨ - كنى البخارى (ص ٦٨)، الجرح (٤/ ٢/ ٤٣٥)، المقتنى في سرد الكنى (١٢٣/ ب)."],[11449,"(٢) الصّهبانى: بضم الصاد وسكون الهاء وفتح الباء الموحدة وفى آخرها النون. نسبة إلى صهبان بن سعد بن مالك بن النخع، وهو بطن من النخع. اهـ اللباب (٢/ ٢٥٢)."],[11450,"(٣) وفى كنى البخارى أيضا \"عن الحسن بن سعد عن على\" وأما في الجرح \"عن الحسن بن سعد عن مسلم عن على\". ="],[11451,"عنه في الشراب (١). روى عنه عبد الرحيم بن سليمان."],[11452,"١٧٩٩ - أبو مالك الكوفى. روى عن زيد بن وهب. روى عنه عبيدة بن معتب (٢) الضبى."],[11453,"= والحسن بن سعد \"هو كوفى مولى لعلى ويقال مولى الحسن رضي الله عنهما وهو ثقة، من الرابعة./ بخ. م. د. س. ق. التقريب (١/ ١٦٦) التهذيب (٢/ ٢٧٩)."],[11454,"(١) لم أقف على حديث على في الشراب."],[11455,"١٧٩٩ - الجرح (٤/ ٢/ ٤٣٥) وقال: روى عن زيد بن وهب، روى عنه عبيدة الضبى: . . سئل أبو زرعة عنه فقال: لا أعرفه إلا بهذا الحديث."],[11456,"(٢) عبيدة بن معتب، بكسر المثناة الثقيلة بعدها موحدة الضبى، أبو عبد الرحيم الكوفى، الضرير، ضعيف واختلط بآخره، من الثامنة. انظر التقريب: (١/ ٥٤٨)."],[11457,"باب أبى المثنى"],[11458,"١٨٠٠ - أبو المثنى، الجهنى، المدنى، روى عن سعد بن أبى وقاص وأبى سعيد الخدرى، وسمع منهما، روى عنه أيوب بن حبيب (١) مولى سعد بن أبى وقاص، ومحمد بن أبى يحيى الأسلمى، ذكر أبو حاتم الرازى عن إسحاق بن منصور عن يحيى بن معين أنه قال: \"أبو المثنى الذى روى عنه أيوب بن حبيب ثقة\" (٢)."],[11459,"١٨٠١ - أبو المثنى عن أبى ذر، حديثه في المصريين. روى عنه دراج أبو السمح."],[11460,"١٨٠٠ - كنى البخارى (ص ٧٢) كنى مسلم (ص ١٣١)، الثقات (٥/ ٥٦٥) وأيضا في الثقات (٥/ ٥٨٢)، الجرح (٤/ ٢/ ٤٤٤)، الميزان (٤/ ٥٦١)، التقريب (٢/ ٤٦٩) وقال: مقبول، من الثالثة./ ت. ق."],[11461,"(١) في ثقات ابن حبان (٥/ ٥٨٢) \"أيوب بن أبى حبيب مولى سعد بن أبى وقاص\". وقال في التهذيب (١/ ٤٠٠) \"أيوب بن حبيب الزهرى المدنى مولى سعد بن أبى أيوب. . إلخ\". قاله في ترجمة أيوب، وفى الجرح (١/ ١/ ٢٤٤) في ترجمة أيوب بن أبى حاتم \"أيوب بن حبيب المدنى مولى سعد بن أبى وقاص. روى عن أبى المثنى الجهنى. روى عنه مالك بن أنس وفليح بن سليمان. سمعت أبى وأبا زرعة يقولان ذلك\"."],[11462,"(٢) انظر الجر (٤/ ٢/ ٤٤٤)."],[11463,"١٨٠١ - كنى البخارى (ص ٧٢)، الجرح (٤/ ٢/ ٤٤٤)."],[11464,"باب أبى مسلم"],[11465,"١٨٠٢ - أبو مسلم الجليلى. يقال: أنه معلم كعب الأحبار وانه كانت كنيته أبا السمؤل (١) فكناه أبو بكر الصديق أبا مسلم وقد روى حماد بن سلمة عن القاسم الرحال (٢) عن أبى قلابة أن أبا مسلم الجليلى أسلم على عهد معاوية فقال له أبو مسلم الخولانى ما منعك أن تسلم على عهد النبى عليه السلام وأبى بكر وعمر وعثمان حتى أسلمت الآن؟ ."],[11466,"فقال إنى وجدت في التوراة أن هذه الأمة ثلاثة أصناف، صنف يدخل الجنة بغير حساب، وصنف يحاسبون حسابا يسيرا، وصنف يصيبهم شئ ثم يدخلون الجنة فأردت أن أكون من الأولين فان لم أكن من الأولين كنت من الذين يحاسبون حسابا يسيرا. فان لم أكن منهم كنت من الذين يصيبهم شئ ثم يدخلون الجنة (٣)."],[11467,"١٨٠٢ - كنى البخارى (ص ٦٨) الإصابة (٤/ ٣/ ١٩٠) وقال: أبو مسلم الجليلى ويقال: الجلولى، تاريخ ابن معين (٢/ ٧٢٥) وقال: أبو مسلم الجليلى. ويقال: الجلولى، علل أحمد (١/ ٢٠٠)، الجرح (٤/ ٢/ ٤٣٦)، تاريخ دمشق (ل ٦٥٦) المقتنى في سرد الكنى (١٢٧/ ب)."],[11468,"(١) سمؤل: بالسين المهملة وبالهمزة بعد الواو. الاكمال (٤/ ٣٧٠)."],[11469,"(٢) الرحال: في اللباب (٢/ ١٨) الرحال: بفتح الراء والحاء المهملة المشددة وفى آخرها اللام، هذه نسبة إلى المبالغة في الرحلة كثرة الأسفار في طلب الحديث. . ثم قال: وأما القاسم بن يزيد الرحال فمن الرحل، لا من الرحلة يروى عن أنس بن مالك، روى عنه ابن عيينة وحماد بن سلمة، وقال ابن حجر في اللسان (٤/ ٤٦٩): قاسم بن يزيد أبو مالك الرحال. سمع أنسا. روى عنه حماد بن سلمة وسفيان بن عيينة. ثم قال: وقال إسحاق بن منصور عن يحيى بن معين ثقة ولم يذكره ابن ماكولا في الاكمال ولا استدركه عليه ابن نقطة ولا من بعده أهـ كلامه."],[11470,"(٣) أخرجه البغوى من طريق أبى قلابة به. ="],[11471,"١٨٠٣ - أبو مسلم العبدى مولى زيد بن صوحان. روى عن سلمان الفارسى"],[11472,"= وأخرجه تمام في فوائده، وعبد بن حميد في تفسيره من طريق صالح المزى عن أبى عبد اللَّه الشامى عن مكحول عن أبى مسلم الخولانى أنه لقى أبا مسلم الجليلى فذكر الحديث وقال: صالح ضعيف."],[11473,"انظر الإصابة (٤/ ٣/ ١٩٠) في كل ما ذكر."],[11474,"وأخرجه أيضا ابن عساكر من هذا الوجه به انظر التاريخ (ل ٦٥٦) - وأخرجه ابن عساكر أيضا من طريق أبى عبد اللَّه الشامى عن مكحول عن أبى مسلم الخولانى فذكره."],[11475,"وقال المزى في تحفة الاشراف (٤/ ٣٥) رواه عبد السلام بن حرب عن سعيد بن أبى عروبة، عن قتادة. عن أبى شريح - مختصرا. وقال: ليس في السماع ولم يذكره أبو القاسم."],[11476,"وقال ابن حجر في النكت الظراف على تحفة الاشراف: (٤/ ٣٥) قوله: ليس في الرواية يعنى عند \"ق\" ولم يذكره أبو القاسم."],[11477,"قلت: كان ينبغى أن يبين رواية من ذكره عن ابن ماجه. وقد رأيته في رواية سعدون. عن ابن ماجه في نسخة صحيحة مجودة. وفيها عدة أحاديث في الطهارة لم أرها في رواية غيره. وقد تتبعتها في أماكنها بعون اللَّه تعالى. وذكر الحافظ قول ابن أبى حاتم في العلل (١/ ٦٠) حيث قال: سئل أبو زرعة عن حديث رواه أبو غسان النهدى عن عبد السلام بن حرب عن سعيد ابن أبى عروبة عن قتادة عن أبى مسلم عن أبى شريح عن أبى مسلم عن سلمان عن النبى -صلى الله عليه وآله وسلم- في المسح. فقال أبو زرعة: هذا حديث وهم فيه عبد السلام بن حرب. وقال الحافظ ابن حجر: قلت: ووجدت لموسى متابعا من رواية شعيب بن إسحاق، عن شعبة عن داود."],[11478,"والحديث أخرجه ابن عساكر في التاريخ (ل/٦٥٨) به."],[11479,"١٨٠٣ - كنى البخارى (ص ٦٨) تاريخ دمشق (ل/ ٦٥٨)، المقتنى في سرد الكنى (١٢٧/ أ)، الثقات (٥/ ٥٨٤)، الجرح (٤/ ٢/ ٤٣٥) الميزان (٤/ ٥٧٣)، التهذيب (١٢/ ٢٣٦)، التقريب (٢/ ٤٧٣). وقال ابن حجر: مقبول، من الثالثة. ق."],[11480,"أنه رآه يمسح على الخفين (١) وأنه قال: رأيت رسول اللَّه -صلى الله عليه وآله وسلم- يمسح على الخفين (٢) روى عنه أبو شريح (٣)."],[11481,"١٨٠٤ - أبو مسلم الجرمى (٤)، روى عن أبى ذر الغفارى، والجارود (ابن أبى المعلى) (٥)، روى عنه أبو العالية الرياحى، ومطرف بن الشخير."],[11482,"(١) في كنى البخارى زيادة لفظ \"والخمار\"."],[11483,"(٢) الحديث أخرجه البخارى في الكنى وابن أبى حاتم في الجرح، انظر مصادر الترجمة، وأخرجه ابن أبى شيبة في المصنف - كتاب الطهارة (١/ ١٧٨) من طريق يونس عن داود بن أبى الفرات عن محمد بن زيد، عن أبى شريح عن أبى مسلم مولى زيد بن صوحان، قال: كنت مع سلمان فرأى رجلا ينزع خفيه للوضوء فقال له سلمان: امسح على خفيك وعلى خمارك وامسح بناصيتك فانى رأيت رسول اللَّه -صلى الله عليه وآله وسلم- يمسح على الخفين والخمار\"."],[11484,"ومن طريق ابن أبى شيبة أخرجه ابن ماجه في السنن - كتاب الطهارة (١/ ١٨٦)."],[11485,"(٣) أبو شريح. يأتى في (٢٤٨٤)."],[11486,"١٨٠٤ - كنى البخارى (ص ٦٨)، الثقات (٥/ ٥٨١) و(٥٨٧) الجرح: (٤/ ٢/ ٤٣٥)، التهذيب (١٢/ ٢٣٥)، التقريب (٢/ ٤٧٢) وقال: مقبول، من الثالثة./ ت. س."],[11487,"(٤) هكذا في الأصل \"الجرمى\" بالراء المهملة، وفى جميع مصادر الترجمة \"الجذمى\" بالذال المعجمة."],[11488,"وجاء في اللباب (١/ ٢٦٦) \"الجذمى، بفتح الجيم وسكون الذال المعجمة هذه النسبة إلى جذيمة\". اهـ."],[11489,"(٥) هكذا في الأصل \"الجارود بن أبى المعلى\" وفى الجرح الجارود بن المعلى قال الذهبى في تجريد أسماء الصحابة (١/ ٧٤) الجارود بن المعلى أبو المنذر وقيل: أبو غياث وهو أصح وضبطه عبد الغنى أبو عتاب وذكرهما أبو أحمد الحاكم. مختلف في نسبه. وقيل: اسمه بشر بن حنش العبدى، ويقال: إنما لقب جارودا لأنه أغار على بكر بن وائل فأصابهم وجردهم ثم ="],[11490,"١٨٠٥ - أبو مسلم. عن عمر بن الخطاب قوله. روى عبد الوارث بن سعيد العنبرى."],[11491,"١٨٠٦ - أبو مسلم الأغر أصله المدينة، وسكن الكوفة. روى عن أبى هريرة وأبى سعيد. روى عنه أبو إسحاق السبيعى وحبيب بن أبى ثابت."],[11492,"وقد قيل: أبو مسلم الأغر، هو أبو عبد اللَّه الأغر (١)."],[11493,"= قال: وفد سنة عشر في عبد القيس فأسلم وكان نصرانيا ففرج به النبى -صلى الله عليه وآله وسلم- أكرمه. روى عنه من الصحابة عبد اللَّه بن عمرو ومن التابعين مطرف بن عبد اللَّه بن الشخير وزيد بن على أبو القموص وأبو مسلم الجذمى ومحمد بن سيرين مرسلا. اهـ وقال ابن حجر في التقريب (١/ ١٢٤) في ترجمته \"اختلف في اسم أبيه فقيل المعلى أو العلاء. وقيل: عمرو، صحابى جليل استشهد سنة احدى وعشرين."],[11494,"١٨٠٥ - كنى البخارى (ص ٦٨)"],[11495,"١٨٠٦ - كنى مسلم (ص ٩٣٣)، الثقات (٤/ ٥٣)، الطبقات الكبرى (٥/ ٢٨٤)، تهذيب الكمال (١/ ١١٩ - ١٢٠)، التهذيب (١/ ٣٦٥) المقتنى في سرد الكنى (١٢٧/ أ)."],[11496,"قلت: وقد تقدم أبو مسلم الأغر هذا في الكتاب الثانى بنحو ما هنا. انظر الترجمة (٧٩٧) والتعليق عليها."],[11497,"(١) أبو عبد اللَّه الأغر، هو المتقدم في (٩١٧)."],[11498,"قلت: وقد قال ابن حجر في التهذيب (١/ ٣٦٥) في ترجمة الأغر أبى مسلم المدنى، وزعم قوم أنه أبو عبد اللَّه سلمان الأغر، وهو وهم قال: قلت: ومنهم عبد الغنى بن سعيد، وسبقه الطبرانى وزاد الوهم وهما، فزعم أن اسم الأغر مسلم كنيته أبو عبد اللَّه فأخطأ، فان الأغر الذى يكنى أبا عبد اللَّه اسمه سلمان لا مسلم وتفرد بالرواية عنه أهل المدينة، وأما هذا فإنما روى عنه أهل الكوفة، وكأنه اشتبه على الطبرانى بمسلم المدنى شيخ للشعبى، فانه يروى أيضا عن أبى هريرة لكنه لا يلقب بالأغر وأما أبو مسلم هذا فالأغر اسمه لا لقبه. = قيل ذلك: لروايتهما عن أبى هريرة حديث التنزل (١). واللَّه أعلم."],[11499,"وقد قيل: في هذا مسلم وليس بشئ، وصوابه أبو مسلم وهما عندى اسمان، أبو عبد اللَّه مدنى. روى عن جماعة من الصحابة منهم أبو سعيد وأبو هريرة. وأبو مسلم لم يرو إلا عن أبى هريرة وأبى سعيد. ولا يوقف على اسم أبى مسلم هذا ولم يرو عنه غير أبى إسحاق. وقيل وحبيب بن أبى ثابت وهو كوفى. وأما أبو عبد اللَّه فروى عنه الزهرى وابنه عبيد اللَّه وجماعة وهو معدود في أهل المدينة."],[11500,"= وقال أبو بكر بن خزيمة في التوحيد (ص ١٢٦): الحجازيون والعراقيون يختلفون في كنية الأغر يقول الحجازيون: الأغر أبو عبد اللَّه، والعراقيون يقولون أبو مسلم، غير مستنكر أن يكون للرجل كنيتان قد يكون للرجل ابنان أحدهما عبد اللَّه واسم الآخر مسلم فيكون له كنيتان على اسم ابنيه وكذا ذو النورين له كنيتان أبو عمرو، وأبو عبد اللَّه، هذا كثير في الكنى. اهـ."],[11501,"(١) حديث التنزيل وهو قوله -صلى الله عليه وآله وسلم- \"ينزل ربنا تبارك وتعالى في كل ليلة إلى السماء الدنيا، حين يبقى ثلث الليل الآخر، فيقول: من يدعونى فأستجيب له؟ من يسألنى فأعطيه؟ من يستغفرنى فأغفر له؟"],[11502,"أخرجه مالك \"القرآن\" باب ما جاء في الدعاء (١/ ٢١٤) من طريق ابن شهاب عن أبى عبد اللَّه الأغر وعن أبى سلمة بن عبد الرحمن عن أبى هريرة به."],[11503,"ومن طريق مالك أخرجه البخارى \"التهجد\" باب الدعاء والصلاة من آخر الليل (٣/ ٢٩) وفى \"الدعوات\" باب الدعاء نصف الليل (١١/ ١٢٩) وفى \"التوحيد\" (٣/ ٤٦٤) والبخارى أيضا في الأدب المفرد (ص ١٩٦) ومسلم \"صلاة المسافرين\" باب الدعاء والذكر في آخر الليل والاجابة فيه (١/ ٥٢١) وأبو داود \"السنة\" باب في الرد على الجهمية (٤/ ٢٣٤)، وأحمد في المسند (٢/ ٤٨٧)، والبيهقى في الأسماء والصفات (ص ٤٤٩) والبيهقى أيضا في الاعتقاد (ص ٤٣) وابن خزيمة في التوحيد (ص ١٢٧) = ١٨٠٧ - أبو مسلم التغلبى (١). سمع أبا أمامة الباهلى. روى عنه اياد (٢) بن أبى حازم."],[11504,"= و(ص ١٢٨) والبسوى في المعرفة والتاريخ (١/ ٤١٤)."],[11505,"والحديث أخرجه أيضا أحمد (٢/ ٢٦٤ و٢٦٧) والنسائى في عمل اليوم والليلة (٤٨٠). وابن ماجة \"إقامة\" باب ما جاء في أى ساعات الليل أفضل (١/ ٤٣٥)، والدارمى (١/ ٣٤٧) وعبد الرزاق (١٠/ ٤٤٤) وابن خزيمة في التوحيد (ص ١٢٨) و(ص ١٢١) كلهم من طريق ابن شهاب الزهرى عن أبى سلمة بن عبد الرحمن وأبى عبد اللَّه الأغر عن أبى سعيد وأبى هريرة به."],[11506,"وأخرجه أيضا مسلم (١/ ٥٢٣) والبيهقى في الأسماء والصفات (ص ٤٥٠) وعبد الرزاق (١٠/ ٤٤٤) والنسائى في عمل اليوم والليلة (٤٨١) و(٤٨٢) من طريق أبى إسحاق عن الأغر أبى مسلم عن أبى سعيد وأبى هريرة به وأخرجه أيضا مسلم (١/ ٥٢٢) والترمذى (٢/ ٥٢٤) والدارمى (٤٣٦) وأحمد (٢/ ٢٥٨ و٢٨٢ و٤١٩ و٤٣٣ و٥٠٤ و٥٢١) والبيهقى في الأسماء والصفات (ص ٤٤٩) و(ص ٤٥٠) والنسائى في عمل اليوم والليلة (٤٧٦) و(٤٧٧) و(٤٧٨) و) (٤٧٩) و(٤٨٣) و(٤٨٤) و(٤٨٥) و(٤٨٦) وابن خزيمة في التوحيد (ص ١٢٧) و(ص ١٢٩) و(ص ١٣٠) و(ص ١٣١) من غير طريق عن أبى هريرة به. وأخرجه أيضا ابن خزيمة في التوحيد (ص ١٢٧) و(ص ١٣١) من طريق أبى إسحاق وحبيب عن الاغر عن أبى هريرة به مرفوعا."],[11507,"١٨٠٧ - كنى البخارى (ص ٦٨)، الجرح (٤/ ٢/ ٤٣٦)، المقتنى في سرد الكنى (١٢٧/ ب)، تعجيل المنفعة (ص ٣٤٠)."],[11508,"(١) هكذا في الأصل \"التغلبى\" بالتاء الثناه من فوقها وفى مصادر الترجمة \"الثعلبى\" بالثاء المثلثة."],[11509,"(٢) هكذا في الأصل \"اياد بن أبى حازم\" وفى مصادر الترجمة \"ابان بن عبد اللَّه ابن أبى حازم، ولعل الصواب هو كما في مصادر الترجمة، وابان بن عبد اللَّه ابن أبى حازم ينسب أحيانا لجده فيقال: ابان بن أبى حازم. واللَّه أعلم."],[11510,"١٨٠٨ - أبو مسلم البجلى. سمع زيد بن أرقم. روى عنه داود الطفاوى (١)."],[11511,"١٨٠٩ - أبو مسلم، مولى بنى ضمرة (٢)، مدنى، عن أبى هريرة. روى عنه محمد بن أبى يحيى الاسلمى."],[11512,"١٨١٠ - أبو مسلم. روى عن معاوية. روى عنه سعيد بن عبد العزيز."],[11513,"١٨١١ - أبو مسلم عن شعبة. روى عنه عبد اللَّه بن ذكوان."],[11514,"١٨٠٨ - كنى البخارى (ص ٦٨)، الثقات (٥/ ٥٨٤)، الجرح (٤/ ٢/ ٤٣٦) تهذيب الكمال (٣/ ١٦٤٧)، الميزان (٤/ ٥٧٣)، المقتنى في سرد الكنى (١٢٧/ ب) ديوان الضعفاء (ص ٣٦٥) وقال: مجهول، التهذيب (١٢/ ٢٣٥)، التقريب (٢/ ٤٧٢) وقال: مقبول، من الرابعة./ د. س."],[11515,"(١) الطّفاوى في كنى مسلم \"العطّار\" وفى بقية المصادر كما هنا \"الطفاوى\" وهى بضم الطاء وفتح الفاء وبعد الألف واو - نسبة إلى طفاوة، وهى طفاوة بنت جرم بن ريان، نسب إليها أولادها، وهم من أولاد أعصر، انظر اللباب (٢/ ٢٨٣)، وداود الطفاوى هذا هو ابن راشد، يكنى أبا بحر، بصرى لين الحديث من السابعة. انظر التهذيب (٣/ ١٨٣) التقريب (١/ ٢٣١)."],[11516,"١٨٠٩ - كنى البخارى (ص ٦٨)، الجرح (٤/ ٢/ ٤٣٦)."],[11517,"(٢) ضمرة: بفتح الضاد وسكون الميم وفى آخرها راء. اللباب (٢/ ٢٦٤)."],[11518,"١٨١٠ - لم أقف عليه."],[11519,"١٨١١ - لم أقف عليه."],[11520,"باب أبى المنذر"],[11521,"(١)"],[11522,"١٨١٢ - أبو المنذر البرّاد مولى أبى ذر، روى عن أبى ذر وروى عن أبى أمية المخزومى (٢) عن النبى عليه السلام. روى عنه إسحاق بن أبى طلحة."],[11523,"١٨١٣ - أبو المنذر عن أبى أسيد. روى عنه شريك بن عبد اللَّه بن أبى نمر."],[11524,"(١) سيأتى هذا الباب مكررًا بكامله. انظر الترجمتين (١٨٧٣)، (١٨٧٤)."],[11525,"١٨١٢ - كنى البخارى (ص ٧٢)، الجرح (٤/ ٢/ ٤٤٢)، الميزان (٤/ ٥٧٧) تهذيب الكمال (٣/ ١٦٥٠ - ١٦٥١)، التهذيب (١٢/ ٢٤٧)، التقريب (٢/ ٤٧٧) وقال: مقبول، من الثانية./ د. س. ق."],[11526,"(٢) أبو أمية المخزومى تقدم في الصحابة (١٨)."],[11527,"١٨١٣ - كنى البخارى (ص ٧٢)، الجرح (٤/ ٢/ ٤٤٢)."],[11528,"باب أبى المغيرة"],[11529,"١٨١٤ - أبو المغيرة. رأى عمر بن الخطاب. روت عنه ابنته أم حفص (١)."],[11530,"١٨١٥ - أبو المغيرة. روى عن على بن أبى طالب. روى عنه مجاهد بن جبر."],[11531,"١٨١٦ - أبو المغيرة القوّاس، بصرى، عن عبد اللَّه بن عمرو بن العاص. روى عنه عوف الاعرابى."],[11532,"حدثنا عبد الوارث، حدثنا قاسم، حدثنا أبو بكر بن أبى خيثمة، قال: حدثنا إبراهيم بن عرعرة (٢) قال: حدثنا يحيى بن سعيد قال: ضعف سليمان التيمى أبا المغيرة القوّاس (٣). وذكر صالح بن أحمد بن حنبل عن على بن المدينى عن يحيى بن سعيد أنه ضعفه أيضا (٤)."],[11533,"١٨١٤ - كنى البخارى (ص ٧٠)، الجرح (٤/ ٢/ ٤٣٩)."],[11534,"(١) في كنى البخارى \"أم جعفر\". انظر مصادر الترجمة."],[11535,"١٨١٥ - المقتنى في سرد الكنى (١٣٣/ أ)."],[11536,"١٨١٦ - كنى البخارى (ص ٧٠)، الثقات (٥/ ٥٦٥)، الجرح (٤/ ٢/ ٤٣٩) الميزان (٤/ ٥٧٦)، اللسان (٧/ ١٠٩)، المقتنى في سرد الكنى (١٣٣/ أ)."],[11537,"(٢) عرعره: بفتح مهملتين وسكون راء أولى. المغنى (ص ٥٤) وإبراهيم بن عرعرة: هو إبراهيم بن محمد بن عرعرة."],[11538,"(٣) قال ابن أبى حاتم في الجرح (٤/ ٢/ ٤٣٩) \"حدثنا أبو بكر بن أبى خيثمه فيما كتب إلى حدثنا إبراهيم بن عرعرة حدثنا يحيى بن سعيد قال: ضعف سليمان التيمى أبا المغيرة القواس\"."],[11539,"(٤) وقال ابن أبى حاتم أيضا في الجرح (٤/ ٢/ ٤٣٩): حدثنا صالح بن أحمد بن محمد بن حنبل حدثنا على -يعنى ابن المدينى، قال: قلت ليحيى بن سعيد: أبو المغيرة القواس؟ قال: كان اشر عنده -يعنى عند سليمان التيمى- من عبد اللَّه بن شقيق\". اهـ."],[11540,"١٨١٧ - أبو المغيرة. عن أبى هريرة. حدث عنه زياد بن كليب التميمى (١)."],[11541,"١٨١٨ - أبو المغيرة الخصاف (٢). قال: سألت ابن عباس. روى عنه عاصم ابن سليمان الأحول."],[11542,"١٨١٩ - أبو المغيرة، عن أبى هريرة في الضيافة (٣). روى عنه معاوية بن صالح."],[11543,"١٨١٧ - المقتنى في سرد الكنى (١٣٣/ أ)."],[11544,"(١) هو أبو معشر تقدم في (٨١٩)."],[11545,"١٨١٨ - كنى البخارى (ص ٧٠)، الجرح (٤/ ٢/ ٤٣٩)."],[11546,"(٢) في كنى البخارى \"الخفاف\" بالفاء المعجمة."],[11547,"١٨١٩ - كنى البخارى (ص ٧٠) وجعله هو وصاحب الترجمة الآتية واحدا، الجرح (٤/ ٢/ ٤٤٠) وذكره كما هنا. وقال: حديثه مرسل."],[11548,"(٣) الحديث لم أقف عليه من هذا الطريق. وقد أخرج أحمد في المسند (٢/ ٣٥٤ و٤٣١ و٥٣٤) والبخارى \"الأدب\" باب من كان يؤمن باللَّه واليوم الآخر فلا يؤذ جاره (١٠/ ٤٤٥) وباب اكرام الضيف (١٠/ ٥٣٢) وفى كتاب الرقاق باب حفظ اللسان (١١/ ٣٠٨)."],[11549,"ومسلم \"الايمان\" باب الحث على اكرام الجار والضيف (١/ ٦٨) وأبو داود \"الأطعمة\" (٣/ ٣٤٢) والبخارى في الأدب المفرد (ص ١٩٣) حديث أبى هريرة بطرق عنه مرفوعا. ومن ألفاظه \"الضيافة ثلاثة أيام فما سوى ذلك فهو صدقة\" وفى بعض الألفاظ أيضا \"من كان يؤمن باللَّه واليوم الاخر فلا يؤذ جاره، من كان يؤمن باللَّه واليوم الاخر فليكرم ضيفه\" وذكر الهيثمى في مجمع الزوائد (٨/ ١٧٥) حديث أبى هريرة هذا وعزاه لأبى يعلى والبزار وقال: فيه ليث بن أبى سليم وهو مدلس وبقية رجاله ثقات فلعل هذا الحديث هو الحديث المشار إليه في هذه الترجمة واللَّه أعلم."],[11550,"١٨٢٠ - أبو المغيرة، عن سليمان بن موسى. روى عنه معاوية بن صالح. قيل هو الذى قبله."],[11551,"١٨٢١ - أبو المغيرة قال: قال كعب الأحبار لأبى مسلم."],[11552,"\"ان في التوراة\" (١) حديثه عند موسى بن إسماعيل عن أبى هلال (٢) عنه."],[11553,"١٨٢٢ - أبو المغيرة. قال: كنت مؤذنا ببخارى ثلاثين سنة. وقال: سألت الحسن وابن سيرين وقتادة عن الاذان. (روى عنه الفضل بن موسى السينانى) (٣)."],[11554,"١٨٢٣ - (أبو المغيرة. روى عن أبيه (٤) عن أبى برزه) (٥). روى عنه حماد بن سلمة."],[11555,"١٨٢٤ - أبو المغيرة الذهلى، كوفى، سمع فلفله (٦) بن عبد اللَّه الجعفى. روى عنه فضيل بن غزوان."],[11556,"١٨٢٠ - الجرح (٤/ ٢/ ٤٤٠)."],[11557,"١٨٢١ - كنى البخارى (ص ٧٠)، الجرح (٤/ ٢/ ٤٣٩)، المقتنى في سرد الكنى (١٣٣/ أ)."],[11558,"(١) انظر كنى البخارى (ص ٧٠)، الجرح (٤/ ٢/ ٤٣٩) واللفظ هناك \"في التوراة أزهد الناس في العالم جاره\"."],[11559,"(٢) أبو هلال: هو الراسبى واسمه محمد بن سليم."],[11560,"١٨٢٢ - كنى البخارى (ص ٧٠)، الجرح (٤/ ٢/ ٤٤٠)."],[11561,"(٣) الحق في هامش الأصل."],[11562,"١٨٢٣ - الجرح (٤/ ٢/ ٤٤٠) وقال: سئل أبو زرعة عنه فقال: لا يسمى ولا أعرفه."],[11563,"(٤) لم أقف على من سماه."],[11564,"(٥) الحق في هامش الأصل."],[11565,"١٨٢٤ - المقتنى في سرد الكنى (١٣٣/ أ)."],[11566,"(٦) فلفلة بن عبد اللَّه الجعفى، الكوفى، مقبول، من الثانية. التقريب (٢/ ١١٤)."],[11567,"باب أبى مصعب"],[11568,"١٨٢٥ - أبو مصعب، رأى جابر بن عبد اللَّه الأنصارى، روى عنه اشعث ابن سليم المحاربى (١)."],[11569,"١٨٢٦ - أبو مصعب المكى. أدرك زيد بن ارقم. وروى عن أنس بن مالك \"حديث الغار\" (٢)."],[11570,"١٨٢٥ - كنى البخارى (ص ٧١)، الجرح (٤/ ٢/ ٤٤١)."],[11571,"(١) هو أشعث بن أبى الشعثاء."],[11572,"١٨٢٦ - الجرح (٤/ ٢/ ٤٤١)، الميزان (٣/ ٣٠٧)، المقتنى في سرد الكنى (١٢٨/ ب) وقال: خبره منكر، العقد الثمين (٨/ ١٠٢)، اللسان (٧/ ١٠٦)."],[11573,"(٢) الحديث أخرجه الذهبى في الميزان (٣/ ٣٠٨) وتبعه ابن حجر في اللسان (٧/ ١٠٦) في ترجمة عون بن عمرو القيسى. راوى الحديث عن أبى مصعب المكى. وأخرجه الحافظ ابم نعيم في دلائل النبوة (ص ٢٦٩)، وابن سعد في الطبقات الكبرى (١/ ٢٢٩)، والبيهقى في دلائل النبوة (٢/ ٢١٤)، والبزار كما في كشف الاستار (٢/ ٢٩٩) والعقيلى في الضعفاء (٣/ ١٤٤٥ - ١٤٤٦) والحافظ ابن كثير في السيرة النبوية (٢/ ٢٤٠)، والسيوطى في الدر المنثور (٣/ ٢٤٢) ونسبه إلى ابن سعد وابن مردويه. وذكره أيضا الهيثمى في مجمع الزوائد (٦/ ٥٢ - ٥٣) إلى البزار، والطبرانى. وقال الهيثمى: فيه جماعة لم أعرفهم. كلهم أخرجوه من طريق عون بن عمرو القيسى، قال: حدثنى أبو مصعب المكى قال: ادركت زيد بن ارقم والمغيرة بن شعبة، وأنس ابن مالك يحدثون أن النبى -صلى الله عليه وآله وسلم- لما كان ليلة بات في الغار أمر اللَّه تبارك وتعالى شجرة فنبتت في وجه الغار فسترت وجه النبى -صلى الله عليه وآله وسلم-، وامر اللَّه تبارك وتعالى حمامتين وحشيتين فوقفتا بفم الغار. . \" الحديث وهو طويل. قال البزار: لا نعلم رواه إلا عون بن عمير - هكذا هو في مطبوعة كشف ="],[11574,"وروى عن المغيرة بن (شعبة) (١) الثقفى. روى عنه عون بن أبى عمر القيسى أو عمرو بن عون القيسى (٢)."],[11575,"١٨٢٧ - أبو مصعب الأنصارى، روى حديثا مرسلا. روى عنه عبد الحميد ابن جعفر الأنصارى."],[11576,"= الاستار عون بن عمير وهو خطأ والصواب عون بن عمرو. واللَّه أعلم -وهو بصرى مشهور. وأبو مصعب فلا نعلم حدث عنه إلا عوين- وكان عوين ورباح أخوين أهـ."],[11577,"قلت: وعوين هو لقب عون بن عمرو القيسى."],[11578,"وقال الحافظ ابن كثير بعد أن ذكر الحديث في السيرة: هو حديث غريب جدا من هذا الوجه. اهـ. وقال العقيلى بعد أن ذكر هذا الحديث في ترجمة عون بن عمرو: لا يتابع عليه وأبو مصعب رجل مجهول اهـ."],[11579,"(١) في الأصل \"سعيد\" وهو تحريف، والصواب ما أثبته فقد جاء في اللسان (٤/ ٣٨٨) في ترجمة عون بن عمرو أن أبا مصعب المكى قال: ادركت زيد بن أرقم وأنسا، والمغيرة بن شعبة قال: وسمعتهم يتحدثون أن النبى -صلى الله عليه وآله وسلم-. . وذكر حديث الغار."],[11580,"(٢) القيسى: بفتح القاف وسكون الياء تحتها نقطتان وفتح السين المهملة والراء وبعد الألف نون. اللباب (٣/ ٦٩). وجاء في الجرح (٣/ ١/ ٣٨٦) عون بن عمرو القيسى أخو رباح بن عمرو الزاهد، روى عن سعيد الجريرى، روى عنه مسلم بن إبراهيم وإسماعيل بن سيف. . . قال ابن أبى حاتم: ذكره أبى عن إسحاق بن منصور عن يحيى بن معين أنه قال: عون بن عمرو القيسى لا شئ، وقال ابن أبى حاتم أيضا سألت أبى عن عون بن عمرو فقال: شيخ. وفى اللسان (٤/ ٣٨٨) \"عون بن عمرو، ويقال: عوين بالتصغير\"."],[11581,"١٨٢٧ - كنى البخارى (ص ٧١)، الجرح (٤/ ٢/ ٤٤١)، اللسان (٧/ ١٠٦) المقتنى في سرد الكنى (١٢٨/ ب) وقال: ارسل عنه عبد الحميد بن جعفر."],[11582,"قال ابن حجر \"أبو مصعب الأنصارى مجهول لا يعرف اسمه ارسل هذا الخبر المنكر قال مسدد في مسنده: أخبرنا عيسى بن يونس ثنا عبد الحميد = ١٨٢٨ - أبو مصعب الجهنى، عن أبى هريرة، روى عنه سعيد بن اياس الجريرى، وقتادة ويونس بن عبيد، وحاتم بن أبى صغيرة (١)."],[11583,"= ابن جعفر، ثنا أبو مصعب الأنصارى أن رسول اللَّه -صلى الله عليه وآله وسلم- قال: اطلبوا الخير إلى حسان الوجوه. قال أبو نعيم في معرفة الصحابة: وأبو مصعب مختلف في صحبته. قال ابن حجر: لو كان صحابيا لكان هذا الخبر صحيحا لصحة اسناده إليه وقد حكم ائمة الحديث بأن هذا المتن باطل فوجب الحكم بأنه غير صحابى وهو غير معروف في التابعين أيضا\" اهـ."],[11584,"١٨٢٨ - الثقات (٥/ ٥٨٣)، المقتنى في سرد الكنى (١٢٨/ ب)."],[11585,"(١) حاتم بن أبى صغيرة، بكسر الغين المعجمة، أبو يونس البصرى وأبو صغيرة. اسمه مسلم، وهو جده لأمه. وقيل: زوج أمه، ثقة، من السادسة./ ع. التقريب (١/ ١٣٧)."],[11586,"باب أبى مروان"],[11587,"١٨٢٩ - أبو مروان الأسلمى، مدنى، عن أبى ذر كعب (١) الأحبار، روى عنه ابنه عطاء بن أبى مروان الأسلمى (٢)."],[11588,"١٨٣٠ - أبو مروان، عن أبى، ظبية، عن عبد اللَّه بن عمر، روى عنه حفص ابن ميسرة الصنعانى (٣)."],[11589,"١٨٢٩ - كنى البخارى (ص ٧٤)، الثقات (٥/ ٥٨٥)، الثقات (٧/ ٦٥٩)، المقتنى في سرد الكنى (١٢٦/ أ)، الجرح (٤/ ٢/ ٤٤٥)، الميزان (٤/ ٥٧٢)، جامع التحصيل في أحكام المراسيل (ص ٣٩٠)."],[11590,"ذكره ابن حبان في موضعين من الثقات فقال في الموضع الأول: \"أبو مروان الاسلمى يروى عن أبى ذر، روى عنه ابنه عطاء بن أبى مروان\"."],[11591,"وقال في الموضع الثانى: \"أبو مروان يروى عن كعب، روى عنه ابنه عطاء بن أبى مروان\". وسيأتى في ترجمة ابنه عطاء أن ابن حجر قال اسم أبيه سعيد. وقيل: عبد الرحمن. فاللَّه أعلم."],[11592,"(١) في كنى البخارى: \"عن أبى ذر عن كعب الاحبار\" وفى الجرح \"أبو مروان الاسلمى سمع اباه عن كعب الاحبار\". وقد تقدم التنبيه على ذكر ابن حبان له في موضعين، وذكر في الموضوع الأول أنه روى عن أبى ذر، وفى الموضع الثانى \"روى عن كعب\" واللَّه أعلم."],[11593,"(٢) مدنى نزل الكوفة ويكنى بأبى مصعب، اسم أبيه سعيد وقيل: عبد الرحمن ثقة، من السادسة./س. التقريب (٢/ ٢٢)."],[11594,"١٨٣٠ - المقتنى في سرد الكنى (١٢٦/ أ)."],[11595,"(٣) ثقة ربما وهم، من الثامنة (ت: ١٨١). انظر التقريب (١/ ١٨٩) والصنعانى: بفتح الصاد وسكون النون وفتح العين المهملة وفى آخرها نون - هذه النسبة ="],[11596,". . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . ."],[11597,"= إلى صنعاء، وهى مدينة باليمن مشهورة. انظر اللباب (٢/ ٢٤٨) وفى مراصد الاطلاع (٢/ ٨٥٣): كان اسمها قديما أزال فلما وافتها الحبشة ورأوها حصينة قالوا صنعاء، معناه حصينة. فسميت صنعاء بذلك وهى قصبة اليمن واحسن بلادها. اهـ."],[11598,"باب أبى معمر"],[11599,"١٨٣١ - أبو معمر التميمى، رأى أبا الشعثاء جابر بن زيد، روى عنه غالب ابن سليمان (١)."],[11600,"١٨٣٢ - أبو معمر السّرَاج، سمع الحسن، روى عنه موسى بن إسماعيل. قال البخارى: وخليقا أن يكون هذا هو الذى تقدم ذكره قبل (٢)، قال البخارى وخليقا أيضا أن يكون أبو معمر السّرّاج هذا حفص بن أبى حفص الذى روى عن شهر بن حوشب (٣)."],[11601,"١٨٣١ - كنى البخارى (ص ٧١)، الثقات (٧/ ٦٦٥)، الجرح (٤/ ٢/ ٤٤٢)."],[11602,"(١) غالب بن سليمان العتكى، أبو صالح أو أبو سلمة الخراسانى، أصله من البصرة، ثقة، من السابعة التقريب (٢/ ١٠٤)."],[11603,"١٨٢٣ - كنى البخارى (ص ٧١)، الثقات (٧/ ٦٦٤)، الجرح (٤/ ٢/ ٤٤٢)."],[11604,"(٢) و(٣) قلت: الذى في كنى البخارى: \"أبو معمر السّرّاج، سمع الحسن روى عنه موسى بن إسماعيل\". اهـ. وانظر ترجمة حفص بن أبى حفص في التاريخ الكبير (١/ ٢/ ٣٦٨) وذكر البخارى في ترجمته هناك أنه روى عن شهر بن حوشب وسمع منه العقدى، وأبو الوليد وموسى بن إسماعيل بن وقال أيضا: وهو أبو معمر كناه موسى، يقال: التميمى، وقال سكن بن سليمان: حدثنا حفص بن سليمان، عن شهر بن حوشب، وهو حفص بن أبى حفص اهـ."],[11605,"باب أبى منصور"],[11606,"١٨٣٣ - أبو منصور مولى سليم (١)، روى عن ابن عباس. روى عنه عاصم ابن سليمان الأحول."],[11607,"١٨٣٤ - أبو منصور. مولى ابن عباس. روى عنه عزوة بن أبى قيس (٢)."],[11608,"١٨٣٥ - أبو منصور، عن أبى هريرة، روى عنه ابنه يزيد (٣)، يعد في البصريين."],[11609,"١٨٣٦ - أبو منصور، قاضى افريقية، روى حديثا مرسلا عن النبى عليه السلام من حديث سعيد بن أبى أيوب، عن عبد اللَّه بن الوليد عنه."],[11610,"١٨٣٧ - أبو منصور الفارسى، روى عن النبى عليه السلام حديثا مرسلا،"],[11611,"١٨٣٣ - كنى البخارى (ص ٧١)، الجرح (٤/ ٢/ ٤٤١)، المقتنى في سرد الكنى (١٣٤/ ب) وقال: أبو منصور مولى سليم عن ابن عباس وعنه عاصم الأحول."],[11612,"(١) في كنى البخارى \"مولى سليمان بن عباس\"."],[11613,"١٨٣٤ - كنى البخارى (ص ٧١)، الجرح (٤/ ٢/ ٤٤١)، المقتنى في سرد الكنى (١٣٤/ ب)."],[11614,"(٢) انظر ترجمته في الجرح (٣/ ١/ ٣٩٧)، اللسان (٤/ ١٦٤)."],[11615,"١٨٣٥ - المقتنى في سرد الكنى (١٣٤/ ب)."],[11616,"(٣) يزيد بن أبى منصور الأزدى، أبو روح البصرى، لا بأس به من الخامسة، ووهم من ذكره في الصحابة. التقريب (٢/ ٣٧١)."],[11617,"١٨٣٦ - كنى البخارى (ص ٧١)، الجرح (٤/ ٢/ ٤٤١). المقتنى في سرد الكنى (١٣٤/ ب)."],[11618,"١٨٣٧ - كنى البخارى (ص ٧١)، الجرح (٤/ ٢/ ٤٤١)، المقتنى في سرد الكنى (١٣٤/ ب)."],[11619,"قلت: وقد تقدم أبو منصور الفارسى في الصحابة وذكر ابن عبد البر في ="],[11620,"روى عنه ذويد (١) بن نافع."],[11621,"١٨٣٨ - أبو منصور، عن عمرو بن قيس الكندى (٢). روى عنه أصحاب يزيد بن عبد ربه (٣)."],[11622,"١٨٣٩ - أبو منصور، روى عن أنس بن مالك عن النبى -صلى الله عليه وآله وسلم- أنه قال: \"ان لى عليكم حقا وللأئمة من قريش من بعدى -ما أقاموا ثلاثا، إذا حكموا عدلوا وإذا استرحموا رحموا وإذا عاهدوا وفوا- الحديث\" (٤). روى عنه موسى الجهنى."],[11623,"= ترجمته هناك حديثا له. وقال قد قيل في حديثه أنه مرسل ولا صحبة له واللَّه أعلم."],[11624,"(١) في المقتنى \"دريد\"."],[11625,"١٨٣٨ - المقتنى في سرد الكنى (١٣٤/ ب)."],[11626,"(٢) عمرو بن قيس الكندى، أبو ثور الحمصى، ثقة، من الثالثة (ت: ١٤٠). التقريب: (٢/ ٧٧)."],[11627,"(٣) حمصى، ثقة، من العاشرة (ت: ٢٢٤). التقريب (٢/ ٣٦٧)."],[11628,"١٨٣٩ - الجرح (٤/ ٢/ ٤٤١)."],[11629,"(٤) الحديث لم أقف عليه من هذا الطريق. لكن أخرجه البزار. كما في كشف الأستار (٢/ ٢٢٨) وأحمد في المسند (٣/ ١٢٩) و(١٨٣) من حديث أنس رضي الله عنه يرفعه وفيه \"الأئمة من قريش ولهم عليكم حق ولكم مثل ذلك ما إذا استرحموا رحموا، وإذا حكموا عدلوا وإذا عاهدوا وفوا فمن لم يفعل ذلك منهم فعليه لعنة اللَّه والملائكة والناس أجمعين\" هذا لفظ أحمد. والبزار بنحوه."],[11630,"وعزاه الهيثمى في مجمع الزوائد (٥/ ١٩٢) و(١٩٤) إلى أحمد والطبرانى في الكبير والأوسط وأبى يعلى والبزار. وقال: رجال أحمد ثقات."],[11631,"وفيه عند الطبرانى عبد اللَّه بن فروخ وثقه ابن حبان وقال: ربما خالف وفيه كلام، وبقية رجال الكبير ثقات، وأخرجه عبد الرزاق في المصنف (١١/ ٥٧) وابن حبان في الصحيح كما في موارد الظمآن (ص ٣٦٩)، وأحمد في = . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . ."],[11632,"= المسند (٢/ ٢٧٠) من حديث أبى هريرة رضي الله عنه به، وقال الهيثمى في مجمع الزوائد (٥/ ١٩٢) رواه أحمد والطبرانى في الأوسط ورجال أحمد رجال الصحيح. اهـ. وأخرجه البزار بنحوه من حديث أبى موسى. انظر كشف الأستار (٢/ ٢٢٩)."],[11633,"ومن حديث أبى برزة الأسلمى برواية سكين بن عبد العزيز عن سيار بن سلامة عنه أخرجه أحمد (٤/ ٤٢١)."],[11634,"والبزار كما في كشف الأستار (٢/ ٢٣٠) بنحو حديث أنس رضي الله عنه وقال: لا نعلمه عن أبى برزة إلا بهذا الاسناد، وسكين بصرى مشهور. أهـ. وقال الهيثمى في مجمع الزوائد (٥/ ١٩٣) بعد أن ذكر حديث أبى برزة: رواه أحمد وأبو يعلى أتم منه وفيه قصة والبزار، ورجال أحمد رجال الصحيح خلا سكين بن عبد العزيز وهو ثقة. اهـ."],[11635,"باب أبى المعتمر"],[11636,"١٨٤٠ - أبو المعتمر بن عمرو بن رافع مدنى، روى عن أبى خلدة (١) عمر ابن خلدة الزرقى، قاضى المدينة، وعن عبيد اللَّه بن على بن أبى رافع (٢)، روى عنه ابن أبى ذئب، وروى (يزيد) (٣) بن أبى حكيم العدنى عن الثورى، عن الصلت بن بهرام، عن أبى المعتمر، وأبى الجويرية (٤)، عن على رضي الله عنه، أنه"],[11637,"١٨٤٠ - كنى البخارى (ص ٧٣)، الثقات (٧/ ٦٦٣) الجرح (٤/ ٢/ ٤٤٣)، الميزان (٤/ ٥٧٥)، تهذيب الكمال (٣/ ١٦٤٩)، التهذيب، (١٢/ ٢٤١)، التقريب (٢/ ٤٧٤) وقال مجهول الحال، من السادسة./ د. ق."],[11638,"قال ابن حجر، التهذيب (١٢/ ٢٤١): قال ابن عبد البر: ليس بمعروف بحمل العلم."],[11639,"(١) خلدة: بفتح المعجمة وسكون اللام، وعمر بن خلدة هذا ثقة من الثالثة./ د. ق، التقريب (٢/ ٥٤)."],[11640,"(٢) يعرف بعبادل، ويقال فيه على بن عبيد اللَّه، لين الحديث، من السادسة/ د. ت. ق. التقريب (١/ ٥٣٧)."],[11641,"(٣) في الأصل \"مرثد\" وهو تصحيف، والتصحيح عن الجرح."],[11642,"وقال ابن حجر في التقريب (٢/ ٣٦٣) \"يزيد بن أبى حكيم العدنى، أبو عبد اللَّه صدوق، من التاسعة."],[11643,"والعدنى: بفتح العين والدال المهملتين وفى آخرها النون. هذه النسبة إلى عدن، وهى مدينة باليمن. انظر اللباب (٢/ ٣٢٨)."],[11644,"(٤) هو العبدى تقدم في (٥٤٢)."],[11645,"قال: لا تأتوا النساء في أعجازهن (١). ورويا عنه سؤال ابن الكوا (٢) اياه."],[11646,"(١) الأثر: أخرجه ابن أبى شيبة في المصنف (٤/ ٢٥٣) من طريق ابن نمير عن الصلت بن بهرام عن عبد الرحمن بن مسعود عن أبى المعتمر أو إلى الجويرية قال: نادى على على المنبر فقال: سلونى فقال رجل: أتؤنى النساء في أدبارهن؟ فقال: سفلت سفل اللَّه بك. أن اللَّه تعالى يقول: ﴿أَتَأْتُونَ الْفَاحِشَةَ - الآية﴾ وأخرجه أيضا البيهقى (٧/ ١٩٨) من طريق سفيان عن الصلت بن بهرام عن أبى المعتمر عن أبى الجويرية قال: سأل رجل عليا رضي الله عنه عن ذلك فقال: سفلت سفل اللَّه بك أما سعت اللَّه يقول: ﴿أَتَأْتُونَ الْفَاحِشَةَ مَا سَبَقَكُمْ بِهَا مِنْ أَحَدٍ مِنَ الْعَالَمِينَ﴾ قال: والصواب عن الصلت ابن بهرام عن أبى الجويرية وهو عبد الرحمن بن مسعود العبدى عن أبى المعتمر قال: سأل رجل عليا رضي الله عنه وهو على المنبر عن اتيان النساء في أدبارهن -فذكره. وقال البيهقى: وكذلك رواه أبو أسامة وغيره عن الصلت بن بهرام عن عبد الرحمن بن مسعود العبدى، عن أبى المعتمر به."],[11647,"وأخرج أحمد في المسند (١/ ٨٦) الحديث عن على رضي الله عنه مرفوعا إلى النبى -صلى الله عليه وآله وسلم- وفيه لفظ \"لا تأتوا النساء في أعجازهن -وقال مرة \"في أدبارهن\"."],[11648,"وقال الهيثمى \"في مجمع الزوائد (٤/ ٢٩٨) بعد أن عزاه لأحمد: ورجاله ثقات. قلت: وانظر الترجمة (٤٥٧) حيث تقدم كلام العلماء في الآية ﴿نِسَاؤُكُمْ حَرْثٌ لَكُمْ﴾."],[11649,"(٢) ابن الكواء: هو عبد اللَّه بن الكواء من بنى يشكر كان من أصحاب على رضي الله عنه، وكان يلزمه ويعييه في الأسألة، ثم خرج مع الخوارج على على رضي الله عنه ونزلوا حروراء وكان هو من رؤسائهم ثم رجع عن مذهب الخوارج وعاود صحبة على رضي الله عنه."],[11650,"قال البخارى: لم يصح حديثه. انظر ترجمته في الفرق بين الفرق (ص ٧٥)، اللسان (٣/ ٣٢٩)"],[11651,"١٨٤١ - أبو المعتمر، روى عن رجل (١) عن على وربما ارسل عن على. روى عنه ابنه حفص (٢)."],[11652,"١٨٤١ - كنى البخارى (ص ٧٣)، الجرح (٤/ ٢/ ٤٤٣)، جامع التحصيل (ص ٣٩١)، المراسيل لابن أبى حاتم (ص ٢٥٩) وقال: أبو المعتمر عن على مرسل."],[11653,"(١) هكذا ذكر هنا مبهما، وكذا في مصادر الترجمة. ولم أقف على من سماه."],[11654,"(٢) في الجرح (١/ ٢/ ١٨٧) \"حفص بن المعتمر المدينى، ويقال: ابن أبى المعتمر روى عن أبيه، روى عنه عبيد اللَّه بن عبد الرحمن بن موهب\" اهـ."],[11655,"باب أبى المعلى"],[11656,"١٨٤٢ - أبو المعلّى (١) بن رؤبة كذا قال: البخارى (٢). وقال أبو حاتم: الرازى (٣): إنما هو المعلّى بن رؤبه، وهو شامى يروى عن ابن لعبد اللَّه بن الزبير (٤). روى عنه الزهرى وأرطأة بن المنذر."],[11657,"وقال أبو أحمد الحاكم: أبو المعلى بن رؤبة أراه الذى يروى عن إبراهيم النخعى عن علقمة وعبيدة. روى عنه إسماعيل بن علية قال: وقد روى يونس بن يزيد الأيلى (٥) عن ابن شهاب قال: حدثنى المعلى بن رؤبة التميمى. عن (هشام) (٦) بن عبد اللَّه بن الزبير عن عمر قال: فلا أدرى أهو الأول أم هما اثنان؟ ."],[11658,"١٨٤٢ - كنى البخارى (ص ٧٣)، الجرح (٤/ ٢/ ٤٤٣)، المقتنى في سرد الكنى (١٣١/ ب)."],[11659,"(١) المعلى: بمضمومة وفتح لام مشددة. المغنى (ص ٧٣)."],[11660,"(٢) الكنى (ص ٧٣)."],[11661,"(٣) الجرح (٤/ ٢/ ٤٤٣)."],[11662,"(٤) هو هشام بن عبد اللَّه بن الزبير. كما سيأتى في آخر هذه الترجمة."],[11663,"(٥) الأيلى: بفتح الألف وسكون الياء المنقوطة باثنتين من تحتها وفى آخرها اللام هذه بلدة على ساحل القلزم مما يلى ديار مصر، خرج منها جماعة من العلماء في كل فن، منهم يونس بن يزيد الأيلى صاحب الزهرى. اهـ."],[11664,"اللباب (١/ ٩٨) وقال ابن حجر في التقريب (٢/ ٣٨٦) \"ثقة إلا أن في روايته عن الزهرى وهما قليلا وفى غير الزهرى خطأ، من كبار السابعة (ت: ١٥٩)."],[11665,"(٦) في الأصل \"هشام\" والصواب ما أثبته بدليل ما ذكره البخارى في التاريخ الكبير (٤/ ٢/ ٢٣٥) قال: هاشم بن عبد اللَّه بن الزبير أن عمر بن الخطاب ="],[11666,"قال أبو عمر: هما اثنان المعلّى وأبو المعلّى على ما حكى أبو حاتم الرازى. واللَّه أعلم."],[11667,"١٨٤٣ - أبو المعلّى، عن الحكم بن عمرو الغفارى، روى عنه جميل بن عبيد الطائى (١)."],[11668,"= أصابته مصيبة فأتى رسول اللَّه -صلى الله عليه وآله وسلم-. . عن ابن شهاب قال: حدثنى المعلى ابن رؤبة عن هاشم. اهـ. وذكره أيضا ابن أبى حاتم في الجرح (٤/ ٢/ ١٠٤) فقال: هاشم بن عبد اللَّه بن الزبير روى عن عمر رضي الله عنه مرسل، روى عنه المعلى بن رؤبة. . \" وذكر ابن حبان في الثقات (٥/ ٥١٣) فقال: هاشم ابن عبد اللَّه بن الزبير وذكر روايته عن عمر ورواية: المعلى بن رؤبة عنه، وذكره أيضا ابن سعد في الطبقات الكبرى فقال: هاشم بن عبد اللَّه بن الزبير بن العوام. انظر طبقات ابن سعد - القسم المخطوط (١٥)، وذكر مصعب الزبيرى في نسب قريش (ص ٢٣٦ - ٢٤٣) وتبعه الزبير بن بكار في جمهرة نسب قريش وأخبارها (ص ٣٢ - ٣٥) عبد اللَّه بن الزبير وأولاده فذكرا فيهم هاشم بن عبد اللَّه بن الزبير. ولم يذكرا فيهم من اسمه هشام بن عبد اللَّه. واللَّه أعلم."],[11669,"١٨٤٣ - المقتنى في سرد الكنى (١٣١/ ب)."],[11670,"(١) جميل بن عبيد الطائى: قال ابن أبى حاتم: ذكره أبى عن إسحاق بن منصور عن يحيى بن معين قال: جميل بن عبيد الطائى ثقة. اهـ. الجرح (١/ ١/ ٥١٩)."],[11671,"باب أبى معن"],[11672,"١٨٤٤ - أبو معن البصرى، عن عبد اللَّه بن عمر، وعبد اللَّه بن الزبيير، وأنس ابن مالك، وأبى العالية (١)، وجابر بن زيد، روى عنه معتمر بن سليمان التيمى. قال يحيى بن معين: \"أبو معن هذا شيخ بصرى\" (٢)."],[11673,"١٨٤٥ - أبو معن، عن محمد بن سيرين، روى عنه مسعدة."],[11674,"١٨٤٦ - أبو معن، عن أبى عقيل (٣)، عن أبى صالح (٤)، روى عنه عبد اللَّه ابن المبارك."],[11675,"١٨٤٤ - كنى البخارى (ص ٧٠)، الثقات (٥/ ٥٧٦)، الثقات (٧/ ٦٦٤) الجرح (٤/ ٢/ ٤٤٠)."],[11676,"ذكره ابن حبان في موضعين في الثقات فقال في الموضوع الأول: \"أبو معن يروى عن ابن عمر، روى عنه المعتمر بن سليمان\" الخ. وقال مرة أخرى في موضع آخر: \"أبو معن يروى عن جابر بن زيد، روى عنه المعتمر بن سليمان. . \" الخ. والذى يظهر أن الترجمتين لرجل واحد واللَّه أعلم."],[11677,"(١) هو الرياحى."],[11678,"(٢) لم أقف على قول ابن معين هذا عند غير ابن عبد البر."],[11679,"١٨٤٥ - كنى البخارى (ص ٧١)، الجرح (٤/ ٢/ ٤٤١)، المقتنى في سرد الكنى (١٢٣/ أ)."],[11680,"١٨٤٦ - كنى البخارى (ص ٧١)، المقتنى في سرد الكنى (١٣٢/ أ)."],[11681,"(٣) أبو عقيل: سيأتى في (٢١٧٩) وذكر ابن عبد البر في ترجمته هناك أنه روى عنه أبو معن غير منسوب ولا مسمى."],[11682,"(٤) أبو صالح: قال البخارى: أظنه مولى عثمان بن عفان. انظر الترجمة (٢١٧٩) قلت: وانظر ترجمة أبى صالح مولى عثمان بن عفان في (٨٩٧) و(١٩٥٦)."],[11683,"باب أبى المنهال"],[11684,"١٨٤٧ - أبو المنهال (١) العترى (٢)، بصرى، سأل ابن عباس. روى عنه أبو التّيّاح يزيد بن حميد."],[11685,"١٨٤٨ - أبو المنهال، عن أبى هريرة، روى عنه إسماعيل بن عبد الرحمن السّدّى (٣)."],[11686,"١٨٤٩ - أبو المنهال، مولى ابن أبى بكرة، روى عن عبد العزيز بن أبى بكرة، روى عنه سلم بن قتيبة."],[11687,"١٨٤٧ - كنى البخارى (ص ٧٢)، الثقات (٥/ ٥٨١)، المقتنى في سرد الكنى (١٣٤/ ب)."],[11688,"(١) المنهال: بمكسورة وسكون نون وبلام. المغنى (ص ٧٥)."],[11689,"(٢) في الثقات \"العبدى\"."],[11690,"١٨٤٨ - كنى البخارى (ص ٧٢)، الثقات (٥/ ٥٨١)، الجرح (٤/ ٢/ ٤٤٥) المقتنى في سرد الكنى (١٣٤/ ب)."],[11691,"(٣) إسماعيل بن عبد الرحمن بن أبى كريمة السّدّى، بضم المهملة وتشديد الدال أبو محمد الكوفى، صدوق يهم ورمى بالتشيع، من الرابعة (ت: ١٢٧)، التقريب (١/ ٧٢)."],[11692,"١٨٤٩ - المقتنى في سرد الكنى (١٣٤/ ب)."],[11693,"باب أبى ميمونة"],[11694,"١٨٥٠ - أبو ميمونة الأزدى. وقد قيل فيه: أبو ميمون بصرى. روى عن أبى هريرة. روى عنه قتادة."],[11695,"١٨٥١ - أبو ميمونة الأبّار. ذكره أبو أحمد الحاكم وجعله غير الازدى الذى قبله. وأما ابن أبى حاتم فقال (١): \"أبو ميمونة روى عن أبى هريرة عن النبى عليه السلام في ليلة القدر (٢). روى عنه قتادة. قال: وذكر أبى عن إسحاق بن منصور الكوسج عن يحيى بن معين أنه قال: أبو ميمونة الابار صالح (٣). فجعله رجلا واحدا. ثم قال: قال أبى: أبو ميمونة هذا لا يسمى\" (٤)."],[11696,"١٨٥٠ - الميزان (٤/ ٥٧٩) وقال: قال الدارقطنى: مجهول، يترك. المقتنى في سرد الكنى (١٣٧/ أ) وقال: أبو ميمونة وقيل: أبو ميمون الازدى. . فذكره. اللسان (٧/ ١١٣)."],[11697,"١٨٥١ - كنى البخارى (ص ٧٤)، كنى مسلم (ص ٩٦٤)، الجرح (٤/ ٢/ ٤٤٧) المقتنى في سرد الكنى (١٣٧/ أ)."],[11698,"(١، ٢، ٣) انظر الجرح (٤/ ٢/ ٤٤٧)."],[11699,"(٤) الحديث أخرجه أحمد في المسند (٢/ ٥١٩) والبزار كما في كشف الاستار (١/ ٤٨٤) من طريق قتادة عن أبى ميمونة عن أبى هريرة قال: قال رسول اللَّه -صلى الله عليه وآله وسلم-: \"ليلة القدر ليلة سابعة أو تاسعة وعشرين، أن الملائكة تلك الليالى في الأرض أكثر من عدد الحصى\" وقال البزار: لا نعلم روى قتادة بهذا الاسناد إلا حديثين، ولا نعلم بهذا عن أبى هريرة إلا هذا الطريق. وقال الهيثمى في مجمع الزوائد (٣/ ١٧٦) بعد أن ذكر الحديث: رواه أحمد وألبزار والطبرانى في الأوسط ورجاله ثقات. اهـ. والحديث بهذا المعنى في الصحيح عن غير واحد من الصحابة رضي الله عنهم. انظر صحيح البخارى \"الايمان\" (١/ ١١٣)."],[11700,"باب أبى المهاجر"],[11701,"١٨٥٢ - أبو المهاجر (عن يزيد بن حصين الاسلمى) (١). روى عنه أبو قلابة الجرمى."],[11702,"١٨٥٣ - أبو المهاجر، مولى بنى كلاب. قال: \"قلت لابن عباس وأنا أطوف بالبيت: كما لا ينفع مع الشرك شئ فهل يضر مع الاخلاص شئ (٢)؟ روى عنه (عبد الواحد بن صفوان) (٣) (٤)."],[11703,"١٨٥٤ - (أبو المهاجر. عن يزيد بن يزيد - أبو خالد. روى عنه) (٥)،"],[11704,"١٨٥٢ - الميزان (٤/ ٥٧٧) وقال: لا يعرف، تهذيب الكمال (٣/ ١٦٥١)، المقتنى في سرد الكنى (١٣٥/ أ)، اللسان (٧/ ٤٨٥)، التهذيب (١٢/ ٢٤٨ - ٢٤٩)."],[11705,"(١) هكذا في الأصل \"يزيد بن حصين. . إلخ\" والذى في تهذيب الكمال والتهذيب واللسان بريدة بن الحصيب الاسلمى. وذكر بعضهم أن صاحب الترجمة \"أبو المهاجر هذا\" إنما هو \"أبو المهلب\" وقد وهم فيه الأوزاعى فقال: عن أبى المهاجر\" اهـ. انظر تهذيب الكمال (٣/ ١٦٥١) التهذيب (١٢/ ٢٤٩)، اللسان (٧/ ٤٨٥)."],[11706,"١٨٥٣ - كنى البخارى (ص ٧٣)، الثقات (٥/ ٥٦٥)، المقتنى في سرد الكنى (١٣٥/ أ)."],[11707,"(٢) الأثر: أخرجهْ البخارى في الكنى (ص ٧٣)."],[11708,"(٣) عبد الواحد بن صفوان بن أبى عياش الأموى، مولى عثمان، مدنى سكن البصرة، مقبول، من السابعة. التقريب (١/ ٥٢٦)."],[11709,"(٤) الحق في هامش الأصل. كتب عنده كلمة \"صح أصل\"."],[11710,"١٨٥٤ - في المقتنى في سرد الكنى (١٣٥/ أ) أبو المهاجر يحيى بن كهمس."],[11711,"(٥) الحق في هامش الأصل. كتب في آخره \"صح أصل\"."],[11712,"يحيى بن كهمس. قال أبو أحمد: خليقا أن يكون سالما أبا المهاجر (١)."],[11713,"١٨٥٥ - أبو المهاجر، عن عطاء بن أبى مسلم الخراسانى، روى عنه جعفر بن برقان الكلابى."],[11714,"(١) سالم أبو المهاجر تقدم. انظر الترجمة (٨٢٤)."],[11715,"١٨٥٥ - كنى البخارى (ص ٧٣)، المقتنى في سرد الكنى (١٣٥/ أ)."],[11716,"باب أبى مرة"],[11717,"١٨٥٦ - أبو مرة، رأى عمر بن الخطاب، وروى عن عبد اللَّه بن عمر. روى عنه بكر بن عبد اللَّه المزنى - في البصريين."],[11718,"١٨٥٧ - أبو مرة مولى قيس بن عبيد الأنصارى (١)، روى عن رويفح بن ثابت الأنصارى (٢). أنه قال: ما لفظ البحر فكلوه (٣). روى عنه بكر بن سوادة."],[11719,"١٨٥٦ - كنى البخارى (ص ٧٢)، الجرح (٤/ ٢/ ٤٤٢)."],[11720,"١٨٥٧ - كنى البخارى (ص ٧١)، الجرح (٤/ ٢/ ٤٤٢)."],[11721,"(١) قيس بن عبيد، بخارى مازنى، له صحبة شهد أحدا والمشاهد كلها واستشهد يوم اليمامة، انظر التجريد (٢/ ٢٣)."],[11722,"(٢) رويفع، بالفاء، ابن ثابت الأنصارى، صحابى، سكن مصر، وولى أمرة برقة، ومات بها سنة (٥٦). التقريب (١/ ٢٥٤)، (١/ ٥٢٢)."],[11723,"(٣) الأثر، أخرجه البخارى في الكنى (ص ٧١)، وابن أبى حاتم في الجرح (٤/ ٢/ ٤٤٢) وقد أخرج مالك في الموطأ - كتاب الصيد باب ما جاء في صيد البحر (٢/ ٢٩٥) والبيهقى (٩/ ٢٥٤)، حديث أبى هريرة وزيد بن ثابت \"انهما كانا لا يريان بأكل ما لفظ البحر بأسا\" وحديث أبى هريرة أخرجه أيضا ابن أبى شيبة في المصنف \"كتاب الصيد\" (٥/ ٣٨١)."],[11724,"ويشهد لهذا الأثر حديث جابر بن عبد اللَّه رضي الله عنهما وفيه أنه -صلى الله عليه وآله وسلم- بعثهم وأمّر عليهم أبا عبيدة رضي الله عنه وزوّدهم جرابا من تمر لم يجد لهم غيره فأصابهم جوع شديد، والقى البحر حوتا يقال له العنبر فأكلوا منه وأقاموا عليه شهرا فلما قدموا المدينة أتوا رسول اللَّه -صلى الله عليه وآله وسلم- فذكروا له ذلك فقال \"هو رزق أخرجه اللَّه لكم. فهل معكم من لحمه شئ فتطعمونا؟ قال: فأرسلنا إلى رسول اللَّه -صلى الله عليه وآله وسلم- منه فأكله\". أخرجه البخارى: \"الذبائح والصيد\". (٩/ ٦١٤ - ٦١٥) ومسلم \"الصيد والذبائح\" باب إباحة ميتات البحر (٣/ ١٥٣٥ - ١٥٣٧)."],[11725,"باب أبى المختار"],[11726,"١٨٥٨ - أبو المختار، سمع ابن عمر، روى عنه معمر."],[11727,"١٨٥٩ - أبو المختار، رأى معاوية، روى عنه ابناه يوسف (١) كثير (٢)."],[11728,"١٨٦٠ - أبو المختار الطائى، روى عن شريح، روى عنه شريك بن عبد اللَّه النخعى، كوفى."],[11729,"١٨٦١ - أبو المختار، عن ابن البيلمانى (٣)، روى عنه هشام بن يوسف الصنعانى."],[11730,"١٨٥٨ - المقتنى في سرد الكنى (١٢٥/ أ)."],[11731,"١٨٥٩ - كنى البخارى (ص ٧١)، الجرح (٤/ ٢/ ٤٣٣)."],[11732,"(١) يوسف بن أبى المختار، ذكره ابن أبى حاتم في الجرح (٤/ ٢/ ٢٣٢) فقال يوسف بن أبى المختار، روى عن أبيه قال: رأيت معاوية بن أبى سفيان يصفر لحيته، روى عنه نوح بن قيس. اهـ."],[11733,"(٢) كثير بن أبى المختار، ذكره ابن أبى حاتم في الجرح (٣/ ٢/ ١٥٧) فقال: بصرى روى عن أبيه، روى عنه نوح بن قيس اهـ."],[11734,"١٨٦٠ - الجرح (٤/ ٢/ ٤٤٣)، الميزان (٤/ ٥٧١)، تهذيب الكمال (٣/ ١٦٤٥)، التهذيب (١٢/ ٢٢٦)، التقريب (٢/ ٤٧٠) وقال قيل اسمه سعد، مجهول، من السادسة./ ت. عس."],[11735,"١٨٦١ - المقتنى في سرد الكنى (١٢٥/ أ)."],[11736,"(٣) هو محمد بن عبد الرحمن."],[11737,"باب أبى منيب"],[11738,"١٨٦٢ - أبو المنيب الأحدب (١)، روى عن معاذ بن جبل، وأبى عبيدة (٢) بن الجراح، روى عنه عاصم بن سليمان الأحول، وأبو عطاء (٣)."],[11739,"١٨٦٣ - أبو المنيب الجرشى (٤)، عن عبد اللَّه بن عمر (٥)، وسعيد بن المسيب. روى عنه حسان بن عطية، وزيد بن واقد (٦) الشاميان، ومجاهد بن"],[11740,"١٨٦٢ - كنى البخارى (ص ٧٠)، الجرح (٤/ ٢/ ٤٤٠)، اللسان (٧/ ١١١) تاريخ دمشق (٦٢٢) وقال: أبو المنيب الجرشى الاحدب ثم ذكره وجعله هو والذى بعده واحدا، وذكر ابن حجر أبا المنيب الاحدب هذا في التقريب (٢/ ٤٧٧) تمييزا وقال: مقبول، من الثانية، ووهم من خلطه بالذى قبله. اهـ. وانظر أيضا الترجمة الاتية بعد هذه الترجمة والتعليق عليها."],[11741,"(١) الاحدب: بفتح الألف وسكون الحاء المهملة وفتح الدال المهملة أيضا وفى آخرها الباء المنقوطة بواحدة، تقال لمن في ظهره حدب وهو الانحناء والنتوء وغيره. اهـ. انظر اللباب (١/ ٣٠)."],[11742,"(٢) في كنى البخارى \"وعبادة\"."],[11743,"(٣) هو أبو عطاء اليحبورى وسيأتى في (٢٢٣١)."],[11744,"١٨٦٣ - كنى البخارى (ص ٧٠)، كنى مسلم (ص ٩٧٦)، الثقات (٥/ ٥٦٤)، الجرح (٤/ ٢/ ٤٤٠)، تاريخ دمشق (ل/ ٦٢٢)، تهذيب الكمال (٣/ ١٦٥١)، التهذيب (١٢/ ٢٤٨)، اللسان (٧/ ١١١)، التقريب (٢/ ٤٧٧) وقال: ثقة من الرابعة./ د."],[11745,"(٤) الجرشى: بضم الجيم وفتح الراء كسر الشين المعجمة - هذه النسبة إلى بنى جرش، بطن من حمير، اللباب (١/ ٢٧٢)."],[11746,"(٥) في كنى مسلم \"عمرو\"."],[11747,"(٦) زيد بن واقد القرشى، الدمشقى، ثقة، من السادسة. انظر التقريب (١/ ٢٧٧)."],[11748,"فرقد الصنعانى (١). وروى محمد بن الصباح (٢)، عن جرير (٣) عن عاصم، عن أبى منيب الجرشى قال: خطبنا معاذ بن جبل، جعل البخارى (٤) الجرشى غير الأحدب وكذلك فعل ابن أبى حاتم (٥)."],[11749,"وقال أبو أحمد الحاكم (٦):"],[11750,"(١) فرقد: بمفتوحة وسكون راء وبقاف ومهملة. المغنى (ص ٦١) ومجاهد بن فرقد الصنعانى ذكره ابن أبى حاتم في الجرح (٤/ ١/ ٣٢٠) عن أبيه فقال: روى عن واثلة بن الخطاب وأبى منيب الجرشى، مرسل، روى عنه إسماعيل ابن عياش. اهـ."],[11751,"(٢) محمد بن الصبّاح بن سفيان الجرجرائى، بجيمين مفتوحتين بينهما راء ساكنة ثم راء خفيفة، أبو جعفر التاجر، صدوق من العاشرة (ت: ٢٤٠) التقريب (٢/ ١٧١)."],[11752,"(٣) هو ابن عبد الحميد، روى عن عاصم، وروى عنه محمد بن الصباح. انظر التهذيب (٢/ ٧٥) و(٩/ ٢٢٨)."],[11753,"(٤) انظر الكنى (ص ٧٠)."],[11754,"(٥) انظر الجرح (٤/ ٢/ ٤٤٠)."],[11755,"(٦) هكذا جاء في هذه الترجمة أن البخارى وتبعه ابن أبى حاتم جعلا أبا المنيب الجرشى غير أبى المنيب الاحدب، وجعله الحاكم أبو أحمد وتبعه ابن عبد البر هو والاحدب واحدا، لكن رجح ابن حجر في التهذيب (١٢/ ٢٤٨) ما ذهب إليه البخارى ابن أبى حاتم فقال: أبو المنيب الجرشى الدمشقى الأحدب. روى عن معاذ بن جبل وعمرو بن العاص وأبى هريرة وابن عمر وسعيد بن المسيب وأبى عطاء اليحبورى. . إلخ - ثم قال: وفرق البخارى بين أبى المنيب الجرشى الشامى الراوى عن ابن عمر وابن المسيب فقط وعنه حسان بن عطية وغيره. وكذا صنع ابن أبى حاتم عن أبيه وأبو محمد بن صاعد في كتابه في الكنى. وقال الحاكم أبو أحمد في الكنى: ما ="],[11756,"ما أراهما إلا واحدا واللَّه (أعلم) (١) قال أبو عمر ما رواه جرير عن عاصم دليل على أنهما واحد. واللَّه أعلم."],[11757,"١٨٦٤ - أبو المنيب. روى عن يحيى بن أبى كثير مناكير، وروى عنه عبيد اللَّه بن زحر (٢) مناكير، وهو مجهول."],[11758,"= أراهما إلا واحدا، وليس كما قال. واللَّه تعالى أعلم. اهـ. هكذا عبارة التهذيب. والذى يبدو أن فيها سقطًا عند قوله \"وغيره\" وتقدير السقط هو \"وبين أبى المنيب الأحدب\" واللَّه أعلم."],[11759,"(١) لم تكن في الأصل، والسياق يقتضيها."],[11760,"١٨٦٤ - كنى البخارى (ص ٧٠)، الجرح (٤/ ٢/ ٤٤٠)، اللسان (٧/ ١١١) وقال: فرق الحاكم بينه وبين الجرشى. . - ثم قال ابن حجر: ما أظنه إلا الجرشى لأنه شامى ويحيى بن أبى كثير أبو النضر يمامى. . . ثم قال: قال الحاكم: أبو المنيب رجل مجهول. اهـ."],[11761,"(٢) عبيد اللَّه بن زحر: بفتح الزاى وسكون المهملة، الضمرى مولاهم الأفريقى، صدوق، يخطئ، من السادسة. التقريب (١/ ٥٣٣)."],[11762,"باب أبى مضر"],[11763,"١٨٦٥ - أبو مضر (١) النّاجى، عن عبد اللَّه بن دينار (٢) عن ابن عمر. قال: ذكر حاتم طئ (٣) عند النبى عليه السلام فقال: ذاك امرؤ طلب أمرا فأدركه (٤) لم يتابع عليه، روى عنه عبيد بن واقد (٥)."],[11764,"١٨٦٦ - أبو مضر، عن الحسن بن أبى الحسن، ومحمد بن سيرين، روى عنه سليمان بن محمد الجرمى (٦)."],[11765,"١٨٦٥ - الاكمال (٧/ ٢٥٩)، المقتنى في سرد الكنى (١٢٨/ ب)."],[11766,"(١) مضر: بضم الميم وبالضاد المعجمة. كما في الاكمال (٧/ ٢٥٩)."],[11767,"(٢) هو العدوى مولى ابن عمر."],[11768,"(٣) له ترجمة في المحبّر (ص ١٤٥ - ١٤٦)."],[11769,"(٤) الحديث أخرجه الدارقطنى في الإفراد، وابن عساكر في التاريخ من حديث ابن عمر به. كما في الجامع الكبير للسيوطى (٢/ ٤٩٦)."],[11770,"(٥) في الاكمال، والمقتنى \"عبيد اللَّه\"."],[11771,"وقال ابن حجر في التقريب (١/ ٥٤٦): عبيد بن واقد القيسى أو الليثى، أبو عباد، ضعيف، من التاسعة. اهـ."],[11772,"١٨٦٦ - كنى البخارى (ص ٧٥)، الثقات (٧/ ٦٦٥)، الجرح (٤/ ٢/ ٤٤٧). المقتنى في سرد الكنى (١٢٨/ ب)."],[11773,"(٦) زاد ابن أبى حاتم \"القافلانى\" وذكر ابن أبى حاتم أيضًا في الجرح (٢/ ١/ ١٣٩) عن أبيه سليمان بن محمد الجرمى وقال: روى عن ابن سيرين روى عنه مسعدة. اهـ. وذكر بعده مباشرة سليمان بن محمد القافلانى أبو الربيع. روى عن ابن سيرين وروى عن أبى طالوت عن مالك بن عبد اللَّه الخثعمى. الخ. ففرق بين سليمان بن محمد الجرمى، وبين سليمان بن محمد القافلانى. واللَّه أعلم."],[11774,"باب أبى مرزوق"],[11775,"١٨٦٧ - أبو مرزوق التجيبى، المصرى. سمع حنش بن عبد اللَّه السّبائى (١) الصنعانى. روى عنه يزيد بن أبى حبيب ومحمد بن عبد الرحمن (٢)."],[11776,"١٨٦٨ - أبو مرزوق. روى عن أبى غالب (٣)، روى عنه أبو العدبّس (٤)."],[11777,"١٨٦٩ - أبو مرزوق بن حزوز القرشى. روى عنه منيع بن سليمان الأسدى (٥)."],[11778,"١٨٦٧ - كنى البخارى (ص ٧٢)، الثقات (٧/ ٦٦٥)، الجرح (٤/ ٢/ ٤٤٢) فتوح مصر (٢٧٨)، الميزان (٤/ ٥٧٢)، المقتنى في سرد الكنى (١٢٥/ ب)، اللسان (٥/ ٢٥٧) وقال: قال أبو حاتم: مجهول، التهذيب (١٢/ ٢٢٨)، التقريب (٢/ ٤٧١) وقال: اسمه حبيب بن الشهيد على الأشهر، ثقة، من الخامسة (ت: ١٥٩)./ د. ق."],[11779,"(١) السبائى: بفتح السين المهملة والباء الموحدة بعدها همزة مكسورة - هذه النسبة إلى سبأ بن يشجب بن يعرب بن قحطان. اهـ. اللباب (٢/ ٩٨)."],[11780,"(٢) زاد ابن حجر في التهذيب \"المدنى ثم المصرى المؤذن أبو عيسى\" ومحمد ابن عبد الرحمن هذا ذكره ابن أبى حاتم عن أبيه في الجرح (٣/ ٢/ ٣٢٥) فقال: \"محمد بن عبد الرحمن أبو عيسى المؤذن. روى عن أبى مرزوق التجيبى. . ولم يذكر فيه شيئا. اهـ."],[11781,"١٨٦٨ - كنى البخارى (ص ٧٢)، الجرح (٤/ ٢/ ٤٤٢)، الميزان (٤/ ٥٧١)، التهذيب (١٢/ ٢٢٩)، المقتنى في سرد الكنى (١٢٥/ ب)، التقريب (٢/ ٤٧١) وقال: ليّن، من السادسة ولا يعرف اسمه./ د. ق."],[11782,"(٣) هو صاحب أبى مامة."],[11783,"(٤) هو منيع بن سليمان."],[11784,"١٨٦٩ - لم أقف عليه."],[11785,"(٥) هو أبو العدبس."],[11786,"باب أبى معقل"],[11787,"١٨٧٠ - أبو معقل بن أبى مسلم، روى عن أبى عبيد (١)، مولى رفاعة بن رافع عن النبى عليه السلام قال: \"ملعون من سأل بوجه اللَّه وملعون من سئل بوجه اللَّه فمنع سائله\" (٢) من حديث ابن وهب عن عبد اللَّه بن عياش عن عبد اللَّه بن الأسود (٣) عن أبى معقل بن أبى مسلم قال أبو زرعة: أبو معقل هذا لا يسمى. وأبو عبيد ليست له صحبة (٤)."],[11788,"١٨٧٠ - الجرح (٤/ ٢/ ٤٤٨)، الميزان (٤/ ٥٧٦) وقال: لا يعرف."],[11789,"(١) أبو عبيد يأتى في (٢٠٩٧)."],[11790,"(٢) الحديث أخرجه ابن أبى حاتم في الجرح (٤/ ٢/ ٤٤٨)، والطبرانى في الكبير كما في مجمع الزوائد (٣/ ١٠٣)، وقال الهيثمى: وفيه من لم أعرفه وعزاه الحافظ المناوى في الجامع الأزهر (٢/ ١٧٥/ أ)، والسخاوى في المقاصد الحسنة (ص ٤٧١) أيضًا إلى الطبرانى في الكبير."],[11791,"وأخرجه ابن أبى حاتم في المراسيل (ص ٢٥٣) وقال: أبو عبيد مولى رفاعة بن رافع ليست له صحبة. وذكره العلائى في جامع التحصيل (ص ٣٨٧) أيضًا بنحو ما ذكره ابن أبى حاتم."],[11792,"والحديث أخرجه أيضا الطبرانى في الكبير. كما في الجامع الأزهر (٢/ ١٧٥/ أ) ومجمع الزوائد (٣/ ١٠٣)، والمقاصد الحسنة (ص ٤٧١) من حديث أبى موسى الأشعرى به وقال المناوى: في إسناده يحيى بن عثمان بن صالح وهو ثقة، وبقية رجاله رجال الصحيح، وقال الهيثمى: إسناده حسن على ضعف في بعضه مع توثيق."],[11793,"(٣) عبد اللَّه بن الأسود القرشى، ذكره ابن أبى حاتم، عن أبيه فقال: شيخ لا أعلم. روى عنه غير عبد اللَّه بن وهب. انظر الجرح (٢/ ٢/ ٢)."],[11794,"(٤) الجرح (٤/ ٢/ ٤٤٨)."],[11795,"١٨٧١ - أبو معقل. روى عن أنس عن النبى عليه السلام أنه مسح بمقدم رأسه تحت العمامة (١)."],[11796,"من حديث معاوية بن صالح عن عبد العزيز بن مسلم (٢) عنه."],[11797,"١٨٧١ - الجرح (٤/ ٢/ ٤٤٨)، تهذيب الكمال (٣/ ١٦٤٩)، التهذيب (١٢/ ٢٤٢)، التقريب (٢/ ٤٧٥)، وقال مجهول، من الخامسة./ د. ق."],[11798,"(١) الحديث أخرجه ابن أبى حاتم في الجرح (٤/ ٢/ ٤٤٨) وأبو داود \"الطهارة\" باب المسح على العمامة (١/ ٣٦)، وابن ماجه \"الطهارة\" باب ما جاء في المسح على العمامة (١/ ١٨٦)، والبيهقى في السنن (١/ ٦١)، والحاكم (١/ ١٦٩) وقال: هذا الحديث وإن لم يكن إسناده من شرط الكتاب فإن فيه لفظة غريبة وهى أنه مسح على بعض الرأس ولم يمسح على عمامته، وقال الذهبى في التلخيص على المستدرك لو صح لدل على مسح بعض الرأس. ا. هـ."],[11799,"قلت: والحديث أخرجه أيضًا المزى في تهذيب الكمال (٢/ ٨٤٣ - ٨٤٤) في ترجمة عبد العزيز بن مسلم - راوى هذا الحديث عن أبى معقل فقال المزى: وقع لنا حديثه بعلو فذكر الحديث بسنده المتصل إلى أنس رضي الله عنه كلهم أخرجوه من طريق عبد اللَّه بن وهب، عن معاوية بن صالح، عن عبد العزيز بن مسلم، عن أبى معقل، عن أنس بن مالك قال: رأيت رسول اللَّه -صلى الله عليه وآله وسلم- يتوضأ وعليه عمامة قطرية، فأدخل يده من تحت العمامة فمسح مقدم رأسه ولم ينقض العمامة\"."],[11800,"وقوله في الحديث: قطرية: هى ضرب من البرود فيه حمرة ولها إعلام فيها بعض الخشونة، وقيل: هى حلل جياد وتحمل من قبل البحرين، قال الأزهرى: في أعراض البحرين قرية يقال لها قطر، واحسب الثياب القطرية نسبت إليها، فكسروا القاف للنسبة وخفضوا، انظر النهاية (٤/ ٨٠)."],[11801,"(٢) عبد العزيز بن مسلم المدنى، مولى آل رفاعة، مقبول من السابعة. انظر التقريب (١/ ٥١٢). قلت: وهو غير عبد العزيز بن مسلم القسملى كما ذكر ابن حجر في التهذيب (١٢/ ٢٤٢) في ترجمة أبى معقل."],[11802,"١٨٧٢ - أبو معقل. عن أبى هريرة. روى عنه عثمان بن عبيد اليحصبى (١) في الشاميين."],[11803,"١٨٧٢ - المقتنى في سرد الكنى (١٣١/ ب)."],[11804,"(١) عثمان بن عبيد اليحصبى، مقبول، من السابعة. انظر التقريب (٢/ ١٢)."],[11805,"باب أبى المنذر"],[11806,"(١)"],[11807,"١٨٧٣ - أبو المنذر، مولى أبى ذر. روى عن أبى أمية المخزومى عن النبى عليه السلام في السارق (٢). حديثه عند موسى بن إسماعيل عن، حماد بن سلمة عن إسحاق بن عبد اللَّه بن أبى طلحة."],[11808,"١٨٧٤ - أبو المنذر. روى عن أبى أسيد. روى عنه شريك بن عبد اللَّه بن أبى نمر."],[11809,"(١) تقدم هذا الباب بكامله عن المؤلف انظر الترجمتين (١٨١٢) و(١٨١٣)."],[11810,"(٢) الحديث تقدم تخريجه في ترجمة أبى أمية المخزومى في الصحابة. انظر الترجمة (١٨) والتعليق عليها."],[11811,"١٨٧٤ - تقدم. انظر الترجمة (١٨١٣)."],[11812,"باب أبى ميسرة"],[11813,"١٨٧٥ - أبو ميسرة الهاشمى. مولى العباس بن عبد المطلب (عن ابن عباس بن عبد المطلب) (١) عن النبى -صلى الله عليه وآله وسلم- حدث عنه أبو قبيل المعافرى (٢)."],[11814,"١٨٧٦ - أبو ميسرة القصّار (٣) بصرى. روى عن قتادة. روى عنه سعيد بن سالم (٤) العطار، وسعيد منكر الحديث."],[11815,"١٨٧٥ - كنى البخارى (ص ٧٥)، الجرح (٤/ ٢/ ٤٤٦)، المقتنى في سرد الكنى (١٣٧/ أ)."],[11816,"قلت: وستأتى هذه الترجمة مكررة عند المؤلف في أفراد الميم. انظر الترجمة (١٩١٨)."],[11817,"(١) في الجرح \"روى عن العباس بن عبد المطلب\" وسيأتى في ترجمته في (١٩١٨) أنه روى عن \"العباس بن عبد المطلب\" واللَّه أعلم."],[11818,"(٢) هو حى بن هانئ تقدم في (١٠٦٤)."],[11819,"١٨٧٦ - المقتنى في سرد الكنى (١٣٧/ أ) وقال: أبو ميسرة القطان عن قتادة وعنه سعيد بن سلام العطار، بخبر منكر في التزاور في الاكفان. اهـ."],[11820,"(٣) القصّار: بفتح القاف والصاد المشددة وبعد الألف راء، هذه النسبة إلى قصارة الثياب وغيرها. اللباب (٣/ ٣٩)."],[11821,"(٤) في الجرح (٢/ ١/ ٣١) سعيد بن سلّام العطار. قال ابن أبى حاتم عن أبيه: منكر الحديث جدا. وفى المجروحين (١/ ٣٢١) \"سعيد بن سلام العطار، عن أهل البصرة كنيته أبو الحسن يروى عن ثور بن يزيد والثورى روى عنه العراقيون، منكر الحديث، ينفرد عن الإثبات بما لا أصل له."],[11822,"باب أبى ماجد"],[11823,"١٨٧٧ - أبو ماجد (١) الحنفى. وقيل العجلى. عن عبد اللَّه بن مسعود روى عنه يحيى بن عبد اللَّه الجابر التيمى (٢) قال الحميدى (٣) عن ابن عيينة قلت ليحيى الجابر من أبو ماجد؟ قال: طار طرأ علينا فحدثنا (٤)، حديثه ليس بالقوى."],[11824,"١٨٧٨ - أبو ماجد الزيادى (٥)، مصرى، عن ابن عمر قال:"],[11825,"١٨٧٧ - كنى البخارى (ص ٧٣)، التاريخ الصغير (ص ١١١)، الضعفاء الصغير (ص ١٢٤)، الضعفاء والمتروكين (ص ١١٣)، الضعفاء لأبى زرعة الرازى (٢/ ٦٧٤)، الجرح (٣/ ٢/ ١٦)، الميزان (٤/ ٥٦٦)، تهذيب الكمال (٣/ ١٦٤٢)، التهذيب (١٢/ ٢١٦)، التقريب (٢/ ٤٦٨) وقال: قيل: اسمه عائذ بن نضلة، مجهول، لم يرو عنه غير يحيى الجابر، من الثانية./ د. ت. ق."],[11826,"(١) في الجرح \"عائذ بن نضلة الحنفى أبو ماجد. . \" فذكر ترجمته."],[11827,"(٢) يحيى بن عبد اللَّه الجابر التيمى، لين الحديث، من السادسة، وروايته عن المقدام مرسلة. انظر التقريب (٢/ ٣٥١)."],[11828,"(٣) الحميدى: هو عبد اللَّه بن الزبير بن عيسى بن عبد اللَّه الأسدى الحميدى."],[11829,"(٤) في الضعفاء الصغير \"طارئ طرأ علينا، وهو منكر الحديث وفى ضعفاء أبى زرعة\" قال الحميدى: قال ابن عيينة: قلت ليحيى الجابر: من أبو ماجد الحنفى؟ قال: طار علينا طير فحدثنا، وهو منكر الحديث\" وكذا ذكره المزى في تهذيب الكمال عن ابن عيينة عن يحيى الجابر قال: \"شيخ طرى علينا من البصرة\" وفى التهذيب \"طير طرأ علينا\"."],[11830,"١٨٧٨ - كنى البخارى (ص ٧٣)، الجرح (٤/ ٢/ ٤٤٥)."],[11831,"(٥) الزّيادى: بكسر الزاى وفتح الياء وبعد الألف دال مهملة - هذه النسبة إلى جد المنتسب إليه. اهـ. اللباب (٢/ ٨٤)."],[11832,"\"ما نظرت إلى فرج امرأة منذ أسلمت\" (١). روى عنه موسى بن أيوب الغافقى (٢)."],[11833,"(١) الأثر: أخرجه البخارى في الكنى (ص ٧٣). وابن أبى حاتم في الجرح (٤/ ٢/ ٤٤٥) وأخرجه الطبرانى في التفسير (٤/ ٤٠٦) عند قوله تعالى ﴿نِسَاؤُكُمْ حَرْثٌ لَكُمْ. .﴾ الآية ٢٢٣ من سورة البقرة - من طريق محمد بن إسحاق قال: أخبرنا عمرو بن طارق قال: أخبرنا يحيى بن أيوب عن موسى ابن أيوب الغافقى قال: قلت لأبى ماجد الزيادى: أن نافعا يحدث عن ابن عمر في دبر المرأة. فقال: كذب نافع، صحبت ابن عمر ونافع مملوك فسمعته يقول: \"ما نظرت إلى فرج أمرأتى منذ كذا وكذا\" قلت: ولفظه عند البخارى وابن أبى حاتم \"ما نظرت إلى فرجى منذ أسلمت\"."],[11834,"(٢) موسى بن أيوب الغافقى، بصرى، مقبول، من السادسة (ت: ١٥٣) انظر التقريب (٢/ ٢٨١)."],[11835,"باب أبى مطر"],[11836,"١٨٧٩ - أبو مطر البصرى، الجهنى، عن على بن أبى طالب، روى عنه المختار بن نافع التميمى (١)، سئل أبو زرعة عن أبى مطر هل سمى؟"],[11837,"فقال (٢): لا أعرف اسمه. قال عمر بن حفص بن غياث (٣): (يقول) (٤) \"ترك أبى حديث أبى مطر\"."],[11838,"١٨٨٠ - أبو مطر، عن سالم بن عبد اللَّه، روى عنه الحجاج بن ارطأة في الكوفيين."],[11839,"١٨٧٩ - كنى البخارى (ص ٧٥)، الجرح (٤/ ٢/ ٤٤٥)، الميزان (٤/ ٥٧٤) وقال: مجهول تعجيل المنفعة (ص ٣٤٠)، اللسان (٧/ ١٠٧) وقال: مجهول."],[11840,"(١) مختار بن نافع التميمى، ويقال العكلى، أبو اسحاق التمار، الكوفى، ضعيف، من السادسة. التقريب (٢/ ٢٣٤)."],[11841,"(٢) الجرح (٤/ ٢/ ٤٤٥)."],[11842,"(٣) عمر بن حفص بن غياث، بكسر المعجمة وآخره مثلثة، ابن الطلق بفتح الطاء وسكون اللام، الكوفى، ثقة ربما وهم، من العاشرة (ت: ٢٢٢). التقريب (٢/ ٥٣)."],[11843,"(٤) هكذا في الأصل \"يقول\" ولعلها زائدة، والذى في الجرح \"قال عمر بن حفص بن غياث\" ترك أبى حديث أبى مطر \"وفى تعجيل المنفعة\" ترك حفص حديث أبى مطر \"وفى اللسان\" تركه حفص بن غياث."],[11844,"١٨٨٠ - كنى البخارى (ص ٧٥)، الثقات (٧/ ٦٦٤)، الميزان (٤/ ٥٧٤)، وقال: لا يدرى من هو، التهذيب (١٢/ ٢٣٨)، التقريب (٢/ ٤٧٣) وقال: مجهول، من السادسة./ بخ د. س."],[11845,"باب أبى محرز"],[11846,"١٨٨١ - أبو مُحْرِز (١)، بصرى، عن عثمان بن أبى العاص الثقفى، روى عنه المبارك بن فضالة."],[11847,"١٨٨٢ - أبو مُحْرِز البكرى، أدرك الجاهلية، روى عنه ابنه عبد اللَّه بن أبى محرز (٢)."],[11848,"١٨٨١ - المقتنى في سرد الكنى (١٢٤/ ب)."],[11849,"(١) محرز، بضم الميم، وبسكون الحاء، كسر الراء وبعدها أى الاكمال (٧/ ٣١٦)."],[11850,"١٨٨٢ - كنى البخارى (ص ٧٤)، الجرح (٤/ ٢/ ٤٤٤)، الإصابة (٤/ ق ٣/ ١٨٩)."],[11851,"(٢) عبد اللَّه بن أبى محرز. قال ابن حجر: مجهول. انظر اللسان (٣/ ٣٥٦)."],[11852,"باب أبى المصبح"],[11853,"١٨٨٣ - أبو المُصَبَّح (١) (٢) الأوزاعى الحمصى، روى عن جابر بن عبد اللَّه وثوبان مولى رسول اللَّه -صلى الله عليه وآله وسلم-، ومالك بن عبد اللَّه الخثعمى (٣)، روى عنه يزيد بن جابر (٤) وحصين بن حرملة (٥) وأمية بن يزيد (٦). سئل أبو زرعة عن أبى المصبح"],[11854,"١٨٨٣ - كنى البخارى (ص ٧٤)، الجرح (٤/ ٢/ ٤٤٥)، الثقات (٥/ ٥٧٠) و(٥٨٣)، تاريخ دمشق (ل/ ٦٦٤)، تهذيب الكمال (٣/ ١٦٤٨)، التهذيب (١٢/ ٢٣٧)، التقريب (٢/ ٤٧٣) وقال: ثقة، نزل حمص، من الثالثة./ د. الخلاصة (ص ٤٦٠)، الاكمال (٧/ ٣٢٠)."],[11855,"(١) مُصَبَّح: بمضمومة، وفتح صاد مهملة، وشدة موحدة مكسورة. الخلاصة (ص ٤٦٠)، المغنى (ص ٧٢)."],[11856,"(٢) في الثقات، والإكمال، وتهذيب الكمال والخلاصة زيادة \"المقرائى\" والمقرائى: بضم الميم وقيل: بفتحها، وسكون القاف، وفتح الراء وبعدها همزة - نسبة إلى مقراء قرية بدمشق. انظر اللباب (٢/ ٢٤٧)."],[11857,"(٣) مالك بن عبد اللَّه الخثعمى: نزل فلسطين، يعرف بمالك السرايا، وكان كثير الغزو - قاد الصوائف مدة أربعين سنة. انظر الإصابة (٣/ ٣٤٧)، التجريد (٢/ ٤٥)."],[11858,"(٤) يزيد بن جابر، قال ابن القطان: لا يعرف. انظر اللسان (٦/ ٢٨٥)."],[11859,"(٥) حصين بن حرملة، ذكره ابن أبى حاتم، عن أبيه فقال: حصين بن حرملة المهرى، شامى، روى عن أبى المصبح، روى عنه، عتبة بن أبى حكيم. انظر الجرح (١/ ٢/ ١٩١)."],[11860,"(٦) أمية بن يزيد، ذكره ابن أبى حاتم عن أبيه فقال: أمية بن يزيد بن أبى عثمان القرشى، شامى، روى عن أبى المصبح، ومكحول. . \" إلخ. انظر الجرح (١/ ١/ ٣٠٢)."],[11861,"فقال (١): ثقة حمصى لا أعرف اسمه."],[11862,"١٨٨٤ - أبو المصبّح الليثى. روى عن أبى الزناد (٢) خبرا طويلا في بيعة العقبة - هو مجهول. روى عنه علوان بن داود (٣)، مجهول أيضًا."],[11863,"(١) انظر الجرح (٤/ ٢/ ٤٤٥)."],[11864,"١٨٨٤ - لم أقف عليه عند غير المؤلف."],[11865,"(٢) هو عبد اللَّه بن ذكوان."],[11866,"(٣) علوان بن داود، ذكره ابن حجر في اللسان (٤/ ١٨٨ - ١٩٠) فقال: علوان ابن داود مولى جرير بن عبد اللَّه ويقال: علوان بن صالح، قال البخارى: علوان ابن داود. ويقال ابن صالح منكر الحديث."],[11867,"وذكر ابن حجر له أحاديث منها حديثه عن الليثى عن أبى الزناد قال: لما اشتد المشركون على النبى -صلى الله عليه وآله وسلم- بمكة قال للعباس يا عم أنى لا أرى عندك ولا عند أهل بيتك نصرة ولا منفعة واللَّه ناصر دينه بقوم يهون عليهم -رغم قريش- في ذات اللَّه فامضوا بى إلى عكاظ فأرونى منازل أحياء العرب حتى ادعوهم إلى اللَّه. قال: فبدأ بثقيف. . وذكر الحديث في نحو من كراس في عرضه نفسه على القبائل. اهـ. وانظر أيضًا البداية والنهاية (٣/ ١٣٨) وما بعدها."],[11868,"باب أبى منظور"],[11869,"١٨٨٥ - أبو منظور الشامى عن عمه (١). وروى عنه محمد بن إسحاق."],[11870,"١٨٨٦ - أبو منظور، عن أبى معاذ، عن أبى كاهل. روى عنه الفضل بن شعيب (٢) وإسناد حديثه مجهول."],[11871,"١٨٨٥ - كنى البخارى (ص ٧٥)، الجرح (٤/ ٢/ ٤٤٧)، تهذيب الكمال (٣/ ١٦٥١)، الميزان (٤/ ٥٧٧) وقال: لا يعرف، المقتنى في سرد الكنى (١٣٤/ ب)، التهذيب (١٢/ ٢٤٧)، التقريب (٢/ ٤٧٧)، وقال: مجهول، من السادسة./ د."],[11872,"(١) هكذا في الأصل \"عمه\" وكذا هو في مصادر الترجمة ولم أقف على من سماه."],[11873,"١٨٨٦ - المقتنى في سرد الكنى (١٣٤/ ب)، وقال: أبو منظور عن أبى معاذ عن أبى كاهل وعنه الفضل بن شعيب ظلمات."],[11874,"(٢) الفضل بن شعيب. لم أقف له على ترجمة."],[11875,"باب أبى مسكين"],[11876,"١٨٨٧ - أبو مسكين الجزرى، روى عن إسماعيل بن نشيط (١)، عن عكرمة روى عنه بقية. قال ابن أبى حاتم: \"سألت أبى عنه فقال: مجهول والحديث الذى رواه كأنه موضوع (٢)."],[11877,"١٨٨٨ - أبو مسكين يحدث عن طلحة بن البراء (٣). حدث عنه عروة بن رُوَيم (٤) في الشاميين."],[11878,"١٨٨٧ - الجرح (٤/ ٢/ ٤٤٧)، الميزان (٤/ ٥٧٣) وقال: مجهول. اللسان (٧/ ١٠٥) وقال: قال محمود بن غيلان: ضرب أحمد وابن مغيرة، وأبو خيثمة على حديثه، واسقطوه. اهـ."],[11879,"(١) إسماعيل بن نشيط العامرى. قال ابن أبى حاتم عن أبيه شيخ مجهول، وقال أبو زرعة: هو صدوق. انظر الجرح (١/ ١/ ٢٠٢)."],[11880,"(٢) انظر الجرح (٤/ ٢/ ٤٤٧)."],[11881,"١٨٨٨ - المقتنى في سرد الكنى (١٢٧/ أ)."],[11882,"(٣) قال ابن أبى حاتم عن أبيه الجرح (٢/ ١/ ٤٧٢): \"طلحة بن البراء توفى على عهد النبى -صلى الله عليه وآله وسلم- روى عروة بن رويم عن أبى مسكين الأنصارى عنه، مرسل، روى عن الحصين بن وحوح الأنصارى أن طلحة بن البراء مرض فعاده النبى -صلى الله عليه وآله وسلم-. اهـ."],[11883,"(٤) عروة بن رُوَيم، بالبراء، مصغرا، اللخمى، أبو القاسم، صدوق، يرسل كثيرا من الخامسة (ت: ١٣٥) على الصحيح. التقريب (٢/ ١٩)."],[11884,"باب أفراد في الميم"],[11885,"١٨٨٩ - أبو مُرَاوحِ (١) الغفارى - روى عن أبى ذر. روى عنه عروة قد ذكرنا قول من قال: اسمه سعيد وأكثرهم يقول: لا اسم له، غير كنيته."],[11886,"١٨٩٠ - أبو مُدِلَّة (٢) مولى عائشة، وقيل: اسمه سعيد وأكثرهم يقول: لا اسم له غير كنيته. روى عن أبى هريرة عن النبى عليه السلام قال: \"بناء الجنة لبنة من ذهب ولبنة من فضة\" (٣). روى عنه سعد الطائى أبو مجاهد."],[11887,"١٨٨٩ - كنى مسلم (ص ٩٨٩)، الثقات (٥/ ٥٦٣)، الاستيعاب (٤/ ١٩١)، الإصابة (٤/ ١٧٧) و٤/ ق ٣/ ١٨٩، تهذيب الكمال (٣/ ١٦٤٥) التهذيب (١٢/ ٢٢٧)، التقريب (٢/ ٤٧٠) وقال: ثقة، من الثالثة خ. م. س. ق."],[11888,"(١) مراوح: بضم الميم، كسر الواو. المغنى (ص ٩٠)."],[11889,"١٨٩٠ - كنى البخارى (ص ٧٤)، كنى مسلم (ص ٩٨٩)، تهذيب الكمال (٣/ ١٦٤٥) الجرح (٤/ ٢/ ٤٤٤)، الميزان (٤/ ٥٧١)، اللسان (٧/ ٤٨٢)، التهذيب (١٢/ ٢٢٧) التقريب (٢/ ٤٧٠) وقال: يقال: اسمه عبيد اللَّه، مقبول، من الثالثة./ ت. ق."],[11890,"(٢) مُدِلَّة: بضم الميم كسر المهملة، وتشديد اللام، كما في التقريب (٢/ ٤٧٠)."],[11891,"(٣) الحديث: أخرجه أحمد (٢/ ٣٠٤) و(٤٤٥)، والدارمى (٢/ ٣٣٣) كلاهما من طريق أبى مجاهد الطائى عن أبى مدله عن أبى هريرة به وهو عند أحمد مطول في بعض ألفاظه وفيه \"قلنا يا رسول اللَّه أنا إذا رأيناك رقت قلوبنا وكنا من أهل الآخرة، وإذا فارقناك أعجبتنا الدنيا وشممنا النساء والأولاد قال: \"لو تكونون أو قال: لو أنكم تكونون على كل حال على الحال التى أنتم عليها ="],[11892,"١٨٩١ - أبو مازن (١) الأزدى الحدانى، كان من صلحاء الأزد قدم المدينة في زمن عثمان. روى قتادة عن صاحب (٢) له عنه."],[11893,"١٨٩٢ - أبو المُؤَمَّر (٣) الوائلى كوفى. رأى عليا رضي الله عنه. روى عنه سويد بن عبيد العجلى (٤) كذا قال الحاكم \"أبو المؤمر\" وقد قيل في هذا \"أبو"],[11894,"= عندى، لصافحتكم الملائكة بأكفهم ولزارتكم في بيوتكم، ولو لم تذنبوا لجاء اللَّه بقوم يذنبون كى يغفر لهم\" قال: قلنا يا رسول اللَّه حدثنا عن الجنة ما بناؤها؟ قال: لبنة من ذهب ولبنة من فضة. . \" الحديث."],[11895,"والحديث أخرجه الترمذى \"أبواب الجنة\" باب صفة الجنة ونعيمها (٧/ ٢٢٧) وقال: هذا حديث ليس إسناده بذاك القوى، وليس هو عندى بمتصل، وقد روى هذا الحديث بإسناد آخر عن أبى هريرة. اهـ."],[11896,"وأخرجه أيضا أبو بكر الشافعى في الفوائد (٧٣٢)، وأبو نعيم في صفة الجنة (ل/ ٢٤/ أ) و(ل/ ٣٩/ أ)."],[11897,"وذكره الهيثمى في مجمع الزوائد (١٠/ ٣٩٦) وقال: رواه البزار والطبرانى في الأوسط ورجاله رجال الصحيح. اهـ."],[11898,"١٨٩١ - كنى البخارى (ص ٧٤)، الجرح (٤/ ٢/ ٤٤٤)."],[11899,"(١) في كنى البخارى (ملز)."],[11900,"(٢) لعله سعيد بن يزيد البصرى. انظر ترجمة قتادة في تهذيب الكمال (٢/ ١١٢١) حيث ذكر المزى هناك أن قتادة يروى عن صاحبه سعيد بن يزيد البصرى. واللَّه أعلم."],[11901,"١٨٩٢ - كنى البخارى (ص ٧٤)، الجرح (٤/ ٢/ ٤٤٤)، تهذيب الكمال (٣/ ١٦٥٢)، الخلاصة (ص ٤٦١)، التهذيب (١٢/ ٢٥٢)، التقريب (٢/ ٤٧٩) وقال: مقبول، من الثالثة./ عس."],[11902,"(٣) في مصادر الترجمة \"المؤمن\" بالنون وزاد المزى وابن حجر \"ويقال: آخره راء\" وفى الخلاصة \"أبو المؤمّن: بتشديد الميم الثانية بعد الهمزة وضم الأولى\"."],[11903,"(٤) سويد بن عبيد العجلى: صاحب القصب، مقبول، من الثالثة، انظر التقريب: (١/ ٣٤١)."],[11904,"المؤمن\" كذلك ذكره ابن أبى حاتم."],[11905,"١٨٩٣ - أبو المُخَيَّس (١) - اليشكرى (٢). سمع أنس بن مالك والأحنف ابن قيس. (روى عنه الحكم بن عطية (٣) وعمرو بن ظِبيان البصرى (٤) (٥)."],[11906,"١٨٩٤ - (أبو مُزَاحِم (٦). سمع أبا هريرة. روى عنه يحيى بن أبى كثير يعد في أهل المدينة) (٧)."],[11907,"١٨٩٥ - أبو مُجَاشع (٨) الأزدى. روى عن عمر بن الخطاب، شامى روى"],[11908,"١٨٩٣ - كنى البخارى (ص ٧٤)، الجرح (٤/ ٢/ ٤٤٤)، الميزان (٤/ ٥٧١) وقال: لا يدرى من هو، اللسان (٧/ ١٠٤)، تعجيل المنفعة (ص ٣٣٩) وقال: مجهول، الاكمال (٧/ ٢٢٠)."],[11909,"(١) المخيس: قال ابن ماكولا: مُخَيس، بضم الميم وفتح الخاء المعجمة وبعدها ياء مشددة وبعدها سين مهملة. . وأبو المخيس السكونى. . ومن قال فيه \"مخلس\" باللام فقد أخطأ. اهـ. انظر الاكمال (٧/ ٢٢٠)."],[11910,"(٢) في كنى البخارى والإكمال \"السكونى\"."],[11911,"(٣) الحكم بن عطية، بصرى، صدوق، له أوهام، من السابعة. التقريب (١/ ١٩٢)."],[11912,"(٤) عمرو بن ظِبْيَان، بكسر الظاء عند أهل اللغة ذكره ابن أبى حاتم عن أبيه ولم يذكر فيه شيئًا. انظر الجرح (٣/ ١/ ٢٤١)."],[11913,"(٥) الحق في هامش الأصل."],[11914,"١٨٩٤ - كنى البخارى (ص ٧٤)، الجرح (٤/ ٢/ ٤٤٥)، تهذيب الكمال (٣/ ١٦٤٧) الميزان (٤/ ٥٧٣)، التهذيب (١٢/ ٢٣٣) التقريب (٢/ ٤٧٢) وقال مجهول، من الثالثة./ ت."],[11915,"(٦) مُزَاحِمْ: بمضمومة وبزاى، كسر مهملة. المغنى (ص ٧١)."],[11916,"(٧) الحقت هذه الترجمة بكاملها في هامش الأصل."],[11917,"١٨٩٥ - كنى البخارى (ص ٧٤)، الجرح (٤/ ٢/ ٤٤٥)، الميزان (٤/ ٥٦٩) اللسان (٧/ ١٠١)."],[11918,"قال الذهبى وتبعه ابن حجر: لا يعرف."],[11919,"(٨) مجاشع: بمضمومة وشين معجمة. المغنى (ص ٦٨)."],[11920,"عنه أبو بكر بن عبد اللَّه بن أبى مريم الغسانى."],[11921,"١٨٩٦ - أبو مَهْدِيَّة (١)، روى عن أبى أمامة الباهلى. روى عنه العلاء بن هلال الباهلى (٢)."],[11922,"١٨٩٧ - أبو المأموم (٣). وقيل: أبو المأمومة. سمع أبا هريرة. مدنى. سمع منه بكير بن عبد اللَّه بن الأشج."],[11923,"١٨٩٨ - أبو مسعر كوفى، روى عن سعيد بن جبير. روى عنه محمد بن جحادة. قال ابن أبى حاتم: \"سمعت أبا زرعة (و) (٤) سئل عن أبى مسعر الذى روى عنه محمد بن جحادة فقال: ما أعرفه (٥)."],[11924,"وقال الحاكم: \"قد قيل فيه: أبو معشر. والصواب أبو مسعر\"."],[11925,"١٨٩٦ - كنى البخارى (ص ٧٥)، الجرح (٤/ ٢/ ٤٤٦)، الميزان (٤/ ٥٧٧)، اللسان (٧/ ١١٢)."],[11926,"قال الذهبى: وتبعه ابن حجر لا يعرف."],[11927,"(١) في كنى البخارى والجرح \"مهدية\" بالدال المهملة."],[11928,"(٢) العلاء بن هلال الباهلى: فيه لين، من التاسعة (ت: ٢١٥) انظر التقريب (٢/ ٩٤)."],[11929,"١٨٩٧ - كنى البخارى (ص ٧٥)، الجرح (٤/ ٢/ ٤٤٦)، الميزان (٤/ ٥٦٧)، اللسان (٧/ ١٠٠)."],[11930,"قال الذهبى وتبعه ابن حجر: لا يعرف."],[11931,"(٣) في كنى البخارى \"أبو المأمومة\" فقط."],[11932,"١٨٩٨ - الجرح (٤/ ٢/ ٤٤٦)، الميزان (٤/ ٧٣)، اللسان (٧/ ١٠٥)."],[11933,"قال الذهبى وتبعه ابن حجر: لا يعرف."],[11934,"(٤) لم تكن في الأصل وهى مثبتة في الجرح."],[11935,"(٥) الجرح (٤/ ٢/ ٤٤٦)."],[11936,"١٨٩٩ - أبو معدان (١). ذكر إسحاق بن منصور عن يحيى بن معين أنه قال: أبو معدان صالح."],[11937,"١٩٠٠ - أبو محبوبة. قال: \"وجدت في زبور داود\". روى عنه الفضيل بن يحيى (٢). قال ابن أبى حاتم: \"سألت أبا زرعة عنه فقال: لا أعرفه (٣)."],[11938,"١٩٠١ - أبو المبارك، عن عطاء بن أبى رباح، روى عنه أبو فروه يزيد بن سنان - ليس بالمشهور."],[11939,"١٨٩٩ - كنى مسلم (ص ٩٨٨)، الجرح (٤/ ٢/ ٤٤٦) وقال: ذكره أبى عن إسحاق ابن منصور عن يحيى بن معين أنه قال: أبو معدان صالح. التهذيب (١٢/ ٢٤١) وقال: قال إسحاق بن منصور عن ابن معين أبو معدان صالح. أهـ، التقريب (٢/ ٢٧٤) وقال: مقبول من السابعة."],[11940,"(١) الذى في كنى مسلم والتهذيب والتقريب \"أبو معدان المكى عبد اللَّه بن معدان\"."],[11941,"١٩٠٠ - كنى البخارى (ص ٧٥)، الجرح (٤/ ٢/ ٤٤٦). المقتنى في سرد الكنى (١٢٤/ ب) وقال \"أبو محبوب\" فذكره."],[11942,"(٢) فضيل بن يحيى ذكره ابن أبى حاتم عن أبيه في الجرح (٣/ ٢/ ٧٦) فقال: روى عن أبى محبوبة روى عنه عبيد اللَّه بن الوليد الوصافى."],[11943,"وقال ابن أبى حاتم: سألت أبا زرعة عن فضيل بن يحيى فقال: لا أعرفه. وانظر اللسان (٤/ ٤٥٣)."],[11944,"(٣) الجرح (٤/ ٢/ ٤٤٦)."],[11945,"١٩٠١ - كنى البخارى (ص ٧٥)، الجرح (٤/ ٢/ ٤٤٦) الثقات (٧/ ٦٦٦)، الميزان (٤/ ٥٦٧) التهذيب (١٢/ ٢٢٠)، اللسان (٧/ ٤٨١)، التقريب (٢/ ٤٦٩). وقال: مجهول، من السادسة، وروايته عن صهيب مرسلة./ ت. ف."],[11946,"قال الذهبى: لا يدرى من هو وخبره منكر. . وقد أخرج الترمذى في الجامع \"أبواب فضائل القرآن\" (٨/ ٢٣٦) حديثا من طريق أبى فروة يزيد بن سنان عن أبى المبارك عن صهيب قال قال رسول اللَّه -صلى الله عليه وآله وسلم- \"ما آمن بالقرآن من استحل محارمه\" وقال عقبه: وأبو المبارك رجل مجهول. وأخرج ابن = ١٩٠٢ - أبو مسعدة الشامى، روى عنه سالم بن غيلان."],[11947,"١٩٠٣ - أبو المجبر. كوفى. روى عنه خالد المقرا. كان رجلا صالحا."],[11948,"١٩٠٤ - أبو معاوية الأسود الزاهد. قوله. روى عنه أحمد بن أبى الحوارى (١)."],[11949,"١٩٠٥ - أبو مجاهد العدوى، بصرى، عن عمر بن الخطاب. روى عنه حميد بن هلال العدوى."],[11950,"١٩٠٦ - أبو المخارق. كوفى. روى عن النبى عليه السلام، حديثا مرسلا. روى عنه الأعمش."],[11951,"= ماجه \"الزهد\" باب مجالسة الفقراء (٢/ ١٣٨١)."],[11952,"حديثا من طريق يزيد بن سنان، عن أبى المبارك عن عطاء، عن أبى سعيد الخدرى \"قال: أحبوا المساكين فإنى سمعت رسول اللَّه -صلى الله عليه وآله وسلم- يقول في دعائه \"اللهم أحينى مسكينا وأمتنى مسكينا وأحشرنى في زمرة المساكين\"."],[11953,"قال السندى: في الزوائد: أبو المبارك لا يعرف اسمه، وهو مجهول، ويزيد ابن سنان ضعيف. اهـ."],[11954,"١٩٠٢ - كنى البخارى (ص ٧٥)، الجرح (٤/ ٢/ ٤٤٦)."],[11955,"١٩٠٣ - لم أقف عليه."],[11956,"١٩٠٤ - حلية الأولياء (٨/ ٢٧١ - ٢٨٣) ذكر له ترجمة مطولة وذكر أنه روى عنه أحمد بن أبى الحوارى."],[11957,"(١) أحمد بن أبى الحوارى. ذكره ابن حجر في التقريب (١/ ١٤) وقال \"هو ابن عبد اللَّه بن ميمون./ د. ق\"."],[11958,"وقال في ترجمة أحمد بن عبد اللَّه بن ميمون، يكنى أبا الحسن بن أبى الحوارى، بفتح المهملة والواو الخفيفة كسر الراء ثقة زاهد، من العاشرة (ت: ٢٤٦)./ د. ق. التقريب (١/ ١٨)."],[11959,"١٩٠٥ - المقتنى في سرد الكنى (١٢٤/ أ)."],[11960,"١٩٠٦ - كنى البخارى (ص ٧٥)، الإصابة ٤/ ق ٤/ ١٩٣ وقال: ذكر في الصحابة ولا يصح، وذكره البخارى وقال: حديثه مرسل. اهـ."],[11961,"١٩٠٧ - أبو المورع. وقيل: أبو محمد (١). كوفى. عن على بن أبى طالب روى عنه الحكم بن عتيبة، أهل البصرة يكنونه أبا المورع. وأهل الكوفة يكنونه أبا محمد والحديث واحد (٢)."],[11962,"١٩٠٨ - أبو المعافى العكى (٣) بعثه عمر بن عبد العزيز بما أفا اللَّه على المسلمين إلى أهل فلسطين. قال: فلقد رأيته ببابه."],[11963,"روى عنه الهيثم بن خارجة (٤)."],[11964,"١٩٠٩ - أبو المعارك. عن أبى هريرة. روى عنه أبو سنان. قاله البخارى."],[11965,"١٩٠٧ - كنى مسلم (ص ٩٦٨)، الميزان (٤/ ٥٧٨) وقال: لا يعرف، اللسان (٧/ ١١٢)، تعجيل المنفعة (ص ٣٣٩)، التهذيب (١٢/ ٢٢٥)، التقريب (٢/ ٤٧٠) وقال: مجهول، من الثالثة عس."],[11966,"(١) أبو محمد هو الهذلى المتقدم في (١٧٤٨) وتقدم في ترجمته هناك أنه قيل فيه: \"أبو المورع\" أيضًا."],[11967,"(٢) الحديث ذكره المزى في تهذيب الكمال (٣/ ١٦٤٥) وابن حجر في التهذيب وفى اللسان وفى تعجيل المنفعة في ترجمة أبى محمد الهذلى ويقال: أبو المورع عن على عن رسول اللَّه -صلى الله عليه وآله وسلم- بعثه إلى المدينة وأمره أن يسوى القبور وعنه الحكم بن عتيبة. قال: كان رسول اللَّه -صلى الله عليه وآله وسلم- في جنازة فقال: أيكم يأتى المدينة فلا يدع فيها وثنا إلَّا كسَّره."],[11968,"الحديث مرسل. ونسبه المزى وابن حجر إلى النسائى في مسند على."],[11969,"١٩٠٨ - المقتنى في سرد الكنى (٣٠/ أ)."],[11970,"(٣) العكى: بفتح العين وتشديد الكاف - نسبة إلى عك بن عدنان أخى معد ابن عدنان، حالفوا اليمن ونزلوا في الأشعريين، وهم على نسبهم فيهم. وهى أيضًا نسبة إلى عكاء. وقيل: عكة المدينة الشامية. . اهـ اللباب (٢/ ٣٥٢)."],[11971,"(٤) في التقريب (٢/ ٣٢٦) الهيثم بن خارجة المروزى أبو أحمد أو أبو يحيى نزيل بغداد، صدوق، من كبار العاشر (ت: ٢٢٧)، في آخر يوم منها. التقريب (٢/ ٣٢٦)، وانظر الجرح (٤/ ٢/ ٨٦)."],[11972,"١٩٠٩ - المقتنى في سرد الكنى (٣٠/ أ)."],[11973,"١٩١٠ - أبو مَكِين بن أبان عن عكرمة مولى ابن عباس. روى عنه وكيع بن الجراح."],[11974,"١٩١١ - أبو مدرك. شامى عن عَبَاية بن رافع بن خديج (١) وحماد بن أبى سليمان، روى عنه عبد الرحمن بن ثابت بن ثوبان."],[11975,"١٩١٠ - أبو مكين بن أبان تقدم في أبى مكين نوح بن ربيعة."],[11976,"انظر الترجمة (٨٣٤) وقال ابن عبد البر في ترجمته هناك: \"قال فيه وكيع أبو مكين بن أبان أخو الحكم بن أبان فوهم فيه\". اهـ."],[11977,"وقال الدورى عن ابن معين في التاريخ (٢/ ٦١٢) أبو مكين بن أبان أخو الحكم بن أبان وقد أخطأ فيه وكيع إنما هو نوح بن ربيعة. وقال ابن أبى حاتم في الجرح (٤/ ١/ ٤٨٢) في ترجمة نوح بن ربيعة أبى مكين: كان وكيع يقول فيه: أبو مكين بن أبان أخو الحكم بن أبان يهم فيه. وذكر ابن حجر في التهذيب (١٠/ ٤٨٤ - ٤٨٥) في ترجمة نوح بن ربيعة أن أبا زرعة وأبا حاتم والدارقطنى قالوا: وهم وكيع في اسم أبيه فقال: حدثنا أبو مكين نوح بن أبان وإنما هو نوح بن ربيعة. . . وذكر ابن حجر أيضًا بأن مسلما وأبا أحمد الحاكم فرقا بين أبى مكين نوح بن ربيعة وبين أبى مكين ابن أبان وقال ابن حجر والصواب أنهما واحد وإن كيعا وهم في اسم أبيه. أهـ. وقال ابن حجر في التقريب (٢/ ٣٠٨) نوح بن ربيعة الأنصارى مولاهم أبو مكين بفتح الميم كسر الكاف البصرى، صدوق من السادسة وهم وكيع في اسم أبيه فقال: نوح بن أبان، ووهم من جعله اثنين. اهـ."],[11978,"١٩١١ - تاريخ دمشق (ل/ ٦٥٢) وقال: أبو مدرك أظنه عبد اللَّه بن مدرك، المقتنى في سرد الكنى (١٢٥/ أ)، الميزان (٤/ ٥٧١) اللسان (٧/ ١٠٤)."],[11979,"قال الذهبى وابن حجر: قال الدارقطنى: متروك."],[11980,"(١) في التقريب (١/ ٤٠٠) \"عبَايَة، بفتح أوله والموحدة الخفيفة وبعد الألف تحتانية خفيفة، ابن رفاعة بن رافع بن خديج الأنصارى الزرقى أبو رفاعة المدنى، ثقة، من الثالثة."],[11981,"قلت: نسب هنا إلى جده رافع."],[11982,"١٩١٢ - أبو ماجدة عن عبد اللَّه بن مسعود. روى عنه أيوب بن أبى تميمة من رواية شاذة عن أيوب قال أبو أحمد الحاكم: هكذا قال أبو خريم أبو ماجدة واراه غير أبى ماجد الحنفى الذى يروى عن ابن مسعود. وروى عنه يحيى بن عبد اللَّه الجابر. وقد قيل أنه أبو ماجد (١). واللَّه أعلم."],[11983,"١٩١٣ - أبو معانق. الأشعرى. عن أبى مالك الاشعرى. روى عنه ممطور الحبشى (٢)."],[11984,"١٩١٤ - أبو مُجِيْب الشامى. عن أبى ذر الغفارى وعن أبى هريرة. روى"],[11985,"= فقد ذكر ابن أبى حاتم عن أبيه في الجرح (٣/ ٢/ ٢٩) في ترجمته أنه سمع جده رافع بن خديج."],[11986,"١٩١٢ - المقتنى في سرد الكنى (١٢٢/ ب) وقال: أبو ماجد الحنفى، وقيل: أبو ماجدة عن ابن مسعود لين."],[11987,"وذكره ابن حجر للتمييز وقال: مجهول، من الثالثة ووهم من خلطه بالأول. انظر التقريب (٢/ ٤٦٨)."],[11988,"قلت: ويريد بالأول -هنا- أبا ماجد الحنفى المتقدم في (١٨٧٧)."],[11989,"(١) قال ابن حجر في التهذيب (١٢/ ٢١٧) في ترجمة أبى ماجد الحنفى فرق الحاكم أبو أحمد بين أبى ماجد الذى روى عنه يحيى الجابر وبين أبى ماجدة الذى روى عنه أيوب. . اهـ."],[11990,"١٩١٣ - الميزان (٤/ ٥٧٤)، اللسان (٧/ ١٠٨)."],[11991,"قال الذهبى، وتبعه ابن حجر: \"أبو معانق أو ابن معانق عن أبى مالك الأشعرى، قال الدارقطنى: لا شئ. اهـ."],[11992,"(٢) هو أبو سلام ممطور الحبشى."],[11993,"١٩١٤ - الميزان (٤/ ٥٦٩)، اللسان (٧/ ١٠١)، الاكمال (٧/ ٢١٤). في الميزان واللسان، \"أبو المجيب، شامى، عن أبى هريرة وعنه عبد الواحد الثقفى، وعبد اللَّه شيخ لشعبة\". . . الخ."],[11994,"وفى الاكمال \"أبو مجيب الشامى، سمع أبا ذر الغفارى، وشهد أبا هريرة ="],[11995,"عنه رجل. اختلف في اسمه. فقيل: عبد اللَّه بن عبد الواحد الثقفى. وقيل: عبد الواحد. وقيل: يحيى بن عبد الواحد الثقفى (١)."],[11996,"١٩١٥ - أبو مكرز عن أبى هريرة، روى عنه بكير بن عبد اللَّه بن الأشج. في أهل الحجاز."],[11997,"١٩١٦ - أبو المؤمل الشامى، روى عن الزهرى، روى عنه شعبة بن الحجاج."],[11998,"١٩١٧ - أبو المسافر (٢). وقيل: أبو المسافع. عن عمر بن الخطاب وعن"],[11999,"= روى عنه ابن عبد الواحد الثقفى، ويقال: عبد الواحد ويقال: يحيى بن عبد الواحد، ويقال: عبد اللَّه بن عبد الواحد، قاله شعبة أهـ."],[12000,"وأبو مجيب: بكسر الجيم وبعدها ياء ساكنة معجمة باثنتين من تحتها. كما في الاكمال."],[12001,"(١) يحيى بن عبد الواحد الثقفى، ذكره ابن حبان في الثقات (٧/ ٦٠٨) وقال: \"يروى عن أبى المجيب، عن أبى هريرة روى عنه شعبة بن الحجاج\" أهـ."],[12002,"وذكره البخارى في التاريخ الكبير (٤/ ٢/ ٢٩١) فقال \"يحيى بن عبد الواحد الثقفى\". . . الخ."],[12003,"وقال ابن حجر في اللسان (٦/ ٢٦٨) \"يحيى بن عبد الواحد الثقفى روى عنه الليث بن سعد. مجهول، وقيل عبد الواحد بن يحيى. وقيل: غير ذلك. ويروى عن شعبة عن أبى المجيب بحديث منكر\" اهـ. قلت: وقوله في اللسان \"يروى عن شعبة عن أبى المجيب خطأ. فيحيى هذا شيخ لشعبة كما سبق وان عرفت. واللَّه أعلم."],[12004,"١٩١٥ - المقتنى في سرد الكنى (١٣٣/ ب) وقال: أبو مكرز عن أبى هريرة وعنه ابن الأشج."],[12005,"١٩١٦ - كنى البخارى (ص ٧٥)، الجرح (٤/ ٢/ ٤٤٧)، الثقات (٧/ ٦٦٤)."],[12006,"١٩١٧ - كنى البخارى (ص ٧٥)، الجرح (٤/ ٢/ ٤٤٧)، الميزان (٤/ ٥٧٣)."],[12007,"(٢) في الجرح أيضًا \"أبو المسافر من أهل نهاوند، ويقال: أبو المسافع\"."],[12008,"وقال الذهبى: \"أبو مسافع، شيخ تفرد عنه أبو اسحاق، قال على: ="],[12009,"ابن عباس أيضًا. قيل: أنه من أهل نِهَاوَنْد (١). سكن الكوفة. روى عنه أبو إسحاق السبيعى."],[12010,"١٩١٨ - أبو ميسرة، مولى العباس بن عبد المطلب عن العباس بن عبد المطلب، روى عنه أبو قبيل حىّ بن هانئ."],[12011,"١٩١٩ - أبو المُفرِّج (٢) بن عطن بن عدى الضمرى في كتاب ابن أبى حاتم بن عطى بن عدى (٣). وفى كتاب الحاكم (٤) بن عطن بن مجدى. روى عن أبيه (٥) عن جده (٦). روى عنه محمد بن سليمان بن"],[12012,"= مجهول\" اهـ. انظر مصادر الترجمة."],[12013,"وقال ابن ماكولا في الاكمال (٧/ ٢٥٤): \"أبو مسافر، بالفاء من أهل نهاوند، روى عنه أبو إسحاق كناه محمد بن إسماعيل\" اهـ."],[12014,"(١) نِهَاوَنْد: بالكسر وتفتح، والواو مفتوحة، والنون ساكنه، ودال مهملة: مدينة عظيمة في قبلة همذان، بينهما ثلاثة أيام. انظر مراصد الاطلاع (٣/ ١٣٩٧)"],[12015,"١٩١٨ - تقدمت هذه الترجمة، انظر أبا ميسرة الهاشمى (١٨٧٥)."],[12016,"١٩١٩ - كنى البخارى (ص ٧٥)، الجرح (٤/ ٢/ ٤٤٧)، المقتنى في سرد الكنى (١٣٣/ أ) وقال: أبو المفرح بن عطاء الضمرى عن أبيه وعنه محمد بن سليمان السمؤل."],[12017,"(٢) مفرج بالفاء والجيم. الاكمال (٧/ ٢٠١)."],[12018,"(٣) انظر الجرح (٤/ ٢/ ٤٤٧)، وفى كنى البخارى أيضا \"أبو المفرج بن عطى ابن مجدى الضمرى\"."],[12019,"(٤) هو كتاب الأسماء والكنى المعروف."],[12020,"(٥) هو عطى بن مجدى الضمرى ذكره ابن أبى حاتم عن أبيه في الجرح (٣/ ١/ ٤٦) فقال: \"روى عن أبيه روى عنه ابنه أبو المفرج بن عطى هما مجهولان\" اهـ."],[12021,"(٦) هو مجدى الضمرى، ذكره ابن أبى حاتم عن أبيه في الجرح (٤/ ١/ ٤٢٧) فقال \"له صحبة، روى عنه ابنه عطى بن مجدى\" اهـ. وقال الذهبى في التجريد (٢/ ٥١)، \"مجدى الضمرى، غزا مع رسول اللَّه -صلى الله عليه وآله وسلم- سبع غزوات ="],[12022,"مسمول (١)."],[12023,"١٩٢٠ - أبو مقاتل، قوله، روى عن سعيد بن صالح (٢)."],[12024,"١٩٢١ - أبو المعطّل، مولى بنى كلاب، شامى أدرك معاوية بن أبى سفيان، ودخل عليه وسمع منه، ومن عمرو بن مرة الجهنى. روى عنه محمد بن شعيب ابن شابور."],[12025,"سئل عنه أبو زرعة فقال: ما أعرفه إلا في هذا الحديث، ولم يرو عنه غير محمد بن شعيب (٣)."],[12026,"١٩٢٢ - أبو المطوِّس. روى عن أبى هريرة عن النبى عليه السلام \"من أفطر"],[12027,"= فيما يروى عن ابنه عطى عنه\" اهـ. وانظر الإصابة (٣/ ٣٦٤). في ترجمة مجدى الضمرى وقال ابن حجر هناك \"أبو المفرّج في أوله ميم مع التشديد وأبو عطى بصيغة التصغير. اهـ."],[12028,"(١) محمد بن سليمان مسمول: قال ابن أبى حاتم عن أبيه في الجرح \"محمد ابن سليمان مسمول المكى المخزومى، وقال ابن أبى حاتم سألت أبى عنه فقال: ليس بالقوى ضعيف الحديث كان الحميدى يتكلم فيه\" اهـ."],[12029,"وفى اللسان (٥/ ١٨٥) \"محمد بن سليمان بن مشمول المشمولى المخزومى حجازى سكن مكة. . \" الخ."],[12030,"١٦٢٠ - المقتنى في سرد الكنى (١٣٣/ أ)."],[12031,"(٢) سعيد بن صالح. انظر ترجمته في الجرح (٢/ ١/ ٣٤)."],[12032,"١٩٢١ - الجرح (٤/ ٢/ ٤٤٨)، الميزان (٤/ ٥٧٥) وقال: لا يعرف."],[12033,"(٣) انظر الجرح (٤/ ٢/ ٤٤٨)."],[12034,"١٩٢٢ - الجرح (٤/ ٢/ ٤٤٨)، الميزان (٤/ ٥٧٤)، اللسان (٧/ ٤٨٣)، التهذيب (١٢/ ٢٣٨)، التقريب (٢/ ٤٧٣)، قال ابن حجر: لين الحديث، من السادسة./ عـ."],[12035,"ذكره ابن أبى حاتم فقال: أبو المطوس. روى عن أبى هريرة عن النبى -صلى الله عليه وآله وسلم- وذكر الحديث. قال ابن أبى حاتم: سئل أبى: هل يسمى؟ قال: لا. اهـ. ="],[12036,"يوما من رمضان\" (١)."],[12037,"= وذكره الذهبى: فقال: \"أبو المطوس عن أبيه اسمه يزيد بن مطوس، ضعف، روى عنه حبيب بن أبى ثابت، تفرد بحديثه عن أبيه عن أبى هريرة ثم ذكر الحديث وقال: لا يعرف لا هو ولا أبوه."],[12038,"وقال ابن حجر في اللسان: \"أبو المطوس اسمه يزيد أو عبد اللَّه، عن أبيه المطوس وأبى هريرة وعنه حبيب بن أبى ثابت، وثقه ابن معين. اهـ."],[12039,"وذكره ابن أبى حاتم أيضًا في الجرح (٢/ ٢/ ١٦٧) فقال \"عبد اللَّه بن المطوس أبو المطوس، روى عن أبى هريرة روى عنه عماره بن عمير وحبيب ابن أبى ثابت\" الخ. وقد علمت فيما سبق أن أبا حاتم قال لا يسمى. وذكر ابن أبى حاتم أيضًا في الجرح (٤/ ٢/ ٢٨٧) \"يزيد بن المطوس أبو المطوس روى عن أبيه. روى عنه عمارة بن عمير وحبيب بن أبى ثابت\". اهـ."],[12040,"وفى التهذيب: \"أبو المطوس: وقيل ابن المطوس، عن أبيه عن أبى هريرة من أفطر في رمضان. . ثم قال: قال أحمد: لا أعرفه ولا أعرف حديثه من غيره. وقال البخارى: لا أعرف له غير حديث الصيام ولا أدرى سمع أبوه من أبى هريرة أم لا؟ . ثم قال ابن حجر: من قال أبو المطوس أو ابن المطوس فقد أصاب. اهـ."],[12041,"وفى التقريب (٢/ ٢٥٤) \"المطوّس، بتشديد الواو المكسورة، ويقال: أبو المطوّس، عن أبى هريرة، مجهول، من الرابعة./ عـ. ثم قال في أبى المطوس (٢/ ٤٧٣) \"أبو المطوّس، هو يزيد، وقيل: عبد اللَّه بن المطوس لين الحديث، من السادسة./ عـ. مما سبق بتبين أنَّ أبا المطوس يطلق على الابن يزيد أو عبد اللَّه ويسمى الأب المطوس، لكن الأب يحتمل أنه روى عن أبى هريرة رضي الله عنه أما الابن فبعيد جدًا أن يكون روى عنه وإنما روى عن أبيه عنه. واللَّه أعلم."],[12042,"(١) الحديث أخرجه أحمد في المسند (٢/ ٣٨٦، ٤٤٢، ٤٥٨، ٤٧٠)، وأبو داود \"الصوم\" (٢/ ٣١٤)، والترمذى \"الصوم\" (٣/ ٤١٣)، وقال لا نعرفه إلا من هذا الوجه، وسمعت محمدا يقول: أبو المطوس اسمه يزيد بن المطوس="],[12043,"١٩٢٣ - أبو المَوَّالى (١)، وقيل: أبو الموال (٢)، سمع على بن أبى طالب روى عنه يحيى بن قيس (٣)."],[12044,"١٩٢٤ - أبو معان، بصرى، عن ابن سيرين، روى عنه عمار بن سيف (٤)."],[12045,"= ولا أعرف له غير هذا الحديث. اهـ. وابن ماجه \"الصيام\" (١/ ٥٣٥)، والدارمى \"الصوم\" (٢/ ١١) وابن خزيمة \"الصيام\" (٣/ ٢٣٨)، وابن أبى شيبة \"الصيام\" (٣/ ١٠٥). وعلقه البخارى في الصحيح \"الصوم\" (٤/ ١٦٠) ولفظ الحديث عند البخارى \"من أفطر يوما من رمضان من غير علة ولا مرض لم يقضه صيام الدهر وإن صامه\"، والباقون بنحو هذا اللفظ. قال ابن حجر الفتح (٤/ ١٦١) \"اختلف فيه على حبيب بن أبى ثابت اختلافا كثيرا فحصلت فيه ثلاث علل: الاضطراب، والجهل بحال أبى المطوس والشك في سماع أبيه من أبى هريرة. اهـ."],[12046,"والحديث ضعفه أيضًا القرطبى، والدميرى والبغوى. انظر فيض القدير (٦/ ٧٨)."],[12047,"١٩٢٣ - كنى البخارى (ص ٨٦)، الجرح (٤/ ٢/ ٤٤٧)."],[12048,"(١) في كنى البخارى والجرح \"أبو الموّال ويقال: أبو الموالى\" زاد في الكنى \"مولى على بن أبى طالب الهاشمى\"."],[12049,"(٢) الأولى بتشديد الواو، وهذه بتخفيف الواو. كما هو مضبوط في الأصل."],[12050,"(٣) ذكر ابن أبى حاتم في الجرح (٤/ ٢/ ٨٢) عن أبيه يحيى بن قيس. روى عن ابن المسيب وعن ابن أبى الموال مولى على بن أبى طالب أنه رأى عليا رضي الله عنه يشرب قائما، روى عنه بكير بن عبد اللَّه بن الأشج ويحيى بن مسلم ابن الأشج. اهـ."],[12051,"١٩٢٤ - كنى البخارى (ص ٧٥)، الجرح (٤/ ٢/ ٤٤٧)، الميزان (٤/ ٥٧٤) ديوان الضعفاء (ص ٣٦٦) وقال: لا يعرف، اللسان (٧/ ٤٨٣) وقال: مجهول."],[12052,"(٤) زاد في الجرح \"الضبى\"."],[12053,"١٩٢٥ - أبو مصلح (١)، عن الضحاك بن مزاحم، روى عنه النضر بن شميل."],[12054,"١٩٢٦ - أبو مخرمة من حديث ابن المبارك عن عبد الرحمن بن يزيد بن جابر عنه."],[12055,"١٩٢٧ - أبو المشرفى عن زياد بن كليب التميمى (٢). روى عنه هشيم بن بشير."],[12056,"١٩٢٥ - الجرح (٤/ ١/ ٤٧٠) وقال: سألت أبى عنه فقال: شيخ، تهذيب الكمال (٣/ ١٦٤٨)، المقتنى في سرد الكنى (١٢٨/ أ) وقال: خبره منكر، التهذيب (١٢/ ٢٣٨)، التقريب (٢/ ٤٧٣) وقال: لين الحديث، من السابعة./ ل."],[12057,"(١) الذى في تهذيب الكمال والتهذيب \"أبو مصلح الخراسانى، اسمه نصر بن مشارس، أو ابن مشيرس، روى عن الضحاك بن مزاحم. . روى عنه النضر بن شميل\"."],[12058,"١٩٢٦ - لم أقف عليه عند غير المؤلف."],[12059,"١٩٢٧ - المقتنى في سرد الكنى (١٢٨/ أ) وقال: \"أبو المشرق عن أبى معشر هو ليث. قلت: وقد تقدم أبو المشرفى ليث الواسطى. روى عن أبى مدثر زياد ابن كليب وآخرين، وروى عنه هشيم وآخرون\" انظر الترجمة (٨٤١)."],[12060,"(٢) هكذا في الأصل \"التميمى\" وقد تقدم في ترجمته في (٨١٩) أنه \"تيمى\" واللَّه أعلم."],[12061,"كتاب الاستغناء في معرفة المشهورين من حملة العلم بالكنى"],[12062,"«وهو مشتمل على ثلاثة كتب في الكنى»"],[12063,"تأليف"],[12064,"الحافظ أبي عمر يوسف بن عبد الله بن عبد البر النمري القرطبي (٣٦٨ هـ - ٤٦٣ هـ)"],[12065,"دراسة وتحقيق وتخريج"],[12066,"الدكتور عبد الله مرحول السوالمة"],[12067,"[الجزء الثالث]"],[12068,"النون"],[12069,"باب أبى نصر"],[12070,"١٩٢٨ - أبو نصر بن عمرو الكوفى عن على بن أبى طالب وعن عبد اللَّه ابن عمر. روى عنه مالك بن الحارث. وروى عنه ابنه أيضًا."],[12071,"١٩٢٩ - أبو نصر الأسدى. بصرى عن عبد اللَّه بن عباس. روى عنه خليفة ابن حصين بن قيس بن عاصم المنقرى (١). حديثه عند الثورى عن الأغر بن الصبّاح (٢) عن خليفة بن حصين عن أبى نصر عن ابن عباس أنه سأله عن ﴿وَ(٣) الْفَجْرِ وَلَيَالٍ عَشْرٍ﴾ (٤) (٥)، قال أبو زرعة: أبو نصر الأسدى الذى روى"],[12072,"١٩٢٨ - كنى البخارى (ص ٧٦)، الجرح (٤/ ٢/ ٤٤٨)، الميزان (٤/ ٥٧٩) وقال: قال البخارى: لم يعرف سماعه من ابن عباس."],[12073,"١٩٢٩ - كنى البخارى (ص ٧٦)، الجرح (٤/ ٢/ ٤٤٨)، التهذيب (١٢/ ٢٥٥) تهذيب الكمال (٣/ ١٦٥٣)، اللسان (٦/ ٤٨٦)، التقريب (٢/ ٤٨٠) وقال: مجهول، من الرابعة./ خت."],[12074,"(١) ثقة، من الثالثة./ د. ت. س. التقريب (١/ ٢٢٧) وانظر الجرح (١/ ٢/ ٣٧٧)."],[12075,"(٢) الأغر بن الصباح، التميمى، المنقرى، كوفى، ثقة، من السادسة./ د. ت. س. التقريب (١/ ٨٢)."],[12076,"(٣) لم تكن في الأصل، وهى مثبتة في الجرح."],[12077,"(٤) الفجر: ١ - ٢."],[12078,"(٥) الأثر أخرجه ابن جرير الطبرى في التفسير (٣٠/ ١٦٨ - ١٦٩ - ط - حلبى) من طريق سفيان عن الأغر المنقرى عن خليفة بن الحصين عن أبى نصر عن ابن عباس، قوله \"والفجر\" قال: النهار. وقال ابن جرير: وقال ="],[12079,"عن ابن عباس ثقة (١)."],[12080,"= آخرون: عنى به صلاة الصبح."],[12081,"وأخرج الطبرى أيضًا بهذا الإسناد عن ابن عباس \"وليال عشر\" قال: عشر الأضحى."],[12082,"وأخرجه أيضًا الحاكم (٢/ ٥٢٢) من طريق سفيان عن الأغر عن خليفة ابن حصين بن قيس عن أبى نصر عن ابن عباس رضي الله عنهما \"والفجر\" قال: فجر النهار. و\"ليال عشر\" قال: عشر الأضحى. وقال الحاكم: هذا حديث صحيح الإسناد ولم يخرجاه، وأبو نصر هذا هو الأسود بن هلال. ووافقه الذهبى فقال: مثال هذا القول أيضًا. والخبر ذكره أيضًا ابن أبى حاتم في الجرح (٤/ ٢/ ٤٤٨) وقد ساق البخارى في الكنى هذا الاسناد بتمامه في ترجمة أبى نصر ولم يذكر الخبر. وزاد نسبته السيوطى في الدر المنثور (٦/ ٣٤٤ - ٣٤٥) إلى الفريابى وابن أبى حاتم والبيهقى في شعب الإيمان وعبد بن حميد وابن المنذر وابن مردويه من حديث ابن عباس به. وذكره أيضًا ابن كثير في التفسير (٤/ ٥٠٥) من حديث ابن عباس ولم يعزه."],[12083,"(١) انظر الجرح (٤/ ٢/ ٤٤٩)."],[12084,"باب أبى النعمان"],[12085,"١٩٣٠ - أبو النعمان. روى عن المغيرة بن شعبة أنه أجَّل العنين سنة (١). كوفى."],[12086,"١٩٣٠ - كنى البخارى (ص ٧٦). المقتنى في سرد الكنى (١٣٩/ أ)."],[12087,"(١) الأثر: أخرجه ابن أبى شيبة (٤/ ٢٠٦) من طريق وكيع عن سفيان عن الركين عن أبى حنظلة التيمى عن المغيرة بن شعبة أنه أجل العنين سنة. وأخرجه الدارقطنى (٣/ ٢٠٦) من طريق سفيان عن الركين بن الربيع عن أبى النعمان قال: أتيت المغيرة بن شعبة في العنين فقال: يؤجل سنة."],[12088,"وأخرجه الدارقطنى أيضًا من طريق شعبة عن الركين عن أبى طلق عن المغيرة بن شعبة قال: العنين يؤجل سنة. وعند الدارقطنى من طريق الحجاج ابن أرطاة عن الركين بن الربيع عن حنظلة بن نعيم أن المغيرة بن شعبة أجله سنة من يوم رافعته، والأثر أخرجه عبد الرزاق في المصنف (٦/ ٢٥٤) وكيع في أخبار القضاة (٢/ ٢٦٧)، والبيهقى (٧/ ٢٢٦) من طريق سفيان عن الركين بن الربيع عن أبى النعمان قال: أتينا المغيرة بن شعبة رضي الله عنه في العنين فقال: يؤجل سنة. وأخرجه أيضًا البيهقى من طريق شعبة عن الركين عن أبى طلق عن المغيرة بن شعبة به. ومن طريق الحجاج بن أرطاة عن الركين بن الربيع عن حنظلة بن نعيم أن المغيرة بن شعبة رضي الله عنه أجله سنه من يوم رافعته."],[12089,"وتلاحظ الاختلاف على المغيرة في هذا الحديث فروى مرة عن أبى النعمان عنه. وروى أيضًا عن أبى طلق عنه، وعن أبى حنظلة عنه، وعن حنظلة عنه وقد أخرج البيهقى من طريق يحيى بن سعيد القطان قال: قيل لسفيان بن سعيد أن شعبة يخالفك في حديث المغيرة بن شعبة في العنين يؤجل سنة وترويان عن الركين تقول أنت أبو النعمان وهو يقول: هو أبو طلق. = ١٩٣١ - أبو النعمان عن سويد بن غفلة الحنفى. روى عنه زبيد بن الحارث اليامى. جعلهما (١) أبو أحمد الحاكم اثنين. فلا أدرى."],[12090,"١٩٣٢ - أبو النعمان عن أبى وقاص (٢) عن زيد بن أرقم. روى عن سلمان (٣)."],[12091,"روى عنه على بن عبد الأعلى الثعلبى (٤) قال أبو حاتم الرازى: هو مجهول (٥)."],[12092,"= فضحك سفيان وقال: كنت أنا وشعبة عند الركين فمر ابن لأبى النعمان يقال له: أبو طلق فقال الركين سمعت أبا أبى طلق فذهب على شعبة أبا أبى طلق فقال: أبو طلق."],[12093,"وذكر الشيخ الألبانى في إرواء الغليل (٦/ ٣٢٦) أن لفظ \"أبو حنظلة\" محرف وإنما هو \"أبو النعمان\". واللَّه أعلم."],[12094,"١٩٣١ - المقتنى في سرد الكنى (١٣٩/ أ)."],[12095,"(١) الضمير هنا عائد على أبى النعمان هذا والذى قبله وهو الراوى عن المغيرة بن شعبة."],[12096,"١٩٣٢ - كنى البخارى (ص ٧٦)، الثقات (٧/ ٦٦٤)، ديوان الضعفاء والمتروكين (ص ٣٦٨)، الميزان (٤/ ٥٨٠) وقال: قال الترمذى: مجهول، المقتنى في سرد الكنى (١٣٩/ أ)، اللسان (٧/ ٤٨٧)، الجرح (٤/ ٢/ ٤٤٩)، تهذيب الكمال (٣/ ١٦٥٣)، التهذيب (١٢/ ٢٥٨)، التقريب (٢/ ٤٨١) وقال: مجهول، من السادسة./ د. ت."],[12097,"(٢) أبو وقاص. قال ابن حجر في التقريب (٢/ ٤٨٧) \"أبو وقاص، شيخ لأبى النعمان، مجهول، من الثالثة\"./ د. ت. اهـ. وانظر التهذيب (١٢/ ٢٧٣)."],[12098,"(٣) هو سلمان الفارسى. كما صرح بذلك ابن حجر في ترجمة أبى النعمان صاحب هذه الترجمة."],[12099,"(٤) على بن عبد الأعلى الثعلبى: بالمثلثة والمهملة، الكوفى الأحول، صدوق، ربما وهم، من السادسة، التقريب (٢/ ٤٠)."],[12100,"(٥) الجرح (٤/ ٢/ ٤٤٩)."],[12101,"١٩٣٣ - أبو النعمان. عن إسماعيل بن أمية عن عمرو بن سعيد بن العاص (١). روى عنه الخضر بن محمد بن شجاع الأسدى الحرانى (٢)."],[12102,"١٩٣٤ - أبو النعمان الشامى. قال: حججت في ولاية عمر بن الخطاب. روى عنه خالد بن معدان الكلاعى."],[12103,"١٩٣٥ - أبو النعمان عن عبد اللَّه بن عمر بن الخطاب. كوفى حدث عنه خالد بن أبى أيوب (٣)."],[12104,"١٩٣٣ - المقتنى في سرد الكنى (١٣٩/ أ)."],[12105,"(١) عمرو بن سعيد بن العاص بن سعيد بن العاص بن أمية القرشى، الأموى، المعروف بالأشدق، تابعى، ولى أمرة المدينة لمعاوية ولابنه، قتله عبد الملك ابن مروان سنة سبعين، وهم من زعم أن له صحبة وإنما لأبيه رؤية، وكان مسرفا على نفسه، من الثالث./ م. د. ت. س. ق، التقريب (٢/ ٧٠)."],[12106,"(٢) صدوق، من العاشرة (ت: ٢٢١)./ س، والحرانى، بفتح الحاء وتشديد الراء، وفى آخرها نون - نسبة إلى حران، وهى مدينة بالجزيرة، وهى ديار ربيعة. انظر التهذيب (٣/ ١٤٥)، التقريب (١/ ٢٢٤) اللباب (١/ ٣٥٣)."],[12107,"١٩٣٤ - المقتنى في سرد الكنى (١٣٩/ أ)."],[12108,"١٩٣٥ - المقتنى في سرد الكنى (١٣٩/ أ)."],[12109,"(٣) خالد بن أبى أيوب، ذكره ابن أبى حاتم في الجرح (١/ ٢/ ٣٢٢) فقال: \"مدينى، روى عن أبيه، روى عنه أيوب بن خالد\". اهـ."],[12110,"باب أبى النضر"],[12111,"١٩٣٦ - أبو النضر (١) المازنى، روى عن الشعبى، روى عنه سلام بن مسكين الأزدى."],[12112,"١٩٣٧ - أبو النضر الأبار قال: ولد أنس بن مالك ثمانين ولدا (٢) ثمانية وسبعون ذكرا وابنتان واحدة تسمى حفصة والأخرى تكنى أم عمرو. روى عنه منصور بن المهاجر (٣)."],[12113,"١٩٣٨ - أبو النضر. سمع أنس بن مالك يقول: أشبه من رأيت بصلاة"],[12114,"١٩٣٦ - كنى البخارى (ص ٧٧)، الجرح (٤/ ٢/ ٤٥٠)، المقتنى في سرد الكنى (١٣٨/ ب)."],[12115,"(١) بالنون والضاد المعجمة."],[12116,"١٩٣٧ - المقتنى في سرد الكنى (١٣٨/ ب) قال ابن عبد البر في الترجمة الآتية بعد هذه: \"فيه نظر\"."],[12117,"(٢) في الإصابة (١/ ٧٢) عن أنس قال: قالت أم سليم -يعنى أم أنس يا رسول اللَّه أدع اللَّه لأنس فقال: اللهم أكثر ماله وولده وبارك له فيه قال أنس: لقد دفنت من صلبى سوى ولد ولدى مائة وخمسة وعشرين، وأن أرضى لتثمر في السنة مرتين\" أهـ."],[12118,"(٣) منصور بن المهاجر الواسطى، أبو الحسن، بياع القصب ويقال له: البُزُورى، بضم الموحدة، والزاى، مستور، من كبار العاشرة. انظر التقريب (٢/ ٢٧٧)."],[12119,"١٩٣٨ - الجرح (٤/ ٢/ ٤٥٠)."],[12120,"رسول اللَّه -صلى الله عليه وآله وسلم- عمر بن عبد العزيز (٤). روى عنه ابن لهيعة. فيه وفى الذى قبله نظر."],[12121,"(٤) الأثر: أخرجه ابن أبى حاتم في الجرح (٤/ ٢/ ٤٥٠) من طريق أبى النضر به."],[12122,"وأخرجه أيضًا ابن الجوزى في سيرة عمر بن عبد العزيز (ص ٢١) من طريق عامر بن عبد اللَّه بن الزبير ومن طريق زيد بن أسلم ومن طريق ربيعة بن أبى عبد الرحمن، ومن طريق سعيد بن جبير كلهم رووه عن أنس بن مالك رضي الله عنه. وذكره المزى في تهذيب الكمال في ترجمة عمر بن عبد العزيز (٢/ ١٠١٦)."],[12123,"باب أبى نعامة"],[12124,"١٩٣٩ - أبو نعامة الأسدى. كوفى عن خاله سمع عبد اللَّه بن عمر. روى عنه الحسن بن صالح بن حى."],[12125,"١٩٤٠ - أبو نعامة، شيخ من الحى، قال: اختصم إلى عبد الرحمن بن سمرة، حديثه عند يحيى بن أبى بكير عن أبى جهضم (١) عنه."],[12126,"١٩٣٩ - كنى البخارى (ص ٧٧)، الجرح (٤/ ٢/ ٤٤٩)، الميزان (٤/ ٥٨٠) اللسان (٧/ ١١٤)."],[12127,"قال الذهبى، وتبعه ابن حجر: لا يعرف."],[12128,"١٩٤٠ - كنى البخارى (ص ٧٧)، الجرح (٤/ ٢/ ٤٤٩)، الميزان (٤/ ٥٨٠) اللسان (٧/ ١١٤)."],[12129,"قال الذهبى، وتبعه ابن حجر: لا يعرف."],[12130,"في الكنى للبخارى زيادة في هذه الترجمة \"قال اختصم إلى عبد الرحمن ابن سمرة في سيل جاء قال: من أين؟ قالوا: من هاهنا نحو الجبان قال: فإن هذا جهد\" أهـ."],[12131,"(١) هو أبو جهضم الهجيمى المتقدم في (١٤٥٥)."],[12132,"باب أبى نصير"],[12133,"(١)"],[12134,"١٩٤١ - أبو نصير. روى عن الزهرى. روى عنه الربيع بن صَبِيح (٢) - هو مجهول."],[12135,"١٩٤٢ - أبو نصير الواسطى عن عمران بن سلمان العطاردى، روى عنه الضحاك بن حميرة الأملوكى، وسويد بن عبد العزيز السلمى."],[12136,"١٩٤٣ - أبو نصير عن مولى لأبى بكر الصديق. روى عنه عثمان بن واقد العمرى."],[12137,"١٩٤٤ - أبو نصير، عن أبى سعيد الخدرى، كوفى، روى عنه إبراهيم بن يزيد الكوفى، وهارون بن أبى إبراهيم."],[12138,"(١) نصير: بالصاد المهملة."],[12139,"١٩٤١ - الجرح (٤/ ٢/ ٤٤٩) وقال ابن أبى حاتم: \"سألت أبى عنه فقال: لا يعرف\""],[12140,"(٢) الربيع بن صَبِيح، بفتح المهملة السعدى، البصرى، صدوق، سئ الحفظ، وكان عابدا مجاهدا، قال الرامهرمزى: هو أول من صنف الكتب بالبصرة، من السابعة، (ت: ١٦٠)، التقريب (١/ ٢٤٥)."],[12141,"١٩٤٢ - المقتنى في سرد الكنى (١٣٨/ أ)."],[12142,"١٩٤٣ - كنى البخارى (ص ٧٦) وقال أبو نصيرة. المقتنى في سرد الكنى (١٣٨/ أ)."],[12143,"١٩٤٤ - كنى البخارى (ص ٧٦). المقتنى في سرد الكنى (١٣٨/ أ)."],[12144,"قلت: وقد تقدم أبو نصير هذا في الكتاب الثانى. انظر الترجمة (٨٨٥)."],[12145,"باب أبى نهيك"],[12146,"(١)"],[12147,"١٩٤٥ - أبو نَهِيك، عن عبد اللَّه بن عباس، وأبى زيد عمرو بن أخطب. روى عنه قتادة بن دعامة زياد بن سعد الخراسانى والحسين بن واقد."],[12148,"١٩٤٦ - أبو نَهِيك (عن) (٢) سلمان، وشهر بن حوشب، روى عنه العلاء ابن بدر (٣). في الكوفيين."],[12149,"(١) نهيك: بفتح النون، كسر هاء، وبكاف. تبصير المنتبه (٤/ ١٤٢٨) المغنى (ص ٨١)."],[12150,"١٩٤٥ - كنى البخارى (ص ٧٦)، كنى مسلم (ص ١٠٠٥)، تهذيب الكمال (٣/ ١٦٥٤)، التهذيب (١٢/ ٢٥٩)، التقريب (٢/ ٤٨٢) وقال: اسمه عثمان بن نَهِيك، ثقة، من الثالثة./ بخ. د."],[12151,"١٩٤٦ - الجرح (٤/ ٢/ ٤٤٩)، كنى البخارى (ص ٧٦)."],[12152,"(٢) لم تكن في الأصل وهى مثبته في مصادر الترجمة. والسياق يقتضيها."],[12153,"(٣) العلاء بن بدر هو العلاء بن عبد اللَّه بن بدر البصرى، قد ينسب إلى جده، ثقة، من السادسة./ مد. التقريب (٢/ ٩٢)."],[12154,"باب أفراد"],[12155,"١٩٤٧ - أبو نبيه (١). سمع عائشة قالت سمعت رسول اللَّه -صلى الله عليه وآله وسلم- يقول: \"ما تحت الكعبين من الإزار في (٢) النار\" (٣). روى عنه محمد بن إسحاق من حديث يوسف بن بهلول (٤) عن عبدة (٥) عن ابن إسحاق عنه."],[12156,"١٩٤٨ - أبو نَهْشل (٦). روى عن أبى وائل شقيق بن سلمة. روى عنه"],[12157,"١٩٤٧ - كنى البخارى (ص ٧٧)، الثقات (٥/ ٥٧١)، الجرح (٤/ ٢/ ٤٤٩) تعجيل المنفعة (ص ٣٤٢)."],[12158,"(١) في الثقات، والتعجيل أبو نبيه بن إبراهيم التيمى."],[12159,"(٢) في الجرح والثقات \"ففى\" بزيادة فاء."],[12160,"(٣) الحديت أخرجه أحمد في المسند (٦/ ٥٩ و٢٥٤ و٢٥٧) من طريق يعلى ابن عبيد ومحمد بن عبيد كلاهما عن محمد بن إسحاق قال سمعت أبا نبيه يقول: سمعت عائشة. فذكره."],[12161,"والحديث ذكره الهيثمى في مجمع الزوائد (٥/ ١٢٣) وعزاه لأحمد. وقال رجاله ثقات وقد صرح ابن إسحاق بالسماع. اهـ."],[12162,"وأخرج البخارى \"اللباس\" (١٠/ ٢٥٦) حديث أبى هريرة رضي الله عنه بلفظ \"ما أسفل من الكعبين من الإزار ففى النار\"."],[12163,"(٤) يوسف بن بهلول التيمى، الأنبارى، بفتح الهمزة وسكون النون، بعدها موحدة، نزيل الكوفة، ثقة، من العاشرة (ت: ٢١٨). انظر التقريب (٢/ ٣٧٩)."],[12164,"(٥) عبدة هو ابن سليمان. كما صرح بذلك المزى في تهذيب الكمال (٣/ ٥٥٨) في ترجمة يوسف بن بهلول."],[12165,"١٩٤٨ - كنى البخارى (ص ٧٧)، الثقات (٧/ ٦٦٣)، الجرح (٤/ ٢/ ٤٤٩)، الميزان (٤/ ٥٨١) تعجيل المنفعة (ص ٣٤٢)، اللسان (٧/ ١١٥) قال الذهبى: وتبعه ابن حجر: لا يعرف."],[12166,"(٦) نهشل، بالنون، والهاء وبعدها شين معجمة. انظر تبصير المنتبه (١/ ١٠٨)."],[12167,"عبد الرحمن بن عبد اللَّه المسعودى."],[12168,"١٩٤٩ - أبو النَّيل (١) الشامى، سمع عمر بن عبد العزيز، روى عنه الجراح ابن مليح الرؤاسى (٢)، من حديث وكيع عن أبيه."],[12169,"١٩٥٠ - أبو نمير شامى، روى عن القاسم بن مالك (٣) عن النبى عليه السلام مرسل، روى عنه معاوية بن صالح."],[12170,"١٩٥١ - أبو نعيم. روى عن محمد بن زياد السلمى (٤)، عن معاذ بن جبل، روى عنه مندل بن على."],[12171,"١٩٥٢ - أبو نافع، عن قيس بن سعد بن عبادة (٥). حدث عنه الجراح بن"],[12172,"١٩٤٩ - الجرح (٤/ ٢/ ٤٥٠)، الميزان (٤/ ٥٨١)، اللسان (٧/ ١١٦) الاكمال (٧/ ٣٦٩)."],[12173,"قال الذهبى وتبعه ابن حجر: لا يدرى من هو."],[12174,"(١) النيل: كما في الاكمال بكسر النون ويقال بفتحها. اهـ."],[12175,"(٢) الجراح بن مليح بن عدى الرؤاسى، والد وكيع، صدوق يهم، من السابعة (ت: ١٧٥) ويقال: (١٧٦)، التقريب (١/ ١٢٦) والرؤاسى: بضم الراء وفتح الواو المهموزة وفى آخرها السين المهملة - هذه النسبة إلى رؤاس وهو الحارث ابن كلاب بن ربيعة بن عامر بن صعصعة بن قيس عيلان. اهـ. كما في اللباب (٢/ ٤٠)."],[12176,"١٩٥٠ - كنى البخارى (ص ٧٧)، الجرح (٤/ ٢/ ٤٥٠)."],[12177,"(٣) في كنى البخارى والجرح \"الهيثم بن مالك\"."],[12178,"١٩٥١ - الجرح (٤/ ٢/ ٤٥٠)، الميزان (٤/ ٥٨٠)، اللسان (٧/ ١١٥) قال الذهبى وتبعه ابن حجر: مجهول."],[12179,"(٤) محمد بن زياد السلمى. ذكره ابن أبى حاتم في الجرح (٣/ ٢/ ٢٥٨) وقال: سألت أبى عنه فقال: مجهول."],[12180,"١٩٥٢ - المقتنى في سرد الكنى (١٣٧/ أ) وذكره كما هنا."],[12181,"(٥) قيس بن سعد بن عبادة الخزرجى الأنصارى، صحابى جليل، (ت: ٦٠) تقريبا وقيل بعد ذلك. التقريب (٢/ ١٢٨)."],[12182,"مليح البَهْرانى (١)."],[12183,"١٩٥٣ - أبو نُبَاته (٢)، عن شريح بن الحارث القاضى الكندى، كوفى روى عنه محمد بن عبيد اللَّه العَرْزَمى (٣)."],[12184,"١٩٥٤ - أبو النجم. واظنه العجلى الشاعر (٤). قال: سابق هشام بن عبد الملك (٥) الناس وكان مسبقا (٦)، روى عنه عامر بن عبد الملك."],[12185,"(١) الجراح بن مليح البَهْرانى بفتح الموحدة، أبو عبد الرحمن الحمصى، صدوق، من السابعة. التقريب (١/ ١٢٦)."],[12186,"١٩٥٣ - المقتنى في سرد الكنى (١٣٧/ أ)."],[12187,"(٢) نباتة: بضم الميم. تبصير المنتبه (٤/ ١٤٠٦)."],[12188,"(٣) محمد بن عبيد اللَّه بن أبى سليمان العَرْزَمى، بفتح المهملة والزاى بينهما راء ساكنة نسبة إلى عرزم قال السمعانى: وظنى أنها بطن من فزاره وجبَّانة عرزم بالكوفة معروفة ولعل هذا البطن نزلوا بها فنسب إليهم. اهـ. ومحمد العرزمى هذا متروك، من السادسة، مات سنة بضع وخمسين بعد المائة انظر التقريب (٢/ ١٨٧)، اللباب (٢/ ٣٣٤)."],[12189,"١٩٥٤ - المقتنى في سرد الكنى (١٣٧/ أ)."],[12190,"(٤) أبو النجم العجلى الشاعر. هو الراجز الفضل بن قدامة من عجل وكان ينزل بسواد الكوفة في موضع يقال له \"الفرك\" اقطعه إياه هشام بن عبد الملك."],[12191,"انظر طبقات الشعراء لمحمد بن سلام الجمحى ص ١٤٨ - ١٥٠ والشعر والشعراء لابن قتيبة ص ٣٠٢ - ٣٠٥، المعارف لابن قتيبة (ص ٩٧)."],[12192,"(٥) هشام بن عبد الملك. أبو الوليد ولد سنة نيف وسبعين، واستخلف بعهد من أخيه يزيد، وكان حازما عاقلا، مات في ربيع الآخر سنة خمس وعشرين ومائه. انظر تاريخ الخلفاء للسيوطى (ص ٢٤٧ - ٢٥٠)."],[12193,"(٦) أخرج ابن قتيبة في الشعر والشعراء (ص ٣٠٣) قال: \"كان هشام بن عبد الملك مسبقا لا يكاد يسبق فسبق ذات يوم على فرس له أنثى وصلى؟ ="],[12194,". . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . ."],[12195,"= على ابنها ففرح وقال: علىَّ بالشعراء قال أبو النجم فدعينا فقيل لنا: قولوا في هذه الفرس السابقة وفى ابنها فقال أصحاب القصيد أنظرنا حتى نقول. وقلت في مقامى ذلك: هل لك في رجل ينقذك إذا استنسئوك قال: هاته فقلت من ساعتى:"],[12196,"أشاع للغراء فينا ذكرها ... قوائم عوج أطعن أمرها"],[12197,"فذكر قصيدة طويله له."],[12198,"قلت: وهذا يؤيد أن يكون أبو النجم هذا هو أبو النجم العجلى الشاعر. واللَّه أعلم."],[12199,"الصاد"],[12200,"باب أبى صالح"],[12201,"١٩٥٥ - أبو صالح الأشعرى. شامى، روى عن أبى ريحانة (١) وأبى أمامة الباهلى. وسمع منهما. روى عنه حسان بن عطيه وأبو سلام الأسود."],[12202,"ذكر ابن أبى حاتم قال: نا محمد بن عوف قال: نا أبو مسهر (٢) قال: نا هقل قال: نا الأوزاعى، عن حسان بن عطية عن أبى صالح الأشعرى (٣) قال ابن معين: روى أبو صالح الأشعرى عن أبى عبد اللَّه الأشعرى (٤) وأبى ريحانة وأبى أمامة (٥). قال ابن أبى حاتم: \"سألت أبى عن أبى صالح الأشعرى فقال: لا بأس به (٦) \" \"وسئل أبو زرعة عن أبى صالح الأشعرى فقال: ثقة. روى عنه حسان بن عطية وأبو سلام الأسود وإسماعيل بن عبيد اللَّه (٧)، ولا يعرف اسمه\" (٨)."],[12203,"١٩٥٥ - ذكرت هذه الترجمة في هامش كنى البخارى (ص ٤٣)، كنى الدولابى (٢/ ١٠) تاريخ ابن معين (٢/ ٧١١)، كنى مسلم (ص ٥١٩)، كنى الحاكم (١/ ٢٣٥/ ب)، الجرح (٤/ ٢/ ٣٩٢)، الميزان (٤/ ٥٣٨)، التهذيب (١٢/ ١٣١)، التقريب (٢/ ٤٣٦). وقال، مقبول، من الثالثة./ ق."],[12204,"(١) هو الصحابى شمعون."],[12205,"(٢) هو عبد الأعلى بن مسهر."],[12206,"(٣) الجرح (٤/ ٢/ ٣٩٢)."],[12207,"(٤) أبو عبد اللَّه الأشعرى يأتى في (٢٠٠٢)."],[12208,"(٥) انظر التاريخ (٢/ ٧١٠ - ٧١١)."],[12209,"(٦) انظر الجرح (٤/ ٢/ ٣٩٢)."],[12210,"(٧) إسماعيل بن عبيد اللَّه بن المهاجر المخزومى، مولاهم، الدمشقى، أبو عبد الحميد، ثقة من الرابعة، (ت: ١٣١). التقريب (١/ ٧٢)."],[12211,"(٨) الجرح (٤/ ٢/ ٣٩٢) لكن ليس فيه كلمة \"ثقة\"."],[12212,"١٩٥٦ - أبو صالح مولى عثمان بن عفان. روى عن عثمان وأبى هريرة."],[12213,"روى عنه زهرة بن معبد (١)، وقيل: روى عنه مروان بن رؤبة التَّغلِبِى (٢). جعله البخارى الأول فغلط."],[12214,"١٩٥٧ - أبو صالح الحادى. روى عن النعمان بن بشير. روى عنه أبو قلابة الجرمى. سئل أبو زرعة عن أبى صالح الحادى فقال: روى عنه أبو قلابة الجرمى. (سئل أبو زرعة عن أبى صالح الحادى فقال: روى عنه أبو قلابة) (٣) لا يعرف اسمه (٤)."],[12215,"١٩٥٦ - تقدم في الكتاب الثانى، انظر الترجمة \"٨٩٧\" وتقدم في ترجمته هناك أنه قيل في اسمه: الحارث، وقيل \"بركان\"."],[12216,"(١) زهرة، بضم أوله ابن معبد بن عبد اللَّه بن هشام القرشى التيمى أبو عقيل المدنى، نزيل مصر، ثقة عابد، من الرابعة (ت: ١٢٧)./ خ. عـ. التقريب (١/ ٢٦٣)."],[12217,"(٢) مروان بن رؤبة التَّغلبى، بفتح المثناة من فوق وسكون الغين المعجمة كسر اللام والباء الموحدة - نسبة إلى تَغْلِب وهى قبيلة معروفة وهى تغلِب بن وائل ابن قاسط، ومروان هذا، حمصى، مقبول، من الخامسة، / د. انظر التقريب (٢/ ٢٣٩، اللباب (١/ ٢١٧)."],[12218,"١٩٥٧ - كنى ابن منده (١٦٠/ أ) وقال: أبو صالح الحمادى، الثقات (٥/ ٥٨٩) الجرح (٤/ ٢/ ٣٩٢)، كنى الحاكم (١/ ٢٣٦/ ب)، الميزان (٤/ ٥٣٩) وقال: لا يعرف ما حدث عنه غير أبى قلابة، التهذيب (١٢/ ١٣١)، التقريب (٢/ ٤٣٦) وقال: مقبول، من الخامسة./ سى."],[12219,"(٣) كذا هو مكرر في الأصل."],[12220,"(٤) انظر الجرح (٤/ ٢/ ٣٩٢)."],[12221,"١٩٥٨ - أبو صالح مولى الساعديين (١) (وقيل: مولى السعديين) (٢) ويقال: أبو صالح السعدى. سمع أبا هريرة كعب الاحبار. روى عنه هاشم بن هاشم (٣) وشريك بن عبد اللَّه بن أبى نمر. سئل أبو زرعة عن أبى صالح مولى الساعديين فقال: مدنى معروف لا يعرف اسمه (٤)."],[12222,"١٩٥٩ - أبو صالح الخولانى، عن أبى هريرة، ومرة بن كعب (٥). روى عنه عاصم الاحول، وعامر الاحول، سئل أبو حاتم عن أبى صالح الخولانى فقال: \"لا بأس به (٦) \"."],[12223,"١٩٦٠ - أبو صالح مولى حكيم بن حزام، روى عن حكيم بن حزام. روى عنه أبو الزبير المكى."],[12224,"١٩٥٨ - كنى البخارى (ص ٤٣)، كنى مسلم (ص ٥١٩)، الجرح (٤/ ٢/ ٣٩٢)، الثقات (٥/ ٥٩٠)، كنى ابن منده (١٦٠/ أ)."],[12225,"(١) في كنى مسلم \"السعديين\". وفى كنى البخارى \"السعدى\". وفى الثقات \"الشعثى\" وفى الجرح \"مولى السعديين، ويقال: أبو صالح السعدى\"."],[12226,"(٢) الحق في الهامش. كتب عنده كلمة \"صح\"."],[12227,"(٣) هاشم بن هاشم بن عتبة بن أبى وقاص الزهرى، المدنى، ويقال: هاشم بن هاشم بن هاشم، ثقة، من السادسة، مات سنة بضع وأربعين ومائة التقريب (٢/ ٣١٤)."],[12228,"(٤) الذى في الجرح (٤/ ٢/ ٣٩٢) قال أبو زرعة. روى عنه شريك بن عبد اللَّه ابن أبى نمر وهاشم بن هاشم، لا بأس به، ولا يعرف اسمه\" أهـ."],[12229,"١٩٥٩ - كنى البخارى (ص ٤٣)، كنى الحاكم (١/ ٢٣٦/ ب)، الجرح (٤/ ٢/ ٣٩٢) الثقات (٥/ ٥٨٩)."],[12230,"(٥) مرة بن كعب. وقيل: كعب بن مرة السلمى البهزى، وقيل: هما اثنان نزل الشام. اهـ. التجريد (٢/ ٧٠)."],[12231,"(٦) الجرح (٤/ ٢/ ٣٩٢) وزاد قوله \"سئل أبو زعة عن أبى صالح الخولانى فقال روى عنه عامر الاحول لا يعرف اسمه\" أهـ."],[12232,"١٩٦٠ - كنى ابن منده (١٥٩/ أ) كنى الحاكم (١/ ٢٣٥/ أ)، الميزان (٤/ ٥٣٩) = ١٩٦١ - أبو صالح، مولى جبير بن مطعم، روى عن جبير بن مطعم، روى عنه الحارث بن يزيد. قال أبو زرعة: \"لا يعرف اسمه\" (١)."],[12233,"١٩٦٢ - أبو صالح الخوزى (٢) عن أبى هريرة عن النبى عليه السلام أنه قال: \"من لم يسأل اللَّه يغضب عليه\" (٣). روى عنه أبو المليح الفارسى (٤). سئل أبو زرعة عن اسم أبى صالح الخوزى فقال: \"لا يعرف اسمه، ليس به بأس\" (٥)."],[12234,"= وقال: لا يعرف. يقع حديثه عاليا في نسخة أبى الجهم. متنه \"ابدأ بمن تعول\". اهـ وكذا قال ابن حجر في اللسان (٧/ ٦٥)."],[12235,"١٩٦١ - الجرح (٤/ ٢/ ٣٩٣) المقتنى في سرد الكنى (٧٢/ ب)."],[12236,"(١) انظر الجرح (٤/ ٢/ ٣٩٣)."],[12237,"١٩٦٢ - كنى مسلم (ص ٥٢٠)، كنى ابن منده (١٦٠/ ب)، كنى الحاكم (١/ ٢٣٦/ أ)، الجرح (٤/ ٢/ ٣٩٣)، تهذيب الكمال (٣/ ١٦١٥) ديوان الضعفاء (ص ٣٥٩)، الميزان (٤/ ٥٣٨)، التهذيب (١٢/ ١٣١) التقريب (٢/ ٤٣٦) وقال: لين الحديث، من الثالثة./ بخ. ت. ق، الكامل لابن عدى (٣/ ٢٥٨ - ٢٥٩)."],[12238,"(٢) في التقريب \"الخوذى\" بالذال."],[12239,"(٣) الحديث أخرجه أحمد في المسند (٢/ ٤٤٢ و٤٤٣ و٤٧٧)، والترمذى \"الدعوات\" (٩/ ٣١٣) وقال: لا نعرفه إلا من هذا الوجه، وابن ماجه في \"الدعاء\" (٢/ ١٢٥٨)، والحاكم \"الدعاء\" باب من لا يدعوا اللَّه يغضب عليه (١/ ٤٩١) وقال: هذا حديث صحيح الاسناد فان أبا صالح الخوزى وأبا المليح الفارسى لم يذكرا بالجرح، إنما هما في عداد المجهولين لقلة الحديث، والبخارى في الأدب المفرد (ص ١٧١)، وابن عدى في الكامل (٣/ ٢٥٩)، كلهم أخرجوه من طريق أبى المليح عن أبى صالح به. وزاد نسبته المباكفورى في تحفة الأحوذى (٩/ ٣١٤) أيضا إلى البزار من حديث أبى هريرة رضي الله عنه."],[12240,"(٤) أبو المليح الفارسى هو المتقدم في (٨١٧)."],[12241,"(٥) انظر الجرح (٤/ ٢/ ٣٩٣)."],[12242,"وقال على: \"روى عنه بعض أهل البصرة لا أعرف اسمه. روى عنه أبو المليح الفارسى (١)."],[12243,"١٩٦٣ - أبو صالح، الأنصارى الحمصى، قال: \"قدمت حمص أول ما فتحت (٢)، روى عنه (٣) صفوان بن عمرو."],[12244,"١٩٦٤ - أبو صالح البزاز. رأى الحسن والحسين (٤)، وروى عنهما وعن أم كلثوم بنت على (٥)، أختهما. روى عنه أبو البخترى الطائى (٦) ثقة."],[12245,"١٩٦٥ - أبو صالح مولى عمر بن الخطاب (٧). روى عنه عبد الرحمن بن القاسم (٨) وروى العوام بن حوشب عن رجل عنه."],[12246,"(١) لم أقف على قول ابن المدينى هذا."],[12247,"١٩٦٣ - كنى البخارى (ص ٤٣)، كنى ابن منده (١٦١/ أ)، الجرح (٤/ ٢/ ٣٩٣)."],[12248,"(٢) ومثله في مصادر الترجمة."],[12249,"(٣) في الجرح \"روى صفوان بن عمرو عن مروان بن رؤبة عنه\"."],[12250,"١٩٦٤ - كنى البخارى (ص ٤٣)، كنى مسلم (ص ٥٢٠)، كنى ابن منده (١٥٩/ أ) الجرح (٤/ ٢/ ٣٩٣)، كنى الحاكم (١/ ٢٣٦/ أ)."],[12251,"(٤) الحسين بن على بن أبى طالب الهاشمى، أبو عبد اللَّه المدنى، سبط رسول اللَّه -صلى الله عليه وآله وسلم- وريحانته، حفظ عنه، استشهد يوم عاشوراء سنة (٦١). وله ست وخمسون سنة./ ع."],[12252,"(٥) أم كلثوم بنت على بن أبى طالب من فاطمة رضي الله عنها ولدت قبل وفاة جدها -صلى الله عليه وآله وسلم-، تزوجها عمر على صداق أربعين الفا فولدت له زيدا رقية وتزوجت بعده بعون بن جعفر. التجريد (٢/ ٣٣٣)."],[12253,"(٦) هو سعيد بن كلثوم."],[12254,"١٩٦٥ - كنى الدولابى (٢/ ١٠)، الثقات (٥/ ٥٩١)، الجرح (٤/ ٢/ ٣٩٣)، تعجيل المنفعة (ص ٣٢٥) وقال: روى عنه رجل لم يسم، تاريخ ابن معين (٢/ ٧١٠)."],[12255,"(٧) في الثقات زيادة \"يروى، عن عمر بن الخطاب\"."],[12256,"(٨) عبد الرحمن بن القاسم بن محمد بن أبى بكر الصديق التيمى، أبو محمد ="],[12257,"١٩٦٦ - أبو صالح العطار. روى عن معاوية بن أبى سفيان. روى عنه ابنه يزيد بن أبى صالح (١)."],[12258,"١٩٦٧ - أبو صالح الاحمسى المؤذن. روى عن (مر) (٢) المؤذن. روى عنه أهل اليمن. وروى عنه النعمان بن الزبير الصنعانى (٣)."],[12259,"١٩٦٨ - أبو صالح مولى البراء (٤). حديثه عند بكير بن الاشج عن عبيد اللَّه"],[12260,"= المدنى، ثقة جليل، قال ابن عيينة: كان أفضل أهل زمانه، من السادسة (ت: ١٢٦)، وقيل: بعدها. التقريب (١/ ٤٩٥)."],[12261,"١٩٦٦ - كنى البخارى (ص ٤٤)، كنى الحاكم (١/ ٢٣٦/ أ)، الثقات (٥/ ٥٩٠) الجرح (٤/ ٢/ ٣٩٣)، كنى ابن منده (١٦١/ أ)."],[12262,"(١) يزيد بن أبى صالح أبو حبيب الدباغ روى عن أنس، وروى عنه حماد بن زيد وكيع وأبو نعيم، وثقة ابن معين وقال أبو حاتم: ليس بحديثه بأس وكان أوثق من بقى بالبصرة من أصحاب أنس، وقال أبو زرعة. لا بأس به."],[12263,"انظر الجرح (٤/ ٢/ ٢٧٢)."],[12264,"١٩٦٧ - كنى البخارى (ص ٤٤)، الجرح (٤/ ٢/ ٣٩٤)، كنى الحاكم (١/ ٢٣٦/ ب)، الميزان (٤/ ٥٣٩) وقال: أبو صالح الاحمسى عن مر المؤذن، عن عمر وعنه النعمان بن الزبير - لا يعرفون، اللسان (٧/ ٦٥)."],[12265,"(٢) في الأصل (مرة) والتصحيح عن مصادر الترجمة وهو الصواب وقال ابن أبى حاتم في الجرح (٤/ ١/ ٤٣٠) مر المؤذن، وذكر روايته عن عمر وفيروز الديلمى، ورواية أبى صالح الاحمسى عنه\"."],[12266,"(٣) النعمان بن الزبير الصنعانى، ذكره ابن أبى حاتم في الجرح (٤/ ١/ ٤٤٨) وقال: ذكره أبى عن اسحاق بن منصور عن يحيى بن معين أنه قال: النعمان ابن الزبير ثقة. اهـ."],[12267,"١٩٦٨ - كنى البخارى (ص ٤٣)، الجرح (٤/ ٢/ ٣٩٤)، المقتنى في سرد الكنى (٧٢/ ب)."],[12268,"(٤) زاد في كنى البخارى \"بن عبيد عمرو\" وفى الجرح (بن عبد عمرو وقال في التجريد (١/ ٤٦): البراء بن عبد عمرو بن عبيد بن قمية الساعدى شهد ="],[12269,"ابن مقسم (١) عنه."],[12270,"١٩٦٩ - أبو صالح العقيلى. روى عن أبى العلاء بن الشخير. روى عنه أبو هلال محمد بن سليم الراسبى."],[12271,"١٩٧٠ - أبو صالح مولى الجُنْدَ عِيِّين (٢)، عن أبى هريرة. روى عنه سليمان ابن يسار. وقد اختلفوا في هذا الاسناد. فقال بعضهم: عن أبى عبد اللَّه مولى الجندعيين (٣)."],[12272,"١٩٧١ - أبو صالح شامى. روى عن عكرمة عن ابن عباس حديثا منكرًا قال أبو أحمد الحاكم: هو حديث موضوع يشبه حديث القصاص عن ابن عباس قال: قال على بن أبى طالب يا رسول اللَّه \"إِن القرآن يفلت من"],[12273,"= أحدا وهو والد عمرو بن البراء. وفى الإصابة (١/ ١٤٣): البراء بن عمرو بن عبد الرحمن بن عبيد بن قميه بن عامر بن عوف بن حارثة بن عمرو بن الخزرج الخزرجى الساعدى. . شهد أحدًا. اهـ."],[12274,"(١) عبيد اللَّه بن مقسم المدنى، ثقة، مشهور، من الرابعة. التقريب (١/ ٥٣٩)."],[12275,"١٩٦٩ - كنى مسلم (ص ٥٢٠)، كنى ابن منده (١٦١/ أ)، المقتنى في سرد الكنى (٧٢/ أ)، الجرح (٤/ ٢/ ٣٩٤)، كنى الحاكم (١/ ٢٣٦/ ب)."],[12276,"١٩٧٠ - كنى الحاكم (١/ ٢٣٦/ أ) كنى ابن منده (١٦٠/ ب)."],[12277,"(٢) الجُنْدَعيين: بضم الجيم رسكون النون وفتح الدال المهملة كسر العين - نسبة إلى جُنْدع، وهو بطن من ليث بن بكر بن عبد مناة بن مناة. اهـ. اللباب (١/ ٢٩٥)."],[12278,"(٣) قال أبو أحمد الحاكم \"وقد اختلفوا في هذا الاسناد فقال بعضهم، عن أبى عبد اللَّه مولى الجندعيين. اهـ."],[12279,"١٩٧١ - كنى الحاكم (١/ ٢٣٥/ ب). الميزان (٤/ ٥٣٨) وفيه \"أبو صالح صت عكرمة عن ابن عباس. لا يعرف، وجاء بحديث باطل. فيقال: هو اسحاق ابن نجيح\" أهـ. وتبعه ابن حجر أيضا فقال مثل هذا، اللسان (٧/ ٦٥)."],[12280,"صدرى\" فساق حديثا طويلا منكرا. قال: وأبو صالح هذا مجهول وحديثه منكر (١)، (٢)."],[12281,"(١) انظر الكنى (١/ ٢٣٥ - ٢٣٦)."],[12282,"(٢) الحديث أخرجه أبو أحمد الحاكم من طريق محمد بن إبراهيم القرشى قال: حدثنى أبو صالح عن عكرمة عن ابن عباس قال: قال على بن أبى طالب: يا رسول اللَّه ان القرآن ينفلت من صدرى فقال النبى -صلى الله عليه وآله وسلم- ألا اعلمك كلمات ينفعك اللَّه بهن وينتفع من علمته ويثبت ما تعلمت في صدرك قال: بلى. قال: فصل ليلة الجمعة أربع ركعات تقرأ في الركعة الأولى بفاتحة الكتاب ويس، وفى الثانية تقرأ في فاتحة الكتاب وحم الدخان وفى الثالثة بفاتحة الكتاب والم تنزيل السجدة. وفى الرابعة بفاتحة الكتاب وتبارك المفَصل فإذا فرغت من التشهد فاحمد اللَّه واثن عليه وصل على النبيين واستغفر للمؤمنين ثم قل: اللهم ارحمنى بترك المعاصى ابدا ما ابقيتنى وارحمنى من أن اتكلف ما لا يعنينى وارزقنى حسن النظر فيما ترضه عنى اللهم بديع السموات والأرض ذا الجلال والاكرام والعزة التى لا ترام اسألك يا اللَّه يا رحمن أن تنور بكتابك بصرى وتطلق به لسانى وتفرج به عن قلبى وتشرح به صدرى وتستعمل به بدنى وتقوينى على ذلك وتعيننى عليه فانه لا يعين على الخير غيرك ولا يوفق له إلا أنت \"تفعل ثلاث جمع أو خمسا أو سبعا كان باذن اللَّه وما أخطأ مؤمن قط\" فأتى النبى -صلى الله عليه وآله وسلم- بعد ذلك بسبع جمع فأخبره بحفظ القرآن والأحاديث فقال النبى -صلى الله عليه وآله وسلم- مؤمن ورب الكعبة أبا حسن علم علم\". وقال الحاكم: هذا حديث منكر وأبو صالح هذا رجل مجهول. وحديثه هذا يشبه حديث القصاص. اهـ."],[12283,"وأخرج أيضا الترمذى \"الدعوات\" باب في دعاء الحفظ (٩/ ١٨ - ٢١) من طريق الوليد بن مسلم أخبرنا ابن جريح عن عطاء بن أبى رباح وعكرمة مولى ابن عباس عن ابن عباس أنه قال بينما نحن عند رسول اللَّه -صلى الله عليه وآله وسلم- إذ جاءه على بن أبى طالب فقال: بأبى انت وأمى تفلت هذا القرآن من صدرى. . \" الخ الحدث. وقال الترمذى: هذا حديث حسن غريب لا = ١٩٧٢ - أبو صالح دخل على أم كلثوم وهى تمتشط (١). لا يعرف بغير هذا."],[12284,"١٩٧٣ - أبو صالح عن أبى حازم عن ابن عباس. روى عنه ياسين بن محمد بن ايمن (٢) حديثا منكر (٣)."],[12285,"= نعرفه إلا من حديث الوليد بن مسلم. اهـ."],[12286,"وعزاه المنذرى في الترغيب والترهيب (٢/ ١٧٧ - ١٧٨) إلى الترمذى والحاكم وقال: قال الحاكم: صحيح على شرطهما وقال أيضا: قال المملى رضي الله عنه: طريق أسانيد هذا الحديث جيدة ومتنه غريب جدا واللَّه أعلم."],[12287,"قلت: ولم أقف عليه في المستدرك للحاكم، . وعزاه السيوطى في الجامع الصغير (١١٥/ ١) إلى الترمذى والطبرانى والحاكم من حديث أنس رضي الله عنه ورمز إلى ضعفه."],[12288,"والحديث أخرجه أيضا السيوطى في اللآلى المصنوعة في الأحاديث الموضوعة (٢/ ٦٥ - ٦٧) به."],[12289,"١٩٧٢ - تاريخ ابن معين (٢/ ٧١١)، كنى الدولابى (٢/ ١٠) وقال: أبو صالح الزمن، كنى ابن منده (١٦٠/ أ)، كنى الحاكم (١/ ٢٣٦/ ب) المقتنى في سرد الكنى (٧٢/ أ)."],[12290,"(١) ومثله في مصادر الترجمة."],[12291,"١٩٧٣ - كنى الحاكم (١/ ٢٣٦/ ب)، المقتنى في سرد الكنى (٧٢/ ب) وقال: خبره منكر في على. لا. بل موضوع."],[12292,"(٢) ياسين بن محمد ذكره ابن حجر في اللسان (٦/ ٢٣٨) فقال: ياسين بن محمد عن أبى حازم المدينى، لا يعرف، وقال الازدى: متروك، وقال ابن حجر: واظنه ياسين بن حماد. اهـ."],[12293,"(٣) الحديث أخرجه أبو أحمد الحاكم في الكنى (١/ ٢٣٧/ أ) من طريق ياسين ابن محمد بن ايمن عن أبى صالح عن أبى حازم عن ابن عباس قال: قال رسول اللَّه -صلى الله عليه وآله وسلم-: أعطانى ربى تبارك وتعالى في على خصالا في الدنيا ="],[12294,". . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . ."],[12295,"= وخصالا في الاخرة اعطانى به في الدنيا. . وغاسلى ودافنى واعطانى به في الدنيا أنه لن يرجع بعدى كافرا واعطانى به في الاخرة أنه صاحب لواء الحمد تقدمنى به واعطانى به في الاخرة أنه متكأتى في طول الحشر يوم القيامة واعطانى به أنه عونا لى على حمل مفاتيح الجنة."],[12296,"وبنحو هذا اللفظ أخرجه ابن الجوزى في العلل المتناهية (١/ ٢٤٣) من حديث على رضي الله عنه قال: سمعت رسول اللَّه -صلى الله عليه وآله وسلم- يقول: أُعطيت في على خَمْسُ خصال لم يعطها نبى في احد قبلى اما خصلة منها فانه يقضى دَيْنى ويوارى عورتى، وأما الثانية فانه الذائد عن حوضى. وأما الثالثة فانه متكأة لى في طريق المحشر يوم القيامة وأما الرابعة فان لوائى معه يوم القيامة وتحته آدم وما ولد. وأما الخامسة فانى لا أخشى أن يكون زانيا بعد إحصان ولا كافرا بعد إيمان."],[12297,"باب أبى الصلت"],[12298,"١٩٧٤ - أبو الصلت الكوفى. عن عمر بن الخطاب. روى عنه أبو اسحاق السبيعى الهمدانى."],[12299,"١٩٧٥ - أبو الصلت الثقفى عن عمر. روى عنه عبد اللَّه بن عمار اليمامى (١)."],[12300,"١٩٧٦ - أبو الصلت عن أبى هريرة. روى عنه على بن زيد بن جدعان التيمى بصرى."],[12301,"١٩٧٤ - كنى ابن منده (١٦٣/ ب)، كنى الحاكم (١/ ٢٤٢/ أ) وقال: حديثه في الكوفيين، الميزان (٤/ ٥٤٠)، اللسان (٧/ ٦٦)."],[12302,"قال الذهبى وتبعه ابن حجر: شيخ لأبى اسحاق، قال ابن المدينى: مجهول."],[12303,"١٩٧٥ - كنى البخارى (ص ٤٤)، كنى الحاكم (١/ ٢٤٢/ أ) وقال: \"قاله محمد بن إسماعيل فلا أدرى هما اثنان أو هذا والذى تقدم اخراجنا له واحد وخليقا أن يكون اثنين لاختلاف روايتيهما. اهـ."],[12304,"قلت: والذى بعده عنده هو أبو الصلت الكوفى المتقدم الجرح (٤/ ٢/ ٣٩٤)، التهذيب (١٢/ ١٣٥)، التقريب (٢/ ٤٣٨) وقال: مقبول، من الثانية./ ق."],[12305,"(١) ذكره ابن أبى حاتم الجرح (٢/ ٢/ ١٢٩) وذكر روايته عن أبى الصلت. وقال: سمعت أبى يقول: هو مجهول أهـ. وقال ابن حجر في التقريب (١/ ٤٣٤): مجهول: من السابعة."],[12306,"١٩٧٦ - كنى ابن منده (١٦٣/ ب)، كنى الحاكم (١/ ١٤٢/ أ) وقال: حديثه في البصريين، الميزان (٤/ ٥٤٠) وقال: لا يعرف، اللسان (٧/ ٤٧٠) وقال: مجهول، تهذيب الكمال (٣/ ١٦١٦)، التهذيب (١٢/ ١٣٥)، التقريب (٢/ ٤٣٨) وقال: مجهول: من الثالثة، ق."],[12307,"١٩٧٧ - أبو الصلت السراج. سمع ابن عمر. روى عنه حفص بن أبى حفص السراج (١)."],[12308,"١٩٧٨ - أبو الصلت، شامى عن حرملة بن عبد الرحمن (٢) عن عقبة بن مسلم (٣). روى عنه ضُبَارة بن مالك (٤)."],[12309,"١٩٧٩ - أبو الصلت. شامى أيضا جد عيسى بن معمر (٥). روى عن كعب روى عنه صفوان بن عمرو."],[12310,"١٩٨٠ - أبو الصلت بياع المزاد. وقيل: بياع البزور. روى عن أبى عقرب."],[12311,"١٩٧٧ - كنى البخارى (ص ٤٤)، كنى الحاكم (١/ ٢٤٢/ أ)، الجرح (٤/ ٢/ ٣٩٤)."],[12312,"(١) قال ابن حجر في اللسان (٢/ ٣٢١) حفص بن أبى حفص السراج: ليس بالقوى. اهـ."],[12313,"١٩٧٨ - كنى الحاكم (١/ ٢٤٢/ أ) وقال: حديثه في الشاميين."],[12314,"(٢) هكذا هنا \"حرملة بن عبد الرحمن\" وفى كنى البخارى \"أبى عبد الرحمن\" وانظر ترجمته في الجرح (١/ ٢/ ٢٧٣)، التهذيب (٢/ ٢٢٩)."],[12315,"(٣) عقبة بن مسلم التجيبى، ثقة، من الرابعة. التقريب (٢/ ٢٨)، الجرح (٣/ ١/ ٣١٦)."],[12316,"(٤) ضُبَارة، بضم أوله ثم موحدة، ابن عبد اللَّه بن مالك بن أبى السليل، بفتح المهملة، الحضرمى، أبو شريح الحمصى، مجهول، من السادسة. التقريب (١/ ٣٧٢)."],[12317,"١٩٧٩ - كنى البخارى (ص ٤٤)، كنى الحاكم (١/ ٢٤٢/ أ) كنى ابن منده (١٦٣/ ب)، الجرح (٢/ ٤/ ٣٩٤)."],[12318,"(٥) عيسى بن معمر، لين الحديث، من السادسة، التقريب (٢/ ١٠٢) التهذيب (٨/ ٢٣١)، الجرح (٣/ ١/ ٢٨٨)."],[12319,"١٩٨٠ - كنى البخارى (ص ٤٤)، الجرح (٤/ ٢/ ٣١٤)، كنى ابن منده (١٦٣/ ب) كنى الحاكم (١/ ٢٤٢/ أ)، تعجيل المنفعة (ص ٣٢٥) وقال: مجهول، وصفه البخارى، وتبعه أبو أحمد بأنه بياع المرور، المَرور بالراء جمع مَرّ بفتح الميم وتشديد الراء وهو المسحاة\". اهـ = روى عنه أبو يعفور (١) العبدى."],[12320,"١٩٨١ - أبو الصلت. رأى أنس بن مالك. روى عنه سلام بن مسكين النمرى."],[12321,"= قلت: هكذا قال ابن حجر: \"المرور\" وعزاه للبخارى، والحاكم أبى أحمد وهو عند الحاكم \"المرور\" كما ذكر ابن حجر والذى في مطبوعة الكنى للبخارى المزاد\". واللَّه أعلم."],[12322,"(١) في كنى البخارى، وتعجيل المنفعة \"أبو يعقوب\" وهو خطأ، و\"أبو يعفور\" هذا هو العبدى معروف واسمه \"وقدان\". وقد تقدم."],[12323,"١٩٨١ - كنى ابن منده (١٦٣/ ب)، كنى الحاكم (١/ ٢٤٢/ ب)."],[12324,"باب أبى الصهباء"],[12325,"١٩٨٢ - أبو الصهباء البكرى. سأل ابن عباس. روى عنه سعيد بن جبير. سئل أبو زرعة عنه فقال: لا أعرف اسمه (١). وقد قيل: إِنَّ أبا الصهباء البكرى اسمه صهيب. وقد ذكرناه (٢) في باب من يعرف اسمه وذكرنا من روى عنه وعن من روى، ومن قال فيه انه مولى ابن عباس."],[12326,"١٩٨٣ - أبو الصهباء المصرى (٣). روى عن بكير (٤) بن عبد اللَّه بن الاشج روى عنه معن بن عيسى."],[12327,"١٩٨٤ - أبو الصهباء البصرى (٥). سمع سعيد بن جبير. روى عنه حماد بن زيد وأخوه سعيد بن زيد (٦)، وعمارة بن زاذان والحسن بن أبى جعفر."],[12328,"١٩٨٢ - كنى الدولابى (٢/ ١١)، الجرح (٤/ ٢/ ٣٩٤)، كنى ابن منده (١٦٤/ أ)."],[12329,"(١) انظر الجرح (٤/ ٢/ ٣٩٤)."],[12330,"(٢) انظر الترجمة (٩٠٩)."],[12331,"١٩٨٣ - كنى البخارى (ص ٤٤)، كنى الحاكم (١/ ٢٤٣/ أ)، الجرح (٤/ ٢/ ٣٩٤)."],[12332,"(٣) الذى في كنى البخارى وفى الجرح (البصرى) بالباء الموحدة."],[12333,"(٤) في كنى البخارى \"بكر\"."],[12334,"١٩٨٤ - كنى البخارى (ص ٤٤)، كنى الحاكم (١/ ٢٤٣/ أ)، الجرح (٤/ ٢/ ٣٩٥) كنى ابن منده (١٦٤/ أ)، الثقات (٧/ ٦٥٧)، التهذيب (١٢/ ١٣٥) التقريب (٢/ ٤٣٨)، وقال: مقبول. من السادسة./ت. فق."],[12335,"(٥) في الجرح والتهذيب \"الكوفى\"."],[12336,"(٦) سعيد بن زيد، صدوق له أوهام، من السابعة، (ت: ١٦٧)، التقريب (١/ ٢٩٦)."],[12337,"باب أبى صفوان"],[12338,"١٩٨٥ - أبو صفوان. روى عنه عبد اللَّه بن مصعود. وزعموا أنه لم يسمع منه. روى عنه أشعث بن سوّار."],[12339,"١٩٨٦ - أبو صفوان. روى عن محمد بن عبيد بن أبى صالح (١). روى عنه عطاف بن خالد. ضعفه أبو حاتم."],[12340,"١٩٨٥ - كنى ابن منده (١٦٣/ أ)، كنى الحاكم (١/ ٢٤٠/ ب) وقال: حديثه في الكوفيين، الجرح (٤/ ٢/ ٣٩٥) وقال: روى عن ابن مسعود مرسل. سمعت أبى يقول: هو مجهول لم يدرك ابن مسعود. الميزان (٤/ ٥٤٠)، اللسان (٧/ ٦٦) وقال: مجهول."],[12341,"١٩٨٦ - الجرح (٤/ ٢/ ٣٩٥) وقال: سألت أبى عنه فقال: هو ضعيف الحديث."],[12342,"(١) ضعيف، من الخامسة./ د. التقريب (٢/ ١٨٨)."],[12343,"باب أفراد في الصاد"],[12344,"١٩٨٧ - أبو صَبَّاح (١) الوراق (٢) مؤذن واسط، سمع (ابن كثير) (٣). روى عنه العُكْلى (٤)."],[12345,"١٩٨٨ - أبو صخر مدنى. وقيل: أبو صخرة صاحب العباء سمع أبا سعيد المقبرى. روى عنه عبد العزيز بن أبى سلمة الماجشون."],[12346,"١٩٨٧ - كنى البخارى (ص ٤٥)، كنى الحاكم (١/ ٢٤١/ أ)، كنى ابن منده (٢٦٥/ أ)."],[12347,"(١) صَبَّاح: بفتح الصاد المهملة، وتشديد الباء المعجمة بواحدة، الاكمال (٥/ ١٨٥)، تبصير المنتبه (٣/ ٨٢٧)."],[12348,"(٢) الورّاق: بفتح الواو والراء المشدده وبعد الالف قاف - يقال: لمن ينسخ الكتب ولمن يبيع الكاغد. اللباب (٣/ ٣٥٧)."],[12349,"(٣) هكذا في الأصل \"ابن كثير\" والذى في كنى البخارى، كنى ابن منده، كنى الحاكم \"أم كثير\"."],[12350,"(٤) العكلى: بضم العين وسكون الكاف كسر اللام - نسبة إلى عُكْل وهو بطن من تميم، وقال ابن الاثير: هكذا قال السمعانى: ان عكلا بطن من تميم وليس بصحيح، وإنما عكل اسم أَمَة لأمرأة من حمير يقال لها: بنت ذى اللحية فتزوجها عوف بن قيس بن وائل. . فولدت له جشما وسعدا وعليا ثم هلكت الحميرية فحضنت عكل ولدها فغلبت عليهم ونسبوا إليها انظر اللباب (٢/ ٣٥١ - ٣٥٢)."],[12351,"١٩٨٨ - كنى البخارى (ص ٤٥)، كنى ابن منده (١٦٤/ أ)، كنى الحاكم (١/ ٢٤٤/ أ) و(١/ ٢٤٤/ ب)."],[12352,"قلت: ترجم له أبو أحمد الحاكم في \"أبى صخر\" وفى أبى صخرة وقال: حديثه في أهل المدينة."],[12353,"١٩٨٩ - أبو صدقة الجُدِّى (١) سمع محمد بن عجلان والجعيد بن عبد الرحمن (٢). روى عنه محمد بن عبد الملك بن أبى الشوارب (٣)."],[12354,"١٩٩٠ - أبو صادق كوفى. عن أبى هريرة. روى عنه وقدان العبدى (٤) هو غير أبى صادق (٥) مسلم بن يزيد الذى يروى عن ربيعة بن ناجد وهذا غير مسمى عندهم. لا أعرف أحدا سماه."],[12355,"١٩٨٩ - كنى الحاكم (١/ ٢٤٥/ ب) وقال: كناه لنا، أبو القاسم البغوى. الثقات (٥/ ٥٧٣)."],[12356,"(١) الجُدِّى: هكذا هى مضبوطة في كنى أبى أحمد الحاكم بضم الجيم وتشديد الدال وفى اللباب (١/ ٢٦٤) الجدّى بضم الجيم وتشديد الدال المكسورة المهملة نسبة إلى جُده وهى بليدة بساحل مكة. اهـ. وانظر مراصد الاطلاع (١/ ٣١٨)."],[12357,"(٢) في كنى الحاكم \"الجعد\" وفى التقريب (١/ ١٢٨) الجعد بن عبد الرحمن ابن أوس، وقد ينتسب إلى جده، وقد يصغر، ثقة، من الخامسة (ت: ١٤٤)."],[12358,"(٣) اسم ابن أبى الشوارب محمد بن عبد الرحمن بن أبى عثمان، ومحمد بن عبد الملك هذا صدوق من كبار العاشرة (ت: ٢٤٤). انظر التقريب (٢/ ١٨٦)."],[12359,"١٩٩٠ - كنى ابن منده (١٦٥/ أ)، كنى الحاكم (١/ ٢٤٧/ أ) وقال: حديثه في الكوفيين لا أعلم أحدا سماه، وهو علمى غير الذى تقدم أهـ."],[12360,"قلت: ويعنى بالذى تقدم أبا صادق مسلم بن يزيد، التهذيب (١٢/ ١٣٠) وقال: \"أبو صادق الازدى الكوفى، من أزد شنؤة\" وقيل: اسمه مسلم بن يزيد. وقيل: عبد اللَّه بن ناجد. التقريب (٢/ ٤٣٦)."],[12361,"وقال: صدوق، وحديثه عن على مرسل، من الرابعة. س ق."],[12362,"(٤) هو أبو يعفور."],[12363,"(٥) انظر (٩١١)."],[12364,"١٩٩١ - أبو صحار. رجل من بنى راشد بصرى. (روى عن أبيه) (١). روى عنه عبد السلام بن مالك (٢)."],[12365,"١٩٩٢ - أبو صهيب رفع الحديث إلى النبى عليه السلام \"يكون عليكم أمراء\" (٣). الحديث."],[12366,"١٩٩٣ - أبو الصعبة. روى عن عمر. حديثه عند عمران بن موسى (٤) عن ابن أبى الصعبة (٥) عن أبيه."],[12367,"١٩٩١ - كنى البخارى (ص ٤٤)، كنى ابن منده (١٦٦/ أ)، الجرح (٢/ ٤/ ٣٩٥) وقال: سمعت أبى يقول: هو مجهول، الثقات (٧/ ٦٦١)، ديوان الضعفاء (ص ٣٥٩)، الميزان (٤/ ٥٣٩)، وقال: مجهول، ولا يدرى من أبوه والمتن منكر، اللسان (٧/ ٦٦)."],[12368,"(١) في الأصل مكرر."],[12369,"(٢) عبد السلام بن مالك، ذكره ابن أبى حاتم في الجرح (٣/ ١/ ٤٧) ولم يذكر فيه شيئا."],[12370,"١٩٩٢ - كنى الحاكم (١/ ٢٤٧/ ب)."],[12371,"(٣) الحديث أخرجه الحاكم في الكنى. انظر مصادر الترجمة."],[12372,"١٩٩٣ - كنى البخارى (ص ٤٤)، الجرح (٤/ ٢/ ٣٩٥)، كنى ابن منده (١٦٦/ أ)."],[12373,"(٤) عمران بن موسى بن عمرو بن سعيد بن العاص، أخو أيوب، مقبول، من السابعة. انظر التقريب (٢/ ٨٥)."],[12374,"(٥) ابن أبى الصعبة، هو عبد العزيز بن أبى الصعبة التيمى، مولاهم أبو الصعب، المصرى، لا بأس به، من الثالثة. التقريب (١/ ٥٠٩)."],[12375,"الضاد"],[12376,"باب أبى الضحاك"],[12377,"١٩٩٤ - أبو الضحاك، روى عن أبى هريرة، روى عنه شعبة بن الحجاج بصرى."],[12378,"١٩٩٥ - أبو الضحاك. رأى مصعب بن الزبير (١). روى عنه قرة بن خالد بصرى."],[12379,"١٩٩٦ - أبو الضحاك الجرمى، بصرى، عن هرم بن حيان (٢)."],[12380,"١٩٩٤ - كنى ابن منده (١٦٧/ أ)، كنى الحاكم (١/ ٢٤٨/ ب) وقال: تابعى عداده في البصريين، الجرح (٤/ ٢/ ٣١٥) وقال: سمعت أبى يقول: أبو الضحاك هذا لا أعلم روى عنه غير شعبة، الميزان (٤/ ٥٤٠) وقال: لا يعرف لكن شيوخ شعبة جياد اللسان (٧/ ٤٧٠) وقال: لا يعرف، التهذيب (١٢/ ١٣٦)، التقريب (٢/ ٤٣٩)، وقال: مقبول، من الثالثة./ فق."],[12381,"١٩٩٥ - كنى البخارى (ص ٤٥)، كنى مسلم (ص ٥٣٦)، كنى الحاكم (١/ ٢٤٨/ ب) وساق حديثه من طريق، مسدد عن المعتمر عن قرة بن خالد قال حدثنى أبو الضحاك أنه أبصر مصعب بن الزبير يمشى في جنازة الاحنف ابن قيس بغير رداء أهـ، الجرح (٤/ ٢/ ٣٩٥)."],[12382,"(١) مصعب بن الزبير بن العوام أبو عبد اللَّه القرشى الاسدى، قتل بالعراق سنة أحدى وسبعين وفتك به يزيد بن ظبيان الفائشى وكان من أصحابه. اهـ. الجرح (٤/ ١/ ٣٠٣)."],[12383,"١٩٩٦ - كنى مسلم (ص ٥٣٦)، كنى ابن منده (١٦٦/ ب)، كنى الحاكم (١/ ١٤٨/ ب)."],[12384,"(٢) هرم بن حيان الازدى العبدى، روى عن عمر بن الخطاب رضي الله عنه، روى عنه الحسن البصرى كذا. ذكره ابن أبى حاتم عن أبيه ولم يذكر فيه شيئا، الجرح (٤/ ٢/ ١١٠)."],[12385,"١٩٩٧ - أبو الضحاك. روى عن أبى حكيمة رجل منهم، عن على بن أبى طالب. روى عنه عبد الرحمن بن الأصبغ (١)."],[12386,"١٩٩٧ - كنى البخارى (ص ٤٥)، كنى الحاكم (١/ ٢٤٨/ ب)، الجرح (٤/ ٢/ ٣٩٥)."],[12387,"(١) عبد الرحمن بن اصبغ الحضرمى، ذكره ابن أبى حاتم وذكر روايته عن أبى الضحاك. ولم يذكر فيه شيئا. الجرح (٢/ ٢/ ٢١٣)."],[12388,"باب أبى ضمرة"],[12389,"١٩٩٨ - أبو ضَمْرة (١)، سمع عمر بن عبد العزيز، روى عنه الليث بن سعد."],[12390,"١٩٩٩ - أبو ضمرة القاص. سمع كعب الاحبار، روى عنه حريز بن عثمان وفرج بن يُحْمِد (٢)."],[12391,"١٩٩٨ - كنى البخارى (ص ٤٥)، كنى الحاكم (١/ ٢٤٩/ أ)، الجرح (٤/ ٢/ ٣٩٦) كنى ابن منده (١٦٧/ ب)."],[12392,"(١) ضمرة: بمفتوحة وسكون ميم. المغنى (ص ٤٨)."],[12393,"١٩٩٩ - كنى البخارى (ص ٤٥)، كنى الحاكم (١/ ٢٤٩/ أ)، الجرح (٤/ ٢/ ٣٩٦)، كنى ابن منده (١٦٧/ أ)."],[12394,"(٢) فرج بن يحمد الكلاعى الشامى، ذكره ابن أبى حاتم في الجرح (٣/ ٢/ ٨٦) ولم يذكر فيه شيئا، وقال في الاكمال (٧/ ٤٢٤) يُحْمِد: بضم الياء وسكون الحاء كسر الميم. ثم قال في الكنى والاباء. بعده مباشرة \"وفرج بن يحمد عن أبى ضمرة القاص عن كعب الأحبار\" أهـ."],[12395,"باب أفراد"],[12396,"٢٠٠٠ - أبو الضيفى. روى عن أبى هريرة، كعب، روى عنه حميد بن هلال، وروى عنه طلحه بن عبيد اللَّه بن كَرِيز (١)، عن أبى هريرة."],[12397,"٢٠٠١ - أبو ضرغامة، روى عن على بن أبى طالب، روى عنه عبد الرحمن مَغراء (٢) قال ابن أبى حاتم: سألت عنه أبى فقال: لا يعرف."],[12398,"٢٠٠٠ - كنى البخارى (ص ٤٥)، الجرح (٤/ ٢/ ٣٩٦)، كنى ابن منده (١٦٧/ ب)."],[12399,"(١) طلحة بن عبيد اللَّه بن كَريز، بفتح أوله، الخزاعى، أبو المطوف، ثقة، من الثالثة. التقريب (١/ ٣٧٩)."],[12400,"٢٠٠١ - الجرح (٤/ ٢/ ٣٩٦). وقال: سألت أبى عنه فقال: لا يعرف. المقتنى في سرد الكنى (٧٤/ ب)."],[12401,"(٢) عبد الرحمن بن مَغْراء، بفتح الميم وسكون المعجمة ثم راء مقصورا، الدوسى، أبو نصير، الكوفى، نزيل الرى، صدوق، تكلم في حديثه عن الأعمش من كبار التاسعة. مات بضع وتسعين ومائة. التقريب (١/ ٤٩٩)."],[12402,"العين"],[12403,"باب أبى عبد الله"],[12404,"٢٠٠٢ - أبو عبد اللَّه الاشعرى، سمع عمرو بن العاص، وخالد بن الوليد ويزيد بن أبى سفيان، وشُرَحْبيل بن حسنه (١) وأبا الدرداء. روى عنه إسماعيل بن عبيد اللَّه بن أبى المهاجر المخزومى وأبو صالح الاشعرى. يعد في الشاميين."],[12405,"٢٠٠٣ - أبو عبد اللَّه الكوفى. وقيل: المدائنى رجل من أصحاب حذيفة. روى عن حذيفة. روى عنه عمرو بن هرم."],[12406,"٢٠٠٤ - (أبو عبد اللَّه شامى. عن عمر بن الخطاب مرسل. روى عنه إبراهيم بن أدهم العجلى) (٢)."],[12407,"٢٠٠٢ - كنى البخارى (ص ٤٨)، الجرح (٤/ ٢/ ٤٠٠)، الثقات (٥/ ٥٧٧)، كنى ابن منده (١٧٦/ ب)، التهذيب (١٢/ ١٤٧) وقال: ذكره ابن سميع في الطبقة الأولى من التابعين وذكره ابن حبان في الثقاب، وقال أبو زرعة الدمشقى: لم أجد أحدًا سماه. وقال في التقريب (٢/ ٤٤): ثقة من الثانية، / د. ق."],[12408,"(١) شرحبيل، بضم أوله وفتح الراء وسكون المهملة، ابن حسنة هو ابن عبد اللَّه ابن مطاع الكندى، حليف بنى زهرة. وحسنة أمه او التى ربته، صحابى جليل، كان أميرا في فتح الشام ومات بها سنة ثمانى عشرة./ ق التقريب (١/ ٣٤٩)، التجريد (١/ ٢٥٥)."],[12409,"٢٠٠٣ - كنى البخارى (ص ٥٠)، كنى الحاكم (٢/ ٢/ ب) وقال: أراه ابن حيّان الازدى البصرى، حديثه في الكوفيين. الجرح (٤/ ٢/ ٤٠٢)."],[12410,"٢٠٠٤ - كنى الحاكم (٢/ ٢/ ب) وقال: عن عمر مرسل."],[12411,"(٢) الحقت هذه الترجمة بكاملها في هامش الأصل. كتب بعدها \"صح أصل\"."],[12412,"٢٠٠٥ - أبو عبد اللَّه الأنصارى، عن عائشة أم المؤمنين، شامى، روى عنه معاوية بن صالح."],[12413,"٢٠٠٦ - أبو عبد اللَّه، سمع أبا هريرة. حديثه عند يحيى بن أبى كثير عن محمد بن إبراهيم بن الحارث التيمى عنه، يعد في أهل المدينة."],[12414,"٢٠٠٧ - أبو عبد اللَّه الشيبانى. يقال له: ابن سوّار (١) كان شيعة لعلى رضي الله عنه. روى عنه عاصم الأحول."],[12415,"٢٠٠٨ - أبو عبد اللَّه، مولى بنى مرّة، سمع عبد الرحمن بن عوف وبلال ابن رباح. روى عنه أبو عبد الرحمن (٢). غير مسمى ولا منسوب."],[12416,"٢٠٠٩ - أبو عبد اللَّه الشرعبى. سمع ثوبان. روى عنه عبد القدوس بن حبيب (٣) وعبد الرحمن (٤) بن محمد اليمامى."],[12417,"٢٠٠٥ - كنى البخارى (ص ٤٨)، كنى الحاكم (٢/ ٣/ أ) وقال: حديثه في الشاميين، الجرح (٤/ ٢/ ٤٠٠)."],[12418,"٢٠٠٦ - كنى البخارى (ص ٤٨)، كنى الحاكم (٢/ ٣/ أ)، الثقات (٥/ ٥٧٨)، الجرح (٤/ ٢/ ٤٠٠)، اللسان (٧/ ٤٧٢)، التهذيب (١٢/ ١٥٢) التقريب (٢/ ٤٤٦)، وقال: مقبول، من الثالثة./ س."],[12419,"٢٠٠٧ - كنى البخارى (ص ٤٩)، كنى الحاكم (٢/ ٣/ أ)، الجرح (٤/ ٢/ ٣٩٩) كنى ابن منده (١٧٧/ أ)."],[12420,"(١) سوّار، بمفتوحة وشدة واو آخره راء. المغنى (ص ٤١)."],[12421,"٢٠٠٨ - كنى البخارى (ص ٤٨)، كنى الحاكم (٢/ ٣/ أ)."],[12422,"(٢) سيأتى في (٢٠٤٦)."],[12423,"٢٠٠٩ - كنى البخارى (ص ٤٩)، كنى الحاكم (٢/ ٣/ ب)، الجرح (٤/ ٢/ ٤٠٠)."],[12424,"قلت: سيأتى في ترجمة أبى عبد اللَّه المكى الحجام (٢٠١٧) قول ابن عبد البر حيث قال هناك: \"فيه وفى الشرعبى عندى نظر\"."],[12425,"(٣) عبد القدوس بن حبيب الكلاعى الشامى أبو سعيد. قال أبو حاتم: متروك الحديث. انظر الجرح (٣/ ١/ ٥٥) وانظر الميزان (٤/ ٤٥)."],[12426,"(٤) هكذا في الأصل \"عبد الرحمن\" وفى كنى الحاكم \"عبد اللَّه \" وعبد اللَّه بن ="],[12427,"٢٠١٠ - أبو عبد اللَّه الشامى. روى عن أبى غالب حزور. روى عنه المعتمر ابن سليمان."],[12428,"٢٠١١ - أبو عبد اللَّه بن عم أبى هريرة. سمع أبا هريرة. روى عنه بشر بن رافع أبو الاسباط الحارثى."],[12429,"٢٠١٢ - أبو عبد اللَّه النجرانى (١) روى عن القاسم (٢) بن عبد الرحمن. روى"],[12430,"= محمد اليمامى، البكرى، روى عن آدم بن على الشيبانى روى عنه عبيد بن اسحاق العطار، قال أبو حاتم: هو مجهول انظر الجرح (٢/ ٢/ ١٥٨)."],[12431,"٢٠١٠ - كنى ابن منذه (١٧٧/ ب)، كنى الحاكم (٢/ ٣/ ب)."],[12432,"٢٠١١ - كنى البخارى (ص ٤٩)، كنى ابن منده (١٧٧/ أ)، كنى الحاكم (٢/ ٣/ ب)، الميزان (٤/ ٥٤٥)، وقال: لا يعرف ما حدث عنه سوى بشر بن رافع، ديوان الضعفاء (ص ٣٦١)، اللسان (٧/ ٤٧٢)، وقال: أبو عبد اللَّه الدوسى، ابن عم أبى هريرة. قيل: اسمه عبد الرحمن بن هضهاض، وقيل: ابن الصامت. وقيل: هضاض، عن أبى هريرة وعنه بشر بن رافع، التهذيب (١٢/ ١٤٩) وفى التقريب (٢/ ٤٤٥) قال: مقبول، من الثالثة. قيل: اسمه عبد الرحمن بن هضهاض وقيل: ابن الصامت./ د. ق. وفى الثقات (٥/ ٩٧) \"عبد الرحمن بن الصامت بن عم أبى هريرة، يروى عن أبى هريرة، روى عنه أبو الزبير المكى وفى الجرح (٢/ ٢/ ٢٩٧)، عبد الرحمن بن الهضهاض ويقال: ابن هضهاض وابن هضهاض أصح، روى عن أبى هريرة. أهـ."],[12433,"٢٠١٢ - كنى البخارى (ص ٤٩)، الجرح (٤/ ٢/ ٤٠١) وقال: سألت أبى عنه فقال: صالح الحديث، لا بأس به."],[12434,"(١) النجرانى: بفتح النون وسكون الجيم وفتح الراء وسكون الالف وبعدها نون نسبة إلى نجران، وهى ناحية بين اليمن وهجر. اللباب (٣/ ٢٩٩) وانظر مراصد الاطلاع (٣/ ١٣٥٩ - ١٣٦٠)."],[12435,"(٢) هكذا هنا \"القاسم بن عبد الرحمن\" والذى في كنى البخارى \"القاسم بن أبى قرة\" وفى الجرح \"القاسم أبى عبد الرحمن\"."],[12436,"عنه يحيى بن حمزة وسويد بن عبد العزيز هو عندهم صالح الحديث حسن الحديث."],[12437,"٢٠١٣ - أبو عبد اللَّه الشامى قال: سمعت معاوية بن أبى سفيان يخطب وهو يقول: حدثنى الأنصارى -يعنى زيد بن ارقم- روى عنه شعبة بن الحجاج."],[12438,"٢٠١٤ - أبو عبد اللَّه. شيخ من أهل المدينة. روى عن أبى سعيد الخدرى عن النبى عليه السلام: \"الدينار بالدينار\" (١) من حديث الليث بن سعد عن بكير ابن عبد اللَّه بن الاشج عنه."],[12439,"٢٠١٣ - الجرح (٤/ ٢/ ٣٩٩) وقال: سألت أبى عنه فقال: لا يسمى ولا يعرف وهو شيخ. تعجيل المنفعة (ص ٣٢٧) وقال: بعد أن ذكره كذا ذكره الهيثمى ولم أر له في اصل المسند ذكرا ولا أورده الحسينى. اهـ."],[12440,"٢٠١٤ - كنى البخارى (ص ٤٨)، الجرح (٤/ ٢/ ٤٠٠)، كنى الحاكم (٢/ ٤/ أ) الجرح (٤/ ٢/ ٤٠٠)."],[12441,"(١) الحديث أخرجه البخارى في الكنى من طريق عبد اللَّه بن صالح حدثنى الليث، حدثنى بكير أن شيخا لا أعلم شيخا أكبر منه يقال له: أبو عبد اللَّه قال: انطلقت إلى العراق ثم جئت أبا سعيد فقال: سمعت رسول اللَّه -صلى الله عليه وآله وسلم- يقول \"الدينار بالدينار والدرهم بالدرهم لا فضل بينهما\". وأخرجه أيضا أبو أحمد الحاكم في الكنى من هذا الطريق به وزاد في آخره لفظ \"الأوزان بوزن\". وذكره ابن أبى حاتم في الجرح من هذا الطريق. انظر مصادر الترجمة."],[12442,"والحديث أخرجه البخارى ومسلم من حديث أبى سعيد الخدرى لكن من غير هذا الطريق وبألفاظ قريبة من هذا اللفظ. انظر البخارى \"البيوع\" (٤/ ٣٨١) ومسلم \"المساقاة\" (٣/ ١٢٠٩) وأخرجه أيضا مالك \"البيوع\" (٢/ ٦٣٢)، والشافعى في الرسالة (ص ٢٧٦) وابن ماجه \"التجارات\" باب من قال: لا ربا إلا في النسيئة (٢/ ٧٥٨) والبيهقى في السنن (٥/ ٢٨٠) والطحاوى في شرح معانى الآثار (٤/ ٦٤، ٦٧، ٦٨) كلهم أخرجوه من حديث أبى سعيد الخدرى بنحوه."],[12443,"٢٠١٥ - أبو عبد اللَّه البراد. روى عنه يزيد بن قسيط."],[12444,"٢٠١٦ - أبو عبد اللَّه الشامى. روى عنه جعفر بن سليمان."],[12445,"٢٠١٧ - أبو عبد اللَّه الحجام المكى. سمع ابن عمر. روى عنه عبد اللَّه بن محمد اليمامى. فيه وفى الشرعبى عندى نظر."],[12446,"٢٠١٨ - أبو عبد اللَّه الخيّاط (١). روى عن أبى رهم - الغفارى (عن) (٢) أبى هريرة روى عنه سعيد بن أبى هلال."],[12447,"٢٠١٩ - أبو عبد اللَّه الأغر. ويقال: أبو مسلم. ويقال: هما اثنان سمى أبا عبد اللَّه بعضهم سلمان وكذلك أبو مسلم. وقيل: اسمه كنيته. روى عن أبى هريرة."],[12448,"٢٠١٥ - كنى البخارى (ص ٤٩)، كنى الحاكم (٢/ ٣/ ب)، كنى ابن منده (١٧٧/ أ)."],[12449,"٢٠١٦ - كنى البخارى (ص ٤٩)، الجرح (٤/ ٢/ ٤٠١)، كنى ابن منده (١٧٧/ أ)."],[12450,"٢٠١٧ - كنى البخارى (ص ٤٩)، الجرح (٤/ ٢/ ٤٠٠)، كنى ابن منده (١٧٧/ أ)."],[12451,"٢٠١٨ - كنى البخارى (ص ٤٩)، كنى الحاكم (٢/ ٤/ أ)، الجرح (٤/ ٢/ ٤٠٠). الثقات (٧/ ٦٦٣)، كنى ابن منده (١٧٧/ أ)."],[12452,"(١) في الجرح الحنّاط بالنون."],[12453,"(٢) غير واضحة في الأصل. وهى في مصادر الترجمة كما أثبتها."],[12454,"٢٠١٩ - الجراح (٤/ ٢/ ٤٠١)، وقال: أبو عبد اللَّه الأغر ويقال: أبو مسلم الاغر ويقال: هما اثنان، ويقال: اسمه كنيته واحد. وقال ابن أبى حاتم: قيل لأبى: كيف حديثه؟ قال: صالح. وانظر التهذيب (١٢/ ١٣٩) حيث قال ابن حجر: قال عبد الغنى بن سعيد في الايضاح: سلمان الاغر مولى جهينة هو أبو عبد اللَّه الاصبهانى الاغر وهو مسلم المدينى، الذى يحدث عنه الشعبى وقال قوم هو الاغر أبو مسلم الذى يروى عنه أهل الكوفة قلت: وقد تقدم أبو عبد اللَّه الاغر سلمان في (٩١٧) وأيضا تقدم أبو مسلم الاغر في (٧٩٧) فليرجع إلى ترجمتيهما هناك."],[12455,"٢٠٢٠ - أبو عبد اللَّه الشامى، روى عن تميم الدارى، روى عنه ضرار بن عمرو (١)."],[12456,"٢٠٢١ - أبو عبد اللَّه مولى أبى موسى الاشعرى. روى عن سعيد بن أبى الحسن أخى الحسن البصرى. روى عنه عبد ربه بن سعيد الأنصارى (٢)."],[12457,"٢٠٢٢ - أبو عبد اللَّه قال: كان ابن أبى أوفى يؤمهم وهو أعمى روى عنه الحسن بن صالح، كوفى."],[12458,"٢٠٢٣ - أبو عبد اللَّه، عن سعيد بن جبير، روى عنه اسرائيل بن يونس كوفى."],[12459,"٢٠٢٤ - أبو عبد اللَّه مولى الجندعين، مدنى، روى عن أبى هريرة روى عنه"],[12460,"٢٠٢٠ - كنى البخارى (ص ٤٩)، الجرح (٤/ ٢/ ٤٠١)، الميزان (٤/ ٥٤٤) وقال: لا يعرف. وكذا قال ابن حجر في اللسان (٧/ ٧٢)."],[12461,"(١) ضرار بن عمرو ذكره ابن أبى حاتم في الجرح (٢/ ١/ ٤٦٥) وذكر روايته عن أبى عبد اللَّه الشامى. ولم يذكر فيه جرحا. وانظر ترجمته أيضا في اللسان (٣/ ٢٠٢)."],[12462,"٢٠٢١ - كنى البخارى (ص ٥٠)، كنى الحاكم (٤/ ٢/ أ)، الجرح (٤/ ٢/ ٤٠١) كنى ابن منده (١٧٧/ أ)."],[12463,"(٢) عبد ربه بن سعيد الأنصارى. أخو يحيى المدنى، ثقة من الخامسة (ت: ١٣٩) وقيل: بعد ذلك. التقريب (١/ ٤٧٠)."],[12464,"٢٠٢٢ - كنى البخارى (ص ٤٩)، كنى الحاكم (٢/ ٤/ أ)."],[12465,"٢٠٢٣ - كنى البخارى (ص ٤٩)، الثقات (٧/ ٦٦٥)."],[12466,"٢٠٢٤ - كنى البخارى (ص ٤٨)، كنى ابن منده (١٧٧/ أ)، كنى الحاكم (٢/ ٤/ ب)، وقال حديثه في أهل المدينة، وقد اختلفوا فيه فقال بضعهم عن أبى صالح مولى الجندعيين، الجرح (٤/ ٢/ ٤٠٠)، الثقات (٥/ ٥٦٤)، التهذيب (١٢/ ١٥٠)، التقريب (٢/ ٤٤٥) وقال: ثقة، من الثالثة. وقيل: هو نافع بن أبى نافع./ س."],[12467,"سليمان بن يسار، وقد اختلفوا فيه فقال بعضهم، عن أبى صالح (١) مولى الجندعيين."],[12468,"٢٠٢٥ - أبو عبد اللَّه الفراء (٢) عن سالم بن عبد اللَّه بن عمر. روى عنه الدراوردى."],[12469,"٢٠٢٦ - أبو عبد اللَّه. شيخ من أهل صنعاء. سمع وهب بن منبه. روى عنه بشر بن رافع. قال أبو أحمد الحاكم: خليقا أن يكون هذا وابن عم أبى هريرة واحدا قال أبو عمر: هما اثنان (٣) واللَّه أعلم."],[12470,"٢٠٢٧ - أبو عبد اللَّه. روى عن عبيد بن أبى الجعد (٤) حديثا منقطعا."],[12471,"٢٠٢٨ - أبو عبد اللَّه. وقيل: أبو عبيد اللَّه القرشى. جليس جعفر بن"],[12472,"(١) أبو صالح مولى الجندعيين تقدم في (١٩٧٠)."],[12473,"٢٠٢٥ - كنى البخارى (ص ٥٠)، الثقات (٧/ ٦٦٦)، كنى ابن منده (١٧٧/ أ)، الجرح (٤/ ٢/ ٤٠١) وقال: سمعت أبى يقول: هو مجهول، الميزان (٤/ ٥٤٦) وقال: مجهول، اللسان (٧/ ٧٣)، وقال أيضا مجهول."],[12474,"(٢) في الجرح، والميزان، واللسان \"القزاز\"."],[12475,"٢٠٢٦ - كنى ابن منده (١٧٧/ أ)، كنى الحاكم (٢/ ٤/ ب) وقال: قد أخرجت فيما تقدم أبا عبد اللَّه بن عم أبى هريرة قوله، روى عنه بشر بن رافع النجرانى فلا ادرى هما اثنان أو واحد، وخليقا ان يكونا واحدا."],[12476,"قلت: وأبو عبد اللَّه بن عم أبى هريرة تقدم انظر الترجمة (٢٠١١)."],[12477,"(٣) يذكر ابن حجر في التهذيب (١٢/ ١٥) في ترجمة أبى عبد اللَّه السدوسى ابن عم أبى هريرة قال: وفرق ابن عبد البر بينهما -يعنى بين صاحب هذه الترجمة وبين ابن عم أبى هريرة."],[12478,"٢٠٢٧ - كنى البخارى (ص ٥٠)، كنى الحاكم (٢/ ٥/ أ)، الجرح (٤/ ٢/ ٤٠١)."],[12479,"(٤) في كنى البخارى \"عبيد اللَّه بن أبى الجعد\". وفى التقريب (١/ ٥٤٢) عبيد ابن أبى الجعد الغَطَفانى، بفتح المعجمة، صدوق، من الثالثة."],[12480,"٢٠٢٨ - كنى البخارى (ص ٥٣)، كنى ابن منده (١٧٧/ أ)، كنى الحاكم (٢/ ٥/ أ) وقال: أبو عبد اللَّه ويقال: أبو عبيد اللَّه القرشى. الميزان (٤/ ٥٤٥) وقال لا ="],[12481,"ربيعة (١). سمع أبا بردة بن أبى موسى. روى عنه سعيد بن أبى أيوب المصرى."],[12482,"٢٠٢٩ - أبو عبد اللَّه النِّبَاجى (٢) قوله. روى عنه عبد اللَّه بن خُبَيْق (٣) بن سابق الانطاكى."],[12483,"٢٠٣٠ - أبو عبد اللَّه المكى. عن نافع بن جبير بن مطعم. روى عنه الحجاج بن أرطأة."],[12484,"= يعرف، عنه سعيد بن أبى أيوب فقط -حديث: \"من أعظم الذنوب بعد الكبائر أن يموت الرجل رعليه دين لا يدع له وفاء\". التهذيب (١٢/ ١٥٠)، التقريب (٢/ ٤٤٥) وقال: مقبول، من السادسة./ د."],[12485,"(١) جعفر بن ربيعة بن شرحبيل بن حسنة الكندى، ثقة، من الخامسة. (ت: ١٣٦) التقريب (١/ ١٣٠)."],[12486,"٢٠٢٩ - كنى الحاكم (٢/ ٥/ أ)."],[12487,"(٢) النِّبَاجى، بكسر النون وفتح الباء الموحدة وفى آخرها الجيم - هذه النسبة إلى النباج، وهى قرية من بادية البصرة. اهـ. الاكمال (٧/ ٣٧٢)، اللباب (٣/ ٢٩٤)."],[12488,"(٣) جاء في تبصير المنتبه (٢/ ٥٢٤) خبيق بالضم وفتح الموحدة ثم ياء وقاف، عبد اللَّه بن خبيق الأنطاكى، عن يوسف بن أسباط زاهد مشهور اهـ. وفى الجرح (٢/ ٢/ ٤٦) قال ابن أبى حاتم: ادركته ولم اكتب عنه كتب إلى أبى بجزء من حديثه اهـ. والانطاكى كما في اللباب (١/ ٩٠) بفتح الالف وسكون النون وفتح الطاء - هذه النسبة إلى بلدة انطاكية من الشام، والدواء المسهل الذى يقال له الانطاكى منسوب إليها، وهو السمقونيا. اهـ."],[12489,"٢٠٣٠ - كنى ابن منده (١١٧/ أ)، كنى الحاكم (٢/ ٥/ أ) وقال \"أبو عبد اللَّه عن نافع ابن جبير بن مطعم عن على بن أبى طالب رضي الله عنه قال: كان النبى -صلى الله عليه وآله وسلم- لا طويل ولا قصير حسن الوجه. روى عنه الحجاج بن أرطأة. وقال ابن حجر في تعجيل المنفعة (ص ٣٢٦) أبو عبد اللَّه المكى عن نافع بن جبير عن على رضي الله عنه وعنه عثمان، وقال ابن حجر: قلت: كذا اختصره الحسينى والحديث عند عبد اللَّه بن أحمد في زياداته من طريق أبى خالد عن = ٢٠٣١ - أبو عبد اللَّه البكرى، روى عمن حدثه عن سعيد بن أبى سعيد المقبرى، روى عنه هشيم بن بشير الواسطى، وهو اسناد مجهول أكثره."],[12490,"٢٠٣٢ - أبو عبد اللَّه الشامى، عن طاوس بن كيسان. روى عنه الجراح بن مليح (الرؤاسى) (١)."],[12491,"٢٠٣٣ - أبو عبد اللَّه البصرى، عن سليمان التيمى. روى عنه عبد اللَّه بن وهب حديثا ليس بالقائم."],[12492,"= حجاج وهو ابن أرطأة عن عثمان عن أبى عبد اللَّه المكى، واظن فيه تصحيفا، والصواب عن عثمان بن عبد اللَّه المكى فقد أخرجه أحمد من طرق عن المسعودى ومسعر كلاهما عن عثمان بن عبد اللَّه بن هرمز عن نافع بن جبير عن على في صفة النبى -صلى الله عليه وآله وسلم-. والحديث عند الترمذى من طريق المسعودى. اهـ."],[12493,"قلت وانظر الحديث في المسند (١/ ٩٦ و١١٦ و١١٧ و١٢٧) وفى جامع الترمذى \"الفضائل\" (١٠/ ١١٦ و١١٧)."],[12494,"٢٠٣١ - كنى البخارى (ص ٥٠)، كنى ابن منده (١٧٧/ أ)، كنى الحاكم (٢/ ٥/ أ) وقال: أبو عبد اللَّه البكرى عن سعيد بن أبى سعيد المقبرى عن أبى هريرة قال قال رسول اللَّه -صلى الله عليه وآله وسلم- السفر قطعة من العذاب، روى عنه هشيم بن بشير الواسطى. الجرح (٤/ ٢/ ٤٠١)، وقال: سألت أبى عنه فقال: مجهول لا يسمى. الميزان (٤/ ٥٤٦)، وقال: لا شئ غمزه ابن حبان. ديوان الضعفاء (ص ٣٦١)، اللسان (٧/ ٧٣)."],[12495,"٢٠٣٢ - كنى الحاكم (٢/ ٥/ ب)."],[12496,"(١) في الأصل \"الراوسى\" بتقديم الالف على الواو. وهو خطأ."],[12497,"٢٠٣٣ - كنى الحاكم (٢/ ٥/ ب)، وقال: حديثه ليس بالقائم. ثم ساق الحديث من طريق أحمد بن عبد الرحمن، نا عمى حدثنا أبو عبد اللَّه البصرى عن سليمان التيمى، عن أبى عمر النهدى عن سلمان عن النبى -صلى الله عليه وآله وسلم- قال: البركة في ثلاثة في الجماعة والثريد، . . \" الحديث."],[12498,"٢٠٣٤ - أبو عبد اللَّه التميمى (١) من ولد أبى هاله (٢) زوج خديجة عن ابن لأبى هالة عن الحسن بن على. روى عنه جميع بن عمير (٣)."],[12499,"٢٠٣٥ - أبو عبد اللَّه الفلسطينى (٤). سمع عبد العزيز (٥) اخا حذيفة روى"],[12500,"٢٠٣٤ - كنى الحاكم (٢/ ٥/ ب)، اللسان (٧/ ١٤٨)، التهذيب (١٢/ ١٤٨) التقريب (٢/ ٤٤٥)، وقال: مجهول، من السادسة، قيل: اسمه يزيد بن عمر. /تم، الثقات (٧/ ٦٢٦)، التاريخ الكبير (٤/ ٢/ ٣٥٠)."],[12501,"(١) هكذا في الأصل \"التميمى\" وفى كنى الحاكم \"التيمى\"."],[12502,"(٢) أبو هالة ذكره ابن سعد في الطبقات الكبرى (٨/ ١٤) في ترجمة خديجة فقال: \"فتزوجها أبو هالة واسمه هند بن النباش بن زرارة بن وقدان بن حبيب ابن سلامة بن غوى بن جروة بن أسيد بن عمرو بن تميم. . فولدت خديجة لأبى هالة رجلا يقال له هند وهالة رجل أيضا وقال ابن سعد أيضا في الطبقات (١/ ٤٢٢): أخبرنا مالك بن إسماعيل أبو غسان النهدى أخبرنا جميع بن عمير بن عبد الرحمن العجلى حدثنى رجل بمكة عن ابن لأبى هالة التيمى عن الحسن بن على قال: سألت خالى هند بن أبى هالة التميمى، وكان وصافا، عن حلية رسول اللَّه -صلى الله عليه وآله وسلم- وأنا اشتهى ان يصف لى منها شيئا اتعلق به فقال: \"كان رسول اللَّه -صلى الله عليه وآله وسلم- فخما مفخما يتلألأ وجهه تلألؤ القمر ليلة البدر. . \" فذكر حديثا طويلا في وصف النبى -صلى الله عليه وآله وسلم-."],[12503,"(٣) جميع، بالتصغير، ابن عمير بالتصغير أيضا، ابن عبد الرحمن العجلى ضعيف، رافضى، من الثامنة. التقريب (١/ ١٣٣)."],[12504,"٢٠٣٥ - كنى الحاكم (٢/ ٦/ أ) أخرجه بعد أبى عبد اللَّه الفلسطينى الآتى بعد صاحب هذه الترجمة وقال في ترجمة أبى عبد اللَّه هذا: فلا أدرى هما اثنان أم واحد وخليقا ان يكونا واحدا، الثقات (٥/ ١٢٤) ذكره في ترجمة عبد العزيز أخى أبى حذيفة وذكر ان اسم أبى عبد اللَّه هذا \"حميد بن زياد اليمانى\"."],[12505,"(٤) في كنى الحاكم \"الأفلسطينى\"."],[12506,"(٥) عبد العزيز أخو حذيفة بن اليمان. انظر ترجمته في الثقات (٥/ ١٢٤) وقال ="],[12507,"عنه عكرمة بن عمار."],[12508,"٢٠٣٦ - أبو عبد اللَّه الفلسطينى. عن من رأى عبد اللَّه بن مُحَيْرِيز (١)، (٢) روى عنه شعبة. قال الحاكم: خليقا أن يكونا (٣) واحدا."],[12509,"٢٠٣٧ - أبو عبد اللَّه مولى أم مسكين بنت عاصم بن عمر بن الخطاب (٤) قال: ارسلتنى مولاتى إلى أبى هريرة. روى عنه على بن العلاء (٥) من حديث عبد الوارث."],[12510,"٢٠٣٨ - أبو عبد اللَّه العمرى قال: قيل لعمر بن عبد العزيز. روى عنه أحمد ابن أبى الحوارى الدمشقى."],[12511,"٢٠٣٩ - أبو عبد اللَّه عن عبد الرحمن بن أبى ليلى. روى عنه سالم بن أبى الجعد."],[12512,"= ابن حجر في التقريب (١/ ٥١٤) وثقة ابن حبان، من الثانية، وذكره بعضهم في الصحابة. اهـ."],[12513,"٣٠٣٦ - كنى الحاكم (٢/ ٦/ أ)."],[12514,"(١) عبد اللَّه بن محيريز، بمهملة وراء آخره زاى، مصغرا، ابن جنادة بن وهب الجُمَحى، بضم الجيم وفتح الميم بعدها مهملة، المكى، كان يتيما في حجر أبى محذورة بمكة، ثم نزل بيت المقدس، ثقة، عابد، من الثالثة. (ت: ٩٩) وقيل: بعدها. التقريب (١/ ٤٤٩)."],[12515,"(٢) في كنى الحاكم زيادة \"يصافح نصرانيا\"."],[12516,"(٣) هما أبو عبد اللَّه الفلسطينى هذا والذى تقدم قبله (٢٠٣٥)."],[12517,"٢٠٣٧ - لم أقف عليه عند غير المؤلف."],[12518,"(٤) أم مسكين بنت عاصم بن عمر بن الخطاب خالة عمر بن عبد العزيز تزوجها يزيد بن معاوية لما قدم المدينة وحملت إليه بالشام حكى عنها مولاها أبو عبد اللَّه أنها سألت أبا هريرة عن الحديث بعد العتمة. انظر التهذيب (١٢/ ٤٧٩)، وقال في التقريب (٢/ ٦٢٥) مقبولة من الثالثة."],[12519,"(٥) مقبول من السادسة./ بخ. التقريب (٢/ ٤٢)."],[12520,"٢٠٣٨ - لم أقف عليه عند غير المؤلف."],[12521,"٢٠٣٩ - كنى ابن منده (١٧٧/ أ)."],[12522,"٢٠٤٠ - أبو عبد اللَّه التميمى، سمع بريد بن أبى بردة الأشعرى (١) روى عنه يزيد بن هارون، فيه وفى ابن أبى هالة نظر. قاله الحاكم ربما كانا واحدا."],[12523,"٢٠٤١ - أبو عبد اللَّه الجَرسى (٢) مولى سليمان بن على بصرى. سمع سفيان بن حبيب (٣). روى عنه العباس بن مرثد."],[12524,"٢٠٤٢ - أبو عبد اللَّه الباهلى. سمع عبد الرحمن بن مغرا الدوسى روى عنه أبو بكر بن أبى الدنيا."],[12525,"٢٠٤٣ - أبو عبد اللَّه الشامى، عن ابن أبى مليكة، روى عنه المنهال بن خليفة (٤) قال الحاكم: لا أدرى إن كان الذى روى عنه طاوس (٥) أو غيره."],[12526,"٢٠٤٠ - لم أقف عليه عند غير المؤلف."],[12527,"(١) هو أبو بردة."],[12528,"٢٠٤١ - لم أقف عليه عند غير المؤلف."],[12529,"(٢) الجرسى: بفتح الجيم والراء ثم السين المهملة - نسبة إلى جرس وهو بطن من مزينة، وهو جرس بن لاطم بن عثمان بن مزينة. اللباب (١/ ٢٧١)."],[12530,"(٣) هو البصرى، أبو معاوية ذكره ابن أبى حاتم في الجرح (٢/ ١/ ٢٢٨)، وقال أبو حاتم: صالح الحديث."],[12531,"٢٠٤٢ - لم أقف عليه عند غير المؤلف."],[12532,"٢٠٤٣ - كنى ابن منده (١٧٧/ أ)، الميزان (٤/ ٥٤٤)، وقال: وهاه الازدى لعله محمد سعد المصلوب. ديوان الضعفاء (ص ٣٦٠)، اللسان (٧/ ٧٢)."],[12533,"(٤) المنهال بن خليفة العجلى، أبو قدامة الكوفى، ضعيف، من السابعة./ انظر التقريب (٢/ ٢٧٧)."],[12534,"(٥) الذى روى عنه طاووس هو المتقدم في (٢٠٣٢)."],[12535,"باب أبى عبد الرحمن"],[12536,"٢٠٤٤ - أبو عبد الرحمن، سمع أبا بكر الصديق، روى عنه عمرو بن دينار، قال عباس: سئل يحيى بن معين عنه فقال: لا أعرفه (١)."],[12537,"٢٠٤٥ - أبو عبد الرحمن، مكاتب عائشة، روى عنه عبد اللَّه بن عبد اللَّه الرازى، قاضى الرى (٢)."],[12538,"٢٠٤٦ - أبو عبد الرحمن عن أبى عبد اللَّه. سمع عبد الرحمن بن عوف وبلالا. حديثه عند شعبة، عن أبى بكر بن حفص بن عمر بن سعد بن أبى وقاص، عن أبى عبد اللَّه مولى لبنى مرة عنه."],[12539,"قال أبو عمر: هذا اسناد مقلوب مضطرب. مرة يقولون عن أبى عبد اللَّه عن أبى عبد الرحمن. ومرة عن أبى عبد الرحمن عن أبى عبد اللَّه، وكلاهما مجهول لا يعرف (٣) والعجيب انه من حديث شعبة وهو امام عن أبى بكر (بن"],[12540,"٢٠٤٤ - كنى البخارى (ص ٥٠)، الجرح (٤/ ٢/ ٤٠٢)، الثقات (٥/ ٥٨٨)."],[12541,"(١) الجرح (٤/ ٢/ ٤٠٢)."],[12542,"قلت: لم أقف على كلام يحيى في التاريخ رواية الدورى."],[12543,"٢٠٤٥ - كنى الدولابى (١/ ٤٢) وقال: مكاتب عائشة أو حاضنها."],[12544,"(٢) عبد اللَّه بن عبد اللَّه الرازى أصله، كوفى، صدوق، من الرابعة. انظر التقريب (١/ ٤٢٦)."],[12545,"٢٠٤٦ - الجرح (٤/ ٢/ ٤٠٢)، الميزان (٤/ ٥٤٧) وقال: لا يعرف، التهذيب (١٢/ ١٥٥)، التقريب (٢/ ٤٤٧)، وقال: قيل: هو مسلم بن يسار والا فمجهول، من الثانية./ د. س."],[12546,"(٣) قال الحافظ ابن حجر: \"وأما قول من قال فيه أبو عبد الرحمن عن أبى عبد اللَّه عن بلال فقد قلبه ابن جريح صرح بذلك غير واحد من الحفاظ وقال ابن عبد البر: مرة يقولون عن أبى عبد اللَّه عن أبى عبد الرحمن ومرة عن ="],[12547,"حفص) (١) وهو ثقة."],[12548,"٢٠٤٧ - أبو عبد الرحمن، مولى سعد بن أبى وقاص. عن سعد بن أبى وقاص، روى عنه يحيى بن أبى كثير."],[12549,"٢٠٤٨ - أبو عبد الرحمن، عن زياد بن أبى مريم (٢). روى عنه سلَّام بن سليم الطويل المدائنى (٣)."],[12550,"٢٠٤٩ - أبو عبد الرحمن، سمع أبا هريرة، روى عنه صالح بن كيسان مدنى."],[12551,"٢٠٥٠ - أبو عبد الرحمن الموصلى، روى عن ابن عمر، وإبراهيم النخعى، روى عنه موسى بن أبى عائشة."],[12552,"٢٠٥١ - أبو عبد الرحمن عن عامر الشعبى عن النعمان بن بشير عن النبى عليه السلام قال \"لا يشكر اللَّه من لا يشكر الناس\" (٤) لم يتابع عليه، روى عنه الجراح بن مليح الرؤاسى."],[12553,"= أبى عبد الرحمن عن أبى عبد اللَّه، وكلاهما مجهول لا يعرف\" أهـ. انظر مصادر الترجمة."],[12554,"(١) الحق في الهامش."],[12555,"٢٠٤٧ - المقتنى في سرد الكنى (٨٧/ أ)."],[12556,"٢٠٤٨ - المقتنى في سرد الكنى (٨٧/ أ)."],[12557,"(٢) زياد بن أبى مريم الجزرى، وثقة العجلى، من السادسة، ولم يثبت سماعه من أبى موسى، وجزم أهل بلده بأنه غير ابن الجراح. التقريب (١/ ٢٧٠)."],[12558,"(٣) سلّام، بتشديد اللام، ابن سليم أو سلم، أبو سليمان. ويقال له الطويل المدائنى، متروك، من السابعة (ت: ١٧٧)، التقريب (١/ ٣٤٢)."],[12559,"٢٠٤٩ - كنى البخارى (ص ٥٠)، الثقات (٥/ ٥٦٨)."],[12560,"٢٠٥٠ - كنى البخارى (ص ٥١)، الجرح (٤/ ٢/ ٤٠٢)، الثقات (٥/ ٥٦٥)."],[12561,"٢٠٥١ - الجرح (٤/ ٢/ ٤٠٣) وقال بعد أن ذكر الحديث: لم يتابع عليه. المقتنى في سرد الكنى (٨٧/ أ)."],[12562,"(٤) الحديث أخرجه أحمد في \"المسند\" (٤/ ٢٧٨ و٣٧٥) من طريق منصور ="],[12563,". . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . ."],[12564,"= ابن أبى مزاحم ويحيى بن عبد الرحمن مولى ابن هشام كلاهما عن أبى وكيع جراح بن مليح الرؤاسى في أبى عبد الرحمن، عن الشعبى، عن النعمان بن بشير قال: قال رسول اللَّه -صلى الله عليه وآله وسلم- على هذه الاعواد أو على هذا المنبر \"من لم يشكر القليل لم يشكر الكثير، ومن لم يشكر الناس لم يشكر اللَّه والتحدث بنعمة اللَّه شكر، وتركها كفر، والجماعة رحمة، والفرقة عذاب\" وزاد في حديث يحيى قال: فقال أبو أمامة الباهلى: \"عليكم بالسواد الاعظم. . \" الحديث."],[12565,"والحديث ذكره الهيثمى في مجمع الزوائد (٨/ ١٨٢) وعزاه لأحمد وقال: أبو عبد الرحمن راويه عن الشعبى لم أعرفه وبقيه رجاله ثقات."],[12566,"وأخرجه أيضا ابن أبى الدنيا في اصطناع المعروف. كما في كشف الخفاء ومزيل الالباس (٢/ ٢٧٨) وتحفة الأحوذى (٦/ ٨٨) وأخرجه أيضا القضاعى في المسند. كما في المقاصد الحسنة (ص ٤٢٨) وانظر أيضا اللباب في شرح الشهاب (ص ١٤٧) وقال المنذرى: اسناد حديث النعمان ابن بشير لا بأس به كما في تحفة الاحوذى (٦/ ٨٨)."],[12567,"والحديث أخرجه أيضا أحمد في المسند (٢/ ٢٥٨ و٢٩٥ و٣٠٣ و٣٨٨ و٤٦١ و٤٩٢) من حديث أبى هريرة رضي الله عنه وعند أحمد أيضا (٣/ ٣٢ و٧٤) من حديث أبى سعيد الخدرى رضي الله عنه وعنده أيضا في (٥/ ٢١١ و٢١٢) من حديث الأشعث بن قيس رضي الله عنه والبخارى في الأدب المفرد (ص ٦٥) وأبو داود \"الأدب\" (٤/ ٢٥٥) من حديث أبى هريرة أيضا والترمذى \"البر\" (٦/ ٨٧) وقال صحيح من حديث أبى هريرة أيضا، وأخرجه الترمذى أيضا في \"البر\" من حديث أبى سعيد الخدرى رضي الله عنه وقال: وفى الباب عن أبى هريرة والاشعث بن قيس والنعمان بن بشير. ثم قال: هذا حديث حسن. اهـ. كلهم أخرجوه بألفاظ متقاربة وبنحو حديث النعمان."],[12568,"قال الحاكم: قد قيل انه القاسم بن الوليد الهمدانى (١) فلا أدرى أيصح ذاك أم لا؟"],[12569,"٢٠٥٢ - أبو عبد الرحمن الجُبْلانى (٢). روى عنه أبو عبد الرحمن المرادى (٣)."],[12570,"٢٠٥٣ - أبو عبد الرحمن الشامى. سمع عمارة بن عثمان (٤) روى عنه المعافى بن عمران (٥). قال الحاكم: وخليقا ان يكون محمد بن سعيد المصلوب."],[12571,"(١) القاسم بن الوليد الهمدانى أبو عبد الرحمن الكوفى القاضى، صدوق، يغرب، من السابعة (ت: ١٤١). التقريب (٢/ ١٢١)."],[12572,"٢٠٥٢ - كنى البخارى (ص ٥١)، الجرح (٤/ ٢/ ٤٠٣)، تعجيل المنفعة (ص ٣٢٧)."],[12573,"(٢) الجُبْلانى: بضم الجيم وبالباء الساكنة الموحدة وفى آخرها نون بعد لام ألف - نسبة إلى جُبْلان وهو بطن من حمير وهو جبلان بن سهل بن عمرو بن قيس بن معاوية بن جشم بن عبد شمس بن وائل بن الغوث بن سعد بن عوف بن عدى بن مالك بن حمير وأخوه وصاب بن سهل إليه ينسب الوصابيون وهما بحمص. اهـ. الاكمال (٢/ ١٧٦)، اللباب (١/ ٢٥٨)"],[12574,"(٣) زاد في الجرح محمد بن عبد الرحمن مؤذن مسجد مصر."],[12575,"قلت: وستأتى ترجمة أبى عبد الرحمن المرادى في (٢٠٥٥) إن شاء اللَّه تعالى."],[12576,"٢٠٥٣ - المقتنى في صد الكنى (٨٧/ أ) وقال: أبو عبد الرحمن الشامى. كأنه المصلوب عنه المعافى الموصلى."],[12577,"(٤) عمارة بن عثمان بن حنيف الأنصارى المدنى، مقبول، من الثالثة. التقريب (٢/ ٥٠)."],[12578,"(٥) المعافى بن عمران الازدى الفهمى، أبو مسعود الموصلى، ثقة عابد من كبار التاسعة (ت: ١٨٥) وقيل: سنة (١٨٦) التقريب (٢/ ٢٥٨) الجرح (٤/ ١/ ٣٩٩)."],[12579,"٢٠٥٤ - أبو عبد الرحمن الطائى. عن الضحاك السكسكى (١). قيل: انه الهيثم بن عدى (٢)، حديثه متروك."],[12580,"٢٠٥٥ - أبو عبد الرحمن المرادى. سمع أبا عبد الرحمن الجبلانى (٣). كلاهما مجهول."],[12581,"٢٠٥٦ - أبو عبد الرحمن، عن الأعمش، روى عنه جرول بن جيفل (٤) حديثه ليس بالقائم."],[12582,"٢٠٥٧ - أبو عبد الرحمن، عن أبى عبد اللَّه (٥)، مولى بنى تميم. مجهول عن مجهول."],[12583,"٢٠٥٤ - ذكره الذهبى في المقتنى في سرد الكنى (٨٦/ أ) فيمن يكنى أبا عبد الرحمن: وذكر انه الهيثم بن عدى الطائى وقال: واه."],[12584,"(١) الضحاك بن زمل بن عمرو السكسكى، روى عن أبيه عنه الهيثم بن عدى. الجرح (٢/ ١/ ٤٦١)."],[12585,"(٢) الهيثم بن عدى الطائى أبو عبد الرحمن المنبجى ثم الكوفى، قال البخارى ليس بثقة كان يكذب، وقال أبو داود كذاب، وقال النسائى وغيره: كان متروك الحديث. اللسان (٦/ ٢٠٩)."],[12586,"٢٠٥٥ - كنى البخارى (ص ٥١)."],[12587,"(٣) في كنى البخارى \"الجبلى\"."],[12588,"٢٠٥٦ - كنى البخارى (ص ١٥١)، الميزان (٤/ ٥٤٧)، وقال: مجهول. اللسان (٧/ ٧٥) وقال أيضا: مجهول."],[12589,"(٤) جرول بن جيفل الحرانى أبو توبة النميرى، ذكره ابن أبى حاتم في الجرح (١/ ١/ ٥٥١) وقال: سألت أبى عنه فقال: لا بأس به. وقال أيضا سمعت أبا زرعة يقول: كان صدوقا ما كان به بأس اهـ. وانظر اللسان (٢/ ١٠١)."],[12590,"٢٠٥٧ - كنى البخارى (ص ٥١)."],[12591,"(٥) تقدم في (٢٠٠٨)."],[12592,"٢٠٥٨ - أبو عبد الرحمن مولى أم همام (١) أو أم قهد، سمع أبا هريرة. روى عنه محمد بن مسلم بن السائب (٢). قال الحاكم أبو أحمد: وقد قيل: فيه عبد الرحمن. واللَّه أعلم، بالصحيح منهما."],[12593,"٢٠٥٩ - أبو عبد الرحمن الكندى. سمع كثير بن مرد (٣) في الصلوات. روى عنه معاوية بن صالح."],[12594,"٢٠٦٠ - أبو عبد الرحمن الحارثى عن مسلم الملائى (٤). روى عنه وليد بن حماد. قال أبو أحمد (٥). وقد خرجت فيمن له اسم وعرف بكنيته أبا عبد الرحمن عبد اللَّه بن الأسود الحارثى. سمع حصين بن عمر (٦)."],[12595,"٢٠٥٨ - كنى البخارى (ص ٥١)، المقتنى في سرد الكنى (٨٧/ أ) وقال مولى أم قوام سمع أبا هريرة."],[12596,"(١) هكذا في الأصل \"أم همام أو أم قهد\". والذى في تهذيب الكمال (٣/ ١٢٦٨) في ترجمة محمد بن مسلم بن السائب \"أم فهكم\" وفى التهذيب (٩/ ٤٤٣) في ترجمة محمد بن مسلم بن السائب \"أم مشكم\" وفى المقتنى في سرد الكنى \"أم قوام\" فاللَّه أعلم."],[12597,"(٢) محمد بن مسلم بن السائب. مقبول، من الخامسة. انظر التقريب (٢/ ٢٠٧)."],[12598,"٢٠٥٩ - كنى البخارى (ص ٥١)، الجرح (٤/ ٢/ ٤٠٣)، تعجيل المنفعة (ص ٣٢٧)."],[12599,"(٣) كثير بن مرة الحضرمى، الحمصى، ثقة، من الثانية، ووهم من عدّه في الصحابة. التقريب (٢/ ١٣٣)."],[12600,"٢٠٦٠ - لم أقف عليه عند غير المؤلف."],[12601,"(٤) مسلم بن كيسان الضبى الملائى البرّاد الأعور. أبو عبد اللَّه الكوفى، ضعيف، من الخامسة./ ت. ق. انظر التقريب (٢/ ٢٤٦)."],[12602,"(٥) لم أقف على قول الحاكم في الكنى والأسماء له."],[12603,"(٦) حصين بن عمر الأحمسى، بمهملتين، الكوفى، متروك، من الثامنة./ ت. التقريب (١/ ١٨٣)، وانظر الجرح (١/ ٢/ ١٩٤)."],[12604,"روى عنه محمد بن بشر العبدى. فلا أدرى هما اثنان أو واحد. وخليقا أن يكونا اثنين. . واللَّه أعلم."],[12605,"٢٠٦١ - أبو عبد الرحمن الأنصارى. عن زيد بن اسلم حدث عنه. . بقيه ابن الوليد بحديث منكر الاسناد."],[12606,"٢٠٦٢ - أبو عبد الرحمن الأنصارى. عن زيد بن مسلم حدث عنه بقيه بن الوليد بحديث منكر الاسناد."],[12607,"٢٠٦٣ - أبو عبد الرحمن الصائغ، روى حديثه مرفوعا في فضل الماء."],[12608,"٢٠٦١ - المقتنى في سرد الكنى (٨٧/ أ)، الميزان (٤/ ٥٤٧) وقال: من شيوخ بقية الذين لا يعرفون بخبر منكر. اللسان (٧/ ٧٥) وقال: بخبر منكر، وهو من شيوخ بقية الذين لا يعرفون."],[12609,"٢٠٦٢ - مكرر سابقه تماما كما هو ملاحظ."],[12610,"٢٠٦٣ - لم أقف له على ترجمة عند غير المؤلف."],[12611,"باب أبى عبيدة"],[12612,"٢٠٦٤ - أبو عبيدة بن عبد اللَّه بن مسعود. روى عن أبيه. روى عنه أبو اسحاق السبيعى. ذكر اسحاق بن منصور عن يحيى بن معين قال (١): أبو عبيدة بن عبد اللَّه بن مسعود ثقة. وسئل أبو زرعة عن اسم أبى عبيدة هذا فقال (٢): اسمه كنيته واحدة (٣). قال ابن أبى حاتم: وسمعت أبى يقول: أبو عبيدة بن عبد اللَّه بن مسعود لا يسمّى (٤). قال أبو عمر: قد ذكره قوم فسموه عامرا (٥)."],[12613,"٢٠٦٥ - أبو عبيدة. روى عن سلمان أنه قال: \"انه رخص في الجبن والفراء (٦) والسمن\" (٧)."],[12614,"٢٠٦٤ - كنى البخارى (ص ٥١ - ٥٢)، الجرح (٤/ ٢/ ٤٠٣)، تعجيل المنفعة (ص ٣٢٨ - ٣٢٩)."],[12615,"(١، ٢، ٣) الجرح (٤/ ٢/ ٤٠٣)."],[12616,"(٤) هكذا في الأصل \"واحدة\" وفى الجرح \"واحد\"."],[12617,"(٥) تقدم في (٩٤٥) أبو عبيدة عامر بن عبد اللَّه بن مسعود."],[12618,"٢٠٦٥ - الجرح (٤/ ٢/ ٤٠٤)، الميزان (٤/ ٥٤٩) وقال: مجهول، اللسان (٧/ ٧٩)."],[12619,"(٦) الفراء، مقصور، مهموز، وهو حمار الوحش، وجمعه فراء، مهموز ممدود. انظر غريب الحديث (٢/ ٢٢٦). النهاية (٣/ ٤٢٢) والفراء أيضا جمع فرو وفروة وهو اللباس المعروف. انظر لسان العرب مادة \"فراء\" (١٥/ ١٥١)."],[12620,"(٧) الحديث أخرجه الترمذى \"اللباس\" باب ما جاء في لبس الفراء (٣/ ٤٢٢) وابن ماجه \"الأطعمة\" باب أكل الجبن والسمن (٢/ ١١١٧) كلاهما من طريق سليمان التيمى عن أبى عثمان النهدى عن سلمان الفارسى قال: سئل رسول اللَّه -صلى الله عليه وآله وسلم- عن السمن والجبن والفراء؟ فقال: الحلال ما أحل اللَّه في كتابه والحرام ما حرّم اللَّه في كتابه، وما سكت عنه فهو مما عفى عنه. وقال ="],[12621,"روى عنه يونس بن خباب (١). قال أبو حاتم: أبو عبيدة هذا ليس هو ابن عبد اللَّه بن مسعود هو رجل آخر (٢)."],[12622,"٢٠٦٦ - أبو عبيدة بن حذيفة بن (الخيار) (٣) العبسى، روى عن أبيه حذيفة، وعن أبى موسى الأشعرى، روى عنه يوسف بن ميمون القرشى (٤) ومحمد ابن سيرين ويزيد بن خالد الواسطى."],[12623,"٢٠٦٧ - أبو عبيدة، عن أنس بن مالك، روى عنه سفيان بن حسين، قاله البخارى، وغيره."],[12624,"= الترمذى: وفى الباب عن المغيرة، هذا حديث غريب لا نعرفه مرفوعا إلا من هذا الوجه. وروى سفيان وغيره عن سليمان التيمى عن أبى عثمان قوله، وكأن الحديث الموقوف أصح\". اهـ."],[12625,"(١) يونس بن خبّاب، بمعجمة وموحدتين، الاسدى، مولاهم الكوفى، صدوق، يخطئ، ورمى بالرفض، من السادسة. التقريب (٢/ ٣٨٤)."],[12626,"(٢) الجرح (٤/ ٢/ ٤٠٤) وزاد كلمة \"مجهول\"."],[12627,"٢٠٦٦ - كنى البخارى (ص ٥١)، الثقات (٥/ ٥٩٠)، تهذيب الكمال (٣/ ١٦٢٣ - ١٦٢٤)، الجرح (٤/ ٢/ ٤٠٣) وقال: سمعت أبى يقول: لا يسمى. التهذيب (١٢/ ١٥٩)، التقريب (٢/ ٤٤٨) وقال: مقبول، من الثانية./ س. ق."],[12628,"(٣) هكذا في الأصل والمثبت في جميع مصادر الترجمة \"اليمان\"."],[12629,"(٤) يوسف بن ميمون المخزومى القرشى، الكوفى، الصباغ، ضعيف، من الرابعة. التقريب (٢/ ٣٨٣)، التهذيب (١١/ ٣٢٦)."],[12630,"٢٠٦٧ - كنى البخارى (ص ٥٢)، الجرح (٤/ ٢/ ٤٠٤)، الميزان (٤/ ٥٤٨)، وقال: هو حميد الطويل، التهذيب (١٢/ ١٦١) وقال: ذكره البخارى في الكنى المجردة وقال الدورى عن ابن معين هو حميد الطويل وكذا حرر ذلك الحاكم أبو أحمد. . اهـ. وانظر تاريخ ابن معين روايه الدورى (٢/ ١٣٥)، التقريب (٢/ ٤٤٨) وقال: يقال هو حميد الطويل، وإلا فمجهول من الخامسة./ ز."],[12631,"وقال أبو أحمد الحاكم: خليقا ان يكون أبو عبيدة هذا حميدا الطويل. كناه سفيان بن حسين بكنيته وخفى ذلك على محمد بن إسماعيل البخارى، وقد حدث سفيان هذا عن حميد (١)."],[12632,"٢٠٦٨ - أبو عبيدة مولى (٢) ابن سيرين. روى عن ابن سيرين. روى عنه عبد اللَّه بن عون وسليمان بن الحسن."],[12633,"٢٠٦٩ - أبو عبيدة. روى عن يزيد الرحبى (٣). روى عنه محمد بن حمير."],[12634,"٢٠٧٠ - أبو عبيدة، روى عن أبى صخرة أو أبى صخر (٤)، روى عنه عثمان ابن عبد الرحمن الطرائفى (٥)."],[12635,"(١) ذكر ابن حجر في التهذيب (٤/ ١٠٧) بأن سفيان بن حسين بن الحسن روى عن حميد الطويل."],[12636,"٢٠٦٨ - كنى البخارى (ص ٥٢)، الثقات (٧/ ٦٥٧)، الجرح (٤/ ٢/ ٤٠٤)."],[12637,"(٢) في كنى البخارى والثقات \"من آل ابن سيرين\"."],[12638,"٢٠٦٩ - الجرح (٤/ ٢/ ٤٠٤) وقال: سألت أبى عنه فقال: مجهول، الميزان: (٤/ ٥٤٩) وقال: مجهول."],[12639,"(٣) يزيد بن يوسف الرحبى، بفتح الراء والمهملة بعدها موحدة، الصنعانى صنعاء دمشق، ضعيف، من التاسعة. التقريب (٢/ ٣٧٢)."],[12640,"٢٠٧٠ - الجرح (٤/ ٢/ ٤٠٤)، وقال: سألت أبى عنه فقال: هو مجهول، الميزان (٤/ ٥٤٩) وقال: مجهول، اللسان (٧/ ٧٩) وقال: مجهول."],[12641,"(٤) هو صاحب العباء المتقدم في (١٩٨٨)."],[12642,"(٥) صدوق، أكثر الرواية عن الضعفاء والمجاهيل، فضعّف بسبب ذلك حتى نسبه ابن نمير إلى الكذب، وقد وثقه ابن معين، من التاسعة (ت: ٢٠٢) انظر التقريب (٢/ ١١). والطرائفى. بفتح الطاء والراء كسر الياء المثناة من تحتها وفى آخرها فاء - هذه النسبة إلى بيع الطرائف وشرائها، وهى الأشياء الحسنة المتخذة من الخشب، والمشهور بهذه النسبة جماعة، وأما عثمان ابن عبد الرحمن بن مسلم الطرائفى هذا فإنما قيل له ذلك لأنه كان يتبع طرائف الحديث، ويرويها عن قوم ضعاف. انظر اللباب (٢/ ٢٧٨)."],[12643,"٢٠٧١ - أبو عبيدة بن عبد اللَّه بن زمعة بن الأسود بن المطلب بن اسد بن عبد العزيز القرشى الأسدى أمه زينب (١) بنت أبى سلمة بن عبد الاسد القرشى وهى بنت أم سلمة أم المؤمنين، روى عن جدته أم سلمه. روى عنه الزهرى وقد روى عن الزهرى، عن أبى عبيدة هذا عن أبيه (٢) عن أم سلمة اتفقوا على أنه لا اسم له."],[12644,"٢٠٧٢ - أبو عبيدة بن محمد بن عمار بن ياسر العنسى حليف بنى مخزوم، روى عن جابر بن عبد اللَّه، والربيع بنت معوذ بن عفراء (٣). روى عنه"],[12645,"٢٠٧١ - الجرح (٤/ ٢/ ٤٠٤ - ٤٠٥) وقال: سئل أبو زرعة عن اسم أبى عبيدة هذا فقال: لا أعرف اسمه ولا أعلم أحدا سماه. . سمعت أبى يقول: أبو عبيدة بن عبد اللَّه بن زمعة لا أعلم له اسما، المقتنى في سرد الكنى (٩٠/ أ)، تهذيب الكمال (٣/ ١٦٢٤)، التهذيب (١٢/ ١٥٩)، التقريب (٢/ ٤٤٨)، وقال: مقبول، من الثالثة/ م. د. س. ق."],[12646,"(١) زينب بنت أبى سلمة بن عبد الأسد، المخزومية، ربيبة النبى -صلى الله عليه وآله وسلم- ماتت سنة ثلاث وسبعين وحضر ابن عمر جنازتها قبل ان يحج ويموت بمكة./ ع. التقريب (٢/ ٦٠٠)."],[12647,"(٢) هو عبد اللَّه بن زمعة بن الأسود بن المطلب الاسدى ابن أخت أم سلمة أحد الاشراف \"كان يأذن على النبى -صلى الله عليه وآله وسلم-\" التجريد (١/ ٣١١)."],[12648,"٢٠٧٢ - كنى البخارى (ص ٥٢)، الجرح (٤/ ٢/ ٤٠٥) وقال: \"سمعت أبى يقول: منكر الحديث. \"تهذيب الكمال\" (٣/ ١٦٢٤)، الميزان (٤/ ٥٤٩) وقال: صدوق إن شاء اللَّه، اللسان (٧/ ٤٧٣) وقال: وثقه يحيى بن معين، المقتنى في سرد الكنى (٧/ ٤٧٣) وقال: وثقه يحيى بن معين، المقتنى في سرد الكنى (٩٠/ أ)، التهذيب (١٢/ ١٦٠)، التقريب (٢/ ٤٤٨) وقال: أخو سلمة وقيل: هو مقبول، من الرابعة./ ع."],[12649,"(٣) الربيع بنت معوذ، انصارية بايعت تحت الشجرة وتأخرت وفاتها. التجريد (٢/ ٢٦٧)."],[12650,"محمد بن اسحاق، (ويعقوب بن عبد اللَّه بن أبى سلمة) (١) المَاجِشُون (٢)."],[12651,"٢٠٧٣ - أبو عبيدة بن الفضيل بن عياض بن مسعود التميمى اليربوعى. سمع عبد الرحمن بن عبد اللَّه مولى بنى هاشم البصرى روى عنه الحسين بن محمد بن زياد."],[12652,"٢٠٧٤ - أبو عبيدة الازدى (٣). سمع معاذ بن جبل. روى عنه إبراهيم بن عبد الأعلى (٤)."],[12653,"(١) هكذا في الأصل \"يعقوب بن عبد اللَّه بن أبى سلمة\" والذى في تهذيب الكمال والتهذيب والتقريب \"يعقوب بن أبى سلمة\" ويعقوب هذا هو أبو يوسف المدنى، صدوق، من الرابعة (ت: بعد ١٢٠). التقريب (٢/ ٣٧٥)، التهذيب (١١/ ٣٨٨)."],[12654,"(٢) الماجشون: بفتح الميم كسر الجيم وضم الشين المعجمة وفى آخرها النون - هذا لقب أبى سلمة يوسف بن يعقوب بن عبد اللَّه بن أبى سلمة الماجشون لحمرة خديه، وهذه لغة أهل المدينة، والماجشون الورد. اهـ. انظر اللباب (٣/ ١٤١)."],[12655,"٢٠٧٣ - التاريخ الصغير (ص ٢٣٢)، ديوان الضعفاء (ص ٣٦١)، الميزان (٤/ ٥٤٩)، اللسان (٧/ ٧٩)، العقد الثمين (٨/ ٦٩ - ٧٠) قال الذهبى وتبعه ابن حجر: فيه لين، قال ابن الجوزى ضعيف، وقد وثقة الدارقطنى، فلا يلتفت إلى كلام ابن الجوزى بلا سبب. اهـ."],[12656,"٢٠٧٤ - كنى البخارى (ص ٥١)، الثقات (٥/ ٥٦٧)."],[12657,"(٣) في الثقات \"الأودى\" بالواو."],[12658,"(٤) إبراهيم بن عبد الاعلى الجعفى مولاهم، الكوفى، ثقة من السادسة. التقريب (١/ ٣٨)."],[12659,"٢٠٧٥ - أبو عبيدة بن عقبة بن نافع القرشى الفهرى (١) مصرى وكان (أبوه) (٢) على مصر، وافريقيه (٣). روى عن ابن عمر، وعن أخيه عياض بن عقبة وعن رجل عن شرحبيل بن السِّمْط (٤). روى عنه عبد الكريم بن الحارث (٥) وصاعد بن محمد (٦) (وحسين بن أبى حكيم) (٧)."],[12660,"٢٠٧٦ - أبو عبيدة الرعينى. سأل سالم بن عبد اللَّه بن عمر عن عذاب القبر."],[12661,"٢٠٧٥ - كنى البخارى (ص ٥١)، الثقات (٥/ ٥٦٨) و(٧/ ٦٦٣)، فتوح مصر (ص ٨٤)، ذكره ابن حبان في موضعين في الثقات، الجرح (٤/ ٢/ ٤٠٤)، تهذيب الكمال (٣/ ١٦٢٤)، التهذيب (١٢/ ١٦٠)، التقريب (٢/ ٤٤٨) وقال: مقبول، من الثالثة (ت: ١٠٧). م. س."],[12662,"(١) في تهذيب الكمال، والتهذيب والتقريب زيادة \"قيل: اسمه مرة\"."],[12663,"(٢) في كنى البخارى \"جده\" وفى التجريد (١/ ٣٨٤ - ٣٨٥) عقبة بن رافع وقيل: ابن نافع بن عبد القيس بن لقيط القرشى الفهرى الامير، شهد فتح مصر وولى امرة المغرب، واستشهد بافريقية. . ولد على عهد الرسول -صلى الله عليه وآله وسلم- ولا تصح له صحبة."],[12664,"(٣) يذكر المزى في تهذيب الكمال (٣/ ١٦٢٤) في ترجمة أبى عبيدة بن عقبة قال: \"قال أبو عمر بن عبد البر: كان أبوه على مصر وافريقية\" اهـ."],[12665,"(٤) شرحبيل بن السّمط: بكسر المهملة وسكون الميم، الكندى الشامى جزم ابن سعد بأن له وفادة، ثم شهد القادسية وفتح حمص، وعمل عليها لمعاوية (ت: ٤٠) أو بعدها. التقريب (١/ ٣٤٨)."],[12666,"(٥) عبد الكريم بن الحارث بن يزيد الحضرمى، المصرى ثقة عابد، من السادسة، وروايته عن المستورد منقطعة. التقريب (١/ ٥١٥)."],[12667,"(٦) صاعد بن محمد، مصرى. ذكره ابن أبى حاتم وذكر روايته عن أبى عبيدة ابن عقبة بن نافع. انظر الجرح (٢/ ١/ ٤٥٢)."],[12668,"(٧) هكذا في الأصل \"حسين بن أبى حكيم\" والذى في تهذيب الكمال والتهذيب \"جبير بن أبى حكيم\"."],[12669,"٢٠٧٦ - المقتنى في سرد الكنى (٩٠/ أ)."],[12670,"٢٠٧٧ - أبو عبيدة صاحب الدّستوائى، عن الحسن وابن سيرين روى عنه مسكين بن عبد اللَّه (١). قال أبو أحمد الحاكم: وخليقا أن يكون أبا عبيدة الناجى بكر بن الأسود صاحب المواعظ (٢)."],[12671,"٢٠٧٧ - كنى مسلم (ص ٧١١)، المقتنى في سرد الكنى (٩٠/ أ) وقال: أبو عبيدة الدستوائى عن الحسن فلعله بكر بن الأسود، الميزان (٤/ ٥٤٩)، اللسان (٧/ ٧٩) وقالا: قال يحيى بن معين: مجهول."],[12672,"(١) مسكين بن عبد اللَّه أبو فاطمة، ذكره ابن أبى حاتم في الجرح (٤/ ١/ ٣٢٩) وقال ابن أبى حاتم عن أبيه: وهن امر مسكين بحديث رواه."],[12673,"(٢) تقدم في (٩٤٦)."],[12674,"باب أبى عبيد الله"],[12675,"٢٠٧٨ - أبو عبيد اللَّه مولى ابن عباس، روى عن سلمان الفارسى وعن ابن عباس، روى عنه الحجاج بن ارطاة ويونس بن خباب الأسدى أبو الجهم."],[12676,"روى عبد الواحد بن زياد عن الحجاج عن أبى عبيد اللَّه عن ابن عباس قال: لو يعلم المقيمون ما لحاج بيت اللَّه عليهم من الفضل لأتوهم إذا قدموا يقبلون رواحلهم. انهم وفد اللَّه (١)."],[12677,"٢٠٧٩ - أبو عبيد اللَّه. روى عنه قوله في معنى قول اللَّه: ﴿فَأَجَاءَهَا الْمَخَاضُ إِلَى جِذْعِ النَّخْلَةِ﴾ (٢)، (٣) قاله ثابت بن يزيد (٤) عن هلال بن خبّاب عن أبى عبيد اللَّه."],[12678,"٢٠٧٨ - كنى البخارى (ص ٥٣)، الثقات (٥/ ٥٧٠)، المقتنى في سرد الكنى (٨٩/ أ)."],[12679,"(١) لم أقف على هذا الحديث غير ان الحافظ الهيثمى ذكر في مجمع الزوائد (٣/ ٢٧٧) كتاب الحج \"باب فضل الحج حديثا عن ابن عباس قال: سمعت النبى -صلى الله عليه وآله وسلم- يقول: لو يعلم أهل الجمع بمن حلوا لاستبشروا بالفضل بعد المغفرة\". وقال الهيثمى: رواه الطبرانى في الكبير وفى اسناده من لم اعرفه. اهـ."],[12680,"٢٠٧٩ - المقتنى في سرد الكنى (٨٩/ أ)."],[12681,"(٢) سورة مريم: ٢٣."],[12682,"(٣) الحديث أخرجه عبد بن حميد كما في الدر المنثور (٤/ ٢٦٧) من طريق هلال بن خباب عن أبى عبيد اللَّه فأجاءها المخاض إلى جذع نخلة يابسة قد جئ به ليُبْنى به بيت يقال له: بيت لحم فحركته فإذا هو نخلة\"."],[12683,"(٤) ثابت بن يزيد الأحول، أبو زيد البصرى، ثقة ثبت من السابعة (ت: ١٦٩). انظر التقريب (١/ ١١٨)، التهذيب (٢/ ١٨)."],[12684,"٢٠٨٠ - أبو عبيد اللَّه، ويقال: أبو عبد اللَّه. . جليس جعفر بن ربيعة. روى عنه حيوة وقد تقدم (١)."],[12685,"٢٠٨٠ - كنى البخارى (ص ٥٣)."],[12686,"(١) تقدم في أبى عبد اللَّه انظر الترجمة (٢٠٢٨)."],[12687,"باب أبى عبد الجبار"],[12688,"٢٠٨١ - أبو عبد الجبار، سمع عائشة بنت سعد مدنى، روى عنه عبيد اللَّه ابن عمر."],[12689,"٢٠٨٢ - أبو عبد الجبار، المصرى، روى عن الحسن، روى عنه الضحاك ابن عثمان (١)."],[12690,"٢٠٨١ - كنى البخارى (ص ٥٣)، الجرح (٤/ ٢/ ٤٠٦)، الثقات (٧/ ٦٥٩) كنى الحاكم (٢/ ٢٨/ أ)."],[12691,"٢٠٨٢ - الجرح (٤/ ٢/ ٤٠٦)، كنى الحاكم (٢/ ٢٨/ أ)، الثقات (٧/ ٦٥٨)."],[12692,"(١) الضحاك بن عثمان بن عبد اللَّه بن خالد بن حرام الاسدى، الحزامى، بكسر أوله وبالزاى، أبو عثمان المدنى، صدوق يهم، من السابعة. التقريب (١/ ٣٧٣)."],[12693,"باب أبى عبد العزيز"],[12694,"٢٠٨٣ - أبو عبد العزيز، قال: \"أمسى أبو هريرة عندنا\" (١) روى عنه أبو جمرة (٢)."],[12695,"٢٠٨٤ - أبو عبد العزيز الحرشى من أهل الثغر. سمع سفيان بن عيينة حدث عنه إبراهيم بن الحسن."],[12696,"٢٠٨٣ - كنى البخارى (ص ٥٣)، المقتنى في سرد الكنى (٨٧/ ب)، الجرح (٤/ ٢/ ٤٠٦)، وقال: سمعت أبى يقول: هو مجهول. الثقات (٥/ ٥٩٠)، الميزان (٤/ ٥٤٨)، وقال: مجهول. له في ذم الاماره اللسان (٧/ ٤٧٣). وقال: وثقه ابن حبان. التهذيب (١٢/ ١٥٦) التقريب (٢/ ٤٤٧) وقال: مجهول، من الثالثة./ بخ."],[12697,"(١) ذكر هذا الأثر في جميع مصادر الترجمة."],[12698,"(٢) ورد في بعض المصادر \"حمزة\" مصحفا، وإنما هو أبو جمرة نصر بن عمران كما صرح بذلك ابن حجر في اللسان. انظر مصادر الترجمة."],[12699,"٢٠٨٤ - المقتنى في سرد الكنى (٨٧/ ب)."],[12700,"باب أبى عبد الملك"],[12701,"٢٠٨٥ - أبو عبد الملك القارئ، شامى روى عن يحيى بن الحارث الذمارى. روى عنه مروان بن محمد الطاطرى ومحمد بن حسان الأسدى."],[12702,"٢٠٨٦ - أبو عبد الملك، مصرى، روى عن حذيفة بن اليمان. روى عنه بكر بن عمرو المعافرى."],[12703,"٢٠٨٧ - أبو عبد الملك مولى أم مسكين بنت عاصم بن عمر بن الخطاب. أرسلته مولاته إلى أبى هريرة. روى عنه (يحيى) (١) بن العلاء الخزاعى."],[12704,"٢٠٨٨ - أبو عبد الملك، رجل من قريش، روى عنه قتادة قال: قتل يوم صفين ستون الفا."],[12705,"٢٠٨٥ - المقتنى في سرد الكنى (٨٨/ ب)."],[12706,"٢٠٨٦ - المقتنى في سرد الكنى (٨٨/ ب)."],[12707,"٢٠٨٧ - كنى البخارى (ص ٥٣)، الجرح (٤/ ٢/ ٤٠٦)، المقتنى في سرد الكنى (٨٨/ ب). الميزان (٤/ ٥٤٨) وقال: مجهول. ديوان الضعفاء (ص ٣٦١) اللسان (٧/ ٥٤٨). وقال: مجهول، التهذيب (١٢/ ١٥٦)، التقريب (٢/ ٤٧٧) وقال: مجهول، من الثالثة./ بخ."],[12708,"(١) هكذا في الأصل \"يحيى\" وفى مصادر الترجمة \"على\" ولم أقف على من اسمه يحيى بن العلاء الخزاعى روى عن أبى عبد الملك مولى أم مسكين. وقد ذكر ابن حجر في التهذيب (٧/ ٣٦٨) على بن العلاء الخزاعى روى عن الحسن البصرى وأبى عبد الملك مولى أم مسكين بنت عاصم بن عمر بن الخطاب. الخ. وفى التقريب (٢/ ٤٢) قال: \"على بن العلاء الخزاعى\"، مقبول، من السادسة./ بخ. اهـ."],[12709,"٢٠٨٨ - المقتنى في سرد الكنى (٨٨/ ب) وذكر أنه روى عنه الأصمعى."],[12710,"باب أبى عبد الحميد"],[12711,"٢٠٨٩ - أبو عبد الحميد قال: كتب سلمان إلى أبى الدرداء سمعت النبى عليه السلام يقول: \"المسجد بيت كل تقى\" (١)."],[12712,"٢٠٩٠ - أبو عبد الحميد. عن أبى هريرة. روى عنه إبراهيم بن سعيد (٢) وكلاهما مجهولان لا يعرفان."],[12713,"٢٠٨٩ - الميزان (٤/ ٥٤٦) وقال: لا يدرى من ذا وذكر الحديث وقال: نقله الحاكم أبو أحمد، اللسان (٧/ ٧٥) وقال كما قال الذهبى تماما."],[12714,"(١) الحديث أخرجه الطبرانى في الكبير، لكن عن أبى عثمان قال: كتب سلمان إلى أبى الدرداء: يا أخى ليكن المسجد بيتك فإنى سمعت رسول اللَّه -صلى الله عليه وآله وسلم- يقول: \"المسجد بيت كل تقى، وقد ضمن اللَّه عز وجل لمن كانت المساجد بيوته، الروح والرحمة والجواز على الصراط. والحديث ذكره الهيثمى في مجمع الزوائد (٢/ ٢٢) وقال: فيه صالح المزى وهو ضعيف. وذكره الحافظ المناوى في الجامع الأزهر (٣/ ٥٤/ ب) وعزاه أيضًا إلى الطبرانى في الكبير وقال: فيه صالح المزى وهو ضعيف."],[12715,"والحديث أخرجه أيضًا البزار. كما في كشف الاستار (١/ ٢١٧) و(٢١٨)، عن أبى الدرداء قال: لتكن المساجد بيتك فانى سمعت رسول اللَّه -صلى الله عليه وآله وسلم- يقول: \"فذكره. وقال البزار: لا نعلم هذا الحديث بهذا اللفظ إلا بهذا الإسناد وإسناده حسن، وقد روى نحوه بغير لفظه. اهـ. وعزاه الهيثمى في مجمع الزوائد (٢/ ٢٢) أيضًا إلى الطبرانى في الكبير والأوسط والبزار وقال: إسناده حسن. وعزاه الحافظ المناوى في الجامع الأزهر (٣/ ٥٤/ ب) أيضًا إلى الطبرانى في الكبير والأوسط والبزار وقال: إسناده حسن ورجال البزار رجال الصحيح. اهـ."],[12716,"٢٠٩٠ - المقتنى في سرد الكنى (٨٤/ ب) وذكره كما هنا تماما."],[12717,"(٢) إبراهيم بن سعيد، ذكره ابن أبى حاتم، وذكر روايته عن أبى عبد الحميد عن أبى هريرة، ولم يذكر فيه شيئًا. انظر الجرح (١/ ١/ ١٠٤)."],[12718,"باب أبى عبد السلام"],[12719,"٢٠٩١ - أبو عبد السلام، سأل ابن عمر كيف كان النبى -صلى الله عليه وآله وسلم- يعتم؟ قال: \"كان يديرها على رأسه ثم يغرزها خلفه ويرخى طرفها بين كتفيه\" (١) هو عندهم مجهول."],[12720,"٢٠٩٢ - أبو عبد السلام. عن ثوبان في الشاميين."],[12721,"٢٠٩٣ - أبو عبد السلام رجل من أهل الحجاز. روى عنه موسى بن عبد العزيز (٢)."],[12722,"٢٠٩١ - كنى البخارى (ص ٥٢)، الجرح (٤/ ٢/ ٤٠٦) وقال: سمعت أبى يقول: هو مجهول، المجروحين (٣/ ١٥٣)، وقال: شيخ يروى عن ابن عمر ما لا يشبه حديث الاثبات، لا يجوز الاحتجاج به، وذكر حديثه، الميزان (٤/ ٥٤٨) وقال: لا يعرف. قيل: اسمه الزبير، ديوان الضعفاء (ص ٣٦١)، اللسان (٧/ ٧٧)، كنى الحاكم (٢/ ٢٧/ ب)."],[12723,"(١) الحديث أخرجه الطبرانى في الأوسط كما في مجمع الزوائد (٥/ ١٢٠) وابن حبان في المجروحين (٣/ ١٥٣) من حديث أبى عبد السلام قال: قلت لابن عمر، كيف كان رسول اللَّه -صلى الله عليه وآله وسلم- يعتم؟ قال: كان يدور كور عمامته على رأسه ويغرزها من ورائه ويرسلها بين كتفيه وقال الهيثمى: رجاله رجال الصحيح خلا أبا عبد السلام وهو ثقة وأخرج الترمذى في الشمائل (ص ٧٤) عن ابن عمر رضي الله عنهما قال: كان النبى -صلى الله عليه وآله وسلم- إذا اعتم سدل عمامته بين كتفيه، وكان ابن عمر يفعل ذلك، وأخرج ابن أبى شيبة (٨/ ٤٢٧) عن نافع قال: كان ابن عمر يعتم ويرخيها بين كتفيه\" أهـ."],[12724,"٢٠٩٢ - كنى البخارى (ص ٥٢) وزاد \"روى عنه ابن جابر. الثقات (٥/ ٥٦٣) وقال أيضًا: روى عنه ابن جابر. كنى الحاكم (٢/ ٢٧/ أ)."],[12725,"٢٠٩٣ - كنى الحاكم (٢/ ٢٧/ ب) وقال: قاله محمد بن إسماعيل."],[12726,"(٢) موسى بن عبد العزيز العدنى، أبو شبيب القنبارى، بكسر القاف وسيكون ="],[12727,"٢٠٩٤ - أبو عبد السلام الوحاظى، شامى، عن إسحاق بن عبد اللَّه بن أبى طلحة، روى عنه بقية بن الوليد."],[12728,"= النون ثم موحدة، والقنبار: حبل الليف، صدوق سئ الحفظ، من الثامنة (ت: ١٧٥)، التقريب (٢/ ٢٨٥)."],[12729,"٢٠٩٤ - كنى الحاكم (٢/ ٢٧/ أ)، الميزان (٤/ ٥٤٨)، اللسان (٧/ ٧٧) وقالا: في مشيخة بقية العوام المجاهيل، والخبر منكر."],[12730,"باب أبى عبيد"],[12731,"٢٠٩٥ - أبو عبيد، رأى عليا. روى عنه عبادة بن نسى."],[12732,"٢٠٩٦ - أبو عبيد النحّام (١) الكنانى من أهل فلسطين. سمع أبا موسى الأشعرى. روى عنه الثورى."],[12733,"٢٠٩٧ - أبو عبيد، مولى رفاعة بن رافع. روى عن النبى عليه السلام \"ملعون من سأل بوجه اللَّه ومعلون من سئل بوجه اللَّه فمنع سائله\" (٢) حديثه عن ابن وهب، عن عبد اللَّه بن عياش، عن عبد اللَّه بن الأسود، عن أبى معقل بن أبى مسلم عنه. قال ابن أبى حاتم: سمعت أبا زرعة يقول: أبو عبيد هذا ليست له صحبة، وأبو معقل لا يسمى."],[12734,"٢٠٩٥ - المقتنى في سرد الكنى (٨٩/ أ)."],[12735,"٢٠٩٦ - الجرح (٤/ ٢/ ٤٠٥)."],[12736,"(١) النحّام بفتح، النون والحاء المشددة وبعد الألف ميم - هذه النسبة إلى النحمة وهى السلعة وقيل: النحنحة. انظر اللباب (٣/ ٣٠٠)."],[12737,"٢٠٩٧ - الجرح (٤/ ٢/ ٤٠٥) وقال: سمعت أبا زرعة يقول: أبو عبيد هذا ليست له صحبة وأبو معقل لا يسمى، المراسيل لابن أبى حاتم (ص ٢٥٢) وقال بعد أن ذكر حديثه: ليست له صحبة، جامع التحصيل (ص ٣٨٧) وذكر قول أبى زرعة فيه."],[12738,"(٢) الحديث تقدم في ترجمة أبى معقل، وتم تخريجه هناك. انظر الترجمة (١٨٧٠) والتعليق عليها."],[12739,"افراد في العبادلة"],[12740,"٢٠٩٨ - أبو عبد الغفار الازدى، سمع أنس بن مالك، روى عنه يحيى بن أيوب المصرى."],[12741,"٢٠٩٩ - أبو عبد الصمد. روى عن (أبى الدراء) (١). روى عنه حبيب بن عمر (٢)."],[12742,"٢١٠٠ - أبو عبد الجليل. روى عن عبد اللَّه بن فروخ (٣) عن عائشة قالت:"],[12743,"٢٠٩٨ - ذكره الحاكم (٢/ ٢٨/ أ) وسماه عبد الرحمن بن عيسى المصرى، وذكر روايته عن أنس بن مالك ورواية أبى العباس يحيى بن أيوب المصرى عنه، الجرح (٤/ ٢/ ٤٠٦) وقال: سمعت أبى يقول: هو مجهول. الميزان (٤/ ٥٤٨) وقال: مجهول."],[12744,"٢٠٩٩ - كنى البخارى (ص ٥٣)، كنى الحاكم (٢/ ٢٨/ أ) الثقات (٧/ ٦٦٨) الجرح (٤/ ٢/ ٤٠٦)، تعجيل المنفعة (ص ٣٢٨)، الميزان (٤/ ٥٤٨) وقال: مجهول، اللسان (٧/ ٧٧) وقال: مجهول."],[12745,"(١) هكذا في الأصل \"أبو الدرداء\" وفى مصادر الترجمة \"أم الدرداء\"."],[12746,"(٢) في الثقات وفى تعجيل المنفعة \"عمير\" وذكر ابن أبى حاتم في الجرح (١/ ٢/ ١٠٥) حبيب بن عمر الأنصارى، وقال: سمعت أبى يقول: هو ضعيف الحديث، مجهول، لم يرو عنه غير بقية. أهـ. وذكره ابن حجر في اللسان (٢/ ١٧١) وذكر روايته عن أبى عبد الصمد ورواية بقية عنه وقال: قال الدارقطنى: مجهول."],[12747,"٢١٠٠ - كنى البخارى (ص ٥٣)، الثقات (٧/ ٦٦٥)، الجرح (٤/ ٢/ ٤٠٦) وقال: سمعت أبى يقول: هو مجهول."],[12748,"(٣) عبد اللَّه بن فروخ التيمى، مولى عائشة، المدنى، نزل الشام، ثقة، من الثالثة. انظر التقريب (١/ ٤٤٠)."],[12749,"\"يؤم القوم أقرؤهم (الكتاب) (١) اللَّه\" (٢) هو مجهول."],[12750,"(١) في الأصل \"بكتاب اللَّه\" والصواب ما أثبته، وهو المثبت في مصادر الترجمة وفى أصول التخريج كما سيأتى في تخريج الحديث."],[12751,"(٢) الحديث أخرجه البخارى \"الاذان\" باب امامة العبد والمولى (٢/ ١٨٤) وقال في عنوان الباب \"وكانت عائشة يؤمها عبدها ذكوان من المصحف\" ووصله ابن أبى شيبة (٢/ ٢١٨) والشافعى في المسند (ص ٥٤)."],[12752,"ويشهد لهذا الحديث حديث أبى سعيد الخدرى رضي الله عنه قال: قال رسول اللَّه -صلى الله عليه وآله وسلم- \"إذا كانوا ثلاثة فليؤمهم أحدهم وأحقهم بالإمامة أقرؤهم\" أخرجه مسلم \"المساجد ومواضع الصلاة\" باب من أحق بالإمامة (١/ ٤٦٤)، والنسائى \"الإمامة\" باب من أحق بالإمامة (٢/ ٧٦)، وأحمد (٣/ ٤٨ و٥١ و٨٤). وحديث أبى مسعود الأنصارى أخرجه مسلم \"المساجد\" باب من أحق بالإمامة (١/ ٤٦٥)، والترمذى \"الصلاة\" باب من أحق بالإمامة (٢/ ٣٠)، وأبو داود \"الصلاة\" باب من أحق بالإمامة (١/ ١٥٩)، النسائى \"الإمامة\" باب من أحق بالإمامة؟ (٢/ ٧٦)، وابن ماجه \"إقامة الصلاة\" باب من أحق بالإمامة؟ (١/ ٣١٣) وأحمد (٤/ ١١٨ و١٢١) كلهم أخرجوه بألفاظ متقاربه ومن ألفاظه عند مسلم \"يؤم القوم أقرؤهم لكتاب اللَّه، فإن كانوا في القراءة سواء فاعلمهم بالسنة فإن كانوا في السنة سواء فأقدمهم هجرة فان كانوا في الهجرة سواء فاقدمهم سلما، ولا يؤمّن الرجل الرجل في سلطانه ولا يقعد في بيته على تكرمته إلا بإذنه\"."],[12753,"باب أبى عمر"],[12754,"٢١٠١ - أبو عمر الغدانى (١)، روى عن أبى هريرة، بصرى، روى عنه قتادة."],[12755,"٢١٠٢ - أبو عمر الصينى (٢)، روى عن أبى الدرداء، روى عنه عبد العزيز ابن رفيع."],[12756,"٢١٠١ - كنى البخارى (ص ٥٥)، الثقات (٥/ ٥٦٩)، المقتنى في سرد الكنى (١٠٢/ أ)، الجرح (٤/ ٢/ ٤٠٧)، الميزان (٤/ ٥٥٥)، التهذيب (١٢/ ١٧٦)، وقال: قال الحاكم: اسمه يحيى بن عبيد البهرانى، التقريب (٢/ ٤٥٤) وقال: مقبول، من الثالثة، ووهم من قال: اسمه يحيى بن عبيد./ د. س، اللباب (٢/ ٣٧٥)."],[12757,"(١) زاد في الميزان \"وقيل: أبو عمرو\" وكذا في التهذيب والتقريب أيضًا."],[12758,"٢١٠٢ - كنى البخارى (ص ٥٥)، تاريخ ابن معين (٢/ ٧١٧)، الجرح (٤/ ٢/ ٤٠٧) وقال: قال أبو زرعة: لا نعرفه إلا برواية حديث واحد عن أبى الدرداء عن النبى -صلى الله عليه وآله وسلم- \"سبقنا الأغنياء بالدنيا والآخرة يصلون كما نصلى ويصومون كما نصوم\" الحديث - ولا يسمى، المقتنى في سرد الكنى (١٠٢/ أ)، تهذيب الكمال (٣/ ١٦٢٩)، التهذيب (١٢/ ١٧٦)، التقريب (٢/ ٤٥٤) وقال: يقال: اسمه نشيط، وهو وهم، ووهم أيضًا من قال فيه: الضبى، بالمعجمة والموحدة مقبول، من السادسة، وروايته عن أبى الدراء مرسلة./ س وقال العلائى في جامع التحصيل (ص ٣٨٨) روى عن أبى الدراء، وقيل: هو مرسل، بل هو عن أم الدراء، عن أبى الدراء رضي الله عنه."],[12759,"قلت: وسيأتى أبو عمر المنبهى، وقيل: اسمه نشيط. انظر الترجمة (٢١٠٦)."],[12760,"(٢) الصينى: بكسر الصاد وسكون الياء المثناة من تحتها وفى آخرها نون - هذه النسبة إلى موضعين. أحدهما بلاد الصين، وهو الاقليم المشهور ="],[12761,"٢١٠٣ - أبو عمر البيروتى (١)، عن أبى الدرداء، روى عنه عبد الرحمن بن يزيد بن جابر."],[12762,"٢١٠٤ - أبو عمر الجدلى، عن أبى هريرة، روى عنه داود بن أبى هند، وقيل: أنه شيخ من ربيعة."],[12763,"٢١٠٥ - أبو عمر البزار (٢)، عن عامر الشعبى، وإبراهيم بن يزيد النخعى، ومسلم البطين، روى عنه سفيان الثورى، قال أحمد بن حنبل: قال وكيع: أبو عمر البزار ثقة (٣)."],[12764,"= بالمشرق، وهو موصوف بحسن الصور وحسن الصنعة والثانى نسبة إلى صينية وهى مدينة بين واسط والصليق بالعراق. انظر اللباب (٢/ ٢٥٥) مراصد الاطلاع (٢/ ٨٦٠)."],[12765,"٢١٠٣ - المقتنى في سرد الكنى (١٠٢/ أ)."],[12766,"(١) البيروتى: نسبة إلى بيروت، بالفتح ثم السكون، وضم الراء، وسكون الواو والتاء فوقها، نقطتان، مدينة مشهورة على بحر الشام، تعد من أعمال دمشق، بينها وبين صيدا ثلاثة فراسخ. انظر اللباب (١/ ١٩٦) مراصد الاطلاع (١/ ٢٤٠)."],[12767,"٢١٠٤ - الجرح (٤/ ٢/ ٤٠٨)، الميزان (٤/ ٥٥٥). وقال: لا يدرى من هو. اللسان (٧/ ٨٦). وقال: لا يدرى من هو. المقتنى في سرد الكنى (١٠٢/ أ)."],[12768,"٢١٠٥ - كنى البخارى (ص ٥٦)، الجرح (٤/ ٢/ ٤٠٧ - ٤٠٨)، اللسان (٧/ ٤٧٥) وقال: هو دينار بن عمر الاعمى."],[12769,"(٢) في الأصل \"البزاز\" آخره زاى. والمثبت عن مصادر الترجمة \"البزار\" آخره راء مهملة. ونص الحافظ ابن حجر في التقريب (١/ ٢٣٧) في ترجمة دينار ابن عمر أبو عمر البزار بأن آخره راء مهملة. واللَّه أعلم."],[12770,"(٣) انظر العلل ومعرفة الرجال لأحمد (١/ ١٠٧ و٢١٥) وذكره ابن أبى حاتم في الجرح (٤/ ١/ ٤٠٨) أيضًا عن عبد اللَّه بن أحمد عن أبيه به."],[12771,"٢١٠٦ - أبو عمر النخعى المنبهى (١). سمع أبا جحيفة روى عنه (٢)."],[12772,"٢١٠٧ - أبو عمر، مولى بشر بن غالبا (٣)، عن محمد بن الحنفية، روى عنه إسماعيل بن (سلمان) (٤) الازرق."],[12773,"٢١٠٦ - كنى البخارى (ص ٥٦)، كنى مسلم (ص ٦٤٧)، الجرح (٤/ ٢/ ٤٠٧)، الميزان (٤/ ٥٥٥)، وقال: أبو عمر المنبهى عن النخعى، اللسان (٧/ ٤٧٥)، تهذيب الكمال (٣/ ١٦٣٠)، التهذيب (١٢/ ١٧٦)، التقريب (٢/ ٤٥٤) وقال: أبو عمر المنبهى، النخعى، أو البجلى، الكوفى، مجهول، من الرابعة، وهو الذى اسمه نشيط، ووهم من خلطه بالصينى./ بخ. ق."],[12774,"(١) المنبهى: منبه: مدينة من مدن الشام بناها كسرى لما غلب على الشام فعربت وقيل: مَنْبِج، بالفتح ثم السكون وباء موحدة مكسورة وجيم، والنسبة إليها منْبِجى، بفتح الميم وسكون السكون كسر الباء الموحده وبعدها جيم. انظر معجم البلدان (٥/ ٢٠٥)، اللباب (٣/ ٢٥٩)، تبصير المنتبه (٤/ ١٣٩٤)."],[12775,"(٢) هكذا في الأصل \"روى عنه\" ولم يذكر شيئا بعدها وكذا هو في الجرح وفى مصادر الترجمة \"روى عنه شريك القاضى\"."],[12776,"٢١٠٧ - الجرح (٤/ ٢/ ٤٣٠) وقال: دينار بن عمر أبو عمر البزار الاسدى مولى بشر ابن غالب، كوفى، روى عن زيد بن ارقم، وابن الحنفية ومسلم البطين، روى عنه إسماعيل بن سلمان، وسفيان الثورى، . . وذكر توثيق أحمد بن حنبل له. التهذيب (٣/ ٢١٦)."],[12777,"(٣) بشر بن غالب، أسدى ذكره ابن أبى حاتم في الجرح (١/ ١/ ٣٦٣) ولم يذكر فيه شيئا."],[12778,"(٤) في الأصل \"سليمان\" والتصحيح عن الجرح (١/ ٢/ ٤٣٠) وعن التهذيب (٣/ ٢١٦) ذكراه في ترجمة دينار بن عمر أبو عمر البزار. وقال ابن أبى حاتم أيضًا في الجرح (١/ ١/ ١٧٦) إسماعيل بن سلمان الكوفى الازرق، وذكر روايته عن أبى عمر البزار، وقال ابن حجر في التهذيب (١/ ٣٠٣): إسماعيل بن سلمان بن أبى المغيرة الازرق التميمى الكوفى، روى عن أنس ="],[12779,"٢١٠٨ - أبو عمر الشامى (١) عن عبيد بن الخشخاش (٢) عن أبى ذر روى عنه المسعودى."],[12780,"٢١٠٩ - أبو عمر الدمشقى، عن كعب، روى عنه معاوية بن صالح."],[12781,"٢١١٠ - أبو عمر، روى عن عاصم الجحدرى، روى عنه هارون النحوى (٣)."],[12782,"٢١١١ - أبو عمر، مولى لبنى خزيمة، روى عن مورّق العجلى، روى عنه سلام بن مسكين."],[12783,"٢١١٢ - أبو عمر، روى عن الحسن، روى عنه إسماعيل بن عبد الملك (٤) قال أبو حاتم: هو مجهول."],[12784,"= ودينار بن عمر البزار، وقال في التقريب (١/ ٧٠) إسماعيل بن سلمان بن أبى المغيرة الازرق التميمى، الكوفى، ضعيف من الخامسة. اهـ."],[12785,"٢١٠٨ - كنى البخارى (ص ٥٦)، الجرح (٤/ ٢/ ٤٠٧)، الميزان (٤/ ٥٥٥) وقال: قال الدارقطنى: متروك، ويقال: أبو عمرو، التهذيب (١٢/ ١٧٥) التقريب (٢/ ٤٥٤) وقال: ضعيف، من السادسة. س."],[12786,"(١) في الميزان \"الدمشقى\"."],[12787,"(٢) في كنى البخارى، والتهذيب \"الحسحاس\" بالمهملات، وفى التقريب (١/ ٥٤٣)، عبيد بن الخشخاش بمعجمات، وقيل: بمهملات، لين من الثالثة."],[12788,"٢١٠٩ - كنى البخارى (ص ٥٦)، الجرح (٤/ ٢/ ٤٠٧)."],[12789,"٢١١٠ - الجرح (٤/ ٢/ ٤٠٨)."],[12790,"(٣) هارون بن موسى الازدى العتكى، مولاهم، الاعور النحوى البصرى، ثقة، مقرئ إلا أنه رمى بالقدر، من السابعة. انظر التقريب (٢/ ٣١٣)."],[12791,"٢١١١ - كنى البخارى (ص ٥٦)، الجرح (٤/ ٢/ ٤٠٨)، الثقات (٧/ ٦٦٠)."],[12792,"٢١١٢ - كنى البخارى (ص ٥٥)، الجرح (٤/ ٢/ ٤٠٨) وقال: سمعت أبى يقول: هو مجهول، الميزان (٤/ ٥٥٥). وقال: مجهول."],[12793,"(٤) إسماعيل بن عبد الملك بن أبى الصُّفَيْر، بالمهملة والفاء مصغرا، صدوق، كثير الوهم، من السادسة. التقريب (١/ ٧٢)."],[12794,"٢١١٣ - أبو عمر الدِّيلى، روى عن عبد العزيز بن أبى رواد، روى عنه ابن أبى فديك."],[12795,"٢١١٤ - وعمر الهِزَّانِى (١). سمع محمد بن على. روى عنه حجاج بن حسان (٢)."],[12796,"٢١١٥ - أبو عمر الازرق، الازدى بن المنهال (. . . .) (٣) سمع سفيان بن عيينة. روى عنه محمد بن عمرو الرازى (٤)."],[12797,"٢١١٦ - أبو عمر (الاشجعى) (٥) كوفى. عن سالم بن أبى الجعد، روى عنه عطاء بن مسلم الخفاف (٦)."],[12798,"٢١١٣ - الجرح (٤/ ٢/ ٤٠٨) وقال: سئل أبو زرعة، عنه فقال: لا أعرفه."],[12799,"٢١١٤ - الجرح (٤/ ٢/ ٤٠٨)."],[12800,"(١) الهِزَّانى: بكسر الهاء وفتح الزاى المشددة وبعد الالف نون - هذه النسبة إلى هِزَّان وهو بطن من العتيك، والعتيك من ربيعة وهو هزان بن صباح بن عتيك بن اسلم. اللباب (٣/ ٣٨٧)."],[12801,"(٢) حجاج بن حسان القيسى، البصرى، لا بأس به، من الخامسة. التقريب (١/ ١٥٢)، التهذيب (٢/ ٢٠٠)."],[12802,"٢١١٥ - المقتنى في سرد الكنى (١٠٢/ أ)."],[12803,"(٣) يوجد بياض في الأصل بمقدار كلمة."],[12804,"(٤) محمد بن عمرو بن بكر الرازى، أبو غسان زنُيَجْ، بزاى ونون وجيم، مصغرا، ثقة، من العاشرة، مات في آخر سنة (٢٤٠) أو أول التى بعدها. التقريب (٢/ ١٩٥)."],[12805,"٢١١٦ - الميزان (٤/ ٥٥٥) وقال: مجهول. المقتنى في سرد الكنى (١٠٢/ أ)."],[12806,"(٥) غير واضح في الأصل، والمثبت عن الميزان."],[12807,"(٦) عطاء بن مسلم الخفاف، كوفى، نزل حلب، صدوق يخطئ كثيرا، من الثامنة (ت: ١٩٠). انظر التقريب (٢/ ٢٢)."],[12808,"٢١١٧ - أبو عمر الصَّفَّار عن عبيد (١) اللَّه بن العيزار روى عنه المقبرى (٢)."],[12809,"٢١١٧ - كنى البخارى (ص ٥٦)، المقتنى في سرد الكنى (١٠٢/ أ)، الميزان (٤/ ٥٥٥)، اللسان (٧/ ٨٦) وقال الذهبى وتبعه ابن حجر: روى عباس عن ابن معين ضعيف."],[12810,"(١) في كنى البخارى \"عبد اللَّه\"."],[12811,"(٢) في كنى البخارى \"المُقْرئ\"."],[12812,"باب أبى عثمان"],[12813,"٢١١٨ - أبو عثمان، شهد عبد اللَّه بن عباس والحسن بن على اتتهما امرأة فقالت: إن زوجى يطلقنى ويجحدنى فقال ابن عباس: ارفعى أمره إلى معاوية فقال الحسن إلا تفتيهما قال: بماذا؟ فقال: يحلف ثلاث مرات ما طلق (١)."],[12814,"روى عنه الهذيل بن بلال الفزارى (٢)."],[12815,"٢١١٨ - المقتنى في سرد الكنى (٩٣/ أ)."],[12816,"(١) الأثر أخرجه سعيد بن منصور في السنن (١/ ٣٥٨) وابن أبى شيبة (٥/ ٧٩) عن الحسن قال: تقدمه إلى السلطان فتستحلفه ثلاثا وأخرجه أيضًا ابن أبى شيبة من طريق شيخ يكنى أبا عمرو قال: كنت جالسا عند ابن عباس فأتته امرأة فقالت: إن زوجها يطلقها في السر ويجحد في العلانية فقال: عليه أن يحلف أربع شهادات باللَّه ما طلق والخامسة أن لعنة اللَّه عليه إن كان فعل. وأخرجه أيضًا عبد الرزاق (٦/ ٤١٤ و٤١٥) من طريق قتادة عن الحسن قال: يستحلف ثم يكون الاثم عليه. قال: وقال قتادة: يستحلف بين الركن والمقام."],[12817,"(٢) هذيل بن بلال الفزارى، ذكره ابن أبى حاتم في الجرح (٤/ ٢/ ١١٣) وقال: سألت أبى عن هذيل بن بلال فقال: محله الصدق، يكتب حديثه. . سئل أبو زرعة عنه فقال: هو لين ليس بالقوى، وقال الدورى عن ابن معين كان ينزل المدائن، وليس بشئ. انظر التاريخ (٢/ ٦١٥)."],[12818,"٢١١٩ - أبو عثمان بن (سَنَّه) (١)، (٢) شامى. روى عن ابن مسعود. روى عنه الزهرى قال أبو زرعة: لا أعرف اسمه. قال أبو عمر: قد ذكره بعضهم في الصحابة وغير بعيد ان يدرك النبى عليه السلام."],[12819,"٢١٢٠ - أبو عثمان، روى عن أبيه عن معقل بن يسار عن النبى عليه السلام أنه قال: \"اقرأوا \"ياسين\" على موتاكم\" (٣)، رواه محمد بن كثير عن ابن"],[12820,"٢١١٩ - الجرح (٤/ ٢/ ٤٠٨)، وقال: سئل أبو زرعة عن اسمه فقال: لا أعرف اسمه. الميزان (٤/ ٥٤٩) وقال: ما أعرف روى عنه غير الزهرى. التهذيب (١٢/ ١٦٢)، التقريب (٢/ ٤٤٩) وقال: ما أعرف روى عنه غير الزهرى. التهذيب (١٢/ ١٦٢)، التقريب (٢/ ٤٤٩) وقال: أبو عثمان بن سَنَّة: بفتح المهملة وتشديد النون، الخزاعى الدمشقى، مقبول، من الثانية، ووهم من زعم أن له صحبة، فان حديثه مرسل./ س. فق."],[12821,"قلت: وقد تقدم أبو عثمان بن سنة في الصحابة. انظر الترجمة (٢٤٨)."],[12822,"(١) صورتها في الأصل \"سبط\" والذى في مصادر الترجمة \"سنة\" وقال في التقريب سنة بفتح المهملة وتشديد النون. فاللَّه أعلم."],[12823,"(٢) زاد في التهذيب \"الخزاعى الكعبى الدمشقى\"."],[12824,"٢١٢٠ - كنى البخارى (ص ٥٧) وذكره كما هنا. الثقات (٧/ ٦٦٤) وقال: ليس بالنهدى. الجرح (٤/ ٢/ ٤٠٨) وذكر الحديث. الميزان (٤/ ٥٥٠) وقال: يقال: اسمه سعد، عن أبيه. . الخ وقال: لا يعرف أبوه ولا هو ولا روى عنه سوى سليمان التيمى، التهذيب (١٢/ ١٦٣) وقال: قيل: اسمه سعد روى عن معقل بن يسار وأنس بن مالك بن جندل، وقيل: عن أبيه عن معقل. . روى عنه سليمان التيمى."],[12825,"قال ابن المدينى: لم يرو عنه غيره وهو مجهول، وقال في التقريب (٢/ ٤٤٩) مقبول، من الرابعة./ د. س. ق."],[12826,"(٣) الحديث أخرجه أبو داود \"الجنائز\" باب القراءة عند الميت (٣/ ١٩١) وابن ماجه \"كتاب الجنائز\" باب ما يقال عند المريض إذا حضر (١/ ٤٦٥)، وأحمد في المسند (٥/ ٢٦/ ٢٧) وابن حبان. كما في موارد الظمآن (ص ="],[12827,"المبارك عن سليمان التيمى عنه وليس بالنهدى (١)."],[12828,"٢١٢١ - أبو عثمان العدوى. روى عن أبى جهم (٢) عن سالم (٣) عن أبيه عن النبى عليه السلام قال: \"لا ينظر اللَّه إلى الاشمط الزانى\" (٤). قال أبو زرعة: لا أعرفه إلا بهذا الحديث."],[12829,"= ١٨٤)، والطيالسى في المسند (٢/ ٢٣)، والبيهقى في السنن (٣/ ٣٨٣)، والنسائى في عمل اليوم والليلة (١٠٧٤) و(١٠٧٥)، والحاكم في المستدرك (١/ ٥٦٥) كلهم أخرجوه من طريق ابن المبارك عن سليمان التيمى، عن أبى عثمان، وليس بالنهدى، عن أبيه، عن معقل بن يسار به، إلا أنه عند ابن حبان \"عن يحيى القطان، حدثنا سليمان التيمى به. وفى مسند الطيالسى، عمل اليوم والليلة، عن ابن المبارك عن سليمان التيمى عن رجل عن أبيه به."],[12830,"وقال الحاكم: أوقفه يحيى بن سعيد وغيره عن سليمان التيمى، والقول فيه قول ابن المبارك، اذ الزيادة من الثقة مقبولة، ووافقه الذهبى. والحديث ذكره السيوطى في الدر المنثور (٥/ ٢٥٦) وزاد نسبته إلى محمد بن نصر المروزى، والطبرانى، ونسبه الشيخ الألبانى في ارواء الغليل (٣/ ١٥٠)، إلى ابن أبى شيبة، والى الضياء المقدسى في عواليه. وذكره السيوطى في الجامع الصغير (١/ ٥٢) ورمز لى سنة. وقال النووى في الاذكار (ص ١٣٢): إسناده ضعيف، فيه مجهولان لكن لم يضعفه أبو داود، وقال الحافظ ابن حجر في تلخيص الحبير (٢/ ١٠٤): اعله ابن القطان بالاضطراب، وبالوقف وبجهالة حال أبى عثمان، وأبيه ونقل أبو بكر بن العربى عن الدارقطنى. أنه قال: هذا حديث ضعيف الإسناد، مجهول المتن، ولا يصح في الباب حديث. اهـ."],[12831,"(١) النهدى، هو أبو عثمان النهدى المتقدم في (٢٦٠)."],[12832,"٢١٢١ - الجرح (٤/ ٢/ ٤٠٨) وقال: سألت أبا زرعة عنه فقال: لا أعرفه إلا في هذا الحديث."],[12833,"(٢) هو ابن صخير انظر (١٤٥٢)."],[12834,"(٣) هو ابن عبد اللَّه بن عمر."],[12835,"(٤) الحديث رواه الطبرانى من حديث ابن عمر قال: قال رسول اللَّه -صلى الله عليه وآله وسلم- \"لا ="],[12836,"٢١٢٢ - أبو عثمان. سمع أبا هريرة قال: أوصانى خليلى (١) أن أوتر بسبع (٢) روى عنه معاوية بن صالح."],[12837,"٢١٢٣ - أبو عثمان الترمسى دمشقى."],[12838,"= ينظر اللَّه إلى الأشمط الزانى ولا العائل المزهو\". كما في مجمع الزوائد (٦/ ٢٥٥) وقال الهيثمى: فيه ابن لهيعة وحديثه حسن وفيه ضعف، وبقية رجاله ثقات. اهـ."],[12839,"والحديث أخرجه أيضًا ابن أبى حاتم في الجرح (٤/ ٢/ ٤٠٨)."],[12840,"٢١٢٢ - كنى البخارى (ص ٥٧)، الثقات (٥/ ٥٦٨)، الجرح (٤/ ٢/ ٤٠٩)."],[12841,"(١) قال الحافظ ابن حجر في الفتح (٣/ ٥٧): الخليل: الصديق الخالص الذى تخللت محبته القلب فصارت في خلاله، أى في باطنه."],[12842,"(٢) الحديث أخرجه البخارى في الكنى (ص ٥٧) وابن حبان في الثقات (٥/ ٥٦٧) وابن أبى حاتم في الجرح (٤/ ٢/ ٤٠٩) وفيه عندهم لفظ \"أوصانى خليلى أن اوتر بسبع سور أقرا في ثلاث الوتر منهن\" ﴿قُلْ هُوَ اللَّهُ أَحَدٌ﴾ والمعوذتين."],[12843,"والحديث أخرجه أيضًا البخارى \"التهجد\" باب صلاة الضحى في الحضر (٣/ ٥٦) وفى \"الصوم\" باب صيام البيض (٤/ ٢٢٦) ومسلم \"صلاة المسافرين\" باب استحباب صلاة الضحى (١/ ٤٩٩)، والنسائى \"الصيام\" باب ذكر الاختلاف على أبى عثمان في حديث أبى هريرة في صيام ثلاثة أيام (٤/ ٢١٨) ومحمد بن نصر المروزى في كتاب الوتر - باب اختيار الوتر أول الليل (ص ٢٠١) وأبو داود \"الصلاة\" باب الوتر قبل النوم (٢/ ٦٥)، وأحمد في المسند (٢/ ٢٢٩، ٢٣٣، ٢٥٤، ٢٦٠، ٢٦٥، ٢٧١، ٣١١، ٣٢٩، ٣٤٧، ٣٧٧، ٤٠٢، ٤٥٩، ٤٧٢، ٤٨٤، ٤٨٩، ٤٩٧، ٤٩٩، ٥٠٥، ٥٢٦)، واسحاق بن راهوية. وأبو يعلى في المسند كما في فتح البارى (٢/ ٤٨٦) كلهم أخرجوه بنحوه من حديث أبى هريرة رضي الله عنه."],[12844,"٢١٢٣ - لم أقف له على ترجمة عند غير المؤلف."],[12845,"٢١٢٤ - أبو عثمان الجهنى المدنى. سمع ربيعة بن أبى عبد الرحمن (١). روى عنه مطرف بن مازن الصنعانى (٢)."],[12846,"٢١٢٥ - أبو عثمان الجيشانى مصرى. عن عقبة بن عامر. روى عنه جعفر القتبانى."],[12847,"٢١٢٦ - أبو عثمان من ولد أبى العاص قال: غزا محمد بن أبى حذيفة بن عتبة. روى عنه محمد بن وهب بن هشام."],[12848,"٢١٢٧ - أبو عثمان بن جبيريت مطعم. روى عن أبيه. روى عنه كلاب بن على (٣)."],[12849,"٢١٢٤ - المقتنى في سرد الكنى (٩٣/ أ)."],[12850,"(١) ربيعة بن أبى عبد الرحمن هو ربيعة الرأى، واسم أبيه فروخ، ثقة فقيه مشهور، قال ابن سعد: كانوا يتقونه لموضع انرأى، من الخامسة. التقريب (١/ ٢٤٧)."],[12851,"(٢) مطرّف بن مازن الصنعانى، ولى القضاء بصنعاء، وتوفى بالرّقَّة، ويقال: مات بمنبج، قال ابن أبى حاتم: قرئ على العباس الدورى قال: سئل يحيى بن معين عن مطرف بن مازن فقال: كذاب. انظر الجرح (٤/ ١/ ٣١٤)، تاريخ ابن معين (٢/ ٥٧٠)."],[12852,"٢١٢٥ - المقتنى في سرد الكنى (٩٢/ أ)."],[12853,"٢١٢٦ - لم أقف له على ترجمة عند غير المؤلف."],[12854,"٢١٢٧ - المقتنى في سرد الكنى (٩٣/ أ)."],[12855,"(٣) كلاب بن على الجعفرى العامرى، مجهول، من السادسة. تمييز التقريب (٢/ ١٣٧)، التهذيب (٨/ ٤٥٢)."],[12856,"باب أبى على"],[12857,"٢١٢٨ - أبو على الكاهلى (١)، سمع أبا موسى الاشعرى، سمع منه عبد الملك بن أبى سليمان."],[12858,"٢١٢٩ - أبو على (٢) الصيقل (٣) روى عن جعفر بن تمام (٤). روى عنه منصور والثورى."],[12859,"٢١٢٨ - كنى البخارى (ص ٥٢)، (ص ٥٨)، الثقات، (٥/ ٥٦٢)، الجرح (٤/ ٢/ ٤٠٩) المقتنى دى سرد الكنى (٩٩/ ب)، تعجيل المنفعة (ص ٣٣٢) وقال: ذكره الحاكم أبو أحمد فيمن لما يسم."],[12860,"(١) الكاهلى: بفتح أوله وسكون الألف كسر الهاء واللام - نسبة إلى كاهل بن الحارث بن تميم بن سعد هذيل بن مدركة بن الياس بن مضر. اللباب (٣/ ٧٩)."],[12861,"٢١٢٩ - كنى البخارى (ص ٥٢)، الجرح (٤/ ٢/ ٤٠٩)، الميزان (٤/ ٥٥٤) وقال: قال أبو على بن السكن وغيره: مجهول، اللسان (٧/ ٨٣) وقال: مثل قول الذهبى. تعجيل المنفعة (ص ٣٣٢)."],[12862,"(٢) زاد في تعجيل المنفعة \"الرداد\"."],[12863,"(٣) زاد في الميزان واللسان \"مولى بنى أسد\"."],[12864,"(٤) ذكره ابن أبى حاتم في الجرح (١/ ١/ ٤٧٥) فقال: جعفر بن تمام بن العباس بن عبد المطلب روى عن أبيه روى عنه أبو حازم المدينى، وابن أبى ذئب، وأبو على الصيقل سمعت أبى يقول ذلك. ثم قال ابن أبى حاتم: سئل أبو زرعة عن جعفر بن تمام بن العباس بن عبد المطلب فقال: مدينى ثقة، أهـ."],[12865,"٢١٣٠ - أبو على بن يزيد بن مُشْكان (١). الايلى -أخو يونس بن يزيد الايلى- مولى معاوية بن أبى سفيان روى عن ابن شهاب الزهرى. روى عنه أخوه يونس بن يزيد."],[12866,"٢١٣١ - أبو على الخزاز. عن عبد الرحمن بن أبى ليلى يعد في الكوفيين."],[12867,"٢١٣٢ - أبو على الليثى من بنى ليث بن بكر بن عبد مناة المدنى حكى موت الصَّعْب بن جَثَّامَة (٢) روى عنه محمد بن إسماعيل البخارى."],[12868,"٣١٣٠ - كنى البخارى (ص ٥٢)، الثقات (٧/ ٦٥٨)، الجرح (٤/ ٢/ ٤٠٩)، الميزان (٤/ ٥٥٤) وقال: هو مجهول، تهذيب الكمال (٣/ ١٦٢٨ - ١٦٢٩) المقتنى في سرد الكنى (٩٩/ ب)، التهذيب (١٢/ ١٧٤)، التقريب (٢/ ٤٥٢) وقال: مجهول، من السابعة./ د. ت."],[12869,"(١) مُشْكَان: بالشين المعجمة وضم الميم. الاكمال (٧/ ٢٥٦)."],[12870,"٢١٣١ - المقتنى في سرد الكنى (٩٩/ ب) وقال: أبو على الهمدانى من عبد الرحمن ابن أبى ليلى. كوفى."],[12871,"٢١٣٢ - المقتنى في سرد الكنى (٩٩/ ب)."],[12872,"(٢) الصعب، بفتح أوله وسكون المهملة، ابن جثامة، بفتح الجيم وتشديد المثلثة، الليثى، صحابى، مات في خلافة الصديق، والأصح أنه عاش إلى خلافة عثمان. انظر التقريب (١/ ٣٦٧)."],[12873,"باب أبى عمرو"],[12874,"٢١٣٣ - أبو عمرو بن عاصم بن عدى الأنصارى المدنى الاوسى العجلانى يعرف بأبى البدّاح بن عاصم بن عدى. روى عن أبيه (١). روى عنه أبو بكر بن محمد بن عمرو بن حزم وابنه عاصم بن أبى البداح."],[12875,"٢١٣٤ - أبو عمرو. سمع عثمان. روى عنه ابنه."],[12876,"٢١٣٥ - أبو عمرو بن حِمَاس (٢) بن عمرو الليثى. من أنفسهم مدنى كان عندهم من العبَاد. سمع مالك بن أوس بن الحَدَثَان النّصرى (٣) وحمزة بن"],[12877,"٢١٣٣ - المقتنى في سرد الكنى (١٠٥/ أ) وقال: أبو عمرو بن عاصم بن عدى العجلانى، ويعرف بأبى البداح."],[12878,"قلت: وقد تقدم أبو البداح بن عاصم. في الصحابة وقال ابن عبد البر في ترجمته هناك قيل: أبو البداح لقب وكنيته أبو عمرو. انظر الترجمة (٤٢)."],[12879,"(١) عاصم بن عدى بن الجد بن العجلان بن حارثة البلوى، يروى عنه ابنه وسهل ابن سعد والشعبى، حليف بنى عمرو بن عوف أخو معن، بدرى أُحُدِى، وكان سيد بنى العجلان، وهو والد أبى البداح. انظر التجريد (١/ ٢٨٢)."],[12880,"٢١٣٤ - لم أقف له على ترجمة عند غير المؤلف."],[12881,"٢١٣٥ - كنى البخارى (ص ٥٥) الطبقات الكبرى (٥/ ٦٢)، المقتنى في سرد الكنى (١٠٥/ أ)، الجرح (٤/ ٢/ ٤١٠)، الميزان (٤/ ٥٥٧) وقال: مجهول، التهذيب (٢/ ١٧٨)، التقريب (٢/ ٤٥٤) وقال: مقبول، من السادسة. (ت: ١٣٩)./ د."],[12882,"(٢) حماس: قال ابن ماكولا في الاكمال (٢/ ٤٩٩) حماس: بالسين المهملة فهو حماس بن عمرو الليثى، عن عمر بن الخطاب رضي الله عنه روى عنه ابنه أبو عمر. اهـ. وفى تبصير المنتبه (١/ ٤٥٢) حِمَاس، بالكسر وتخفيف الميم. اهـ."],[12883,"(٣) مالك بن أوس بن الحَدَثَان، بفتح المهملة والمثلثة النصرى بالنون أبو سعيد ="],[12884,"عبد اللَّه بن عمر بن الخطاب (١). روى عنه محمد بن عمرو بن علقمة بن وقاص وابنه شداد بن أبى عمرو (٢)، ويحيى بن سعيد."],[12885,"٢١٣٦ - أبو عمرو العبدى (٣). ويقال: العنزى كان له علم. روى عنه عبد اللَّه بن أبى الهذيل العمرى قوله."],[12886,"٢١٣٧ - أبو عمرو السَّيْبَانى (٤). والد يحيى بن أبى عمرو، شامى سمع عمر بن الخطاب، وعقبة بن عامر الجهنى، روى عنه ابنه يحيى."],[12887,"= المدنى، له رؤية، وروى عن عمر، (ت: ٩٢) وقيل (ت: ٩١) التقريب (٢/ ٢٢٣)."],[12888,"(١) عبد اللَّه هو شقيق سالم، ثقة، من الثالثة. التقريب (١/ ١٩٩)."],[12889,"(٢) شداد أبى عمرو حِمَاس، بكسر المهملة، الليثى المدنى، مجهول من السادسة. التقريب (١/ ٣٤٧)."],[12890,"٢١٣٦ - كنى البخارى (ص ٥٤)، الجرح (٤/ ٢/ ٤٠٩)."],[12891,"(٣) زاد في كنى البخارى \"السروى\"."],[12892,"٢١٣٧ - كنى البخارى (ص ٥٤)، الجرح (٤/ ٢/ ٤٠٩)، الاكمال (٥/ ١١١) المقتنى في سرد الكنى (١٠٥/ أ)، الثقات (٥/ ٥٨١) وقال أبو عمرو السيبانى، من أهل الرملة يروى عن عمر بن الخطاب، روى عنه ابنه يحيى ابن أبى عمرو، وأبو عمرو السيبانى من أهل الكوفة. اهـ. الميزان (٤/ ٥٥٨) وقال: أبو عمرو السيبانى بمهملة، الفلسطينى، اسمه زرعة له من عقبة بن عامر وأبى هريرة وعنه ابنه يحيى بن أبى عمرو السيبانى وجماعة وهو مقل يقال: لحق عمر، وثقة يعقوب الفسوى. اهـ."],[12893,"اللسان (٧/ ٤٧٦)، التهذيب (١٢/ ١٨٢) وقال أبو عمرو السيبانى الشامى الفلسطينى اسمه زرعة وهو عم الأوزاعى. التقريب (٢/ ٤٥٥) وقال: مقبول، من الثانى./ بخ."],[12894,"(٤) السَّيبانى: بالمهملة والموحدة بينهما تحتانية ساكنة، اللسان (٧/ ٤٧٦) وقال في الاكمال (٥/ ١١١): السَّيبانى، بسين مهملة. وانظر تبصير المنتبه (٢/ ٨٢٠) وسيبان بطن من حمير كما سبق وأن عرفت."],[12895,"٢١٣٨ - أبو عمرو (١) بن حريث."],[12896,"٢١٣٨ - تاريخ ابن معين (٢/ ٧١٨)، تهذيب الكمال (٣/ ١٦٣٢)، المقتنى في سرد الكنى (١٠٥/ أ)، الميزان (٤/ ٥٥٦)، اللسان (٧/ ٤٧٦) وقال: مجهول، التهذيب (١٢/ ٦٧١)، التقريب (٢/ ٤٥٥) وقال: مجهول، من السادسة، / د. ق."],[12897,"(١) في تهذيب الكمال والتهذيب، والميزان، واللسان \"أبو عمرو بن محمد بن حريث\" وفى تهذيب الكمال، والتهذيب واللسان، وقيل: \"أبو محمد بن عمرو بن حريث، جد لاسماعيل بن أمية لأمه\". وقد ذكره ابن حبان في أبى محمد فقال: أبو محمد بن عمرو بن حريث. . الخ."],[12898,"قلت: وقد اختلف عليه في حديثه وهو حديث الخط، فقد أخرج البخارى في التاريخ الكبير (١/ ٢/ ٧١) عن أبى هريرة، وابن ماجه \"الإقامة\" باب ما يستر المصلى (١/ ٣٠٣) من طريق حميد الأسود وسفيان بن عيينه كلاهما عن إسماعيل بن أمية عن أبى عمرو بن محمد بن عمرو بن حريث عن جده حريث بن سليم، عن أبى هريرة عن النبى -صلى الله عليه وآله وسلم- قال: \"إذا صلى أحدكم فليجعل تلقاء وجهه شيئا فإن لم يجد فلينصب عصا فإن لم يجد فليخط خطا، ثم لا يضره ما بين يديه. وأخرجه أحمد في المسند (٢/ ٢٤٩) من طريق سفيان عن إسماعيل بن أميه عن أبى محمد بن عمرو بن حريث قال مرة: عن أبى عمرو بن محمد بن حريث عن جده، عن أبى هريرة به. وفى المسند (٢/ ٢٥٥) أيضًا من طريق معمر والثورى عن إسماعيل بن أمية عن عمرو بن حريث عن أبيه عن أبى هريرة به. وأيضًا في المسند (٢/ ٢٦٦) من طريق معمر والثورى عن إسماعيل بن أمية عن أبى عمرو بن حريث عن أبيه، عن أبى هريرة به. والاضطراب ظاهر في هذا الحديث كما هو ملاحظ، وقيل: الاضطراب فيه من إسماعيل بن أمية، وقال البخارى في التاريخ الكبير (١/ ٢/ ٧٢) قال سفيان: جاءنا بصرى عتبة أبو معاذ قال: لقيت هذا الشيخ الذى روى عنه إسماعيل فسألته فخلط على."],[12899,"قال الحافظ في التهذيب (٢/ ٢٣٦) فهذا يدل على أن أبا عمرو بن = العذرى (١). روى عن جده (٢)، عن أبى هريرة روى عنه إسماعيل بن أمية وعبيد النصرى."],[12900,"٢١٣٩ - أبو عمرو العدوى. وقيل: العبدى الاجدع كوفى، كان من أصحاب على رضي الله عنه. وروى (عن) (٣) على في \"الجدّاب\" (٤). روى عنه ليث بن أبى سليم."],[12901,"= محمد بن حريث كان منه الاضطراب أيضًا."],[12902,"قلت: والحديث ضعفه غير واحد من أئمة هذا الشأن، قال أحمد بن حنبل: ضعيف، وقال الدارقطنى: لا يصح ولا يثبت، وقال الطحاوى: أبو عمرو وجده مجهولان. أيهما ذكر في غير حديث الخط. انظر التهذيب (١٢/ ١٨١)."],[12903,"(١) العذرى: بضم العين وسكون الذال وفى آخرها راء - نسبة إلى عذرة قبيلة من قضاعة. اللباب (٢/ ٣٣١)."],[12904,"(٢) جده: هو حريث، نسب أبو عمرو إليه، وفى التقريب (١/ ١٥٩) حريث رجل من بنى عذرة، اختلف في اسه أبيه فقيل: ابن سليم، أو سليمان أو عمار، مختلف في صحبته، وعندى أن راوى حديث الخط، غير الصحابى، بل هو مجهود، من الثالثة. اهـ."],[12905,"٢١٣٩ - كنى البخارى (ص ٥٤)، الجرح (٤/ ٢/ ٤٠٩ - ٤١٠)، المقتنى في سرد الكنى (١٠٥/ أ)."],[12906,"(٣) في الأصل \"عنه\" بزيادة الهاء في آخره. والمثبت، عن مصادر الترجمة وعن أصول التخريج كما سيأتى. وهو الصواب."],[12907,"(٤) الحديث أخرجه البخارى في الكنى (ص ٥٤)، والبيهقى (٦/ ٢٤٦) من طريق حفص بن غياث عن ليث عن أبى عمرو العبدى، عن على رضي الله عنه قال: \"الديّة لمن احرز الميراث، والجد أب\". وأخرجه أيضًا عبد الرزاق (١٠/ ٢٦٤) من حديث على رضي الله عنه به."],[12908,"ويشهد لهذا الحديث حديث علقه البخارى \"الفرائض\" باب ميراث الجد مع الأب والاخوة. قال: وقال أبو بكر وابن عباس، وابن الزبير: الجد أب = . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . ."],[12909,"= (١٢/ ١٨) وقول أبى بكر هذا وصله الدارمى في السنة (٢/ ٣٥٢) بسنده المتصل إلى أبى سعيد الخدرى، وصت عكرمة أن أبا بكر جعل الجد أبا. قال الحافظ ابن حجر في الفتح (١٢/ ١٩) سنده على شرط مسلم، ووصله أيضًا سعيد بن منصور في السنن (١/ ٢١) من هذا الطريق به."],[12910,"وأخرج الدارمى (٢/ ٣٥٢) بسنده إلى أبى موسى الاشعرى أن أبا بكر الصديق جعل الجد أبا، وصحح الحافظ ابن حجر إسناده. انظر الفتح (١٢/ ١٩)."],[12911,"وعند الدارمى أيضًا (٢/ ٣٥٣) عن ابن عباس أن أبا بكر كان يجعل الجد أبا. وصححه الحافظ أيضًا. كما في الفتح (١٢/ ١٩) وعند الدارمى أيضًا (٢/ ٣٥٣) عن ابن الزبير أن أبا بكر جعل الجد أبا. وقد اسند البخارى أيضًا \"الفرائض\" (١٢/ ١٩) عن ابن عباس أن أبا بكر أنزل الجد أبا."],[12912,"وأخرج قول ابن عباس أيضًا محمد بن نصر المروزى في كتاب الفرائض من طريق عمرو بن دينار عن عطاء عن ابن عباس قال: الجد أب. انظر الفتح (١٢/ ١٩) وأخرجه أيضًا عبد الرزاق (١٠/ ٢٦٤) من هذا الوجه وأخرجه أيضًا الدارمى (٢/ ٣٥٦) بسنده المتصل إلى ابن طاووس عن أبيه عن ابن عباس أنه جعل الجد أبا، وقال الحافظ في الفتح (١٢/ ١٩) سنده صحيح."],[12913,"وأما قول ابن الزبير فأخرجه البخارى \"الفضائل\" باب لو كنت متخذا خليلا (٧/ ١٧) أخرجه موصولا من طريق عبد اللَّه بن أبى مليكه قال: كتب أهل الكوفة إلى ابن الزبير في الجد فقال: أما الذى قال رسول اللَّه -صلى الله عليه وآله وسلم- \"لو كنت متخذا من هذه الأمة خليلا لا تخذته أنزله أبا -يعنى أبا بكر- قال الحافظ في الفتح (١٢/ ١٩) وفيه دلالة على أنه أفتاهم بمثل قوق أبى بكر. أهـ."],[12914,"قلت: ومعنى قوله الجد أب: قال الحافظ ابن حجر في الفتح (١٢/ ١٩): أنه ينزل منزلة الأب في الحرمة ووجوه البر. اهـ. ويراد به هنا أيضًا أنه يرث ما يرثه الأب عند عدم وجود الأب حيا. واللَّه أعلم."],[12915,"٢١٤٠ - أبو عمرو، مولى المطلب بن حنطب (١) رأى ابن عمر (٢). روى عنه محمد بن اسحاق."],[12916,"٢١٤١ - أبو عمرو، مولى أنس بن مالك بصرى، روى عنه الربيع بن سليمان (٣)."],[12917,"٢١٤٢ - أبو عمرو الازدى، شامى. روى عن بشير مولى معاوية روى عنه معاوية بن صالح."],[12918,"٢١٤٣ - أبو عمرو الموصلى، عن فراس، روى عنه معن بن عيسى."],[12919,"٢١٤٤ - أبو عمرو الرازى (٤). روى عن ابن عجلان وزيد بن أسلم. هو"],[12920,"٢١٤٠ - كنى البخارى (ص ٥٤)، الجرح (٤/ ٢/ ٤١٠)، الثقات (٥/ ٥٦٨)، المقتنى في سرد الكنى (١٠٥/ أ)، وقال الدولابى في الكنى (٢/ ٤٣/ ٤٥) أبو عمرو مولى المطلب واسمه ميسرة."],[12921,"(١) المطّلب، بن حنطب بن الحارث المخزومى أبو عبد اللَّه، ذكره ابن اسحاق فيمن أُسر يوم بدر ثم أسلم. روى عنه ابنه عبد اللَّه. الإصابة (٣/ ٤٢٥)، التجريد (٢/ ٧٩)."],[12922,"(٢) في الثقات والجرح (رأى عمر)."],[12923,"٢١٤١ - كنى البخارى (ص ٥٥)، الجرح (٤/ ٢/ ٤١٠)."],[12924,"(٣) في كنى البخارى والجرح \"سليم\"."],[12925,"٢١٤٢ - كنى البخارى (ص ٥٥)، الجرح (٤/ ٢/ ٤١٠)، المقتنى في سرد الكنى (١٠٥/ أ)."],[12926,"٢١٤٣ - كنى البخارى (ص ٥٥)، الجرح (٤/ ٢/ ٤١٠)، المقتنى في سرد الكنى (١٠٥/ أ)."],[12927,"٢١٤٤ - كنى البخارى (ص ٥٥)، المقتنى في سرد الكنى (١٠٥/ أ)، الجرح (٤/ ٢/ ٤١٠) وقال: سمعت أبى يقول: هو مجهول، ديوان الضعفاء (ص ٣٦٢) وقال: مجهول، الميزان (٤/ ٥٥٦). وقال: مجهول اللسان (٧/ ٨٧) وقال: مجهول."],[12928,"(٤) في الجرح، والميزان، وديوان الضعفاء \"الدارى\" بالدال المهملة والراء."],[12929,"عندهم مجهول."],[12930,"٢١٤٥ - أبو عمرو الجَمَلى (١) مجهول. روى عن زاذان، روى عنه صدقة (ابن) (٢) سهل."],[12931,"٢١٤٦ - أبو عمرو (٣) مولى بنى أمية. سمع محمد بن أبى سفيان (٤)، روى عنه ابن المبارك."],[12932,"٢١٤٧ - أبو عمرو، صاحب القمص. قال يحيى بن معين: أبو عمرو صاحب القمص ثقة، ذكره اسحاق بن منصور عن ابن معين (٥)."],[12933,"٢١٤٨ - أبو عمرو، روى عن قيس بن سعد المكى، روى عنه معتمر بن سليمان."],[12934,"٢١٤٥ - كنى البخارى (ص ٥٥)، المقتنى في سرد الكنى (١٠٥/ أ) الجرح (٤/ ٢/ ٤١٠) وقال: سمعت أبى يقول: هو مجهول. ديوان الضعفاء (ص ٣٦٢) وقال: مجهول، الميزان (٤/ ٥٥٦) وقال: مجهول. اللسان (٧/ ٨٧) وقال: مجهول."],[12935,"(١) الجَمَلى: بفتح الجيم والميم وبعدها اللام -هذه النسبة- إلى جمل بن كنانة بن ناجية بن مراد وهو بطن من مراد. اللباب (١/ ٢٩٢)."],[12936,"(٢) هكذا في الأصل \"بن\" وفى كنى البخارى والجرح والمقتنى \"أبو\" وفى الجرح (٢/ ١/ ٤٣١) قال ابن أبى حاتم عن أبيه: صدقة أبو سهل الهنائى، روى عن محمد بن سيرين وأبى عمرو الجملى وشيخ كبير من بنى شيبة. وذكر أن ابن معين وثقه."],[12937,"٢١٤٦ - الجرح (٢/ ١/ ٤١٠)، الثقات (٧/ ٦٥٩)، كنى البخارى (ص ٥٦)."],[12938,"(٣) الذى في مطبوعة كنى البخارى \"أبو عمر مولى بنى أمية\"."],[12939,"(٤) محمد بن أبى سفيان بن حرب، الأموى، أخو معاوية، مقبول، من الثالثة، وقيل: الصواب، عنبسة بن أبى سفيان./ س. التقريب (٢/ ١٦٥)."],[12940,"٢١٤٧ - الجرح (٤/ ٢/ ٤١١)."],[12941,"(٥) انظر الجرح (٤/ ٢/ ٤١١)."],[12942,"٢١٤٨ - الجرح (٢/ ٢/ ٤١١) وقال: سئل أبو زرعة عنه فقال: لا أعرفه."],[12943,"٢١٤٩ - أبو عمرو. روى عن أنس بن مالك عن النبى عليه السلام أنه قال: \"يخرج من النار قوم يسمون الجهنَّميُّون\" (١)."],[12944,"٢١٤٩ - الجرح (٤/ ٢/ ٤١١)."],[12945,"(١) الحديث أخرجه ابن أبى حاتم في الجرح (٤/ ٢/ ٤١١)، والطبرانى في الأوسط من حديث أنس رضي الله عنه قال: قال رسول اللَّه -صلى الله عليه وآله وسلم- \"إن أناسا من أهل لا إله إلا اللَّه يدخلون النار بذنوبهم فيقول لهم أهل اللات والعزى ما أغنى عنكم قولكم لا اله إلا اللَّه وأنتم معنا في النار، فيغضب اللَّه لهم فيخرجهم فيقذف بهما في نهر الحياة فيبرؤون من حرقهم، كما بيرأ القمر من كسوفه فيدخلون الجنة فيسميهم أهل الجنة الجهنميين، فقال رجل: يا أنس سمعت هذا من رسول اللَّه -صلى الله عليه وآله وسلم- فقال أنس: سمعت رسول اللَّه -صلى الله عليه وآله وسلم- يقول: \"من كذب على متعمدا فليتبوأ مقعده من النار\"، أنا سمعت رسول اللَّه -صلى الله عليه وآله وسلم- يقول هذا. انظر مجمع الزوائد (١٠/ ٣٧٩) وقال الهيثمى: فيه من لم أعرفهم."],[12946,"وحديث أنس أخرجه أيضًا البخارى \"الرقاق\" باب صفة جهنم (١١/ ٤١٦) وفى \"التوحيد\" باب ما جاء في قوله اللَّه تعالى ﴿إِنَّ رَحْمَتَ اللَّهِ قَرِيبٌ مِنَ الْمُحْسِنِينَ﴾ [الأعراف: ٥٦] (٣/ ٣٤٣) من طريق قتادة عنه مرفوعًا بلفظ \"يخرج قوم من النار بعد ما مسهم منها سَفْع فيدخلون الجنة فيسميهم أهل الجنة الجهنميين\". والسَّفْع بفتح المهملة وسكون الفاء ثم عين مهملة، أى سواد فيه زرقة، أو صفرة، يقال: سفعته النار إذا لفحته فغيرت لون بشرته. انظر فتح البارى (١١/ ٤٢٩). وأخرجه أيضًا ابن خزيمة في كتاب التوحيد ص (٢٨١) عن أنس به ويشهد لحديث أنس هذا حديث عمران بن حصين رضي الله عنهما أخرجه البخارى \"الرقاق\" باب صفة جهنم (١١/ ٤١٨) مرفوعا به. وحديث جابر رضي الله عنه أخرجه مسلم \"الإيمان\" باب أدنى أهل الجنة منزلة فيها (١/ ١٧٩) بنحو حديث أنس رضي الله عنه."],[12947,"وحديث المغيرة أخرجه الطبرانى في الأوسط مرفوعا بلفظ قال: \"يخرج = روى عنه زيد بن أبى أنيسة (١)."],[12948,"٢١٥٠ - أبو عمرو بن العلاء بن عمار بن العريان بن خزاعى بن مازن بن مالك بن عمرو بن تميم التميمى (المازنى) (٢) صاحب القراءة والغريب. قيل: اسمه كنيته. وقيل: اسمه زبّان وقد ذكرناه فيمن وقف على اسمه ممن عرف بكنيته."],[12949,"٢١٥١ - أبو عمرو، أو أبو عمر مولى بشر بن غالب. روى عن محمد بن (الحنفية) (٣). روى عنه إسماعيل بن (سليمان) (٤) الازرق."],[12950,"= قوم من النار فيسمون في الجنة الجهنميين فيدعون اللَّه أن يحول عنهم ذلك الاسم فيمحوه اللَّه عنهما فإذا خرجوا من النار نبتوا كما ينبت الريش. انظر مجمع الزوائد (١٠/ ٣٧٩) وقال الهيثمى: فيه عبد الرحمن بن اسحاق وهو ضعيف."],[12951,"(١) زيد بن أبى أنيسة، كوفى، سكن الرها، ثقة له افراد، من السادسة (ت: ١١٩) وقيل: (١٢٤). التقريب (١/ ٢٧٢)."],[12952,"٢١٥٠ - تقدم. انظر الترجمة (٩٣٩) والتعليق عليها وترجمته هناك مطولة أكثر منها هنا."],[12953,"(٢) الحق في هامش الأصل. وكتب عنده كلمة \"صح\"."],[12954,"٢١٥١ - تقدم في أبى عمر انظر الترجمة (٢١٠٧) والتعليق عليها."],[12955,"(٣) في الأصل \"الحبيب\" وفى ترجمة أبى عمر في (٢١٠٧) \"الحنفية\"، وهو محمد بن الحنفية كما أثبته واللَّه أعلم."],[12956,"(٤) هكذا في الأصل \"سليمان\" ولعل الصواب سلمان كما سبق وإن عرفت في ترجمة أبى عمر مولى بشر في (٢١٠٧)."],[12957,"باب أبى عيسى"],[12958,"٢١٥٢ - أبو عيسى (١) الأُسْوارى (٢)، بصرى، روى عن أبى سعيد الخدرى، وعبد اللَّه بن عمر، روى عنه قتادة، وعاصم بن سليمان الأحول، وقد قال الميمونى، عن أحمد بن حنبل: لا أعلم أحدا روى عن أبى عيسى الاسوارى غير قتادة."],[12959,"٢١٥٣ - أبو عيسى، مدنى، روى عن أنس بن مالك عن النبى عليه السلام. روى عنه صفوان بن سليم."],[12960,"٢١٥٤ - أبو عيسى، سمع عطاء الخراسانى. روى عنه سعيد بن أبى أيوب يعد في المصريين. واظنه أبا عيسى موسى بن عيسى القرشى."],[12961,"٢١٥٢ - كنى البخارى (ص ٥٧)، الثقات (٥/ ٥٨٠) المقتنى في سرد الكنى (١٠٨/ ب)، الجرح (٤/ ٢/ ٤١٣) وقال: ذكره عبد اللَّه بن أبى عمر البكرى قال: سمعت عبد الملك الميمونى قال: قال أبو عبد اللَّه -يعنى أحمد بن حنبل: لا أعلم أحدا روى عن أبى عيسى الأسوارى غير قتادة. التهذيب (١٢/ ١٩٥) وذكر قول الميمونى عن أحمد فيه. وقال في التقريب (٢/ ٤٥٨): مقبول من الرابعة./ بخ. م."],[12962,"(١) زاد في: الثقات \"الحارثى\"."],[12963,"(٢) الاسوارى: بضم الهمزة وسكون السين المهملة وفتح الواه وفى آخرها الراء المهملة - هذه النسبة إلى أُسْوار. والمشهور بهذه النسبة أبو عيسى الاسوارى. كذا قال ابن الاثير. اللباب (١/ ٦٠)."],[12964,"٢١٥٣ - الجرح (٤/ ٢/ ٤١٢)."],[12965,"٢١٥٤ - المقتنى في سرد الكنى (١٠٨/ أ)."],[12966,"٢١٥٥ - أبو عيسى الدمشقى، سمع ابن شهاب الزهرى، روى عنه هشام ابن عمار عن الزهرى، قال: \"مر النبى عليه السلام برجل يتوضأ وهو يفرغ الماء في وضوئه إفراغا فقال: لا تسرف فقال: يا رسول اللَّه وفى الوضوء اسراف؟ قال: نعم وفى كل شئ اسراف\" (١)."],[12967,"٢١٥٦ - أبو عيسى الناجى، بصرى، كان من قدماء أصحاب الحسن، روى عن الحسن، وعن سعيد بن مِينْا (٢). روى عنه الجريرى والسرى بن يحيى."],[12968,"٢١٥٥ - المقتنى في سرد الكنى (١٠٨/ ب) وقال: أبو عيسى الدمشقى سمع الزهرى وعنه هشام بن عمار لعله عيسى بن موسى. اهـ."],[12969,"(١) الحديث ذكره السيوطى في الجامع الكبير (٢/ ٨١٤) من مراسيل الزهرى ولم يعزه. ولكن يشهد له حديث ابن عمر رضي الله عنه في سنن ابن ماجه \"الطهارة\" - باب ما جاء في القصد في الوضوء وكراهية التعدى (١/ ١٤٧) قال: \"رأى رسول اللَّه -صلى الله عليه وآله وسلم- رجلا يتوضأ فقال: \"لا تسرف لا تسرف\" وقال السندى: إسناده ضعيف. وأخرح ابن ماجه أيضًا (١/ ١٤٧) حديث عبد اللَّه بن عمرو \"أن رسول اللَّه -صلى الله عليه وآله وسلم- مر بسعد، وهو يتوضأ فقال: ما هذا السرف؟ فقال: أفى الوضوء اسراف؟ قال: نعم. وإن كنت على نهر جار\" وقال السندى: إسناده ضعيف، وقال البخارى \"كتاب الوضوء\" باب ما جاء في الوضوء (١/ ٢٣٢). وبين النبى -صلى الله عليه وآله وسلم- إن فرض الوضوء مرة مرة. ويتوضأ أيضًا مرتين، وثلاثًا ولم يزد على ثلاث وكره أهل العلم الإسراف فيه وأن يجاوزوا فعل النبى -صلى الله عليه وآله وسلم-. اهـ"],[12970,"٢١٥٦ - كنى البخارى (ص ٥٧)، الثقات (٧/ ٦٥٨)، الجرح (٤/ ٢/ ٤١٢) وقال: سألت أبى عنه فقال: هو شيخ للجريرى ليس بمعروف، المقتنى في سرد الكنى (١٠٨/ ب)."],[12971,"(٢) سعيد بن مِينا -أى بكسر الميم ومد النون-، مولى البخترى، بن أبى ذباب الحجازى، مكى أو مدنى، يكنى أبا الوليد، ثقة، من الثالثة./ التقريب (١/ ٣٠٦)، الخلاصة (ص ١٤٣)."],[12972,"٢١٥٧ - أبو عيسى الخراسانى، سكن الشام، رأى عمر بن الخطاب. روى عنه يحيى بن أيوب المصرى، قال أبو أحمد الحاكم: وقد أخرجت أبا عيسى هارون بن يزيد الخراسانى. روى عنه حيوة بن شريح. ولا أدرى أهما اثنان أم واحد."],[12973,"٢١٥٨ - أبو عيسى. روى عنه معاوية بن صالح الحمصى حديثا مرسلا."],[12974,"٢١٥٩ - أبو عيسى. روى عن (ابن مسعود) (١) مرسلا. روى عنه محمد بن عجلان. هو والذى قبله مجهولان."],[12975,"٢١٥٧ - المقتنى في سرد الكنى (١٠٨/ ب)، كنى البخارى (ص ٥٧)، التهذيب (١٢/ ١٩٦) وذكر قول الحاكم."],[12976,"٢١٥٨ - كنى البخارى (ص ٥٧)، الجرح (٤/ ٢/ ٤١٢)، وذكر البخارى وابن أبى حاتم أنه روى حديثا مرسلا قلت: ولم أقف على من ذكر هذا الحديث، المقتنى في سرد الكنى (١٠٨/ ب)."],[12977,"٢١٥٩ - الجرح (٤/ ٢/ ٤١٢) وقال: سألت أبى عنه فقال: هو مجهول، وهو عن ابن مسعود مرسل. اهـ. الميزان (٤/ ٥٦٠) وقال: مجهول، اللسان (٧/ ٧٠)، وقال: مجهول. المراسيل لابن أبى حاتم (ص ٢٥٥) وقال: سألت أبى عن حديث أبى عيسى عن عبد اللَّه بن مسعود قال أمرنا أن نبدأ بالسلام من لقينا. قات: هو مرسل وأبو عيىسى شيخ مجهول، روى عنه محمد بن عجلان. اهـ، جامع التحصيل (ص ٣٨٩) وذكر قول ابن أبى حاتم السابق."],[12978,"(١) في الأصل بياض، والمثبت عن مصادر الترجمة."],[12979,"باب أبى عمارة"],[12980,"٢١٦٠ - أبو عُمَارة (١)، كوفى. روى عن على بن أبى طالب رضي الله عنه. روى عنه إسماعيل بن عبد الرحمن السدى."],[12981,"٢١٦١ - أبو عمارة بن عبد اللَّه بن عتبة الهذلى. أخو عبيد اللَّه بن عبد اللَّه ابن عتبة بن مسعود. ذكر سفيان بن عيينة أنه كان مضعوفا. روى عن على بن المدينى عن سفيان قال: كنا عند الزهرى فجاء أخ لعبيد اللَّه بن عبد اللَّه يقال له أبو عمارة كان ضعيفا كان يقال له \"يا أبا عمارة احسن علف حمارك فيغضب أو فيرمى\"."],[12982,"٢١٦٠ - كنى البخارى (ص ٥٩). المقتنى في سرد الكنى (١٠٠/ أ)."],[12983,"(١) بضم العين أول الحروف وتخفيف الميم. تبصير المنتبه (٣/ ٩٦٩)."],[12984,"٢١٦١ - المقتنى في سرد الكنى (١٠٠/ أ) وقال: قال ابن عيينة: كان ضعيفًا."],[12985,"باب أبى عامر"],[12986,"٢١٦٢ - أبو عامر الشرعبى. روى عن عبد اللَّه بن عباس. روى عنه عبد اللَّه ابن دينار الحمصى من حديثه ما رواه عثمان بن عبد الرحمن الطرائفى عن اسحاق بن ثعلبة (١) عن عبد اللَّه بن دينار الحمصى عن أبى عامر الشرعبى عن ابن عباس قال: سئل النبى عليه السلام عن الأشربة فقال: \"كل مسكر خمر وكل خمر حرام ولا يكون شراب أحد طرفيه حلال والاخر حرام، ما أسكر كثيره فقليله حرام\" (٢)."],[12987,"٢١٦٢ - المقتنى في سرد الكنى (٧٨/ ب) وقال أبو عامر الزغبى."],[12988,"(١) إسحاق بن ثعلبة، ذكره ابن أبى حاتم في الجرح (١/ ١/ ٢١٥) وذكر رواية عثمان بن عبد الرحمن الطرائفى عنه. وقال: سألت أبى عنه فقال: شيخ مجهول منكر الحديث. اهـ."],[12989,"(٢) الحديث أخرجه أحمد في المسند (١/ ٢٧٤ و٢٧٩ و٣٥٠) عن ابن عباس وفيه \"كل مسكر حرام\" والبخارى \"الأشربة\" باب الباذق، ومن نهى عن كل مسكر من الأشربة (١٠/ ٦٢) وأبو داود \"الأشربة\" باب النهى عن المسكر (٣/ ٣٢٧) والطبرانى في الأوسط كما في مجمع الزوائد (٥/ ٥٣) وقال الهيثمى فيه حفص بن عمر الإمام وهو ضعيف جدا، والبزار أيضًا كما في مجمع الزوائد (٥/ ٥٣) وقال الهيثمى فيه محمد بن عمارة بن صبيح شيخ البزار ولم أعرفه وبقية رجاله رجال الصحيح. كلهم أخرجوه من حديث ابن عباس رضي الله عنهما."],[12990,"ويشهد لهذا الحديث أيضًا حديث عائشة رضي الله عنها بنحو حديث ابن عباس. أخرجه البخارى \"الأشربة\" باب الخمر من العسل (١٠/ ٤١) ومسلم (٣/ ١٥٨٥ و١٥٨٦)، وأبو داود \"الأشربة\" باب النهى عن المسكر (٣/ ٣٢٩) والترمذى \"الأشربة\" باب ما جاء في كل مسكر حرام (٥/ ٦٠٢) = ٢١٦٣ - أبو عامر الحَجْرى (١). سمع أبا ريحانة: روى عنه الهيثم بن شَفِى (٢) حديثه في أهل مصر."],[12991,"٢١٦٤ - أبو عامر. روى عن ابن عباس."],[12992,"= وابن ماجه \"الأشربة\" باب كل مسكر حرام (٢/ ١١٢٣) ومالك \"الأشربة\" باب تحريم الخمر (٢/ ٨٤٥)، الدارمى (٢/ ١١٣) وحديث ابن عمر رضي الله عنهما بنحوه أيضًا وفيه كل مسكر خمر كل خمر حرام وفيه أيضًا \"ما اسكر كثيره فقليله حرام، أخرجه مسلم\" \"الأشربة\" باب بيان أن كل مسكر خمر كل خمر حرام (٣/ ١٥٨٥، ١٥٨٧، ١٥٨٨) والترمذى وقال: حسن صحيح \"الأشربة\" باب ما جاء في شارب الخمر (٥/ ٥٩٨) والنسائى \"الأشربة\" باب اثبات اسم الخمر لكل مسكر من الأشربة (٨/ ٢٩٦ و٢٩٧)، وابن ماجه \"الأشربة\" باب كل مسكر حرام (٢/ ١١٢٣) وفى باب ما اسكر كثيره فقليله حرام."],[12993,"٢١٦٣ - كنى البخارى (ص ٥٧) وقال: المفضل أبو عامر المعافرى. المقتنى في سرد الكنى (٧٨/ ب)، الجرح (٤/ ٢/ ٤١١)، التهذيب (١٢/ ١٤٥)، وقال: أبو عامر الحجرى، الازدى المعافرى المصرى ويقال: عامر، والصحيح أبو عامر واسمه عبد اللَّه بن جابر بن حجر الازدى. وقال في التقريب (٢/ ٤٢٤)، مقبول، من الثالثة./ د. س."],[12994,"(١) الحَجْرى، بفتح الحاء المهملة وسكون الجيم وفى آخرها راء - نسبة إلى حَجْر ذى رعين. انظر الاكمال (٢/ ٣٨٧)، اللباب (١/ ٣٤٣) تبصير المنتبه (٢/ ٤٨٨)."],[12995,"(٢) الهيثم بن شَفِى، بمعجمة وفاء رزن على في الاصح الرعينى، أبو الحصين الحَجْرى، بفتح المهملة وسكون الجيم، مصرى، ثقة، من الثانية، التقريب (٢/ ٣٢٧)."],[12996,"٢١٦٤ - كنى البخارى (ص ٥٧)، الجرح (٢/ ١/ ٤١١)، الميزان (٤/ ٥٤٣) وقال: أبو عامر عن ابن عباس، وعنه إبراهيم بن زياد، وهما مجهولان. وانظر ديوان الضعفاء (ص ٣٦٣)، اللسان (٧/ ٧٠)."],[12997,"روى عنه إبراهيم بن زياد (١)."],[12998,"٢١٦٥ - أبو عامر. روى عن ابن شهاب أنه سئل عن الرجل يجب عليه الحد فيمرض فقال: يؤخر حتى يصح (٢). روى عنه معاوية بن صالح الحضرمى."],[12999,"٢١٦٦ - أبو عامر الأَلْهَانى (٣)، شامى، روى عن ثوبان، وأبى أمامة روى عنه ارطاة (٤) بن المنذر، ومعاوية بن صالح."],[13000,"٢١٦٧ - أبو عامر الاوصابى (٥). روى عن أبى أمامة. روى عنه محمد بن"],[13001,"(١) إبراهيم بن زياد قال ابن أبى حاتم: سألت أبى عنه فقال: مجهول. انظر الجرح (١/ ١/ ١٠٠) وقال البخارى في التاريخ الكبير (١/ ١/ ٢٨٧) لم يصح إسناده. اهـ."],[13002,"٢١٦٥ - كنى البخارى (ص ٥٧)، الجرح (٢/ ١/ ٤١١) وقال: سمعت أبى يقول: هو مجهول، الميزان (٤/ ٥٤٣) وقال: هو مجهول، اللسان (٧/ ٧٠)."],[13003,"(٢) أخرجه البخارى في الكنى (ص ٥٧)."],[13004,"٢١٦٦ - كنى البخارى (ص ٥٧)، الثقات (٥/ ٥٧٧)، الجرح (٤/ ٢/ ٤١١) تهذيب الكمال (٣/ ١٦١٩)، التهذيب (١٢/ ١٤٤) وذكره بكنيته وقال: اسمه عبد اللَّه بن عامر تقدم. وكذا قال في التقريب (٢/ ٤٤٣) ولم اظفر به فيمن اسمه عبد اللَّه بن عامر في الكتابين، ولا في تهذيب الكمال. واللَّه أعلم."],[13005,"(٣) الأَلْهَانى: بفتح الالف وسكون اللام، وفتح الهاء وفى آخرها النون هذه النسبة إلى أَلْهان بن مالك أخى همدان بن مالك. اللباب (١/ ٨٣)."],[13006,"(٤) في كنى البخارى \"ابن ارطاة\"."],[13007,"٢١٦٧ - كنى البخارى (ص ٥٧)، الجرح (٤/ ٢/ ٤١١) المقتنى في سرد الكنى (٧٨/ ب)، التهذيب (١٢/ ١٤٥) ذكره في الكنى وقال: اسمه لقمان بن عامر. وذكره فيمن اسمه لقمان (٨/ ٤٥٥)، وقال: قال أبو حاتم يكتب حديثه، وذكره ابن حبان في الثقات وقال: قال أبو حاتم الرازى: روايته عن أبى الدراء مرسلة. وقال في التقريب (٢/ ١٣٨) صدوق، من الثالثة./ د. س. فق. وانظر الجرح (٣/ ٢/ ١٨٢). ذكره باسمه \"لقمان\"."],[13008,"(٥) زاد في التهذيب \"ويقال: الوصابى\". والاوصابى، بفتح الالف وسكون الواو ="],[13009,"الوليد الزبيدى."],[13010,"= وفتح الصاد المهملة وفى آخرها الباء المنقوطة بواحدة - هذه النسبة إلى أوصاب وهى قبيلة من حمير. اللباب (١/ ٩٤)."],[13011,"باب أبى عمار"],[13012,"٢١٦٨ - أبو عمار، روى عن على كوفى. روى عنه السدّى."],[13013,"٢١٦٩ - أبو عمار الحداد (١) الفارسى، رأى أنس بن مالك، روى عنه نافع بن يزيد."],[13014,"٢١٧٠ - أبو عمار التيمى. روى عن أبيه (٢) عن سفينة مولى النبى عليه السلام. روى عنه عمرو بن حكام القسملى (٣). من حديث عبيد اللَّه بن جرير ابن (. . . .) (٤) عن عمرو بن حكام عن أبى عمار التيمى عن أبيه قال: صحبت سفينه مولى النبى عليه السلام في سفر فعرض لنا الأسد وذكر الخبر (٥)."],[13015,"٢١٦٨ - كنى البخارى (ص ٥٩) لكن قال \"أبو عمارة\"، الجرح (٤/ ٢/ ٤١٣)، وقال: سمعت أبى يقول: هو مجهول."],[13016,"٢١٦٩ - كنى البخارى (ص ٥٩)، الجرح (٤/ ٢/ ٤١٣) وقال: سمعت أبى يقول: هو مجهول. الميزان (٤/ ٥٥٤) وقال: مجهول. المقتنى في سرد الكنى (١٠٠/ أ)."],[13017,"(١) الحداد: بفتح الحاء المهملة وبالالف بين الدالين المهملتين أو لاهما مشدده - نسبة إلى بيع الحديد وشرائه. اللباب (١/ ٣٤٦)."],[13018,"٢١٧٠ - المقتنى في سرد الكنى (١٠٠/ أ)."],[13019,"(٢) لم أقف عليه."],[13020,"(٣) عمرو بن حكام القسملى والقساملة قبيلة من الازد. قال أحمد بن حنبل كان يروى عن شعبة نحوا من أربعة الآف حديث وترك حديثه. وقال أبو زرعة ليس بالقوى. انظر الجرح (٣/ ١/ ٢٧٧ - ٢٢٨)، اللسان (٤/ ٣٦٠)، اللباب (٣/ ٣٧)."],[13021,"(٤) في الأصل بياض بمقدار كلمة."],[13022,"(٥) الحديث ذكره الهيثمى في مجمع الزوائد (٩/ ٣٦٦) عن سفينة قال: كنت ="],[13023,"٢١٧١ - أبو عمار صاحب المزاود (١). قال: ركبت سفينة فيها أنس بن"],[13024,"= في البحر فانكسرت سفينتنا فلم نعرف الطريق فإذا أنا بالاسد قد عرض لنا فتأخر اصحابى فدنوت منه فقلت أنا سفينة صاحب رسول اللَّه -صلى الله عليه وآله وسلم- وقد أضللنا الطريق فمشى بين يدى حتى وقفنا على الطريق ثم تنحى ودفعنى كأنه يورينى الطريق فظننت أنه يودعنا. قال الهيثمى: رواه البزار والطبرانى بنحوه إلا أنه قال: فانكسرت سفينتى التى كنت فيها فركبت لوحا من ألواحها فطرحنى اللوح في أجمة فيها الاسد، فأقبل إلى يريدنى، فقلت له يا أبا الحارث أنا سفينة مولى رسول اللَّه -صلى الله عليه وآله وسلم- فطأطا رأسه وأقبل فدفعنى بمنكبه، والباقى بنحوه."],[13025,"وفى بعض طرقه عن سفينة عن رسول اللَّه -صلى الله عليه وآله وسلم- قال: نحوه ولا ادرى ما معنى قوله عن رسول اللَّه -صلى الله عليه وآله وسلم- ورجالهما وثقوا. اهـ والحديث تقدم في (٦٩٩) بنحو ما هنا وأخرجه أيضًا الحاكم في المستدرك (٣/ ٦٠٦) من طريق محمد بن المنكدر به وقال الحاكم: صحيح على شرط مسلم ولم يخرجاه ووافقه الذهبى."],[13026,"وأخرجه أيضًا الذهبى في سير أعلام النبلاء (٣/ ١٧٣)."],[13027,"٢١٧١ - كنى البخارى (ص ٥٩) وجعله هو والفارسى واحدا ونسب إليه الخبر. الجرح (٤/ ٢/ ٤١٣)، الثقات (٥/ ٥٨٦)، المقتنى في سرد الكنى (١٠٠/ أ)، اللسان (٧/ ٨٦) وقال: أبو عمار عن أنس وعنه رافع بن يزيد."],[13028,"قلت: وقوله رافع بن يزيد تحريف وإنما هو نافع بن يزيد مجهول وفى ثقات ابن حبان أبو عمار صاحب الرواة ركب سفينة فيها أنس روى عنه الفضل بن فضاله فهو هو. اهـ. وبالرجوع إلى ترجمة أبى عمار الحداد (٢١٦٩) نجد أن ابن حجر جعل الترجمتين لرجل واحد. واللَّه أعلم."],[13029,"(١) في الجرح \"المراوزة\"."],[13030,"والمزاود: جمع مزود كالاوعية في وعاء او تجمع أيضًا أزودة جمع زاد على غير القياس. انظر النهاية (٢/ ٣١٧)."],[13031,"مالك فذكر حديثا في الصلاة (١)."],[13032,"٢١٧٢ - أبو عمار، شامى، سمع أبا عبيدة بن الجراح، روى عنه أزهر بن سعيد الحرازى (٢) يعد في الشاميين."],[13033,"٢١٧٣ - أبو عمار مولى (لقوم) (٣) بالمدينة. سمع عبد اللَّه بن هدّاج (٤) روى عنه إبراهيم بن المنذر الحزامى."],[13034,"(١) الخبر أخرجه البخارى في الكنى \"قال: ركبت سفينة فيها أنس بن مالك فصلى وانصرف ذات الشمال ولم يركع في الموضع الذى صلى فيه وما أحب أن لى برؤية أنس مفروح أرجو أن أكون من التابعين. ونحو هذا ذكره ابن أبى حاتم أيضًا. انظر مصادر الترجمة."],[13035,"ولأنس أيضًا حديث آخر في الصلاة في السفينة أخرجه ابن أبى شيبه في المصنف \"الصلوات\" - باب من قال: صل في السفينة جالسا (٢/ ٢٦٦) من طريق ابن سيرين قال: خرجت مع أنس إلى بنى سيرين في سفينه عظيمة قال: فأمنا فصلى بنا فيها جلوسا ركعتين ثم صلى بنا ركعتين أخراوين. وبنحو هذا أخرجه الطبرانى في الكبير أيضًا. وقال الهيثمى رجاله ثقات. انظر مجمع الزوائد (٢/ ١٦٣)."],[13036,"٢١٧٢ - المقتنى في سرد الكنى (١٠٠/ أ)."],[13037,"(٢) ازهر بن سعيد الحَرَازى، بمهملة وراء خفيفة وبعد الالف زاى، حمصى صدوق، ويقال: هو ازهر بن عبد اللَّه، من الخامسة (ت: ١٠٨) وقيل سنة (١٢٩). التقريب (١/ ٥١)."],[13038,"٢١٧٣ - كنى البخارى (ص ٥٩)، الجرح (٤/ ٢/ ٤١٣)."],[13039,"(٣) في الأصل \"القوم\" وفى مصادر الترجمة \"لقوم\" بلا همزة كما اثبته وهو الصواب. واللَّه أعلم."],[13040,"(٤) عبد اللَّه بن هداج -بدال مهملة- الحنفى، من بنى عدى بن حنيفة روى عن أبيه روى عنه أبو عمار هاشم بن غطفان بن عمار بن مهران المدينى الجرح (٢/ ٢/ ١٩٥)، الاكمال (٧/ ٤١٦)."],[13041,"٢١٧٤ - أبو عمار الاسدى، روى عن ابن مسعود، روى عنه عثمان بن زفر (١)."],[13042,"٢١٧٤ - الجرح (٤/ ٢/ ٤١٣) وقال: سألت أبى عنه فقال: هو مجهول. الميزان (٤/ ٥٥٤) وقال: مجهول. اللسان (٧/ ٨٦) وقال: مجهول."],[13043,"(١) في اللسان \"زافر\"."],[13044,"باب أبى عمران"],[13045,"٢١٧٥ - أبو عمران الأَلهانى، روى عن أبى هريرة، وثوبان وأبى امامة، روى عنه معاوية بن صالح، وارطاة بن المنذر هكذا ذكره أبو أحمد الحاكم وذكره ابن أبى حاتم في باب أبى عامر (١)."],[13046,"٢١٧٦ - أبو عمران الفلسطينى. عن يعلى بن شداد ومجاهد. روى عنه معاوية بن صالح."],[13047,"٢١٧٧ - أبو عمران، عن الجعد، اراه أبا عثمان (٢). روى عنه بكر بن خنيس من حديث طالوت بن عبّاد (٣) عن بكر بن خنيس عن أبى عمران عن"],[13048,"٢١٧٥ - كنى البخارى (ص ٦٠)، المقتنى في سرد الكنى (١٠٥/ ب)."],[13049,"(١) انظر الجرح (٢/ ١/ ٤١١) وقد تقدمت ترجمة أبى عامر الالهانى في (٢١٦٦) وقد ذكر ابن أبى حاتم في كتاب بيان خطأ محمد بن إسماعيل البخارى في تاريخه (ص ١٥٩) أبا عمران الألهانى -في الأصل الحلابى مُحرفه- عن أبى هريرة وثوبان وأبى امامة روى عنه معاوية بن صالح وارطاه قال: وإنما هو أبو عامر الألهانى روى عن ثوبان يروى عنه ارطاه وأبو عمران روى عن أبى هريرة روى عنه معاوية بن صالح ولم يرو عن أبى امامة قال: سمعت أبى يقول: ذلك. اهـ."],[13050,"٢١٧٦ - كنى البخارى (ص ٦٠)، الجرح (٤/ ٢/ ٤١٥)."],[13051,"الثقات (٧/ ٦٥٩)، المقتنى في سرد الكنى (١٠٥/ ب)."],[13052,"٢١٧٧ - المقتنى في سرد الكنى (١٠٥/ ب) وقال: أبو عمران، عن الجعد وعنه بكر ابن خنيس."],[13053,"(٢) الجعد بن دينار اليشكرى، أبو عثمان الصيرفى، بصرى، ثقة، من الرابعة. التقريب (١/ ١٢٨)، الجرح (١/ ١/ ٥٢٨)."],[13054,"(٣) طالوت بن عبَّاد الصيرفى، قال ابن حجر: شيخ معمر ليس به بأس، وقال أبو ="],[13055,"الجعد عن أنس بن مالك فقال: ما صلى بنا رسول اللَّه صلاة المكتوبة إلا أقبل بوجهة علينا فقال: \"اللهم إنى أعوذ بك من عمل يخزى وأعوذ بك من صاحب يردى وأعوذ بك من أمل يلهى وأعوذ بك من فقر ينسى، وأعوذ بك من غنى يطغى\" (١)."],[13056,"قال أبو عمر: أبو عمران هذا والجعد مجهولان. والحديث لا يعرف له أصل في الإسناد."],[13057,"= حاتم: صدوق (ت: ٢٣٨) وله أكثر من تسعين سنة، الجرح (٢/ ١/ ٤٩٥)، اللسان (٣/ ٢٠٥)."],[13058,"(١) الحديث أخرجه ابن السنى في عمل اليوم والليلة (ص ٥٤) من طريق طالوت ابن عباد به بمثله لكن قال في سنده \"عن أبى الجعد عن أنس\"، وإنما هو الجعد عن أنس. وأخرجه أبو يعلى. كما في المطالب العالية (٣/ ٢٤٨) من طريق الجعد قال: صلى أنس بن مالك في مسجد بنى رفاعة هاهنا فأمر رجلا من أصحابه أن يؤذن فصلى بهم الصبح فلما أن فرغ من صلاته أقبل على القوم فقال: كان رسول اللَّه -صلى الله عليه وآله وسلم- إذا صلى بأصحابه أقبل على القوم فقال: \"اللهم إنى أعوذ بك من عمل يخزينى، اللهم إنى أعوذ بك من غنى يطغينى. اللهم إنى أعوذ بك من صاحب يؤذينى. . إلخ\" وذكره الهيثمى في مجمع الزوائد (١٠/ ١١٠) من حديث أنس به وقال الهيثمى: رواه البزار وفيه بكر بن خنيس وهو متروك، وقد وثق، ورواه أبو يعلى وفيه عقبة بن عبد اللَّه الاصم وهو ضعيف جدا."],[13059,"وأخرج البخارى \"الجهاد\" باب ما يتعوذ من الجبن (٦/ ٣٦) من حديث سعد قال: إن رسول اللَّه -صلى الله عليه وآله وسلم- كان يتعوذ منهن دبر كل صلاة \"اللهم إنى أعوذ بك من الجبن، وأعوذ بك من أن أرد إلى أرذل العمر، وأعوذ بك من فتنة الدنيا، وأعوذ بك من عذاب القبر\" وعند البخارى أيضًا في نفس الباب السابق (٦/ ٣٦) حديث أنس قال: كان النبى -صلى الله عليه وآله وسلم- يقول: \"اللهم إنى أعوذ بك من العجز والكسل، والجبن والهرم، وأعوذ بك من فتنة المحيا والممات، وأعوذ بك من عذاب القبر."],[13060,"٢١٧٨ - أبو عمران الأنصارى، روى عن النبى عليه السلام حديثا مرسلا، روى عنه ثعلبة بن مسلم الخثعمى (١). سئل عنه أبو زرعة فقال: هو من التابعين لا أعرف اسمه."],[13061,"٢١٧٨ - الجرح (٤/ ٢/ ٤١٥) وذكره كما هنا وقال: سئل أبو زرعة عنه فقال: هو من التابعين، ولا أعرف اسمه."],[13062,"(١) مستور من الخامسة./ د. فق. التقريب (١/ ١١٩)."],[13063,"باب أبى عقيل"],[13064,"٢١٧٩ - أبو عقيل عن أبى صالح، عن عثمان بن عفان، روى عنه أبو معن (١). غير منسوب أيضًا ولا مسمى. قال البخارى: أظن أبا صالح هذا مولى عثمان (٢)."],[13065,"٢١٨٠ - أبو عقيل الأنصارى، مولى بنى زريق، سمع عائشة، روى عنه أبو بكر بن عثمان، يعد في أهل المدينة."],[13066,"٢١٨١ - أبو عقيل، روى عنه ابنه رضى بن أبى عقيل (٣)، لم يذكر بغير هذا."],[13067,"٢١٧٩ - المقتنى في سرد الكنى (٩٦/ أ)."],[13068,"(١) أبو معن هو المتقدم في (١٨٤٦)."],[13069,"(٢) أبو صالح مولى عثمان هو المتقدم في (١٩٥٦)."],[13070,"٢١٨٠ - الجرح (٤/ ٢/ ٤١٦)، المقتنى في سرد الكنى (٩٦/ أ)."],[13071,"٢١٨١ - كنى البخارى (ص ٦٢)، الجرح (٤/ ٢/ ٤١٦)."],[13072,"(٣) ذكره ابن أبى حاتم في الجرح (١/ ٢/ ٥٢٣) وذكر روايته عن أبيه ورواية محمد بن فضل عنه ولم يذكر فيه شيئا. اهـ."],[13073,"باب أبى عون"],[13074,"٢١٨٢ - أبو عون بن أبى حازم مدنى، روى عن المسور بن مخرمة، وعبد اللَّه بن الزبير، روى عنه عبد اللَّه بن جعفر المخرمى (١). سئل أبو زرعة الرازى عنه فقال: لا أعرفه وهو مدنى (٢). قال أبو محمد بن أبى حاتم: إذا يعرفه (٣) فقد جعله مجهولا (٤). قال أبو عمر: كل من لم يرو عنه إلا رجل واحد لا يعرف إلا بذلك فهو مجهول عندهم لا تقوم به حجة (٥). وأكثر هؤلاء الذين لا يعرفون إلا بكناهم كذلك."],[13075,"٢١٨٢ - كنى البخارى (ص ٦٢)، الجرح (٤/ ٢/ ٤١٤) وفيه كلام أبى زرعة. وقول ابن أبى حاتم عَقِبَه \"إذا لم يعرفه مثله فقد جعله مجهولا\". اهـ."],[13076,"تعجيل المنفعة (ص ٣٣٤)، المقتنى في سرد الكنى (١٠٧/ ب)."],[13077,"(١) عبد اللَّه بن جعفر بن عبد الرحمن بن المسور بن مخرمة أبو محمد المدنى المَخْرَمى، بسكون المعجمة، وفتح الراء الخفيفة، ليس به بأس، من الثامنة (ت: ١٧٠). اخت. م. عـ. التقريب (١/ ٤٠٦) والمخرمى، نسبة إلى المسور بن مخرمة بن نوفل. اللباب (٣/ ١٧٨)."],[13078,"(٢) و(٤) انظر الجرح (٤/ ٢/ ٤١٤)."],[13079,"(٣) زاد في الجرح لفظ \"مثله\"."],[13080,"(٥) قال الحافظ ابن الصلاح في مقدمة علوم الحديث (ص ٣٥٤) بلغنى عن أبى عمر بن عبد البر الاندلسى وجادة قال: كل من لم يرو عنه إلا رجل واحد فهو عندهم مجهول إلا أن يكون رجلا مشهورا في غير حمل العلم كاشتهار مالك بن دينار بالزهد وعمرو بن معدى كرب بالنجدة\" أهـ."],[13081,"٢١٨٣ - أبو عون بن أبى عبد اللَّه الأنصارى. شامى (١). روى عن أبى هريرة وابن عمر وأبى إدريس الخولانى. وروى عن عثمان مرسلا. روى عنه ثور بن يزيد وأبو بكر أبى مريم ومحمد بن الوليد الزبيدى وقد روى معاوية بن صالح عن محمد بن أيوب عنه."],[13082,"٢١٨٤ - أبو عون بن أبى رُكَبَة، روى عن غيلان بن جرير. عن أنس، قال ابن أبى حاتم: سألت عنه أبى فقال: هو مجهول. والحديث الذى رواه منكر."],[13083,"٢١٨٥ - أبو عون بن أبى عبيد، حديثه في قدوم عمر الشام (٢). روى عنه ابن الهادى (٣)."],[13084,"٢١٨٣ - المقتنى في سرد الكنى (١٠٧/ ب)، كنى البخارى (ص ٦٢)، كنى مسلم (ص ٧٢٥)، الجرح (٤/ ٢/ ٤١٤) وقال: سئل أبو زرعة عنه فقال: لا أعرف اسمه، وروايته عن عثمان مرسل. الثقات (٧/ ٦٦٢)"],[13085,"وقال: أبو عون بن أبى عبيد اللَّه الأنصارى الاعور من أهل الشام."],[13086,"التهذيب (١٢/ ١٩١) وقال: اسمه عبد اللَّه بن أبى عبد اللَّه. . ثم قال: وقال الحاكم أبو أحمد: أبو عون عبد اللَّه الشامى الاعور سماه أحمد بن عمير. روى عن أبى ادريس وسعيد بن المسيب ويقال: إن أبا بكر بن محمد ابن عمرو بن حزم روى عنه. . . ثم قال ابن حجر أيضًا وذكر ابن عبد البر في الكنى أنه روى عن عثمان مرسلا وزاد في الرواة عنه الزبيدى. اهـ. التقريب (٢/ ٤٥٧) وقال: مقبول، من الخامسة./ س."],[13087,"(١) زاد في كنى البخارى والجرح \"الاعور\"."],[13088,"٢١٨٤ - الجرح (٤/ ٢/ ٤١٤) وفيه قال: سألت أبى عنه. . الخ. الميزان (٤/ ٥٦٠) وقال: مجهول، اللسان (٧/ ٨١) وقال أيضًا: مجهول."],[13089,"٢١٨٥ - كنى البخارى (ص ٦٢)، الثقات (٥/ ٥٧١). المقتنى في سرد الكنى (١٠٧/ ب)."],[13090,"(٢) ومثله في كنى البخارى والثقات."],[13091,"(٣) هكذا في الأصل \"الهادى\" وفى مصادر الترجمة \"الهاد\" بلا ياء. وفى التقريب (٢/ ٣٦٧) يزيد بن عبد اللَّه بن أسامة بن الهاد الليثى."],[13092,"٢١٨٦ - أبو عون الهجيمى، سمع قبيصة بن مُخَارق الهلالى (١)."],[13093,"٢١٨٦ - كنى البخارى (ص ٦٢)، المقتنى في سرد الكنى (١٠٧/ ب) وقال: أبو عون التميمى. سمع قبيصة بن مخارق."],[13094,"(١) قبيصة بن المخارق، بضم الميم وتخفيف المعجمة، ابن عبد اللَّه الهلالى، صحابى، سكن البصرة. التقريب (٢/ ١٢٣)."],[13095,"باب أبى عاصم"],[13096,"٢١٨٧ - أبو عاصم السدوسى - كوفى، روى عن ضرار العبدى، روى عنه عبد الواحد بن زياد العدوى من حديث محمد بن الحسن الاسدى (١)، عن عبد الواحد، عن أبى عاصم، عن ضرار قال: \"قام عمار بين الصفين يوم الجمل فقال: يا صحاب رسول اللَّه نظر كل رجل منكم لحليلته فأغلق بابه دونها وارخى ستره عليها وأخرجتم حليلة رسول اللَّه -صلى الله عليه وآله وسلم- بين الكتائب\" (٢)."],[13097,"٢١٨٨ - أبو عاصم التمار، روى عن سعيد بن جبير، روى عنه الأزهر بن راشد الكاهلى (٣)."],[13098,"٢١٨٩ - أبو عاصم الضرير، البصرى، سمع موسى بن عمران الليثى (٤)، روى عنه محمد بن إسماعيل البخارى."],[13099,"٢١٨٧ - المقتنى في سرد الكنى (٧٧/ ب)."],[13100,"(١) محمد بن الحسن بن الزبير الاسدى، الكوفى، لقبه التل بفتح المثناة وتشديد اللام، صدوق، فيه لين، من التاسعة (ت: ٢٠٠)./ خ. س. ق. التقريب (٢/ ١٥٤)."],[13101,"(٢) لم أقف عليه."],[13102,"٢١٨٨ - كنى البخارى (ص ٦٠)، كنى مسلم (ص ٧٣١)، الجرح (٤/ ٢/ ٤١٤) الثقات (٧/ ٦٦٢)، كنى ابن منده (١٩٦/ ب)."],[13103,"(٣) أزهر راشد الكاهلى، ضعيف، من الثامنة. التقريب (١/ ٥١)."],[13104,"٢١٨٩ - اللسان (٧/ ٧٠) وقال: ذكره أبو أحمد الحاكم في من لا يعرف اسمه. وذكره ابن حجر أيضًا في اللسان (٦/ ١٢٩) في ترجمة شيخه موسى بن عمران الليثى."],[13105,"(٤) انظر ترجمته في اللسان (٦/ ١٢٩)."],[13106,"٢١٩٠ - أبو عاصم الغنوى. روى عن أبى الطفيل عامر بن واثلة. روى عنه حماد بن سلمه. قال ابن أبى حاتم: سألت أبى عن أبى عاصم الغنوى فقال: لا أعلم أحدا روى عنه غير حماد بن سلمة ولا أعرفه بأكثر من هذا ولا أعرف اسمه (١). ذكر اسحاق بن منصور الكوسج (٢) عن يحيى بن معين أنه قال: أبو عاصم الغنوى ثقة (٣)."],[13107,"٢١٩٠ - كنى البخارى (ص ٦٠)، الجرح (٤/ ٢/ ٤١٤)، تهذيب الكمال (٣/ ١٦١٨ - ١٦١٩)، الميزان (٤/ ٥٤٢)، اللسان (٧/ ٤٧١)، التهذيب (١٢/ ١٤٣)، التقريب (٢/ ٤٤٣) وقال: مقبول. من الخامس./ د."],[13108,"(١) انظر الجرح (٤/ ٢/ ٤١٤)."],[13109,"(٢) الكوسج: أولها وسكون الواو وفتح السين المهملة وفى آخرها جيم عرف بهذا أبو يعقوب إسحاقى بن منصور بن بهرام الكوسج المروزى، اللباب (٣/ ١١٧)."],[13110,"(٣) انظر الجرح (٤/ ٢/ ٤١٤)."],[13111,"باب أبى عصام"],[13112,"٢١٩١ - أبو عصام، سمع أنس بن مالك، روى عنه هشام الدستوائى وعبد الوارث بن سعيد، وقد روى عن شعبة عنه. إن كان ذلك محفوظا."],[13113,"٢١٩٢ - أبو عصام الازدى، بصرى، روى عن كعب بن سور، روى عنه قتادة."],[13114,"٢١٩٣ - أبو عصام، روى عن الحسن، روى عنه السرى بن يحيى."],[13115,"٢١٩١ - كنى البخارى (ص ٥٨)، الجرح (٤/ ٢/ ٤١٢)، كنى الحاكم (٢/ ٢٦/ ب) الثقات (٥/ ٥٦٩)، الميزان (٤/ ٥٥٢) وقال: صدوق. التهذيب (١٢/ ١٦٨)، التقريب (٢/ ٤٥١) وقال: قيل: اسمه ثمامة، مقبول من الخامسة./ م. د. ت. س."],[13116,"٢١٩٢ - الجرح (٤/ ٢/ ٤١٢)، الثقات (٧/ ٦٦٧)، كنى الحاكم (٢/ ٢٦/ ب)."],[13117,"٢١٩٣ - كنى البخارى (ص ٥٩)، الجرح (٤/ ٢/ ٤١٣)، كنى الحاكم (٢/ ٢٦/ ب)."],[13118,"باب أبى عصمة"],[13119,"٢١٩٤ - أبو عصمة، روى عن رجل قال: رأيت عليا رضي الله عنه، روى عنه يحيى بن واضح (١). قال أبو أحمد الحاكم: وخليقا أن يكون نوح بن أبى مريم (٢) واللَّه أعلم."],[13120,"٢١٩٥ - أبو عصمة. روى عن سفيان الثورى. روى عنه أحمد بن أبى الحوارى الزاهد."],[13121,"٢١٩٤ - المقتنى في سرد الكنى (٩٤/ ب)."],[13122,"(١) يحيى بن واضح: هو أبو تميلة، مشهور بكنيته. انظر الترجمة (٥٠٠)."],[13123,"(٢) نوح بن أبى مريم هو أبو عصمة المتقدم في (٩٩٢)."],[13124,"٢١٩٥ - لم أقف عليه عند غير المؤلف."],[13125,"باب أبى العلاء"],[13126,"٢١٩٦ - أبو العلاء قال: رأيت عليا يأتزر فوق السرة (١)، مدنى روى عنه محمد بن أبى يحيى الاسلمى."],[13127,"٢١٩٧ - أبو العلاء، روى عن امرأة، عن ابن سيرين، روى عنه سعيد بن عبد الرحمن."],[13128,"٢١٩٨ - أبو العلاء الاودى، روى عن حميد بن عبد الرحمن الحميرى (٢)، روى عنه يزيد أبو خالد الدالانى."],[13129,"٢١٩٩ - أبو العلاء بن أبى اللجلاج. وقيل: القعقاع بن اللجلاج وقيل: حصين بن اللجلاج. روى عن أبى هريرة. روى عنه صفوان بن أبى يزيد (٣) اختلف فيه ولا تعرف صحته."],[13130,"٢١٩٦ - الجرح (٤/ ٢/ ٤١٥) وقال: سئل أبو زرعة عنه فقال: لا أعرفه. . المقتنى في سرد الكنى (٩٧/ أ)."],[13131,"(١) الخبر. ذكره أيضا ابن أبى حاتم هنا. وأيضا أخرجه الذهبى في المقتنى في سرد الكنى. انظر مصادر الترجمة."],[13132,"٢١٩٧ - كنى البخارى (ص ٦٠)، الجرح (٤/ ٢/ ٤١٥)، المقتنى في سرد الكنى (٩٧/ أ)."],[13133,"٢١٩٨ - لم أقف له على ترجمة عند غير المؤلف."],[13134,"(٢) بصرى، ثقة، فقيه، من الثالثة. التقريب (١/ ٢٠٣)."],[13135,"٢١٩٩ - المقتنى في سرد الكنى (٩٧/ أ) وقال: أبو العلاء بن أبى اللجلاج سمع أبا هريرة. ويقال: القعقاع بن اللجلاج. وقيل: حصين بن اللجلاج لا يهتدى إلى صحته. عنه صفوان بن أبى يزيد. اهـ."],[13136,"(٣) صفوان بن أبى يزيد. ويقال: ابن سليم المدنى، مقبول، من الرابعة. التقريب (١/ ٣٦٩)."],[13137,"٢٢٠٠ - أبو العلاء. قال: خرجت معتمرا فكسرت فبعثت إلى ابن عمر وابن عباس فقالا: ليس له وقت كوقت الحج."],[13138,"٢٢٠١ - أبو العلاء. سمع الحسن. روى عنه ابن عيينة."],[13139,"٢٢٠٢ - أبو العلاء، عن عامر الشعبى."],[13140,"٢٢٠٠ - لم أقف له على ترجمة عند غير المؤلف."],[13141,"٢٢٠١ - الثقات (٧/ ٦٥٦) وقال محقق كتاب الثقات في الهامش: لم نظفر به. المقتنى في سرد الكنى (٩٧/ أ)."],[13142,"٢٢٠٢ - المقتنى في سرد الكنى (٩٧/ أ)."],[13143,"باب أبى العالية"],[13144,"٢٢٠٣ - أبو العالية الشامى عن عمر بن الخطاب. روى عنه عبد اللَّه بن مسلم بن هرمز (١)."],[13145,"٢٢٠٤ - أبو العالية القيسى عن أبى المليح (٢) روى عنه عقبة بن أبى الصهباء الباهلى (٣) -يعد في البصريين."],[13146,"٢٢٠٥ - أبو العالية (المكى) (٤)! عن سعيد بن جبير، روى عنه يحيى بن كثير العنبرى (٥)."],[13147,"٢٢٠٣ - كنى مسلم (ص ٧٤٨). كنى ابن منده (١٩٧/ ب)."],[13148,"(١) مكى، ضعيف، من السادسة. التقريب (١/ ٤٥٠)."],[13149,"٢٢٠٤ - كنى مسلم (ص ٧٤٨)، كنى بن منده (١٩٧/ ب)."],[13150,"(٢) زاد مسلم \"الهذلى، وتقد تقدم أبو المليح الهذلى في (٨١٥) واسمه عامر ابن أسامة بن عمير."],[13151,"(٣) عقبة بن أبى الصهباء أبو خريم، بصرى، قال: أحمد بن حنبل: شيخ صالح، وقال: ابن معين: ثقة. وقال أبو حاتم: محله الصدق. انظر الجرح (٣/ ١/ ٣١٢)."],[13152,"٢٢٠٥ - كنى مسلم (ص ٧٤٨)، كنى ابن منده (١٩٧/ ب)."],[13153,"(٤) غير واضحة في الأصل والمثبت عن الكنى لمسلم."],[13154,"(٥) يحيى بن كثير العنبرى، بصرى، يكنى أبا غسان، ثقة، من التاسعة (ت: ٢٠٦)، التقريب (٢/ ٣٥٦). والعنبرى، بفتح العين وسكون النون وفتح الباء الموحدة وفى آخرها راء - هذه النسبة إلى العنبر بن عمرو بن تميم. ويقال لهم: بلعنبر أيضا. اهـ. اللباب (٢/ ٣٦٠)."],[13155,"باب أبى العوام"],[13156,"٢٢٠٦ - أبو العوام. شيخ روى عنه ابن عجلان انه سأل ابن عمر عن الرجل يعزب (١) في ابله وليس معه ماء أياتى أهله؟ فقال: \"اما ابن عمر فلم يكن يفعله وأما أنت فاتق اللَّه فإذا وجدت الماء فاغتسل\" (٢)."],[13157,"٢٢٠٧ - أبو العوام سادن (٣) بيت المقدس. روى عن عمر بن الخطاب"],[13158,"٢٢٠٦ - لم أقف عليه عند غير المؤلف."],[13159,"(١) يعزب: أى يبعد في المرعى. انظر النهاية (٣/ ٢٢٧) وفى القاموس (١/ ١٠٣) مادة \"عزب\" العَزَب: محركة من لا أهل له كالمِعزابة والعزيب ولا تقل أعزب أو قليل ج أعزاب وهى عزَبَه وعَزَب والاسم العُزْبة والعُزُوبه مضمومتين والفعل كَنَصَر، وتَعَزَّب ترك النكاح، والعُزُوب، الغَيْبة يعْزُبُ وَيعْزِبُ والذهاب والمِعْزَابة: من طالت عزوبته، من يعزُبُ بماشيته كالمِعْزَاب والعَزيب، الرجل يعزب عن أهله وماله. اهـ."],[13160,"(٢) الأثر: أخرجه ابن أبى شيبة (١/ ٩٧) من طريق محمد بن عجلان عن أبى العوام قال: كنت جالسا عند ابن عمر فجاء أعرابى فقال له: إنَّا نَعْزُبُ في الماشية عن الماء فيحتاج احدنا إلى أن يصيب أهله قال: اما ابن عمر فلم يكن ليفعله وأما أنت فإذا وجدت الماء فاغتسل\"."],[13161,"ومن طريق محمد بن عجلان عن أبى العوام به أخرجه عبد الرزاق (١/ ٢٤) والدولابى في الكنى (٢/ ٤٧)."],[13162,"٢٢٠٧ - كنى البخارى (ص ٦٠)، كنى مسلم (ص ٧٥٠)، كنى ابن منده (١٩٧/ ب) الجرح (٤/ ٢/ ٤١٥) وقال: نا على بن الحسن الهسنجانى قال: سمعت أبا عبد اللَّه -يعنى أحمد بن حنبل قال: أبو العوام سادن بيت المقدس لا أدرى ما اسمه. الثقات (٥/ ٥٦٤) وقال: روى عنه أهل الشام ومصر. تعجيل المنفعة (ص ٣٣٣)."],[13163,"(٣) قال أبو عبيد في غريب الحديث (١/ ٢٣٧، ٢٨٨): السدانه في كلام ="],[13164,"ومعاذ بن جبل كعب الاحبار. روى عنه روح بن (عائذ) (١) قال أحمد بن حنبل: أبو العوام سادن بيت المقدس لا أدرى ما اسمه؟ قال أبو عمر: من حديثه عند حماد بن سلمة عن على بن زيد عن أبى المليح (٢) عن روح بن عائذ عن أبى العوام عن معاذ بن جبل عن النبى عليه السلام \"من قال لا اله إلا اللَّه دخل الجنة\" (٣)."],[13165,"= العرب: الحجابة، والسادن: الحاجب. والسدنه الجماعة. اهـ. وانظر النهاية (٢/ ٣٥٥)، والقاموس (٤/ ٢٣٤) مادة \"سدن\"."],[13166,"(١) هكذا هنا \"روح بن عائذ\" وكذا في مصادر الترجمة. وفى التاريخ الكبير (٢/ ١/ ٣٠٨) \"روح بن عابد عن أبى العوام، روى عن على بن زيد عن أبى المليح. اهـ. وفى الجرح (١/ ٢/ ٤٩٧) أيضا روح بن عابد شامى روى عن أبى العوام، روى عنه على بن زيد وأبو المليح. وقال ابن حجر في تعجيل المنفعة (ص ٩١): روح بن عابد شامى، روى عن أبى العوام عن معاذ، وعنه أبو المليح بن أسامة وعلى بن زيد بن جدعان، فيه جهالة. وقال: كذا ذكر الحسينى. ثم قال ابن حجر: والذى في المسند رواية على بن زيد عن أبى المليح عن روح، فعلى يروى عن أبى المليح لا عن روح. اهـ. وستأتى هذه الرواية في تخريج الحديث وقد ذكر ابن ماكولا (٦/ ١ - ٢) عابد وضبطه بالباء المعجمة بواحدة ودال مهملة وقال: روح بن عابد سادن بيت المقدس، يروى عن أبى العوام روى عنه أبو المليح. اهـ."],[13167,"(٢) هو عامر بن اسامه، اشتهر بكنيته."],[13168,"(٣) الحديث أخرجه أحمد المسند (٥/ ٢٣٤) من طريقين عن حماد بن سلمة عن على بن زيد عن أبى المليح عن روح بن عابد عن أبى العوام عن معاذ ابن جبل قال: كنت ردف النبى -صلى الله عليه وآله وسلم- على جمل أحمر فقال: يا معاذ قلت: لبيك قال: هل تدرى ما حق اللَّه على العباد. قال: فقلت: اللَّه ورسوله اعلم قالها ثلاثا فقلت ذلك ثلاثا قال: حقه عز وجل أن يعبدوه ولا يشركوا به شيئا ثم قال: هل تدرى ما حق العباد على اللَّه إذا فعلوا ذلك؟ فقلت: اللَّه ورسوله اعلم. قالها ثلاثا وقلت ذلك ثلاثا. فقال: حقهم عليه إذا هم فعلوا ذلك أن ="],[13169,". . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . ."],[13170,"= يغفر لهم وأن يدخلهم الجنة\"."],[13171,"والحديث أخرجه أيضا أحمد بنحو هذا اللفظ لكن من طريق آخر عن معاذ بن جبل. انظر المسند (٥/ ٢٣٠، ٢٣٣، ٢٣٦). وأخرجه البخارى في \"العلم\" باب من خص بالعلم قوما دون قوم (١/ ٢٢٦، ٢٢٧) وفى كتاب \"الجهاد\" باب اسم الفرس والحمار (٦/ ٥٨) وفى كتاب \"اللباس\" - باب ارداف الرجل خلف الرجل (١٠/ ٣٩٧). وفى كتاب \"الاستئذان\" باب من أجاب بلبيك وسعديك (١١/ ٦٠). وفى كتاب \"الرقاق\" باب من جاهد نفسه في طاعة اللَّه (١١/ ٣٣٧) وفى كتاب \"التوحيد\" باب ما جاء في دعاء النبى -صلى الله عليه وآله وسلم- أمته إلى توحيد اللَّه تبارك وتعالى (١٣/ ٣٤٧). ومسلم في \"كتاب الايمان\" باب الدليل على أن من مات على التوحيد دخل الجنة (١/ ٥٨، ٥٩، ٦١) والترمذى \"كتاب الايمان\" باب افتراق هذه الامة (٧/ ٤٠٢) وقال الترمذى: حديث حسن صحيح وقد روى من غير وجه عن معاذ بن جبل. وابن ماجه \"كتاب الزهد\" باب ما يرجى من رحمة اللَّه يوم القيامة (٢/ ١٤٣٥)، كلهم أخرجوه من حديث معاذ وفى بعض ألفاظه عند أحمد والبخارى ومسلم \"ما من أحد يشهد أن لا اله إلا اللَّه وأن محمدا رسول اللَّه صدقا من قلبه إلا حرمه اللَّه على النار، قال: يا رسول اللَّه أفلا أخبر به الناس فيستبشروا؟ قال: إذا يتكلوا، واخبر بها معاذ عند موته تأثما. اهـ. هذا لفظ البخارى."],[13172,"ومعنى قوله تأثما: أى خشية الوقوع في الاثم الحاصل من كتمان العلم. كما في الفتح (١/ ٢٢٧)."],[13173,"وحديث معاذ عند أحمد \"مفاتيح الجنة شهادة أن لا اله إلا اللَّه\" ذكره الهيثمى في مجمع الزوائد (١/ ١٦) وقال: رواه أحمد والبزار وفيه انقطاع بين شهر ومعاذ. ثم ذكره مرة أخرى في (١٠/ ٨٢) وقال: رواه أحمد ورجاله وثقوا إلا أن شهرا لم يسمع من معاذ. اهـ."],[13174,"٢٢٠٨ - أبو العوام الدوسى. روى عن أبى ذر وحسن أو حسين (١) بن على خبرا. روى عنه نوح بن قيس (٢)."],[13175,"٢٢٠٩ - أبو العوام قال: كتب عمر بن الخطاب إلى أبى موسى الاشعرى روى عنه معمر."],[13176,"٢٢٠٨ - كنى البخارى (ص ٦١)، الجرح (٤/ ٢/ ٤١٥) وقال: سمعت أبى يقول: هو مجهول. الثقات (٥/ ٥٦٢)، الميزان (٤/ ٥٦٠) وقال: مجهول، له شئ عن أبى ذر. اهـ. اللسان (٧/ ٨٩) وقال: مجهول. له شئ عن أبى ذر، وقال: ذكره ابن حبان في الثقات."],[13177,"(١) في كنى البخارى \"حسين\" وفى الجرح \"حسن\"."],[13178,"(٢) نوح بن قيس بن رباح الازدى، أبو روح البصرى، أخو خالد صدوق، رمى بالتشيع، من الثامنة (ت: ١٨٣ أو ١٨٤) التقريب (٢/ ٣٠٨)، التهذيب (١٠/ ٤٨٥)."],[13179,"٢٢٠٩ - المقتنى في سرد الكنى (١٠٧/ أ) وقال: أبو العوام قال: كتب عمر إلى أبى موسى وعنه معمر. قلت: وكتاب عمر إلى أبى موسى."],[13180,"أخرجه البيهقى في المعرفة من طريق أبى عبد اللَّه الحافظ ثنا أبو العباس محمد بن يعقوب ثنا محمد بن اسحاق الصنعانى، ثنا محمد بن عبد اللَّه بن كناسه ثنا جعفر بن برقان عن معمر البصرى عن أبى العوام البصرى قال: كتب عمر. فذكره وسيأتى لفظه إن شاء اللَّه في آخر التخريج. انظر نصب الراية (٤/ ٨٢) وقال الألبانى في ارواء الغليل (٨/ ٢٤٢): اسناده إلى أبى العوام صحيح وأما أبو العوام البصرى ففى الرواة ثلاثة كلهم يكنى بهذه الكنية وكلهم بصريون وهم، فائد بن كيسان. وعبد العزيز بن الربيع الباهلى. وعمران ابن داور القطان. ولم يتعين عندى ايهم المراد هنا وثلاثتهم من اتباع التابعين، كلهم ثقات إلا الأول فلم يوثقة إلا ابن حبان ولم يدكر في ترجمة أحد منهم أنه روى عنه معمر. واللَّه أعلم. وعلى كل حال فهذه الطريق معضلة. اهـ."],[13181,"والاثر أخرجه أيضا الدارقطنى في الاقضية (٤/ ٢٠٦)، والجاحظ في البيان والتبيين (٢/ ٤٨)، وما بعدها من طريق عبيد اللَّه بن أبى حميد عن أبى = ٢٢١٠ - أبو العوام عن عبادة بن الصامت. روى عنه زياد بن أبى سودة قال أبو أحمد الحاكم: وخليقا أن يكون هذا هو الذى روى عن معاذ بن جبل (١)."],[13182,"= المليح الهذلى قال: كتب عمر بن الخطاب إلى أبى موسى الاشعرى اما بعد فإن القضاء فريضة محكمة وسنة متبعه، فافهم إذا ادلى اليك بحجة وانفذ الحق إذا وضح فانه لا ينفع تكلم بحق لانفاذ له وآس بين الناس في وجهك، ومجلسك وعدلك، حتى لا ييأس الضعيف من عدلك ولا يطمع الشريف في حيفك. . الخ الرسالة."],[13183,"وقال الزيلعى في نصب الراية (٤/ ٨٢) عبد اللَّه بن أبى حميد ضعيف لكن في التقريب (١/ ٥٣٢) عبيد اللَّه بن أبى حميد الهذلى، أبو الخطاب البصرى متروك الحديث من السابعة."],[13184,"وأخرجه أيضا الدارقطنى (٤/ ٢٠٧) والبيهقى (١٠/ ١٣٥)، ووكيع في أخبار القضاه (١/ ٧٠ - ٧٣ و٢٨٣) ثلاثتهم أخرجوه من طريق سفيان بن عيينة نا ادريس الاودى عن سعيد بن أبى بردة وأخرج الكتاب فقال هذا كتاب عمر، ثم قرئ على سفيان من هاهنا إلى أبى مولى الاشعرى اما بعد فذكره. . . الخ."],[13185,"وقال الألبانى في ارواء الغليل (٨/ ٢٤١): وهذا اسناد رجاله ثقات رجال الشيخين، لكنه مرسل، لأن سعيد بن أبى بردة تابعى صغير، روايته عن عبد اللَّه بن عمر مرسلة فكيف عن عمر؟ لكن قوله \"هذا كتاب عمر\" وجادة، وهى وجادة صحيحة من أصح الوجادات وهى حجة. اهـ."],[13186,"٢٢١٠ - المقتنى في سرد الكنى (١٠٦/ ب)."],[13187,"(١) لعله يريد بالذى روى عن معاذن جبل أبا العوام سادن بيت المقدس المتقدم في (٢٢٠٧). واللَّه أعلم."],[13188,"باب أبى عروة"],[13189,"٢٢١١ - أبو عروة، عن زياد بن (أبى) (١) عمار، عن أنس بن مالك، روى عنه المفضل بن فضالة المصرى."],[13190,"٢٢١٢ - أبو عروة، سمع عمرو بن شعيب، روى عنه خليفة (٢) بن غالب (٣)."],[13191,"٢٢١١ - الميزان (٤/ ٥٥١) وقال: عن زياد بن فلان مجهول، وكذا قال ابن حجر في اللسان (٧/ ٨١)، المقتنى في سرد الكنى (٩٣/ ب)."],[13192,"(١) الحق في هامش الأصل، كتب بعده كلمة \"صح\"."],[13193,"٢٢١٢ - كنى البخارى (ص ٦٣). المقتنى في سرد الكنى (٩٣/ ب)."],[13194,"(٢) في كنى البخارى \"خلف\"."],[13195,"(٣) خليفة بن غالب الليثى، أبو غالب البصرى، صدوق، من السابعة. التقريب (١/ ٢٢٧)."],[13196,"باب أبى عتبة"],[13197,"٢٢١٣ - أبو عتبة الكندى الحمصى. سمع أبا أمامة الباهلى. روى عنه معاوية بن صالح. وروى معاوية بن صالح عن أبى عتبة أن عمر بن عبد العزيز قال: ادرأوا الحدود ما استطعتم في كل شبهة فإن الوالى إذا أخطأ في العفو خير من أن يخطئ في العقوبة (١)."],[13198,"٢٢١٣ - كنى البخارى (ص ٥٨)، الجرح (٤/ ٢/ ٤١٢)، الثقات (٥/ ٥٧٠) وقال أبو عتبة من أهل حمص يروى عن أبى أمامة روى عنه معاوية بن صالح. المقتنى في سرد الكنى (٩٠/ أ)، تعجيل المنفعة (ص ٣٢٩) وقال: ذكره الحاكم أبو أحمد فيمن لا يعرف اسمه، وذكره ابن حبان في الثقات."],[13199,"(١) الأثر أخرجه ابن الجوزى في سيرة عمر بن عبد العزيز (ص ٨٤) من طريق الليث بن سعد عن معاوية بن صالح عن أبى عقبة -هكذا في سيرة عمر \"عقبة\" وهو تصحيف وإنما هو \"عتبة\" واللَّه أعلم- أن عمر بن عبد العزيز قال: \"ادرؤا الحدود ما استطعتم. . الخ\"."],[13200,"وأخرجه أيضا ابن عساكر في تاريخ دمشق (١٩/ ١٧١/ ٢) من طريق محمد بن أحمد بن ثابت نا أبو مسلم إبراهيم بن عبد الصمد نا محمد بن أبى بكر المقدمى نا محمد بن على الشامى نا أبو عمران الجونى قال: قال عمر بن عبد العزيز فذكره. وفيه قصة مطولة. قال الشيخ الألبانى في ارواء الغليل (٧/ ٣٤٤): ضعيف."],[13201,"وأخرجه من هذا الوجه أيضا أبو سعد بن السمعانى في \"الذيل\" كما في المقاصد الحسنة (ص ٣٠) وقال: قال شيخنا: وفى سنده من لا يعرف. اهـ."],[13202,"وأخرجه أيضا ابن أبى شيبة (٩/ ٥٦٦) من طريق هشيم عن منصور عن الحارث عن إبراهيم قال: قال عمر بن الخطاب لئن أعطل الحدود بالشبهات أحب إلى من أن اقيمها بالشبهات. ولعائشة رضي الله عنها حديث مرفوع = قال أبو أحمد الحاكم (وخليقا ان يكون) (١) هذا والذى تقدم واحدا."],[13203,"٢٢١٤ - (أبو عتبة مولى مروان رأى عبد اللَّه بن مُغَفّل روى عنه عبد اللَّه بن الوليد) (٢)، (٣)."],[13204,"٢٢١٥ - أبو عتبة. روى عن عائشة روى عنه مسعر بن كدام قال أبو حاتم: هو مجهول لا يعرف روى عنه مسعر عن رجل عن عائشة."],[13205,"= بنحو هذا ولفظه \"ادرؤوا الحدود عن المسلمين ما استطعتم فإن كان له مخرج فخلوا سبيله فإن الإمام أن يخطى في العفو خير من أن يخطى في العقوبة\" أخرجه الترمذى \"الحدود\" باب ما جاء في درء الحدود (٤/ ٦٨٨) والدارقطنى (٣/ ٨٤) والخطيب في التاريخ (٥/ ٣٣١) والحاكم (٤/ ٣٨٤ - ٣٨٥) وقال: حديث صحيح الاسناد ولم يخرجاه وتعقبه الذهبى فقال: في سنده يزيد بن زياد شامى متروك. وأخرجه البيهقى (٨/ ٢٣٨) مرفوعا وموقوفا على عائشة رضي الله عنها ورجح البيهقى الموقوف."],[13206,"وعن على رضي الله عنه قال: سمعت رسول اللَّه -صلى الله عليه وآله وسلم- يقول: ادرؤوا الحدود. أخرجه الدارقطنى (٣/ ٨٤) والبيهقى (٨/ ٢٣٨) وقال: في اسناده ضعف."],[13207,"(١) في الأصل غير واضح ولعل الصواب ما اثبته واللَّه أعلم."],[13208,"٢٢١٤ - كنى البخارى (ص ٥٨)، الجرح (٤/ ٢/ ٤١٢)، تاريخ ابن معين (٢/ ٧١٤) كنى الدولابى (٢/ ٢٦)، المقتنى في سرد الكنى (٩٠/ ب)."],[13209,"(٢) في كنى البخارى زيادة \"بن معقل\" وفى الجرح \"عبد اللَّه بن الوليد بن عبد اللَّه بن معقل\" وفى التقريب (١/ ٤٥٩) عبد اللَّه بن الوليد بن مغفل المزنى، الكوفى، ويقال: له: العجلى، ثقة، من السابعة./ ت. س. اهـ."],[13210,"(٣) الحقت هذه الترجمة بكاملها في الهامش كتب عندها \"صح أصل\"."],[13211,"٢٢١٥ - الجرح (٤/ ٢/ ٤١٢) وقال: سمعت أبى يقول: لا يدرى من هو ولا يعرف. تهذيب الكمال (٣/ ١٦٢٥)، الميزان (٤/ ٥٤٩) وقال: شيخ لمسعر له عن عائشة أو عن رجل عنها فيه جهالة. اللسان (٧/ ٤٧٣) وقال: مجهول. = ٢٢١٦ - أبو عتبة عن سعيد بن جبير، روى عنه (ادريس الاودى) (١)."],[13212,"= التهذيب (١٢/ ١٦٢) وقال: عن عائشة أو عن رجل عنها، وعنه مسعر. ."],[13213,"قلت: أخرج حديثه الحاكم في المستدرك أهـ التقريب (٢/ ٤٤٩) وقال مجهول، من الثالثة./ س. اهـ، المقتنى في سرد الكنى (٩٠/ أ)."],[13214,"٢٢١٦ - كنى البخارى (ص ٥٨)، الثقات (٧/ ٦٦٠)، المقتنى في سرد الكنى (٩٠/ أ)."],[13215,"(١) غير واضح في الأصل \"والمثبت عن مصادر الترجمة\" وادريس الاودى: هناك أثنان يسمى كل منهما ادريس الاودى وكلاهما من طبقة واحدة فالأول ادريس ابن صبيح الاودى، مجهول من السابعة، ويقال هو ابن يزيد./ ق. والاخر ادريس بن يزيد بن عبد الرحمن الاودى، ثقة، من السابعة./ ع. انظر التقريب (١/ ٥٠)، التهذيب (١/ ١٩٥) والجرح (١/ ١/ ٢٦٣ - ٢٦٤)، وتهذيب الكمال (١/ ٧٣)."],[13216,"باب أبى علقمة"],[13217,"٢٢١٧ - أبو علقمة الهاشمى، مولى بنى هاشم وقد قيل: مولى ابن عباس وقيل: حليف بنى هاشم. وقيل: الأنصارى روى عن أبى هريرة، روى عنه يعلى بن عطاء، ومحمد بن الحارث بن سفيان (١)، ويونس بن خباب، ويعقوب بن عطاء ابن أبى رباح."],[13218,"٢٢١٨ - أبو علقمة عن عائشة روى عنه (مسعر بن كدام) (٢)."],[13219,"٢٢١٩ - (أبو علقمة، عن سعيد بن المسيب أنه سأله، روى عنه) (٣) شعبة."],[13220,"٢٢٢٠ - أبو علقمة، مولى ابن عباس. روى عن يسار بن نمير (٤). روى عنه"],[13221,"٢٢١٧ - كنى البخارى (ص ٥٩) وقد ذكره كما هنا تقريبا، المقتنى في سرد الكنى (٩٦/ أ)، الجرح (٤/ ٢/ ٤١٩) وقال: سمعت أبى يقول: أحاديثه صحاح، التهذيب (١٢/ ١٧٣)، التقريب (٢/ ٢٥٢) وقال: أبو علقمة الفارسى المصرى مولى بنى هاشم ويقال: حليف الأنصار ثقة، وكان قاضى افريقية، من كبار الثالثة./ زم. عـ. أهـ."],[13222,"(١) مكى، مقبول، من السادسة. التقريب (٢/ ١٥٢)."],[13223,"٢٢١٨ - كنى البخارى (ص ٥٦). المقتنى في سرد الكنى (٩٦/ أ)."],[13224,"(٢) الحق في هامش الأصل، كتب بعده \"صح أصل\"."],[13225,"٢٢١٩ - كنى البخارى (ص ٥٩) وقال: \"أبو علقمة سألت سعيد بن المسيب روى عنه شعبة\"، المقتنى في سرد الكنى (٩٦/ أ)."],[13226,"(٣) الحق في هامش الأصل، وكتب بعده \"صح أصل\"."],[13227,"٢٢٢٠ - كنى مسلم (ص ٧٥٨)، كنى ابن منده (٩٨/ أ)، المقتنى في سرد الكنى (٩٦/ أ)."],[13228,"(٤) يسار بن نمير، ذكره ابن حجر في التهذيب (١١/ ٣٧٦) فقال: يسار ="],[13229,"أيوب بن حصين (١)."],[13230,"٢٢٢١ - أبو علقمة. روى عنه عبد الرحمن بن زياد المعافرى ضعفه يحيى ابن معين وقال: ليس بشئ."],[13231,"= المدنى، مولى ابن عمر قال بعضهم: هو ابن نمير، روى عن مولاه عبد اللَّه ابن عمر وعنه أبو علقمة مولى ابن عباس. . الخ وانظر الجرح (٤/ ٢/ ٣٠٧) وقال ابن حجر في التقريب (٢/ ٣٧٣): ثقة، من الرابعة."],[13232,"(١) أيوب بن حصين. ذكره ابن أبى حاتم فيمن اسمه محمد فقال: محمد بن حصين التميمى، وقال بعضهم: أيوب بن حصين، ومحمد بن حصين أصح، روى عن أبى علقمة مولى ابن عباس. . الخ ولم يذكر فيه شيئا. انظر الجرح (٣/ ٢/ ٢٣٥) وذكره ابن حجر. في التهذيب (٩/ ١٢٢) أيضا في المحمدين فقال: محمد بن الحصين وذكر روايته عن أبى علقمة مولى ابن عباس، وقال في التقريب (٢/ ١٥٥) محمد بن الحصين التميمى وسماه بعضهم أيوب كنية أبيه أبو أيوب، مجهول، من السادسة. اهـ."],[13233,"٢٢٢١ - المقتنى في سرد الكنى (٩٦/ أ) وقال: أبو علقمة شيخ ضعفه ابن معين الميزان (٤/ ٥٥٤) وقال: قال ابن معين: ليس بشئ، اللسان (٧/ ٨٢)."],[13234,"باب أبى عائشة"],[13235,"٢٢٢٢ - أبو عائشة، كوفى روى عن عبد اللَّه بن عمر. روى عنه عبيد اللَّه ابن مروان (١). قال: وكان رجل صدق (٢)."],[13236,"٢٢٢٣ - أبو عائشة، جد أبى عاصم الثقفى (٣). قال: كان على رضي الله عنه (يوهب) (٤) الطلاء (٥)، روى عنه أبو عاصم الثقفى."],[13237,"٢٢٢٢ - كنى البخارى (ص ٦٠)، الجرح (٤/ ٢/ ٤١٧)."],[13238,"(١) عبيد اللَّه بن مروان. ذكره ابن أبى حاتم في الجرح (٢/ ٢/ ٣٣٤) وقال: سمع أبا عائشة يحدث عن ابن عمر، ولم يذكر فيه شيئا."],[13239,"(٢) ومثله في مصادر الترجمة."],[13240,"٢٢٢٣ - كنى البخارى (ص ٦٠)، الجرح (٤/ ٢/ ٤١٧)، المقتنى في سرد الكنى (٧٩/ أ)."],[13241,"(٣) تقدم في الكتاب الثانى (٩٦٦)."],[13242,"(٤) هكذا صورتها في الأصل \"يوهب\" وفى كنى البخارى \"يرزقنا\" بلا ذكر \"الطلاء\" وفى الجرح \"يرزقنا الطلاء\"."],[13243,"(٥) الأثر أخرجه النسائى \"الأشربة\" (٨/ ٣٢٩) من طريق الشعبى قال: كان على رضي الله عنه يرزق الناس الطلاء يقع فيه الذباب ولا يستطيع أن يخرج منه\"، وابن أبى شيبة \"الأشربة\" باب الطلاء (٧/ ١٧١) من طريق عبد اللَّه البجلى عن رجل قد سماه قال: كان على يرزق الناس من الطلاء ما ذهب ثلثاه وبقى ثلث، ومن طريق عبد الرحمن بن أبى ليلى وأبى جحيفة قالا: كان على يرزقنا الطلاء وأيضا في (٧/ ١٧٤) من طريق السدى عن شيخ من الحضرميين قال: قسم على طلاء فبعث الىَّ بقدح. . الخ وفى (٧/ ١٧٦) من طريق عطاء عن أبى عبد الرحمن عن على قال كان يرزقنا الطلاء فقلت له: ما هيئته؟ قال: اسود يأخذه أحدنا باصبعه، وقد ذكر ابن التركمانى في الجوهر النقى ="],[13244,"٢٢٢٤ - أبو عائشة، مدنى سمع شعبة (١) مولى ابن عباس. روى عنه عمر ابن عقبة (٢)."],[13245,"٢٢٢٥ - أبو عائشة (٣) مولى سعيد بن العاص، روى عن حذيفة وأبى موسى الاشعرى. روى عنه مكحول."],[13246,"= (٨/ ٣٠١) الحديث عن على رضي الله عنه."],[13247,"وحديث الطلاء علقه البخارى \"الأشربة\" باب الباذق (١٠/ ٦٢) قال: ورأى عمر وأبو عبيدة ومعاذ شرب الطلاء على الثلث وشرب البراء وأبو جحيفة على النصف وقال ابن عباس: اشرب العصير ما دام طريا."],[13248,"قلت: والطلاء: هو عصير العنب يطبخ حتى يذهب ثلثاه ويبقى الثالث، وإنما سمى بذلك لأنه شبه بطلاء الابل في تخنه وسواده، وبعض العرب يجعل الطلاء الخمر. انظر غريب الحديث لأبى عبيد (٢/ ١٧٧)."],[13249,"وقال الحافظ ابن حجر في الفتح (١١/ ٦٤) والطلاء، بكسر المهملة والمد هو الدبس شُبِّه بطلاء الابل وهو القطران الذى يدهن به فإذا طبخ عصير العنب حتى تمدد أشبه طلاء الابل، وهو في تلك الحالة غالبا لا يسكر. اهـ."],[13250,"٢٢٢٤ - المقتنى في سرد الكنى (٧٩/ أ)."],[13251,"(١) شعبة بن دينار الهاشمى، مولى ابن عباس، المدنى، صدوق، سئ الحافظ، من الرابعة، مات في وسط خلافة هشام./ د. التقريب (١/ ٣٥١)."],[13252,"(٢) في المقتنى \"عمر بن عقبة شيخ للواقدى\"."],[13253,"٢٢٢٥ - المقتنى في سرد الكنى (٧٩/ أ)، الميزان (٤/ ٥٤٣) وقال: غير معروف، اللسان (٧/ ٤٧٢)، التهذيب (١٢/ ١٤٦)، التقريب (٢/ ٤٤٤)، وقال: مقبول من الثانية./ د."],[13254,"(٣) في مصادر الترجمة زيادة \"جليس أبى هريرة\"."],[13255,"باب أبى عزرة"],[13256,"٢٢٢٦ - أبو عَزْرة (١) بن شهاب أخو طارق بن شهاب، وقد قيل: فيه أبو عزة، وكان كثير الصلاة. سأل بلالا، وسلمان، روى عنه طارق بن شهاب."],[13257,"٢٢٢٧ - أبو عَزْرة، روى عن ثوبان عن النبى عليه السلام من حديث الأعمش."],[13258,"٢٢٢٦ - كنى البخارى (ص ٦٠)، الجرح (٤/ ٢/ ٤١٣) وقال: سمعت أبى يقول: لا أعلم له اسما، الثقات (٥/ ٥٨٩)، وذكره ابن سعد في الطبقات في الطبقة الأولى من أهل الكوفة بعد رسول اللَّه -صلى الله عليه وآله وسلم- (٦/ ٦٦) في ترجمة أخيه طارق ابن شهاب وقال: روى عن أخيه أبى عزرة وكان أكبر منه وكان يكثر ذكر سلمان \" أهـ. الاكمال (٦/ ٢٠٢)."],[13259,"(١) عَزْرة: بفتح العين وسكون الزاى وفتح الراء، الاكمال (٦/ ٢٠٠) تبصير المنتبه (٣/ ٩٤٦)."],[13260,"٢٢٢٧ - كنى البخارى (ص ٦٠) وذكر حديثه عن ثوبان مرفوعا \"يوشك أن تداعى عليكم الامم تداعى الاكلة على القصعة. الجرح (٤/ ٢/ ٤١٣) وذكر حديثه أيضا، الاكمال (٦/ ٢٠٢) ذكره المحقق في الهامش."],[13261,"قلت: وحديث ثوبان هذا أخرجه أبو داود \"الملاحم\" باب في تداعى الامم على الاسلام (٤/ ١١١)، وأحمد في المسند (٥/ ٢٧٩) وأبو نعيم في الحلية (١/ ١٨٢). وعزاه الهيثمى في مجمع الزوائد (٧/ ٢٨٧) إلى أحمد والطبرانى في الأوسط. وقال: اسناد أحمد جيد. اهـ."],[13262,"باب أبى عطية"],[13263,"٢٢٢٨ - أبو عطية (العقيلى) (١) بصرى مولى لبنى عُقَيْل (٢). سمع مالك بن الحويرث الليثى روى عنه بديل بن ميسرة قال أبو حاتم: لم يرو عنه غير بديل بن ميسرة (. . .) (٣) عن بديل بن ميسرة قال: نا أبو عطية مولى لنا (٤) عن مالك بن الحويرث قال: كان يأتينا في مصلانا فقيل له تقدم فصل بنا فقال: ليتقدم بعضكم اننى اخبركم ان رسول اللَّه -صلى الله عليه وآله وسلم- قال: \"إذا زار أحدكم قوما فلا يصل بهم. وليصل بهم رجل منهم\" (٥)."],[13264,"٢٢٢٨ - كنى البخارى (ص ٦٠)، الجرح (٤/ ٢/ ٤١٤) وقال: سألت أبى عنه فقال: لا يعرف ولا يسمى، الميزان (٤/ ٥٥٣) وقال: لا يدرى من هو. المقتنى في سرد الكنى (٩٥/ أ) تهذيب الكمال (٣/ ١٦٢٧ - ١٦٢٨) اللسان (٧/ ٤٧٤)، التهذيب (١٢/ ١٧٠) وقال: قال أبو حاتم: لا يعرف ولا يسمى وقال ابن المدينى: لا يعرفونه، وقال أبو الحسن القطان مجهول. وصحح ابن خزيمة حديثه. اهـ. وقال في التقريب (٢/ ٤٥١): مقبول، من الثالثة./ د. ت. س."],[13265,"(١) الحق في هامش الأصل. كتب عنده \"صح\"."],[13266,"(٢) بضم العين كما في الخلاصة (ص ٤٥٥)."],[13267,"(٣) في الأصل بياض بمقدار كلمتين."],[13268,"(٤) في المعجم الكبير وتهذيب الكمال \"مولى منا\"."],[13269,"(٥) الحديث أخرجه أحمد في المسند (٣/ ٤٣٦ و٤٣٧ و٥/ ٥٣). وأبو داود \"الصلاة\" باب امامة الزائر (١/ ١٦٢)، والترمذى وقال حسن صحيح \"الصلاة\" باب من زار قوما فلا يصل بهم (٢/ ٣٣٨)، والنسائى \"الإمامة\" امامة الزائر (٢/ ٨٠) كلهم أخرجوه من طريق بديل بن ميسرة قال حدثنا أبو عطية، عن مالك بن الحويرث به. ="],[13270,"٢٢٢٩ - أبو عطية المذبوح حديثه عند أبى بكر بن أبى مريم عن حماد ابن سعيد (١). ذكره البخارى."],[13271,"= والحديث أخرجه الطبرانى في الكبير (١٩/ ٢٨٦) من طريق يزيد بن ميسرة ثنا أبو عطية مولى منا قال: كان مالك بن الحويرث فذكره بنحوه وأخرجه أيضا المزى في تهذيب الكمال (٣/ ١٦٢٧ - ١٦٢٨) من طريق أبى عطيه مولى منا قال: كان مالك بن الحويرث يأتينا إلى مصلانا فذكر الحديث بتمامه. والحديث ذكره السيوطى في الجامع الصغير (١/ ٢٧) ورمز لصحته."],[13272,"٢٢٢٩ - كنى البخارى (ص ٦٠) وذكر ابن حجر في الإصابة (٤/ ١٣٥) في ترجمة أبى عطية غير منسوب فقال: وقد أخرج الحاكم أبو أحمد \"المذبوح\" أيضا ترجمته فيمن لا يعرف اسمه فقال: روى أبو بكر بن أبى مريم عن حماد بن سعد عنه، هكذا ذكر محمد بن إسماعيل أهـ. المقتنى في سرد الكنى (٩٥/ أ) وقال: أبو عطية المذبوح عنه حماد بن سعد."],[13273,"(١) زاد البخارى في الكنى \"بن أبى عطية\" وقد ذكر ابن أبى حاتم حماد بن سعيد بن أبى عطية المذبوح في الجرح (١/ ٢/ ١٤٠) وقال: روى عن أبيه روى عنه أبو بكر بن أبى مريم ولم يذكر فيه شيئا. اهـ."],[13274,"باب أبى عطاء"],[13275,"٢٢٣٠ - أبو عطاء، سمع عليا رضي الله عنه لم يذكروه بغير هذا."],[13276,"٢٢٣١ - أبو عطاء اليحبورى شامى. روى عن عبادة بن الصامت حديثه عند حماد بن سلمة عن داود بن أبى هند (١) عن أبى منيب (٢) عن عبادة في الخسف والمسخ (٣)."],[13277,"٢٢٣٠ - كنى البخارى (ص ٦٠)، الجرح (٤/ ٢/ ٤١٧)، وقد ذكره ابن أبى حاتم في بيان خطأ البخارى في التاريخ (ص ١٥٩) فقال: \"أبو عطاء سمع عليا، وإنما هو عطاء أبو محمد رأى عليا سمعت أبى يقول كما قال\"."],[13278,"قلت: وهو في الجرح كما ذكره البخارى في التاريخ."],[13279,"٢٢٣١ - كنى البخارى (ص ٦٠)، الجرح (٤/ ٢/ ٤١٧)، الثقات (٥/ ٥٨٧) المقتنى في سرد الكنى (٩٤/ ب) وقال: أبو عطاء المخبورى فذكره."],[13280,"(١) في كنى البخارى \"منيب\"."],[13281,"(٢) في كنى البخارى \"داود بن أبى منيب\" وإنما هو أبو منيب كما هنا وفى بقية المصادر. وهو أبو المنيب الاحدب \"وانظر الترجمة (١٨٦٢)."],[13282,"(٣) الحديث أخرجه البخارى في الكنى وفيه عنده زيادة لفظ \"انها السنين يتبع بعضها بعضا\"."],[13283,"وذكره الهيثمى في مجمع الزوائد (٨/ ١٠) من طريق حبيب أبى حبيب الشامى عن أبى عطاء عن عبادة بن الصامت وغير واحد من الصحابة رضي الله عنهم عن النبى -صلى الله عليه وآله وسلم- قال: \"والذى نفس محمد بيدة ليبيتن أناس من امتى على أشر وبطر ولعب ولهو فيصبحوا قردة وخنازير باستحلالهم الحرام واتخاذهم القينات وشربهم الخمر وبأكلهم الربا ولبسهم الحرير. وقال: رواه عبد اللَّه ورواه الطبرانى من حديث أبى أمامة فقط وفرقد ضعيف أهـ."],[13284,"٢٢٣٢ - أبو عطاء، مولى عتبة. قال: قدم ابن عباس على معاوية. روى عنه أبو خالد (١)."],[13285,"٢٢٣٢ - المقتنى في سرد الكنى (٩٤/ ب)."],[13286,"(١) هو المتقدم في (١٥٧٣) حيث جاء في ترجمته هناك أنه روى عن أبى عطاء مولى عتبه بن أبى سفيان."],[13287,"باب أبى عمير"],[13288,"٢٢٣٣ - أبو عمير، عن عاصم الجحدرى، روى عنه هارون النحوى."],[13289,"٢٢٣٤ - أبو عمير قال: كنا مع ابن سيرين في سفر فنمنا حتى طلعت الشمس، سمع منه الثورى."],[13290,"٢٢٣٥ - أبو عمير بن أنس بن مالك، روى عن عمومته (١). روى عنه أبو بشر جعفر بن أبى وحشية."],[13291,"٢٢٣٣ - كنى البخارى (ص ٦٣)، المقتنى في سرد الكنى (١٠٦/ أ)."],[13292,"٢٢٣٤ - المقتنى في سرد الكنى (١٠٦/ أ)."],[13293,"٢٢٣٥ - كنى البخارى (ص ٦٣)، الجرح (٤/ ٢/ ٤١٦)، الميزان (٤/ ٥٥٨) وقال: قال ابن القطان: لم تثبت عدالته، وصحح حديثه ابن المنذر وابن حزم وغيرهما، فذلك توثيق له. فاللَّه أعلم. اهـ. التهذيب (١٢/ ١٨٨) وذكر أن الحاكم أبا أحمد قال: اسمه عبد اللَّه. ثم قال ابن حجر أيضا: قال ابن سعد كان ثقة قليل الحديث وذكره ابن حبان في الثقات وقال ابن عبد البر: مجهول، لا يحتج به. اهـ. وفى التقريب (٢/ ٤٥٦) أبو عميرة بن أنس بن مالك الأنصارى، وقيل: اسمه عبد اللَّه، ثقة، من الرابعة، قيل: كان اكبر ولد أنس بن مالك./ د. س. ق. اهـ. وقوله \"عميرة\" بزيادة التاء في آخره إنما هو خطأ واللَّه أعلم والذى في التهذيب وبقية المصادر \"عمير\" بلا هاء."],[13294,"(١) في كنى البخارى \"عمر مثله\" وهو تحريف. واللَّه أعلم والصواب \"عن عمومته\" كما هو مثبت واللَّه أعلم."],[13295,"٢٢٣٦ - أبو عمير (١) بن سَرِيع، كان عريفا لبنى سَرِيع (٢). روى عن عبد اللَّه ابن عمرو. روى عنه توبة بن نمر (٣)."],[13296,"٢٢٣٦ - كنى البخارى (ص ٦٣)، الجرح (٤/ ٢/ ٤١٦)."],[13297,"(١) هكذا في الأصل \"عمير\" بالميم، وفى كنى البخارى والجرح \"عفير\" بالفاء المعجمة وقد ذكره ابن حبان في الثقات (٥/ ٢٨٢) فقال: عرِيَف بن سريع يروى عن عبد اللَّه بن عمر روى عنه توبة بن نمر. وجاء في الجرح (١/ ١/ ٤٤٦) في ترجمة توبة بن نمر الحضرمى المصرى أنه روى عن أبى عفير عن ابن عمر. وفى التاريخ الكبير (١/ ٣/ ١٥٦) في ترجمة توبة بن نمر أيضا أنه سمع أبا عفير عريف بن سريع عن عبد اللَّه بن عمرو أن عمر حمل على فرس في سبيل اللَّه فقال النبى -صلى الله عليه وآله وسلم-: إذا تصدقت فامضها روى عنه الليث \" أهـ. وفى تعجيل المنفعة (ص ١٩٠) عريف بن سريع أبو عفير، عن ابن عمر رضي الله عنهما وعنه توبة بن نمر، وثقه ابن حبان. اهـ."],[13298,"وقال ابن ماكولا في الاكمال (٦/ ١٦٩)، وأما عَرِيف بفتح العين كسر الراء فهو عريف بن سريع أبو عفير المصرى، روى عن عبد اللَّه بن عمرو، روى عنه أبو توبة. اهـ. والى هذا ذهب ابن حجر في تبصير المنتبه (٣/ ٩٤٤)."],[13299,"قلت: وقد أخرج أحمد في المسند (٢/ ١٧٣) من حديث عمرو بن العاص وفيه قال -صلى الله عليه وآله وسلم- \"إذا تصدقت بصدقة فامضها. من طريق عمرو بن الحارث أن توبة بن نمر حدثه أن أبا عريف سريع حدثه أن رجلا سأل ابن عمرو بن العاص. الحديث."],[13300,"(٢) النسبة اليهم سَرِيعى: بفتح السين كسر الراء وسكون الياء المثناة من تحتها وفى آخرها عين مهملة، وهو بطن من المعافر. انظر اللباب (٢/ ١١٥)."],[13301,"(٣) توبة بن نمر الحضرمى المصرى. ذكره ابن أبى حاتم في الجرح (١/ ١/ ٤٤٦) والبخارى في التاريخ الكبير (١/ ٢/ ١٥٦) ولم يذكرا فيه شيئا."],[13302,"باب أبى عياش"],[13303,"٢٢٣٧ - أبو عياش، مصرى، روى عن جابر بن عبد اللَّه. روى عنه يزيد بن أبى حبيب، وخالد بن أبى عمران المصريان."],[13304,"٢٢٣٨ - أبو عياش سمع رحيلة مولى عائشة. روى عنه بقية بن الوليد."],[13305,"٢٢٣٩ - أبو (العياش) (١). روى عن سعيد بن المسيب، روى عنه الحارث"],[13306,"٢٢٣٧ - كنى مسلم (ص ٧٦٢) كنى ابن منده (١٩٨/ ب)، المقتنى في سرد الكنى (١٠٧/ ب)، التهذيب (١٢/ ١٩٤)، وقال: قال الحاكم أبو أحمد: لا أعرف اسمه. التقريب (٢/ ٤٥٨) وقال أبو عياش بن النعمان المعافرى المصرى، مقبول، من الثالثة./ د. ق. اهـ. وذكره ابن حجر في تبصير المنتبه (٣/ ٨٩٩) فقال: وأبو عياش عن جابر. وذكره ابن ماكولا في الاكمال (٦/ ٧٠) فقال: أبو عياش عن جابر بن عبد اللَّه. . الخ."],[13307,"٢٢٣٨ - المقتنى في سرد الكنى (١٠٧/ ب) وقال: أبو عياش الدمشقى عن زحلة وعنه بقية. اهـ."],[13308,"٢٢٣٩ - كنى البخارى (ص ٦٣)، كنى الحاكم (٢/ ٤٢/ ب)، الجرح (٤/ ٢/ ٤١٩) وقال: سئل أبو زرعة عنه فقال: لا أعرفه إلا في هذا الحديث، ولا اعرف اسمه، الميزان (٤/ ٥٦٠)، وقال: مجهول، اللسان (٧/ ٧١، ٨٩) وقال: مجهول."],[13309,"(١) هكذا ذكره ابن عبد البر هنا في باب أبى عياش بالمثناة التحتانية المشددة والذى في كنى البخارى والجرح \"أبو العباس\" بالباء الموحدة، وزاد في كنى البخارى قوله \"ويقال: أبو العياس\" وجزم ابن أبى حاتم في بيان خطأ البخارى في التاريخ (ص ١٦٠) بأنه أبو العياس بالمثناة من تحتها وبالسين المهملة. وقال ابن ماكولا في الاكمال (٦/ ٦٤): وأما عياس: بياء مشددة معجمة باثنتين من تحتها فهو أبو العياس، شيخ مدنى، روى عن سعيد بن المسيب ="],[13310,"ابن عبد الرحمن بن أبى ذباب (١) حديثه عن على وعن النبى عليه السلام \"في اسباغ الوضوء في المكاره\" (٢) وقد روى عنه عبد الرحمن بن الحارث بن عبد اللَّه"],[13311,"= عن على رضي الله عنه. . وذكر أيضا رواية الحارث بن عبد الرحمن بن أبى ذباب عنه. وبنحو هذا ذكره ابن حجر في تبصير المنتبه (٣/ ٩٠٢)."],[13312,"(١) الحارث بن عبد الرحمن بن أبى ذباب. الذال مضمومة. فوقها نقطة وتحت الباء نقطة. كذا قال العسكرى في تصحيفات المحدثين (٢/ ٦٦٢) والحارث هذا ذكره ابن أبى حاتم في الجرح (١/ ٢/ ٧٩ - ٨٠) وقال: سألت أبى عنه فقال: ليس بذاك القوى، يكتب حديثه. وقال: قال أبو زرعة: لا بأس به."],[13313,"(٢) الحديث أخرجه الحاكم في الكنى (٢/ ٤٢/ ب)، وأخرجه أيضا أبو يعلى والزار باسناد صحيح، انظر الترغيب والترهيب (١/ ١٣٢) ولفظه عندهم \"اسباغ الوضوء على المكاره، واعمال الاقدام إلى المساجد وانتظار الصلاة بعد الصلاة يغسل الخطايا غسلًا."],[13314,"وروى الطبرانى في الأوسط من حديث على رضي الله عنه عن النبى -صلى الله عليه وآله وسلم- قال: \"من اسبع الوضوء في البرد الشديد كان له من الاجر كفلان\" قال الهيثمى في مجمع الزوائد (١/ ٢٣٧) فيه عمر بن حفص العبدى وهو متروك. وانظر الترغيب والترهيب (١/ ١٣٣)."],[13315,"وروى عبد اللَّه في زياداته على أبيه عن على بن أبى طالب قال: قال رسول اللَّه -صلى الله عليه وآله وسلم-: \"يا على اسبع الوضوء وان شق عليك ولا تأكل الصدقة ولا تنزى الحمر على الخيل ولا تجالس أصحاب النجوم\". قال الهيثمى في مجمع الزوائد (١/ ٢٣٦) فيه القاسم بن عبد الرحمن وفيه ضعف. ويشهد لهذا الحديث ما أخرجه مسلم \"الطهارة باب فضل اسباغ الوضوء (١/ ٢١٩)، والنسائى \"الطهارة\" باب فضل اسباغ الوضوء (١/ ٨٩)، وابن ماجه \"الطهارة - باب اسباغ الوضوء\" (١/ ١٤٨) والترمذى \"الطهارة\" باب اسباغ الوضوء (١/ ١٧١)."],[13316,"وقال: حديث حسن صحيح. وفى الباب عن على وعبد اللَّه بن عمرو ="],[13317,"ابن عياش (١)."],[13318,"= وابن عباس وعبيدة وعائشة وعبد الرحمن بن عائش الحضرمى وأنس. وأحمد في المسند (٢/ ٢٣٥، ٢٧٧)، كلهم أخرجوه من حديث أبى هريرة مرفوعا ولفظه عند مسلم \"ألا ادلكم على ما يمحو اللَّه به الخطايا ويرفع به الدرجات؟ قالوا: بلى يا رسول اللَّه. قال: \"اسباغ الوضوء على المكاره، وكثرة الخطا إلى المساجد وانتظار الصلاة بعد الصلاة، فذلكم الرباط، والباقون بنحوه."],[13319,"(١) عبد الرحمن بن الحارث بن عبد اللَّه بن عياش، بتحتانية، ومعجمة، ابن أبى ربيعة المخزومى، أبو الحارث، المدنى، صدوق، له أوهام، من السابعة (ت: ١٤٣). انظر التقريب (١/ ٤٧٦)."],[13320,"باب أبى عقبة"],[13321,"٢٢٤٠ - أبو عقبة الأَلهانى. عن أبى هريرة. روى عنه ثابت بن اسلم البنانى. يعد في أهل البصرة."],[13322,"٢٢٤١ - أبو عقبة روى عن عبد اللَّه بن عمر. روى عنه عبد العزيز بن المختار (١) من حديثه قال: \"مررت مع ابن عمر فمر بغلمة من حبش يلعبون فأعطاهم درهمين\" (٢)."],[13323,"٢٢٤٠ - المقتنى في سرد الكنى (٩٥/ ب) وقال: أبو عقبة الهلالى عن أبى هريرة وعنه ثابت البنانى. اهـ."],[13324,"٢٢٤١ - كنى البخارى (ص ٦٢) وفيه عنده قال عبد العزيز بن المختار حدثنى شيخ من أهل الخير يكنى أبا عقبة. . الخ. الجرح (٤/ ٢/ ٤١٦) وقال: سمعت أبى يقول: هو مجهول. الميزان (٤/ ٥٥٣) وقال: مجهول، المقتنى في سرد الكنى (٩٥/ ب)."],[13325,"(١) عبد العزيز بن المختار الدباغ، البصرى، مولى حفصه بنت سيرين، ثقة، من السابعة./ ع. التقريب (١/ ٥١٢)."],[13326,"(٢) الأثر ذكره البخارى في الكنى، وابن أبى حاتم في الجرح. انظر مصادر الترجمة."],[13327,"باب أبى العجماء"],[13328,"٢٢٤٢ - أبو العجماء السلمى. عن عبد اللَّه بن عمرو بن العاص روى عنه صالح بن جبير الصُّدَائى (١)."],[13329,"٢٢٤٣ - أبو العجماء (٢). عن عمر. روى عنه يحيى بن أبى عمرو السيبانى (٣)."],[13330,"٢٢٤٢ - كنى الحاكم (٢/ ٣٢/ أ) وقال: \"أبو العجفاء\" بالفاء المعجمة السلمى عن عبد اللَّه بن عمرو بن العاص. . الخ: المقتنى في سرد الكنى (٩٣/ أ) وقال أيضا: أبو العجفاء السلمى. . . الخ."],[13331,"(١) صالح بن جبير الصُّدائى، بضم المهملة وتخفيف الدال: نسبة إلى صُدَا قبيلة من اليمن. انظر اللباب (٢/ ٢٣٦)، وصالح هذا كاتب لعمر بن عبد العزيز، صدوق، من الرابعة. التقريب (١/ ٣٥٨)."],[13332,"٢٢٤٣ - كنى البخارى (ص ٦٢)، كنى الحاكم (٢/ ٣٢/ أ) وذكره هو وسابقه في باب أبى العجفاء بالفاء، ثم قال في آخر هذه الترجمة: وخليقا أن يكون هذا أبو العجماء بالميم. اهـ بيان خطأ البخارى في تاريخه (ص ١٦٠)، الجرح (٤/ ٢/ ٤٢٠)، الاكمال (٦/ ١٤٩)."],[13333,"(٢) هكذا في الأصل \"العجماء\" بالميم وكذا في الجرح والاكمال وبيان خطأ البخارى في تاريخه. والذى في كنى البخارى \"العجفاء\" بالفاء."],[13334,"(٣) في كنى البخارى \"الشيبانى\" بالشين المعجمة. ونبه ابن أبى حاتم في بيان خطأ البخارى في التاريخ بأنه بالسين المهملة \"السّيبانى\" وذكره ابن ماكولا أيضا فقال: أبو العجماء بالميم فهو أبو العجماء السّيبانى روى عن عمر بن الخطاب، روى عنه يحيى بن أبى عمرو السيبانى. انظر مصادر الترجمة."],[13335,"باب الكنى الشتى"],[13336,"٢٢٤٤ - أبو عمرة الجهنى. مولى زيد بن خالد الجهنى المدنى. روى عن (١) زيد بن خالد الجهنى. روى عنه محمد بن يحيى بن حَبَّان (٢)."],[13337,"٢٢٤٥ - أبو العَنْبَس (٣) الأكبر (٤). روى عن عبد اللَّه بن عمرو بن العاص وروى عن جابر بن زيد عن ابن عباس. روى عنه شعبة بن الحجاج وعبد الملك ابن عمير. يعد في البصريين."],[13338,"٢٢٤٤ - كنى البخارى (ص ٦١)، كنى مسلم (ص ٧٥٩)، الجرح (٤/ ٢/ ٤١٥)، الثقات (٥/ ٥٨١)، الميزان (٤/ ٥٥٨) وقال ما روى عنه سوى محمد بن يحيى بن حبان. التهذيب (١٢/ ١٨٧) وقال: روى عن مولاه حديث الغلول. التقريب (٢/ ٤٥٦) وقال: مقبول، من الثالثة./ د. س. ق."],[13339,"(١) في الميزان \"عن مولاه عن زيد بن خالد\"."],[13340,"(٢) محمد بن يحيى بن حَبَّان: بفتح الحاء المهملة وبالباء المعجمة بواحدة، ابن منقذ الأنصارى المدنى، ثقة فقيه، من الرابعة (ت ١٢١) وهو ابن أربع وسبعين سنة. الاكمال (٢/ ٣٠٤)، تصحيفات المحدثين (٢/ ٤٤٨) التقريب (٢/ ٢١٦)."],[13341,"٢٢٤٥ - الجرح (٤/ ٢/ ٤١٩) وقال: سمعت أبى يقول: لا يسمى، فقلت: ما حاله؟ فقال: شيخ: وكذا قال أبو زرعة: لا يعرف اسمه."],[13342,"تاريخ ابن معين (٢/ ٧١٨) وقال: لا أعرف اسمه، كنى الدولابى (٢/ ٤٦)، الاكمال (٦/ ١٨)، الميزان (٤/ ٥٥٩) وقال: لم يسم وقيل: هو عبد اللَّه بن مروان، التهذيب (١٢/ ١٨٩)، التقريب (٢/ ٤٥٧) وقال: قيل: اسمه عبد اللَّه بن مروان، مقبول، من السادسة./ د. س."],[13343,"(٣) العَنْبس: بفتح أوله، وسكون النون، وفتح الموحدة بعدها مهملة، تبصير المنتبه (٣/ ٩١٩)."],[13344,"(٤) أبو العَنْبَس الاصغر هو الملائى واسمه سعيد بن كثير تقدم في (٩٨٥)."],[13345,"٢٢٤٦ - أبو عدى الايامى (١)، روى عن ثوبان مولى رسول اللَّه -صلى الله عليه وآله وسلم- روى عنه (٢)."],[13346,"٢٢٤٧ - أبو عُذْرة (٣) أدرك النبى عليه السلام. وروى عن عائشة عن النبى عليه السلام \"أنه نهى الرجال والنساء عن الحمامات ثم رخص للرجال في المآزر\" (٤). روى عنه عبد اللَّه بن شداد قال أبو زرعة: لا أعلم روى حماد بن سلمة عن عبد اللَّه بن شداد غير هذا الحديث."],[13347,"٢٢٤٦ - لم أقف عليه عند غير المؤلف."],[13348,"(١) الإيَامى، بكسر الالف وفتح الياء المنقوطة باثنتين من تحتها - هذه النسبة إلى إِيَام ويقال: يَام أيضا بغير الف. وهو بطن من همدان. اللباب (١/ ٩٦)."],[13349,"(٢) هكذا ذكر ابن عبد البر هذه الترجمة فقال: روى عنه. ولم يذكر من روى عنه."],[13350,"٢٢٤٧ - كنى البخارى (ص ٦١)، الجرح (٤/ ٢/ ٤١٨) وقال: سئل أبو زرعة عن أبى عذرة هل يسمى فقال: لا أعلم أحدا سماه. ولم يرو حماد بن سلمة عن عبد اللَّه بن شداد إلا هذا الحديث. الثقات (٥/ ٥٧٧) وقال: قيل: له صحبة. اللسان (٧/ ٨٠) وقال: مجهول، كنى الحاكم (٢/ ٤٠/ ب) وقال: يقال: انه كان شيخ من تجار واسط."],[13351,"(٣) عذرة: هكذا هو مضبوط في الأصل بضم العين وسكون الذال المعجمة وانظر الاكمال (٦/ ٢٠٣)، وتبصير المنتبه (٣/ ٩٣٨)."],[13352,"(٤) الحديث أخرجه البخارى في الكنى والحاكم في الكنى من طريق حماد بن سلمة عن عبد اللَّه بن شداد عن أبى عذرة عن عائشة به."],[13353,"وأخرجه أيضا أحمد في المسند (٦/ ١٣٩، ١٧٩) وأبو داود \"الحمام\" (٤/ ٣٩)، وابن ماجه \"الأدب\" باب دخول الحمام (٢/ ١٢٣٤)."],[13354,"والترمذى \"الأدب\" باب ما جاء في دخول الحمام (٨/ ٨٦) وقال: حديث لا نعرفه إلا من حديث حماد بن سلمة واسناده ليس بذاك القائم. كلهم أخرجوه من طريق حماد بن سلمة عن عبد اللَّه بن شداد عن أبى عذرة به زاد أحمد وابن ماجه \"ولم يرخص للنساء\" وقد ذكر الحافظ المنذرى في = ٢٢٤٨ - أبو عِيْش (١) روى عن هارون التيمى. روى عنه اسحاق بن سليمان الرازى قال أبو حاتم: لا يعرف أبو عيش ولا هارون التيمى."],[13355,"٢٢٤٩ - أبو عذبة (٢). روى عن عمر بن الخطاب اللهم عجل عليهم بالغلام الثقفى (٣). روى عنه سريج بن عبيد."],[13356,"٢٢٥٠ - أبو عُطَارِد (٤)، روى عن ابن مسعود، روى عنه إِيَاد بن لَقِيط (٥)."],[13357,"= الترغيب والترهيب (١/ ١١٩) حديث عائشة هذا. وقال المباكفورى في تحفة الاحوذى (٨/ ٨٧) قال أبو بكر بن حازِم الحافظ: لا يعرف هذا الحديث إلا من هذا الوجه وأبو عذرة غير مشهور وأحاديث الحمام كلها معلولة، وإنما يصح منها عن الصحابة فإن كان هذا الحديث محفوظا فهو صريح. اهـ."],[13358,"٢٢٤٨ - الجرح (٤/ ٢/ ٤١٩) وقال: سألت أبى عنه فقال: لا يعرف أبو عيش ولا هارون التيمى."],[13359,"(١) عِيْش: بكسر العين وبعدها ياء ساكنة معجمه باثنتين من تحتها وآخره شين معجمة: الاكمال (٦/ ٩٣)، تبصير المنتبه (٣/ ٩١١)."],[13360,"٢٢٤٩ - كنى البخارى (ص ٦٢)، الجرح (٤/ ٢/ ٤٢٠)، الميزان (٤/ ٥٥١). وقال مجهول، كنى الحاكم (٢/ ٤٢/ أ). الاكمال (٦/ ١٦٥)."],[13361,"(٢) في كنى البخارى \"عذية\" بالياء المثناة من تحتها، وفى الاكمال (٦/ ١٦٥) \"عذبة\": بعين مفتوحة وذال معجمة وباء معجمة بواحدة فهو أبو عذبة عن عمر."],[13362,"(٣) الأثر أخرجه البخارى في الكنى، والحاكم في الكنى كما في مصادر الترجمة وابن قتيبة في المعارف (ص ٣٩٧)، وابن العماد الحنبلى في شذرات الذهب (١/ ١٠٦ - ١٠٧) كلهم أخرجوه من طريق أبى عذبة به."],[13363,"٢٢٥٠ - كنى البخارى (ص ٦٢)، الجرح (٤/ ٢/ ٤٢٠)، كنى الحاكم (٢/ ٤٢/ ب) وذكره عن محمد بن إسماعيل البخارى."],[13364,"(٤) عطار: بضم عين وكسر راء. المغنى (ص ٥٤)."],[13365,"(٥) إياد، بكسر أوله ثم تحتانية، بن لقيط، بفتح لام كسر قاف وبطاء مهملة، ="],[13366,"٢٢٥١ - أبو العَيْزَار (١)، والد عقبة (٢) بن أبى العيزار كوفى، سمع ابن عباس روى عنه ابنه عقبة، وروى عنه عاصم بن كليب."],[13367,"٢٢٥٢ - أبو عَنْبَسَة (٣). قال: \"حججت فلقيت ابن عمر\" (٤) روى عنه معاوية بن صالح."],[13368,"٢٢٥٣ - أبو العذراء (٥)، روى عن أبى الدرداء، روى عنه عمير (٦) بن هانئ (٧)"],[13369,"= السدوسى، ثقة، من الرابعة، التقريب (٢/ ٨٦)، المغنى (ص ٦٧)."],[13370,"٢٢٥١ - كنى البخارى (ص ٦٢)، الجرح (٤/ ٢/ ٤٢٠)، الثقات (٥/ ٥٨٣)، كنى الحاكم (٢/ ٤٢/ ب) وذكره عن محمد بن إسماعيل البخارى."],[13371,"(١) العيزار: بفتح مهملة وسكون تحتية وبزاى والف وراء المغنى (ص ٥٧)."],[13372,"(٢) عقبة بن أبى العيزار، ذكره ابن أبى حاتم في الجرح (٣/ ١/ ٣١٥) وذكر أنه سئل عنه يحيى القطان فقال: لم يكن به بأس. . اهـ. وقال أحمد بن حنبل: صالح الحديث. . وقال أبو زرعة: لا بأس به."],[13373,"٢٢٥٢ - كنى البخارى (ص ٦٢) ذكره كما هنا. الجرح (٤/ ٢/ ٤٢٠)، كنى الحاكم (٢/ ٤٢/ ب) وقال: يقال: مات سنة أربع وعشرين ومائة."],[13374,"(٣) عَنْبَسَة: بفتح عين وسكون نون رفتح موحدة وسين مهملة. المغنى (ص ٥٦)."],[13375,"(٤) أخرجه البخارى في الكنى، والحاكم في الكنى، وابن أبى حاتم في الجرح، من طريق معاوية بن صالح عن أبى عنبسة به. انظر مصادر الترجمة."],[13376,"٢٢٥٣ - كنى البخارى (ص ٦٣)، الجرح (٤/ ٢/ ٤٢٠)، الميزان (٤/ ٥٥١) وقال: أبو العذراء عن أم الدرداء، وعنه عمير بن هانئ، مجهول، اللسان (٧/ ٨١)، كنى الحاكم (٢/ ٤٢/ ب)."],[13377,"(٥) العذراء: بالذال المعجمة."],[13378,"(٦) في كنى البخارى \"عمر\"."],[13379,"(٧) زاد الحاكم في الكنى \"العنسى\" وفى التقريب (٢/ ٨٧) عمير بن هانئ العنسى، بسكون النون ومهملتين، أبو الوليد الدمشقى الدارانى، ثقة، من كبار الرابعة، قتل سنه (١٢٧). وقيل: قبل ذلك. اهـ."],[13380,"وقد روى عن أم الدرداء (١) عن أبى الدرداء."],[13381,"٢٢٥٤ - أبو العجلان المحاربى، وكان في جيش ابن الزبير، سمع ابن عمر، الفضل بن يزيد (*) وحميد بن أبى غنِيَّة (٢)."],[13382,"٢٢٥٥ - أبو عَبْس (٣) بن محمد بن أبى عبس بن جبر"],[13383,"(١) هناك زوجتان لأبى الدرداء تسمى كل واحدة منهما أم الدرداء كبرى وصغرى فالكبرى تسمى خيرة بنت أبى حدرد صحابية من فضلى النساء وعقلائهن وذوات الرأى فيهن مع العبادة والنسك توفيت قبل أبى الدرداء وذلك بالشام في خلافة عثمان رضي الله عنه وكانت حفظت عن النبى -صلى الله عليه وآله وسلم- وعن زوجها روى عنها جماعة من التابعين منهم ميمون بن مهران. انظر الإصابة (٤/ ٢٩٥) وأما أم الدرداء الصغرى فاسمها هجيمة، وقيل: جهيمة الاوصابية الدمشقية، ثقة، فقيهة، من الثالثة (ت: ٨١) /ع التقريب (٢/ ٦٢١) وانظر أيضا تهذيب الكمال (٣/ ١٧٠٢ - ١٧٠٣)."],[13384,"٢٢٥٤ - كنى البخارى (ص ٦٣)، الجرح (٤/ ٢/ ٤٢٠) كنى الحاكم (٢/ ٤٣/ ب) تهذيب الكمال (٣/ ١٦٢٦)، الميزان (٤/ ٥٥١) وقال: مجهول التهذيب (١٢/ ١٦٥) وقال: قال العجلى: أبو العجلان المحاربى شامى تابعى ثقة، وذكر ابن عبد البر أنه كان في جيش ابن الزبير. وفى التقريب (٢/ ٤٥٠) أبو العجلان المجاربى. وقيل فيه: أبو المخارق، مقبول من الرابعة./ بخ *. زاد في الجرح \"الثمالى\" وفى التقريب (٢/ ١١٢) الفضل بن يزيد الثمالى، بضم المثلثة، ويقال: البجلى، الكوفى، صدوق، من السادسة./ ت."],[13385,"(٢) حميد بن أبى غنية، بفتح المعجمة كسر النون وتشديد التحتانية، صدوق من السابعة التقريب (١/ ٢٠٣)."],[13386,"٢٢٥٥ - كنى البخارى (ص ٦٣) كنى الحاكم (٢/ ٣٠/ ب)، الجرح (٤/ ٢/ ٤٢٠) وقد ذكره ابن حجر في التهذيب (١٢/ ١٥٧) في ترجمة أبى عبس بن جبر عرضا فقال: أبو عبس بن محمد بن أبى عبس. الاكمال (٦/ ٨٩)."],[13387,"(٣) بفتح العين وسكون الباء الموحدة. كما في الاكمال (٦/ ٨٨)."],[13388,"الأنصارى. روى عنه ابنه عبد المجيد (١)."],[13389,"٢٢٥٦ - أبو عكاشة (٢). روى عن أبى رفاعة (٣). روى عنه أبو ليلى الهمدانى (٤)."],[13390,"٢٢٥٧ - أبو عَتِيق (٥) (البصرى) (٦) روى عن ابان بن يزيد الرقاشى (٧) (. . . .) (٨)."],[13391,"٢٢٥٨ - أبو العبّاس، روى عن إبراهيم، روى عنه أبو الاحوص."],[13392,"٢٢٥٩ - أبو عكرمة. روى عن القاسم أبى عبد الرحمن، روى عنه عبد اللَّه ابن صالح."],[13393,"(١) ذكره ابن أبى حاتم في الجرح (٣/ ١/ ٦٤) وذكر روايته عن أبيه وقال: سألت أبى عنه فقال: هو لين. اهـ."],[13394,"٢٢٥٦ - كنى البخارى (ص ٦٣)، الجرح (٤/ ٢/ ٤٢٠)، كنى الحاكم (٢/ ٤٣/ أ)، الميزان (٤/ ٥٥٣) وقال: لا يكاد يعرف. التهذيب (١٢/ ١٧٢)، التقريب (٢/ ٤٥٢) وقال: مجهول من السادسة./ ق."],[13395,"(٢) زاد الحاكم \"الهمدانى\"."],[13396,"(٣) في كنى الحاكم والميزان، والتهذيب \"رفاعة\" وزاد الحاكم \"البجلى\"."],[13397,"(٤) أبو ليلى الهمدانى، هو المتقدم في الترجمة (١٧٣١)."],[13398,"٢٢٥٧ - كنى البخارى (ص ٦٣)، الجرح (٤/ ٢/ ٤٢٠)، كنى الحاكم (٢/ ٣١/ أ) الاكمال (٦/ ١١١)."],[13399,"(٥) عتيق: بفتح العين. الاكمال (٦/ ١٠٩)."],[13400,"(٦) غير واضح في الأصل، والمثبت عن مصادر الترجمة."],[13401,"(٧) أبان بن يزيد الرقاشى: ذكره ابن أبى حاتم في الجرح (١/ ١/ ٢٩٥) وقال: سمعت أبى يقول: أبان الرقاشى، لم يصح حديثه. إنما روى حديثا واحدا. يرويه عنه ابنه، ما نقدر أن نقول فيه."],[13402,"(٨) في الأصل بياض بمقدار كلمة."],[13403,"٢٢٥٨ - كنى البخارى (ص ٦٣)، الجرح (٤/ ٢/ ٤٢١)."],[13404,"٢٢٥٩ - كنى البخارى (ص ٦٣)، الجرح (٤/ ٢/ ٤٢١)، كنى الحاكم (٢/ ٣٢/ ب) = ٢٢٦٠ - أبو عَطَّاف (١) الازدى، عن أبى هريرة، روى عنه الجريرى."],[13405,"٢٢٦١ - أبو عبدة (٢) روى عن أنس بن مالك عن النبى عليه السلام في تخليل اللحية (٣). روى عنه موسى بن داود قاضى طرسوس."],[13406,"= ذكر في هامش كنى الحاكم."],[13407,"٢٢٦٠ - الثقات (٥/ ٥٨٨) كنى الدولابى (٢/ ٣٢)، تاريخ ابن معين (٢/ ٧١٦) الميزان (٤/ ٥٥٣) وقال: قال ابن المدينى: ما اعلم أحدا روى عنه غير الجريرى. اللسان (٧/ ٨١) كنى الحاكم (٢/ ٤٢/ أ)."],[13408,"(١) عَطَّاف: بفتح العين والطاء المهملة المشددة. تبصير المنتبه (٣/ ٩٥٧)."],[13409,"٢٢٦١ - الجرح ٤/ ٢/ ٤٢١."],[13410,"(٢) عبدة: بفتح العين المهملة أول الحروف وسكون الباء الموحدة من تحتها. تبصير المنتبه (٣/ ٩٠٧)."],[13411,"(٣) الحديث لم أقف عليه من طريق أبى عبدة. ولكن حديث أنس أخرجه أبو داود \"الطهارة\" باب تخليل اللحية (١/ ٣٦) وابن ماجه \"الطهارة\" - باب ما جاء في تخليل اللحية (١/ ١٤٨) والحاكم \"الطهارة\" باب تخليل اللحية (١/ ٣٨)، وأبو بكر الشافعى في الفوائد (٨٤٨) ولفظه عند أبى داود \"أن رسول اللَّه -صلى الله عليه وآله وسلم-\" كان إذا توضأ أخذ كفا من ماء فأدخله تحت حنكه فخلل به لحيته وقال هكذا أمرنى ربى عز وجل\". والباقون بنحوه."],[13412,"وذكر الهيثمى في مجمع الزوائد (١/ ٢٣٥) عن أنس بن مالك قال: وضأت رسول اللَّه -صلى الله عليه وآله وسلم- فأدخل يده تحت حنكه فخلل ليحته فقلت: ما هذا؟ فقال بهذا أمرنى ربى عز وجل. وقال الهيثمى: رواه الطبرانى في الأوسط ورجاله وثقوا. وأخرج الترمذى \"الطهارة\" باب ما جاء في تخليل اللحيه (١/ ١٣٠) حديث عمار وفيه انه رأى رسول اللَّه -صلى الله عليه وآله وسلم- يخلل لحيته. وقال الترمذى وفى الباب عن عثمان وعائشة وام سلمة وأنس وابن أبى اوفى وأبى أيوب."],[13413,"قلت: وحديث أنس هذا متكلم فيه فقد قال الحافظ في تلخيص الحبير (١/ ٨٦) بعد أن ذكر الحديث من رواية أبى داود: في اسناده الوليد بن زوران = ٢٢٦٢ - أبو العَدَبَّس (١)، روى عن أبى خلف."],[13414,"= وهو مجهول الحال. ثم قال: وله طرق أخرى عن أنس ضعيفه، منها: ما رويناه في فوائد أبى جعفر بن البخترى ومستدرك الحاكم، من طريق موسى بن أبى عائشة عن أنس ورجاله ثقات لكنه معلول فإنما رواه موسى بن أبى عائشة عن زيد بن أبى انيسة عن يزيد الرقاشى. عن أنس، ثم ذكر أيضا بعض طرق الحديث."],[13415,"وذكر الحافظ في تلخيص الحبير (١/ ٨٧) قال: قال عبد اللَّه بن أحمد: ليس في تخليل اللحية شئ صحيح. وقال ابن أبى حاتم عن أبيه لا يثبت عن النبى -صلى الله عليه وآله وسلم- في تخليل اللحية شئ. وهناك أحاديث بهذا المعنى منها حديث عثمان رضي الله عنه أخرجه الترمذى (١/ ٣٢) وقال حسن صحيح، والحاكم (١/ ١٤٩) وصححه وابن خزيمة (١/ ٧٨، ٧٩)، والترمذى في العلل الكبير (١/ ٤٢) وحسنه البخارى وقال الهيثمى في مجمع الزوائد (١/ ٢٣٥) رواه أبو يعلى ورجاله موثقون."],[13416,"٢٢٦٢ - كنى البخارى (ص ٦٣) قلت: الموجود في مطبوعة الكنى جزء من الترجمة واشار المحقق إلى أن الجزء الباقى من الترجمة سقط من الأصل، تاريخ ابن معين رواية الدارمى (ص ٢٣٦) وفيه أنه سأل ابن معين أبو العنبس عن أبى العدبس ما حالهما؟ فقال: ثقتان. الجرح (٤/ ٢/ ٤٢١)، الميزان (٤/ ٥٥١) وقال: أبو العدبس عن أبى مرزوق هو تبيع بن سليمان فيه جهالة قلت: وهذا هو أبو العدبس شيخ أبى العنبس، أما أبو العدبس الأكبر عن عمر - فيروى عنه عاصم القارئ، وعاصم الاحول، أوثق، التهذيب (١٢/ ١٦٦) وقال: أبو العدبس الاصغر، وذكر روايته عن أبى مرزوق، ورواية أبى العنبس عنه وقال في التقريب (٢/ ٤٥٠)، كوفى مجهول، من السادسة./ د. ت، الاكمال (٦/ ١٥١) وقال: أبو العدبس منيع بن سليمان الاسدى ويقال: الاشعرى، روى عن عمر بن الخطاب رضي الله عنه وأبى غالب حزور، يعد في الكوفيين. روى عنه عاصم الاحول، والحارث أبو العنبس الكوفى وسليمان أبو الورقاء ذكره أبو أحمد، وروى مسعر عن أبى غالب عن أبى أمامة، واختلف على مسعر في اسناده. اهـ."],[13417,"(١) العَدَبَّس: بفتح العين والدال وتشديد الباء المعجمة بواحدة، كما في الاكمال ="],[13418,"وعن أبى مرزوق (١) روى ابن نمير عن مسعر عن أبى العنبس عن أبى العدبس عن أبى مرزوق عن أبى غالب عن أبى أمامة عن النبى عليه السلام قال: \"إذا رأيتمونى فلا تقوموا كما تفعل العجم بعضها لبعض\" (٢). وقد روى مسعر عن أبى العدبس وروى أبو خلف عن أبى مرزوق."],[13419,"= (٦/ ١٥١)."],[13420,"(١) أبو مرزوق هو المتقدم في (١٨٦٨)."],[13421,"(٢) الحديث أخرجه أحمد (٥/ ٢٥٣) من طريق ابن نمير، ثنا مسعر عن أبى العنبس عن أبى العدبس عن أبى مرزوق عن أبى غالب عن أبى أمامة قال: خرج علينا رسول اللَّه -صلى الله عليه وآله وسلم- وهو متوكئ على عصا فقمنا إليه فقال: \"لا تقوموا كما تقوم الاعاجم يعظم بعضها بعضا\". قال: فكانا اشتهينا أن يدعو اللَّه لنا فقال: \"اللهم اغفر لنا وارحمنا وارض عنا وتقبل منا وادخلنا الجنة وانجنا من النار، واصلح لنا شأننا كله\" فكأنا اشتهينا أن يزيدنا فقال: \"قد جمعت لكم الامر\"."],[13422,"وأخرجه أحمد أيضا في المسند (٥/ ٢٥٦) من طريق مسعر ثنا أبو العدبس عن رجل أظنه أبا خلف، ثنا أبو مرزوق قال: قال أبو أمامة خرج علينا رسول اللَّه -صلى الله عليه وآله وسلم- فذكر الحديث."],[13423,"وأخرج أبو داود \"الأدب\" باب في قيام الرجل للرجل (٤/ ٣٥٨) من طريق عبد اللَّه بن نمير عن مسعر عن أبى العنبس عن أبى العدبس عن أبى مرزوق عن أبى غالب عن أبى أمامة يرفعه مختصرا وفيه قال، \"لا تقوموا كما تقوم إلا عاجم يعظم بعضها بعضا\" وابن ماجه \"الدعاء\" باب دعاء رسول اللَّه -صلى الله عليه وآله وسلم- (٢/ ١٢٦١) من طريق على بن محمد عن وكيع عن مسعر، عن أبى مرزوق، عن أبى وائل عن أبى امامة الباهلى يرفعة به بنحوه عند أحمد. وذكر المزى طريقا آخر للحديث عند ابن ماجه عن على بن محمد عن وكيع عن مسعر عن أبى مرزوق عن أبى العدبس عن أبى أمامة به وقال: هكذا عنده وهو وهم، والصواب الأول أهـ."],[13424,"انظر تحفة الاشراف (٤/ ١٨٣) قلت: ويريد بالأول طريق أبى داود = ٢٢٦٣ - أبو عُبَادة (١) الزرقى حجازى، روى عن خولة بنت قيس الانصارية (٢) امرأة حمزة بن عبد المطلب. روى عنه عبيد سَنُوطا (٣)."],[13425,"٢٢٦٤ - أبو عقرب الاسدى. روى عن أبى الصلت عن عبد اللَّه بن"],[13426,"= المتقدم. وقال المزى أيضا: ووقع في بعض النسخ المتأخرة عن أبى مرزوق عن أبى وائل، عن أبى امامة وهو وهم ممن دون المصنف. اهـ."],[13427,"قلت: والحديث في سنده أبو العدبس وهو مجهول، وأبو غالب وفيه ضعف أهـ."],[13428,"٢٢٦٣ - كنى الحاكم (٢/ ٢٩/ أ)، وذكره ابن حجر في التهذيب (١٢/ ١٤٦) تمييزا. وقال: لا يعرف اسمه وقال في التقريب (٢/ ٤٤٤): لا يعرف اسمه، مدنى، من الثالثة./ تمييز."],[13429,"(١) عبادة: بضم أوله والتخفيف كما في التقريب (٢/ ٤٤٤)."],[13430,"(٢) خولة بنت قيس بن قهد بن قيس بن ثعلبة الانصارية، زوج حمزة بن عبد المطلب، صحابية، لها حديث: التقريب (٢/ ٥٩٦)."],[13431,"(٣) عبيد سَنُوطا، بفتح المهملة وضم النون، ويقال: ابن سنوطا أبو الوليد المدنى وثقه العجلى، من الثالثة. التقريب (١/ ٥٤٦)."],[13432,"٢٢٦٤ - كنى البخارى (ص ٦٢)، كنى الحاكم (٢/ ٢٩/ ب)، الجرح (٤/ ٢/ ٤١٨) وقال: سمع عبد اللَّه بن مسعود. تعجيل المنفعة (ص ٣٣٢) وقال: قال الحسينى: أبو عقرب عن ابن مسعود رضي الله عنه في ليلة القدر وعنه طلق ابن حبيب، مجهول. اهـ. قال ابن حجر: قلت: وله طريق آخر عند أحمد وهو من رواية أبى يعفور عن أبى الصلت عن أبى عقرب وذكره أبو نعيم في تسمية أصحاب على وابن مسعود رضي الله عنهما، وأما ما نقله الحاكم أبو أحمد عن ابن معين انه قال: أبو عقرب يروى عن أبى الصلت عن عبد اللَّه فلعله انقلب، أو كان فيه يروى عن أبى الصلت، فوقع في السياق تغيير. ووقع في الثقات لابن خلفون أن أبا عوانة روى عنه وفيه نظر فانه في المسند من طريق أبى عوانة عن أبى يعقوب عن أبى الصلت. اهـ."],[13433,"قلت: وانظر الحديث بطريقيه في المسند (١/ ٤٠٦) من حديث ابن ="],[13434,"مسعود. روى عنه طلق بن حبييب وأبو عوانة (١)، يعد في البصريين."],[13435,"٢٢٦٥ - أبو عتيبة بن المهلب بن أبى صفرة. روى عن يزيد بن المهلب (٢). روى عنه خالد بن نافع الاسدى."],[13436,"٢٢٦٦ - أبو عَذَبَة، عن نافع مولى ابن عمر، روى عنه الجراح بن مليح (٣) حديثه في الشاميين. قال أبو أحمد الحاكم: وخليقا أن يكون هذا هو الذى"],[13437,"= مسعود رضي الله عنه وفيه قال رسول اللَّه -صلى الله عليه وآله وسلم- \"ان ليلة القدر في النصف من السبع الاواخر من رمضان تطلع الشمس غداة إذ صافية ليس لها شعاع فنظرت إليها فوجدتها كما قال رسول اللَّه -صلى الله عليه وآله وسلم-. وقد تقدم في ترجمة أبى الصلت بياع المزاد وقيل بياع البزور. روى عن أبى عقرب روى عنه أبو يعفور العبدى. اهـ. انظر (١٩٨٠) وتقدم أيضا في ترجمة أبى يعفور العبدى (١٢٤٢) أنه روى عن أبى عقرب هذا."],[13438,"(١) أبو عوانة هو وضاح اليشكرى المتقدم في (٩٩٧)."],[13439,"٢٢٦٥ - كنى الحاكم (٢/ ٤٢/ أ)."],[13440,"(٢) يزيد بن المهلب، كان كريما ممدحا، كثير الغزو والفتوح، كان أميرا على البصرة، فلما تولى عمر بن عبد العزيز، عزله وسجنه، فلما توفى عمر أخرجه خواصه من السجن فوثب على البصرة وهرب منه عاملها عدى بن ارطاة الفزارى ونصب يزيد رايات سود وتسمى بالقحطانى وقال: أدْعُو إلى سيرة عمر بن الخطاب فوجه إليه يزيد بن عبد الملك أخاه مسلمة فحاربه وقتله في صفر سنة اثنتين ومائة، وقيل: بل حبسه الحجاج وعذبه. انظر شذرات الذهب (١/ ١٢٤)."],[13441,"٢٢٦٦ - الثقات (٧/ ٦٦٤) وقال \"يروى عن نافع روى عنه شريح بن عبيد وأهل الشام. الجرح (٢/ ٤/ ٤٢٠)، الميزان (٤/ ٥٥١) وقال: أبو عذَبَةَ -بالحركات- عن نافع في الغسل قال الدارقطنى: مجهول. اللسان (٧/ ٨٠)، كنى الحاكم (٢/ ٤٢/ ب) وقال: وخليقا أن يكون هذا هو الذى روى عن عمر وروى عنه شريح بن عبيد. واللَّه أعلم. اهـ."],[13442,"(٣) زاد الحاكم في الكنى \"البهرانى\"."],[13443,"روى عن عمر. وروى عنه شريح بن عبيد (١)."],[13444,"(١) أبو عذبة الذى روى عن عمر وعنه شريح بن عبيد هو المتقدم في (٢٢٤٩)."],[13445,"حرف الغين"],[13446,"باب أبى غالب"],[13447,"٢٢٦٧ - أبو غالب، سمع عبد اللَّه بن عمر، روى عنه نهشل بن مجمّع الضبى (١) (و) (٢) أبو سنان (٣). قال عباس: سمعت يحيى بن معين يقول: أبو غالب. الذى يحدث سفيان عن نهشل عنه: لا أعرفه (٤)."],[13448,"٢٢٦٨ - أبو غالب المكى، روى عن أنس، روى عنه هشام بن حسّان."],[13449,"٢٢٦٧ - الجرح (٤/ ٢/ ٤٢١)، الثقات (٥/ ٥٩٠)، المقتنى في سرد الكنى (١٠٩/ أ)، الميزان (٤/ ٥٦١)، التهذيب (١٢/ ١٩٨)، التقريب (٢/ ٤٦٠)، وقال: مستور، من الرابعة./ س."],[13450,"(١) كوفى صدوق، من السابعة. التقريب (٢/ ٣٠٨)."],[13451,"(٢) \"و\" ليست في الأصل، والسياق يقتضيها."],[13452,"(٣) زاد في التهذيب \"ضرار بن مرة\"."],[13453,"(٤) التاريخ (٢/ ٧١٩)."],[13454,"٢٢٦٨ - الجرح (٤/ ٢/ ٤٢٢)."],[13455,"باب أبى غسان"],[13456,"٢٢٦٩ - أبو غسّان، روى عن عطاء بن أبى رباح، روى عنه سفيان الثورى."],[13457,"٢٢٧٠ - أبو غسّان، روى عن الحسن، روى عنه ليث بن أبى سليم."],[13458,"٢٢٧١ - أبو غسّان، روى عن الضحاك بن مزاحم، روى عنه يحيى بن اليمان."],[13459,"٢٢٦٩ - الجرح (٤/ ٢/ ٤٢٢)، الثقات (٧/ ٦٦١)."],[13460,"٢٢٧٠ - الجرح (٤/ ٢/ ٤٢٢)."],[13461,"٢٢٧١ - الجرح (٤/ ٢/ ٤٢٢)، المقتنى في سرد الكنى (١٠٩/ ب)."],[13462,"باب أبى غانم"],[13463,"٢٢٧٢ - أبو غانم، روى عن (أبى غالب) (١) عن أبى أمامة. روى عنه (زيد ابن أبى موسى (٢) مولى عطاء) (٣)."],[13464,"٢٢٧٣ - أبو غانم، سمع الحسن، وبلال بن أبى بردة (٤) قاضى البصرة روى عنه سوادة (٥)."],[13465,"٢٢٧٢ - الجرح (٤/ ٢/ ٤٢٣)، وقال: سألت أبى عنه فقال: لا أعرفه. اللسان (٧/ ٩٠)."],[13466,"(١) غير واضح في الأصل والمثبت عن مصادر الترجمة."],[13467,"(٢) زيد بن أبى موسى مولى عطاء، ذكره ابن أبى حاتم في المجرح (١/ ٢/ ٥٧٣) وذكر روايته عن أبى غانم، عن أبى غالب عن أبى امامة. وقال: سألت أبى عنه فقال: لا أعرفه. وانظر اللسان (٢/ ٥١١)."],[13468,"(٣) غير واضح في الأصل. والمثبت عن مصادر الترجمة."],[13469,"٢٢٧٣ - المقتنى في سرد الكنى (١٠٩/ أ)."],[13470,"(٤) بلال بن أبى بردة بن أبى موسى الاشعرى، قاضى البصرة، مقل، من الخامسة: مات سنة نيف وعشرين ومائة. التقريب (١/ ١٠٩)."],[13471,"(٥) هو سوادة بن أبى العالية. ذكره ابن أبى حاتم في الجرح (٢/ ١/ ٢٩٣) ولم يذكر فيه شيئا."],[13472,"باب كنى شتى"],[13473,"٢٢٧٤ - أبو الغصن، الشامى، سمع شداد بن أوس، روى عنه يحيى بن حسان (١)."],[13474,"٢٢٧٥ - أبو غِيَاث (٢) البصرى. روى عن الحسن. روى عنه سلام بن مسكين."],[13475,"٢٢٧٦ - أبو غَطَفَان (٣) بن طريف المرى (٤) ويقال: ابن مالك مدنى، روى"],[13476,"٢٢٧٤ - الجرح (٤/ ٢/ ٤٢٢)، المقتنى في سرد الكنى (١٠٩/ ب)."],[13477,"(١) زاد في الجرح \"البكرى\". وفى التقريب (٢/ ٣٤٥) يحيى بن حسان الفلسطينى، البكرى، ثقة، من الخامسة."],[13478,"٢٢٧٥ - الجرح (٤/ ٢/ ٤٢٣)، الثقات (٧/ ٦٦٠)، اللسان (٧/ ٩٠) وقال مجهول. ثم قال أيضا: وذكر أبو أحمد الحاكم في الكنى عن البخارى أنه حدثه بالوجهين بفتح المهملة وتشديد المثناة الفوقانية آخره موحدة أو بالمعجمة المكسورة والتحتانية الخفيفة آخره مثلثه. وقال أبو القاسم البغوى في ترجمة مغفل بن سيار من معجم الصحابة في رواية أبى غياث من روايته عن سلام ابن مسكين عن الحسن عن مغفل أبو غياب مجهول. اهـ."],[13479,"(٢) في الاكمال (٦/ ١٣١) غِيَاث، بكسر الغين المعجمة وبعدها ياء معجمة بأثنتين من تحتها وآخره ثاء معجمة بثلاث."],[13480,"٢٢٧٦ - الجرح (٤/ ٢/ ٤٢٢)، الثقات (٥/ ٥٦٧)، الميزان (٤/ ٥٦١)، وقال: لا يدرى من هو، قال الدارقطنى: مجهول، والظاهر أنه أبو غطفان بن طريف المرى، وماذا بالمجهول، وثقة غير واحد. اهـ. اللسان (٧/ ٩٠)، التهذيب (١٢/ ١٩٩)، التقريب (٢/ ٤٦١) وقال: قيل: اسمه سعد، ثقة، من كبار الثالثة./ م. د. س. ق."],[13481,"(٣) غطفان. بفتحات. كما في التقريب (٢/ ٤٦١)."],[13482,"(٤) في اللسان \"المزى\" بالزاى المعجمة. وجزم ابن حجر في التقريب بأنه ="],[13483,"عن أبى هريرة، وابن عباس، روى عنه إسماعيل بن أمية، وعمر بن حمزة بن عبد اللَّه بن عمر (١)، وداود بن الحصين، وقارظ بن شيبة الزهرى (٢)، كان لأبى غطفان دار بالمدينة عند دار عمر بن عبد العزيز (٣) قال يحيى بن معين: أبو غطفان الذى يحدث عنه داود بن الحصين مدنى ثقة حكاه عنه عباس (٤)."],[13484,"٢٢٧٧ - أبو غُطَيْف الهذلى. سمع ابن عمر عن النبى عليه السلام في الوضوء لكل صلاة (٥). روى عنه عبد الرحمن بن زياد الافريقى. قال أبو زرعة: لا أعرف اسمه."],[13485,"= \"المرى\" بالراء المهملة."],[13486,"(١) مدنى، ضعيف، من السادسة. التقريب (٢/ ٥٣)."],[13487,"(٢) قارظ آخره معجمة، ابن شيبة بن قارظ، الليثى، المدنى، حليف بنى زهرة، لا بأس به، من الثالثة. التقريب (٢/ ١١٥)."],[13488,"(٣) في الثقات \"كان لأبى غطفان دار بالمدينة عند دار عمر بن عبد العزيز كما هنا."],[13489,"(٤) التاريخ (٢/ ٧٢٠)."],[13490,"٢٢٧٧ - الجرح (٤/ ٢/ ٤٢٢) وقال: سئل أبو زرعة عن اسمه فقال: لا أعرف اسمه، تهذيب الكمال (٣/ ١٦٣٦)، المقتنى في سرد الكنى (١٠٩/ ب)، الميزان (٤/ ٥٦١)، وقال: روى عنه الافريقى حديث الوضوء لكل صلاة."],[13491,"قال البخارى: لم يتابع عليه، التهذيب (١٢/ ١٩٩ - ٢٠٠)، التقريب (٢/ ٤٦١) وقال: أبو غطيف بالتصغير، الهذلى، مجهول، من الثالثة وقيل: هو غطيف أو غضيف، بالضاد المعجمة./ ت. د. ق."],[13492,"(٥) الحديث أخرجه أبو داود \"الطهارة\" باب الرجل يجدد الوضوء من غير حدث (١/ ١٦)، والترمذى \"الطهارة\" باب ما جاء في الوضوء لكل صلاة ١/ ١٩٢، وفى باب ما جاء أنه يصلى الصلوات بوضوء واحد (١/ ١٩٦)، وابن ماجه \"الطهارة\" باب الوضوء على الطهارة (١/ ١٧٠ - ١٧١)، وابن عبد البر في الاستذكار (١/ ١٩٨)، والمزى في تهذيب الكمال (٣/ ١٦٣٦) كلهم أخرجوه من طريق عبد الرحمن بن زياد عن أبى غطيف - وعند أبى ="],[13493,"٢٢٧٨ - أبو الغازى العنسى، روى عن أبى امامة عن النبى -صلى الله عليه وآله وسلم- \"في خيار الناس\" (١). روى عنه عبد الرحمن بن زياد بن انعم الافريقى ثم الشيبانى المعافرى."],[13494,"= داود في رواية عن غطيف - عن ابن عمر مرفوعا وفيه لفظ \"من توضأ على طهر كتب اللَّه له عشر حسنات\". وقال الترمذى بعد روايته للحديث: إسناده ضعيف، وقال السندى في حاشيته على سنن ابن ماجه بعد ذكر الحديث: في الزوائد: مدار الحديث على عبد الرحمن بن زياد الافريقى، وهو ضعيف، ومع ضعفه كان يدلس. وقال البغوى في شرح السنة (١/ ٤٤٩) بعد ذكر هذا الحديث: إسناده ضعيف، ورمز السيوطى أيضا في الجامع الصغير (٢/ ١٦٩) لضعفه."],[13495,"٢٢٧٨ - الجرح (٤/ ٢/ ٤٢٢)، المقتنى في سرد الكنى (١٠٨/ ب)."],[13496,"(١) الحديث ذكره ابن أبى حاتم في الجرح (٤/ ٢/ ٤٢٢) كما هنا، وذكر الحافظ المناوى في الجامع الأزهر في حديث النبى الانور (١/ ١٢٧/ أ) حديثا لأبى أمامة قال: \"خياركم من تعلم القرآن وعلمه\" وعزاه للطبرانى في الكبير وقال: فيه على بن أبى طالب البزار ضعفه ابن معين وابن عدى."],[13497,"حرف الفاء"],[13498,"باب أبى فاطمة"],[13499,"٢٢٧٩ - أبو فاطمة بصرى، روى عن أنس عن النبى عليه السلام \"من صلى الفجر في جماعة ثم جلس في مصلاه يدعو ربه حتى تطلع الشمس كان له من الاجر مثل زبد البحر\" (١). من حديث موسى بن إسماعيل، عن القاسم بن القاسم أبى هاشم البصرى عنه."],[13500,"٢٢٧٩ - الجرح (٤/ ٢/ ٤٢٤) وذكر الحديث كما هنا. الميزان (٤/ ٥٦١) وقال مجهول. اللباب (٧/ ٩١) وقال مجهول. المقتنى في سرد الكنى (١١٠/ ب)."],[13501,"(١) الحديث لم أقف عليه من هذا الطريق ولكن أخرجه الترمذى \"الجمعة\" باب الجلوس بعد صلاة الصبح حتى تطلع الشمس، ٣/ ١٩٣ من حديث أنس قال: قال رسول اللَّه -صلى الله عليه وآله وسلم- \"من صلى الصبح في جماعة ثم قعد يذكر اللَّه حتى تطلع الشمس ثم صلى ركعتين، كانت له كأجر حجّة وعمرة\". قال: قال رسول اللَّه -صلى الله عليه وآله وسلم- \"تامة، تامة، تامة\"."],[13502,"وقال الترمذى: هذا حديث حسن غريب. وذكره المنذرى في الترغيب والترهيب (١/ ٢٣٤) وعزاه للترمذى، وللحديث شواهد في الصحيح منها ما أخرجه مسلم \"المساجد\" باب فضل الجلوس في مصلاه بعد الصبح وفضل المساجد (١/ ٤٦٣) من حديث سماك بن حرب قال: قلت لجابر ابن سمرة: أكنت تجالس رسول اللَّه -صلى الله عليه وآله وسلم-؟ قال: نعم. كثيرا. كان لا يقوم من مصلاه الذى يصلى فيه الصبح أو الغداة حتى تطلع الشمس فإذا طلعت الشمس قام. وأخرج مسلم أيضا (١/ ٤٦٤) من حديث جابر بن سمرة أن النبى -صلى الله عليه وآله وسلم- كان إذا صلى الفجر جلس في مصلاه حتى تطلع الشمس حسنا. وما أخرجه أحمد في المسند (٣/ ٤٣٩) من حديث سهل بن معاذ = ٢٢٨٠ - أبو فاطمة، روى عن ابن سيرين قوله، روى عنه أبو نعيم."],[13503,"٢٢٨١ - أبو فاطمة، روى عن أبى معشر، روى عنه الربيع بن صبيح. قال ابن أبى حاتم: سألت عنه أبى فقال: هو شتى بابة الوصّافى (١)."],[13504,"= عن أبيه عن رسول اللَّه -صلى الله عليه وآله وسلم- إنه قال من قعد في مصلاه حين يصلى الصبح حتى يسبح الضحى لا يقول إلا خيرا غفرت له خطاياه وإن كانت أكثر من زبد البحر."],[13505,"٢٢٨٠ - الجرح (٤/ ٢/ ٤٢٤)، الثقات (٧/ ٦٦١)، المقتنى في سرد الكنى (١١٠/ ب) وقال: مجهول. اللباب (٧/ ٩١) وقال: مجهول والظاهر أنهما واحد. اهـ."],[13506,"قلت: وقوله والظاهر أنهما واحد يريد بهما صاحب هذه الترجمة والمتقدم قبله الراوى عن أنس."],[13507,"٢٢٨١ - الجرح (٤/ ٢/ ٤٢٤) وقال: سألت أبى عنه فقال: شيخ بابة الوصَّافى."],[13508,"(١) قلت: والوصافى، هو عبيد اللَّه بن الوليد الوصافى من ولد الوصاف بن عامر العجلى ذكره ابن أبى حاتم في الجرح (٢/ ٢/ ٣٣٦ - ٣٣٧) وقال: قال أحمد بن حنبل: ليس بمحكم الحديث، يكتب حديثه للمعرفة. سئل عنه يحيى بن معين فقال: ضعيف الحديث. . قال عمرو بن على متروك الحديث. ثم قال ابن أبى حاتم: سألت أبى عن عبيد اللَّه بن الوليد الوصافى فقال: ضعيف الحديث، وسئل عنه أبو زرعة فقال: كوفى ضعيف. اهـ."],[13509,"باب أبى الفضل"],[13510,"٢٢٨٢ - أبو الفضل يباع الخمر (١). قال جاءنا أنس بن مالك. روى عنه الحسن بن أبى يزيد (٢)."],[13511,"٢٢٨٣ - أبو الفضل روى عن عبد اللَّه بن مسعود روى عنه جِسُر بن فرقد (٣)."],[13512,"٢٢٨٤ - أبو الفضل، قال: جاءنا كتاب عمر بن عبد العزيز إلى عدى بن أرطاة. من حديث محمد بن المثنى أبى موسى عن حماد بن بشير (٤) عنه."],[13513,"قال أبو أحمد الحاكم: قد أخرجنا أبا الفضل خلف القرشى عن كتاب عمر"],[13514,"٢٢٨٢ - الجرح (٤/ ٢/ ٤٢٤)، الميزان (٤/ ٥٦٢) وقال: مجهول. اللسان (٧/ ٩٢)، المقتنى في سرد الكنى (١١٢/ ب)."],[13515,"(١) زاد في الجرح \"والبرود\"."],[13516,"(٢) ذكره ابن أبى حاتم في الجرح (١/ ٢/ ٤٥) فقال: الحسن بن أبى يزيد الهمدانى الكوفى روى عن الشعبى وأبى الفضل بياع الخمر. . الخ ولم يذكر فيه شيئا."],[13517,"٢٢٨٣ - الميزان (٤/ ٥٦٢) وقال: مجهول. اللسان (٧/ ٩٢)، المقتنى في سرد الكنى (١١٢/ ب) وقال: أبو الفضل عن ابن مسعود وعنه جسر بن فرقد. اهـ."],[13518,"(٣) جِسْر، بكسر الجيم وبالسين المهملة، ابن فرقد، أبو جعفر القصاب، قال ابن معين: لا شئ، وقال أبو حاتم: ليس بالقوى، كان رجلا صالحا، انظر الاكمال (٢/ ١٠٠)، الجرح (١/ ١/ ٥٣٨ - ٥٣٩)، اللسان (٢/ ١٠٤)"],[13519,"٢٢٨٤ - الجرح (٤/ ٢/ ٤٢٤)، المقتنى في سرد الكنى (١١٢/ ب) وذكره بنحو ما ذكره ابن عبد البر هنا."],[13520,"(٤) حماد بن بشير الجهضمى أبو عبد اللَّه البصرى، لين الحديث، من العاشرة، التقريب (١/ ١٩٦)، التهذيب (٣/ ٤)."],[13521,"ابن عبد العزيز (١) فلا أدرى. وخليفا أن يكون واحدا. واللَّه أعلم."],[13522,"٢٢٨٥ - أبو الفضل، عن سنان بن أبى منصور (٢) مولى واثلة عن واثلة بن الأسقع قال: سمعت النبى عليه السلام يقول: \"من دفن ثلاثة من الولد يحتسبهم حرمه اللَّه على النار\" (٣)."],[13523,"(١) أخرج ابن الجوزى في سيرة عمر بن عبد العزيز (ص ٥٥ - ٥٦) من طريق سليمان بن نفيع القرشى عن خلف أبى الفضل القرشى عن كتاب عمر بن عبد العزيز إلى نفر كتبوا بالتكذيب بالقدر:"],[13524,"\"أما بعد فقد علمتم أن أهل السنة كانوا يقولون الاعتصام بالسنة نجاة وسينقص العلم نقصا سريعا. . إلخ وهو حديث طويل."],[13525,"٢٢٨٥ - الجرح (٤/ ٢/ ٤٢٤) وقال: سمعت أبى يقول: هما مجهولان أبو الفضل وسنان بن أبى منصور. الميزان (٤/ ٥٦٢) وقال: مجهول، ديوان الضعفاء (ص ٣٦٣)، اللسان (٧/ ٩٢)، المقتنى في سرد الكنى."],[13526,"(٢) سنان بن أبى منصور ذكره ابن أبى حاتم في الجرح (٢/ ١/ ٢٥٢) وقال: سنان بن أبى منصور، ويقال: ابن أبى منصور شامى مولى واثلة بن الأسقع. وذكر رواية أبى الفضل عنه. ولم يذكر فيه شيئا، لكن تقدم في ترجمة أبى الفضل في مصادر انترجمة قول أبى حاتم بأنه مجهول كما سبق وأن عرفت. وانظر ترجمته أيضا في التاريخ الكبير (٢/ ٢/ ١٦٤)."],[13527,"(٣) الحديث أخرجه الطبرانى في الكبير، عن سنان مولى واثلة قال: توفى ولد الريان وشهده واثلة فلما انصرفوا من المقبرة قعد واثلة على باب دمشق فمر به الريان فقال له واثلة: يا أبا سعيد جبر اللَّه مصيبتك وغفر لمتوفاك إنى سمعت رسول اللَّه -صلى الله عليه وآله وسلم- يقول: \"من دفن ثلاثة من الولد حرم اللَّه عليه النار\" مجمع الزوائد (٣/ ٧) وقال الهيثمى سنان مجهول. وعزاه أيضا السيوطى في الصغير (٢/ ١٧١) إلى الطبرانى في الكبير ورمز لحسنه."],[13528,"قلت: والحديث مخرج في الصحيحين من حديث غير واحد من الصحابة رضي الله عنهم كأبى هريرة وأبى سعيد الخدرى. انظر البخارى \"الجنائز\" باب فضل من مات له ولد فاحتسبه (٣/ ١١٨)، ومسلم \"البر = روى عنه أبو عبد الرحيم خالد بن أبى يزيد (١) قال أبو حاتم: أبو الفضل وسنان هذا مجهولان."],[13529,"٢٢٨٦ - أبو الفضل، روى عن نافع، روى عنه أبان المكتب (٢)."],[13530,"٢٢٨٧ - أبو الفضل. روى عن راشد بن سعد الحبرانى. روى عنه عنبسة ابن سعيد أخو أبى الربيع السمان."],[13531,"٢٢٨٨ - أبو الفضل، روى عن مكحول، روى عنه بقية بن الوليد هو عندهم مجهول."],[13532,"= والصلة\" باب فضل من يموت له ولد فيحتسبه (٤/ ٢٠٢٨ - ٢٠٣٠)."],[13533,"(١) خالد بن أبى يزيد بن سماك بن رستم أبو عبد الرحيم الحرانى، ثقة، من السادسة (ت: ١٤٤). التقريب (١/ ٢٢١)."],[13534,"٢٢٨٦ - الميزان (٤/ ٥٦٣) وقال: مجهول، ديوان الضعفاء (ص ٣٦٣)، اللسان (٧/ ٩٢)، المقتنى في سرد الكنى (١١٣/ أ)."],[13535,"(٢) ابان بن بشير المكتب. ذكره ابن أبى حاتم في الجرح (١/ ١/ ٢٩٩)، ولم يذكر فيه شيئا."],[13536,"٢٢٨٧ - الجرح (٤/ ٢/ ٤٢٥) وقال: سألت أبى عنه فقال: هو مجهول. الميزان (٤/ ٥٦٢) وقال: مجهول، اللسان (٧/ ٩٢)، المقتنى في سرد الكنى (١١٣/ أ)."],[13537,"٢٢٨٨ - الجرح (٤/ ٢/ ٤٢٥) وقال: سألت أبى عنه فقال: هو شيخ مجهول، الميزان (٤/ ٥٦٣) وقال: مجهول، اللسان (٧/ ٩٢)."],[13538,"باب أبى فروة"],[13539,"٢٢٨٩ - أبو فروة، قال على بن المدينى: أبو فروة من أصحاب عبد اللَّه وهو كنانى."],[13540,"٢٢٩٠ - أبو فروة مولى أنس بن مالك، سمع أنسا، روى عنه جرير بن حازم."],[13541,"٢٢٩١ - أبو فروة وقيل: أبو قرة مولى عبد الرحمن بن الحارث بن هشام المخزومى (١). روى عن أبى بكر الصديق."],[13542,"٢٢٩٢ - أبو فروة. روى عن عائشة أنها قالت: \"من قتل وزغة فله سبع حسنات\" (٢) روى عنه معاوية بن صالح."],[13543,"٢٢٨٩ - لم أقف له على ترجمة عند غير المؤلف."],[13544,"٢٢٩٠ - المقتنى في سرد الكنى (١١١/ أ)."],[13545,"٢٢٩١ - سيأتى في أبى قرة انظر (٢٣١٢). وذكره الذهبى في المقتنى (١١١/ أ) في أبى فروة."],[13546,"(١) له رؤية، وكان من كبار ثقات التابعين (ت: ١٤٣)./ خ. عـ. التقريب (١/ ٤٧٦)."],[13547,"٢٢٩٢ - الجرح (٤/ ٢/ ٤٢٥)، المقتنى في سرد الكنى (١١١/ أ)."],[13548,"(٢) الحديث أخرجه الطبرانى في الأوسط من حديث عائشة مرفوعا قالت: سمعت رسول اللَّه -صلى الله عليه وآله وسلم- يقول: \"من قتل وزغة محا اللَّه عنه سبع خطيئات\" كما في مجمع الزوائد (٤/ ٤٧) وقال الهيثمى: فيه عبد الكريم بن أبى المخارق وهو ضعيف. وعزاه السيوطى في الجامع الصغير (٢/ ١٧٧) أيضا للطبرانى في الأوسط من حديث عائشة رضي الله عنها ورمز لحسنه."],[13549,"وأخرجه أحمد (٦/ ٨٣ و١٠٩ و٢٠٠ و٢١٧) وابن ماجه \"الصيد\" باب قتل الوزغ (٢/ ١٠٧٦) بلفظ \"أن سائبة مولاة الفاكه بن المغيرة = ٢٢٩٣ - أبو فروة، سمع أبا ذر الغفارى، قوله، روى عنه معاوية بن صالح، قال الحاكم: أراه الذى قبله."],[13550,"= دخلت على عائشة فرأت في بيتها رمحا موضوعا فقالت: يا أم المؤمنين ما تصنعين بهذا؟ قالت: نقتل به هذه الأوزاغ إلخ وفيه أن الوزغ كان ينفخ النار على ابرإهيم عليه السلام فأمر رسول اللَّه -صلى الله عليه وآله وسلم- بقتله. وقال السندى في حاشيته على سنن ابن ماجه: في الزوائد اسناد حديث عائشة صحيح ورجاله ثقات."],[13551,"وأخرج البخارى \"بدء الخلق\" باب خير مال المسلم غنم يتبع بها شعف الجبال (٦/ ٣٥١)، ومسلم \"السلام\" باب استحباب قتل الوزغ (٤/ ١٧٥٨) وابن ماجه \"الصيد\" باب قتل الوزغ (٢/ ١٠٧٦) عن عائشة أن النبى -صلى الله عليه وآله وسلم- قال للوزغ الفويسق، ويشهد لحديث عائشة، حديث أم شريك في الصحيحين أن رسول اللَّه -صلى الله عليه وآله وسلم- أمر بقتل الوزغ وقال: كان ينفخ على إبراهيم عليه السلام انظر البخارى \"بدء الخلق\" باب خير مال المسلم غنم. . إلخ (٦/ ٣٥١) و\"الأنبياء\" (باب ﴿وَاتَّخَذَ اللَّهُ إِبْرَاهِيمَ خَلِيلًا﴾ النحل: ٢٠) (٦/ ٣٨٩)، ويشهد له أيضا حديث أبى هريرة رضي الله عنه مرفوعا أخرجه مسلم \"السلام\" باب استحباب قتل الوزغ (٤/ ١٧٥٨) والترمذى \"الصيد\" باب في قتل الوزغ (٤/ ١٧٥٨) والترمذى \"الصيد\" باب في قتل الوزغ (٥/ ٥٧) وقال: حديث حسن صحيح وفى الباب عن ابن مسعود وسعد وعائشة وأم شريك. اهـ. وأخرجه أيضا ابن ماجه \"الصيد\" باب قتل الوزغ (٢/ ١٠٧٦) بلفظ من قتل وزغة في أول ضربة فله كذا وكذا حسنة ومن قتلها في الضربة الثانية فله كذا وكذا حسنة لدون الأولى، وأن قتلها في الضربة الثالثة، فله كذا وكذا حسنة لدون الثانية هذا لفظ مسلم، وهو عنده من غير طريق عن أبى هريرة رضي الله عنه وبألفاظ متقاربة."],[13552,"٢٢٩٣ - المقتنى في سرد الكنى (١١١/ ب)."],[13553,"باب أبى فزاوة"],[13554,"٢٢٩٤ - أبو فزارة قال: سألت ابن عباس، روى عنه أبو اسحاق الهمدانى."],[13555,"٢٢٩٥ - أبو فزارة، سمع أنس بن مالك، روى عنه يعلى بن عطاء."],[13556,"٢٢٩٦ - أبو فزارة العنزى (١) وكان شيعة لعلى رضي الله عنه روى عن على. روى عنه عاصم الأحول قال ابن أبى حاتم: سمعت أبى يقول: هو شيخ ليس بالمشهور وقد ادخله البخارى في الضعفاء (٢) وليس مثله يدخل في الضعفاء ولم (. . . .) (٣) وسمعت أبى يقول: يحول من هناك."],[13557,"٢٢٩٧ - أبو فزارة العبسى (. . . . .) (٤) روى عنه الثورى. قال أبو أحمد"],[13558,"٢٢٩٤ - الجرح (٤/ ٢/ ٤٤٣)، المقتنى في سرد الكنى (١١١/ ب)."],[13559,"٢٢٩٥ - الجرح (٤/ ٢/ ٤٣٣)، المقتنى في سرد الكنى (١١١/ ب)."],[13560,"٢٢٩٦ - الجرح (٤/ ٢/ ٤٢٣)، وقال: سمعت أبى يقول: هو شيخ ليس بمشهور أدخله البخارى في كتاب الضعفاء فسمعت أبى يقول: يحول من هناك. الميزان (٤/ ٥٦٢) وقال: لينه البخارى. اللسان (٧/ ٩٢) وقال أيضا لينة البخارى. المقتنى في سرد الكنى (١١١/ ب)."],[13561,"(١) في اللسان \"العنبرى\"."],[13562,"(٢) لم أقف عليه في الضعفاء الصغير ولعله في الضعفاء الكبير. واللَّه أعلم."],[13563,"(٣) غير واضح في الأصل، وهو بمقدار كلمة أو كلمتين. ولعل العبارة كالآتى \"ولم أر من ضعفه\" واللَّه أعلم."],[13564,"٢٢٩٧ - المقتنى في سرد الكنى (١١١/ ب) وقال: أبو فزارة العبسى عن مسقلة بن مالك هو راشد. اهـ. الثقات (٧/ ٦٦١) وقال: أبو فزارة العبسى كوفى، عن رقية بن مالك روى عنه الثورى. وقال محقق الثقات في هامش نفس الورقة: إن لم يكن راشد بن كيسان العبسى أبو فزارة الكوفى فلم ندر من هو. اهـ. وقد تقدم أبو فزارة راشد بن كيسان في \"الكتاب الثانى\" (١٠٥٢)."],[13565,"(٤) بياض في الأصل بمقدار ثلاث كلمات."],[13566,"الحاكم: قد أخرجنا أبا فزارة راشد بن كيسان. روى عنه الثورى فلا أدرى أهما اثنان أو واحد. وقد جعلهما البخارى اثنين (١). وخليقا أن يكون واحدا. واللَّه أعلم."],[13567,"٢٢٩٨ - أبو الفيض (٢)، روى عن نافع، عن ابن عمر أن النبى عليه السلام شد على أصبعه خيطا يتذكر به (٣)، روى عنه عبد اللَّه بن ادريس، قال يحيى بن معين: ليس بشئ."],[13568,"٢٢٩٩ - أبو الفيض العقيلى، من بنى عقيل، روى عنه ابن أبى أنيسه (٤)."],[13569,"(١) انظر التاريخ الكبير (٢/ ١/ ٢٩٦ - ٢٩٧) في أبى فزارة العبسى راشد بن كيسان."],[13570,"٢٢٩٨ - الجرح (٤/ ٢/ ٤٢٥) وقال: قال يحيى بن معين: ليس بشئ. الميزان (٤/ ٥٦٣) وقال: قال ابن معين: ليس بشئ. اللسان (٧/ ٩٤) وقال: اسمه سالم بن عبد الأعلى."],[13571,"(٢) هكذا ذكر المؤلف أبا الفيض بعد أبى فزارة مباشرة، ولم يعنون له في باب كما هى عادته. واللَّه أعلم."],[13572,"(٣) الحديث لم أقف عليه من حديث ابن عمر: وقد أخرجه الطبرانى في المعجم الكبير كما في مجمع الزوائد (١/ ١٦٦) من حديث رافع بن خديج قال: رأيت في يد رسول اللَّه -صلى الله عليه وآله وسلم- خيطا فقلت: ما هذا؟ قال استذكر به. وقال الهيثمى: في سنده غياث بن إبراهيم وهو ضعيف جدا. اهـ."],[13573,"٢٢٩٩ - المقتنى في سرد الكنى (١١٣/ ب)."],[13574,"(٤) في المقتنى \"زهير بن أبى أنيسة\"."],[13575,"باب الافراد الكنى الشتى"],[13576,"٢٣٠٠ - أبو فراس (١) النهدى قال: شهدت خطبة عمر بن الخطاب (٢). روى عنه أبو نضرة. قال الحاكم: قال اسحاق بن راهويه: أبو فراس هذا هو الربيع بن زياد الحارثى (٣) وما أظن اسحاق حفظ ذلك أن كان سمعه وربما سماه"],[13577,"٢٣٠٠ - الجرح (٤/ ٢/ ٤٢٣) وقال: سئل أبو زرعة عن أبى فراس هذا فقال: لا أعرفه، وأبو فراس الاخر يزيد بن رباح، الثقات (٥/ ٥٨٥) ديوان الضعفاء (ص ٣٦٣)، الميزان (٤/ ٥٦١) وقال: لا يعرف، اللسان (٧/ ٤٧٨) وقال: اسمه الربيع بن زياد، التهذيب (١٢/ ٢٠١) وذكره بنحو ما هنا مع ذكر هذه الأقوال فيه ثم قال: ما المانع أن يكون اسم أبى فراس النهدى أيضا الربيع بن زياد وقول اسحاق فيها \"الحارثى\" وهم، وإنما هو \"النهدى\"، التقريب (٢/ ٤٦٢) وقال: مقبول، من الثانية./ د. س."],[13578,"(١) فراس: بكسر الفاء وتخفيف الراء. الاكمال (٧/ ٥٧)."],[13579,"(٢) الخطبة أخرجها أبو داود \"الديات\" باب القود من الضربة، وقص الأمير من نفسه (٤/ ١٨٣)، والنسائى \"القسامة\" باب القصاص من السلاطين (٨/ ٣٤) وأحمد في المسند (١/ ٤١) كلهم أخرجوه من طريق سعيد بن اياس الجريرى، عن أبى نضرة، عن أبى فراس قال: خطبنا عمر بن الخطاب رضي الله عنه فقال: \"انى لم ابعث عمالي ليضربوا ابشاركم. ولا ليأخذوا أموالكم، فمن فعل به ذلك فليرفعه إلى أقصه منه، قال عمرو بن العاص: لو أن رجلا ادب بعض رعيته اتقصّه منه؟ قال: اى والذى نفسى بيده، أقصّه، وقد رأيت رسول اللَّه -صلى الله عليه وآله وسلم- من نفسه\". هذا لفظ أبى داود، وأخرجه أحمد مطولا، والنسائى بنحو هذا اللفظ."],[13580,"(٣) الربيع بن زياد الحارثى أبو فراس، مخضرم من الثانية، التقريب (١/ ٢٤٤) وانظر التهذيب (٣/ ٢٤٣)."],[13581,"من قبل نفسه (١). وقد قال خليفه بن خياط: الربيع بن زياد الحازى كنيته أبو عبد الرحمن (٢) قال: ولا أعرف لأبى نضرة رواية عن الربيع بن زياد وإنما روى عنه أبو مجلز وقتادة وقد روى عنه الشعبى خبرا ذكره عنه، وأبو فراس هذا هو النهدى والربيع بن زياد حازى وما اظن إسحاق إلا وهم. واللَّه أعلم (٣). وقد ذكره البخارى (٤) كما ذكره إسحاق، فلم يصنع شيئا."],[13582,"٢٣٠١ - أبو فِهْر (٥). قال: صلّيت خلف الزهرى شهرا فكان يقرأ ﴿تَبَارَكَ﴾ و﴿قُلْ هُوَ اللَّهُ أَحَدٌ﴾ (٦). روى عنه جرير بن عبد الحميد وجرير بن حازم."],[13583,"(١) انظر قول الحاكم في تهذيب الكمال (٣/ ١٦٣٧)."],[13584,"(٢) انظر طبقات خليفة بن خياط (ص ٢٢)."],[13585,"(٣) تهذيب الكمال (٣/ ١٦٣٧) حيث ذكر كلام الحاكم بتمامه."],[13586,"(٤) انظر التاريخ الكبير (٢/ ١/ ٢٦٨) حيث ذكر ترجمة ربيع بن زياد ولم يكنه."],[13587,"قلت: وقد فرق ابن ماكولا في الاكمال (٧/ ٥٧) بين أبى فراس عن عمر ابن الخطاب وعنه أبو نضرة. وبين أبى فراس الربيع بن زياد الحارثى."],[13588,"٢٣٠١ - الجرح (٤/ ٢/ ٤٢٥)، المقتنى في سرد الكنى (١١٣/ أ)، اللسان (٧/ ٩٣) وقال: ذكره الحاكم أبو أحمد فيمن لا يعرف اسمه وذكر عن البخارى أنه قال: حدثنا جرير بن حازم عن أبى فهر صليت. . فذكره، وأخرج الخطيب في كتابه من طريق ابن غسان عن جرير عن أبى فهر قال: صليت خلف الزهرى. . مثله. وزاد \"في صلاة الفجر\" وزاد \"قيل لجرير من أبو فهر؟ قال: لعن كان يسكن الرى. فقيل له: يروى عن اللصوص؟ قال: نعم كان مع بعض السلاطين وجرير هذا هو ابن عبد الحميد فكان كلا الجريرين رويا عن أبى فهر، ولم أر له ذكرا إلا في هذا الأثر\". اهـ. وانظر أيضا الكفاية ص ١٥٣."],[13589,"(٥) فهر: بكسر الفاء وآخره راء. الاكمال (٧/ ٧٧)."],[13590,"(٦) الأثر أخرجه البخارى في الكنى، والحاكم في الكنى والخطيب في التاريخ كما في اللسان (٧/ ٩٣)، وأخرجه أيضا أبو نعيم في الحلية (٣/ ٣٧٠) وابن ="],[13591,"٢٣٠٢ - أبو فرقد (١) سمع أبا موسى الاشعرى. روى عنه مرزوق بن عمرو (٢)."],[13592,"٢٣٠٣ - أبو الفرج (٣)، مولى عمر بن عبد العزيز، روى عن عمر بن عبد العزيز حكايات كثيرة، قال ابن أبى حاتم: سمعت أبا زرعة يقول: قدم علينا الرى شيخ يقال له: أبو الفرج مولى عمر بن عبد العزيز. فكان يحدث عن عمر ابن عبد العزيز حكايات كثيرة وكان يكذب (٤)."],[13593,"٢٣٠٤ - أبو الفضة، سمع أنس بن مالك عن النبى عليه السلام قال: لعقبة ابن أبى معيط: \"لاقتلنك. قال: من بين قريش؟ قال: نعم تذكر يوم وطئت على عنقى\" (٥). روى عنه أبو سعيد مولى بنى هشام."],[13594,"= أبى حاتم في الجرح (٤/ ٢/ ٤٢٥) كلهم أخرجوه من طريق جرير عن أبى فهر به."],[13595,"٢٣٠٢ - الجرح (٤/ ٢/ ٤٢٥)، المقتنى في سرد الكنى (١١١/ أ)."],[13596,"(١) فرقد: أوله فاء وآخره، دال مهملة، الاكمال (٧/ ٦٢)."],[13597,"(٢) مرزوق بن عمرو، ذكره ابن أبى حاتم في الجرح (٤/ ١/ ٢٦٥) فقال: مرزوق ابن عمرو أبو حكيم جد ريحان بن سعيد الناجى، وذكر روايته عن أبى فرقد ولم يذكر فيه شيئا."],[13598,"٢٣٠٣ - الجرح (٤/ ٢/ ٤٢٦)، ديوان الضعفاء (ص ٣٦٣)، الميزان (٤/ ٥٦١) وقال: قال أبو زرعة: كان يكذب. اللسان (٧/ ٩٢)."],[13599,"(٣) فرج: بالفتحات والجيم، الاكمال (٧/ ٥٥)."],[13600,"(٤) انظر الجرح (٤/ ٢/ ٤٢٦)."],[13601,"٢٣٠٤ - الجرح (٤/ ٢/ ٤٢٦)، المقتنى في سرد الكنى (١١٣/ أ)، اللسان (٧/ ٩٣) وقال: مجهول."],[13602,"(٥) الخبر أخرجه الواقدى في المغازى (١/ ١١٤) بنحوه وذكر ابن قتيبة في المعارف (ص ١٥٥) أن الرسول -صلى الله عليه وآله وسلم- قتل عقبة بن أبى معيط بالصفراء بعد معركة بدر. وفى طبقات ابن سعد (٢/ ١٨) أنه قتله صبرا بالصفراء. ="],[13603,"٢٣٠٥ - أبو الفرات، روى عن عبد اللَّه بن مسعود، ما أخاف عليكم الفقر ولكنى أخاف عليكم الغنى (١)، روى عنه فضيل بن غزوان، (قال أبو أحمد"],[13604,"= وأخرج ابن إسحاق وموسى بن عقبة كما في البداية والنهاية (٣/ ٣٠٥ - ٣٠٦) من طريق حماد بن سلمة عن عطاء بن السائب عن الشعبى قال: لما أمر رسول اللَّه -صلى الله عليه وآله وسلم- بقتل عقبة قال: اتقتلنى يا محمد من بين قريش؟ قال: \"نعم. اتدرون ما صنع هذا بى؟ جاء وأنا ساجد خلف المقام فوضع رجله على عنقى وغمزها فما رفعها حتى ظننت أن عينى ستندران، وجاء مرة أخرى بسلا شاة فألقاه على رأسى وأنا ساجد فجاءت فاطمة فغسلته عن رأسى. أهـ."],[13605,"قلت: وقصة وضع السلى على ظهره -صلى الله عليه وآله وسلم- وهو ساجد في الصحيحين. انظر البخارى \"الوضوء\" باب إذا القى على ظهر المصلى قذر أو جيفة لم تفسد عليه صلاته (١/ ٣٤٩) ومسلم \"الجهاد والسير\" باب ما لقى النبى -صلى الله عليه وآله وسلم- من أذى المشركين والمنافقين (٣/ ١٤١٨ - ١٤٢٠)."],[13606,"٢٣٠٥ - المقتنى في سرد الكنى (١١٠/ ب) وقال: أبو الفرات قال عبد اللَّه، ما الفقر أخاف عليكم وعنه فضيل بن غزوان كأنه شداد أهـ."],[13607,"(١) الحديث لم أقف عليه من حديث ابن مسعود بهذا اللفظ، لكن ذكر الهيثمى في مجمع الزوائد في كتاب \"الزكاة\" (٣/ ١٢٢) حديثا عن ابن مسعود يرفعه \"أن هذا الدينار والدرهم اهلكا من كان قبلكم ولا أراهما إلا مهلكاكم\" وقال الهيثمى: رواه الطبرانى في الكبير، وفيه يحيى بن المنذر وهو ضعيف. ثم ذكر الهيثمى أيضًا في مجمع الزوائد كتاب \"الزهد\" (١٠/ ٢٣٧) حديثا عن ابن مسعود انه كان يعطى الناس عطاءهم فجاءه رجل فأعطاه الف درهم ثم قال: خذها فافنى سمعت رسول اللَّه -صلى الله عليه وآله وسلم- يقول: \"أنما أهلك من كان قبلكم الدينار والدرهم وهما مهلكاكم\" وقال الهيثمى: رواه البزار واسناده جيد."],[13608,"ويشهد للحديث حديث أبى هريرة رضي الله عنه أخرجه أحمد (٢/ ٣٠٨، ٥٣٩) قال: قال -صلى الله عليه وآله وسلم- ما أخشى عليكم الفقر ولكن أخشى عليكم ="],[13609,"الحاكم: وقد روى فضيل بن غزوان) (١)، عن شداد (بن أبى العالية أبى الفرات) (٢)، عن أبى داود الاحمرى، عن حذيفة، فلا أدرى أهما اثنان أو واحد. (. . . . . . . . .) (٣) فضيل بن غزوان، وربما ارسل أبو الفرات حديثه، عن عبد اللَّه وهما واحد. واللَّه أعلم."],[13610,"= التكاثر وما أخشى عليكم الخطأ ولكن أخشى عليكم العمد\". وقال الهيثمى في مجمع الزوائد (٣/ ١٢١، ١٠/ ٢٣٦) رجال أحمد رجال الصحيح."],[13611,"وحديث عمرو بن عوف أخرجه أحمد (٤/ ١٣٧، ٣٢٧) وقال الهيثمى في مجمع الزوائد (٣/ ١٢١، ١٠/ ١٣٧) رجاله رجال الصحيح، وأخرجه أيضا البخارى \"الجزية\" باب الجزية والموادعة مع أهل الحرب (٦/ ١٥٧) وفى \"المغازى\" (٧/ ٣٢٠) وفى \"الرقاق\" باب ما يحذر من زهرة الدنيا والتنافس فيها (١١/ ٢٤٣)."],[13612,"والترمذى \"القيامة\" وصححه (٧/ ١٦١)، وابن ماجه \"الفتن\" باب فتنة المال (٢/ ١٣٢٤) كلهم أخرجوه من حديث عمرو بن عوف مرفوعا وللحديث عندهم قصة وفيه \"فواللَّه لا الفقر أخشى عليكم ولكن أخشى عليكم أن تبسط عليكم الدنيا كما بسطت على من قبلكم فتنافسوها، كما تنافسوها وتهلككم كما أهلكتهم\" اللفظ للبخارى."],[13613,"وحديث عقبة بن عامر وأبى سعيد الخدرى رضي الله عنهما أخرجه البخارى \"الرقاق\" باب ما يحذر من زهرة الدنيا (١١/ ٢٤٤) بنحوه."],[13614,"(١) الحق في هامش الأصل. كتب عنده \"صح أصل\"."],[13615,"(٢) في الأصل غير واضح وهو في ترجمة أبى داود الاحمرى المتقدم في (٦٦٩) وفى ترجمة أبى الفرات شداد بن أبى العالية المتقدم في (١٠٤٨) كما أثبته هنا. واللَّه أعلم."],[13616,"(٣) في الأصل بياض بمقدار كلمة أو كلمتين."],[13617,"حرف القاف"],[13618,"باب أبى القاسم"],[13619,"٢٣٠٦ - أبو القاسم، مولى زينب بنت جحش، روى عن زينب بنت جحش، روى عنه (١)."],[13620,"٢٣٠٧ - أبو القاسم الحمصى، روى عن عمرو بن قيس السّكونى، روى عنه سعيد بن أبى أيّوب."],[13621,"٢٣٠٨ - أبو القاسم الضرير، روى عن عبد العزيز بن (٢) الماجشون. روى عنه محمد بن حرب النَّشائى (٣)."],[13622,"٢٣٠٦ - الجرح (٤/ ٢/ ٤٢٦)، كنى ابن منده، المقتنى في سرد الكنى (٥/ أ)."],[13623,"(١) هكذا قال ابن عبد البر هنا \"روى عنه\" ولم يذكر من روى عنه وفى الجرح ذكر أنه روى عنه حدمر. وفى الجرح (١/ ٢/ ٣١٧) ذكر ابن أبى حاتم حدمر مولى بنى عبس روى عن أبى القاسم مولى زينب روى عنه ليث بن أبى سليم. وانظر التاريخ الكبير (٢/ ١/ ١٣١). والكنى لابن منده (٨/ ب)."],[13624,"٢٣٠٧ - الجرح (٤/ ٢/ ٤٢٦)، كنى ابن منده، المقتنى في سرد الكنى (٥/ أ)."],[13625,"٢٣٠٨ - الجرح (٤/ ٢/ ٤٢٧) وقال: سئل أبو زرعة عنه فقال: لا أدرى من هو منكر الحديث. الميزان (٤/ ٥٦٣)، اللسان (٧/ ٩٤)، كنى ابن منده (٨/ ب) وقال: أبو القاسم الضرير المكتب جار عبيدة بن حميد."],[13626,"(٢) زاد في اللسان \"أبى سلمة الماجشون\"."],[13627,"(٣) صدوق، من العاشرة (ت: ٢٥٥). والنشائى: بفتح النون والشين وبعد الألف ياء تحتها نقطتان نسبة إلى النشا واشتهر بهذه النسبه أبو عبد اللَّه محمد بن حرب الواسطى انظر التقريب (٢/ ١٥٣) اللباب (٣/ ٣٠٩)."],[13628,"٢٣٠٩ - أبو القاسم بن أبى الزناد، أخو عبد الرحمن بن أبى الزناد، روى عن إسحاق بن حازم (١)، وافلح بن حميد، وإبراهيم بن إسماعيل بن أبى حبيبة (٢)، روى عنه أحمد بن حنبل، وسعيد بن يحيى بن سعيد الأموى (٣). ذكر أبو بكر الأثرم (٤) قال: سمعت أحمد بن حنبل ذكر أبا القاسم ابن أبى الزناد فأثنى عليه وقال: كتبنا عنه وهو شاب (٥). وقال عباس: سئل يحيى بن معين عن أبى القاسم بن أبى الزناد فقال: ليس به بأس قد سمع منه أحمد (٦). سئل أبو زرعة عن أبى القاسم بن أبى الزناد فقال: (ليس به بأس قد سمع منه أحمد) (٧) سئل أبو زرعة عن أبى القاسم بن أبى الزناد فقال: اسمه كنيته لا"],[13629,"٢٣٠٩ - كنى مسلم (ص ٨٢٠)، كنى الدولابى (٢/ ٨٦)، الجرح (٤/ ٢/ ٤٢٧) تاريخ بغداد (١٤/ ٣٩٨) وقال: قال سعيد بن يحيى بن سعيد الأموى سألته عن اسمه فقال: اسمى كنيتى. قلت: وسيأتى قول أبى زرعة أيضا بنحو هذا في نهاية الترجمة. التهذيب (١٢/ ٢٠٣)، التقريب (٢/ ٤٦٣) وقال: ليس به بأس من التاسعة./ ق."],[13630,"(١) اسحاق بن حازم. وقيل: ابن أبى حازم، البزاز المدنى، صدوق، تكلم فيه للقدر، من السابعة. التقريب (١/ ٥٧)."],[13631,"(٢) مدنى ضعيف من السابعة (ت: ١٦٥). التقريب (١/ ٣١)."],[13632,"(٣) بغدادى، ثقة، ربما أخطأ، من العاشرة (ت: ٢٤٩)، التقريب (١/ ٣٠٨)."],[13633,"(٤) أبو بكر الأثرم: واسمه أحمد بن محمد بن هانئ، من أصحاب أحمد بن حنبل، وهو من أهل اسكاف بنى جنيد، له من الكتب كتاب السنن في الفقه على مذهب أحمد وشواهده من الحديث وكتاب التاريخ، وكتاب العلل وكتاب الناسخ والمنسوخ في الحديث. انظر الفهرست لابن النديم (ص ٣٢٠ - ٣٢١)."],[13634,"(٥) انظر الجرح (٤/ ٢/ ٤٢٧)، تاريخ بغداد (٤/ ١/ ٣٩٩)."],[13635,"(٦) التاريخ (٢/ ٧٢٠)."],[13636,"(٧) ليس في مطبوعة الجرح، والظاهر أنه سبق قلم من الناسخ، إذ الملاحط أنه ="],[13637,"يعرف له اسم."],[13638,"= كلام ابن معين السابق، وقد كرره الناسخ. واللَّه أعلم."],[13639,"وكلام أبى زرعة في الجرح كالاتى \"قال: هو أخو عبد الرحمن بن أبى الزناد، اسمه كنيته، لا يعرف له أسم\"."],[13640,"باب أبى قرة"],[13641,"٢٣١٠ - أبو قرّة (١)، روى عن سلمان، روى عنه أبو إسحاق السبيعى، حديثه في الكوفيين."],[13642,"٢٣١١ - أبو قرة، مولى بنى أبى جهل بن هشام، روى عن أبى هريرة، روى عنه أبو الأسود محمد بن عبد الرحمن يتيم عروة."],[13643,"٢٣١٢ - أبو قرة مولى عبد الرحمن بن الحارث بن هشام. قال: قسم لى أبو بكر. روى عنه (٢)."],[13644,"٢٣١٠ - كنى مسلم (ص ٨٢٥)، كنى ابن منده (٢٠٢/ أ)، الثقات (٥/ ٥٨٧) المقتنى في سرد الكنى (١١٤/ ب)."],[13645,"(١) في الثقات زيادة \"الكندى\"."],[13646,"٢٣١١ - الجرح (٤/ ٢/ ٤٢٨)."],[13647,"٢٣١٢ - تقدم أبو قرة هذا في أبى فروة. وقال ابن عبد البر في ترجمته هناك (٢٢٩١): أبو فروة. وقيل: أبو قرة. وذكر روايته عن أبى بكر الصديق رضي الله عنه. وانظر ترجمة أبى قرة أيضا في الجرح (٤/ ٢/ ٤٢٧)، المقتنى في سرد الكنى (١١٤/ ب). وذكره ابن عبد البر أيضا في الاستيعاب (٤/ ١٥٧) في حرف الفاء فقال: أبو فروة مولى عبد الرحمن بن هشام كان مسلما على عهد رسول اللَّه -صلى الله عليه وآله وسلم-، ذكر الواقدى عنه أنه قال: قسم أبو بكر قسما فقسم لى كما قسم لمولاى. اهـ. وذكره ابن حجر في الإصابة (٤/ ١٦٠) فقال: أبو قرة مولى عبد الرحمن بن الحارث بن هشام المخزومى. . ويقال: أبو فروة بفتح الفاء وسكون الراء بعدها واو، ثم ذكر قول ابن عبد البر في الاستيعاب وقال: أوره أبو عمر في حرف الفاء، واورده أبو أحمد الحاكم في حرف القاف وهو أولى. اهـ."],[13648,"(٢) هكذا قال ابن عبد البر هنا \"روى عنه\" ولم يسم الراوى عنه وكذا هو في الجرح لابن أبى حاتم."],[13649,"٢٣١٣ - أبو قرة الاسدى، الصيداوى (١)، من أهل البادية، سمع سعيد بن المسيب، روى عنه النضر بن شميل."],[13650,"٢٣١٤ - أبو قرة، سمع عطاء، روى عنه المبارك بن (حسان) (٢)."],[13651,"٢٣١٥ - أبو قرة بصرى، روى عن ابن سيرين، روى عنه يزيد بن ميمون (٣)."],[13652,"٢٣١٦ - أبو قرة العبسى بصرى سمع الحسن بن أبى الحسن. وسمع عروبة العابد، روى عنه الضحاك بن مخلد أبو عاصم."],[13653,"٢٣١٣ - كنى مسلم (ص ٨٢٥)، الجرح (٤/ ٢/ ٤٢٧)، المقتنى في سرد الكنى (١١٤/ ب)، الميزان (٤/ ٥٦٤) وقال: حدث ببلد صيدا، مجهول، تفرد عنه النضر بن شميل، اللسان (٧/ ٤٧٩) وقال: مجهول، التهذيب (١٢/ ٢٠٦) وقال: قال ابن خزيمة: لا أعرفه بعدالة ولا جرح - التقريب (٢/ ٤٦٤) وقال: مجهول، من السادسة./ ت."],[13654,"(١) الصيداوى: نسبة إلى صيدا وهى مدينة على ساحل بحر الشام. انظر اللباب (٢/ ٢٥٣)."],[13655,"قلت: وصيداء، بالفتح ثم السكون ودال مهملة. انظر مراصد الاطلاع (٢/ ٨٥٩)."],[13656,"٢٣١٤ - الجرح (٤/ ٢/ ٤٢٧)، المقتنى في سرد الكنى (١٢١٤/ ب)."],[13657,"(٢) في الأصل غير واضح، وهو في الجرح، والمقتنى كما أثبته والمبارك بن حسان السلمى أبو يونس أو أبو عبد اللَّه البصرى، نزيل مكة، لين الحديث من السابعة. التقريب (٢/ ٢٢٧)، الجرح (٤/ ١/ ٣٤٠)."],[13658,"٢٣١٥ - الجرح (٤/ ٢/ ٤٢٨)."],[13659,"(٣) ذكره ابن أبى حاتم في الجرح (٤/ ٢/ ٢٩٠) فقال: يزيد بن ميمون قال: نا أبو قرة أنه سأل محمد بن سيرين عن دم البراغيث، روى عنه أبو سلمة. . . سمعت أبى يقول: هو مجهول."],[13660,"٢٣١٦ - الجرح (٤/ ٢/ ٤٢٧)، المقتنى في سرد الكنى (١١٤/ ب)."],[13661,"٢٣١٧ - أبو قرة قال: خرج عمر بن عبد العزيز، روى عنه أبو بكر النصرى (١)."],[13662,"٢٣١٧ - المقتنى في سرد الكنى (١١٤/ ب)."],[13663,"(١) أبو بكر النصرى، هو المتقدم في الترجمة (١٣٧٧) وذكر ابن عبد البر في ترجمته هناك أنه روى عن أبى قرة."],[13664,"باب أبى قبيصة"],[13665,"٢٣١٨ - أبو قَبِيصة (١)، روى عن الحسن، روى عنه الدراوردى، وسعيد بن أبى أيوب."],[13666,"٢٣١٩ - أبو قبيصة. روى عن عطاء (٢). روى عنه أُمَىَّ (٣) الصيرفى."],[13667,"٢٣٢٠ - أبو قبيصة، عن أنس بن سيرين (٤)، حدث عنه المسيب بن شريك التميمى (٥)."],[13668,"٢٣١٨ - الجرح (٤/ ٢/ ٤٢٨)، الثقات (٧/ ٦٦٢). المقتنى في سرد الكنى (١١٣/ ب)."],[13669,"(١) قبيصة: بمفتوحة كسر موحدة واهمال صاد. المغنى (ص ٦٢)."],[13670,"٢٣١٩ - الجرح (٤/ ٢/ ٤٢٨)."],[13671,"(٢) في الجرح \"طارق\"."],[13672,"(٣) أمى، الصيرفى، هو ابن ربيعة الصيرفى أبو عبد الرحمن، كوفى روى عن الشعبى وأبى قبيصة وعطاء وطاووس وأبى الهيثم صاحب القصب روى عنه جميع وأبو نعيم، وثقة أحمد، وابن معين وقال أبو حاتم: ما به بأس."],[13673,"الجرح (١/ ١/ ٣٤٧)، وفى التقريب (١/ ٨٣): أمى بالتصغير، وقال أيضا: ثقة، من السابعة."],[13674,"٢٣٢٠ - المقتنى في سرد الكنى (١١٣/ ب)."],[13675,"(٤) أنس بن سيرين. وهو أخو محمد، ثقة، من الثالثة (ت: ١١٨) وقيل (١٢٠)، التقريب (١/ ٨٤)."],[13676,"(٥) المسيب بن شريك التميمى أبو سعيد، ذكره ابن أبى حاتم في الجرح (٤/ ١/ ٢٩٤) وقال: سألت أبى عن المسيب بن شريك فقال: ضعيف الحديث كأنه متروك."],[13677,"٢٣٢١ - أبو قبيصة العنزى بصرى، روى عن يزيد بن زريع، روى عنه عمرو ابن على الصيرفى، قال ابن أبى حاتم: نا عمرو بن على قال: سمعت أبا قبيصة العنزى وكان من الثقات."],[13678,"٢٣٢١ - الجرح (٤/ ٢/ ٤٢٨) وقال: سمعت أبى قال: سمعت عمرو بن على يقول: سمعت أبا قبيصة العنزى وكان من الثقات. اهـ."],[13679,"باب أبى قتادة"],[13680,"٢٣٢٢ - أبو قتادة، روى عن الأوزاعى، وليس هو بأبى قتادة الحرانى سكن بغداد، سمع منه يحيى بن معين، منكر الحديث."],[13681,"٢٣٢٣ - أبو قتادة الشامى، وليس بالحرانى أيضا، سمع عبد اللَّه بن جراد (١)."],[13682,"٢٣٢٢ - تاريخ ابن معين (٢/ ٧٢٠ - ٧٢١) وقال: ليس بشئ، وقال أيضا: كان شيخ عند درب أبى الطيب، يروى عن الأوزاعى، وكان يقول: حدثنا أبو عمرو -رحمه الله- فذهبنا إليه، واختلفنا إليه، فقعدنا يوما في الشمس، فذهبنا ننظر، فإذا في أعلى الصحيفة، حدثنا إسماعيل بن عبد اللَّه بن سماعة، عن الأوزاعى، قال: فطرحنا صحيفته، وتركناه، وكانت كنيته أبو قتادة، وليس هو أبا قتادة الحرانى، كان رجلا آخر. اهـ. تاريخ بغداد (٤/ ٤٠١)، المقتنى في سرد الكنى (١١٣/ ب) وقال: متروك، الميزان (٤/ ٥٦٤)، اللسان (٧/ ٩٧)."],[13683,"٢٣٢٣ - كنى البخارى (ص ٦٤)، المقتنى في سرد الكنى (١١٣/ ب)، اللسان (٧/ ٩٧)."],[13684,"(١) هكذا في الأصل \"عبد اللَّه بن جراد\" وفى كنى البخارى \"حوار\" وفى الجرح (٣/ ٢/ ٢١) عبد اللَّه بن جراد، روى عن النبى -صلى الله عليه وآله وسلم-، روى عنه يعلى ابن الاشدق. . قال أبى: عبد اللَّه بن جراد لا يعرف، ولا يصح هذا الاسناد أهـ. وقال ابن عساكر: عبد اللَّه بن جراد بن المنتفق بن عامر بن عقيل العقيلى يقال: أن له صحبة. انظر تهذيب تاريخ دمشق (٧/ ٣٢٦) وذكره الذهبى في التجريد (١/ ٣٠٢) فقال: روى عنه يعلى بن الاشدق، وأبو قتادة الشامى، وقال البخارى له صحبة. وذكره البخارى في التاريخ الكبير (٣/ ١/ ٣٥) وقال: عبد اللَّه بن جراد له صحبة قال لى أحمد بن الحارث، حدثنا أبو قتادة الشامى ليس بالحرانى، مات سنة أربع وستين ومائة. وذكره ="],[13685,"مات سنة أربع وستين ومائة، روى عنه أحمد بن الحارث الغسّانى (١)."],[13686,"٢٣٢٤ - أبو قتادة، صاحب عمرو بن على الباهلى الصيرفى، سمع عاصما الكُوْزى (٢)."],[13687,"= ابن حبان في الصحابة من كتاب الثقات (٣/ ٢٤٤) وقال: يقال: أن له صحبة، روى عنه يعلى بن الاشدق مات سنة أربع وستين ومائة، وليست صحبته عندى بصحيحه. اهـ."],[13688,"قلت: وظاهر أن قول ابن حبان في عبد اللَّه بن جراد أنه مات سنه أربع وستين ومائة خطأ فهذا صحابى وإنما الذى مات في هذه السنة إنما هو أبو قتادة الراوى عن ابن جراد، وقد نبه الحافظ ابن حجر في الإصابة (٢/ ٢٨٨) على هذا الخطأ فقال بعد أن ذكر كلام البخارى المتقدم في عبد اللَّه بن جراد: وذهل ابن حبان فأرخ وفاة عبد اللَّه بن جراد سنة (١٦٤) وطعن لأجل ذلك في صحبته، وكأنه اشتبه عليه كلام البخارى، والبخارى إنما قصد بيان وفاة أبى قتادة الراوى عن عبد اللَّه بن جراد ليميز بينه وبين الحرانى. وقال ابن حجر في اللسان (٣/ ٢٦٦ - ٢٦٧) في ترجمة عبد اللَّه بن جراد، ذكره في الصحابة أبو عيسى الترمذى، ويعقوب بن سفيان والبرقى، والبلاذرى، وابن سلام، والبزار، والازدى، وأبو نعيم، وابن منده، وابن قانع، وابن زبر، وأبو جعفر، وأبو القاسم الطبرانى، وابن الجوزى وغيرهم."],[13689,"(١) أحمد بن الحارث الغسانى، ذكره ابن أبى حاتم في الجرح (١/ ١/ ٤٧) وقال: سألت أبى عنه فقال: متروك."],[13690,"٢٣٢٤ - المقتنى في سرد الكنى (١١٣/ ب)."],[13691,"(٢) الكوزى كما في اللباب (٣/ ١١٧) بضم اولها وسكون الواو وفى آخرها الزاى - نسبة إلى الكوز وعرف بها أبو محمد ويقال: أبو شعيب عاصم بن سليمان التيمى الكوزى العبدى البصرى. وقال في الجرح (٣/ ١/ ٣٤٤) في ترجمة الكوزى هذا: سمعت أبى يقول: أبو شعيب التميمى اسمه عاصم بن سليمان الكوزى ضعيف الحديث متروك الحديث. اهـ."],[13692,"باب أبى قدامة"],[13693,"٢٣٢٥ - أبو قدامة العمرى، سمع عائشة بنت سعد، روى عنه أبو عامر العقدى، وهشام بن عبيد اللَّه الرازى، وإسماعيل بن أبى اويس."],[13694,"٢٣٢٦ - أبو قدامة الرملى، روى عن عبد العزيز بن قرير (١)، عن الحسن حديثا منكرا. رواه عنه منصور بن عمار (٢)."],[13695,"٢٣٢٥ - أبو قدامة العمرى هذا هو المتقدم في الكتاب الثانى في الترجمة (١٠٥٥) وقال ابن عبد البر في ترجمته هناك: أبو قدامة العمرى عثمان بن محمد بن عبيد اللَّه بن عبد اللَّه بن عمر بن الخطاب ثم ذكره كما هنا."],[13696,"٢٣٢٦ - الميزان (٤/ ٥٦٤) وقال: مجهول وأتى بخبر منكر، اللسان (٧/ ٩٨) وقال: مجهول بخبر منكر، المقتنى في سرد الكنى (١١٤/ أ)."],[13697,"(١) عبد العزيز بن قرير، بضم القاف وفتح الراء الأولى وآخره راء أيضا مصغرا، بصرى، ثقة، من السادسة. انظر التقريب (١/ ٥١١)، الجرح (٢/ ٢/ ٣٩٢)، الاكمال (٧/ ١٠٨)."],[13698,"(٢) منصور بن عمار، ذكره ابن أبى حاتم في الجرح (٤/ ١/ ١٧٦) وقال: سئل أبى عن منصور بن عمار فقال: ليس بالقوى، صاحب مواعظ."],[13699,"باب أبى قيس"],[13700,"٢٣٢٧ - أبو قيس (١) مولى عمرو بن العاص، روى عنه بسر بن سعيد الحضرمى، وعلى بن رباح، ويزيد بن أبى حبيب، حديثه في أهل مصر."],[13701,"٢٣٢٨ - أبو قيس الدمشقى، عن عبادة بن نسى، روى عنه أبو معاوية الضرير حديثا ليس بالقائم قال الحاكم: وخليقا أن يكون محمد بن سعيد المصلوب."],[13702,"٢٣٢٧ - كنى البخارى (ص ٦٤)، الثقات (٥/ ٥٧١ و٥/ ٥٩٠) ذكره ابن حبان في موضعين في كنى الثقات فقال في الموضع الأول: أبو قيس مولى عمرو بن العاص، يروى عن عمرو بن العاص، روى عنه بشر بن سعيد، وقال في الموضع الاخر: أبو قيس مولى عمرو بن العاص، روى عنه على بن رباح، وأهل الشام. فكأنه جعله رجلين. والصحيح أن الترجمتين لرجل واحد كما هو ملاحظ. واللَّه أعلم، فتوح مصر (ص ٢٥٠) و(ص ٢٢٧ - ٢٢٨) التهذيب (١٢/ ٢٠٧)، التقريب (٢/ ٤٦٤) وقال: اسمه عبد الرحمن بن ثابت، وقيل: ابن الحكم، وهو غلط، ثقة، من الثانية مات قديما سنة (٥٤)."],[13703,"(١) في التهذيب زيادة \"السهمى\"."],[13704,"٢٣٢٨ - كنى البخارى (ص ٦٤)، الميزان (٤/ ٥٦٤) وقال: أبو قيس الدمشقى، عن عبادة بن نسى، أظنه المصلوب، هالك، اللسان (٧/ ٩٨) وقال أيضا: أظنه المصلوب، هالك، التهذيب (١٢/ ٢٠٧) وقال: هو محمد بن سعيد المصلوب هكذا كناه أبو معاوية. اهـ."],[13705,"باب أفراد شتى في الكنى"],[13706,"٢٣٢٩ - أبو قحذم (١)، رأى أبا بكرة صاحب رسول اللَّه -صلى الله عليه وآله وسلم- روى عنه منصور بن زاذان."],[13707,"٢٣٣٠ - أبو قابوس، مولى عبد اللَّه بن عمرو بن العاص مكى، روى عن عبد اللَّه بن عمرو بن العاص، روى عنه عمرو بن دينار."],[13708,"٢٣٣١ - أبو القعقاع الجرمى (٢). روى عن عبد اللَّه بن مسعود روى عنه سلمة بن تمَّام (٣) والحجاج بن ارطاة ذكر أبو أحمد الحاكم قال: ذكر البخارى"],[13709,"٢٣٢٩ - كنى البخارى (ص ٦٤)، الجرح (٤/ ٢/ ٤٢٩)، المقتنى في سرد الكنى (١١٤/ أ)."],[13710,"(١) قحذم: بفتح القاف والذال المعجمتين. هكذا ضبطه ابن ماكولا في الاكمال (٧/ ١٠١)."],[13711,"٢٣٣٠ - كنى البخارى (ص ٦٤)، الجرح (٤/ ٢/ ٤٢٩)، الثقات (٥/ ٥٨٨)، الميزان (٤/ ٥٦٣) وقال: لا يعرف، تفرد عنه عمرو بن دينار، وذكر خبره \"الراحمون يرحمهم الرحمن\"، اللسان (٧/ ٤٧٩)، التهذيب (١٢/ ٢٠٣) وقال: ذكره البخارى في الضعفاء من الكبير له، ولكنه ذكره في الأسماء فقال: قابوس. أهـ. التقريب (٢/ ٤٦٣) وقال: مقبول من الرابعة./ د. ت."],[13712,"٢٣٣١ - كنى البخارى (ص ٦٤)، كنى مسلم (ص ٨٣١) وقال: أبو القعقاع الجرمى عبد اللَّه بن خالد، نسبه ابن أبى شيبة منقطع."],[13713,"(٢) في كنى البخارى \"الحرامى\"."],[13714,"(٣) سلمة بن تمام، بفتح التاء المثناة من فوقها، وتشديد الميم الشَّقَرى بفتح المعجمة والقاف، ذكره ابن أبى حاتم في الجرح (٢/ ١/ ١٥٧) وذكر روايته عن أبى القعقاع الجرمى، وقال: سمعت أبى يقول: سلمة بن تمام، ثقة صدوق، لا بأس به. وانظر التقريب (١/ ٣١٦)، تبصير المنتبه (١/ ٢٠٣)."],[13715,"أبا القعقاع في موضعين في التاريخ الكبير، فسماه مرة، وكناه ونسبه إلى أبيه وقبيلته ولم يبين عمن روى ولا من روى عنه (١) وأخرجه في الكنى المجردة (٢) فذكر كنيته ولم يذكر اسمه ولا قبيلته، فدل على أنه (عنده) (٣) غير الأول، وما أراه إلا رجلا واحدا. واللَّه أعلم."],[13716,"٢٣٣٢ - أبو القمّاص (٤)، روى عن على رضي الله عنه أنه ذكر فتنة التنزيل (٥)، حديثه عند الثورى عن أبيه عن سلمة (شيخ للحى) (٦) عن حَرِيز (٧)."],[13717,"(١) الذى في التاريخ الكبير (٣/ ١/ ٧٧)، إنما هو عبد اللَّه بن خالد أبو القعقاع الجرمى، هكذا ذكره البخارى. وقال: نسبه ابن أبى شيبة منقطع."],[13718,"(٢) انظر كنى البخارى (ص ٦٤)."],[13719,"(٣) الحق في هامش الأصل."],[13720,"٢٣٣٢ - كنى البخارى (ص ٦٤)، الجرح (٤/ ٢/ ٤٢٩)، المقتنى في سرد الكنى (١١٤/ ب) وقال: مجهول."],[13721,"(٤) القمّاص، في الاكمال (٧/ ٧٩): قمّاص، أوله قاف، بعده ميم وآخره صاد مهملة أهـ. وضبطه بفتح القاف وتشديد الميم."],[13722,"(٥) ومثله في كنى البخارى والجرح، وزاد في البخارى قال \"نا أبو نعيم عن سفيان عن أبيه عن سلمة شيخ للحى عن جرير عن أبى القماص قال: ذكر على فتنة التنزيل حتى لو كان رجل من أهل الحق في أهل الباطل عليه كذا وكذا من حديد صار إلى أهل الحق، ولو كان رجل من أهل الباطل في أهل الحق كان عليه كذا وكذا من حديد صار إلى أهل الباطل أهـ."],[13723,"(٦) في الأصل \"الشيخ المحق\" والمثبت عن مصادر الترجمة، وقال ابن أبى حاتم في الجرح (٢/ ١/ ١٧٨) عن أبيه \"سلمة شيخ للحى روى عن حريز وليس بابن عثمان روى عنه سعيد بن مسروق."],[13724,"(٧) حريز، أوله حاء مهملة مفتوحة وراء مكسورة وآخره زاى ذكره ابن أبى حاتم في الجرح (١/ ٢/ ٢٨٩)، والبخارى في التاريخ الكبير (٢/ ١/ ١٠٣) وابن ماكولا في الاكمال (٢/ ٨٦) وذكروا روايته عن أبى القماص وعنه سلمة شيخ للحى ولم يذكروا فيه شيئا."],[13725,"قال الحاكم: أظنه والد غزوان بن جرير (١)."],[13726,"٢٣٣٣ - أبو قَنَان (٢)، مصرى، عن أبى فراس، روى عنه عمرو بن الحارث المصرى، يعد في أهل مصر."],[13727,"٢٣٣٤ - أبو قيلة (٣)، المعافرى. سمع عمر بن الخطاب. روى عنه عبد الرحمن بن (جبريل) (٤)."],[13728,"(١) غزوان بن جرير الضبى مولاهم الكوفى، مقبول، من السادسة. التقريب (٢/ ١٠٥) وذكر البخارى في التاريخ الكبير (٢/ ١/ ١٠٣) وابن أبى حاتم في الجرح (١/ ٢/ ٢٨٩) وابن ماكولا في الاكمال (٢/ ٨٦) في ترجمة حريز روى عن أبى القماص، قالوا: \"روى حديثه سعيد بن مسروف عن سلمة شيخ للحيى عنه\"."],[13729,"٢٣٣٣ - كنى البخارى (ص ٦٤)، المقتنى في سرد الكنى (١١٤/ ب)."],[13730,"(٢) قنان: بالفتح والنون المحففة تبصير المنتبه (٣/ ١١٣٧)."],[13731,"٢٣٣٤ - الجرح (٤/ ٤٢٨)، الثقات (٥/ ٥٩١)، المقتنى في سرد الكنى (١١٥/ أ)."],[13732,"(٣) هكذا في الأصل \"قيلة\" وفى الجرح \"قافلة\" وفى الثقات \"قتيلة\" وذكر ابن ماكولا (٧/ ١٣٠) باب قيلة بياء معجمة باثنتين من تحتها. وذكر ابن حجر في تبصير المنتبه (٣/ ١١٢٢) قتيلة، بمثناة مصغرا. جماعة ولم يذكر أبا قيلة هذا. فاللَّه أعلم بالصواب."],[13733,"(٤) هكذا في الأصل \"جبريل\" والذى في مصادر الترجمة \"حيويل\" وذكر ابن أبى حاتم في الجرح (٢/ ٢/ ٢٢٦) عبد الرحمن بن حيويل بن ناشر المعافرى، والد قرة بن عبد الرحمن، روى عن أبى قافلة المعافرى ولم يذكر فيه شيئا. فالظاهر أنه جاء الاسم في الأصل محرفا \"حيويل\" \"بجبريل\". واللَّه أعلم."],[13734,"٢٣٣٥ - أبو قُبَيْس (١). روى عن مجاهد. روى عنه ايمن بن نابل الحبشى (٢)."],[13735,"٢٣٣٥ - كنى البخارى (ص ٦٤)، الجرح (٤/ ٢/ ٤٢٩)، الثقات (٧/ ٦٦٨)، الميزان (٤/ ٥٦٣) وقال: مجهول، المقتنى في سرد الكنى (١١٣/ أ) اللسان (٧/ ٩٨) وقال: مجهول."],[13736,"(١) في كنى البخارى، والجرح، والثقات، واللسان \"أبو قبيس\"، وفى الاكمال (٦/ ٩٦) \"أبو قُبَيْس\" بضم القاف وبعدها باء معجمة بواحدة مفتوحة، وانظر تبصير المنتبه (٣/ ١١٢١)."],[13737,"(٢) ايمن بن نابل، بنون وموحدة، أبو عمران، ويقال: أبو عمرو الحبشى المكى، نزيل عسقلان، صدوق، يهم من الخامسة. انظر التقريب (١/ ٨٨)."],[13738,"حرف السين"],[13739,"باب أبى سعيد"],[13740,"٢٣٣٦ - أبو سعيد، مولى أبى أسَيد (١) مالك بن ربيعة الأنصارى، ذكر قتل عثمان، روى عنه أبو نضرة المنذر بن مالك."],[13741,"٢٣٣٧ - أبو سعيد، مولى بنى أمية عن أبى الدرداء، روى عنه عبد اللَّه بن بُجَيْر (٢)."],[13742,"٢٣٣٦ - كنى مسلم (ص ٤٣٨) وقال: شهدت مقتل عثمان، كنى الحاكم (١/ ١٨٣/ أ) وقال: ذكر قتل عثمان، وذكر أن حديثه في البصريين، الثقات (٥/ ٥٨٨)، وذكره ابن حجر في الإصابة (٤/ ٣/ ٩٩) وقال: ذكره ابن منده في الصحابة، ولم يذكر ما يدل على صحبته لكن ثبت أنه أدرك أبا بكر الصديق رضى اللَّه تعالى عنه، فيكون من أهل هذا القسم، قال ابن منده، وروى عنه أبو نضرة العبدى قصة مقتل عثمان بطولها، وهو كما قال: وقد رويناها من هذا الوجه، وليمر فيها مايدل على صحبته. اهـ. المقتنى في سرد الكنى (٦١/ ب)."],[13743,"(١) أسيد، بالتصغير. كما في الإصابة (٤/ ٩٩)."],[13744,"٢٣٣٧ - كنى البخارى (ص ٣٤)، كنى الحاكم (١/ ١٨٣/ ب). المقتنى في سرد الكنى (٦١/ ب)."],[13745,"(٢) عبد اللَّه بن بُجَيْر، بالموحدة والجيم، مصغرا بن حمران التيمى أو القيسى أبو حمران البصرى، ثقة من السادسة. التقريب (١/ ٤٠٣). وانظر الجرح (٢/ ٢/ ١٥)."],[13746,"٢٣٣٨ - أبو سعيد مولى عبد اللَّه بن عامر بن كريز القرشى (١)، روى عن أبى هريرة، روى عنه صفوان بن سليم، ومحمد بن عجلان، وداود بن قيس، وأسامة ابن زيد، والعلاء بن عبد الرحمن."],[13747,"٢٣٣٩ - أبو سعيد، مولى ابن عبد الرحمن فيما ذكره البخارى ولم يقله غيره. روى عن ابن عباس في الصلاة. حديثه عند الثورى عن فرات القزاز عنه."],[13748,"٢٣٤٠ - أبو سعيد بن أبى المعلى، سمع عليا، وأبا هريرة، سمع منه سلمة ابن وردان."],[13749,"٢٣٤١ - أبو سعيد التيمى قال: رأيت حسين بن على يطوف (وهو القصر) (٢) روى عنه عمار الدهنى."],[13750,"٢٣٣٨ - كنى البخارى (ص ٣٤)، كنى مسلم (ص ٤٣٨)، الجرح (٤/ ٢/ ٣٧٦)، كنى الحاكم (١/ ١٨٣/ ب) الثقات (٥/ ٥٨٦)، التهذيب (١٢/ ١١١)، التقريب (٢/ ٤٢٨) وقال: مقبول، من الرابعة./ م. مد. س. ق."],[13751,"(١) عبد اللَّه بن عامر بن كريز صحابى توفى سنة تسع وخمسين. التجريد (١/ ٣٢٠)."],[13752,"٢٣٣٩ - كنى البخارى (ص ٣٤)، وقال: أبو سعيد سمع ابن عباس قال محمد بن يوسف، عن سفيان، عن فرات القزار، الجرح (٤/ ٢/ ٣٧٦)، كنى الحاكم (١/ ١٨٣/ ب) وقال: أبو سعيد مولى ابن عباس، وقال: قاله محمد بن إسماعيل. المقتنى في سرد الكنى (٦١/ ب)."],[13753,"٢٣٤٠ - كنى البخارى (ص ٣٤)، الجرح (٤/ ٢/ ٣٧٥)، كنى الحاكم (١/ ١٨٣/ أ) وقال: أبو سعيد بن المعلى، ويقال ابن أبى المعلى، التهذيب (١٢/ ١٠٨)، التقريب (٢/ ٤٢٧) وقال: مقبول، من الثالثة./ ت."],[13754,"٢٣٤١ - لم أقف عليه عند غير المؤلف."],[13755,"(٢) هكذا في الأصل \"وهو القصر\"."],[13756,"٢٣٤٢ - أبو سعيد (١) مولى عبد اللَّه بن مسعود، روى عن عبد اللَّه بن مسعود، روى عنه أبو يعفور."],[13757,"٢٣٤٣ - أبو سعيد المدنى، سمع ابن عمر، روى عنه بشير بن سلمان."],[13758,"٢٣٤٤ - أبو سعيد مولى المهرى، روى عن ابن عمر، وأبى سعيد الخدرى، روى عنه يحيى بن أبى كثير، وسعيد بن أبى سعيد المقبرى، ويحيى بن أبى إسحاق البصرى، وابنه يزيد (٢) بن أبى سعيد، وعبد الرحمن بن النعمان (٣)."],[13759,"٢٣٤٢ - كنى البخارى (ص ٣٤)، الجرح (٤/ ٢/ ٣٧٦)، كنى الحاكم (١/ ١٨٣/ ب) وقال: وقد أخرجت فيما تقدم أبا سعيد مسلم سمع عبد اللَّه ابن مسعود روى عنه أبو يعفور ولا أراهما إلا واحدا. واللَّه أعلم، المقتنى في سرد الكنى (٦١/ ب)."],[13760,"(١) زاد الحاكم \"الهذلى\"."],[13761,"٢٣٤٣ - كنى البخارى (ص ٣٤)، الجرح (٤/ ٢/ ٣٧٦)، كنى الحاكم (١/ ١٨٣/ ب)، ذكره عن البخارى. وقال: قاله محمد بن إسماعيل، المقتنى في سرد الكنى (٦١/ ب)."],[13762,"٢٣٤٤ - كنى البخارى (ص ٣٥)، كنى مسلم (ص ٤٣٨)، المقتنى في سرد الكنى (٦١/ ب)، الجرح (٤/ ٢/ ٣٧٧)، كنى الحاكم (١/ ١٨٣/ ب)، الثقات (٥/ ٥٨٨)، التهذيب (١٢/ ١١١) وذكر أنه روى عنه ابناه سعيد ويزيد، التقريب (٢/ ٤٢٩)، وقال: مقبول، من الثالثة/ م. د. ت. س."],[13763,"(٢) في كنى البخارى والجرح \"سعيد\" وقد ذكر ابن حجر كما تقدم في التهذيب أنه روى عنه ابناه سعيد ويزيد. ويزيد بن أبى سعيد المدنى مولى المهرى، مقبول، من السادسة. كما قال ابن حجر في التقريب (٢/ ٣٦٥)."],[13764,"(٣) عبد الرحمن بن النعمان بن معبد الأنصارى، أبو النعمان الكوفى، صدوق ربما غلط، من السابعة. التقريب (١/ ٥٠١)."],[13765,"٢٣٤٥ - أبو سعيد صاحب الفساطيط مولى سهيل بن (ذريح) (١). سمع سمرة بن جندب. روى عنه وهب بن إسماعيل (٢)."],[13766,"٢٣٤٦ - أبو سعيد الأزدى كان امامهم (٣). رأى على بن أبى طالب. روى عنه إسماعيل بن سالم."],[13767,"٢٣٤٧ - أبو سعيد التمار (٤) المازنى الأنصارى، روى عن أبى سعيد الخدرى، روى عنه زيد بن اسلم، يعد في أهل المدينة."],[13768,"٢٣٤٨ - أبو سعيد بن عوذ البراد المكى، سمع عبد اللَّه بن الزبير بن العوام، روى عنه أبو نعيم الفضل بن دكين، ويحيى بن المتوكل، ومروان بن معاوية."],[13769,"٢٣٤٥ - كنى البخارى (ص ٣٤)، الجرح (٤/ ٢/ ٣٧٦)، كنى الحاكم (١/ ١٨٤/ أ) المقتنى في سرد الكنى (٦١/ ب)."],[13770,"(١) هكذا في الأصل \"ذريح\" ومثله في كنى البخارى، والجرح، والذى في كنى الحاكم \"ذراع\". وفى التقريب (١/ ٣٣٨) سهيل بن ذراع أبو ذراع، الكوفى مقبول، من الثالثة."],[13771,"(٢) هكذا في الأصل \"روى عنه وهب بن إسماعيل\"، وفى الجرح \"روى وهب ابن إسماعيل عن ابن أبى كبشة عنه\"، ووهب بن إسماعيل بن محمد بن قيس الاسدى، أبو محمد الكوفى، صدوق، من كبار التاسعة، كما في التقريب (٢/ ٢٣٧). وانظر الجرح (٤/ ٢/ ٢٧)."],[13772,"٢٣٤٦ - كنى ابن منده (١٣٥/ أ)، كنى الحاكم (١/ ١٨٤/ أ)، المقتنى في سرد الكنى (٦١/ ب)."],[13773,"(٣) في كنى الحاكم \"كان اماما من أئمة الازد\"."],[13774,"٢٣٤٧ - كنى البخارى (ص ٣٤)، الجرح (٤/ ٢/ ٣٧٦)، كنى الحاكم (١/ ١٨٤/ أ)، الثقات (٥/ ٥٨٦)، المقتنى في سرد الكنى (٦١/ ب)."],[13775,"(٤) زاد الحاكم \"ويقال\". وفى الثقات \"أبو سعيد اليمانى\"."],[13776,"٢٣٤٨ - كنى الحاكم (١/ ١٨٤/ أ)، كنى ابن منده (١٣٦/ ب)، المقننى في سرد الكنى (٦١/ ب)."],[13777,"٢٣٤٩ - أبو سعيد، رجل من أهل البصرة، حدث الشعبى عنه، عن عمر، روى عنه مجالد بن سعيد."],[13778,"٢٣٥٠ - أبو سعيد الأَعْسَم (١)، الاسدى كوفى، روى عن مصعب بن سعد ابن أبى وقاص، روى عنه الحجاج بن أرطاة."],[13779,"٢٣٥١ - أبو سعيد الازدى، الشّنوى (٢) من ازد شنؤة بصرى، روى عن أبى هريرة، روى عنه قتادة."],[13780,"٢٣٥٢ - أبو سعيد، روى عن سعيد بن جبير، روى عنه السدى."],[13781,"٢٣٥٣ - أبو سعيد الحميرى (٣)، روى عنه. حيوة بن شريح."],[13782,"٢٣٤٩ - كنى ابن منده (١٣٦/ أ)، كنى الحاكم (١/ ١٨٤/ ب)."],[13783,"٢٣٥٠ - كنى البخارى (ص ٣٥)، كنى مسلم (ص ٤٣٨)، الجرح (٤/ ٢/ ٣٧٦)، كنى الحاكم (١/ ١٨٤/ ب) وقال: حديثه في الكوفيين. المقتنى في سرد الكنى (٦١/ ب)."],[13784,"(١) الأعْسَم: بفتح الألف وسكون العين المهملة وفتح السين المهملة وفى آخرها الميم: هو أبو عبد اللَّه محمد بن عبد اللَّه بن يزيد الاعسم. اللباب (١/ ٧٥)."],[13785,"٢٣٥١ - كنى الحاكم (١/ ١٨٤/ ب) وقال: حديثه في البصريين. الثقات (٥/ ٥٦٥)، الميزان (٤/ ٥٢٩). وقال: لا يعرف إلا برواية قتادة عنه، اللسان (٧/ ٤٦٦)، التهذيب (١٢/ ١٠٨)، التقريب (٢/ ٤٢٧) وقال: مقبول، من الثالثة./ د."],[13786,"(٢) في التهذيب \"الشنائى\"، والشنائى والشنوى. كلاهما نسبة إلى أزد شنوءة. انظر اللباب (٢/ ٢١١ - ٢١٢)."],[13787,"٢٣٥٢ - كنى البخارى (ص ٣٥)، الجرح (٤/ ٢/ ٣٧٦)، كنى الحاكم (١/ ١٨٤/ ب)، الثقات (٧/ ٦٥٧)."],[13788,"٢٣٥٣ - كنى البخارى (ص ٣٥)، الجرح (٤/ ٢/ ٣٧٦)، كنى الحاكم (١/ ١٨٤/ ب) الميزان (٤/ ٥٣٠) وقال: لا يدرى من هو، اللسان (٧/ ٤٦٦)، التهذيب (١٢/ ١٠٩) وقال: قال الحسن بن القطان: أبو سعيد هذا شامى مجهول الحال. التقريب (٢/ ٤٢٨) وقال: شامى مجهول، من الثالثة وروايته عن معاذ بن جبل مرسله./ د. ق."],[13789,"(٣) في الميزان، واللسان، والتهذيب والتقريب زيادة \"عن معاذ مرسلا\"."],[13790,"٢٣٥٤ - أبو سعيد (١) قاضى افريقية."],[13791,"٢٣٥٥ - أبو سعيد مولى جراد (٢)، روى عن عوف بن أبى جميلة، روى عنه إسحاق بن ادريس الاسوارى (٣). واسحاق ذاهب الحديث (٤)."],[13792,"٢٣٥٦ - أبو سعيد، مولى بنى تميم، عن رجل من بنى شيبة، روى عن ابن المبارك."],[13793,"٢٣٥٧ - أبو سعيد الجرُجَانى (٥)، صاحب بشر بن غياث (٦)، روى عنه"],[13794,"٢٣٥٤ - كنى البخارى (ص ٣٥)، كنى الحاكم (١/ ١٨٥/ أ)."],[13795,"(١) زاد البخارى في الكنى \"الرعينى\"."],[13796,"٢٣٥٥ - كنى الحاكم (١/ ١٨٤/ ب). المقتنى في سرد الكنى (٦١/ ب)."],[13797,"(٢) جراد بن عبس من اعراب البصرة، رُوِى عنه حديث من وجه مجهول التجريد (١/ ٨١)."],[13798,"(٣) إسحاق بن ادريس الاسوارى، ذكره ابن أبى حاتم في الجرح (١/ ١/ ٢١٣) وقال: تركه على بن المدينى. . سألت أبى عنه فقال: ضعيف الحديث، سئل أبو زرعة عنه فقال: واهى الحديث، ضعيف الحديث."],[13799,"(٤) وفى كنى الحاكم أيضا: \"واسحاق ذاهب الحديث\"."],[13800,"٢٣٥٦ - كنى البخارى (ص ٣٥)، الجرح (٤/ ٢/ ٣٧٧) وذكر أيضا أنه روى عنه الوليد بن شجاع وهشام بن عمار. وقال: سألت أبى عنه فقال: ما أرى بحديثه بأسا، كنى الحاكم (١/ ١٨٤/ ب)."],[13801,"٢٣٥٧ - كنى الحاكم (١/ ١٨٤/ ب) وقال: كناه لنا أبو العباس الثقفى عن عبيد بن عبد الواحد، المقتنى في سرد الكنى (٦١/ ب)."],[13802,"(٥) الجرجانى: بضم الجيم وسكون الراء وبالجيم المفتوحة وبالنون بعد الألف - نسبة إلى مدينة جُرْجَان وفتحها يزيد بن المهلب أيام سليمان بن عبد الملك. انظر اللباب (١/ ٢٧٠)، وانظر جُرْجَان أيضا في مراصد الاطلاع (١/ ٣٢٣)."],[13803,"(٦) بشر بن غياث المريسى، مبتدع ضال لا ينبغى أن يروى عنه ولا كرامة. انظر ترجمته في اللسان (٢/ ٢٩ - ٣١)."],[13804,"عبيد بن عبد الواحد البزار (١)."],[13805,"٢٣٥٨ - أبو سعيد البجلى، شامى، عن على بن عروة (٢)، روى عنه هشام ابن عمّار."],[13806,"٢٣٥٩ - أبو سعيد بن أخى مبشّر بن عبد اللَّه بن رَزِين (٣) حكى في مولد مبشر حكاية."],[13807,"٢٣٦٠ - أبو سعيد. روى عن خالد بن يزيد (٤) عن سعيد بن أبى هلال (٥) روى عنه معاوية بن صالح."],[13808,"٢٣٦١ - أبو سعيد، قال شهدت عروة بن الزبير، وعبد اللَّه بن عمر،"],[13809,"(١) عبيد بن عبد الواحد بن شريك البزار، ثمة صدوق (ت: ٢٨٥)، اللسان (٤/ ١٢٠)."],[13810,"٢٣٥٨ - كنى الحاكم (١/ ١٨٥/ أ)، كنى ابن منده (١٣٨/ أ)، المقتنى في سرد الكنى (٦١/ ب)."],[13811,"(٢) على بن عروة القرشى الدمشقى، متروك، من الثامنة. التقريب (٢/ ٤١) وانظر الجرح (٣/ ١/ ١٩٨)."],[13812,"٢٣٥٩ - كنى الحاكم (١/ ١٨٥/ أ) ذكره كما هنا تماما وقال: كناه لنا أبو العباس الثقفى."],[13813,"(٣) مُبَشّر بكسر المعجمة الثقيلة بن عبد اللَّه بن رَزِين، بفتح الراء كسر الزاى أبو بكر النيسابورى، ثقة، من كبار التاسعة. التقريب (٢/ ٢٢٨) التهذيب (١٠/ ٣٢)."],[13814,"٢٣٦٠ - كنى البخارى (ص ٣٥)، الجرح (٤/ ٢/ ٣٣٧)، كنى الحاكم (١/ ١٨٥/ أ)."],[13815,"(٤) هو المصرى كما صرح ابن حجر في التهذيب (٤/ ٩٥) في ترجمة سعيد ابن أبى هلال الليثى."],[13816,"(٥) زاد البخارى في الكنى \"مرسل\"."],[13817,"٢٣٦١ - كنى البخارى (ص ٣٥)، الجرح (٤/ ٢/ ٣٧٧) وقال: قال شهدت. . إلخ. كنى الحاكم (١/ ١٨٥/ أ) وذكره عن البخارى تماما."],[13818,"يتحدثان عند المقام (١). حديثه عند شعبة، عن إبراهيم بن محمد بن حاطب عنه."],[13819,"٢٣٦٢ - أبو سعيد (شهد عروة بن الزبير وعبد اللَّه بن عمر يتحدثان) (٢). عن يحيى بن أبى كثير. روى عنه محمد بن عبد الرحمن بن ثوبان."],[13820,"٢٣٦٣ - أبو سعيد عن مكحول، أن لم يكن الحبرانى فلا أدرى (٣)."],[13821,"٢٣٦٤ - أبو سعيد خادم الحسن بن أبى الحسن، روى عن الحسن، حدث عنه محمد بن مهاجر."],[13822,"(١) زاد البخارى في الكنى \"فجاء أعرابى فصلى يركع ويسجد فناداه ابن عمر لا صلاة بعد طلوع الفجر إلا ركعتين فصل بعد ذلك ما بدا لك. قلت: هكذا هو في مطبوعة الكنى \"فناداه ابن عمر لا صلاة\". . إلخ."],[13823,"قلت: والمقام المذكور هو: بالفتح، وهو الحجر الذى قام عليه إبراهيم عليه السلام حين رفع بناء البيت. وقيل: الذى قام عليه حين غسلت زوجة إسماعيل رأسه وهو موضع بالمسجد الحرام أمر اللَّه عز وجل بالصلاة عنده وهو معروف. انظر مراصد الاطلاع (٣/ ١٢٩٥)."],[13824,"٢٣٦٢ - كنى ابن منده (١٣٨/ أ)، كنى الحاكم (١/ ١٨٥/ أ)."],[13825,"(٢) هكذا في الأصل، وبالنظر إلى الترجمة السابقة نجد أن هذا القدر من الكلام هو جزء منها. وهو مقحم في هذه الترجمة اقحاما ولم يذكر ابن منده والحاكم في ترجمة أبى سعيد شيئا من هذا النص المقحم، ولعل ذكره في هذه الترجمة هو سبق قلم من الناسخ. واللَّه أعلم."],[13826,"٢٣٦٣ - الميزان (٤/ ٥٣٠) وقال: أبو سعيد، عن مكحول، وعنه عتبة بن يقظان قال الدارقطنى: مجهول، اللسان (٧/ ٤٦٦)، التهذيب (١٢/ ١١١) التقريب (٢/ ٤٢٨) وقال: مجهول، من السابعة./ ق."],[13827,"(٣) هكذا قال ابن عبد البر هنا \"أن لم يكن الحبرانى فلا أدرى\" وقد تقدم أبو سعيد الحبرانى في الكتاب الثانى (١٠٧٥) وقد فرق الذهبى وابن حجر بين أبى سعيد عن مكحول وبين أبى سعيد الحبرانى. انظر مصادر الترجمة."],[13828,"٢٣٦٤ - كنى ابن منده (١٣٦/ أ)، المقتنى في سرد الكنى (٦١/ ب)، كنى الحاكم = ٢٣٦٥ - أبو سعيد بن رافع، عم عباد بن أبى صالح (١)، روى عن (٢) ابن عباس. روى عنه عمرو بن دينار."],[13829,"٢٣٦٦ - أبو سعيد، روى عن على، روى يحيى بن مسلم بن الضحاك عن أمه عنه."],[13830,"٢٣٦٧ - أبو سعيد، روى عن أبى غالب، عن أبى أمامة عن النبى عليه السلام \"في الكرات والبصل\" (٣)."],[13831,"= (١/ ١٨٥/ أ) وذكر حديثه عن الحسن عن أبى سعيد مرفوعا \"من ابغض عمر فقد ابغضنى ومن أحب عمر فقد احبنى. وذكره الذهبى في الميزان (٤/ ٥٢٩) في أبى سعد وقال: لا يدرى من ذا وخبره باطل ثم ذكر الخبر من طريق إسماعيل بن عياش، حدثنا محمد بن مهاجر عن أبى سعد خادم الحسن، عن الحسن، عن أبى سعيد الخدرى قال: قال رسول اللَّه -صلى الله عليه وآله وسلم- من أبغض عمر فقد ابغضنى أن اللَّه باهى بالناس عشية عرفة عامة وباهى بعمر خاصة\" وقال: رواه الطبرانى في المعجم الأوسط، وتبعه ابن حجر في اللسان فذكره كما ذكره تماما. انظر اللسان (٧/ ٥١)."],[13832,"١٣٦٥ - كنى البخارى (ص ٣٥)، الجرح (٤/ ٢/ ٣٧٦)."],[13833,"(١) عباد بن أبى صالح، هو عبد اللَّه بن أبى صالح ذكوان السمان المدنى لين الحديث، من السادسة. التقريب (١/ ٤٢٣)، التهذيب (٥/ ٢٦٣)."],[13834,"(٢) في الجرح قال \"روى عن. . . \" ولم يسم أحدا."],[13835,"٢٣٦٦ - الجرح (٤/ ٢/ ٣٧٧) وقال: سألت أبا زرعة عنه فقال: لا أعرفه إلا في هذا الحديث."],[13836,"٢٣٦٧ - الجرح (٤/ ٢/ ٣٧٧) وذكر الحديث مرفوعا قال \"الكراث والبصل سك ابليس -يعنى طيبة\" وقال ابن أبى حاتم أيضا: سئل أبى عنه فقال: لا أعرفه."],[13837,"(٣) الحديث أخرجه الطبرانى في الكبير من طريق أبى غالب عن أبى امامة مرفوعا قال: \"الثوم والبصل والكراث من سكّ ابليس\" كما في مجمع الزوائد ="],[13838,"روى عنه عبد العزيز بن عبد الصمد (١)."],[13839,"٢٣٦٨ - أبو سعيد، روى عن أبى هريرة، مدنى، روى عن عبد الرحمن بن يزيد بن جابر. قال ابن أبى حاتم: سألت أبى عنه فقال: هو شيخ مدنى أدركه ابن جابر بالسّاحل لا يسمّى."],[13840,"قال ابن أبى حاتم: حديثه. قال: سمعت أبا هريرة عن النبى عليه السلام \"أن المسلم أخو المسلم لا يظلمه ولا يخذله. التقوى هاهنا\" (٢) وأشار إلى صدره."],[13841,"= (٢/ ١٨) وقال الهيثمى: فيه رجل يقال له: أبو سعيد روى عن أبى غالب وروى عنه عبد العزيز بن عبد الصمد، ولم اجد من ترجمه. اهـ. ومن الغريب أن الحافظ الهيثمى يقول: في أبى سعيد هذا: لم أجد من ترجمه، وقد ترجم له ابن أبى حاتم، وابن عبد البر. كما هو ملاحظ. ويشهد لهذا الحديث حديث جابر بن عبد اللَّه رضي الله عنه أخرجه البخارى \"الاذان\" باب ما جاء في الثوم النئ والبصل والكراث (٣/ ٣٣٩) ومسلم \"المساجد\" باب نهى من أكل ثوما أو بصلا أو كراثا أو نحوها."],[13842,"(١/ ٣٩٤ - ٣٩٥) ومن ألفاظ الحديث عندهما \"من أكل ثوما أو بصلا فليعتزلنا\". وجاء من وجه عند مسلم بلفظ: نهى رسول اللَّه -صلى الله عليه وآله وسلم- عن أكل البصل والكراث، فغلبتنا الحاجة فأكلنا منها. فقال: \"من أكل من هذه الشجرة المنتنه فلا يقربن مسجدنا، فإن الملائكة تأذى مما يتأذى منه الانس\". ومن ألفاظه أيضا عند مسلم \"من أكل من هذه البصلة الثوم، وقال مرة من أكل البصل والثوم والكراث، فلا يقربن مسجدنا فإن الملائكة تتأذى مما تتأذى منه بنو آدم\"."],[13843,"(١) عبد العزيز بن عبد الصمد العمّى، بصرى، ثقة، حافظ، من كبار التاسعة (ت: ١٨٧) ويقال: بعد ذلك. التقريب (١/ ٥١٠)، وانظر الجرح (٢/ ٢/ ٣٨٨)."],[13844,"٢٣٦٨ - الجرح (٤/ ٢/ ٣٧٥)، وقال: سألت أبى. . إلخ. وذكر أيضا الحديث. كنى ابن منده (١٣٥/ أ) وقال: أبو سعيد بن أبى سعيد جليس أبى هريرة فذكره."],[13845,"(٢) الحديث أخرجه مسلم \"البر\" - باب تحريم ظلم المسلم (٤/ ١٩٨٦) ="],[13846,"٢٣٦٩ - أبو سعيد الأموى، روى عن شعبة، كان أحمد بن حنبل يرضاه."],[13847,"= وأحمد في المسند (٢/ ٢٧٧ و٣١١ و٣٦٠) من حديث أبى هريرة رضي الله عنه لكن من رواية أبى سعيد مولى عبد اللَّه بن عامر بن كريز وهو المتقدم في (٢٣٣٨) عنه بلفظ \"لا تحاسدوا ولا تناجشوا ولا تباغضوا ولا تدابروا ولا يبع بعضكم على بيع بعض، وكونوا عباد اللَّه اخوانا، المسلم أخو المسلم لا يظلمه ولا يخذله ولا يحقره، التقوى ها هنا، ويشير إلى صدره ثلاث مرات. . إلخ وعند أحمد بنحو هذا. وأخرجه الترمذى \"البر\" باب شفقة المسلم على المسلم (٦/ ٥٤) بنحو هذا اللفظ لكن من طريق أبى صالح عن أبى هريرة. وقال الترمذى: هذا حديث حسن غريب. ويشهد للحديث حديث ابن عمر مرفوعا بنحو حديث أبى هريرة أخرجه البخارى \"المظالم\" - باب لا يظلم المسلم المسلم ولا يسلمه (٥/ ٩٧)، وفى \"الاكراه\" باب يمين الرجل لصاحبه أنه أخوه (١٢/ ٣٢٣) وأخرجه أيضا أحمد في المسند (٢/ ٦٨) وأيضا يشهد له حديث واثلة بن الاسقع مرفوعا بنحوه عند أحمد (٣/ ٤٩١) وحديث الحسن عن رجل من بنى سليط مرفوعا بنحوه وهو عند أحمد أيضا (٤/ ٦٦ و٦٩) (٥/ ٢٤ و٢٥ و٧١ و٣٧٩ و٣٨١)."],[13848,"٢٣٦٩ - الجرح (٤/ ٢/ ٣٧٧) وقال: سمعت أبى يقول: كان أحمد بن حنبل يرضاه."],[13849,"باب أبى سلمة"],[13850,"٢٣٧٠ - أبو سلمة، روى عن النبى عليه السلام مرسلا انه قال \"ان الشيطان قال: لا ينجو منى صاحب المال\" (١) الحديث."],[13851,"٢٣٧١ - أبو سلمة الخوّاص الواسطى، روى عن ثابت البنانى، وابان بن أبى عياش (٢)، وأيوب السختيانى، روى عنه الحسن بن خلف البزار (٣). حديثه ليس بالقائم."],[13852,"٢٣٧٠ - كنى الحاكم (١/ ١٩١/ أ)، المقتنى في سرد الكنى (٦٤/ ب)."],[13853,"(١) الحديث أخرجه الحاكم في الكنى بهذا اللفظ مرفوعا. والذهبى في المقتنى في سرد الكنى وقال: إسناده مظلم. وأخرج الطبرانى من حديث عبد الرحمن ابن عوف قال: قال رسول اللَّه -صلى الله عليه وآله وسلم- قال الشيطان -لعنه اللَّه- لن يسلم منى صاحب المال من احدى ثلاث اغدو عليه بهن واروح بهن أخذه من غير حله وانفاقه في غير حقه وأحبّبْه إليه فيمنعه من حقه\". انظر مجمع الزوائد (١٠/ ٢٤٥) وقال الهيثمى: إسناده حسن."],[13854,"٢٣٧١ - كنى ابن منده (١٣٢/ أ)، كنى الحاكم (١/ ١٩١) وقال: حديثه ليس بالقائم، وذكر الحديث من طريق الحسن بن خلف البزار، عن أبى سلمه الخوّاص عن أيوب السختيانى قال: حدثنى حمزة بن أنس، عن أنس مرفوعا \"من عال أختين أو ابنتين. . \" فذكر الحديث، المقتنى في سرد الكنى (٦٤/ ب) وقال: حديثه ليس بالقائم، الميزان (٤/ ٥٣٢) وقال: قال أحمد بن حنبل: حديثه ليس بالقائم، اللسان (٧/ ٥٦)."],[13855,"(٢) أبان بن أبى عياش: بصرى، متروك، من الخامسة، انظر التقريب (١/ ٣١)."],[13856,"(٣) الحسن بن خلف البزار الواسطى، هو الحسن بن شاذان، كان شاذان لقب أبيه، صدوق، له أوهام، من الحادية عشرة له عند البخارى حديث واحد (ت: ٢٤٦ هـ). التقريب (١/ ١٦٦)."],[13857,"٢٣٧٢ - أبو سلمة مولى آل (١) ربيعة. روى عن أبى هريرة عن النبى عليه السلام \"لو كان الدين معلقا بالثريا\" (٢). الحديث روى عنه إسماعيل بن جعفر."],[13858,"٢٣٧٢ - كنى البخارى (ص ٣٩)، الجرح (٤/ ٢/ ٣٨٣)، كنى الحاكم (١/ ١٩١/ أ)، المقتنى في سرد الكنى (٦٤/ ب)."],[13859,"(١) في كنى البخارى زيادة \"أبى\"."],[13860,"(٢) الحديث أخرجه البخارى في الكنى (ص ٣٩) من طريق قتيبة عن إسماعيل ابن جعفر عن أبى سلمة، عن أبى هريرة يرفعه بلفظ \"لو كان الدين عند الثريا لتناوله رجال من فارس\". ومن هذا الطريق أخرجه الحاكم في الكنى وابن أبى حاتم في الجرح به. كما في مصادر الترجمة. والحديث أخرجه البخارى في \"التفسير\" باب قوله تعالى ﴿وَآخَرِينَ مِنْهُمْ لَمَّا يَلْحَقُوا بِهِمْ﴾ الجمعة: ٣ (٨/ ٦٤١)، ومسلم \"فضائل الصحابة\" باب فضل فارس (٤/ ١٩٧٢) من حديث أبى هريرة برواية ثور عن أبى الغيث عنه قال: كنا جلوسا عند النبى -صلى الله عليه وآله وسلم- فأنزلت عليه سورة الجمعة ﴿وَآخَرِينَ مِنْهُمْ لَمَّا يَلْحَقُوا بِهِمْ﴾ قال: قلت من هم يا رسول اللَّه؟ فلم يراجعه النبى -صلى الله عليه وآله وسلم- حتى سأل ثلاثا -وفينا سلمان الفارسى، وضع رسول اللَّه -صلى الله عليه وآله وسلم- يده على سلمان- ثم قال: لو كان الايمان عند الثريا لناله رجال -أو رجل من هؤلاء. هذا اللفظ للبخارى، ولفظه عند مسلم بنحو هذا وأخرجه مسلم أيضا (٤/ ١٩٧٢) من طريق يزيد بن الاصم عن أبى هريرة قال: قال رسول اللَّه -صلى الله عليه وآله وسلم- \"لو كان الدين عند الثريا لذهب به رجل من فارس -أو يقال: من أبناء فارس حتى يتناوله\"."],[13861,"وأخرجه أيضا الطحاوى في مشكل الآثار (٣/ ٩٥) من طرق عن أبى هريرة رضي الله عنه به، والترمذى \"التفسير\" باب تفسير سورة الجمعة (٩/ ٢٠٩) من طريق عبد اللَّه بن جعفر، حدثنى ثور بن يزيد الديلى عن أبى الغيث، عن أبى هريرة به وقال: حديث غريب. ومن طريق ثور بن يزيد عن سالم أبى الغيث أخرجه ابن جرير الطبرى في التفسير (٢٨/ ٩٦)، وأخرجه السيوطى في الدر المنثور (٦/ ٢١٥) وزاد نسبته إلى سعيد بن منصور، = ٢٣٧٣ - أبو سلمة الجهنى. عن القاسم بن عبد الرحمن. روى عنه الفضيل ابن مرزوق (١). في الكوفيين."],[13862,"٢٣٧٤ - أبو سلمة بن عبد اللَّه بن عبد اللَّه بن عمر بن الخطاب وقيل أبو سلمة بن عبيد اللَّه بن عبد اللَّه بن عمر بن الخطاب. روى عن القاسم ابن محمد، ووهب بن منبه، روى عنه أبو عاصم النبيل، وحماد بن سلمة"],[13863,"= والنسائى وابن المنذر وابن مردوية وأبى نعيم، والبيهقى معا في الدلائل، عن أبى هريرة به. ولم أقف على الحديث في السنن الصغرى للنسائى ولعله في الكبرى. واللَّه أعلم. والحديث ذكره الهيثمى في مجمع الزوائد (١٠/ ٦٤) من حديث قيس بن سعد قال: قال رسول اللَّه -صلى الله عليه وآله وسلم- لو كان الايمان معلقا بالثريا لناله رجال من ابناء فارس وقال: رواه أبو يعلى والبزار والطبرانى ورجالهم رجال الصحيح. اهـ. قلت: وقد أفاض الحافظ أبو نعيم في ذكر طرف هذا الحديث في مقدمة كتابه أخبار أصبهان انظر أخبار أصبهان (١/ ٢ - ٩)."],[13864,"٢٣٧٣ - كنى البخارى (ص ٣٩)، الثقات (٧/ ٦٥٩)، كنى الحاكم (١/ ١٩١/ أ) المقتنى في سرد الكنى (٦/ ب)، الميزان (٤/ ٥٣٣) وقال: لا يدرى من هو. اللسان (٧/ ٥٦) وقال: مجهول، تعجيل المنفعة (ص ٣٢٢) وقال: قال الحسينى: مجهول."],[13865,"(١) الفضيل بن مرزوق الأغر الرقاشى، صدوق، يهم، ورمى بالتشيع، من السابعة. التقريب (٢/ ١١٣)"],[13866,"٢٣٧٤ - كنى البخارى (ص ٤٠)، وقال: أبو سلمة بن عبد اللَّه بن عبيد اللَّه بن عمر ابن الخطاب، سمع القاسم، روى عنه أبو عاصم، ثم قال: ويروى الدراوردى عن أبى سلمة بن عبيد اللَّه بن عبد اللَّه بن عمر، عن وهب بن منبه، الجرح (٤/ ٢/ ٣٨٣) وقال: أبو سلمة بن عبد اللَّه بن عبد اللَّه، وقال بعضهم: أبو سلمة بن عبيد اللَّه بن عبد اللَّه. . \" إلخ وقد فرق ابن أبى حاتم بين أبى سلمة ابن عبد اللَّه هذا وبين أبى سلمة روى عن وهب بن منبه، روى عنه حماد بن سلمة فجعلهما اثنين، وهو عند ابن عبد البر رجل واحد كما هو ملاحظ في هذه الترجمة، الثقات (٧/ ٦٦٠)، كنى ابن منده (١٣١/ ب) وقال: أبو ="],[13867,"والدراوردى قال (. . . . . . .) (١) بن عبيد اللَّه."],[13868,"٢٣٧٥ - أبو سلمة الحمصى. روى عن خالد بن معدان. روى عنه الأوزاعى ولعله سليمان بن سليم (٢)."],[13869,"٢٣٧٦ - أبو سلمة الكلاعى، عن ثوبان. روى عنه الأحوص بن حكيم، حديثه في الشاميين."],[13870,"٢٣٧٧ - أبو سلمة بن أبى بكر بن عبد الرحمن بن الحارث بن هشام"],[13871,"= سلمة بن عبد اللَّه بن عبد اللَّه بن عمر بن الخطاب، كنى الحاكم (١/ ١٩١/ أ)، وذكره كما ذكره البخارى، المقتنى في سرد الكنى (٦٤/ ب)."],[13872,"(١) في الأصل بياض بمقدار كلمتين."],[13873,"٢٣٧٥ - كنى ابن منده (١٣١/ ب)، كنى الحاكم (١/ ١٩١/ ب) ذكره بنحو ما هنا ثم قال: وقد أخرجت فيما تقدم أبا سلمة سليمان بن سليم الكنانى الحمصى، عن يحيى بن جابر الشامى، وأبى عبد اللَّه المثنى بن الصباح، روى عنه أبو عبد اللَّه محمد بن حرب الخولانى، وأبو عتبة إسماعيل بن عباس العنسى، فلا أدرى هما اثنان أم واحد، وخليقا أن يكونا اثنين لرواية هذا الثانى عن خالد بن معدان، ورواية الأوزاعى عنه. وأنه أعلى سماعا وراويا من الذى تقدم ذكرنا له، المقتنى في سرد الكنى (٦٤/ ب) الميزان (٤/ ٥٣٣) وقال: لا يعرف، اللسان (٧/ ٤٦٧) وقال: هو سليمان بن سليم الكلبى، مجهول، وثقه النسائى."],[13874,"(٢) سليمان بن سليم، قاضى حمصى، ثقة، عابد، من السابعة (ت: ١٤٧) انظر التقريب (١/ ٣٢٥)."],[13875,"٢٣٧٦ - كنى البخارى (ص ٣٩)، الجرح (٤/ ٢/ ٣٨٣)، كنى ابن منده (١٣١/ ب)، كنى الحاكم (١/ ١٩١/ ب)، المقتنى في سرد الكنى (٦٤/ ب)."],[13876,"٢٣٧٧ - كنى مسلم (ص ٤٥٩)، كنى ابن منده (١٣١/ ب)، كنى الحاكم (١/ ١٩٢/ أ)، المقتنى في سرد الكنى (٦٤/ ب). ="],[13877,"المخزومى، مدنى، روى عن أبيه، روى عنه شيبة بن نِصَاح (١)."],[13878,"٢٣٧٨ - أبو سلمة بن سفيان بن عبد الأسد المخزومى، روى عن عبد اللَّه ابن السائب (٢)، وأبى (أمية) (٣) بن الأخنس الثقفى، روى عنه محمد بن عبّاد بن جعفر (٤)، وعبد الملك بن عبد اللَّه بن أبى سفيان (٥) ويحيى بن عبد اللَّه بن محمد (٦) وعبد العزيز بن عبد اللَّه (٧)، وعمر بن عبد الرحمن بن محيصن"],[13879,"(١) شيبة بن نِصَاح، بكسر النون بعدها مهملة وآخره مهملة، مدنى، قاضى، ثقة، من الرابعة (ت: ١٣٠). انظر التقريب (١/ ٣٥٧)."],[13880,"٢٣٧٨ - كنى البخارى (ص ٣٩)، كنى الحاكم (١/ ١٩٢/ أ) المقتنى في سرد الكنى (٦٤/ ب)، التهذيب (٥/ ٢٤٠) ذكره فيمن اسمه عبد اللَّه فقال: مشهور بكنيته. وذكر روايته عن عبد اللَّه بن السائب المخزومى، وأبى أمية بن الأخنس، ورواية محمد بن عباد بن جعفر وعمر بن عبد العزيز ويحيى بن عبد اللَّه بن صيفى عنه وقال في التقريب (١/ ٤٢٠) ثقة، من الرابعة./م. د. س. ق. اهـ."],[13881,"(٢) هو عبد اللَّه بن السائب بن أبى السائب المخزومى -كما صرح بذلك الحاكم في الكنى في ترجمة أبى سلمة بن سفيان- وهو مكى، له ولأبيه صحبة وكان قارئ أهل مكة مات سنة بضع وستين وهو عبد اللَّه بن السائب قائد ابن عباس رضي الله عنهما. التقريب (١/ ٤١٧)."],[13882,"(٣) في الأصل غير واضح، والمثبت عن كنى الحاكم. والتهذيب، وأبو أمية ابن الاخنس هو المتقدم في (١٢٧٤) وذكر ابن عبد البر في ترجمته هناك انه روى عنه أبو سلمة بن سفيان."],[13883,"(٤) مكى ثقة، من الثالثة. التقريب (٢/ ١٧٤)."],[13884,"(٥) ذكره ابن أبى حاتم في الجرح (٢/ ٢/ ٣٥٤) ولم يذكر فيه شيئا."],[13885,"(٦) يحيى بن عبد اللَّه بن محمد بن يحيى بن صيفى، المكى، ثقة، من السادسة. التقريب (٢/ ٣٥٢)."],[13886,"(٧) عبد العزيز بن عبد اللَّه. ذكره ابن أبى حاتم في الجرح (٢/ ٢/ ٣٨٦) وذكر روايته عن أبى سلمة بن سفيان. ولم يذكر فيه شيئا."],[13887,"السهمى (١)."],[13888,"٢٣٧٩ - أبو سلمة، رجل من أصحاب الحديث، روى عن (حفص بن سليمان الضبعى) (٢)، (روى عنه محمد بن محبوب البصرى) (٣)، (٤)."],[13889,"٢٣٨٠ - أبو سلمة الحضرمى، رأى (٥) عبد اللَّه بن عباس، روى عنه أسحاق ابن يحيى بن طلحة ولعله أبا سلمة عبد اللَّه بن رافع الحضرمى الذى روى عن"],[13890,"(١) هو قارئ أهل مكة، ويقال: اسمه محمد، مقبول، من الخامسة (ت: ١٢٣). التقريب (٢/ ٥٩)."],[13891,"٢٣٧٩ - كنى الحاكم (١/ ١٩٢/ أ) وقال: أبو سلمة رجل من أصحاب الحديث. . . \"إلخ، المقتنى في سرد الكنى (٦٤/ ب)."],[13892,"(٢) هكذا في الأصل \"حفص بن سليمان الضبعى\" والذى في كنى ابن منده وكنى الحاكم \"جعفر بن سليمان الضبعى\" وفى الجرح (١/ ١/ ٤٨١) جعفر بن سليمان الضبعى الجرشى، البصرى أبو سليمان مولى حريش، وكان ينزل في بنى ضبيعة ولعل الصواب هو \"جعفر\" كما في مصادر الترجمة كما في الجرح. واللَّه أعلم."],[13893,"(٣) محمد بن محبوب البنانى، بضم الموحدة وخفة النون، البصرى، ثقة، من العاشرة (ت: ٢٢٣). التقريب (٢/ ٢٠٤)."],[13894,"(٤) الحق في هامش الأصل، كتب بعده \"صح أصل\"."],[13895,"٢٣٨٠ - كنى ابن منده (١٣٢/ أ)، كنى الحاكم (١/ ١٩٢/ أ) ذكره فيمن لا يعرف له اسم، وقال: وقد اخرجت فيما تقدم أبا سلمة عبد اللَّه بن رافع الحضرمى، سمع عمرو بن معدى كرب الصدفى، روى عنه جعفر بن ربيعة القرشى، ولا أراهما إلا اثنين. اهـ. وقد ذكر الحاكم أبو أحمد أبا سلمة عبد اللَّه بن رافع الحضرمى المذكور في الكنى (١/ ١٨٦/ أ)، المقتنى في سرد الكنى (٦٤/ ب)."],[13896,"(٥) في كنى ابن منده، كنى الحاكم زيادة \"قبر\" وأخرج الحاكم من طريق اسحاق بن يحيى نا أبو سلمة الحضرمى قال: \"رأيت قبر عبد اللَّه بن عباس وابن الحنفية قائم عليه\"."],[13897,"عمرو بن معدى كرب الزبيدى (١) قال أبو أحمد الحاكم: لا أراهما إلا اثنين."],[13898,"٢٣٨١ - أبو سلمة، عن أبيه (٢) قال: قدم علينا عمر بن عبد العزيز مكة (٣)، روى عنه عبد الرحمن بن مهدى."],[13899,"٢٣٨٢ - أبو سلمة، شامى، روى عن أبى مسلم الجليلى، روى عنه حريز ابن عثمان."],[13900,"٢٣٨٣ - أبو سلمة الواسطى (٤). روى عن الشعبى. روى عنه شعبة أحاديث"],[13901,"(١) عمرو بن معدى كرب الزبيدى، قال الذهبى في التجريد (١/ ٤١٨) وفد مع مراد لأنه كان فارق زبيدا ونزل في مراد. اسلم سنة تسع وارتد مع الأسود، ثم اسلم وشهد اليرموك. اهـ. وقال ابن الاثير في النهاية (٢/ ٦٠) \"الزبيدى: بضم الزاى وفتح الباء وسكون الياء المثناة من تحتها وفى آخرها دال مهملة - هذه النسبة إلى زبيد وهى قبيلة من مذحج، واسم زبيد منبه بن صعب بن سعد العشيرة بن مالك بن أدد، وإنما قيل له زبيد لأنه قال: من يزيد لمن رفده؟ وذكر أيضا انه ينسب إليها خلق كثير منهم عمرو بن معدى كرب الزبيدى وذكر أنه استشهد بنهاوند أيام عمر بن الخطاب رضي الله عنه."],[13902,"٢٣٨١ - كنى البخارى (ص ٤٠)، الجرح (٤/ ٢/ ٣٨٣)، كنى ابن منده (١٣١/ ب)، كنى الحاكم (١/ ١٩٢/ أ)."],[13903,"(٢) لم أقف عليه."],[13904,"(٣) أخرجه البخارى وأبو أحمد الحاكم وابن منده وابن أبى حاتم في الجرح كما هنا. انظر مصادر الترجمة."],[13905,"٢٣٨٢ - كنى البخارى (ص ٤٠)، الجرح (٤/ ٢/ ٣٨٣)، كنى الحاكم (١/ ١٩٢/ ب)."],[13906,"٢٣٨٣ - كنى البخارى (ص ٤٠)، كنى ابن منده (١٣١/ ب)، الجرح (٤/ ٢/ ٣٨٤) وقال: سألت أبى عنه فقال: لا يسمى وهو شيخ مجهول، كنى الحاكم (١/ ١٩٢/ ب)، الميزان (٤/ ٥٣٣)، وقال مجهول، اللسان (٧/ ٥٦) وقال: مجهول."],[13907,"(٤) زاد في الجرح \"ويعرف بالقرادى\" وفى اللباب (٣/ ٢١) القرادى بضم القاف ="],[13908,"منها خطب بلال إلى قوم من أهل اليمن (١). حديث مرسل."],[13909,"٢٣٨٤ - أبو سلمة العاملى (٢)، شامى، روى عن الزهرى، روى هشام بن عمار، عن عبد الملك بن محمد الصنعانى عنه. قال أبو حاتم: كان كذابا متروك الحديث. والحديث الذى رواه باطل."],[13910,"٢٣٨٥ - أبو سلمة، روى عن شهر بن حوشب، روى عنه عبد الصمد بن عبد الوارث، ضعفه أبو حاتم."],[13911,"٢٣٨٦ - أبو سلمة اللوذانى، روى عن أنس عن النبى عليه السلام حديثا في"],[13912,"= وفتح الراء وبعد الألف دال - هذه النسبة إلى قراد وهو لقب جد. اهـ."],[13913,"(١) أخرجه البخارى في الكنى وقال أيضا مرسل وقال: قاله ابن أبى عدى عن شعبة. وأخرجه أبو أحمد الحاكم في الكنى أيضا وعزاه للبخارى."],[13914,"٢٣٨٤ - الجرح (٤/ ٢/ ٣٨٣) وقال: سألت أبى عنه فقال: كذاب متروك الحديث. . إلخ. الميزان (٤/ ٥٣٢) وقال: اسمه الحكم بن عبد اللَّه بن خطاف، اللسان (٧/ ٤٦٧) وقال: اسمه الحكم بن عبد اللَّه بن خطاف، التقريب (٢/ ٤٣٠) وقال: متروك ورماه أبو حاتم بالكذب من السابعة./ ق."],[13915,"(٢) العاملى: بفتح العين المهملة وبعد الألف ميم مكسورة ولام هذه النسبة إلى عاملة وهو من العماليق. كذا قال السمعانى، وتعقبه ابن الاثير فقال: الصحيح أن عاملة ولد الحارث بن عدى بن الحارث بن مرة. . ونسب ولد الحارث بن عدى إلى أمهم عاملة بنت مالك بن وديعة من قضاعة. اهـ. بتصرف. انظر اللباب (٢/ ٣٦٠)."],[13916,"٢٣٨٥ - الجرح (٤/ ٢/ ٣٨٤) وقال: سألت أبى عنه فقال: ضعيف الحديث، الميزان (٤/ ٥٣٢) وقال: ضعفه أبو حاتم. اللسان (٧/ ٥٦)، كنى ابن منده (١٣١/ أ) ذكره كما هنا وسماه مروان."],[13917,"٢٣٨٦ - الجرح (٤/ ٢/ ٣٨٤)، وذكره بنحو ما هنا، وذكر حديثه."],[13918,"المؤاخاة في اللَّه (١)، حديثه عند محمد بن حميد (٢) عن الحكم بن بشير (٣) عن عمرو بن قيس الملائى عن أبى سلمة عن أنس. قال أبو عبد اللَّه محمد بن حميد: ولم يسمع أبو سلمة هذا من أنس (٤)."],[13919,"(١) الحديث أخرجه ابن أبى حاتم في الجرح من هذا الطريق بلفظ \"من أحدث أخا في اللَّه عز وجل رفعه اللَّه عز وجل بها درجة في الجنة وماتوا رجلان في اللَّه عز وجل إلا كان افضلهما منزلة عند اللَّه عز وجل اشدهما حبا لأخيه حتى يحدث احدهما، واشرهما الذى يحدث."],[13920,"(٢) صرح ابن حجر في التهذيب (٢/ ٤٢٤) في ترجمة الحكم بن بشير بأنه روى عنه محمد بن حميد الرازى، وفى التقريب (٢/ ١٥٦) محمد بن حميد ابن حيان الرازى، حافظ ضعيف، وكان ابن معين حسن الرأى فيه، من العاشرة (ت: ٢٣٠). اهـ."],[13921,"(٣) الحكم بن بشير بن سليمان النهدى، أبو محمد بن أبى إسماعيل الكوفى، صدوق، من الثامنة، / التقريب (١/ ١٩٠)."],[13922,"(٤) انظر الجرح (٤/ ٢/ ٣٨٤) في ترجمة أبى سلمة اللوذانى."],[13923,"باب أبى سعد"],[13924,"٢٣٨٧ - أبو سعد، عن ابن عمر، كوفى، روى عنه أبو إسحاق السبيعى. عمرو بن عبد اللَّه الهمدانى."],[13925,"٢٣٨٨ - أبو سعد الازدى كوفى عن عبد اللَّه بن عمرو بن العاص، روى عنه الأعمش، وزكريا بن أبى زائدة، جعلهما الحاكم رجلين (١). وجعلهما ابن أبى حاتم رجلا واحدا، وقال: روى عنه أبو إسحاق والأعمش."],[13926,"٢٣٨٩ - أبو سعد الازدى (قاضى) (٢) الازد. روى عن أبى الكنود عبد اللَّه (٣) ابن عمران الأزدى. روى عنه إسماعيل بن عبد الرحمن السدى ويزيد بن أبى"],[13927,"٢٣٨٧ - كنى الحاكم (١/ ٢٠٤/ ب)، الميزان (٤/ ٥٢٨) وقال: ما حدث عنه سوى أبى إسحاق السبيعى، اللسان (٧/ ٥١)."],[13928,"٢٣٨٨ - كنى البخارى (ص ٣٦)، كنى مسلم (ص ٤٧١)، الجرح (٤/ ٢/ ٣٧٨) الثقات (٥/ ٥٨٧) وقال: أبو سعد يروى عن ابن عمر، روى عنه الأعمش، كنى الحاكم (١/ ٢٠٥/ أ)، تعجيل المنفعة (ص ٣٢٠) وقال: هو غير أبى سعيد الأزدى الراوى عن زيد بن ارقم."],[13929,"(١) هما صاحب هذه الترجمة والذى قبله المتقدم في (٢٣٨٧)."],[13930,"٢٣٨٩ - كنى البخارى (ص ٣٦) وقال روى عن زيد بن أرقم، كنى مسلم (ص ٤٧١) الثقات (٥/ ٥٦٨)، وقال: روى عن زيد بن ارقم، كنى الحاكم (١/ ٢٠٥/ أ)، التهذيب (١٢/ ١٠٦)، وقال: أبو سعد الارحبى الكوفى قارئ الازد ويقال: أبو سعيد روى عن زيد بن ارقم وأبى الكنود وقال في التقريب (٢/ ٤٢٦) مقبول، من الثالثة./ ت. ق."],[13931,"(٢) في كنى الحاكم والتهذيب \"قارئ\"."],[13932,"(٣) في الأصل \"وعبد اللَّه بن عمران الازدى\" وبهذا يكون أبو الكنود غير عبد اللَّه ="],[13933,"٢٣٩٠ - أبو سعد الغفارى. روى عن أبى هريرة. روى عنه أبو هانى الخولانى - مصرى."],[13934,"٢٣٩١ - أبو سعد. قال: \"رأيت ابن الزبير\" (١). روى عنه سيف بن ميسرة (٢)."],[13935,"= ابن عمران الأزدى \"وليس كذلك. فأبو الكنود هو عبد اللَّه بن عمران أو ابن عويمر. كما تقدم في أبى الكنود في الكتاب الثانى (٧٥٦) ويؤيد هذا ما جاء عند الحاكم في الكنى في ترجمة أبى سعد الأزدى هذا حيث ذكر أنه روى عن أبى الكنود عبد اللَّه بن عمران الأزدى وانظر أيضا ترجمة عبد اللَّه بن عمران أبى الكنود في الجرح (٢/ ٢/ ١٢٩)."],[13936,"٢٣٩٠ - كنى البخارى (ص ٣٦)، كنى مسلم (ص ٤٧١)، كنى ابن منده (١٤١/ أ)، الجرح (٤/ ٢/ ٣٧٩)، الثقات (٥/ ٥٧٣)، وقال أبو سعد الغفارى، يروى عن أبى هريرة، روى عنه أبو هانئ الخولانى ثم ذكره مرة ثانية في نفس المجلد (ص ٥٨٢) فقال: أبو سعد مولى بنى غفار، يروى عن أبى هريرة، روى عنه أبو هانئ حميد بن هانئ الخولانى. اهـ. فيكون قد كرر نفس الترجمة في موضعين. واللَّه أعلم. كنى الحاكم (١/ ٢٠٥/ أ)، تعجيل المنفعة (ص ٣٢٠) وقال: أبو سعيد الغفارى عن أبى هريرة وذكر من ترجمه في أبى سعد بسكون العين وقال: وجدته في تاريخ ابن يونس فقال: مولى بنى غفار، روى عنه أبو هانئ وخلاد بن سليمان الحضرمى فأفاد عنه راويا آخر. اهـ. الميزان (٤/ ٥٢٨) وقال: ما حدث عنه سوى أبى هانئ الخولانى. اللسان (٧/ ٥١)."],[13937,"٢٣٩١ - كنى البخارى (ص ٣٦)، الجرح (٤/ ٢/ ٣٧٩)، كنى الحاكم (١/ ٢٠٥/ أ) كنى ابن منده (١٤١/ أ)."],[13938,"(١) ومثله في كنى الحاكم والذى في كنى البخارى والجرح \"قال: رأيت الزبير\" فاللَّه أعلم."],[13939,"(٢) سيف بن ميسرة. ذكره ابن أبى حاتم في الجرح (٢/ ١/ ٢٧٥) ولم يذكر فيه شيئا."],[13940,"٢٣٩٢ - أبو سعد (١)، عن مكحول الدمشقى، روى عنه (عبيد) (٢) بن يقظان حديثا لم يروه غيره مسندا، حدث عن مكحول، عن واثلة بن الأسقع قال: قال رسول اللَّه -صلى الله عليه وآله وسلم-: \"صلوا على أهل ملتكم ولا تكفروهم وإن ركبوا الكبائر، وجاهدوا مع كل إمام برّ وفاجر وصلوا خلفهم واغزوا مع امرائهم\" (٣) وهذا عندهم حديث لم يتابع عليه منكر."],[13941,"٢٣٩٢ - كنى ابن منده (١٤٢/ أ)، كنى الحاكم (١/ ٢٥٠/ ب) وقال: حديثه ليس من مخرج يعتمد عليه، المقتنى في سرد الكنى (٥٨/ ب) وقال: لين."],[13942,"(١) هكذا ذكره ابن عبد البر في باب أبى سعد والذى في أصول التخريج كسنن ابن ماجه والدارقطنى والعلل المتناهية \"أبو سعيد\" واللَّه أعلم."],[13943,"(٢) هكذا في الأصل \"عبيد\" وفى كنى الحاكم والمقتنى في سرد الكنى \"عتبة\" ولم أقف على من اسمه \"عبيد بن يقظان\" وذكر ابن أبى حاتم في الجرح (٣/ ١/ ٣٧٤) عتبة بن يقظان وقال: سمعت على بن الحسين بن الجنيد يقول: لا يساوى شيئا، وفى التهذيب (٧/ ١٠٣) عتبة بن يقظان الراسبى، روى عن قيس بن مسلم وأبى سعيد الشامى. اهـ. وفى التقريب (٢/ ٥) عتبة ابن يقظان، بصرى، ضعيف، من السادسة. وسيأتى في تخريج الحديث ما يدل على أن الراوى عن أبى سعد هذا إنما هو عتبة بن يقظان. لا عبيد بن يقظان. واللَّه أعلم."],[13944,"(٣) الحديث أخرجه ابن ماجه \"الجنائز\" باب في الصلاة على أهل القبلة (١/ ٤٨٨) مختصرا من طريق أحمد بن يوسف السّلمى، ثنا مسلم بن إبراهيم ثنا الحارث بن نبهان، ثنا عتبة بن يقظان عن أبى سعيد، عن مكحول، عن واثلة بن الأسقع، فال: قال رسول اللَّه -صلى الله عليه وآله وسلم- \"صلوا على كل ميت. وجاهدوا مع كل أمير\"."],[13945,"وقال السندى: في الزوائد: في إسناده عتبة بن يقظان، وهو ضعيف والحارث بن نبهان مجمع على ضعفه، وأبو سعيد هو المصلوب كذاب. اهـ. وأخرجه أيضًا الدارقطنى (٢/ ٥٧) من طريق الحارث بن نبهان عن أبى سعيد الشامى، عن مكحول، عن واثلة بن الأسقع به مرفوعا. أخرجه ابن الجوزى = ٢٣٩٣ - أبو سعد الأعمى، مكى عن أبى هريرة، روى عنه عطاء بن أبى رباح وابن جريج، يعد في أهل الحجاز."],[13946,"٢٣٩٤ - أبو سعد بن حفص بن عمر بن ثابت بن رواحة الأنصارى، حلبى، كان يسكن حلب. روى عن أبيه، وعن مسعر بن كدام، روى عنه هشام ابن عمار، والوليد بن شجاع، قال ابن أبى حاتم: سألت - عنه أبى فقال: ما أرى بحديثه بأسا."],[13947,"٢٣٩٥ - أبو سعد، روى عن أبى عون الأنصارى - عن أبى هريرة."],[13948,"= في العلل المتناهية (١/ ٤٢٥) من طريق الحارث بن نبهان فقال: نا عتبة بن يقظان، عن أبى سعيد عن مكحول عن واثله بن الأسقع قال: قال رسول اللَّه -صلى الله عليه وآله وسلم- \"لا تكفروا أهل ملتكم وإن عملوا الكبائر، وصلوا على كل إمام، وجاهدوا مع كل أمير، وصلوا على كل ميت، من أهل القبلة\" أهـ. وقال ابن الجوزى عند الكلام على هذا الحديث وطرقه في العلل (٢/ ٤٢٨) قال الدارقطنى أبو سعيد مجهول. وقال أيضًا قال العقيلى: ليس في هذا المتن إسناد يثبت، وقال الدارقطنى: ليس فيها ما يثبت إسناده، وسئل أحمد بن حنبل عن هذا الحديث صلوا خلف كل بر وفاجر. فقال: ما سمعنا بهذا. اهـ."],[13949,"٢٣٩٣ - كنى البخارى (ص ٣٦)، الجرح (٤/ ٢/ ٣٧٩)، كنى الحاكم (١/ ٢٠٥/ ب)، تعجيل المنفعة (ص ٣٢٠) وقال: أبو سعد المكى، ويقال: أبو سعيد الأعمى، الميزان (٤/ ٥٢٩) وقال: روى قصة خروج أبى أيوب إلى عقبة بن عامر، تفرد عنه ابن جريح، تهذيب الكمال (٣/ ١٦٠٨)، المقتنى في سرد الكنى (٥٨/ ب)، التهذيب (١٢/ ١٠٧)، التقريب (٢/ ٤٢٧)، وقال: مجهول، من الثالثة./ ق. الإصابة (٤/ ٤/ ٩٩)، العقد الثمين (٨/ ٤٧ - ٤٨)."],[13950,"٢٣٩٤ - الجرح (٤/ ٢/ ٣٧٩) وقال: سألت أبى عنه فقال: ما أرى بحديثه بأسًا."],[13951,"٢٣٩٥ - كنى ابن منده (١٤١/ أ)، كنى الحاكم (١/ ٢٠٥/ ب) وذكر حديثه قال: \"علمنى النبى -صلى الله عليه وآله وسلم- ادعو اللهم اجعلنى أعظم شكرك وأكثر ذكرك\". الميزان (٤/ ٥٢٨) وقال: لا يعرف، المقتنى في سرد الكنى (٥٨/ ب)."],[13952,"٢٣٩٦ - أبو سعد الجعفى (١)، أو الجرمى (٢)، روى عن يونس بن عبد اللَّه (٣)، روى عنه القاسم بن يزيد الجرمى (٤)."],[13953,"٢٣٩٧ - أبو سعد السّاعدى، روى عن أنس بن مالك، روى عنه رواد بن الجراح، لم يرو عنه غيره."],[13954,"٢٣٩٨ - أبو سعد الخزاعى، روى عن ابن ابزى حديثه (٥) عند القطان عن سفيان عن منصور عنه."],[13955,"٢٣٩٦ - كنى البخارى (ص ٣٧)، كنى الحاكم (١/ ٢٠٥/ ب)، كنى ابن منده (١٤٢/ أ)، المقتنى في سرد الكنى (٥٨/ ب)."],[13956,"(١) هكذا في الأصل \"الجعفى\" وفى كنى الحاكم \"الحنفى\"."],[13957,"(٢) ومثله في كنى الحاكم لكن قال \"الحنفى أو الجرمى\" وثقه أحمد وابن معين. كما ذكر."],[13958,"(٣) لعله يونس بن عبد اللَّه الجرمى، أحد الثقات وثقه أحمد وابن معين. كما ذكر ابن أبى حاتم في الجرح (٤/ ٢/ ٢٤١)."],[13959,"(٤) ثقة، عابد، من التاسعة (ت: ١٩٤). التقريب (٢/ ١٢١)."],[13960,"٢٣٩٧ - الجرح (٤/ ٢/ ٣٧٨) وقال: سألت أبى عنه فقال: هو مجهول، لم يرو عنه غير رواد. . سئل أبو زرعة عن اسم أبى سعد الساعدى فقال: لا أعرف اسمه. الميزان (٤/ ٥٢٨) وقال: مجهول. . حدث عنه رواد بن الجراح وليس بعمدة، حديثه رأى النبى -صلى الله عليه وآله وسلم- رجلا يتبع حمامة فقال: \"شيطان يتبع شيطانة\"، تهذيب الكمال (٣/ ١٦٠٨) التهذيب (١٢/ ١٠٦)، التقريب (٢/ ٤٢٧) وقال: مجهول، من الخامسة./ ق."],[13961,"٢٣٩٨ - كنى البخارى (ص ٣٦)، الجرح (٤/ ٢/ ٣٧٨)."],[13962,"(٥) ذكر البخارى في الكنى حديثه من طريق مسدد عن يحيى عن سفيان عن منصور عن أبى سعد الخزاعى عن ابن أبزى قال: كان النبى -صلى الله عليه وآله وسلم- يشير في الصلاة بالسبابة."],[13963,"باب أبى سليمان"],[13964,"٢٣٩٩ - أبو سليمان الليثى، عن أبى سعيد الخدرى، حديثه عند سعيد بن أبى أيّوب، عن عبد اللَّه بن الوليد (١) عنه."],[13965,"٢٤٠٠ - أبو سليمان، روى عن أبى هريرة، عن النبى عليه السلام قال (إذا وضع الميت على سريره قال: قدمونى) (٢)، (٣)، روى عنه معاوية بن صالح."],[13966,"٢٣٩٩ - كنى البخارى (ص ٣٧) وذكر حديثه من طريق عبد اللَّه بن الوليد عن أبى سليمان عن أبى سعيد مرفوعًا بلفظ \"أطعموا طعامكم الأتقياء وولوا معروفكم المؤمنين\". الجرح (٤/ ٢/ ٣٧٩)، كنى ابن منده (١٤٢/ ب) الثقات (٥/ ٥٨٥)، كنى الحاكم (١/ ١٦٤/ ب) وقال: حديثه في أهل المدينة، تعجيل المنفعة (ص ٣٢٢) وقال: قال على بن المدينى مجهول، اللسان (٧/ ٥٨)."],[13967,"(١) في كنى الحاكم زيادة \"بن قيس\"."],[13968,"٢٤٠٠ - كنى البخارى (ص ٣٧)، الجرح (٤/ ٢/ ٣٧٩)، كنى الحاكم (١/ ١٦٤/ ب)، كنى ابن منده (١٤٢/ ب)."],[13969,"(٢) في الأصل غير واضح، وهو في مصادر الترجمة كما أثبته."],[13970,"(٣) الحديث أخرجه البخارى في الكنى وابن أبى حاتم في الجرح، وابن منده في الكنى، والحاكم في الكنى من هذا الطريق مرفوعًا به. وأخرجه أيضًا أحمد في المسند (٢/ ٢٩٢ و٤٧٤ و٥٠٠) والنسائى في \"الجنائز\" باب السرعة بالجنازة (٤/ ٤٠) من حديث أبى هريرة مرفوعًا لكن من رواية عبد الرحمن بن مهران عنه بلفظ \"إذا وضع الرجل الصالح على سريرة قال: قدمونى قدمونى وإذا وضع الرجل السوء على سريره قال: يا ويله أين تذهبون بى\"."],[13971,"وأخرج البخارى \"الجنائز\" باب السرعة بالجنازة (٣/ ١٨٢) حديث أبى = ٢٤٠١ - أبو سليمان الحدّانى (١)، روى عن أنس بن مالك، روى عنه شعبة، وربما قال شعبة: سليمان أو أبو سليمان (٢)."],[13972,"٢٤٠٢ - أبو سليمان المرعشى (٣) عن كعب الأحبار قوله. روى عنه قتادة."],[13973,"٢٤٠٣ - أبو سليمان بن جبير بن مطعم بن عدى بن نوفل القرشى، أخو"],[13974,"= هريرة برواية الزهرى عن سعيد بن المسيب عنه مرفوعًا قال \"اسرعوا بالجنازة فإن تك صالحة فخير تقدمونها إليه وإن يك سوى ذلك فشر تضعونه عن رقابكم\". ويشهد لحديث أبى هريرة المتقدم حديث أبى سعيد الخدرى رضي الله عنه أخرجه البخارى \"الجنائز\" باب حمل الرجال الجنازة دون النساء (٣/ ١٨١)، وفى باب قول الميت وهو على الجنازة: قدمونى (٣/ ١٨٤) وفى باب كلام الميت على الجنازة (٣/ ٢٤٤) وأخرجه كذلك أحمد في المسند (٣/ ٤١ و٥٨) والنسائى \"الجنائز\" باب السرعة بالجنازة (٤/ ٤١) بلفظ \"إذا وضعت الجنازة فاحتملها الرجال على أعناقهم فإن كانت صالحة قالت: قدمونى قدمونى، وإن كانت غير صالحة قالت: يا ويلها أين يذهبون بها؟ يسمع صوتها كل شئ إلا الإنسان لو سمعها الإنسان لصعق\". هذا لفظ البخارى."],[13975,"٢٤٠١ - كنى البخارى (ص ٣٧)، الجرح (٤/ ٢/ ٣٨٠)."],[13976,"(١) في كنى البخارى \"الحرانى\"."],[13977,"(٢) هكذا هنا \"قال شعبة: سليمان أو أبو سليمان\" وفى كنى البخارى \"وربما قال شعبة سليمان أو أبو سليمان\"."],[13978,"٢٤٠٢ - كنى البخارى (ص ٣٧)، الجرح (٤/ ٢/ ٣٨٠)، كنى الحاكم (١/ ١٦٤/ ب)."],[13979,"(٣) المرعشى: بفتح الميم وسكون الراء وفتح العين المهملة وفى آخرها شين معجمة - هذه النسبة إلى مرعش وهى بلدة من بلاد الشام. اللباب (٣/ ١٩٦)."],[13980,"٢٤٠٣ - كنى البخارى (ص ٣٧)، كنى ابن منده (١٤٢/ ب)، الجرح (٤/ ٢/ ٣٨٠)، كنى الحاكم (١/ ١٦٤/ ب)، المقتنى في سرد الكنى (٦٦/ أ)."],[13981,"محمد (١)، ونافع، روى عن أبيه وعن سعيد بن المسيب، روى عنه يحيى بن سعيد الأنصارى (٢)، ذكر إسحاق بن منصور عن يحيى بن معين قال: أبو سليمان بن جبير بن مطعم ثقة (٣)."],[13982,"٢٤٠٤ - أبو سليمان الأزدى، سمع أبا يحيى (٤) مولى معاذ بن عفراء، روى عن ابن عباس، روى شعبة عن أبى هارون الغنوى (٥) عنه."],[13983,"٢٤٠٥ - أبو سليمان العصرى، روى عن عقبة بن صهبان عن أبى بكرة، روى عنه سعيد بن زيد أخو حماد بن زيد ذكر إسحاق بن منصور عن يحيى بن معين قال: أبو سليمان العصرى ثقة (٦)."],[13984,"٢٤٠٦ - أبو سليمان، عن زيد بن صوحان، روى عنه سلام بن مسكين."],[13985,"(١) محمد بن جبير بن مطعم بن عدى بن نوفل، النوفلى، ثقة عارف بالنسب من الثالثة. مات على رأس المائة./ التقريب (٢/ ١٥٠)."],[13986,"(٢) في كنى البخارى \"الأموى\"."],[13987,"(٣) قال ابن أبى حاتم في الجرح (٤/ ٢/ ٣٨٠) ذكره أبى عن إسحاق بن منصور عن يحيى بن معين قال: أبو سليمان بن جبير بن مطعم، ثقة."],[13988,"٢٤٠٤ - كنى البخارى (ص ٣٧)، كنى مسلم (ص ٤٤٩)، الجرح (٤/ ٢/ ٣٨٠)، كنى الحاكم (١/ ١٦٤/ ب)، كنى ابن منده (١٤٢/ ب)."],[13989,"(٤) هو الأعرج المتقدم في (١٢٢٢)."],[13990,"(٥) في كنى البخارى \"إبراهيم بن العلاء\" وهو اسم أبى هارون الغنوى وهو المتقدم في الكتاب الثانى. انظر الترجمة (١١٩٣)."],[13991,"٢٤٠٥ - كنى البخارى (ص ٣٧)، الجرح (٤/ ٢/ ٣٨٠)، كنى الدولابى (١/ ١٩٤)، كنى الحاكم (١/ ١٦٤/ ب)، المقتنى في سرد الكنى (٦٦/ أ)، التهذيب (٣/ ١٥٩)، التقريب (١/ ٢٢٧) وقال: صدوق يرسل من الرابعة."],[13992,"(٦) قال ابن أبى حاتم في الجرح (٤/ ٢/ ٣٨٠) ذكره أبى عن إسحاق بن منصور عن يحيى بن معين أنه قال: أبو سليمان العصرى ثقة."],[13993,"٢٤٠٦ - كنى البخارى (ص ٣٧)، الجرح (٤/ ٢/ ٣٨٠)، الثقات (٧/ ٦٥٩)، كنى الحاكم (١/ ١٦٥/ أ)، كنى ابن منده (١٤٢/ ب)."],[13994,"٢٤٠٧ - أبو سليمان التيمى من تيم اللَّه (١). روى عن عمر بن حبيب. روى عنه المحاربى (٢)."],[13995,"٢٤٠٨ - أبو سليمان. روى عن محمد بن إسحاق. روى عنه حفص بن ميسرة لم يعرفه أبو حاتم (٣)."],[13996,"٢٤٠٩ - أبو سليمان الفلسطينى، عن القاسم بن محمد بن أبى بكر، عن أبى إدريس الخولانى، عن أبى ذر الغفارى حديثا منكرًا طويلا في قصة الأنبياء (٤)."],[13997,"٢٤٠٧ - كنى البخارى (ص ٣٨)، الجرح (٤/ ٢/ ٣٨٠)، كنى ابن منده (١٤٣/ أ)، كنى الحاكم (١/ ١٦٥/ أ)، اللسان (٧/ ٥٧)، وقال قال الدارقطنى في العلل: مجهول."],[13998,"(١) في اللباب (١/ ٢٣٣) \"من تيم اللَّه بن ثعلبة\"."],[13999,"(٢) المحاربى: هو عبد الرحمن بن زياد، أبو محمد الكوفى، لا بأس به، وكان يدلس قاله أحمد، من التاسعة (ت: ١٩٥). انظر التقريب (١/ ٤٩٧)."],[14000,"٢٤٠٨ - الجرح (٤/ ٢/ ٣٨١)."],[14001,"(٣) هكذا قال ابن عبد البر هنا: لم يعرفه أبو حاتم. والذى في الجرح (٤/ ٢/ ٣٨١) قال ابن أبى حاتم: سئل أبو زرعة عنه فقال: لا أعرفه."],[14002,"٢٤٠٩ - كنى ابن منده (١٤٣/ أ)، كنى الحاكم (١/ ١٦٤/ ب)، المقتنى في سرد الكنى (٦٦/ أ)، الميزان (٤/ ٥٣٣)، اللسان (٧/ ٥٧)."],[14003,"(٤) الحديث أخرجه أحمد في المسند (٥/ ١٧٨ و١٧٩ و٢٦٦)، وابن حبان كما في موارد الظمآن (ص ٥٢ - ٥٤)، والبخارى في خلق أفعال العباد (ص ٤١)، وأبو داود الطيالسى في المسند (٢/ ٣١) ومحمد بن أبى عمر في مسنده كما في المطالب العالية (٣/ ١١٤) والخطابى في غريب الحديث (٢/ ١٥٧)، والبزار في صحيحه، والطبرانى في الأوسط كما في مجمع الزوائد (١/ ١٦٠ و٨/ ٢١٠) كلهم أخرجوه من طريق أبى إدريس الخولانى عن أبى ذر رضي الله عنه قال: أتيت رسول اللَّه -صلى الله عليه وآله وسلم- وهو في المسجد فجلست فقال: \"يا أبا ذر هل صليت؟ قلت: لا. قال: قم ="],[14004,"٢٤١٠ - أبو سليمان اليشكرى، مولى يحيى بن يعمر، سمع عبد اللَّه بن عباس، روى عنه أيوب السختيانى."],[14005,"٢٤١١ - أبو سليمان الخراسانى، سمع أنسا."],[14006,"٢٤١٢ - أبو سليمان الهمدانى، كوفى، روى عن أبيه (١)، عن على بن أبى طالب رضي الله عنه، روى عنه أبو جناب يحيى بن أبى حية - وقد قيل: أنه أبو سليمان أيوب بن دينار المكتب (٢). الذى روى عن أبيه عن على أنه كان لا يقبل هدّيّة النّيروز (٣)، الذى روى عنه أبو نعيم وحفص بن غياث. وقال الحاكم: خليقا أن يكونا اثنين."],[14007,"= فصل. . \" وفيه أيضًا أنه قال: يا رسول اللَّه أى الأنبياء كان أول؟ قال: آدم. قلت: يا رسول اللَّه ونبى كان؟ قال: نعم نبى مكلم\" قلت: يا رسول اللَّه كم المرسلون؟ قال: ثلاثمائة وبضعة عشر جما غفيرا. . \" الحديث وهو طويل. وقال الهيثمى بعد أن ذكر الحديث فيه المسعودى وهو ثقة."],[14008,"٢٤١٠ - كنى الحاكم (١/ ١٦٥/ أ)، المقتنى في سرد الكنى (٦٦/ أ)."],[14009,"٢٤١١ - كنى ابن منده (١٤٣/ أ)، كنى الحاكم (١/ ١٦٥/ أ) وقال: قاله محمد بن إسماعيل."],[14010,"٢٤١٢ - المقتنى في سرد الكنى (٦٦/ أ)، كنى الحاكم (١/ ١٦٥/ أ)، وقال: قد أخرجت فيما تقدم أبا سليمان أيوب بن دينار المكتب عن أبيه أن عليا كان لا يقبل هدية النيروز. روى حفص بن غياث وأبو نعيم، فلا أدرى هما اثنان أم واحد، وخليقا أن يكونا اثنين فإن الهمدانى هذا رواته أقدم من رواة أيوب بن دينار واللَّه أعلم. اهـ. الميزان (٤/ ٥٣٣) وقال: لا يدرى من هو كأبيه وأتى بخبر منكر. اللسان (٧/ ٥٧)."],[14011,"(١) لم أقف على من سماه."],[14012,"(٢) أبو سليمان أيوب بن دينار المكتب. انظر ترجمته في الجرح (١/ ١/ ٢٤٦)."],[14013,"(٣) أخرجه الحاكم في الكنى (١/ ١٦٥/ أ)، وابن تيمية في اقتضاء الصراط المستقيم مخالفة أصحاب الجحيم (ص ٢٠٠) و(ص ٢٥٠)، والذهبى في سير أعلام النبلاء في ترجمة أبى حنيفة النعمان بن ثابت (٦/ ٣٩٥) قلت: ="],[14014,"٢٤١٣ - أبو سليمان، عن عبد اللَّه بن عمرو بن العاص شامى، روى عنه خالد بن معدان."],[14015,"= والنيروز، هو يوم عيد النصارى يفرحون فيه ويصنعون فيه المأكولات والحلوى ويتبادلون فيه الزيارات والهدايا. انظر اقتضاء الصراط المستقيم (ص ١٩٩ - ٢٠٠)."],[14016,"٢٤١٣ - كنى الحاكم (١/ ١٦٥/ أ) وقال حديثه في أهل الشام، المقتنى في سرد الكنى (٦٦/ أ)."],[14017,"باب أبى سهل"],[14018,"٢٤١٤ - أبو سهل الأنصارى، سمع أبا سعيد الخدرى (يقول: حق) (١) على كل مسلم الاغتسال يوم الجمعة (٢). (رواه أبو معاوية) (٣) عن الأشعث عنه."],[14019,"٢٤١٤ - كنى الحاكم (١/ ١٩٨/ ب)، كنى ابن منده (١٤٦/ ب)، المقتنى في سرد الكنى (٦٨/ أ)."],[14020,"(١) غير واضح في الأصل والمثبت عن كنى الحاكم."],[14021,"(٢) الحديث أخرجه الحاكم في الكنى من طريق أبى معاوية عن الأشعث عن أبى سهل به وقال: قاله محمد بن إسماعيل. وأخرج البخارى \"الجمعة\" باب فضل الغسل يوم الجمعة (٢/ ٣٥٧) وفى باب هل على من لم يشهد الجمعة غسل من النساء والصبيان وغيرهم (١/ ٣٨٢) ومسلم \"الجمعة\" باب وجوب غسل الجمعة على كل بالغ من الرجال (٢/ ٥٨٠) حديث أبى سعيد الخدرى برواية عطاء بن السائب عنه مرفوعا بلفظ \"الغسل يوم الجمعة واجب على كل محتلم\". وهو عند البخارى أيضًا بلفظ \"حق على كل مسلم أن يغتسل في كل سبعة أيام يومًا يغسل فيه رأسه وجسده\". وانظر البخارى (٢/ ٣٨٢ و٦/ ٥١٥). وأخرجه أيضًا مالك \"الجمعة\" باب العمل في غسل الجمعة (١/ ١٠٢) وابن ماجه \"إقامة الصلاة والسنة فيها\" باب غسل الجمعة (١/ ٣٤٦) وأبو داود \"الطهارة\" باب غسل الجمعة (١/ ٩٤ - ٩٥). والدارمى (١/ ٣٦١) والبيهقى (١/ ٢٩٤) كلهم أخرجوه من طريق عطاء بن يسار عن أبى سعيد به."],[14022,"(٣) غير واضح في الأصل، والمثبت عن كنى الحاكم."],[14023,"٢٤١٥ - أبو سهل الدّمشقى، عن سعيد بن عبد العزيز (١). روى عنه عبد اللَّه بن خبيق بن سابق."],[14024,"٢٤١٦ - أبو سهل، كوفى، روى عن محمد بن زيد بن الخطاب (٢). روى عنه حبيب بن أبى ثابت."],[14025,"٢٤١٥ - كنى الحاكم (١/ ١٩٨/ ب)، كنى ابن منده (١٤٧/ أ) وقال: أبو سهل الدمشقى حدث عن عبد العزيز: روى عنه عبد اللَّه بن خبيق الأنطاكى، المقتنى في سرد الكنى (٦٨/ أ)."],[14026,"(١) في كنى الحاكم زيادة \"التنوخى\"."],[14027,"٢٤١٦ - كنى الحاكم (١/ ١٩٨/ ب)، المقتنى في سرد الكنى (٦٨/ أ)."],[14028,"(٢) محمد بن زيد بن عبد اللَّه بن عمر بن الخطاب، مدنى ثقة، من الثالثة التقريب (٢/ ١٦٢)."],[14029,"باب أبى سنان"],[14030,"٢٤١٧ - أبو سِنَان (١) القسملى، سمع وهب بن منبه، قوله. روى عنه جعفر ابن سليمان، قال أبو أحمد الحاكم: وليس هو عيسى بن سنان (٢)."],[14031,"٢٤١٨ - أبو سنان الغنوى، روى عن أبيه (٣)، روى عنه موسى بن إسماعيل المنقرى."],[14032,"٢٤١٩ - أبو سنان الأسلمى."],[14033,"٢٤٢٠ - أبو سنان العجلى، سمع أنس بن مالك، حدث عنه ربيعة (٤) أراه"],[14034,"٢٤١٧ - كنى الحاكم (١/ ٢٠٧/ ب) وقال: وهذا ليس بالقسملى الذى تقدم ذكرنا له وأخرجنا اسمه عيسى بن سنان. اهـ. الاكمال (٤/ ٤٤٤) والمقتنى في سرد الكنى (٦٧/ أ)، قلت: وانظر ترجمة أبى سنان عيسى بن سنان في كنى الحاكم (١/ ٢٠٧/ أ)."],[14035,"(١) سنان: بكسر السين المهملة وبنونين، الاكمال (٤/ ٤٣٩)."],[14036,"(٢) عيسى بن سنان، ويكنى أبا سنان، وهو القسملى أيضًا وهو المتقدم في الكتاب الثانى في الترجمة (١١٠٥)."],[14037,"٢٤١٨ - كنى الحاكم (١/ ٢٠٧/ ب)، كنى ابن منده (١٥٠/ أ)، المقتنى في سرد الكنى (٦٧/ أ)."],[14038,"(٣) لم أقف على من سماه."],[14039,"٢٤١٩ - كنى الحاكم (١/ ٢٠٧/ ب)، المقتنى في سرد الكنى (٦/ أ)، كنى ابن منده (١٥٠/ أ)، وقال: أبو سنان الأسلمى حدث عن على بن أبى طالب. روى عنه محمود بن لبيد. قاله البخارى."],[14040,"٢٤٢٠ - كنى الحاكم (١/ ٢٠٧/ ب)، الميزان (٤/ ٥٣٤) وقال عن أنس في السحور مجهول، كنى ابن منده (١٥٠/ أ)، المقتنى في سرد الكنى (٦٧/ أ)."],[14041,"(٤) ربيعة بن كلثوم بن جبر، بجيم وموحدة ساكنة، بصرى، صدوق، يهم من ="],[14042,"ابن كلثوم بصرى."],[14043,"٢٤٢١ - أبو سنان البكرى، روى عن عمر، روى عنه حجاج بن أرطاة."],[14044,"= السابعة، التقريب (١/ ٢٤٨)."],[14045,"٢٤٢١ - الجرح (٤/ ٢/ ٣٨٨) وقال: سئل أبو زرعة عنه فقال: لا أعرفه. كنى ابن منده (١٥٠/ أ)."],[14046,"باب أبى السوار"],[14047,"٢٤٢٢ - أبو السّوّار (١). عن خاله (٢)، (٣). روى عنه سميط بن عمير السدوسى (٤)."],[14048,"٢٤٢٣ - أبو السّوّار، السلمى، سمع أبا حاضر، روى عنه عباد بن العوام."],[14049,"٢٤٢٢ - كنى الحاكم (١/ ٢٠٨/ أ)، الميزان (٤/ ٥٣٥) وقال: لا يعرف، المقتنى في سرد الكنى (٦٨/ أ) وقال: عن خاله صحابى."],[14050,"(١) السوّار: بتشديد الواو. الاكمال (٤/ ٣٨٧)، تبصير المنتبه (٢/ ٦٩٩)."],[14051,"(٢) هكذا في الأصل عن خاله وكذا في مصادر الترجمة. ولم أقف على من سمى خاله."],[14052,"(٣) في كنى الحاكم زيادة \"قال: رأيت النبى -صلى الله عليه وآله وسلم-\"."],[14053,"(٤) سميط بن عمير، ويقال: ابن سمير، السدوسى البصرى، أبو عبد اللَّه، صدوق، من الثالثة. انظر التقريب (١/ ٣٣٤)."],[14054,"٢٤٢٣ - الجرح (٤/ ٢/ ٣٨٨)، كنى الحاكم (١/ ٢٠٨/ ب) ذكره كما هنا وقال: قاله محمد بن إسماعيل. قلت: ولم أقف عليه في الكنى المجردة للبخارى، تعجيل المنفعة (ص ٣٢٣)، المقتنى في سرد الكنى (٦٨/ أ)."],[14055,"باب أبى سفيان"],[14056,"٢٤٢٤ - أبو سفيان بن سعد (١) بن الأخنس بن شريق الثقفى ابن أخت أم حبيبة، زوج النبى عليه السلام، روى عن خالته أم حبيبة، روى عنه أبو سلمة بن عبد الرحمن بن عوف."],[14057,"٢٤٢٥ - أبو سفيان مولى ابن - أحمد بن جحش (٢) والصواب مولى ابن"],[14058,"٢٤٢٤ - كنى مسلم (ص ٤٦٥)، المقتنى في سرد الكنى (٦٢/ ب) وقال: أبو سفيان ابن المغيرة بن الأخنس يروى عن خالته أم حبية روى عنه الزهرى، الميزان (٤/ ٥٣١) وقال: ما روى عنه سوى أبى بن عبد الرحمن، التهذيب (١٢/ ١١٢)، التقريب (٢/ ٤٢٩) وقال: مقبول، من الثالثة./ عـ. س."],[14059,"(١) في التهذيب \"سعيد بن المغيرة\"."],[14060,"٢٤٢٥ - كنى البخارى (ص ٣٩)، الطبقات الكبرى (٥/ ٣٠٧) وقال: كان ثقة قليل الحديث، كنى مسلم (ص ٤٦٥)، الجرح (٤/ ٢/ ٣٨١)، الثقات (٥/ ٥٦١)، كنى ابن منده (١٤٨/ ب)، التهذيب (١٢/ ١١٣) وقال: قال الدارقطنى: اسمه وهب، وقال غيره: اسمه قزمان، وقال ابن حجر أيضًا: قال ابن عبد البر: قيل: اسمه قزمان، ولا يصح له اسم غير كنيته، التقريب (٢/ ٤٢٩) وقال: ثقة من الثالثة./ ع."],[14061,"قلت: ومن الجدير بالذكر أنه تقدم في الصحابة (٢٩٣) أبو سفيان والد عبد اللَّه بن أبى سفيان، روى عنه ابنه عبد اللَّه، وقال ابن عبد البر في ترجمته هناك، أخشى أن يكون حديثه مرسلا، وقد تقدم أبو سفيان صاحب هذه الترجمة أيضًا في الكتاب الثانى (١٠٨٩) وقال ابن عبد البر في ترجمته هناك: \"قيل: اسمه قزمان، ولا يصح\"."],[14062,"(٢) هكذا قال ابن عبد البر هنا مولى ابن جحش، والصواب مولى ابن أبى أحمد الأسدى والذى في كنى مسلم، كنى ابن منده مولى أبى أحمد أو ابن أبى ="],[14063,"أبى أحمد الأسدى (١). لا يصح له اسم غير كنيته. واللَّه أعلم. وقيل: إنه مولى لبنى عبد الأشهل والأول أكثر. كان له انقطاع إلى ابن أبى أحمد بن جحش فنسب إلى ولائه، روى عن أبى هريرة، وأبى سعيد الخدرى، روى عنه داود بن الحصين، وابنه عبد اللَّه بن أبى سفيان (٢)، وقيل: عبد الرحمن بن أبى سفيان وخالد بن رباح الهذلى."],[14064,"٢٤٢٦ - أبو سفيان، سمع عليا رضي الله عنه، روى عمران بن سليمان (٣)."],[14065,"٢٤٢٧ - أبو سفيان الفلسطينى - شامى، روى عن بجير بن ريسان (٤)، روى عنه يحيى بن أبى كثير."],[14066,"= أحمد وفى الجرح مولى ابن أبى أحمد وفى الثقات مولى عبد اللَّه بن أبى أحمد، ولم يكن بمولاه، كان ينقطع إليه فنسب إليه، وهو مولى لبنى عبد الأشهل."],[14067,"(١) ابن أبى أحمد الأسدى: ذكره ابن حجر في التقريب (١/ ٤٠١) فقال: عبد اللَّه بن أبى أحمد بن جحش الأسدى، ولد في حياة النبى -صلى الله عليه وآله وسلم-، روى عن عمر وغيره، وذكره جماعة في ثقات التابعين. اهـ."],[14068,"(٢) عبد اللَّه بن أبى سفيان، ذكره ابن أبى حاتم في الجرح (٢/ ٢/ ٦٧) وذكر روايته عن أبيه، ولم يذكر فيه شيئًا."],[14069,"٢٤٢٦ - كنى البخارى (ص ٣٨)، الجرح (٤/ ٢/ ٣٨١)."],[14070,"(٣) عمران بن سليمان المرادى، كوفى، ذكره ابن أبى حاتم (٣/ ١/ ٢٩٩) ولم يذكر فيه شيئًا."],[14071,"٢٤٢٧ - كنى البخارى (ص ٣٩) وقال: روى عنه بقية، الجرح (٤/ ٢/ ٣٨١)، كنى ابن منده (١٤٨/ ب)، المقتنى في سرد الكنى (٦٢/ ب)."],[14072,"(٤) ذكره ابن أبى حاتم في الجرح (١/ ١/ ٤١١) فقال: بجير بن ريسان من أهل اليمن روى عن عبادة بن الصامت، روى عنه أبو سفيان الشامى. اهـ. ولم يذكر فيه جرحا."],[14073,"٢٤٢٨ - أبو سفيان الأنمارى شامى. روى عن حبيب بن عبد اللَّه ابن أبى كبشة، ويحيى بن سعيد الأنصارى. روى عنه بقية بن الوليد. حديثه ليس بالقائم."],[14074,"٢٤٢٩ - أبو سفيان بن (. . . . .) (١) بن عبد المطلب بن أبى وداعة السهمى، روى عن أبيه عن (. . . . .) (٢) حديثه ليس بالقائم."],[14075,"٢٤٣٠ - أبو سفيان بن عبد الرحمن بن المطلب بن أبى وداعة السهمى. روى عن أبيه، عن جده. حديثه عند أبى عامر العقدى، عن عبد ربه بن عطاء اللَّه (٣) عنه."],[14076,"٢٤٣١ - أبو سفيان بن العلاء بن عمار بن العريان بن خزاعى بن مازن بن مالك بن عمرو بن تميم، بصرى أخو أبى عمرو بن العلاء، ومعاذ بن العلاء،"],[14077,"٢٤٢٨ - الجرح (٤/ ٢/ ٣٨١) وقال: سألت أبى عنه فقال: هو مجهول، المقتنى في سرد الكنى (٦٢/ ب)، كنى ابن منده (١٤٩/ ب)، الميزان (٤/ ٥٣١) وقال: مجهول، اللسان (٧/ ٥٥) وقال: مجهول، المجروحين (٣/ ١٤٨) وقال: شيخ يروى الطامات من الروايات، لا يجوز الاحتجاج به إذا انفرد، وذكر حديثه من طريق بقية، قال: حدثنا أبو سفيان الأنمارى، عن حبيب بن عبد اللَّه بن أبى كبشة، عن أبيه، عن جده، قال: \"كان رسول اللَّه -صلى الله عليه وآله وسلم- يعجبه النظر إلى الأترج، والحمام الأحمر\"."],[14078,"٢٤٢٩ - لم أقف عليه عند غير المؤلف."],[14079,"(١) في الأصل بياض بمقدار كلمة."],[14080,"(٢) في الأصل بياض بمقدار كلمة أيضًا."],[14081,"٢٤٣٠ - كنى البخارى (ص ٣٩)، الجرح (٤/ ٢/ ٣٨١)، كنى ابن منده (١٤٨/ ب)."],[14082,"(٣) عبد ربه بن عطاء اللَّه، القرشى، المكى، مجهول الحال، من الثامنة التقريب (١/ ٤٧١)، الجرح (٣/ ١/ ٤٣)."],[14083,"٢٤٣١ - كنى البخارى (ص ٣٩)، الجرح (٤/ ٢/ ٣٨٢)، كنى ابن منده (١٤٨/ ب)، المقتنى في سرد الكنى (٦٢/ ب)."],[14084,"روى عن الحسن بن أبى الحسن، وابن أبى عتيق، روى عنه شعبة بن الحجاج، وإسماعيل بن علية، ووكيع، وقال يحيى القطان: \"كنت اشتهى أن أسمع من أبى سفيان بن العلاء حديث الحسن (عن) (١) عبد اللَّه بن مغفل. كان يقول فيه: حدثنى ابن مغفل\" (٢)."],[14085,"٢٤٣٢ - أبو سفيان بن جابر بن عتيك. قد نسبنا أباه في بابه من كتاب الصحابة (٣)، روى عن أبيه، روى عنه نافع بن يزيد، وسعيد بن أبى أيوب."],[14086,"٢٤٣٣ - أبو سفيان عن معروف السلمى لقيه بالموصل. روى عنه عبد الرحمن بن ثابت بن ثوبان."],[14087,"(١) في الأصل \"بن\" وهو تصحيف. والصحيح \"عن\" كما هو مثبت وكما هو في مصادر الترجمة. والحسن هذا هو الحسن البصرى، وعبد اللَّه بن مغفل هو الصحابى المعروف، روى عنه الحسن البصرى. وانظر التهذيب (١/ ٤٢)."],[14088,"(٢) انظر قول القطان هذا في كنى البخارى (ص ٣٩) والجرح (٤/ ٢/ ٣٨٢)."],[14089,"٢٤٣٢ - كنى البخارى (ص ٣٩) وقال: وكان قدم مصر، الجرح (٤/ ٢/ ٣٨١)، كنى ابن منده (١٤٨/ ب)، المقتنى في سرد الكنى (٦٢/ ب)."],[14090,"(٣) الاستيعاب (١/ ٢٢٣) وقال: جابر بن عتيك الأنصارى العامرى من بنى عمرو بن عوف بن مالك بن الأوس ويقال: جبر بن عتيك. . وذكر أيضًا أنه شهد بدرًا وجميع المشاهد بعدها وتوفى سنة إحدى وستين وهو ابن إحدى وتسعين سنة يكنى أبا عبد اللَّه وكانت معه راية بنى معاوية عام الفتح. اهـ."],[14091,"٢٤٣٣ - كنى ابن منده (١٤٨/ ب) وقال: أبو سفيان حدث عن معروف عن الحسن روى عنه عبد الرحمن بن ثابت بن ثوبان الشامى. المقتنى في سرد الكنى (٦٢/ ب) وقال: أبو سفيان عن معروف وعنه ابن ثوبان. اهـ."],[14092,"٢٤٣٤ - أبو سفيان مدنى (١)، سمع أبا هريرة. روى عنه واصل بن سيف. قال أبو حاتم: هو مجهول."],[14093,"٢٤٣٥ - أبو سفيان، روى عن سالم الخياط (٢) عن الحسن، روى عنه إسماعيل بن إبراهيم الصائغ (٣)، مجهولان."],[14094,"٢٤٣٦ - أبو سفيان الصواف، بصرى، روى عن ابن عون قال عباس عن ابن"],[14095,"٢٤٣٤ - كنى البخارى (ص ٣٩)، كنى ابن منده (١٤٨/ ب)، الجرح (٤/ ٢/ ٣٨١) وقال: سمعت أبى يقول: هو مجهول. الثقات (٥/ ٥٨٧)، الميزان (٤/ ٥٣١) وقال: مجهول اللسان (٧/ ٥٥)، وقال: مجهول."],[14096,"(١) في كنى البخارى \"المقرنى\" وفى الثقات \"المزنى\"."],[14097,"٢٤٣٥ - الجرح (٤/ ٢/ ٣٨٢) وقال: سألت أبى عنه فقال: هو مجهول. الميزان (٤/ ٥٣٢) وقال: هو مجهول، اللسان (٧/ ٥٥) وقال: مجهول."],[14098,"(٢) سالم بن عبد اللَّه الخياط، بصرى، نزل مكة، وهو سالم مولى عكاشة، وقيل: هما اثنان صدوق، سئ الحفظ، من السادسة. التقريب (١/ ٢٨٠)."],[14099,"(٣) إسماعيل بن إبراهيم بن ميمون الصائغ خراسانى نزل مكة قال أبو حاتم: هو شيخ. انظر الجرح (١/ ١/ ١٥٢)."],[14100,"٢٤٣٦ - الجرح (٢/ ٢/ ٣١٨) و(٤/ ٢/ ٣٨٢)، الميزان (٣/ ٩) و(٤/ ٥٣١) اللسان (٤/ ١٠٤ و٧/ ٥٤)."],[14101,"ذكره ابن أبى حاتم أولا في عبيد اللَّه بن سفيان بن رواحة أبو سفيان الصواف وقال: سألت أبى عنه فقال: هو شيخ ليس بالقوى وذكره ابن أبى حاتم مرة ثانية في الكنى من الجرح (٤/ ٢/ ٣٨٢) وذكر قول ابن معين فيه، وذكره الذهبى في الميزان (٣/ ٩) فقال: عبيد اللَّه بن سفيان أبو سفيان عن ابن عون وقال: كذبه ابن معين ووهى ابن حبان حديثه وهو غدانى بصرى، روى عنه أحمد بن سنان القطان وغيره والكديمى وعبد الرحمن بن بشر ويعرف بابن رواحة، وذكره الذهبى مرة ثانية في الكنى فقال أبو سفيان الصيرفى عن ابن عون قال الأزدى: يكذب وكذا كذبه ابن معين وقيل فيه: الصواف. وقيل: هما اثنان، والصواف اسمه عبيد اللَّه والصيرفى يقال له: ابن رواحة هو صاحب ابن عون."],[14102,"معين: كان كذابا (١)."],[14103,"٢٤٣٧ - أبو سفيان بن عبد ربه، روى عن عمر بن نبهان (٢)، روى عنه عمرو بن أبى قيس (٣). هو عندهم مجهول."],[14104,"٢٤٣٨ - أبو سفيان، عن عبد اللَّه بن دينار، روى عنه منصور (٤) بن دينار (٥)، لم يعرفه أبو زرعة."],[14105,"(١) انظر تاريخ ابن معين (٢/ ٣٨٢) وقال: عبيد اللَّه بن سفيان بن عبد اللَّه بن رواحة، أبو سفيان الصواف، كان كذابا، وكان يقال له: ابن رواحة وقد قدم علينا، وهو بصرى، وكان يروى عن ابن عون. وانظر قول ابن معين أيضًا في مصادر الترجمة كما تقدم."],[14106,"٢٤٣٧ - الجرح (٤/ ٢/ ٣٨٢) وقال: سألت أبى عنه فقال: هو شيخ مجهول، الميزان (٤/ ٥٣٢) وقال: مجهول، اللسان (٧/ ٤٦٧) وقال: قال أبو حاتم شيخ. وذكره ابن أبى حاتم أيضًا في الجرح (٢/ ٢/ ٢٥٦) فقال: عبد الرحمن بن عبد ربه الشيبانى قاضى نيسابور، قدم الرى، ويعرف بأبى سفيان بن عبد ربه، وذكر روايته عن عمر بن نبهان وآخرين ورواية عمر بن أبى قيس وآخرون عنه. وقال أيضًا: سألت أبى عنه فقال: شيخ. اهـ."],[14107,"(٢) عمر بن نبهان بفتح النون وسكون الموحدة العبدى، ويقال: الغبرى بضم المعجمة وفتح الموحدة الخفيفة، بصرى خال محمد بن بكر، ضعيف من السابعة. التقريب (٢/ ٦٤) وذكره ابن أبى حاتم في الجرح (٣/ ١/ ١٣٨) وذكر رواية أبى سفيان عبد الرحمن بن عبد ربه بن تميم عنه. وقال: سألت أبى عنه فقال: ضعيف الحديث. اهـ."],[14108,"(٣) عمرو بن أبى قيس الكوفى، نزيل الرى، ذكره ابن أبى حاتم في الجرح (٣/ ١/ ٢٥٥) ولم يذكر فيه شيئًا."],[14109,"٢٤٣٨ - كنى مسلم (ص ٤٦٥)، الجرح (٤/ ٢/ ٣٨٢) وقال: سئل أبو زرعة عنه فقال: لا أعرفه."],[14110,"(٤) في كنى مسلم \"معتمر\"."],[14111,"(٥) منصور بن دينار التميمى، ذكره ابن أبى حاتم في الجرح (٤/ ١/ ١٧١) ="],[14112,"٢٤٣٩ - أبو سفيان. روى عن مسلم بن كثير (١). عن عمرو بن حَرِيش (٢) عن عبد اللَّه بن عمرو بن العاص. روى عنه محمد بن إسحاق بن يسار. قال عثمان بن سعيد الدارمى: قلت ليحيى بن معين: محمد بن إسحاق روى عن أبى سفيان ما حال أبى سفيان؟ فقال: ثقة مشهور (قلت) (٣) عن مسلم بن كثير عن عمرو بن حريش الزّبيدى؟ قال: هذا حديث مشهور (٤)."],[14113,"= وقال: سألت أبى عنه فقال: ليس به بأس. اهـ. وقال عباس عن ابن معين: ضعيف الحديث. انظر التاريخ (٢/ ٥٨٧)."],[14114,"٢٤٣٩ - الجرح (٤/ ٢/ ٣٨٢) وذكر قول عثمان بن سعيد الدارمى عن ابن معين فيه. تهذيب الكمال (٣/ ١٦١٠)، الميزان (٤/ ٥٣١) وقال: لا يعرف، تعجيل المنفعة (ص ٢٦٢)، التهذيب (١٢/ ١١٣)، التقريب (٢/ ٤٢٩) وقال: مقبول، من السادسة./ د."],[14115,"(١) مسلم بن كثير. ذكره ابن أبى حاتم في الجرح (٤/ ١/ ١٩٣) فقال: مسلم ابن كثير. روى عن عمرو بن حريش الزبيدى، عن عبد اللَّه بن عمرو بن العاص روى عنه أبو سفيان. قلت: وقد قيل فيه مسلم بن جبير، بل ذكره الكثيرون في مسلم بن جبير وسيأتى ذكره أيضًا عند تخريج الحديث."],[14116,"(٢) عمرو بن حَرِيش، بفتح أوله، وآخره معجمة، الزبيدى، بضم أوله له حديث مشهور، وهو مجهول الحال، من الرابعة، وزعم ابن حبان أنه عمرو بن حبشى فوهم، انظر تهذيب الكمال (٢/ ١٠٢٩ - ١٠٣٠) التقريب (٢/ ٦٨)."],[14117,"(٣) الحق في هامش الأصل، كتب عنده \"صح\"."],[14118,"(٤) انظر قول عثمان بن سعيد الدارمى عن يحيى في تاريخ ابن معين رواية الدارمى (ص ١٩٩) قلت: والحديث المشار إليه في هذه الترجمة هو ما رواه محمد بن إسحاق عن أبى سفيان عن مسلم، عن عمرو بن حريش الزبيدى قال: قلت لعبد اللَّه بن عمرو إنا بأرض ليس بها ذهب ولا فضة نبيع البقرة بالبقرتين والبعير بالبعيرين، والشاة بالشاتين. فقال: أمرنى رسول اللَّه -صلى الله عليه وآله وسلم- أن ="],[14119,". . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . ."],[14120,"= اجهز جيشا فنفذت الإبل فقلت لرسول اللَّه -صلى الله عليه وآله وسلم-: نفذت الإبل فقال: خذ في قلاص الصدقة قال: فجعلت آخذ البعير بالبعيرين إلى إبل الصدقة. والحديث أخرجه ابن أبى حاتم في الجرح (٤/ ٢/ ١٩٣)، المزى في تهذيب الكمال في ترجمة عمرو بن حريش (٢/ ١٠٢٩) وأحمد في المسند (٢/ ١٧١ و٢١٦) من طريق جرير بن حازم عن محمد بن إسحاق، عن أبى سفيان، عن مسلم بن جبير، عن عمرو بن الحريش عن عبد اللَّه بن عمرو بن العاصى، ومن طريق يعقوب بن سعد عن أبيه عن ابن إسحاق قال: حدثنى أبو سفيان الجرشى، وكان ثقة فيما ذكر أهل بلاده، عن مسلم بن جبير مولى ثقيف وكان مسلم رجلا يؤخذ عنه وقد أدرك وسمع عن عمرو بن حريش الزبيدى، عن عبد اللَّه بن عمرو بن العاص."],[14121,"وأخرجه أبو داود \"البيوع\" باب الرخصة في الحيوان بالحيوان نسيئة (٣/ ٢٥٠) من طريق حماد بن سلمة عن محمد بن إسحاق عن يزيد بن أبى حبيب، عن مسلم بن جبير، عن أبى سفيان، عن عمرو بن حريش، عن عبد اللَّه بن عمرو به مختصرا. أخرجه الطحاوى في شرح معانى الآثار (٤/ ٦٠) من طريق حماد بن سلمة عن محمد بن إسحاق، عن يزيد بن أبى حبيب عن مسلم بن جبير عن أبى سفيان، عن عمرو بن حريش عن عبد اللَّه ابن عمرو بن العاص به."],[14122,"والحاكم (٢/ ٥٦ - ٥٧) من طريق حماد بن سلمة به كما عند الطحاوى وقال الحاكم: هذا حديث صحيح على شرط مسلم ولم يخرجاه ووافقه الذهبى. والبيهقى (٥/ ٢٨٧ - ٢٨٨) من طريق حماد بن سلمة به أيضًا وقال البيهقى: اختلفوا على محمد بن إسحاق في إسناده، وحماد بن سلمة أحسنهم سياقة له، وله شاهد صحيح، ووافقه ابن التركمانى في الجوهر النقى. وأخرجه البيهقى أيضًا من طريق ابن جريح أن عمرو بن شعيب أخبره عن أبيه عن عبد اللَّه بن عمرو بن العاص أن رسول اللَّه -صلى الله عليه وآله وسلم- أمره أن يجهز جيشا. . فذكره. والحديث كما سبق وإن عرفت في سنده اضطراب فروى من = . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . ."],[14123,"= طريق مسلم بن جبير هو الأكثر، وروى من طريق مسلم بن كثير وأيضًا اختلف فيه على أبى سفيان فعند أحمد رواه ابن إسحاق عن أبى سفيان عن مسلم بن جبير وعند أبى داود رواه مسلم بن جبير عن أبى سفيان عن عمرو ابن حريش، وقد قال الحافظ ابن حجر في ترجمة مسلم بن جبير في تعجيل المنفعة وقد ذكر هذا الحديث وبعض طرقه: إذا كان الحديث واحدًا وفى رجال إسناده اختلاف بالتقديم والتأخير رجح الإتحاد ويترجح برواية إبراهيم ابن سعد على رواية حماد باختصاصه بابن إسحاق، وقد تابع جرير بن حازم إبراهيم فهى الراجحة. اهـ. وقد ذكر الدكتور أحمد نور سيف في تحقيقه لتاريخ ابن معين رواية الدارمى هذا الحديث في ترجمة مسلم بن كثير (ص ١٩٩ - ٢٠١) وذكر الاختلاف في سنده في شئ من التفصيل، ورجح بأن مسلم بن كثير هذا إنما هو مسلم بن جبير وأن التحريف وقع من الرواة. واللَّه أعلم."],[14124,"وقد قوى الحافظ ابن حجر إسناد حديث عبد اللَّه بن عمرو هذا وذلك في كتابه الدراية (٢/ ١٥٩)، وقال في تلخيص الحبير (٣/ ٨) في إسناد الحديث ابن إسحاق، وقد اختلف عليه فيه وقد صححه البيهقى وقال ابن أبى حاتم في العلل (١/ ٣٩٠): سألت أبى عن حديث رواه حماد بن سلمة عن محمد بن إسحاق عن يزيد بن أبى حبيب عن مسلم بن جبير عن أبى سفيان عن عمرو بن حريش عن عبد اللَّه بن عمرو بن العاص. . فذكر الحديث. وقال: قلت لأبى: من مسلم بن جبير؟ فقال: هو مصرى."],[14125,"قلت: فأبو سفيان من هو؟ قال: هو الشامى، إن لم يكن الذى روى عنه يحيى بن أبى كثير عن أبى سفيان رجل من أهل الشام، عن بجير بن ريسان عن عبادة في الصلاة بين التراويح قال: لا أدرى من هو؟ اهـ. وقال ابن القطان كما في نصب الراية (٤/ ٤٧) بعد ذكر طريق هذا الحديث هذا حديث ضعيف مضطرب الإسناد وبين وجوه الاضطراب ثم قال: ومع هذا الاضطراب فعمرو بن حريش مجهول الحال، ومسلم بن جبير لم أجد له ذكرا ولا أعلمه في غير هذا الإسناد، وكذلك مسلم مجهول الحال أيضًا إذا كان عن أبى سفيان، وأبو سفيان فيه نظر. اهـ."],[14126,"باب أبى سبرة"],[14127,"٢٤٤٠ - أبو سَبْرة (١)، روى عن محمد بن كعب القرظى، روى عنه الأعمش قال ابن معين: لا أعرفه."],[14128,"٢٤٤١ - أبو سبرة النخعى (٢) كوفى روى عن فروة بن مُسَيك (٣)، (٤). روى عنه الحسن بن الحكم النخعى (٥)."],[14129,"٢٤٤٠ - كنى البخارى (ص ٤٠)، كنى مسلم (ص ٤٨٤)، الجرح (٤/ ٢/ ٣٨٤) وقال: ذكره أبى عن إسحاق بن منصور عن يحيى بن معين أنه قال: أبو سبرة الذى روى عن محمد بن كعب القرظى، الذى روى عنه الأعمش لا أعرفه، المقتنى في سرد الكنى (٥٧/ أ)."],[14130,"(١) سبرة: بفتح السين المهملة، وسكون الموحدة. كما في التقريب (٢/ ٤٢٦) وتبصير المنتبه (٢/ ٦٧٣)."],[14131,"٢٤٤١ - كنى البخارى (ص ٤٠)، الجرح (٤/ ٢/ ٣٨٥)، الثقات (٥/ ٥٦٩) تهذيب الكمال (٣/ ١٦٠٧)، التهذيب (١٢/ ١٠٥) وجعله هو والذى قبله واحدًا ثم قال: وقد قيل: أن الراوى عن فروة بن مسيك غير الراوى عن محمد بن كعب القرظى. فاللَّه أعلم. التقريب (٢/ ٤٢٦) وقال: أبو سبرة، بسكون الموحدة. النخعى، الكوفى، يقال: اسمه عبد اللَّه بن عابس، مقبول، من الثالثة./ د. ت. ق."],[14132,"(٢) في الثقات \"البجلى\"."],[14133,"(٣) فروة بن مسيك: بمهملة مصغرا، المرادى، ثم الغُطَيْفى بمعجمة مصغرا، صحابى سكن الكوفة، يكنى أبا عمير، واستعمله عمر. قال ابن حبان في الثقات (٥/ ٥٦٩): له صحبة. وانظر التجريد (٢/ ٧)."],[14134,"(٤) زاد في الثقات \"وله صحبة\"."],[14135,"(٥) الحسن بن الحكم النخعى، أبو الحكم الكوفى، صدوق يخطئ، من السادسة. مات قبيل الخمسين. التقريب (١/ ١٦٥)."],[14136,"٢٤٤٢ - أبو سبرة عن شريح في الرهن (١). روى عنه سيار. قال ابن أبى حاتم: سمعت أبى وأبا زرعة يقولان ذلك."],[14137,"٢٤٤٢ - الجرح (٤/ ٢/ ٣٨٤) ذكره كما هنا وقال: سمعت أبى وأبا زرعة يقولان ذلك."],[14138,"(١) لم أقف على هذا الخبر من هذا الطريق وقد رويت أخبار عن شريخ في الرهن انظر مصنف ابن أبى شبية (٦/ ٢١) مصنف عبد الرزاق (٢/ ٢٣٨ و٢٣٩ و٢٤٧)."],[14139,"وأخرج وكيع في أخبار القضاة (٢/ ٢٩٩) من طريق هشيم عن سيار عن أبى سبرة سمع شريحا يقول: \"ذهبت الرهان بما فيها\" وأخرجه أيضًا وكيع في أخبار القضاة (٣/ ٢٣٠ و٢٤١ و٢٤٢ و٢٦٥ و٢٨٧ و٢٩٩ و٣٧٣ و٣٨٧) من طرق عن شريح به وبنحوه وفى أحد ألفاظه أنه سئل وإن كان أقل أو أكثر قال: نعم وفى لفظ آخر عن شريح قال إذا كان الرهن بأقل ممن رهن قال: أنت رضيت به من حقك وإذا كان أكثر قال: أنت أغلقته."],[14140,"باب أبى السائب"],[14141,"٢٤٤٣ - أبو السائب الأنصارى المدنى، مولى هشام بن زهرة، وقيل: مولى عبد اللَّه بن هشام بن زهرة (١)، وقيل: مولى بنى عبد اللَّه بن هشام بن زهرة. وقيل: مولى بنى زهرة وأصح ما في ذلك قول من قال مولى هشام بن زهرة وهو قول الحفاظ من أصحاب العلاء بن عبد الرحمن، كان من جلساء أبى هريرة. روى عن أبى هريرة وسعد بن أبى وقاص وأبى سعيد الخدرى. روى عنه العلاء بن عبد الرحمن، وشريك بن عبد اللَّه بن أبى نمر وبكير بن الأشج وصيفى (٢) بن"],[14142,"٢٤٤٣ - كنى مسلم (ص ٤٨٢)، الطبقات الكبرى (٥/ ٣٠٧)، الثقات (٥/ ٥٦١) وقال: أبو السائب مولى هشام بن زهرة بن عثمان بن عمرو بن كعب السلمى أصله من فارس، يروى عن أبى هريرة روى عنه العلاء بن عبد الرحمن وبكير بن الأشج والزهرى، كنى ابن منده (١٥٢/ أ)، التهذيب (١٢/ ١٠٤)، التقريب (٢/ ٤٢٦) وقال: يقال: اسمه عبد اللَّه بن السائب، ثقة، من الثالثة. م. عـ."],[14143,"قلت: وقد تقدم لأبى السائب هذا ترجمة في الكتاب الثانى (١١٠٦) وأشار ابن عبد البر في ترجمته هناك بأنه ذكره أيضًا في الذين لا تعرف أسماؤهم."],[14144,"(١) عبد اللَّه بن هشام بن زهرة بن عثمان التيمى، صحابى، صغير مات في خلافة معاوية. انظر التقريب (١/ ٤٥٨)."],[14145,"(٢) هكذا في الأصل \"صيفى بن أفلح\" وفى التهذيب \"صيفى مولى أفلح\" وذكره البخارى في التاريخ الكبير (٢/ ٢/ ٣٢٣) فقال: صيفى أبو زياد مولى أفلح مولى أبى أيوب عن أبى السائب ولم يذكر فيه شيئًا. وذكره ابن أبى حاتم في الجرح (٢/ ١/ ٤٤٨) ولم يذكر فيه شيئًا. وذكره ابن حبان في الثقات (٤/ ٣٨٤) وقال: عداده في أهل المدينة."],[14146,"أفلح، ومحمد بن عمرو بن عطاء، وعبيد اللَّه بن عمر، وقد روى عن ابن شهاب الزهرى، وصفوان بن سليمان عنه من طرق ليست بالقوية، أجمعوا على أن أبا السائب هذا ثقة مقبول النقل (١)."],[14147,"٢٤٤٤ - أبو السائب المخزومى. روى عن جدته آمنة بنت الأرقم (٢) روى عنه الحسين (٣) بن زيد بن على بن حسين بن على رضي الله عنهم."],[14148,"(١) يذكر ابن حجر في التهذيب (١٢/ ١٠٤) قال: \"قال ابن عبد البر أجمعوا على أنه ثقة مقبول النقل\"."],[14149,"٢٤٤٤ - كنى ابن منده (١٥٢/ أ)، الميزان (٤/ ٥٢٧) وقال: مجهول، اللسان (٧/ ٥٠)."],[14150,"(٢) آمنة بنت الأرقم. ذكرها ابن حجر في الإصابة (٤/ ٢٢٤) وقال: روى أبو السائب المخزومى عن جدته آمنة بنت الأرقم أن النبى -صلى الله عليه وآله وسلم- أقطعها بئرا ببطن العقيق فكانت تسمى بئر آمنه وبرك لها فيها، وكانت من المهاجرات ذكرها ابن الدباغ مستدركا على الاستيعاب. اهـ."],[14151,"(٣) الحسين بن زيد بن على بن الحسين بن على، صدوق، ربما أخطأ من الثامنة مات وله ثمانون سنة. انظر التقريب (١/ ١٧٦)."],[14152,"باب أبى سلامة"],[14153,"٢٤٤٥ - أبو سلامة الشيبانى. سمع عمر بن الخطاب. روى عنه سماك بن حرب."],[14154,"٢٤٤٦ - أبو سلامة مولى الفهريين هكذا قال الحاكم في الكنى وقال ابن أبى حاتم: أبو سلام. روى عن على بن عبد اللَّه بن عباس. قال: سمعت على ابن عبد اللَّه بن عباس يقول: \"إذا جامعت فاستتر من السماء\". روى عنه معن بن عيسى."],[14155,"٢٤٤٥ - كنى البخارى (ص ٤٢)، الجرح (٤/ ٢/ ٣٨٧)، كنى ابن منده (١٥٣/ أ)، المقتنى في سرد الكنى (٦٣/ أ)."],[14156,"٢٤٤٦ - الجرح (٤/ ٤/ ٣٨٥) وقال: أبو سلام مولى الفهريين قال: سمعت على بن عبد اللَّه بن عباس يقول: إذا جامعت فاستتر من السماء. روى عنه معن بن عيسى\". اهـ. ويشهد لهذا الخبر حديث ابن عمر يرفعه. أخرجه الترمذى \"الأدب\" باب ما جاء في الاستتار عند الجماع (٨/ ٨٤) قال: قال رسول اللَّه -صلى الله عليه وآله وسلم- \"إياكم والتعرى فإن معكم من لا يفارقكم إلا عند الغائط وحين يفضى الرجل إلى أهله، فاستحيوهم وأكرموهم\" وقال: هذا حديث غريب لا نعرفه إلا من هذا الوجه. وحديث بهز بن حكيم عن أبيه عن جده قال: قلت يا رسول اللَّه أعوراتنا ما نأتى منها وما نذر؟ قال: \"احفظ عورتك، إلا من زوجك أو ما ملكت يمينك، قلت: يا رسول اللَّه أرأيت إن كان القوم بعضهم في بعض؟ قال \"إن استطعت أن لا تريها أحدا، فلا ترينها\" قلت: يا رسول اللَّه فإن كان أحدنا خاليا؟ قال: \"فاللَّه أحق أن يستحيى منه من الناس\" وأخرجه ابن ماجه \"النكاح\" باب التستر عند الجماع (١/ ٦١٨) وأخرج ابن ماجه أيضًا (١/ ٦١٨ - ٦١٩) حديث عتبة بن عبد السّلمى قال: قال رسول اللَّه -صلى الله عليه وآله وسلم- \"إذا أتى أحدكم أهله فليستتر ولا يتجرد تجرّد العيرين\". قال = . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . ."],[14157,"= السندى: في الزوائد إسناده ضعيف وذكر أن فيه مجهولا. وأخرج البزار كما في كشف الأستار (٢/ ١٦٩ - ١٧٠) حديث أبى هريرة قال: قال رسول اللَّه -صلى الله عليه وآله وسلم-: \"إذا أتى أحدكم أهله فليستتر، فإنه إذا لم يستتر، استحيت الملائكة فخرجت وبقى الشيطان، فإن كان بينهما ولد كان للشيطان فيه نصيب\"."],[14158,"قال البزار: لا نعلمه مرفوعا إلا بهذا الإسناد عن أبى هريرة فقط وإسناده ليس بالقوى. وعزاه الهيثمى في مجمع الزوائد (٤/ ٢٩٣) إلى البزار والطبرانى في الأوسط. وقال: إسناد البزار ضعفه، وفى إسناد الطبرانى أبو المنيب صاحب يحيى بن أبى كثير ولم أجد من ترجمه وبقية رجال الطبرانى ثقات، وفى بعضهم كلام لا يضر. اهـ. وأخرج البزار أيضًا كما في كشف الأستار (٢/ ١٧٠) حديث عبد اللَّه، من طريق أبى غسان، ثنا مندل بن على، عن الأعمش، عن أبى وائل، عن عبد اللَّه قال: قال رسول اللَّه -صلى الله عليه وآله وسلم- \"إذا أتى أحدكم أهله فليستتر ولا يتجرد تجرد العيرين\" وقال البزار: لا نعلم رواه عن الأعمش هكذا إلا مندل وأخطأ فيه وذكر شريك أنه كان هو ومندل عند الأعمش وعنده عاصم الأحول فحدث عاصم عن أبى قلابة، عن النبى -صلى الله عليه وآله وسلم- بهذا الحديث مرسلا. وذكر الهيثمى في مجمع الزوائد (٤/ ٢٩٣) حديث عبد اللَّه هذا وعزاه للبزار والطبرانى في الكبير وقال: وفيه مندل بن عدى وهو ضعيف وقد وثق وبقية رجاله رجال الصحيح."],[14159,"باب أبى سويد"],[14160,"٢٤٤٧ - أبو سويد - القضاعى (١) سمع تبيعا (٢). روى عنه عبد اللَّه بن أبى رفيق الأزدى (٣)."],[14161,"٢٤٤٨ - أبو سويد العبدى يقال: أبو سويد بن المغيرة. روى عن الحسن"],[14162,"٢٤٤٧ - كنى البخارى (ص ٤٠)، الجرح (٤/ ٢/ ٣٨٥) وقال: سمعت أبى يقول: لا أعرف أبا سويد، كنى ابن منده (١٥٣/ ب) وقال: عداده في أهل مصر."],[14163,"(١) القضاعى: بضم القاف وفتح الضاد المعجمة وفى آخرها عين مهملة - هذه النسبة إلى قضاعة، شعب عظيم يشتمل على قبائل كثيرة. اللباب (٣/ ٤٣)."],[14164,"(٢) زاد البخارى في الكنى \"مرسل\"."],[14165,"(٣) عبد اللَّه بن أبى رُفَيْق، بضم الراء وبعدها فاء مفتوحة. ذكره ابن أبى حاتم في الجرح (٢/ ٢/ ٥٥) وذكر روايته عن أبى سويد القضاعى عن تبيع ولم يذكر فيه شيئا. وانظر الاكمال (٤/ ٨٢)."],[14166,"٢٤٤٨ - كنى ابن منده (١٥٣/ ب)، الجرح (٤/ ٢/ ٣٨٥)، الثقات (٧/ ٦٦٢) تعجيل المنفعة (ص ٣٢٣) وقال: أورده الحاكم أبو أحمد فيمن لا يعرف اسمه ونقل عن البخارى من طريق وكيع عن بركة عنه. قال: كنا بباب عمر رضي الله عنه فذكر قصته. اهـ. ومن الجدير بالذكر أن البخارى جعله هو والذى قبله واحدا فقال: أبو سويد القضاعى سمع تبيعا مرسل، قاله سعيد بن أبى أيوب عن عبد اللَّه بن أبى رفيق قال سليمان بن حرب: نا حماد بن زيد قال: نا أبو سويد وهو ابن المغيرة عن الحسن أن الأحنف بن قيس قدم على عمر في وفد أهل البصرة فسرحهم واحتبس الأحنف حولا ثم دعاه فقال: إن النبى -صلى الله عليه وآله وسلم- حذرنا كل منافق عالم اللسان وأنى تخوفت أن تكون منهم وأنا أرجو أن لا تكون فالحق بأهلك. اهـ."],[14167,"عن الأحنف أنه قدم على عمر (١). روى عنه حماد بن زيد وبركة بن يعلى التميمى (٢)."],[14168,"(١) انظر كنى البخارى (ص ٤١)، الجرح (٤/ ٢/ ٣٨٥)، تعجيل المنفعة (ص ٣٢٣) في هذا الخبر."],[14169,"(٢) بركة بن يعلى التميمى، قال الذهبى: وتبعه ابن حجر: لا يعرف. انظر الميزان (١/ ٣٠٤)، اللسان (٢/ ٨)."],[14170,"باب أبى سيف"],[14171,"٢٤٤٩ - أبو سيف مولى عبد الرحمن بن سمرة القرشى (١)، روى عنه ثابت ابن أسلم البنانى قوله."],[14172,"٢٤٥٠ - أبو سيف. روى عن الحسن قوله. روى عنه يعقوب بن القعقاع (٢)."],[14173,"٢٤٥١ - أبو سيف. روى عن الأعمش. روى عنه يعقوب القمىّ."],[14174,"٢٤٤٩ - كنى البخارى (ص ٤١)، الجرح (٤/ ٢/ ٣٨٥)، الثقات (٥/ ٥٨٧) المقتنى في سرد الكنى (٦٨/ ب)."],[14175,"(١) زاد في الثقات \"يروى عن عبد الرحمن بن سمرة\"."],[14176,"٢٤٥٠ - كنى البخارى (ص ٤١)، الجرح (٤/ ٢/ ٣٨٥)، كنى ابن منده (١٥٣/ ب)، المقتنى في سرد الكنى (٦٨/ ب)."],[14177,"(٢) يعقوب بن القعقاع بن الأعلم الأزدى أبو الحسن الخراسانى، ثقة من السادسة، التقريب (٢/ ٣٧٦)، الجرح (٤/ ٢/ ٢١٣)."],[14178,"٢٤٥١ - الجرح (٤/ ٢/ ٣٨٥) وقال: سألت أبى عنه فقال: لا أعرفه. كنى ابن منده (١٥٣/ ب)."],[14179,"باب أبى سهلة"],[14180,"٢٤٥٢ - أبو سهلة، مولى عثمان بن عفان. وقيل: أبو سهيلة - كوفى روى عن عائشة زوج النبى عليه السلام وعن عثمان بن عفان. روى عنه قيس بن أبى حازم."],[14181,"٢٤٥٣ - أبو سهلة البصرى، روى عن أبى هريرة. روى عنه سليمان التيمى."],[14182,"٢٤٥٢ - كنى ابن منده (١٥٣/ أ) وقال: مشهور، المقتنى في سرد الكنى (٦٨/ أ)، التهذيب (١٢/ ١٢٢) وذكر أنه روى عن عائشة رضي الله عنها أيضًا وأن أبا زرعة قال: لا أعرف اسمه، وأنه وثقه العجلى وابن حبان. وقال في التقريب (٢/ ٤٣٢) أبو سهلة مولى عثمان بن عفان، ويقال بالمعجمة، ثقة، من الثالثة./ ت. ق. اهـ."],[14183,"٢٤٥٣ - المقتنى في سرد الكنى (٦٨/ أ)."],[14184,"باب أفراد في الكنى"],[14185,"٢٤٥٤ - أبو سلام. روى عن أبى محذورة في الأذان (١). قال أبو حاتم: لا أعلمه يسمى."],[14186,"٢٤٥٥ - أبو سارية، سمع أنس بن مالك. روى عنه هشام بن سعد."],[14187,"٢٤٥٦ - أبو سُمَيَّة مذكور في حديث (٢) جابر لا نعرفه بغير ذلك. سئل أبو زرعة عن اسمه فقال: لا أعرف اسمه."],[14188,"٢٤٥٤ - الجرح (٤/ ٢/ ٣٨٥) وقال: سئل أبى عنه فقيل: هل يسمى؟ قال: لا أعلمه."],[14189,"(١) تقدم حديث أبى محذورة في الأذان في (١٦٨)."],[14190,"٢٤٥٥ - كنى ابن منده (٥٤/ أ)، الجرح (٤/ ٢/ ٣٨٧)، كنى الحاكم (١/ ٢١٦/ ب) وقال: قاله محمد بن إسماعيل. اهـ. قلت: ولم أقف عليه في الكنى المجردة للبخارى وذلك لوجود سقط في باب السين فيه. واللَّه أعلم."],[14191,"٢٤٥٦ - كنى ابن منده (٥٤/ ب)، تهذيب الكمال (٣/ ١٦١٢)، الجرح (٤/ ٢/ ٣٨٨)، الثقات (٥/ ٥٦٩)، كنى الحاكم (١/ ٢١٦/ ب) الميزان (٤/ ٥٣٤)، وقال: مجهول، اللسان (٧/ ٥٨)، التهذيب (١٢/ ١٢٠)، التقريب (٢/ ٤٣١) وقال: أبو سمية بالتصغير، عن جابر، مقبول، من الرابعة./ ق."],[14192,"(٢) الحديث أخرجه أبو أحمد الحاكم في الكنى (١/ ٢١٦/ ب) من طريق كثير ابن زياد عن أبى سمية قال: سألت جابرًا فقلت سمعت النبى -صلى الله عليه وآله وسلم- يقول: الورود الدخول \"ثم ننجى الذين اتقوا\" اهـ. يشير بذلك إلى الآيتين ٧١، ٧٢ من سورة مريم وهو قوله تعالى ﴿وَإِنْ مِنْكُمْ إِلَّا وَارِدُهَا كَانَ عَلَى رَبِّكَ حَتْمًا مَقْضِيًّا. ثُمَّ نُنَجِّي الَّذِينَ اتَّقَوْا وَنَذَرُ الظَّالِمِينَ فِيهَا جِثِيًّا﴾. . وأخرجه أحمد في المسند (٣/ ٣٢٨) من طريق كثير بن زياد البرسانى عن أبى سمية قال: اختلفنا ههنا في الورود فقال بعضنا: لا يدخلها مؤمن وقال بعضنا ="],[14193,"٢٤٥٧ - أبو السّكن (١) الهجرى. روى عن جابر عن النبى عليه السلام. روى الصمد بن عبد الوارث عن صدقة (٢) عنه."],[14194,"= يدخلونها جميعًا ثم ينجى اللَّه الذين أتقوا فلقيت جابر بن عبد اللَّه فقلت له: أنا اختلفنا في ذلك الورود فقال بعضنا يدخلها مؤمن وقال بعضنا يدخلونها جميعًا فأهوى بأصبعيه إلى أذنيه وقال: صمتا إن لم أكن سمعت رسول اللَّه -صلى الله عليه وآله وسلم- يقول: الورود الدخول لا يبقى بر ولا فاجر إلا دخلها فتكون على المؤمن بردًا وسلامًا كما كانت على إبراهيم، حتى إن النار أو قال: لجهنم ضجيجا من بردهم ثم ينجى اللَّه الذين اتقوا ويذر الظالمين فيها حيثا\". وأخرج الدارقطنى في الصفات (ص ٢٨ - ٢٩) وابن كثير في التفسير (٣/ ١٣١ - ١٣٢) من طريق أحمد بن حنبل حدثنا سليمان بن حرب، حدثنا خالد بن سليمان، عن كثير بن زياد به وقال ابن كثير: غريب ولم يخرجوه. وذكره السيوطى في الدر المنثور (٤/ ٢٨٠) وزاد نسبته إلى عبد بن حميد، والحكيم الترمذى، وابن المنذر، وابن أبى حاتم، والحاكم وصححه ابن مردويه، والبيهقى في البعث، عن ابن سمية به وانظر المستدرك (٤/ ٥٨٧)، والحديث ذكره الهيثمى في مجمع الزوائد (٧/ ٥٥) من حديث أبى سمية عن جابر وقال: رواه أحمد ورجاله ثقات. اهـ. وأخرج مسلم حديث جابر في الورود لكن من طريق آخر وبنحو هذا اللفظ. انظر الصحيح \"الإيمان\" باب أدنى أهل الجنة منزلة (١/ ٧٧)."],[14195,"٢٤٥٧ - الجرح (٤/ ٢/ ٣٨٨)، كنى ابن منده (١٥١/ ب)، الميزان (٤/ ٥٣٢) وذكر أن له حديثا في \"الشعر\" وقال: حديثه منكر، ذكره البخارى في الضعفاء. رواه صدقة الدقيقى عنه، وتبعه الذهبى في اللسان (٧/ ٥٥) فقال مثل ما قال."],[14196,"(١) سكن: بسين مهملة مفتوحة وآخره نون. الاكمال (٤/ ٣٢١)."],[14197,"(٢) صدقة بن موسى، الدَّقِيقى، أبو المغيرة أو أبو محمد، السّلمى البصرى صدوق، له أوهام، من السابعة. التقريب (١/ ٣٦٦)، التهذيب (٤/ ٤١٨)."],[14198,"٢٤٥٨ - أبو سُخَيْلة (١) روى عن على. روى عنه الخضر بن القوّاس (٢) سئل أبو زرعة عن اسم أبى سخيلة فقال: لا أعرف اسمه."],[14199,"٢٤٥٩ - أبو سيّار (٣) الغنوى. روى عن أبيه (٤) عن عمر بن عبد العزيز روى عنه أبو سلمة موسى بن إسماعيل."],[14200,"٢٤٦٠ - أبو سيّارة (٥) روى عن محمد بن كعب القرظى. روى عنه ابن زَحْر (٦) أظنه الغنوى."],[14201,"٢٤٥٨ - كنى ابن منده (٥٤/ أ)، الجرح (٤/ ٢/ ٣٨٨) وقال: سئل أبو زرعة عن اسم أبى سخيلة فقال: لا أعرف اسمه. كنى الحاكم (١/ ٢١٦/ ب)، وقال: حديثه في الكوفيين، التهذيب (١٢/ ١٠٥) وقال: غير منسوب ولا مسمى. روى عن أبى ذر وسلمان الفارسى وعلى بن أبى طالب، وذكر أيضًا من الرواة عنه فضيل بن مرزوق، ومحمد بن عبيد العرزمى، وقال في التقريب (٢/ ٤٢٦) أبو سخيلة بالمعجمة مصغرًا، مجهول من الثالثة./ عس."],[14202,"(١) سخيلة: بضم السين المهملة وفتح الخاء المعجمة، مصغرًا، انظر التقريب (٢/ ٤٢٦) والخلاصة (ص ٤٥٠)."],[14203,"(٢) الخضر بن القوّاس، مجهول، من السادسة. التقريب (١/ ٢٢٤)."],[14204,"٢٤٥٩ - لم أقف له على ترجمة عند غير المؤلف."],[14205,"(٣) سيّار: أوله سين مهملة ثم ياء معجمة باثنتين من تحتها وآخره راء. الاكمال (٤/ ٤٢٣)."],[14206,"(٤) لم أقف عليه."],[14207,"٢٤٦٠ - لم أقف له ترجمة عند غير المؤلف."],[14208,"(٥) سيّارة: كالذى قبله، وبزيادة التاء المربوطة في آخره. تبصير المنتبه (٢/ ٧٠٤)."],[14209,"(٦) زحر: أوله زاى بعدها حاء مهملة كما في الاكمال (٤/ ١٧٨) وقال في التقريب (١/ ٥٣٣) عبيد اللَّه بن زحر: بفتح الزاى وسكون المهملة، الضمرى، مولاهم الإفريقى، صدوق، يخطئ، من السادسة وانظر الجرح (٢/ ٢/ ٣١٥)."],[14210,"٢٤٦١ - أبو سَوْرة (١)، ابن أخى أيوب الأنصارى، روى عن أبى أيوب روى عنه واصل بن السائب (٢)."],[14211,"٢٤٦٢ - أبو سهيل بن مسلم، روى عن أنس بن مالك، عن النبى عليه السلام أنه قال: \"طلب العلم فريضة على كل مسلم\" (٣). روى عنه إسماعيل بن عيّاش."],[14212,"٢٤٦١ - تاريخ ابن معين (٢/ ٧٠٩) وقال: يقال: أنه ليس هو أبو أيوب، صاحب النبى -صلى الله عليه وآله وسلم-، هو رجل آخر. اهـ. الجرح (٤/ ٢/ ٣٨٨) وقال: سألت أبا زرعة عن أبى سورة فقال: أبو سورة هو ابن أخى أبى أيوب. الثقات (٥/ ٥٧٠)، كنى الحاكم (١/ ٢١٧/ أ) الميزان (٤/ ٥٣٥) وقال: قال البخارى عنده مناكير، اللسان (٧/ ٤٦٨) وقال أيضًا قال البخارى: منكر الحديث. التهذيب (١٢/ ١٢٤)، التقريب (٢/ ٤٣٢) وقال: ضعيف، من الثالثة./ د. ت. ق. وقد أخرج أبو داود \"الجهاد\" باب الجعائل في الغزو (٣/ ١٦) حديثا من طريق أبى سلمة سليمان بن سليم، عن يحيى بن جابر الطائى، عن ابن أخى أبى أيوب الأنصارى، عن أبى أيوب أنه سمع رسول اللَّه -صلى الله عليه وآله وسلم- يقول: ستفتح عليكم الأمصار وستكون جنود مجندة، تقطع عليكم فيها بعوث فيكره الرجل منكم البعث فيها فيتخلَّص من قومه ثم يتصفّح القبائل يعرض نفسه عليهم يقول: من أكفيه بعث كذا؟ من أكفيه بعث كذا؟ إلا وذلك الأجير إلى آخر قطرة من دمه. اهـ."],[14213,"قلت: إن كان أخو أبى أيوب الذى جاء في هذا الحديث هو أبو سورة صاحب هذه الترجمة فهو صريح في أنه ابن أخى أبى أيوب الصحابى رضي الله عنه. واللَّه أعلم."],[14214,"(١) سَوْرة: بفتح أوله وسكون الواو بعدها راء. كما في التقريب (٢/ ٤٣٢)."],[14215,"(٢) واصل بن السائب الرقاشى، أبو يحيى البصرى، ضعيف، من السادسة (ت: ١٤٤). انظر التقريب (٢/ ٣٢٨)."],[14216,"٢٤٦٢ - الجرح (٤/ ٢/ ٣٨٨)."],[14217,"(٣) الحديث أخرجه ابن ماجه \"المقدمة\" باب فضل العلماء والحث على طلب ="],[14218,". . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . ."],[14219,"= العلم (١/ ٨١) وابن عبد البر في جامع بيان العلم وفضله (١/ ٧ - ٩) وأبو نعيم في الحلية (٨/ ٣٢٣) والخطيب في التاريخ (٤/ ١٥٧ و٢٠٨ و٧/ ٣٨٦ و٩/ ١١١ و١٠/ ٥٣٧ و١١/ ٤٢٤) وابن عدى في الكامل والحاكم في الكنى، والبيهقى في شعب الإيمان وابن عساكر في التاريخ وابن النجار. كما في الجامع الكبير للسيوطى (١/ ٥٦٦) كلهم أخرجوه من حديث أنس رضي الله عنه وله عند بعضهم طرق. وقال السندى: في حاشيته على ابن ماجه: في الزوائد: إسناده ضعيف. قال: قال السيوطى سئل الشيخ محيى الدين النووى رحمه اللَّه تعالى عن هذا الحديث فقال: إنه ضعيف أى سندًا، وإن كان صحيحًا أى معنى، وقال تلميذه جمال الدين المزى: هذا الحديث روى من طرق تبلغ رتبة الحسن وهو كما قال، فإنى رأيت له خمسين طريقا وقد جمعتها في جزء. اهـ. والحديث أخرجه أيضًا الخطيب في التاريخ (٤/ ٤٢٧)، والطبرانى في الأوسط. كما في مجمع الزوائد (١/ ١٢٠) وقال الهيثمى: فيه يحيى بن هاشم السمسار كذاب وأخرجه الخطيب في التاريخ (١/ ٤٠٨) من حديث على رضي الله عنه. ومن حديث الحسين بن على أخرجه أيضًا الخطيب في التاريخ ٥/ ٢٠٤، والطبرانى في الصغير ١/ ٢٩، وقال الهيثمى مجمع الزوائد (١/ ١٢٠): فيه عبد العزيز بن أبى ثابت ضعيف جدا. وأخرجه تمام في الفوائد (٥١ و٥٦) من حديث ابن عمر ومن حديث أبى سعيد الخدرى (٥٢) ومن حديث ابن عباس (٥٣) و(٥٤) ومن حديث ابن مسعود (٥٥) كلهم أخرجوه مرفوعًا بهذا اللفظ."],[14220,"حرف الشين"],[14221,"باب أبى شعيب"],[14222,"٢٤٦٣ - أبو شعيب الحضرمى، شامى، روى عن أبى أيوب الأنصارى، روى عنه عثمان بن أبى سودة، من حديث - الأوزاعى، عن عثمان بن أبى سودة."],[14223,"٢٤٦٤ - أبو شعيب، رأى عبد اللَّه بن عمر يحلق عنه الشعر من حديث وكيع عن عبيد بن عبد الملك (١)."],[14224,"٢٤٦٥ - أبو شعيب سمع الحسن وقتادة ويونس بن عبيد. روى عنه يزيد بن هارون."],[14225,"٢٤٦٦ - أبو شعيب (٢) روى عن طاوس عن ابن عمر في الركعتين قبل"],[14226,"٢٤٦٣ - الجرح (٤/ ٢/ ٣٨٩)، الثقات (٥/ ٥٧٢) وقال: يروى عن عبد اللَّه بن عمرو، كنى الحاكم (١/ ٢٤٤/ أ) وقال: أبو شعيب ويقال: أبو الأشعث الحضرمى. كنى ابن منده (١٥٧/ أ)، المقتنى في سرد الكنى (٧٠/ أ)."],[14227,"٢٤٦٤ - الجرح (٤/ ٢/ ٣٨٩) وذكره كما هنا تمامًا، كنى ابن منده (١٥٧/ أ)."],[14228,"(١) عبيد بن عبد الملك أبو عبد الملك الأسدى ذكره ابن أبى حاتم في الجرح (٢/ ٢/ ٤١١) وذكر رواية وكيع عنه. وقال: سألت أبى عنه فقال: ما به بأس."],[14229,"٢٤٦٥ - الجرح (٤/ ٢/ ٣٨٩)، كنى الحاكم (١/ ٢٢٤/ أ) وقال: أبو شعيب شيخ من بنانه. ثم ذكره وقال: قاله محمد بن إسماعيل."],[14230,"٢٤٦٦ - كنى ابن منده (١٥٧/ أ)، الجرح (٤/ ٢/ ٣٨٩)، الثقات (٦/ ٤٤٠) التهذيب (٤/ ٣٥٨)، التقريب (١/ ٣٥٣) وقال: بصرى، لا بأس به يقال: اسم أبيه بيان، من السابعة./ د."],[14231,"(٢) في الثقات، والتهذيب والتقريب \"شعيب\" من غير ذكر الكنية وقال ابن حجر في التهذيب (٤/ ٣٥٨) قال أبو داود عن ابن معين وهم شعبة إنما هو شعيب\"."],[14232,"المغرب (١). (ذكر إسحاق بن) (٢) منصور عن يحيى بن معين أنه قال: أبو شعيب الذى روى عن طاوس عن ابن عمر مشهور بصرى (٣)."],[14233,"٢٤٦٧ - أبو شعيب روى عن جده (٤) عن ابن مسعود، روى عنه عبد اللَّه ابن عون بصرى."],[14234,"(١) الحديث أخرجه أبو داود \"الصلاة\" باب الصلاة قبل المغرب (٢/ ٢٦) من طريق ابن بشارتنا محمد بن جعفر، ثنا شعبة، عن أبى شعيب، عن طاووس، قال: سئل ابن عمر عن الركعتين قبل المغرب فقال: ما رأيت أحدًا على عهد رسول اللَّه -صلى الله عليه وآله وسلم- يصليهما ورخص في الركعتين بعد العصر، قال أبو داود: سمعت يحيى بن معين يقول: هو شعيب -يعنى وهم شعبة في اسمه- اهـ. ومن طريق أبى داود أخرجه البيهقى (٢/ ٤٧٦ - ٤٧٧) به."],[14235,"(٢) غير واضح في الأصل والمثبت عن الجرح."],[14236,"(٣) انظر الجرح (٤/ ٢/ ٣٨٩)."],[14237,"٢٤٦٧ - الجرح (٤/ ٢/ ٣٨٩)، كنى الحاكم (١/ ٢٢٤/ أ) وذكره كما هنا وقال قاله محمد بن إسماعيل، كنى ابن منده (١٥٧/ أ)، المقتنى في سرد الكنى (١٧٠/ أ)."],[14238,"(٤) لم أقف على من سمى جده هذا."],[14239,"باب أبى شيبة"],[14240,"٢٤٦٨ - أبو شيبة. روى عن عمرو بن عبسة (١)، روى عنه جنادة بن أبى خالد (٢). هكذا قال أبو أحمد الحاكم. وقال أبو شيبة المهرى. روى عن ثوبان. روى عنه بلج (٣) المهرى - جعلهما رجلين. وقال ابن أبى حاتم: عن أبيه أبو شيبة المهرى. روى عن ثوبان وعمرو بن عبسة. روى عنه (بلج وجنادة بن أبى خالد) (٤) جعله رجلًا واحدًا. وقال: سئل أبو زرعة عن أبى شيبة المهرى فقال: هو من التابعين لا أعرف اسمه."],[14241,"٢٤٦٨ - كنى مسلم (ص ٤٩٦) وقال: أبو شيبة سمع عمرو بن عنبسة روى عنه جنادة بن أبى أمية. الجرح (٤/ ٢/ ٣٩٠) وذكره كما ذكره ابن عبد البر عنه. الثقات (٥/ ٥٨٩) وقال: أبو شيبة المهرى، يروى عن عمرو بن عبسة وثوبان. روى عنه جنادة بن أبى خالد، كنى ابن منده (٥٥/ أ)، المقتنى في سرد الكنى (٧٠/ ب)، كنى الحاكم (١/ ١٢٨/ ب) و(١/ ٢١٩/ أ)، تعجيل المنفعة (ص ٣٢٥) وجعلهما رجلًا واحدًا كما فعل ابن أبى حاتم وآخرون."],[14242,"(١) هو أبو نجيح تقدم في الصحابة (١٩٩)."],[14243,"(٢) جنادة بن أبى خالد الدمشقى، ذكره ابن أبى حاتم في الجرح (١/ ١/ ٥١٥) وذكر روايته عن أبى شيبة المهرى ولم يذكر فيه شيئًا."],[14244,"(٣) بلج: بفتح الباء وسكون اللام. كما في الاكمال (١/ ٣٥٠) وقال: بلج المهرى عن أبى شيبة المهرى عن ثوبان. وقال ابن حجر في اللسان (٢/ ٦٣): بلج المهرى، عن أبى شيبة المهرى عن ثوبان قاء فأفطر لا يدرى من ذا ولا من شيخه. رواه شعبة عن أبى الجودى عنه قال البخارى إسناده ليس بمعروف. اهـ. وذكره ابن حبان في الثقات (٦/ ١١٨) فقال بلج بن عبد اللَّه المهرى. وذكر روايته عن أبى شيبة المهرى عن ثوبان. فاللَّه أعلم."],[14245,"(٤) في الأصل \"بلج بن أبى جنادة\" ولم أقف على من اسمه بلج بن أبى جنادة والمثبت في الجرح وفى تعجيل المنفعة وفى المراجع الأخرى \"بلج وجنادة ابن أبى خالد\" كما أثبته وهو الصواب واللَّه أعلم."],[14246,"٢٤٦٩ - أبو شيبة (١)، روى عن عيسى بن الحارث (٢)، روى عنه شعبة بن الحجاج."],[14247,"٢٤٧٠ - أبو شيبة المكى، روى عن عكرمة، عن ابن عباس أنه كان ينام بين جاريتين (٣). روى عنه عباد بن العوام وابن أبى زائدة."],[14248,"٢٤٦٩ - كنى الحاكم (١/ ٢١٩/ أ)، المقتنى في سرد الكنى (٧٠/ ب)."],[14249,"(١) ذكر ابن أبى حاتم في ترجمة شيخه عيسى بن الحارث كما سيأتى أنه أبو شيبة جد بنى أبى شيبة."],[14250,"(٢) عيسى بن الحارث ذكره ابن أبى حاتم في الجرح (٣/ ١/ ٢٧٤) وذكر رواية أبى شيبة جد بنى شيبة عنه. وقال: سألت أبا زرعة عنه فقال: لا بأس به."],[14251,"٢٤٧٠ - الجرح (٤/ ٢/ ٣٩٠) وقال: سئل أبو زرعة عن أبى شيبة المكى فقال: روى عنه ابن أبى زائدة وعباد بن العوام، ولا يعرف اسمه. كنى الحاكم (١/ ٢١٩/ أ)."],[14252,"(٣) أخرجه الحاكم في الكنى وابن أبى حاتم في الجرح. انظر مصادر الترجمة وأخرجه أيضًا ابن أبى شيبه (٤/ ٣٨٩) من طريق عباد بن العوام عن أبى شيبة قال: سمعت عكرمة يحدث عن ابن عباس قال: كان ينام بين جاريتين. وأخرج ابن أبى شيبة عن عطاء أيضًا أنه كان لا يرى بأسا أن ينام الرجل بين الامتين."],[14253,"باب أبى شداد"],[14254,"٢٤٧١ - أبو شداد عقل متوفى رسول اللَّه -صلى الله عليه وآله وسلم- ولم يره ولم يسمع منه ودخل على أبى أمامة الباهلى. روى عنه معاوية بن صالح."],[14255,"٢٤٧١ - كنى الحاكم (١/ ٢٢٦/ أ) ذكره كما هنا وقال: حديثه في الشاميين كنى ابن منده (٥٥/ أ)."],[14256,"قلت: وقد تقدم أبو شداد عقل متوفى رسول اللَّه -صلى الله عليه وآله وسلم- ولم يره. في الصحابة. انظر الترجمة (٣٣٤) فاللَّه أعلم."],[14257,"باب أبى شعبة"],[14258,"٢٤٧٢ - أبو شعبة (١) مولى سويد بن مُقَرِّن (٢)، روى عنه محمد بن المنكدر، يعد في أهل الحجاز."],[14259,"٢٤٧٣ - أبو شعبة الأشجعى، رجل من أهل البصرة، روى عن - عبد اللَّه ابن عمر، روى هلال بن يساف."],[14260,"٢٤٧٤ - أبو شعبة الدُّهْنِى (٣)، وقيل التميمى، رأى الحسن والحسين وروى عن أبى ذر، روى عنه ليث بن أبى سليم، وعمار بن معاوية الدهنى، وسفيان بن عيينة."],[14261,"٢٤٧٢ - كنى مسلم (ص ٥٠٠)، الجرح (٤/ ٢/ ٣٨٩)، الثقات (٥/ ٥٧٢)، كنى ابن منده (٥٦/ أ)، المقتنى في سردر الكنى (٦٩/ ب) وذكر أنه روى عن سويد بن مقرن، كنى الحاكم (١/ ٢١٩/ ب)، التهذيب (١٢/ ١٢٦)، التقريب (٢/ ٤٣٤) وقال: أبو شقيط، المدنى، مولاهم الكوفى، مقبول، من الثالثة./ بخ. م. س."],[14262,"(١) زاد في التهذيب \"المدنى\"."],[14263,"(٢) سويد بن مُقَرِّن، بضم ففتح فكسر مع التشديد، المزنى، صحابى مشهور، نزل الكوفة. التقريب (١/ ٢٤١)."],[14264,"٢٤٧٣ - الجرح (٤/ ٢/ ٣٩٠)، كنى الحاكم (١/ ٢١٩/ ب)، كنى ابن منده (١٥٦/ ب)، المقتنى في سرد الكنى (٦٩/ ب)."],[14265,"٢٤٧٤ - كنى مسلم (ص ٥٠٠)، كنى الحاكم (١/ ٢١٩/ ب)، كنى ابن منده (١٥٦/ ب)."],[14266,"(٣) الدُّهْنِى: بضم الدال المهملة وسكون الهاء وفى آخرها نون نسبة إلى دُهْن ابن معاوية بن أسلم بن أحمس بن الغوث بن انمار وهو بطن من بَجِيْلة. اهـ. اللباب (١/ ٥٢٠)."],[14267,"٢٤٧٥ - أبو شعبة عن عبد الرحمن بن فارس الغفارى وقيل: ابن الفارس بن الأبلق روى عنه عبد الملك بن ميسرة، يعد في الكوفيين."],[14268,"٢٤٧٦ - أبو شعبة الحنفى ويقال: الحنظلى روى عنه ابنه الربيع أو أبو الربيع (١)."],[14269,"٢٤٧٥ - الجرح (٤/ ٢/ ٣٩٠)، كنى الحاكم (١/ ٢٢٠/ أ)، كنى ابن منده (٥٦/ ب)، المقتنى (٦٩/ ب) وقال: أبو شعبة عن أبى فارس وعنه عبد الملك. اهـ."],[14270,"٢٤٧٦ - كنى ابن منده (١٥٦/ ب) وقال: أبو شعبة الحنفى حدث عن أبى الربيع روى عنه أبو تميلة يحيى بن واضح. كنى الحاكم (١/ ٢٢٠/ أ) وقال: أبو شعبة الحنفى، قال: حدثنى الربيع أو أبو الربيع الحنظلى سمع ابن عمر رأيت النبى -صلى الله عليه وآله وسلم- لا يقدم ويؤخر\" رواه عنه زيد بن خباب قاله محمد بن إسماعيل."],[14271,"(١) لم أقف له على ترجمة."],[14272,"باب أبى الشعثاء"],[14273,"٢٤٧٧ - أبو الشّعثاء الكوفى، روى عن ابن عمر، وابن عباس اختلف فيه، روى عنه أبو سنان (١) وسعيد بن سعيد التغلبى (٢) وقد قيل: (أن الذى) (٣) روى عنه سعيد بن سعيد التغلبى غير الكندى الذى روى عنه أبو سنان (وأن الذى روى عنه سعيد بن سعيد التغلبى غير الكندى الذى روى عنه أبو سنان) (٤) وإن الذى روى عنه سعيد بن سعيد لم يرو عنه ابن عباس."],[14274,"وقال على بن المدينى. أبو الشعثاء الذى روى عنه أبو إسحاق الهمدانى، ويونس بن أبى إسحاق، وأبو العنبس (٥)، وأبو سنان هو الكندى، وليس هو أبو الشعثاء سليم والد أشعث (٦)، (٧) وقال ابن أبى حاتم: خالف أبى عليا في ذلك"],[14275,"٢٤٧٧ - الجرح (٤/ ٣٩١/٢)، كنى الحاكم (١/ ٢٢١/ ب) وذكره مختصرًا وقال قاله محمد بن إسماعيل."],[14276,"(١) زاد في الجرح \"الشيبانى\" ولعله أبو سنان سعيد بن سنان الشيبانى الكوفى. المتقدم في الكتاب الثانى (١١٠٤)."],[14277,"(٢) سعيد بن سعيد التغلبى: بمثناة ومعجمة، الكوفى أبو الصباح مقبول، من السادسة./ س. التقريب (١/ ٢٩٧) وذكره ابن أبى حاتم في الجرح (٢/ ١/ ٢٥) وذكر روايته عن أبى الشعثاء ولم يذكر فيه شيئًا."],[14278,"(٣) غير واضح في الأصل. والسياق يقتضى إثباته فأثبت."],[14279,"(٤) هكذا مكرر في الأصل. وهو كما يبدو سهو من الناسخ."],[14280,"(٥) هو الأكبر تقدم في (٢٢٤٥) وذكر ابن أبى حاتم في الجرح (٤/ ٢/ ٤١٩) في ترجمة أبى العنبس أنه روى عن أبى الشعثاء عن ابن عباس."],[14281,"(٦) هو أبو الشعثاء المحاربى سليم بن أسود تقدم في الكتاب الثانى (١١٤٣)."],[14282,"(٧) انظر قول ابن المدينى هذا في كنى الحاكم (١/ ٢٢١/ أ) في ترجمة أبى الشعثاء يزيد بن مهاصر الكندى. وفى الجرح (٤/ ٢/ ٣٩١) في ترجمة أبى الشعثاء الكوفى وهى الترجمة التى نحن بصددها."],[14283,"فقال: أبو الشعثاء الكندى اسمه يزيد بن مهاصر (١)، (٢)."],[14284,"٢٤٧٨ - أبو الشعثاء، قنبر مولى عمر بن عبيد اللَّه معمر، سمع عبد اللَّه بن عباس، وعبد اللَّه بن عمر، روى عنه (صالح بن عبيد) (٣) والمثنى بن سعيد (٤)، يعد في البصريين."],[14285,"٢٤٧٩ - أبو الشعثاء، عن عبد اللَّه بن بريدة (وعنه) (٥) عبد الملك بن أبى سليمان إن صح عنه."],[14286,"(١) ذكره ابن أبى حاتم في الجرح (٤/ ٢/ ٢٨٧) فقال: أبو يزيد بن مهاصر أبو الشعثاء الكندى كوفى، روى عنه أبو إسحاق الهمدانى وأبو العنبس بن أبى إسحاق وأبو سنان الشيبانى. ولم يذكر فيه شيئا."],[14287,"(٢) ذكره في ترجمة أبى الشعثاء الكوفى بعد قول ابن المدينى. انظر الجرح (٤/ ٢/ ٣٩١)."],[14288,"٢٤٧٨ - تقدم في الكتاب الثانى (١١٤٤) أبو الشعثاء قنبر مولى ابن عمر سمع ابن عمر وابن عباس روى عنه صالح السلمى وأبو غفار. والظاهر أن الترجمتين لرجل واحد. واللَّه أعلم."],[14289,"(٣) هكذا هنا \"صالح بن عبيد\" وفى ترجمة أبى الشعثاء المتقدمة في (١١٤٤) صالح السلمى. وقد تقدمت ترجمته هناك."],[14290,"(٤) هو أبو غفار تقدم في الكتاب الثانى (١٠٣٦)."],[14291,"٢٤٧٩ - كنى ابن منده (١٥٦/ ب)، كنى الحاكم (١/ ١٢١/ ب) وقال: أبو الشعثاء عن أبى سهل عن عبد اللَّه بن بريدة الأسلمى، روى عن أبى عبد اللَّه عبد الملك بن أبى سليمان الفزارى عنه إن كان ذلك محفوظًا ثم ذكر إسناد حديثه من طريق صالح بن أبى الأسود عن عبد الملك بن أبى سليمان عن أبى الشعثاء عن عبد اللَّه بن بريدة عن أبيه فذكر حديثًا مسندًا، المقتنى في سرد الكنى (٦٩/ ب)."],[14292,"(٥) في الأصل \"وعن\" والمثبت عن مصادر الترجمة."],[14293,"باب أبى شمر"],[14294,"٢٤٨٠ - أبو شمر (١) الضبعى. سمع عائذ بن عمرو المزنى (٢) وأبا عثمان النهدى. روى عنه شعبة."],[14295,"٢٤٨١ - أبو شِمْر عن ابن أبى ملكيه. روى عنه الصلت بن طريف (٣)."],[14296,"٢٤٨٠ - الجرح (٤/ ٢/ ٣٩١) وقال: سألت أبى عنه فقال: شيخ، الثقات (٥/ ٥٦٩)، كنى الحاكم (١/ ٢٢٧/ ب)، كنى ابن منده (٥٦/ أ)، تهذيب الكمال (٣/ ١٦١٤)، التهذيب (١٢/ ١٢٧)، التقريب (٢/ ٤٣٤)، وقال: مقبول، من الرابعة./ م. س."],[14297,"(١) شِمرْ، بكسر أوله، وسكون الميم. كما في التقريب (٢/ ٤٣٤)."],[14298,"(٢) عائذ بن عمرو المزنى، أبو هبيرة البصرى، صحابى. شهد الحديبية مات في ولاية عبيد اللَّه بن زياد، سنة إحدى وستين. انظر التقريب (١/ ٣٩٠)."],[14299,"٢٤٨١ - كنى ابن منده (٥٦/ أ) وقال: أراه الأول. اهـ."],[14300,"قلت: والأول عنده هو أبو شمر الأدمرى، شامى عن كعب روى عنه شريح بن عبيد، كنى الحاكم (١/ ٢٢٧/ ب)، المقتنى في سرد الكنى (٧٠/ أ)."],[14301,"(٣) صلت بن طريف، ذكره ابن أبى حاتم في الجرح (٢/ ١/ ٤٤٠) وذكر روايته عن أبى شمر ولم يذكر فيه شيئًا. اهـ."],[14302,"باب الإفراد في الكنى من الشين"],[14303,"٢٤٨٢ - أبو الشِّمَال (١) بن ضِبَاب (٢). روى عن أبى أيوب الأنصارى عن النبى -صلى الله عليه وآله وسلم- أنه قال: \"أربع من سنن المرسلين، الحياء والسواك والتعطر والنكاح\" (٣). روى عنه مكحول."],[14304,"٢٤٨٢ - كنى مسلم (ص ٥١١)، الجرح (٤/ ٢/ ٣٩٠) وقال: سئل أبو زرعة عن أبى الشمال فقال: لا أعرفه إلا في هذا الحديث، ولا أعرف اسمه، كنى ابن منده (١٥٨/ أ)، تهذيب الكمال (٣/ ١٦١٤)، الميزان (٤/ ٥٣٦) وذكر حديثه وقال: لا يعرف إلا بهذا الحديث. قاله أبو زرعة، كنى الحاكم (١/ ٢٢٩/ ب)، اللسان (٧/ ٤٦٨)، التهذيب (١٢/ ١٢٧)، التقريب (٢/ ٤٣٤) وقال: مجهول، من الثالثة./ ت."],[14305,"(١) الشمال: بكسر أوله وتخفيف الميم، اللسان (٧/ ٤٦٨)."],[14306,"(٢) ضِبَاب: بكسر المعجمة، وبموحدتين، اللسان (٧/ ٤٦٨)."],[14307,"(٣) الحديث أخرجه أبو أحمد الحاكم في الكنى (١/ ٢٢٩/ ب)، والمزى في تهذيب الكمال (٢/ ١٦١٤)، والترمذى \"النكاح\" باب ما جاء في فضل التزويج (٤/ ١٩٦)، وقال: حسن غريب من طريق حفص بن غياث عن الحجاج، عن مكحول، عن أبى الشمال، عن أبى أيوب مرفوعًا به، وروى الترمذى أيضًا في نفس الباب (٤/ ١٩٨) الحديث من طريق عباد بن العوام، عن الحجاج، عن مكحول، عن أبى الشمال، عن أبى أيوب مرفوعًا به نحو حديث حفص بن غياث، وقال الترمذى: روى هذا الحديث هشيم ومحمد ابن يزيد الواسطى، وأبو معاوية وغير واحد، عن الحجاج، عن مكحول، عن أبى أيوب قلت: ولم يذكروا فيه \"عن أبى الشمال\" قال: وحديث حفص بن غياث وعباد بن العوام أصح. اهـ."],[14308,"وأخرجه أحمد (٥/ ٤٢١) من طريق يزيد ومحمد بن يزيد كلاهما عن الحجاج عن مكحول، عن أبى أيوب به، ولم يذكر في سنده \"أبو الشمال\" والحديث ذكره السيوطى في الجامع الصغير (١/ ٣٧) وعزاه إلى أحمد = ٢٤٨٣ - أبو شيخ، روى عن شريح قوله، روى عنه أبو يعفور العبدى."],[14309,"٢٤٨٤ - أبو شريح. روى عن أبى مسلم (١)، روى عنه محمد بن زيد."],[14310,"٢٤٨٥ - أبو شرقى (٢)، روى عن أبى عثمان النهدى، روى عنه شعبة."],[14311,"٢٤٨٦ - أبو شهدة، حديثه عند حكيم (٣) بن محمد بن طلحة"],[14312,"= والترمذى وإلى البيهقى في شعب الإيمان، ورمز السيوطى لحسنه، وذكر الحافظ في تلخيص الحبير (١/ ٦٦) حديث أبى أيوب هذا وقال: رواه أحمد والترمذى وقال أيضًا: رواه ابن أبى خيثمة وغيره من حديث مليح بن عبد اللَّه عن أبيه عن جده نحوه، ورواه الطبرانى من حديث ابن عباس. اهـ."],[14313,"٢٤٨٣ - الجرح (٤/ ٢/ ٣٩١)."],[14314,"٢٤٨٤ - كنى ابن منده (١٥٨/ ب)، المقتنى في سرد الكنى (٦٩/ أ)، الجرح (٤/ ٢/ ٣٩١)، الثقات (٧/ ٦٦٠)، كنى الحاكم (١/ ٢٢٢/ ب) التهذيب (١٢/ ١٢٦)، التقريب (٢/ ٤٣٤) وقال: مقبول، من السادسة./ ق"],[14315,"(١) زاد في التهذيب \"مولى زيد بن صوحان\" وقد تقدم أبو مسلم العبدى مولى زيد بن صوحان في (١٨٠٣) وذكر ابن عبد البر في ترجمته هناك أنه روى عنه أبو شريح."],[14316,"٢٤٨٥ - كنى مسلم (ص ٥١١)، الجرح (٤/ ٢/ ٣٩١)، الثقات (٧/ ٦٥٩)، المقتنى في سرد الكنى (٦٩/ أ)، كنى الحاكم (١/ ٢٢٩/ ب). الاكمال (٥/ ٥١)، وقال: أبو شرقى الضبى عن أبى عثمان النهدى روى عنه شعبة."],[14317,"(٢) شَرْقِىَّ بالقاف وتشديد الياء. كما في الاكمال (٥/ ٥١)."],[14318,"٢٤٨٦ - الجرح (٤/ ٢/ ٣٩١)، كنى ابن منده (٥٨/ ب)، كنى الحاكم (١/ ٢٣٠/ أ)، المقتنى في سرد الكنى (٧٠/ أ) وقال: أبو شهدة حكى عنه طلحة."],[14319,"(٣) هكذا في الأصل \"حكيم\" وكذا في الجرح. والذى في كنى الحاكم كنى ابن منده \"الحكم\" وذكر ابن أبى حاتم في الجرح (١/ ٢/ ١٢٧) الحكم ابن محمد أبو مضر مصرى. روى عن الحسن بن غالب وعقبة بن سنان وأبى الهيثم الضمرى، والقاسم بن عبد الرحمن، وطلحة، روى عنه سعيد بن أبى أيوب، ولم يذكر فيه شيئًا. فاللَّه أعلم."],[14320,"عن طلحة (١) (عنه قوله) (٢)."],[14321,"٢٤٨٧ - أبو شهاب، روى عن زيد بن اسلم، روى عنه يحيى بن سعيد العطار."],[14322,"(١) طلحة، ذكر ابن أبى حاتم في الجرح (٢/ ١/ ٤٨١) طلحة بن سمرة روى عن. . روى عنه الحكم بن محمد وقال ابن أبى حاتم: سمعت أبى يقول: هما مجهولان -يعنى طلحة والحكم- أهـ."],[14323,"وقال الذهبى في الميزان (٢/ ٣٤٤) طلحة عن أبى شهدة، شيخ للحكم ابن محمد مجهولان. اهـ."],[14324,"(٢) غير واضح في الأصل، وهو في مصادر الترجمة كما أثبته."],[14325,"٢٤٨٧ - الجرح (٤/ ٢/ ٣٩١ - ٣٩٢) وقال: سألت أبى عنه فقال: هو مجهول، الميزان (٤/ ٥٣٦) وقال: مجهول، اللسان (٧/ ٦٣) وقال: أيضا مجهول."],[14326,"حرف الهاء"],[14327,"باب أبى الهيثم"],[14328,"٢٤٨٨ - أبو الهيثم بن نصر بن دهر الاسلمى. روى عنه أبيه (١) مدنى روى عنه محمد بن إبراهيم بن الحارث التيمى."],[14329,"٢٤٨٩ - أبو الهيثم الضمرى (٢). روى عن سعيد بن أبى عمرة (٣). روى عنه الحكم بن محمد."],[14330,"٢٤٩٠ - أبو الهيثم، روى عن الحسن بن أبى الحسن، روى عنه أبو معاوية محمد بن خازم الضرير."],[14331,"٢٤٨٨ - كنى البخارى (ص ٧٩)، كنى مسلم (ص ١٠٥٠)، الجرح (٤/ ٢/ ٤٥٣) تهذيب الكمال (٣/ ١٦٥٧)، الميزان (٤/ ٥٨٣)، المقتنى في سرد الكنى (١٤٣/ ب)، اللسان (٧/ ٤٨٨)، التهذيب (١٢/ ٢٦٩)، التقريب (٢/ ٤٨٥) وقال: مقبول، من الثالثة، وقيل: اسمه عامر./ س."],[14332,"(١) نصر بن دهر بن الاخرم، الاسلمى، صحابى، نزل المدينة، تفرد ابنه أبو الهيثم بالرواية عنه. التقريب (٢/ ٢٩٩) وانظر التجريد (٢/ ١٠٥)."],[14333,"٢٤٨٩ - كنى البخارى (ص ٧٩)، الجرح (٤/ ٢/ ٤٥٣) وقال: سمعت أبى يقول: هو مجهول، الميزان (٤/ ٥٨٤) وقال: لا يعرف، اللسان (٧/ ١١٩) وقال: لا يعرف، المقتنى في سرد الكنى (١٤٣/ ب)."],[14334,"(٢) في الميزان \"البصرى\"."],[14335,"(٣) سعيد بن أبى عمرة الأنصارى، ذكره ابن أبى حاتم في الجرح (٢/ ١/ ٥٣) وقال: روى الحكم بن محمد عن أبى الهيثم عنه. . سمعت أبى يقول: هم مجهولون."],[14336,"٢٤٩٠ - كنى البخارى (ص ٧٩)، الثقات (٧/ ٦٦٧). المقتنى في سرد الكنى (١٤٣/ ب)."],[14337,"٢٤٩١ - أبو الهيثم شامى، روى عن ابن شهاب، روى عنه بقية بن الوليد الكلاعى حديثا لم يتابع عليه."],[14338,"٢٤٩٢ - أبو الهيثم (١) صاحب القصب كوفى، روى عن سعيد بن المسيب وسعيد بن جبير، وإبراهيم النخعى، روى عنه سفيان الثورى، واسرائيل بن يونس، وعلى بن صالح بن حى، قيل: ان اسمه عمار. وقيل: ان عمارا إنما هو اسم أبى الهيثم العطار كذاك قال البخارى (٢)."],[14339,"٢٤٩١ - الميزان (٤/ ٥٨٤) وقال: لا يعرف. اللسان (٧/ ١١٩) وقال أيضا: لا يعرف. المقتنى في سرد الكنى (١٤٤/ أ) وقال: أبو الهيثم عن الزهرى وعنه بقية بخبر منكر."],[14340,"٢٤٩٢ - كنى البخارى (ص ٧٩) وجعله غير أبى الهيثم العطار فقال: أبو الهيثم العطار. ويقال: الهيثم فذكره ثم ذكر بعده أبا الهيثم صاحب القصب فقال: أبو الهيثم صاحب القصب سمع ابن المسيب وابن جبير، روى عنه الثورى، الكوفى، كنى مسلم (ص ١٠٥٠)، تاريخ ابن معين (٢/ ٧٣٠) الثقات (٧/ ٦٦٠)، تهذيب (٣/ ١٦٥٧)، المقتنى في سرد الكنى (١٤٣/ ب)، التهذيب (١٢/ ٢٦٩)، التقريب (٢/ ٤٨٥) وقال: صدوق، من السادسة. وقيل: اسمه عمار/ مد."],[14341,"قلت: وقد تقدم أبو الهيثم صاحب القصب عمار في الكتاب الثانى (١١٧٠) وقال ابن عبد البر في ترجمته هناك: اسمه عمار، كوفى، روى عن سعيد بن المسيب وسعيد بن جبير وإبراهيم النخعى، روى عنه الثورى، واسرائيل. وحسن وعلى ابنا صالح أهـ. وبالنظر إلى الترجمتين يظهر انهما لرجل واحد. واللَّه أعلم."],[14342,"(١) زاد ابن معين في التاريخ، وابن حبان في الثقات وابن حجر في التهذيب \"المرادى\"."],[14343,"(٢) سبقت الاشارة قبل قليل عند ذكر مصادر الترجمة إلى كلام البخارى، ولم يذكر البخارى في الكنى المجردة اسمه وإنما قال: أبو الهيثم العطار، ويقال: الهيثم. فاللَّه أعلم."],[14344,"باب أبى هلال"],[14345,"٢٤٩٣ - أبو هلال العتكى. روى عن على رضي الله عنه. روى عنه أبو بردة ابن أبى موسى الاشعرى. قال على بن المدينى: \"كان أبو هلال العتكى يقدم عثمان وينال من على وكان رجل سوء متهما في دينه\" (١)."],[14346,"٢٤٩٤ - أبو هلال الليثى، روى عن أبى هريرة، روى عنه عمر مولى غُفْرة (٢)."],[14347,"٢٤٩٣ - كنى البخارى (ص ٨٠)، الجرح (٤/ ٢/ ٤٥٤)، المقتنى في سرد الكنى (١٤٢/ ب) وقال: أبو هلال العكى."],[14348,"(١) لم أقف عليه من كلام على بن المدينى."],[14349,"٢٤٩٤ - كنى البخارى (ص ٨٠). الجرح (٤/ ٢/ ٤٥٥)، المقتنى في سرد الكنى (١٤٢/ ب)."],[14350,"(٢) عمر مولى غُفْرة: بضم المعجمة وسكون الفاء، هو عمر بن عبد اللَّه المدنى، مولى غفرة. ضعيف، وكان، كثير الإرسال من الخامسة، (ت: ١٤٥) أو (١٤٦). التقريب (٢/ ٥٩)."],[14351,"باب أبى هارون"],[14352,"٢٤٩٥ - أبو هارون (١) الواسطى. روى عن شريح في الدية أخماسا (٢) روى عنه شريك القاضى."],[14353,"٢٤٩٥ - كنى البخارى (ص ٨٠). الجرح (٤/ ٢/ ٤٥٤). المقتنى في سرد الكنى (١٤٠/ ب)."],[14354,"(١) زاد في كنى البخارى (بن كعب)."],[14355,"(٢) أخرجه البخارى في الكنى من طريق شريك عن أبى هارون الواسطى قال: وقعت ثنية ابن لعمر بن سعد فقضى شريح بخمس من الإبل وجعله أخماسا\". وأخرجه أيضا ابن أبى حاتم في الجرح من هذا الطريق به وفيه عنده وقعت ثنيتى ابن يعمر بن سعد فقضى شريح بخمس من الإبل وجعله أخماسا."],[14356,"وأخرج أبو داود \"الديات\" باب ديات الاعضاء (٤/ ١٨٩) والنسائى \"القسامة\" باب عقل الاسنان (٨/ ٥٥)، البيهقى \"الديات\" باب دية الاسنان (٨/ ٨٩) وابن أبى شيبة (٩/ ١٨٦) وعبد الرزاق (٩/ ٣٤٦) كلهم أخرجوه من حديث عمرو بن شعيب عن أبيه عن جده."],[14357,"قال: قال رسول اللَّه -صلى الله عليه وآله وسلم- \"في الاسنان خمس من الإبل\" وقال الألبانى في إرواء الغيل (٧/ ٣٢٠) هذا اسناد حسن. وأخرج ابن ماجه أيضا \"الديات\" باب دية الاسنان (٢/ ٨٨٥) حديث ابن عباس يرفعه \"أنه قضى في السن خمسا من الإبل\" وقال السندى \"في الزوائد: إسناده صحيح. وفى مسند أحمد (١/ ٣٨٤) من حديث ابن مسعود يرفعه \"ان رسول اللَّه -صلى الله عليه وآله وسلم- جعل الدية في الخطأ أخماسا\"."],[14358,"وأخرج ابن أبى شيبة (٩/ ١٨٨)، وعبد الرزاق (٩/ ٣٤٦) عن سليمان بن موسى قال: في كتاب عمر بن عبد العزيز إلى أمراء الاجناد وفى السن خمس من الإبل."],[14359,"٢٤٩٦ - أبو هارون الحجام مولى حماد بن عمران التيمى (١). قال: حجمت أبا بكر بن محمد بن عمرو بن حزم يوم السبت (٢) و(. . .) (٣) موضع محاجمة روى عنه معن بن عيسى."],[14360,"٢٤٩٧ - أبو هارون الفلسطينى. روى عن عثمان بن عطاء (٤)، روى عنه سعيد بن كثير بن دينار (٥)."],[14361,"٢٤٩٦ - كنى البخارى (ص ٨٠)، الجرح (٤/ ٢/ ٤٥٤)، المقتنى في سرد الكنى (١٤٠/ أ)."],[14362,"(١) حماد بن عمران التيمى. ذكره ابن أبى حاتم في الجرح (١/ ٢/ ١٤٥) ولم يذكر فيه شيئا."],[14363,"(٢) أخرجه البخارى في الكنى وابن أبى حاتم في الجرح وفيه \"حجمت أبا بكر ابن محمد بن عمرو بن حزم يوم السبت\"."],[14364,"(٣) كلمة غير واضحة في الأصل."],[14365,"٢٤٩٧ - الجرح (٤/ ٢/ ٤٥٤) وقال: سألت أبى عنه فقال: مجهول."],[14366,"(٤) عثمان بن عطاء بن أبى مسلم الخراسانى أبو مسعود المقدسى، ضعيفين السابعة (ت: ١٥٥) وقيل (١٥١). التقريب (٢/ ١٢)."],[14367,"(٥) عثمان بن سعيد بن كثير بن دينار، القرشى، مولاهم أبو عمرو الحمصى ثقة عابد، من التاسعة (ت: / ٢٠٩). التقريب (٢/ ٩)."],[14368,"باب أبى هند"],[14369,"٢٤٩٨ - أبو هند البجلى شامى. روى عن معاوية بن أبى سفيان روى عنه عبد الرحمن بن أبى عوف (١)."],[14370,"٢٤٩٩ - أبو هند الدالانى ويقال له الهمدانى (٢). روى عن أبى (ظبيان روى عنه محمد بن قيس) (٣)، (٤)."],[14371,"٢٤٩٨ - كنى البخارى (ص ٨٠) وذكر حديثه من طريق أبى عون عن أبى هند البجلى، عن معاوية سمعت النبى -صلى الله عليه وآله وسلم- يقول: \"لا تنقطع الهجرة حتى تنقطع التوبة ثلاث مرات، ولا تنقطع التوبة حتى تطلع الشمس من مغربها\"، كنى مسلم (ص ١٠٦٢)، الجرح (٤/ ٢/ ٤٥٣) وقال: ذكر حديث معاوية في الهجرة، الميزان (٤/ ٥٨٣) وقال: لا يعرف اللسان (٧/ ٤٨٨) وقال: مجهول، التهذيب (١٢/ ٢٦٨)، التقريب (٢/ ٤٨٤) وقال: مقبول، من الثالثة/ د. س."],[14372,"(١) في كنى مسلم، واللسان زيادة \"الجرشى\". وعبد الرحمن بن أبى عوف الجرشى. بضم الجيم وفتح الراء بعدها معجمة، الحمصى القاضى، ثقة، من الثانية، يقال: أدرك النبى -صلى الله عليه وآله وسلم-. التقريب (١/ ٤٩٤)."],[14373,"٢٤٩٩ - كنى البخارى (ص ٨٠)، الجرح (٤/ ٢/ ٤٥٣)، الثقات (٧/ ٦٦٦) تهذيب الكمال (٣/ ١٦٥٧)، التهذيب (١٢/ ٢٦٨)، التقريب (٢/ ٤٨٤) وقال: مقبول، من السابعة./ بخ. عس، تعجيل المنفعة (ص ٣٤٤)."],[14374,"(٢) في تهذيب الكمال، والتهذيب، وتعجيل المنفعة، والتقريب زيادة \"اسمه الحارث بن عبد الرحمن\" وقد فرق ابن أبى حاتم في الجرح وابن حبان في الثقات بين أبى هند الحارث بن عبد الرحمن روى عن أبى الجلاس، وبين أبى هند الدلانى، الهمدانى صاحب هذه الترجمة."],[14375,"(٣) زاد في تهذيب الكمال، والثقات \"الاسدى\" وفى التقريب (٢/ ٢٠٢) محمد ابن قيس الاسدى الوالبى، بالموحدة، الكوفى، ثقة، من كبار السابعة. اهـ."],[14376,"(٤) غير واضح في الأصل والمثبت عن كنى البخارى، والجرح، والثقات، وتهذيب الكمال."],[14377,"٢٥٠٠ - أبو هند المرهبى. روى عن الضحاك. روى عنه شريك (١)."],[14378,"٢٥٠٠ - كنى البخارى (ص ٨٠)، تاريخ ابن معين (٢/ ٧٣٠)، الجرح (٤/ ٢/ ٤٥٤)، كنى الدولابى (٢/ ١٥٦)."],[14379,"(١) في كنى البخارى زيادة لفظ \"مرسل\"."],[14380,"باب أبى الهندى"],[14381,"٢٥٠١ - أبو الهندى. روى عن أنس بن مالك. روى عنه أبو عاصم النبيل الضحاك بن مخلد."],[14382,"٢٥٠٢ - أبو الهندى سمع أبا طالوت (١). روى عنه معتمر بن سليمان التيمى."],[14383,"٢٥٠١ - الجرح (٤/ ٢/ ٤٥٤)، الميزان (٤/ ٥٨٣) وقال: أبو الهندى، عن أنس بن مالك بحديث الطير، وعنه أبو عاصم. لا يعرف. اللسان (٧/ ١١٩) وقال: أبو هند ثم ذكره كما في الميزان."],[14384,"٢٥٠٢ - كنى البخارى (ص ٨١). الجرح (٤/ ٢/ ٤٥٤)، الميزان (٤/ ٥٨٣) وقال: لا يعرف، وكأنه الأول. فاللَّه اعلم. اهـ.، اللسان (٧/ ١١٩) وقال: أبو هند ثم ذكره كما في الميزان أيضًا."],[14385,"(١) تقدم في (١٦٩١) ذكر ابن عبد البر في ترجمته هناك أنه روى عنه أبو الهندى."],[14386,"باب أبى هشام"],[14387,"٢٥٠٣ - أبو هشام. روى عن أبى سعيد الخدرى. روى عنه عمرو بن دينار."],[14388,"٢٥٠٤ - أبو هشام. روى عن أبى معاذ. روى عنه سهل (١) العسكرى. قال أبو حاتم: أبو هشام وأبو معاذ مجهولان."],[14389,"٢٥٠٣ - كنى البخارى (ص ٨٠)، الجرح (٤/ ٢/ ٤٥٥)."],[14390,"٢٥٠٤ - الجرح (٤/ ٢/ ٤٥٥) وقال: سألت أبى عنه فقال: هما مجهولان، أبو هشام وأبو معاذ. اهـ، الميزان (٤/ ٥٨٢) وقال: أبو هشام عن أبى معاذ. مجهول كشيخة. اللسان (٧/ ١١٨) وذكره كما ذكره الذهبى في الميزان."],[14391,"(١) زاد في الميزان \"بن عثمان\"."],[14392,"باب أبى همام"],[14393,"٢٥٠٥ - أبو همام الشعبانى. روى عن أبى هريرة. روى عنه يحيى بن أبى كثير."],[14394,"٢٥٠٦ - أبو همام البصرى. روى عنه الأوزاعى قوله. لم يعرفه أبو زرعة."],[14395,"٢٥٠٥ - كنى البخارى (ص ٨١)، الجرح (٤/ ٢/ ٤٥٥)، تعجيل المنفعة (ص ٣٤٣) وذكر أن الحسينى قال: انه مجهول."],[14396,"٢٥٠٦ - الجرح (٤/ ٢/ ٤٥٥) وقال: سئل أبو زرعة عنه فقال: لا أعرفه. الميزان (٤/ ٥٨٣) وقال: قال أبو زرعة: لا يعرف. اللسان (٧/ ١١٨)."],[14397,"باب الافراد في الهاء من الكنى"],[14398,"٢٥٠٧ - أبو هاشم الدوسى، ابن عم أبى هريرة. روى عن أبى هريرة. حديثه عند النضر بن محمد الجرشى (١) عن عكرمة بن عمار عن رجل (٢) من آل حاطب بن أبى بلتعة (٣) عنه."],[14399,"٢٥٠٨ - أبو هُرْمُز (٤) روى عن أنس. روى عنه سعيد بن سليمان الواسطى وأحمد بن يونس (٥). قال عباس عن يحيى بن معين أنه قال: أبو هرمز الذى يروى عن أنس ضعيف (٦)."],[14400,"٢٥٠٧ - كنى البخارى (ص ٨٠)، الجرح (٤/ ٢/ ٤٥٣). الميزان (٤/ ٥٨١)، تهذيب الكمال (٣/ ١٣٦٦)، اللسان (٧/ ٤٨٨)، التهذيب (١٢/ ٢٦١) التقريب (٢/ ٤٨٣) وقال: مجهول الحال، من الثالثة./ د."],[14401,"(١) في كنى البخارى \"النضر بن شميل\"."],[14402,"(٢) لم أقف على من سماه."],[14403,"(٣) حاطب بن أبى بلتعة عمرو بن عمير بن سلمة اللخمى، حليف بنى أسد بن عبد العزيز صحابى، شهد بدرا وكان رسول النبى -صلى الله عليه وآله وسلم- إلى المقوقس (ت: ٣٠) انظر التجريد (١/ ١١٣ - ١١٤)."],[14404,"٢٥٠٨ - الجرح (٤/ ٢/ ٤٥٦) وقال: قرئ على العباس بن محمد الدورى عن يحيى ابن معين أنه قال: أبو هرمز الذى يروى عن أنس ضعيف، الميزان (٤/ ٥٨٢) وقال: أبو هرمز. عن أنس. هو نافع، لينه ابن معين. الضعفاء والمتروكين (ص ١١٤) وقال: ليس بثقة. اللسان (٦/ ١٤٦) وقال: نافع بن هرمز أبو هرمز، وذكر روايته عن الحسن وعن أنس بن مالك: ورواية أحمد بن يونس عنه، الاكمال (٧/ ٤١٠)."],[14405,"(٤) هرمز: بضم الهاء واخره زاى. الاكمال (٧/ ٤٠٩)."],[14406,"(٥) أحمد بن يونس بن المسيب الضبى البغدادى، نزيل أصبهان، صدوق، انظر الجرح (١/ ١/ ٨١)."],[14407,"(٦) تاريخ ابن معين (٢/ ٦٢)."],[14408,"٢٥٠٩ - أبو هبيرة (١) الضبى. روى عن (. . .) (٢) روى عنه حنش بن الحارث (٣)."],[14409,"٢٥١٠ - أبو الهَدَّاج (٤) التُّجَيْبِى (٥). سمع سعيد بن المسيب قوله. روى عنه حرملة بن عمران."],[14410,"٢٥١١ - أبو هنيدة. روى عن أبى أمامة الباهلى (٦). روى عنه داود بن أبى هند."],[14411,"٢٥٠٩ - كنى البخارى (ص ٨١). الجرح (٤/ ٢/ ٤٥٥) المقتنى في سرد الكنى (١٤١/ أ)."],[14412,"(١) هبيرة: بضم هاء وفتح موحدة تبصيرة المنتبة (٤/ ١٤٤٩)."],[14413,"(٢) هكذا بياض في الأصل، وكذا في الجرح أيضا."],[14414,"(٣) حنش: بفتح أوله والنون الخفيفة بعدها معجمة، ابن الحارث بن لقيط النخعى، الكوفى لا بأس به، من السادسة، انظر التقريب (١/ ٢٠٥) وذكره ابن أبى حاتم في الجرح (١/ ٢/ ٢٩١) وذكر روايته عن أبى هبيرة الأنصارى وقال: سمعت أبى يقول: حنش بن الحارث صالح الحديث ما به بأس وانظر أيضا التهذيب (٣/ ٥٧)."],[14415,"٢٥١٠ - كنى البخارى (ص ٨١)، الجرح (٤/ ٢/ ٤٥٥)، الثقات (٧/ ٦٦٧)، الاكمال (٧/ ٤١٦)، المقتنى (١٤١/ أ)."],[14416,"(٤) الهدَّاج: هكذا ضبط في الأصل بتشديد الدال المهملة، وضبط أيضا في الاكمال (٧/ ٤١٦) بفتح الهاء وتشديد الدال المهملة."],[14417,"(٥) التجيبى: هنا نسبة إلى محلة تجيب بمصر، وهى بضم التاء المعجمة باثنتين من فوقها كسر الجيم وتسكين الياء وفى آخرها باء موحدة."],[14418,"انظر اللباب (١/ ٢٠٧)، الاكمال (٧/ ٤١٦)."],[14419,"٢٥١١ - كنى البخارى (ص ٨١)، الجرح (٤/ ٢/ ٤٥٥)، الثقات (٧/ ٦٦٨) الميزان (٤/ ٥٨٣) وقال: لا يعرف. اللسان (٧/ ١١٩) وقال: لا يعرف."],[14420,"(٦) هكذا في الأصل \"أبو امامة الباهلى\" والذى في الميزان \"معاوية\" وفى بقية المراجع \"أبى ماوية\"."],[14421,"٢٥١٢ - أبو هَمْدَان (١) بن هارون. قال عباس عن ابن معين: أبو همدان كذاب (٢)."],[14422,"٢٥١٢ - الجرح (٤/ ٢/ ٤٥٦) وقال: قرئ على العباس بن محمد الدورى قال: سمعت يحيى بن معين يقول: أبو همدان كذاب. الميزان (٤/ ٥٨٣) وقال ابن معين: كذاب \"اللسان\" (٤/ ٤٥٨) وذكره في القاسم بن بهرام، وقال: قرأت بخط الحسينى أن الذهبى كناه أبا همدان ثم قال الحسينى الصواب انه القاسم بن مهران أبو الهمدان\". اهـ."],[14423,"وانظر المجروحين (٢/ ٢١٤)."],[14424,"(١) همدان: بمفتوحة وسكون ميم وبدال مهملة ونون. المغنى (ص ٨٤)."],[14425,"(٢) التاريخ (٢/ ٧٣٠) وزاد \"قال أبو الفضل أبو همدان من أهل هيت\"."],[14426,"حرف الواو"],[14427,"باب أبى الوليد"],[14428,"٢٥١٣ - أبو الوليد مولى عمرو بن خداش (١). سمع أبا هريرة. روى عنه ابن أبى ذئب. قال ابن أبى حاتم: سمعت أبى وسئل عن أبى الوليد الذى روى عنه ابن أبى ذئب. فقال: شيخ لابن أبى ذئب. لا أعلم روى عنه غيره، وهو شيخ مستقيم الحديث."],[14429,"٢٥١٣ - كنى البخارى (ص ٧٧)، كنى مسلم (ص ١٠١٨)، الجرح (٤/ ٢/ ٤٥٠) وقال: سمعت أبى وسئل عن أبى الوليد. . . الخ."],[14430,"(١) هكذا في الأصل \"خداش\" بالدال المهملة. وكذا هو في كنى مسلم \"خداش\" والذى في كنى البخارى والجرح \"خراش\" بالراء المهملة."],[14431,"الخاتمة"],[14432,"الحمد للَّه رب العالمين، والصلاة والسلام على أشرف الأنبياء والمرسلين وعلى آله وأصحابه الطبين الطاهرين وبعد،"],[14433,"فاننى سأذكر في هذه الخاتمة أهم النتائج التى توصلت إليها من خلال عملى في هذا الكتاب، وتتلخص هذه النتائج بما يلى:"],[14434,"أولا: أهمية كتب التراث الإسلامى وذلك بما تضمنه هذا التراث من علوم غزيرة نافعة كانت ثمرة لجهود عظيمة مشكورة لسلفنا الصالح رحمهم اللَّه تعالى."],[14435,"ثانيا: كان للدراسة التى قدمتها بين يدى هذا الكتاب وما استهدفته هذه الدراسة من إبراز لبعض الجوانب المتعلقة بالكتاب ومصنفه بعض النتائج المثمرة منها."],[14436,"(أ) التعرف على شخصية الحافظ ابن عبد البر مصنف هذا الكتاب وإبراز الجوانب المختلفة في شخصيته، وما قدمه للمكتبة الإسلامية من مؤلفات جليلة متنوعة الفنون."],[14437,"(ب) إبراز أهمية هذا العلم \"علم الكنى والأسماء\" والغاية التى يخدمها مع ذكر بعض الذين شاركوا في التأليف فيه عبر هذه القرون الطويلة، مع ذكر مؤلفاتهم ومعرفة المخطوط منها من المطبوع، وقد تم ذكر ستة وخمسين مؤلفا في هذا المجال (١)."],[14438,"(جـ) لقد كان لوضع منهج التحقيق والالتزام به أثناء العمل نتائج طيبة منها خروج العمل متناسقا ومنضبطا بخطوات محددة واضحة الأهداف."],[14439,"(د) وقد كان لترقيم التراجم \"الكنى\" ترقيما تسلسليا فوائد كبيرة منها:"],[14440,"١ - معرفة عدد الكنى الواردة في الكتاب، وقد بلغ عددها حوالى الفين وخمسمائة وثلاث عشرة (٢٥١٣) كنية، وقفت على أكثرها في المصادر الأخرى وبقى منها حوالى ثلاثين (٣٠) كنية لم أقف عليها عند مخير الحافظ ابن عبد البر."],[14441,"٢ - عمل الفهارس المتنوعة على هذه الأرقام، وبهذا تكون الإحالة على الأرقام أكثر دقة من الإحالة على أرقام الصفحات، وذلك لأن الصفحة الواحدة قد تشتمل على عدد من الكنى."],[14442,"٣ - ساعد الترقيم على ترتيب مادة الكتاب على حروف المعجم كما هو ملاحظ من الفهرس الثالث (فهرس الكنى)، وقد أغنى هذا الفهرس عن عمل فهرس للكتاب على الأبواب."],[14443,"ثالثا: أهمية هذا الكتاب، وتبرز أهمية هذا الكتاب بما يلى: -"],[14444,"(أ) اشتماله على عدد كبير من الأسماء والكنى بالإضافة إلى اشماله على آلاف التراجم الهامشية كما هو ملاحظ من الفهرسين الثالث والرابع."],[14445,"(١) انظر الدراسة (ص ٩) وما بعدها."],[14446,"(ب) لم يقتصر فيه مصنفه على الأسماء والكنى فحسب بل ضمنه كثيرا من الأقوال في الجرح والعدالة سواء أكانت هذه الأقوال للحافظ ابن عبد البر نفسه أو لأئمة الجرح والتعديل المتقدمين على عصرة."],[14447,"فمثلا اشتمل على حوالى مائة وعشرين (١٢٠) قولا للامام أحمد، ومائة وثمانين قولا (١٨٠) لأبى حاتم الرازى، ومائة قولا لأبى زرعة، ومائتين وخمسين قولا (٢٥٠) لابن معين. وهكذا."],[14448,"(ب) اشتماله على مجموعة كبيرة من الأحاديث والاثار التى ذكرها المصنف اثناء ايراده للكنى."],[14449,"رابعا: وأخيرا أود التنبيه على أنه ينبغى عدم الاعتماد كثيرا في تحقيق التراث ونشره على المصورات، وخاصة في الكتب التى لا يوجد منها أكثر من نسخة، والاولى في مثل هذا الرجوع إلى النسخة الأصلية للكتاب ان وجدت، وذلك لأنه قد يسقط أحيانا بعض الأوراق من الكتاب أثناء عملية التصوير وقد يكون التصوير غير واضح فيتعذر معه قراءة بعض الكلمات، وهذا ما كنت أعانى منه كثيرا وخاصة قبل الوقوف على المخطوط الأصلى للكتاب."],[14450,"هذا ما أردت أن أذكره في هذه الخاتمة، وأسأل اللَّه عز وجل أن يختم بالصالحات أعمالنا، وأن يوفقنا لمرضاته، وهو حسبنا ونعم الوكيل."],[14451,"المراجع"],[14452,"- الاتحافات السنية بالأحاديث القدسية: - عبد الرؤوف المناوى (ت: ١٠٣١) دار المعرفة - بيروت."],[14453,"- أخبار القضاة: - وكيع/ محمد بن خلف بن حيان (ت: ٣٠٦)، عالم الكتب بيروت."],[14454,"- أخبار مكة: محمد بن عبد اللَّه بن أحمد الازرقى تحقيق رشدى صالح ملحس دار الثقافة - مكة المكرمة، ط ٢ - ١٣٩٨ هـ."],[14455,"- الأدب المفرد: - محمد بن إسماعيل البخارى (ت: ٢٥٦)، تحقيق: فؤاد عبد الباقى، المطبعة العربية، باكستان."],[14456,"- الأذكار: - يحيى بن شرف النووى (ت: ٦٧٦)، مكتبة الرياض الحديثة - الرياض."],[14457,"- إرواء الغليل في تخريج أحاديث منار السبيل: - محمد ناصر الدين الألبانى، المكتب الاسلامى، ط ٢، ١٣٩٩ هـ."],[14458,"- الأزهار المتناثرة في الأخبار المتواترة: - جلال الدين السيوطى (ت: ٩١١)، مطبعة صاحب دكن - ١٣٢٤ هـ."],[14459,"- الاستبصار في نسب الصحابة من الأنصار: - عبد اللَّه بن قدامة المقدسى (ت: ٦٢٠)، تحقيق الاستاذ على نويهض - دار الفكر."],[14460,"- الاستذكار لمذاهب فقهاء الأمصار وعلماء الأقطار فيما تضمنه الموطأ من معانى الرأى والآثار: - أبو عمر يوسف بن عبد اللَّه بن عبد البر (ت: ٤٦٣)، تحقيق الاستاذ/ على النجدى ناصف."],[14461,"- الاستيعاب في معرفة الأصحاب: - يوسف بن عبد اللَّه بن محمد بن عبد البر النمرى (ت: ٤٦٣)، مطبعة السعادة - مصر، ط ١ - ١٣٢٨ هـ."],[14462,"- أسد الغابة في معرفة الصحابة: - أبو الحسن على بن محمد بن الاثير الجزرى (ت: ٦٣٠)، مطبعة الشعب."],[14463,"- الأسماء والصفات: أبو بكر أحمد بن الحسين بن على البيهقى (ت: ٤٥٨)، دار احياء التراث العربى - بيروت."],[14464,"- الإصابة في تمييز الصحابة: - أحمد بن على بن حجر العسقلانى (ت: ٨٥٢)، مطبعة السعادة - مصر، ط ١ - ١٣٢٨ هـ."],[14465,"- الاعتبار في الناسخ والمنسوخ من الآثار: - محمد بن موسى بن عثمان الحازمى (ت: ٥٨٤)، مطبعة الاندلس - حمص، ط ١ - ١٣٨٦ هـ - ١٩٦٦ م."],[14466,"- الاعتقاد: - أبو بكر أحمد بن الحسين البيهقى (ت: ٤٥٨)، تصحيح العلامة أحمد محمد مرسى، المطبعة العربية - باكستان."],[14467,"- اعجاز القرآن: - أبو بكر محمد بن الطيب الباقلانى (ت: ٤٠٣)، تحقيق السيد أحمد صقر، دار المعارف - مصر."],[14468,"- اعجاز القرآن والبلاغة النبوية: - مصطفى صادق الرافعى، دار الكتاب العربى بيروت."],[14469,"- الاعلام: - خير الدين الزركلى - دار العلم للملايين - بيروت، ط ٥."],[14470,"- اعلام النبوة: - على بن محمد الماوردى الشافعى (ت: ٤٥٠) دار الكتب العلمية - بيروت، ط ٢ - ١٤٠١ هـ."],[14471,"- اقتضاء الصراط المستقيم مخالفة أصحاب الجحيم: شيخ الاسلام أحمد ابن تيمية (٦٦١ - ٧٢٨)، تحقيق أحمد حامد الفقى، ط ٢ - ١٣٦٩ هـ، مطبعة السنة المحمدية."],[14472,"- الاكمال في رفع الارتياب عن المؤتلف والمختلف في الأسماء والكنى والانساب: - الامير الحافظ ابن ماكولا (ت: ٤٧٥)، نشر/ محمد أمين دمج، بيروت - لبنان."],[14473,"- الأموال: حميد بن مخلد المعروف بابن زنجويه (ت ٢٤٧)، رسالة دكتوراه بجامعة أم القرى بمكة المكرمة، تحقيق الدكتور شاكر ذيب فياض."],[14474,"- الأموال: - أبو عبيد القاسم بن سلام (ت ٢٢٤)، تحقيق محمد خليل هراس، دار الفكر، ط ٢، ١٣٩٥ - ١٩٧٥."],[14475,"- الأنساب: - عبد الكريم بن محمد السمعانى (ت ٥٦٢)، نشر المستشرق: د. سى - مرجليون."],[14476,"- الانساب المتفقه: - أبو الفضل محمد طاهر المعروف بابن القيسرانى (٥٠٧)."],[14477,"- الباعث الحثيث شرح اختصار علوم الحديث: - أحمد محمد شاكر، مكتبة على صبيح وأولاده - مصر، ط ٣ - سنة ١٣٩٧ هـ."],[14478,"- بحوث في تاريخ السنة: - د. أكرم العمرى، مؤسسة الرسالة، ط ٣ - ١٣٩٥ هـ."],[14479,"- البداية والنهاية: - أبو الفداء إسماعيل بن كثير (ت: ٧٧٤)، مكتبة المعارف، بيروت، ط ٢ - ١٩٧٧."],[14480,"- برنامج ابن جابر الوادى آشى: شمس الدين محمد بن جابر الوادى آشى (ت: ٧٤٩)، تحقيق د. محمد الحبيب الهيله، تونس ١٤٠١ هـ."],[14481,"- بغية الملتمس تاريخ رجال أهل الاندلس: - أحمد بن يحيى الضبى (ت: ٥٩٩)، دار الكتاب العربى، سنة ١٩٦٧ م."],[14482,"- بغية الوعاة في طبقات اللغويين والنحاة: - جلال الدين عبد الرحمن السيوطى (ت: ٩١١)، تحقيق: محمد أبو الفضل إبراهيم، دار الفكر، ط ٢ - ١٣٩٩ هـ."],[14483,"- بيان خطأ محمد بن إسماعيل البخارى في تاريخه. رواية ابن أبى حاتم وأبى زرعة، المكتبة الإسلامية - تركيا."],[14484,"- البيان والتبيين: - أبو عثمان عمرو بن بحر الجاحظ (ت: ٢٥٥)، تحقيق عبد السلام هارون، ط/ ٣."],[14485,"- تاج العروس من جواهر القاموس: - محمد مرتضى الزبيدى، مكتبة الحياة - بيروت."],[14486,"- التاريخ: - يحيى بن معين (ت: ٢٣٣)، رواية الدورى، تحقيق: د. أحمد محمد نور سيف، نشر مركز البحث العلمى بجامعة أم القرى، ط ١ - ١٣٩٩ هـ - ١٩٧٩ م."],[14487,"- التاريخ: يحيى بن معين رواية عثمان بن سعيد الدرامى (ت: ٢٨٠) تحقيق: د/ أحمد نور سيف، نشر مركز البحث العلمى - بجامعة أم القرى."],[14488,"- التاريخ: - يحيى بن معين، رواية يزيد بن الهيثم بن طهمان البادى الدقاق، تحقيق: د/ أحمد محمد نور سيف، نشر: مركز البحث العلمى - بجامعة أم القرى."],[14489,"- تاريخ ابن كثير - انظر البداية والنهاية."],[14490,"- تاريخ الامم والملوك: محمد بن جرير الطبرى (ت: ٣١٠)، تحقيق: محمد أبو الفضل ط ٤. دار المعارف - مصر."],[14491,"- تاريخ بغداد: - أبو بكر أحمد بن على بن ثابت المعروف بالخطيب البغدادى (ت ٤٦٣)، المكتبة السلفية - المدينة المنورة."],[14492,"- تاريخ جرجان: - حمزة بن يوسف السهمى (ت ٤٢٧)، دائرة المعارف العثمانية الهند، ط ٢ - ١٣٨٧ - ١٩٦٧."],[14493,"- تاريخ التراث العربى: فؤاد سزكين، الهيئة المصرية - القاهرة، سنة ١٩٧١ م."],[14494,"- تاريخ الخلفاء: - عبد الرحمن بن أبى بكر السيوطى (ت ٩١١)، تحقيق محمد محيى الدين عبد الحميد، مطبعة السعادة - مصر، ط ١، سنة ١٣٧١ - ١٩٥٢."],[14495,"- تاريخ خليفة بن خياط: - خليفة بن خياط (شباب) (ت: ٢٣٠)، تحقيق: أكرم العمرى، مطبعة محمد هاشم الكتبى، ط ٢ - سنة ١٣٩٧ هـ."],[14496,"- تاريخ دمشق: - أبو القاسم على بن عساكر (ت ٥٧١)، مصور بالمكتبة المركزية بجامعة أم القرى."],[14497,"- التاريخ الصغير: - محمد بن إسماعيل البخارى (ت ٢٥٦)، المكتبة الاثرية - باكستان."],[14498,"- التاريخ الكبير: محمد بن إسماعيل البخارى (ت ٢٥٦)، المكتبة الاسلامية - تركيا."],[14499,"- تبصير المنتبه بتحرير المشتبه، أحمد بن على بن حجر العسقلانى (ت: ٨٥٢) تحقيق: محمد على النجار. وعلى محمد البجاوى، المؤسسة المصرية العامة للطباعة والنشر."],[14500,"- تبيين كذب المفترى فيما نسب إلى الإمام أبى الحسن الاشعرى: - على ابن الحسن بن هبة اللَّه بن عساكر (ت: ٥٧١)، دار الكتاب العربى - بيروت، ١٣٩٩ هـ."],[14501,"- تجريد أسماء الصحابة: - محمد بن أحمد الذهبى (ت: ٧٤٨)، دار المعرفة، بيروت."],[14502,"- تحفة الاحوذى شرح جامع الترمذى: - محمد بن عبد الرحمن المباركفورى (ت: ١٣٥٣)، نشر المكتبة السلفية بالمدينة المنورة، ط ٢ - سنة ١٣٨٣ هـ."],[14503,"- تحفة الاشراف بمعرفة الاطراف: - أبو الحجاج يوسف بن عبد الرحمن المزى (ت: ٧٤٢)، المطبعة القيمة - الهند ١٣٩٦ - ١٩٧٦."],[14504,"- تدريب الراوى في شرح تقريب النواوى: - جلال الدين السيوطى - تحقيق عبد الوهاب عبد اللطيف."],[14505,"- تذكرة الحفاظ: محمد بن أحمد بن عثمان الذهبى (ت: ٧٤٨)، دار احياء التراث العربى، ط ٢ - ١٣٨٥ هـ."],[14506,"- ترتيب المدارك: تقريب المسالك لمعرفة اعلام مذهب مالك: - القاضى عياض بن موسى السبتى (ت: ٥٤٤)، مطبوعات وزارة الاوقاف الرباط."],[14507,"- الترغيب والترهيب: - عبد العظيم بن عبد القوى المنذرى (ت ٦٥٦)، تحقيق محمد محيى الدين عبد الحميد، دار الفكر بيروت، ط ٢ - ١٣٩٣ هـ."],[14508,"- تصحيفات المحدثين: - أبو أحمد الحسن بن عبد اللَّه بن سعيد العسكرى (ت: ٣٨٢)، تحقيق: محمود أحمد ميره، المطبعة العربية الحديثة - القاهرة. ط ١."],[14509,"- تعجيل المنفعة: - أحمد بن على بن حجر العسقلانى (ت ٨٥٢)، دار المحاسن (١٣٨٦ - ١٩٦٦)."],[14510,"- التعليق المغنى على سنن الدارقطنى: - محمد شمس الحق آبادى، دار المحاسن القاهرة، ١٣٨٦ - ١٩٦٦."],[14511,"- تفسير القرآن العظيم: - إسماعيل بن كثير (ت ٧٧٤)، دار إحياء الكتب العربية - مصر."],[14512,"- تفسير أبى السعود: - أبو السعود بن محمد العمادى (ت: ٩٨٢)، تحقيق: عبد القادر أحمد عطا - مطبعة السعادة."],[14513,"- تقريب التهذيب: - أحمد بن على بن حجر العسقلانى (ت: ٨٥٢)، تحقيق: عبد الوهاب عبد اللطيف، دار المعرفة - بيروت، ط ٢ - ١٣٩٥ هـ."],[14514,"- التقييد والايضاح شرح مقدمة ابن الصلاح: - زين الدين عبد الرحيم بن الحسين العراقى (ت ٨٠٦)، تحقيق: عبد الرحمن محمد عثمان، المكتبة السلفية - المدينة المنورة، ط ١ - ١٣٨٩ - ١٩٦٩."],[14515,"- تلخيص الحبير تخريج أحاديث الرافعى الكبير: - ابن حجر، تحقيق عبد اللَّه هاشم اليمانى، شركة الطباعة الفنية المتحدة، القاهرة، ١٣٨٤ هـ."],[14516,"- تلخيص المستدرك بهامش مستدرك الحاكم: - محمد بن أحمد الذهبى (ت ٧٤٨) دار الفكر - بيروت ١٣٩٨ - ١٩٧٨."],[14517,"- التمهيد لما في الموطأ من المعانى والاسانيد: - أبو عمر يوسف بن عبد اللَّه بن عبد البر النمرى (ت ٤٦٣)، تحقيق سعيد أحمد اعراب، نشر وزارة الأوقاف بالمغرب."],[14518,"- تنزيه الشريعة المرفوعة عن الاخبار الشنيعة الموضوعة: - على بن محمد ابن عراقى (ت ٩٦٣)، دار الكتب العلمية - بيروت، ط ١ - ١٣٩٩ - ١٩٧٩."],[14519,"- تهذيب الاثار: - محمد بن جرير الطبرى (ت ٣١٠)، تحقيق د. ناصر الرشيد وعبد القيوم عبد رب النبى، مطابع الصفا - مكة المكرمة، ١٤٠٢ هـ."],[14520,"- تهذيب الأسماء واللغات: - محيى الدين بن شرف النووى، دار الكتب العلمية - بيروت."],[14521,"- تهذيب تاريخ دمشق: عبد القادر بدران (ت ١٣٤٦ هـ)، دار المسيرة - بيروت."],[14522,"- تهذيب التهذيب: - أحمد بن على بن حجر العسقلانى (ت ٨٥٢ هـ)، دائرة المعارف - الهند، ط ١ - ١٣٢٥ هـ."],[14523,"- تهذيب سنن أبى داود: - أبو عبد اللَّه محمد بن أبى بكر الشهير بابن القيم (ت ٧٥٢)، تحقيق: محمد حامد الفقى، مكتبة السنة المحمدية - القاهرة."],[14524,"- تهذيب الكمال: أبو الحجاج يوسف بن عبد الرحمن المزى (ت ٧٤٢ هـ)، مصورة دار المأمون للتراث، دمشق."],[14525,"- التوحيد وإثبات صفات الرب عز وجل: - محمد بن اسحاق بن خزيمة (ت: ٣١١) راجعه وعلق عليه خليل الهراس، توزيع دار الباز - مكة المكرمة، سنة ١٣٩٨ هـ - ١٩٧٨ م."],[14526,"- الثقات: - أبو حاتم محمد بن حبان البستى (ت ٣٥٤)، دائرة المعارف العثمانية - الهند، ط ١ - ١٣٩٣ هـ."],[14527,"- الجامع الأزهر في حديث النبى الانور: - المناوى، المركز العربى للبحث والنشر، القاهرة - ١٩٨٠ م."],[14528,"- الجامع الصحيح: - أبو عيسى محمد بن سورة الترمذى (ت: ٢٧٩)، مع شرح تحفة الاحوذى - مطبعة المدنى، سنة ١٣٨٣ هـ."],[14529,"- جامع بيان العلم وفضله: - عمر يوسف بن عبد اللَّه بن عبد البر (ت: ٤٦٣ هـ)، ادارة الطباعة المنيرية، ١٣٩٨ هـ."],[14530,"- جامع البيان عن تأويل آى القرآن: - محمد بن جرير الطبرى (ت ٣١٠)، تحقيق محمود شاكر، دار المعارف - مصر."],[14531,"- جامع البيان عن تأويل آى القرآن: - الطبرى، مطبعة مصطفى البابى الحلبى - مصر، ط ٣، ١٣٨٨ - ١٩٦٨."],[14532,"- جامع التحصيل في أحكام المراسيل: - صلاح الدين خليل بن كيكلدى العلائى (ت ٧٦١)، تحقيق حمدى عبد المجيد السلفى، الدار العربية - بغداد، ط ١ - ١٣٩٨ - ١٩٧٨."],[14533,"- الجامع الصغير: - جلال الدين عبد الرحمن بن أبى بكر السيوطى (ت ٩١١)، دار الكتب العلمية - ط ٤."],[14534,"- الجامع الكبير: جلال الدين عبد الرحمن بن أبى بكر السيوطى (ت ٩١١)، مصورة عن مخطوطة دار الكتب المصرية - الهيئة المصرية العامة للكتاب."],[14535,"- جذوة المقتبس في ذكر ولاة الاندلس الحميدى: أبو عبد اللَّه محمد بن أبى نصر فتوح بن عبد اللَّه الازدى (ت: ٤٨٨)، الدار المصرية للتأليف والترجمة، ١٩٦٦."],[14536,"- الجرح والتعديل: - عبد الرحمن بن أبى حاتم محمد بن ادريس الرازى (ت ٣٢٧) دائرة المعارف العثمانية - الهند، ١٣٧١ هـ."],[14537,"- جمهرة أنساب العرب: - أبو محمد على بن أحمد بن سعيد بن حزم الاندلسى (ت: ٤٥٦)، تحقيق/ عبد السلام هارون، دار المعارف - مصر، ١٣٨٢ هـ."],[14538,"- جمهرة نسب قريش وأخبارها: - الزبير بن بكار (ت: ٢٥٦)، شرح وتحقيق محمود محمد شاكر طبع مكتبة دار العروبة، سنة ١٣٨١ هـ."],[14539,"- الجوهر النقى على سنن البيهقى: علاء الدين بن على بن عثمان بن التركمانى (ت ٧٤٥)، دار الفكر - بيروت."],[14540,"- حلية الأولياء: أبو نعيم أحمد بن عبد اللَّه الاصبهانى (ت ٤٣٠)، دار الكتاب العربى - بيروت، ط ٢ - ١٣٨٧ - ١٩٦٧."],[14541,"- الخراج: - يحيى بن آدم القرشى (ت ٢٠٣)، دار المعرفة - بيروت."],[14542,"- الخراج: يعقوب بن إبراهيم أبو يوسف (ت ١٨٣)، دار المعرفة - بيروت، ١٣٩٩ - ١٩٧٩."],[14543,"- خزانة الأدب ولب لباب لسان العرب: - الشيخ عبد القادر عمر البغدادى (ت: ١٠٩٣)، دار الثقافة - بيروت."],[14544,"- خلق أفعال العباد: - محمد بن إسماعيل البخارى (ت ٢٥٦)، تحقيق د. عبد الرحمن عميرة، دار عكاظ - جده، ط ٢."],[14545,"- خلاصة تهذيب الكمال في أسماء الرجال: أحمد بن عبد اللَّه الخزرجى (ت: ٩٢٣)، مكتبة المطبوعات الاسلامية - بيروت، ١٩٧١ م."],[14546,"- الدراية في تخريج أحاديث الهداية لابن حجر العسقلانى، مطبعة الفجالة الجديدة - القاهرة، ١٣٨٤ هـ."],[14547,"- الدر المنثور في التفسير بالمأثور: جلال الدين السيوطى، دار المعرفة - بيروت."],[14548,"- دلائل النبوة: - أحمد بن السحين البيهقى (ت: ٤٥٨) المكتبة السلفية/ - المدينة المنورة ط ١، ١٣٨٩ هـ."],[14549,"- دلائل النبوة: - أبو نعيم أحمد بن عبد اللَّه الاصبهانى (ت ٤٣٠)، توزيع دار الباز - مكة المكرمة."],[14550,"- الديباج المذهب في معرفة أعيان علماء المذهب: - ابن فرحون المالكى، تحقيق د/ محمد الاحمدى، دار التراث - القاهرة."],[14551,"- ديوان الضعفاء والمتروكين: - شمس الدين بن عثمان الذهبى (ت: ٧٤٨)، تحقيق حماد الأنصارى، مطبعة النهضة - مكة المكرمة، ١٣٨٧ هـ."],[14552,"- ذكر أخبار أصبهان: أبو نعيم أحمد بن عبد اللَّه الاصبهانى (ت: ٣٤٠)، مطبعة بريل في مدينة ليدن، ١٩٣٤ م."],[14553,"- الذهبى ومنهجه في كتابه تاريخ الاسلام: - الدكتور/ بشّار عواد معروف، مطبعة عيسى البابى الحلبى وشركاه، القاهرة، ط ١، سنة ١٩٧٦ م."],[14554,"- رجال السند والهند: - القاضى أبو المعالى أطهر المباركبورى، دار الأنصار ط ١ - ١٣٩٨ هـ."],[14555,"- الرسالة: - محمد بن ادريس الشافعى (ت: ٢٠٤)، تحقيق: أحمد شاكر ١٣٥٨ هـ."],[14556,"- الرسالة المستطرفة: محمد بن جعفر الكتانى (ت ١٣٤٥ هـ)، دار الفكر - دمشق، ط ٣، ١٣٨٣ - ١٩٦٤ م."],[14557,"- الرواة الذين كنوا بأبى زرعة: - الدكتور سعدى الهاشمى، بحث في مجلة الجامعة الاسلامية بالمدينة المنورة، سنة ١٥ - عدد ٥٨."],[14558,"- الروض الانف في شرح السيرة النبوية لابن هشام: - عبد الرحمن السهيلى (٥٠٨ - ٥٨١)، تحقيق وتعليق/ عبد الرحمن الوكيل، دار الكتب الحديثة/ القاهرة."],[14559,"- الزهد: أحمد بن محمد بن حنبل (ت ٢٤١)، دار الكتب العلمية - بيروت، ١٣٩٨ - ١٩٧٨ م."],[14560,"- الزهد: عبد اللَّه بن المبارك (ت ١٨١)، تحقيق عبد الرحمن الاعظمى، دار الكتب العلمية - بيروت."],[14561,"- سبل السلام شرح بلوغ المرام: محمد بن إسماعيل الصنعانى (ت ١١٨٢)، مطبعة مصطفى البابى الحلبى - مصر، ط ٤، سنة ١٣٧٩ هـ - ١٩٦٠ م."],[14562,"- سلسلة الأحاديث الصحيحة: محمد ناصر الدين الألبانى، المكتب الاسلامى ط ٢، ١٣٩٩ هـ - ١٩٧٩ م."],[14563,"- سلسلة الأحاديث الضعيفة: محمد ناصر الدين الألبانى - المكتب الاسلامى ط ٤، ١٣٩٨ هـ."],[14564,"- السنن: سعيد بن منصور (ت ٢٢٧)، تحقيق حبيب الرحمن الاعظمى، مطبعة علمى بريس، ١٣٨٧ هـ - ١٩٦٧ م."],[14565,"- سنن أبى داود: - أبو داود سليمان بن الأشعث السجستانى (ت: ٢٧٥)، دار إحياء السنة النبوية."],[14566,"- سنن الدارقطنى: - أبو الحسن على بن عمر الدارقطنى (ت ٣٨٥)، شركة الطباعة الفنية، ١٣٨٦ هـ."],[14567,"- سنن الدارمى: عبد اللَّه بن عبد الرحمن الدارمى (ت ٢٥٥)، دار إحياء السنة النبوية."],[14568,"- السنن الكبرى: - أحمد بن الحسين البيهقى (ت ٤٥٨)، دار الفكر بيروت."],[14569,"- سنن ابن ماجه: محمد بن يزيد بن ماجه (ت ٢٧٥)، دار إحياء التراث العربى بيروت - ١٣٩٥ - ١٩٧٥."],[14570,"- سنن النسائى: - أحمد بن شعيب النسائى (ت ٣٠٣)، دار إحياء التراث العربى - بيروت."],[14571,"- السنة: عمرو بر أبى عاصم الضحاك بن مخلد (ت ٢٨٧)، المكتب الاسلامى، ط ١ - ١٤٠٠ - ١٩٨٠."],[14572,"- سير أعلام النبلاء: - محمد بن أحمد بن عثمان الذهبى (ت ٧٤٨)، مصور بالمكتبة المركزية بجامعة أم القرى."],[14573,"- سير أعلام النبلاء: - الإمام شمس الدين محمد بن أحمد بن عثمان الذهبى (ت: ٧٤٨)، تحقيق: شعيب الارناؤوط وحسين الاسد، مؤسسة الرسالة، ط ٢ - ١٤٠٢ هـ."],[14574,"- سيرة عمر بن عبد العزيز: - الحافظ أبو الفرج عبد الرحمن بن الجوزى."],[14575,"- السيرة النبوية: - أبو الفداء إسماعيل بن كثير (ت: ٧٧٤)، تحقيق مصطفى عبد الواحد، دار المعرفة - بيروت ١٣٩٦ هـ."],[14576,"- السيرة النبوية: أبو محمد بن عبد الملك بن هشام بن أيوب الحميرى (ت: ٢١٨) تحقيق: مصطفى السّقّا وآخرين، مطبعة مصطفى البابى الحلبى وأولاده ط ٢ - ١٣٧٥ هـ."],[14577,"- السيرة النبوية: محمد بن أحمد بن عثمان الذهبى (ت ٧٤٨)، تحقيق حسام الدين القدسى، دار الكتب العلمية - بيروت، ط ١ - ١٤٠١ - ١٩٨١."],[14578,"- السيرة والمغازى: - محمد بن اسحاق المطلبى (ت: ١٥١) تحقيق سهيل زكار - دار الفكر، ط ١، ١٣٩٨ هـ."],[14579,"- شجرة النور الزكية في طبقات المالكية: - محمد بن محمد مخلوف، دار الكتاب العربى - بيروت."],[14580,"- شذرات الذهب في أخبار من ذهب: عبد الحى بن العماد الحنبلى (ت ١٠٨٩) المكتب التجارى - بيروت."],[14581,"- شذور الذهب في معرفة كلام العرب: - أبو محمد عبد اللَّه جمال الدين ابن يوسف بن أحمد بن عبد اللَّه بن هشام الأنصارى المصرى (٧٠٨ - ٧٦١)، مطبعة السعادة - مصر: ط ٥ - ١٣٧١ هـ."],[14582,"- شرح أشعار الهذليين: تحقيق عبد الستار أحمد فراج ومحمود شاكر، ط ١، القاهرة، ١٣٨٤ هـ."],[14583,"- شرح اصول اعتقاد أهل السنة: هبة اللَّه بن الحسن اللالكائى - تحقيق د. أحمد بن سعد، رسالة دكتوراة، بجامعة أم القرى بمكة المكرمة."],[14584,"- شرح السنة: الحسين بن مسعود البغوى (ت ٥١٦)، تحقيق شعيب الارناؤط، زهير الشاويش، المكتب الاسلامى - بيروت."],[14585,"- شرح علل الترمذى: - عبد الرحمن أحمد بن رجب الحنبلى: تحقيق نور الدين العتر، دار الملاح - دمشق، ط ١، ١٣٩٨ هـ."],[14586,"- شرح الفية العراقى (التبصرة والتذكرة): - الحافظ زين الدين عبد الرحيم بن الحسين بن عبد الرحمن بن أبى بكر بن إبراهيم العراقى (ت: ٨٠٦) المطبعة الجديدة - فاس، ١٣٥٤ هـ."],[14587,"- شرح ابن عقيل على الفية ابن مالك: - بهاء الدين عبد اللَّه بن عقيل العقيلى الهمدانى المصرى (٦٩٨ - ٧٦٩)، المكتبة التجارية الكبرى - القاهرة، ط ١٤ - ١٣٨٥ هـ."],[14588,"- شرح كتاب السير الكبير: - محمد بن الحسن الشيبانى (ت: ١٨٩)، تحقيق: د/ صلاح الدين المنجد، مطبعة شركة الاعلانات الشرقية، ١٩٧١ م."],[14589,"- شرح معانى الآثار: - أبو جعفر أحمد بن محمد الطحاوى (ت: ٣٢١) تحقيق: محمد سيد جاد الحق - مطبعة الأنوار المحمدية."],[14590,"- شرح النووى على مسلم: - محيى الدين يحيى بن شرف النووى (ت ٦٧٦)، المطبعة المصرية ومكتبتها."],[14591,"- الشعر والشعراء أو طبقات الشعراء: - أبو محمد عبد اللَّه بن مسلم بن قتيبة الدينورى (ت: ٢٧٦)، تحقيق الدكتور/ مفيد قميحة، دار الكتب العلمية/ بيروت، ط ١ سنة ١٩٨١ م."],[14592,"- الشمائل: محمد بن عيسى الترمذى (ت ٢٧٩)، مطبعة مصطفى البابى الحلبى، ط ٣، ١٣٧٥ هـ."],[14593,"- شمائل الرسول: أبو الفداء إسماعيل بن كثير (ت: ٧٧٤)، تحقيق مصطفى عبد الواحد، دار المعرفة - بيروت."],[14594,"- الصحاح للجوهرى: - إسماعيل بن حماد الجوهرى، تحقيق: أحمد عبد الغفور عطّار، ط ٢ - ١٤٠٢ هـ."],[14595,"- صحيح البخارى: - محمد بن إسماعيل البخارى (ت ٢٥٦) مع شرح فتح البارى المطبعة السلفية - القاهرة، ١٣٨٠ هـ."],[14596,"- صحيح ابن خزيمة: - أبو بكر محمد بن اسحاق بن خزيمة (ت: ٣١١)، تحقيق د/ محمد مصطفى الاعظمى - المكتب الاسلامى."],[14597,"- صحيح مسلم: مسلم بن الحجاج النيسابورى (ت ٢٦١)، ترتيب محمد فؤاد عبد الباقى."],[14598,"- الصفات: على بن عمر الدارقطنى (ت ٣٨٥)، تحقيق: عبد اللَّه الغنيمان، مكتبة الدار: المدينة المنورة، ط ١، ١٤٠٢ هـ."],[14599,"- صفة الجنة: أبو نعيم أحمد بن عبد اللَّه الاصبهانى (ت ٤٣٠)، مصور بالمكتبة المركزية بجامعة أم القرى بمكة المكرمة."],[14600,"- الصلة: - ابن بشكوال أبو القاسم خلف بن عبد الملك (ت: ٥٧٨)، الدار المصرية للتأليف والترجمة، ١٩٦٦ م."],[14601,"- الضعفاء: محمد بن عمر بن موسى العقيلى (ت: ٣٢٢)، رسالة جامعية بمكتبة الدكتور أحمد محمد نور سيف، إعداد الدكتور عبد اللَّه على حافظ."],[14602,"- الضعفاء أو أسامى الضعفاء ومن تكلم فيهم من المحدثين: - أبو زرعة الرازى. تحقيق الدكتور سعدى الهاشمى، مطبوعات الجامعة الاسلامية بالمدينة المنورة، ط ١ - ١٤٠٢ هـ."],[14603,"- الضعفاء الصغير: - محمد بن إسماعيل البخارى (ت: ٢٥٦)، تحقيق: محمود إبراهيم زايد - دار الوعى - حلب، ط ١، ١٣٩٦ هـ."],[14604,"- الضعفاء والمتروكون: أحمد بن شعيب النسائى (ت ٣٠٣)، مطبوع بذيل الضعفاء الصغير للبخارى - السابق الذكر."],[14605,"- طبقات الحفاظ: - جلال الدين عبد الرحمن بن أبى بكر السيوطى (ت ٩١١)، مطبعة الاستقلال الكبرى، ط ١ - ١٣٩٣ - ١٩٧٣."],[14606,"- طبقات خليفة بن خياط: - خليفة بن خياط شباب العصفرى (ت: ٢٤٠)، تحقيق أكرم العمرى، دار طيبة - الرياض."],[14607,"- طبقات الشافعية الكبرى: - عبد الوهاب بن تقى الدين السبكى (ت:"],[14608,"٧٧١)، دار المعرفة - بيروت، ط ٢."],[14609,"- طبقات الشعراء، محمد بن سلام الجمحى (ت: ٣٣١)، دار النهضة العربية - بيروت."],[14610,"- طبقات الفقهاء: - أبو اسحاق الشيرازى الشافعى (ت: ٤٧٦)، تحقيق د/ احسان عباس، دار الرائد العربى - بيروت، ١٤٠١ هـ."],[14611,"- الطبقات الكبرى: - محمد بن سعد (ت: ٢٣٠)، دار صادر - بيروت."],[14612,"- طبقات المدلسين: - ابن حجر - المطبعة المحمودية، مصر."],[14613,"- طبقات المفسرين: - محمد بن على الداودى (ت ٩٤٥)، تحقيق: - محمد على عمر، مطبعة الاستقلال الكبرى، ط ١ - ١٣٩٢ هـ."],[14614,"- ظلال الجنة في تخريج السنة: محمد ناصر الدين الألبانى، المكتب الاسلامى، ط ١، ١٤٠٠ - ١٩٨٠."],[14615,"- العبر في خبر من غبر: - أبو عبد اللَّه شمس الدين محمد الذهبى (ت: ٧٤٨) تحقيق: فؤاد سيد، الكويت، ١٩٦١."],[14616,"- العقد الثمين في تاريخ البلد الامين: - محمد بن أحمد الحسينى الفاسى (ت ٨٣٢)، تحقيق فؤاد سيد، مطبعة السنة المحمدية، ١٣٨٥ هـ."],[14617,"- العلل: - على بن عبد اللَّه بن المدينى (ت ٢٣٤)، المكتب الاسلامى - بيروت، ١٣٩٢ هـ."],[14618,"- العلل: أبو الحسن على بن عمر الدارقطنى (ت ٣٨٥)، مصورة بمكتبة الدكتور أحمد محمد نور سيف."],[14619,"- علل الترمذى الكبير: - ترتيب أبى طالب القاضى، تحقيق الاستاذ حمزة ذيب مصطفى، رسالة ماجستير في جامعة أم القرى بمكة المكرمة."],[14620,"- علل الحديث: - عبد الرحمن بن أبى حاتم الرازى (ت: ٣٢٧)، المطبعة السلفية - القاهرة، ١٣٤٣ هـ."],[14621,"- العلل المتناهية في الأحاديث الواهية: أبو الفرج عبد الرحمن بن على بن الجوزى (ت: ٥٩٧)، تحقيق ارشاد الحق الاثرى، إدارة ترجمان السنة - لاهور."],[14622,"- العلل ومعرفة الرجال: - أحمد بن محمد بن حنبل (ت: ٢٤١)، نشر: الدكتور طلعت فوج بيكيت والدكتور إسماعيل جراح أو على، انقره، ١٩٦٣."],[14623,"- عمل اليوم والليلة: أبو بكر بن السنى (ت ٣٦٤)، تحقيق عبد القادر عطا، مكتبة الكليات الازهرية، ط ١، ١٣٨٩ هـ."],[14624,"- عمل اليوم والليلة: - أحمد بن شعيب النسائى (ت: ٣٠٣)، تحقيق/ الدكتور فاروق حمادة، مكتبة المعارف - الرباط، ط ١ سنة ١٤٠١ هـ."],[14625,"- غاية النهاية في طبقات القراء: - محمد بن محمد بن الجزرى (ت: ٨٣٣)، دار الكتب العلمية - بيروت، ١٤٠٠ هـ."],[14626,"- غريب الحديث: حمد بن محمد بن إبراهيم الخطابى (ت ٣٨٨)، تحقيق عبد الكريم العزباوى، مطبوعات: مركز البحث العلمى - جامعة أم القرى."],[14627,"- غريب الحديث: - أبو عبيد القاسم بن سلّام الهروى (ت: ٢٢٤ هـ)، دائرة المعارف العثمانية - الهند، ط ١ - ١٣٨٤ هـ."],[14628,"- الفائق في غريب الحديث: - جار اللَّه محمود الزمخشرى (ت: ٥٣٨)، تحقيق: محمد أبى الفضل إبراهيم، مطبعة عيسى البابى الحلبى، ط ٢."],[14629,"- فتح البارى شرح صحيح البخارى: - أحمد بن على بن حجر (ت: ٨٥٢)، المكتبة السلفية - القاهرة ١٣٨٠ هـ."],[14630,"- الفتح الكبير في ضم الزيادة إلى الجامع الصغير: - جلال الدين السيوطى (ت: ٩١١)، وضع الشيخ يوسف النبهانى، دار الكتاب العربى - بيروت."],[14631,"- فتح المغيث شرح الفية الحديث للعراقى للامام شمس الدين محمد بن عبد الرحمن السخاوى (ت: ٩٠٢)، المكتبة العلمية - بيروت، ط ١ سنة ١٤٠٣ هـ."],[14632,"- فتوح البلدان: - أبو الحسن البلاذرى (ت: ٢٧٩)، مراجعة رضوان محمد رضوان، دار الكتب العلمية - بيروت."],[14633,"- فتوح الشام: - محمد بن عمر الواقدى (ت: ٢٠٧)، دار الجيل - بيروت."],[14634,"- فتوح مصر وأخبارها: - أبو القاسم عبد الرحمن بن عبد اللَّه بن عبد الحكم، مكتبة المثنى ببغداد."],[14635,"- الفرق بين الفرق: - عبد القاهر البغدادى الاسفرائينى (ت: ٤٢٩)، تحقيق: محمد محيى الدين عبد الحميد، مطبعة المدنى - القاهرة."],[14636,"- فضائل الصحابة: أحمد بن محمد حنبل (ت ٢٤١)، تحقيق: وصى اللَّه ابن محمد عباس، رسالة دكتوراة بجامعة أم القرى بمكة."],[14637,"- الفقيه والمتفقه: - أبو بكر أحمد بن على الخطيب، دار الكتب العلمية - بيروت ط ٢ - ١٤٠٠ هـ."],[14638,"- فهرس الفهارس والاثبات ومعجم المعاجم والمشيخات والمسلسلات: - الحافظ عبد الحى بن شمس الافاق أبو المكارم عبد الكبير بن القطب الشهير الشيخ محمد الحسنى الادريسى الكتانى الفاسى، المطبعة الجديدة بالطالعة، سنة ١٣٤٦ هـ."],[14639,"- الفهرست: - محمد بن اسحاق بن النديم (ت: ٢٧٨)، نشر: دار المعرفة - بيروت."],[14640,"- فهرسة ابن خير الاشبيلى: - محمد بن خير بن عمر الاشبيلى (ت: ٥٧٥)، دار الافاق الجديدة - بيروت، ط ٢ - ١٣٩٩ هـ."],[14641,"- فوائد تمام: - تمام بن عبد اللَّه الرازى (ت ٤١٤)، تحقيق الدكتور عبد الغنى أحمد جبر، رسالة دكتوراة بجامعة أم القرى بمكة المكرمة."],[14642,"- الفوائد (الغيلانيات): - أبو بكر محمد بن عبد اللَّه الشافعى (ت: ٣٥٤)، تحقيق الدكتور حلمى كامل اسعد عبد الهادى، رسالة دكتوراه بجامعة أم القرى بمكة."],[14643,"- فيض القدير شرح الجامع الصغير: محمد عبد الرؤوف المناوى، دار المعرفة - بيروت، ط ٢ - ١٣٩١ هـ."],[14644,"- القاموس المحيط: مجد الدين محمد بن يعقوب الفيروزآبادى (ت:"],[14645,"٨١٧)، المطبعة الحسينية المصرية - ط ٢ - سنة ١٣٤٤ هـ."],[14646,"- الكامل في أسماء الرجال: الحافظ أبو أحمد بن عدى الجرجانى (ت ٣٦٥)، مصورة بالمكتبة المركزية بجامعة أم القرى."],[14647,"- الكامل في التاريخ: - عز الدين على بن محمد بن الاثير (ت ٦٣٠)، دار صادر بيروت، ١٣٨٦ هـ."],[14648,"- كشف الاستار عن زوائد البزار: - نور الدين على بن أبى بكر الهيثمى (ت ٨٠٧)، تحقيق حبيب الرحمن الاعظمى، مؤسسة الرسالة - بيروت، ط ١، ١٣٩٩ هـ."],[14649,"- كشف الخفا ومزيل الالباس: - إسماعيل بن محمد العجلونى (ت ١١٦٢)، دار إحياء التراث العربى - بيروت. ط ٣ - ١٣٥١ هـ."],[14650,"- كشف الظنون عن أسامى الكتب والفنون: - مصطفى بن عبد اللَّه الشهير بحاجى خليفة (ت: ١٠٦٧)، منشورات مكتبة المثنى - بغداد."],[14651,"- الكفاية في علم الرواية للخطيب البغدادى (ت: ٤٦٣) ط ١."],[14652,"- كنز العمال في سنن الأقوال والأفعال: - علاء الدين على المتقى الهندى - مكتبة التراث - حلب، ط ١ - ١٣٩٠ هـ."],[14653,"- الكنى: أبو أحمد الحاكم محمد بن محمد (ت: ٣٧٨)، مصورة مركز البحث العلمى بجامعة أم القرى."],[14654,"- كنى البخارى: - محمد بن إسماعيل البخارى (ت: ٢٥٦)، المكتبة الاسلامية - تركيا."],[14655,"- الكنى والأسماء: - أبو بشر محمد بن أحمد الدولابى (ت ٣١٠)، دائرة المعارف العثمانية - الهند، ط ١."],[14656,"- الكنى والأسماء: - مسلم بن الحجاج النيسابورى (ت: ٢٦١)، تحقيق الاستاذ عبد الرحيم محمد أحمد القشقرى، رسالة ماجستير في الجامعة الاسلامية بالمدينة المنورة."],[14657,"- الكواكب النيرات في معرفة من اختلط من الرواة الثقات: - محمد بن أحمد بن الكيّال (ت: ٩٣٩)، تحقيق: عبد القيوم عبد رب النبى، دار المأمون للتراث."],[14658,"- اللآلئ المصنوعة في الأحاديث الموضوعة: - جلال الدين عبد الرحمن ابن أبى بكر السيوطى (ت: ٩١١)، دار المعرفة - بيروت، ط ٢، ١٣٩٥ هـ."],[14659,"- اللباب شرح الشهاب: أبو الوفا مصطفى المراغى، المجلس الأعلى للشئون الإسلامية - القاهرة، ١٣٩٠ هـ."],[14660,"- اللباب في تهذيب الانساب: - عز الدين على بن محمد المعروف بابن الاثير (ت: ٦٣٠)، دار صادر - بيروت."],[14661,"- لسان العرب: جمال الدين محمد بن مكرم بن منظور المصرى، دار صادر - بيروت."],[14662,"- لسان الميزان: - أحمد بن على بن حجر العسقلانى (ت: ٨٥٢)، دائرة المعارف العثمانية - الهند، ط ٢، ١٩٧١ - ١٣٩٠."],[14663,"- المجروحون من المحدثين: - أبو حاتم محمد بن حبان البستى (ت: ٣٥٤)، تحقيق: محمود إبراهيم - دار الوعى - حلب."],[14664,"- مجمع الزوائد ومنبع الفوائد: نور الدين على بن أبى بكر الهيثمى (ت: ٨٠٧) دار الكتاب العربى - بيروت، ط ٢ - ١٣٨٧ هـ."],[14665,"- محاسن الاصطلاح: - للحافظ سراج الدين عمر البلقينى (ت: ٨٠٥)، تحقيق: د/ عائشة عبد الرحمن، مطبعة دار الكتب - ١٩٧٤ م."],[14666,"- المحبّر: - أبو جعفر محمد بن حبيب البغدادى (ت: ٢٤٥)، دار الافاق الجديدة - بيروت."],[14667,"- المحلى: على بن أحمد بن حزم (ت ٤٥٦)، دار الاتحاد العربى - القاهرة، ١٣٨٧ هـ."],[14668,"- مرآة الجنان وعبرة اليقظان في معرفة ما يعتبر من حوادث الزمان: عبد اللَّه ابن اسعد اليافعى اليمنى المكى (ت: ٧٦٨)، مؤسسة الاعلمى - بيروت. ط ٢/ سنة ١٣٩٠ هـ."],[14669,"- المراسيل: أبو داود سليمان بن أشعث السجستانى (ت: ٢٧٥)، مكتبة ومطبعة محمد على صبيح وأولاده - مصر."],[14670,"- المراسيل: عبد الرحمن بن أبى حاتم بن ادريس الرازى (ت ٣٢٧)، مؤسسة الرسالة - بيروت، ط ١."],[14671,"- مراصد الاطلاع على أسماء الامكنة والبقاع عبد المؤمن بن عبد الحق البغدادى (ت: ٧٣٩)، تحقيق على محمد البجاوى، دار إحياء الكتب العربية. ط ١، ١٣٧٣ هـ."],[14672,"- مسائل الإمام أحمد بن حنبل: - رواية اسحاق بن إبراهيم النيسابورى (ت: ٢٧٥) تحقيق: زهير الشاويش، المكتب الاسلامى، ١٤٠٠ هـ."],[14673,"- المستدرك على الصحيحين: أبو عبد اللَّه محمد بن عبد اللَّه المعروف بالحاكم (ت ٤٠٥)، دار الفكر - بيروت، ١٣٩٨ هـ."],[14674,"- المسند: عبد اللَّه بن الزبير الحميدى (ت ٢١٩)، عالم الكتب - بيروت، مكتبة المتنبى - القاهرة."],[14675,"- المسند: أحمد بن محمد بن حنبل (ت ٢٤١)، المكتب الاسلامى، دار صادر - بيروت."],[14676,"- المسند: - محمد بن ادريس الشافعى (ت ٢٠٤)، دار الكتب العلمية - بيروت، ط ١، ١٤٠٠ هـ."],[14677,"- مسند أبى عوانة: يعقوب بن اسحق الاسفرائينى (ت ٣١٦)، دار المعرفة بيروت."],[14678,"- المسند: - سليمان بن داود أبو داود الطيالسى (ت: ٢٥٣)، ترتيب أحمد عبد الرحمن البنا، المكتبة الاسلامية - بيروت، ط ٢ - ١٤٠٠ هـ."],[14679,"- مشاهير علماء الأمصار: - محمد بن حبان البستى (ت: ٣٥٤)، تصحيح: م. فلا يشهمر، دار الكتب العلمية."],[14680,"- مشكل الآثار: - أبو جعفر الطحاوى، دار صادر - بيروت."],[14681,"-المصنف: - عبد الرزاق بن همام الصنعانى (ت ٢١١)، تحقيق حبيب الرحمن الاعظمى، المجلس العلمى - ١٣٩٠ هـ."],[14682,"- المصنف: أبو بكر عبد اللَّه بن محمد بن أبى شيبة (ت ٢٣٥)، الدار السلفية - الهند."],[14683,"- المطالب العالية: - أحمد بن على بن حجر العسقلانى (ت ٨٥٢)، تحقيق حبيب الرحمن الاعظمى."],[14684,"- المعارف: - عبد اللَّه بن مسلم بن قتيبة (ت: ٢٧٦)، تحقيق د/ ثروت عكاشة دار المعارف - مصر. ط ٢"],[14685,"- معالم السنن: - حمد بن محمد بن إبراهيم الخطابى (ت ٣٨٨)، مكتبة السنة المحمدية - القاهرة."],[14686,"- معجم البلدان: شهاب الدين أبو عبد اللَّه ياقوت الحموى (ت ٦٢٦)، دار الكتاب العربى - بيروت."],[14687,"- معجم الشعراء: - الإمام أبو عبيد اللَّه محمد بن عمران المرزبانى (ت: ٣٨٤)، نشر/ مكتبة القدسى. ط ٢."],[14688,"- معجم الصحابة: عبد اللَّه بن محمد البغوى (ت: ٣١٧)، مصورة الخزانة العامة بالرباط رقم (٣٤١) منه نسخة ميكروفيلم لدى مركز البحث العلمى بجامعة أم القرى."],[14689,"- المعجم الصغير: - سليمان بن أحمد الطبرانى، دار النصر - القاهرة ١٣٨٨ هـ."],[14690,"- المعجم الكبير: سليمان بن أحمد الطبرانى (ت ٣٦٠)، تحقيق حمدى عبد المجيد السلفى، مطبعة الأمة - بغداد، ١٩٧٨ م."],[14691,"- معجم المؤلفين تراجم مصنفى الكتب العربية: - عمر رضا كحالة، مكتبة المثنى - لبنان."],[14692,"- المعرفة والتاريخ: - يعقوب بن سفيان الفسوى (ت: ٢٧٧)، تحقيق د/ أكرم العمرى، مؤسسة الرسالة، ط ٢."],[14693,"- معرفة علوم الحديث: - محمد بن عبد اللَّه الحاكم، المكتب التجارى - بيروت."],[14694,"- المغازى: - محمد بن عمر بن واقد الواقدى (ت ٢٠٧)، تحقيق د. مارسدن جونس، مؤسسة الاعلمى - بيروت."],[14695,"- المغازى النبوية: - محمد بن مسلم بن شهاب الزهرى (ت: ١٢٤)، تحقيق د/ سهيل زكار، دار الفكر، ط ١، ١٤٠٠ هـ."],[14696,"- المغرب في حلى المغرب: - تأليف: مجموعة من علماء الاندلس."],[14697,"- المغنى: - محمد بن طاهر بن على الهندى (ت: ٩٨٦) دائرة نشر الكتب الاسلامية، ط ١، ١٣٩٣ هـ."],[14698,"- المقاصد الحسنة: - محمد بن عبد الرحمن السخاوى (ت ٩٠٢)، تحقيق عبد اللَّه محمد صديق، دار الكتب العلمية - بيروت."],[14699,"- مقالات الاسلاميين واختلاف المصلين: - أبو الحسن على بن إسماعيل الاشعرى (ت: ٣٣٠)، تحقيق: محيى الدين عبد الحميد، طبع ونشر مكتبة النهضة المصرية - القاهرة."],[14700,"- المقتنى في سرد الكنى: - محمد بن أحمد بن عثمان الذهبى (ت: ٧٤٨)، مصورة مركز البحث العلمى بجامعة أم القرى (ميكروفيلم)."],[14701,"- مقدمة ابن الصلاح في علوم الحديث مع شرحها التقييد والايضاح: أبو عمرو عثمان بن عبد الرحمن بن عثمان المعروف بابن الصلاح (ت ٦٤٣)، المكتبة السلفية - المدينة المنورة، ط ١، ١٣٨٩ هـ."],[14702,"- الملل والنحل: - محمد بن عبد الكريم الشهرستانى (ت: ٥٤٨)، مكتبة ومطبعة محمد على صبيح وأولاده - القاهرة."],[14703,"- المنتقى: عبد اللَّه بن على بن الجارود (ت ٣٠٧)، المكتبة الاثرية - باكستان."],[14704,"- موار الظمآن إلى زوائد ابن حبان: نور الدين الهيثمى (ت ٧٠٨)، دار الكتب العلمية - بيروت."],[14705,"- الموضوعات: - أبو الفرج عبد الرحمن بن على بن الجوزى (ت ٥٩٧)، المكتبة السلفية، ط ١ - ١٣٨٦ هـ."],[14706,"- الموطأ: مالك بن أنس (ت ١٧٩)، دار إحياء الكتب العربية - القاهرة."],[14707,"- ميزان الاعتدال: محمد بن أحمد بن عثمان الذهبى (ت ٧٤٨)، دار المعرفة بيروت، ط ١، ١٣٨٢ هـ."],[14708,"- النجوم الزاهرة في ملوك مصر والقاهرة: - ابن تغرى بردى الاتابكى (ت: ٨٧٤) المؤسسة المصرية العامة للتأليف والترجمة والطباعة والنشر."],[14709,"- نزهة الالبّاء في طبقات الأدباء: - أبو البركات كمال الدين عبد الرحمن ابن محمد الانبارى (ت: ٥٧٧)، تحقيق محمد أبو الفضل إبراهيم، دار نهضة مصر للطباع والنشر- الفجالة - القاهرة."],[14710,"- نسب قريش: - أبو عبد اللَّه المصعب بن عبد اللَّه المصعب الزبيرى (ت: ٢٣٦)، نشر/ ١. ليفى بروفنسال، دار المعارف للطباعة والنشر."],[14711,"- نصب الراية: - عبد اللَّه بن يوسف الزيلعى (ت ٧٦٢)، إدارة المجلس العلمى - الهند."],[14712,"- نظم المتناثر في الحديث المتواتر: - محمد بن جعفر الكتانى، دار المعارف، حلب."],[14713,"- النكت الظراف على الاطراف: - أحمد بن على بن حجر (ت ٨٥٢)، الدار القيمة - الهند."],[14714,"- النهاية في غريب الحديث: مجد الدين المبارك بن محمد بن الاثير (ت ٦٠٦)، المكتبة الاسلامية - بيروت."],[14715,"- نوادر الأصول في معرفة أحاديث الرسول: - أبو عبد اللَّه محمد الحكيم الترمذى المكتبة العلمية بالمدينة المنورة لصاحبها محمد النمنكانى."],[14716,"- نيل الأوطار: - محمد بن على الشوكانى (ت ١٢٥٥)، دار الجيل - لبنان، ١٣٩٣ هـ."],[14717,"- هدى السارى مقدمة فتح البارى: - ابن حجر العسقلانى، المطبعة السلفية."],[14718,"- الوتر: محمد بن نصر المروزى (ت ٢٩٢)، المكتبة الاثرية - باكستان."],[14719,"- وفيات الأعيان وأنباء أبناء الزمان: - أحمد بن محمد بن خلكان (ت: ٦٨١)، تحقيق د. احسان عباس، دار الثقافة - بيروت."]])